Base.@kwdef struct HEURPParams
    A::Float64 = 300.0
    B::Float64 = 1.0
    C::Float64 = 20.0
    alpha::Float64 = 0.1
end

struct Grid3D
    Nx::Int
    L::Float64
    dx::Float64
    volume::Float64
    dimension::Int
end

Grid3D(Nx::Integer, L::Real) = Grid3D(Int(Nx), Float64(L), Float64(L) / Int(Nx), Float64(L)^3, 3)

_proposals_per_sweep(grid::Grid3D) = grid.Nx^grid.dimension

function _steps_from_sweeps(grid::Grid3D, sweeps::Real)
    sweep_count = Float64(sweeps)
    sweep_count > 0.0 || throw(ArgumentError("sweeps must be positive"))
    return max(1, ceil(Int, sweep_count * _proposals_per_sweep(grid)))
end

function _resolve_steps(grid::Grid3D; steps=100, sweeps=nothing)
    sweeps === nothing || return _steps_from_sweeps(grid, sweeps)
    return max(1, Int(steps))
end

_sweeps_from_steps(grid::Grid3D, steps::Real) = Float64(steps) / _proposals_per_sweep(grid)

