Base.@kwdef struct ScalarCellStressRootResult
    bracket_found::Bool
    converged::Bool
    reason::String
    selected::Any
    selected_period::Float64
    selected_stress::Float64
    lower_period::Float64
    upper_period::Float64
    best::Any
    best_period::Float64
    best_stress::Float64
    evaluations::Vector{Any}
    iterations::Int
end

function _scalar_cell_default_stress(item)
    item === nothing && return NaN
    names = propertynames(item)
    if :cell_gradient_density in names
        return getproperty(item, :cell_gradient_density)
    elseif :stress in names
        return getproperty(item, :stress)
    end
    return NaN
end

function _scalar_cell_stress_value(item, stress_getter, valid)
    item === nothing && return NaN
    valid(item) || return NaN
    stress = try
        Float64(stress_getter(item))
    catch
        NaN
    end
    return isfinite(stress) ? stress : NaN
end

function _scalar_cell_result(; bracket_found::Bool, converged::Bool,
        reason::AbstractString, selected, selected_period::Real,
        selected_stress::Real, lower_period::Real, upper_period::Real, best,
        best_period::Real, best_stress::Real, evaluations, iterations::Integer)
    return ScalarCellStressRootResult(; bracket_found=bracket_found,
        converged=converged, reason=String(reason), selected=selected,
        selected_period=Float64(selected_period),
        selected_stress=Float64(selected_stress),
        lower_period=Float64(lower_period), upper_period=Float64(upper_period),
        best=best, best_period=Float64(best_period),
        best_stress=Float64(best_stress), evaluations=Any[evaluations...],
        iterations=Int(iterations))
end

"""
    optimize_scalar_cell_with_stress(evaluate_period, center, lower, upper; ...)

Find a stress-free scalar cell period by rooting the relaxed cell-stress
condition rather than minimizing energy alone. `evaluate_period(period)` must
return an object accepted by `stress_getter`; invalid fixed-cell solves should
produce a non-finite stress or be rejected by `valid`.

The method first checks whether any valid endpoints of the absolute search
window already bracket the stress root. If not, it follows the sign of the
stress from `center` to find a valid sign-changing bracket, then applies a
safeguarded secant step with bisection fallback. The returned
`ScalarCellStressRootResult` separates bracket failure from final stress
convergence so production callers can keep rejected rows as diagnostics
without pretending the cell minimum was located.
"""
function optimize_scalar_cell_with_stress(evaluate_period, center_period::Real,
        lower_period::Real, upper_period::Real;
        stress_getter=_scalar_cell_default_stress,
        valid=item -> true,
        stress_tolerance::Real=1.0e-4,
        step_fraction::Real=0.005,
        step_growth::Real=1.0,
        max_bracket_steps::Integer=12,
        root_iterations::Integer=8)
    center = Float64(center_period)
    lower = Float64(lower_period)
    upper = Float64(upper_period)
    lower < center < upper ||
        throw(ArgumentError("cell stress search requires lower < center < upper"))
    tol = Float64(stress_tolerance)
    tol > 0.0 || throw(ArgumentError("stress_tolerance must be positive"))
    step = max(1.0e-4, abs(center) * Float64(step_fraction))
    step > 0.0 || throw(ArgumentError("step_fraction must define a positive step"))
    growth = Float64(step_growth)
    isfinite(growth) && growth >= 1.0 ||
        throw(ArgumentError("step_growth must be finite and at least 1"))

    evaluations = Any[]
    best = nothing
    best_period = NaN
    best_stress = NaN
    best_abs_stress = Inf

    function tracked_eval(period::Real)
        p = Float64(period)
        item = evaluate_period(p)
        push!(evaluations, item)
        stress = _scalar_cell_stress_value(item, stress_getter, valid)
        if isfinite(stress) && abs(stress) < best_abs_stress
            best = item
            best_period = p
            best_stress = stress
            best_abs_stress = abs(stress)
        end
        return item, stress
    end

    center_item, center_stress = tracked_eval(center)
    if !isfinite(center_stress)
        return _scalar_cell_result(; bracket_found=false, converged=false,
            reason="center_not_valid", selected=best, selected_period=best_period,
            selected_stress=best_stress, lower_period=NaN, upper_period=NaN,
            best=best, best_period=best_period, best_stress=best_stress,
            evaluations=evaluations, iterations=0)
    end
    if abs(center_stress) <= tol
        return _scalar_cell_result(; bracket_found=true, converged=true,
            reason="center_stress_converged", selected=center_item,
            selected_period=center, selected_stress=center_stress,
            lower_period=center, upper_period=center, best=center_item,
            best_period=center, best_stress=center_stress,
            evaluations=evaluations, iterations=0)
    end

    lo = NaN
    hi = NaN
    bracket_reason = "stress_endpoint_bracket"
    bracket_found = false

    function consider_bracket(a::Float64, sa::Float64, b::Float64,
            sb::Float64)
        if isfinite(sa) && isfinite(sb) && sa * sb < 0.0
            candidate_lo = min(a, b)
            candidate_hi = max(a, b)
            if !bracket_found || candidate_hi - candidate_lo < hi - lo
                lo = candidate_lo
                hi = candidate_hi
                bracket_found = true
            end
        end
        return nothing
    end

    direction = center_stress > 0.0 ? -1.0 : 1.0
    previous_period = center
    previous_stress = center_stress
    if !bracket_found
        bracket_reason = "stress_bracket_step_cap"
    end
    for _ in 1:Int(max_bracket_steps)
        bracket_found && break
        trial_period = previous_period + direction * step
        if !(lower < trial_period < upper)
            bracket_reason = "stress_hit_window_edge"
            break
        end
        _, trial_stress = tracked_eval(trial_period)
        if !isfinite(trial_stress)
            bracket_reason = "stress_hit_invalid_cell"
            break
        end
        if abs(trial_stress) <= tol
            return _scalar_cell_result(; bracket_found=true, converged=true,
                reason="trial_stress_converged", selected=best,
                selected_period=best_period, selected_stress=best_stress,
                lower_period=trial_period, upper_period=trial_period, best=best,
                best_period=best_period, best_stress=best_stress,
                evaluations=evaluations, iterations=0)
        end
        if previous_stress * trial_stress < 0.0
            lo = min(previous_period, trial_period)
            hi = max(previous_period, trial_period)
            bracket_reason = "stress_sign_change"
            bracket_found = true
            break
        end
        previous_period = trial_period
        previous_stress = trial_stress
        step *= growth
    end

    if !bracket_found
        lower_item, lower_stress = tracked_eval(lower)
        if isfinite(lower_stress) && abs(lower_stress) <= tol
            return _scalar_cell_result(; bracket_found=true, converged=true,
                reason="lower_stress_converged", selected=lower_item,
                selected_period=lower, selected_stress=lower_stress,
                lower_period=lower, upper_period=lower, best=lower_item,
                best_period=lower, best_stress=lower_stress,
                evaluations=evaluations, iterations=0)
        end

        upper_item, upper_stress = tracked_eval(upper)
        if isfinite(upper_stress) && abs(upper_stress) <= tol
            return _scalar_cell_result(; bracket_found=true, converged=true,
                reason="upper_stress_converged", selected=upper_item,
                selected_period=upper, selected_stress=upper_stress,
                lower_period=upper, upper_period=upper, best=upper_item,
                best_period=upper, best_stress=upper_stress,
                evaluations=evaluations, iterations=0)
        end

        consider_bracket(lower, lower_stress, center, center_stress)
        consider_bracket(center, center_stress, upper, upper_stress)
        consider_bracket(lower, lower_stress, upper, upper_stress)
        bracket_found && (bracket_reason = "stress_endpoint_bracket")
    end

    if !bracket_found
        return _scalar_cell_result(; bracket_found=false, converged=false,
            reason=bracket_reason, selected=best, selected_period=best_period,
            selected_stress=best_stress, lower_period=NaN, upper_period=NaN,
            best=best, best_period=best_period, best_stress=best_stress,
            evaluations=evaluations, iterations=0)
    end

    lo_item, lo_stress = tracked_eval(lo)
    hi_item, hi_stress = tracked_eval(hi)
    if !(isfinite(lo_stress) && isfinite(hi_stress) &&
            lo_stress * hi_stress <= 0.0)
        return _scalar_cell_result(; bracket_found=false, converged=false,
            reason="stress_bracket_not_reproducible", selected=best,
            selected_period=best_period, selected_stress=best_stress,
            lower_period=lo, upper_period=hi, best=best,
            best_period=best_period, best_stress=best_stress,
            evaluations=evaluations, iterations=0)
    end

    selected = abs(lo_stress) <= abs(hi_stress) ? lo_item : hi_item
    selected_period = abs(lo_stress) <= abs(hi_stress) ? lo : hi
    selected_stress = abs(lo_stress) <= abs(hi_stress) ? lo_stress : hi_stress
    for iteration in 1:Int(root_iterations)
        period = hi_stress == lo_stress ? 0.5 * (lo + hi) :
            (lo * hi_stress - hi * lo_stress) / (hi_stress - lo_stress)
        if !(lo < period < hi)
            period = 0.5 * (lo + hi)
        end
        item, stress = tracked_eval(period)
        if isfinite(stress) && abs(stress) < abs(selected_stress)
            selected = item
            selected_period = period
            selected_stress = stress
        end
        if !isfinite(stress)
            return _scalar_cell_result(; bracket_found=true,
                converged=false, reason="stress_root_hit_invalid_cell",
                selected=selected, selected_period=selected_period,
                selected_stress=selected_stress, lower_period=lo,
                upper_period=hi, best=best, best_period=best_period,
                best_stress=best_stress, evaluations=evaluations,
                iterations=iteration)
        end
        if abs(stress) <= tol
            return _scalar_cell_result(; bracket_found=true, converged=true,
                reason="stress_tolerance", selected=item,
                selected_period=period, selected_stress=stress,
                lower_period=lo, upper_period=hi, best=best,
                best_period=best_period, best_stress=best_stress,
                evaluations=evaluations, iterations=iteration)
        end
        if lo_stress * stress <= 0.0
            hi = period
            hi_stress = stress
        else
            lo = period
            lo_stress = stress
        end
    end

    return _scalar_cell_result(; bracket_found=true, converged=false,
        reason="stress_root_iteration_cap", selected=selected,
        selected_period=selected_period, selected_stress=selected_stress,
        lower_period=lo, upper_period=hi, best=best, best_period=best_period,
        best_stress=best_stress, evaluations=evaluations,
        iterations=Int(root_iterations))
end

