end

function _phase_boundary_bool(value)
    value isa Bool && return value
    value === missing && return false
    return lowercase(strip(string(value))) in ("true", "1", "yes", "y")
end

function _phase_boundary_string(row, name::Symbol, default="")
    name in propertynames(row) || return String(default)
    value = getproperty(row, name)
    value === missing && return String(default)
    return String(value)
end

function _phase_boundary_float(row, name::Symbol; default=NaN)
    name in propertynames(row) || return Float64(default)
    value = getproperty(row, name)
    value === missing && return Float64(default)
    return Float64(value)
end

function load_phase_rank_branch_points(path::AbstractString; model=nothing,
        accepted_only::Bool=false)
    isfile(path) || throw(ArgumentError("missing phase-rank branch CSV: $(path)"))
    table = CSV.read(path, DataFrames.DataFrame)
    required = (:target_id, :fA, :chiN, :model, :target_morphology,
        :candidate_morphology, :accepted_for_phase_rank,
        :energy_density_proxy)
    missing_columns = [name for name in required if !(name in propertynames(table))]
    isempty(missing_columns) || throw(ArgumentError(
        "phase-rank branch CSV $(path) is missing columns $(missing_columns)"))
    rows = PhaseBranchPoint[]
    for row in DataFrames.eachrow(table)
        model_filter = model === nothing || string(row.model) == string(model)
        model_filter || continue
        accepted = _phase_boundary_bool(row.accepted_for_phase_rank)
        (!accepted_only || accepted) || continue
        push!(rows, PhaseBranchPoint(
            String(row.target_id),
            String(row.model),
            String(row.candidate_morphology),
            String(row.target_morphology),
            Float64(row.fA),
            Float64(row.chiN),
            Float64(row.energy_density_proxy),
            accepted,
            _phase_boundary_string(row, :source_file, path),
            _phase_boundary_string(row, :accepted_reason, ""),
        ))
    end
    return rows
end

function _matching_phase_branch(points, morphology::AbstractString; model=nothing,
        fA=nothing, chiN=nothing, require_accepted::Bool=true)
    matches = PhaseBranchPoint[]
    for point in points
        point.morphology == String(morphology) || continue
        (model === nothing || point.model == String(model)) || continue
        (fA === nothing || isapprox(point.fA, Float64(fA);
            atol=1.0e-10, rtol=0.0)) || continue
        (chiN === nothing || isapprox(point.chiN, Float64(chiN);
            atol=1.0e-10, rtol=0.0)) || continue
        (!require_accepted || point.accepted) || continue
        push!(matches, point)
    end
    length(matches) == 1 || throw(ArgumentError(
        "expected one accepted branch point for morphology=$(morphology), " *
        "model=$(model), fA=$(fA), chiN=$(chiN); found $(length(matches))"))
    return first(matches)
end

function branch_free_energy_difference(points, phase_a::AbstractString,
        phase_b::AbstractString; model=nothing, fA=nothing, chiN=nothing,
        require_accepted::Bool=true)
    branch_a = _matching_phase_branch(points, phase_a; model=model, fA=fA,
        chiN=chiN, require_accepted=require_accepted)
    branch_b = _matching_phase_branch(points, phase_b; model=model, fA=fA,
        chiN=chiN, require_accepted=require_accepted)
    return branch_a.free_energy_density - branch_b.free_energy_density
end

function _phase_boundary_axis_name(axis)
    normalized = lowercase(strip(string(axis)))
    normalized in ("fa", "f_a", "f") && return "fA"
    normalized in ("chin", "chi_n", "chi*n", "chi n", "χn") &&
        return "chiN"
    throw(ArgumentError("unsupported phase-boundary coordinate $(axis); use fA or chiN"))
end

function _phase_boundary_axis_value(point::PhaseBranchPoint, axis)
    name = _phase_boundary_axis_name(axis)
    name == "fA" && return point.fA
    name == "chiN" && return point.chiN
    error("unreachable phase-boundary axis $(axis)")
end

function _phase_boundary_default_fixed_coordinate(variable)
    var = _phase_boundary_axis_name(variable)
    return var == "fA" ? "chiN" : "fA"
end

function _phase_boundary_same_coordinate(a::Real, b::Real)
    return isapprox(Float64(a), Float64(b); atol=1.0e-10, rtol=0.0)
end

function _phase_boundary_sources(branch_a::PhaseBranchPoint,
        branch_b::PhaseBranchPoint)
    branch_a.source_file == branch_b.source_file &&
        return branch_a.source_file
    return branch_a.source_file * ";" * branch_b.source_file
end

function _phase_boundary_keep_branch(existing::PhaseBranchPoint,
        candidate::PhaseBranchPoint)
    isfinite(candidate.free_energy_density) || return existing
    isfinite(existing.free_energy_density) || return candidate
    candidate.free_energy_density < existing.free_energy_density ?
        candidate : existing
end

function _phase_boundary_bracket_root(low, high; model::AbstractString,
        phase_a::AbstractString, phase_b::AbstractString,
        variable::AbstractString, fixed_coordinate::AbstractString,
        fixed_value::Real)
    interpolation = linear_phase_boundary_estimate(low.coordinate, low.delta,
        high.coordinate, high.delta; model=model, phase_a=phase_a,
        phase_b=phase_b, variable=variable, fixed_coordinate=fixed_coordinate,
        fixed_value=fixed_value)
    if _phase_boundary_axis_name(variable) != "chiN"
        return interpolation
    end

    # chiN boundary searches are expensive branch solves.  A linear DeltaF
    # interpolation is useful as a diagnostic readout, but the returned bracket
    # root must stay on an actually computed bisection endpoint.
    return PhaseBoundaryRootResult(model=String(model),
        phase_a=String(phase_a), phase_b=String(phase_b),
        variable=String(variable), coordinate=Float64(low.coordinate),
        residual=Float64(low.delta),
        bracket_low=min(Float64(low.coordinate), Float64(high.coordinate)),
        bracket_high=max(Float64(low.coordinate), Float64(high.coordinate)),
        delta_low=Float64(low.delta), delta_high=Float64(high.delta),
        fixed_coordinate=String(fixed_coordinate),
        fixed_value=Float64(fixed_value), iterations=0, converged=true,
        method="computed_bisection_endpoint")
end

function find_phase_boundary_brackets(points::AbstractVector{<:PhaseBranchPoint},
        phase_a::AbstractString, phase_b::AbstractString; model=nothing,
        variable::AbstractString="chiN",
        fixed_coordinate=nothing, fixed_value=nothing,
        require_accepted::Bool=true)
    var = _phase_boundary_axis_name(variable)
    fixed = fixed_coordinate === nothing ?
        _phase_boundary_default_fixed_coordinate(var) :
        _phase_boundary_axis_name(fixed_coordinate)
    var == fixed && throw(ArgumentError(
        "phase-boundary variable and fixed coordinate must be different"))

    grouped = Dict{Tuple{String, Float64, Float64},
        Dict{String, PhaseBranchPoint}}()
    for point in points
        (!require_accepted || point.accepted) || continue
        (model === nothing || point.model == String(model)) || continue
        coordinate = _phase_boundary_axis_value(point, var)
        fixed_coord = _phase_boundary_axis_value(point, fixed)
        isfinite(coordinate) && isfinite(fixed_coord) &&
            isfinite(point.free_energy_density) || continue
        if fixed_value !== nothing &&
                !_phase_boundary_same_coordinate(fixed_coord, Float64(fixed_value))
            continue
        end
        key = (point.model, fixed_coord, coordinate)
        morphology_map = get!(grouped, key, Dict{String, PhaseBranchPoint}())
        if haskey(morphology_map, point.morphology)
            morphology_map[point.morphology] = _phase_boundary_keep_branch(
                morphology_map[point.morphology], point)
        else
            morphology_map[point.morphology] = point
        end
    end

    samples = NamedTuple[]
    for ((sample_model, sample_fixed, sample_coordinate), morphology_map) in grouped
        haskey(morphology_map, String(phase_a)) || continue
        haskey(morphology_map, String(phase_b)) || continue
        branch_a = morphology_map[String(phase_a)]
        branch_b = morphology_map[String(phase_b)]
        delta = branch_a.free_energy_density - branch_b.free_energy_density
        isfinite(delta) || continue
        push!(samples, (
            model=sample_model,
            fixed_value=sample_fixed,
            coordinate=sample_coordinate,
            delta=delta,
            branch_a=branch_a,
            branch_b=branch_b,
        ))
    end

    by_branch = Dict{Tuple{String, Float64}, Vector{NamedTuple}}()
    for sample in samples
        push!(get!(by_branch, (sample.model, sample.fixed_value),
            NamedTuple[]), sample)
    end

    brackets = PhaseBoundaryBracket[]
    for ((sample_model, sample_fixed), branch_samples) in by_branch
        sort!(branch_samples, by=sample -> sample.coordinate)
        for idx in 1:(length(branch_samples) - 1)
            low = branch_samples[idx]
            high = branch_samples[idx + 1]
            _phase_boundary_same_coordinate(low.coordinate, high.coordinate) &&
                continue
            low.delta == high.delta && continue
            low.delta * high.delta <= 0.0 || continue
            root = _phase_boundary_bracket_root(low, high;
                model=sample_model, phase_a=String(phase_a),
                phase_b=String(phase_b), variable=var,
                fixed_coordinate=fixed, fixed_value=sample_fixed)
            push!(brackets, PhaseBoundaryBracket(
                sample_model,
                String(phase_a),
                String(phase_b),
                var,
                fixed,
                sample_fixed,
                low.coordinate,
                high.coordinate,
                low.delta,
                high.delta,
                _phase_boundary_sources(low.branch_a, low.branch_b),
                _phase_boundary_sources(high.branch_a, high.branch_b),
                root,
            ))
        end
    end
    sort!(brackets, by=bracket -> (bracket.model, bracket.fixed_value,
        bracket.low_coordinate, bracket.high_coordinate))
    return brackets
end

function find_phase_boundary_root(deltaF, x_low::Real, x_high::Real;
        tolerance::Real=1.0e-8, max_iterations::Integer=100,
        model::AbstractString="", phase_a::AbstractString="",
        phase_b::AbstractString="", variable::AbstractString="coordinate",
        fixed_coordinate::AbstractString="", fixed_value::Real=NaN)
    lo = Float64(x_low)
    hi = Float64(x_high)
    isfinite(lo) && isfinite(hi) && lo != hi ||
        throw(ArgumentError("root bracket endpoints must be finite and distinct"))
    lo > hi && ((lo, hi) = (hi, lo))
    flo = Float64(deltaF(lo))
    fhi = Float64(deltaF(hi))
    isfinite(flo) && isfinite(fhi) ||
        throw(ArgumentError("DeltaF values at the root bracket must be finite"))
    flo == 0.0 && return PhaseBoundaryRootResult(model=String(model),
        phase_a=String(phase_a), phase_b=String(phase_b),
        variable=String(variable), coordinate=lo, residual=0.0,
        bracket_low=lo, bracket_high=hi, delta_low=flo, delta_high=fhi,
        fixed_coordinate=String(fixed_coordinate),
        fixed_value=Float64(fixed_value), iterations=0, converged=true,
        method="bisection")
    fhi == 0.0 && return PhaseBoundaryRootResult(model=String(model),
        phase_a=String(phase_a), phase_b=String(phase_b),
        variable=String(variable), coordinate=hi, residual=0.0,
        bracket_low=lo, bracket_high=hi, delta_low=flo, delta_high=fhi,
        fixed_coordinate=String(fixed_coordinate),
        fixed_value=Float64(fixed_value), iterations=0, converged=true,
        method="bisection")
    flo * fhi < 0.0 || throw(ArgumentError(
        "DeltaF bracket must change sign; got $(flo) and $(fhi)"))

    mid = (lo + hi) / 2.0
    fmid = Float64(deltaF(mid))
    converged = false
    iterations = 0
    for iter in 1:Int(max_iterations)
        iterations = iter
        mid = (lo + hi) / 2.0
        fmid = Float64(deltaF(mid))
        isfinite(fmid) || throw(ArgumentError(
            "DeltaF returned non-finite value at $(mid)"))
        if abs(fmid) <= Float64(tolerance) ||
                abs(hi - lo) <= Float64(tolerance)
            converged = true
            break
        end
        if flo * fmid <= 0.0
            hi = mid
            fhi = fmid
        else
            lo = mid
            flo = fmid
        end
    end
    return PhaseBoundaryRootResult(model=String(model),
        phase_a=String(phase_a), phase_b=String(phase_b),
        variable=String(variable), coordinate=mid, residual=fmid,
        bracket_low=lo, bracket_high=hi, delta_low=flo, delta_high=fhi,
        fixed_coordinate=String(fixed_coordinate),
        fixed_value=Float64(fixed_value), iterations=iterations,
        converged=converged, method="bisection")
end

function linear_phase_boundary_estimate(x_low::Real, delta_low::Real,
        x_high::Real, delta_high::Real; model::AbstractString="",
        phase_a::AbstractString="", phase_b::AbstractString="",
        variable::AbstractString="coordinate",
        fixed_coordinate::AbstractString="", fixed_value::Real=NaN)
    lo = Float64(x_low)
    hi = Float64(x_high)
    dlo = Float64(delta_low)
    dhi = Float64(delta_high)
    isfinite(lo) && isfinite(hi) && lo != hi ||
        throw(ArgumentError("linear boundary endpoints must be finite and distinct"))
    isfinite(dlo) && isfinite(dhi) ||
        throw(ArgumentError("linear boundary DeltaF values must be finite"))
    dlo * dhi <= 0.0 || throw(ArgumentError(
        "linear boundary estimate requires a sign-changing DeltaF bracket"))
    dhi != dlo || throw(ArgumentError(
        "linear boundary estimate requires distinct DeltaF endpoint values"))
    coordinate = lo - dlo * (hi - lo) / (dhi - dlo)
    bracket_low, bracket_high = lo < hi ? (lo, hi) : (hi, lo)
    return PhaseBoundaryRootResult(model=String(model),
        phase_a=String(phase_a), phase_b=String(phase_b),
        variable=String(variable), coordinate=coordinate, residual=0.0,
        bracket_low=bracket_low, bracket_high=bracket_high,
        delta_low=dlo, delta_high=dhi,
        fixed_coordinate=String(fixed_coordinate),
        fixed_value=Float64(fixed_value), iterations=1, converged=true,
        method="linear_interpolation")
end

struct SlitGrid1D
    Nz::Int
    L::Float64
    dz::Float64
    z::Vector{Float64}
    weights::Vector{Float64}
end

function SlitGrid1D(Nz::Integer, L::Real)
    n = Int(Nz)
    n >= 4 || throw(ArgumentError("SlitGrid1D requires Nz >= 4"))
    length = Float64(L)
    length > 0.0 || throw(ArgumentError("slit width L must be positive"))
    dz = length / n
    z = [(i - 0.5) * dz for i in 1:n]
    weights = fill(dz, n)
    return SlitGrid1D(n, length, dz, z, weights)
end

struct SlitGrid3D
    Nx::Int
    Ny::Int
    Nz::Int
    Lxy::Float64
    Lz::Float64
    dx::Float64
    dy::Float64
    dz::Float64
    volume::Float64
    cell_volume::Float64
    z::Vector{Float64}
    slit_grid::SlitGrid1D
end

function SlitGrid3D(Nx::Integer, Nz::Integer, Lz::Real; Ny::Integer=Nx, Lxy::Real=1.0)
    nx = Int(Nx)
    ny = Int(Ny)
    nz = Int(Nz)
    nx >= 2 || throw(ArgumentError("SlitGrid3D requires Nx >= 2"))
    ny >= 2 || throw(ArgumentError("SlitGrid3D requires Ny >= 2"))
    nz >= 4 || throw(ArgumentError("SlitGrid3D requires Nz >= 4"))
    lateral = Float64(Lxy)
    width = Float64(Lz)
    lateral > 0.0 || throw(ArgumentError("lateral slit size Lxy must be positive"))
    width > 0.0 || throw(ArgumentError("slit width Lz must be positive"))
    slit_grid = SlitGrid1D(nz, width)
    dx = lateral / nx
    dy = lateral / ny
    dz = width / nz
    volume = lateral^2 * width
    cell_volume = dx * dy * dz
    return SlitGrid3D(nx, ny, nz, lateral, width, dx, dy, dz, volume, cell_volume,
        copy(slit_grid.z), slit_grid)
end

_proposals_per_sweep(grid::SlitGrid3D) = grid.Nx * grid.Ny * grid.Nz

function _steps_from_sweeps(grid::SlitGrid3D, sweeps::Real)
    sweep_count = Float64(sweeps)
    sweep_count > 0.0 || throw(ArgumentError("sweeps must be positive"))
    return max(1, ceil(Int, sweep_count * _proposals_per_sweep(grid)))
end

_sweeps_from_steps(grid::SlitGrid3D, steps::Real) =
    Float64(steps) / _proposals_per_sweep(grid)

Base.@kwdef struct SlitParams
    B::Float64 = 1.0
    C::Float64 = 1.0
    A::Float64 = 0.0
    alpha::Float64 = 0.0
    model::Symbol = :urp_ti
    local_potential_coeffs::NTuple{3,Float64} = (0.0, 0.0, 0.0)
    projected_local_potential_coeffs::NTuple{3,Float64} = (0.0, 0.0, 0.0)
    projected_local_potential_reference::Union{Nothing,Vector{Float64}} = nothing
    lateral_gradient_coeff::Float64 = 0.0
    lateral_variance_coeff::Float64 = 0.0
    lateral_fraction_z_gradient_coeff::Float64 = 0.0
    profile_entropy_coeff::Float64 = 0.0
    projected_entropy_coeff::Float64 = 0.0
    projected_entropy_reference::Union{Nothing,Vector{Float64}} = nothing
    projected_quadratic_coeff::Float64 = 0.0
    projected_quadratic_reference::Union{Nothing,Vector{Float64}} = nothing
    projected_quadratic_weight::Union{Nothing,Vector{Float64}} = nothing
    projected_quadratic_coeffs::Vector{Float64} = Float64[]
    projected_quadratic_references::Vector{Vector{Float64}} = Vector{Float64}[]
    projected_quadratic_weights::Vector{Vector{Float64}} = Vector{Float64}[]
    projected_profile_kernel_matrix::Matrix{Float64} = zeros(Float64, 0, 0)
    projected_profile_kernel_reference::Union{Nothing,Vector{Float64}} = nothing
end

