function debye(x::Real; zero=1.0e-20)
    y = Float64(x)
    abs(y) < zero && return 1.0
    return 2.0 * (exp(-y) + y - 1.0) / y^2
end

function block_urp_eta(phi::Real, phi0::Real)
    density = Float64(phi)
    reference = Float64(phi0)
    density > 0.0 || throw(DomainError(density, "BURP density must be positive"))
    reference > 0.0 || throw(DomainError(reference, "BURP reference density must be positive"))
    return reference * log(density / reference)
end

function _diblock_validate(f::Real, N::Real, b::Real, k2::Real)
    ff = Float64(f)
    nn = Float64(N)
    bb = Float64(b)
    kk = float(k2)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    nn > 0.0 || throw(ArgumentError("degree of polymerization N must be positive"))
    bb > 0.0 || throw(ArgumentError("bond length b must be positive"))
    kk >= 0.0 || throw(ArgumentError("k2 must be nonnegative"))
    return ff, nn, bb, kk
end

function _same_block_h(xi::Real)
    abs(xi) < 1.0e-7 && return 1.0 - xi / 3.0 + xi^2 / 12.0 - xi^3 / 60.0
    return 2.0 * (exp(-xi) - 1.0 + xi) / xi^2
end

function _cross_block_h(xi_a::Real, xi_b::Real)
    if abs(xi_a) < 1.0e-7 && abs(xi_b) < 1.0e-7
        return 1.0 - 0.5 * (xi_a + xi_b)
    end
    left = abs(xi_a) < 1.0e-7 ? -1.0 + xi_a / 2.0 - xi_a^2 / 6.0 : expm1(-xi_a) / xi_a
    right = abs(xi_b) < 1.0e-7 ? -1.0 + xi_b / 2.0 - xi_b^2 / 6.0 : expm1(-xi_b) / xi_b
    return left * right
end

function diblock_single_chain_h(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, kk = _diblock_validate(f, N, b, k2)
    fa = ff
    fb = 1.0 - ff
    scale = nn * bb^2 * kk / 6.0
    xi_a = fa * scale
    xi_b = fb * scale
    h_aa = nn * fa^2 * _same_block_h(xi_a)
    h_bb = nn * fb^2 * _same_block_h(xi_b)
    h_ab = nn * fa * fb * _cross_block_h(xi_a, xi_b)
    return [h_aa h_ab; h_ab h_bb]
end

function diblock_ideal_vertex(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    h = diblock_single_chain_h(k2; f=f, N=N, b=b)
    return inv(h)
end

function diblock_composition_kernel(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, kk = _diblock_validate(f, N, b, k2)
    kk == 0.0 && return Inf
    gamma = diblock_ideal_vertex(kk; f=ff, N=nn, b=bb)
    # Equivalent to dot(v, gamma * v) for v = [1.0, -1.0], written without the
    # per-call allocations of `v` and `gamma * v`.  `gamma` is the raw
    # per-segment ideal vertex; multiplying by N gives the per-chain kernel
    # paired consistently with the `chiN` contact interaction.
    return nn * (gamma[1, 1] - gamma[1, 2] - gamma[2, 1] + gamma[2, 2])
end

function diblock_composition_kernel_derivative(k2::Real; f::Real=0.5,
        N::Real=1.0, b::Real=1.0)
    kk = Float64(k2)
    kk > 0.0 || throw(ArgumentError("k2 must be positive for kernel derivative"))
    return ForwardDiff.derivative(x ->
        diblock_composition_kernel(x; f=f, N=N, b=b), kk)
end

function diblock_burp_eta_psi(phi_a::Real, f::Real=0.5)
    ff = Float64(f)
    density_a = Float64(phi_a)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    isfinite(density_a) || throw(DomainError(density_a, "phi_A must be finite"))
    # Floor the density a hair inside the box: pure/saturated domains (phi at
    # or slightly past 0/1 at strong segregation) then yield a finite eta
    # rather than throwing.  Unchanged for phi safely inside (0, 1).
    density_a = clamp(density_a, 1.0e-10, 1.0 - 1.0e-10)
    density_b = 1.0 - density_a
    eta_a = block_urp_eta(density_a, ff)
    eta_b = block_urp_eta(density_b, 1.0 - ff)
    return 0.5 * (eta_a - eta_b)
end

# ---------------------------------------------------------------------------
# ABA triblock architecture (Case A: same A/B chemistry, linear A-B-A topology)
#
# The propagator-free BURP-TI / BVK1 functionals depend on chain architecture
# ONLY through the ideal single-chain correlation matrix H(k). For a 2-chemistry
# A/B melt the composition kernel is Γ_ψ = vᵀ H⁻¹ v with v = [1, -1], exactly as
# for the diblock; only H changes. Everything downstream (η, the χ term, the
# Newton–GMRES field solver, the cell-size gradient) is reused verbatim. See
# docs/burp_ti_bvk1_arbitrary_architecture.md (§2–3) for the full derivation.
#
# General linear A-B-A triblock, blocks 1(A)-2(B)-3(A), contour fractions
# fa1 + fb + fa2 = 1. With x_i = f_i · N b² k² / 6 and the SAME primitives the
# diblock uses (g_D = `_same_block_h`; e₁(x_a)·e₁(x_b) = `_cross_block_h`):
#   H_11 = N fa1² g_D(x1)   H_33 = N fa2² g_D(x3)   H_22 = N fb² g_D(x2)
#   H_13 = N fa1 fa2 e₁(x1) e₁(x3) e^{-x2}   (outer-outer, middle B intervenes)
#   H_12 = N fa1 fb  e₁(x1) e₁(x2)           (adjacent)   H_23 = N fb fa2 e₁(x2) e₁(x3)
# Grouping the chemical species A = {1,3}, B = {2}:
#   H_AA = H_11 + H_33 + 2 H_13,   H_BB = H_22,   H_AB = H_12 + H_23.
# Setting fa2 = 0 collapses this to the diblock A-B matrix (exact regression
# test); fa1 = fa2 = f/2 is the symmetric ABA triblock exposed by the public API.
# ---------------------------------------------------------------------------
function _triblock_aba_single_chain_h(k2::Real, fa1::Real, fb::Real, fa2::Real,
        N::Real, b::Real)
    # k2 stays untyped so ForwardDiff Duals propagate through x_i; fractions,
    # N and b are plain scalars supplied by the caller.
    scale = N * b^2 * k2 / 6.0
    x1 = fa1 * scale
    x2 = fb * scale
    x3 = fa2 * scale
    h11 = N * fa1^2 * _same_block_h(x1)
    h33 = N * fa2^2 * _same_block_h(x3)
    h22 = N * fb^2 * _same_block_h(x2)
    h13 = N * fa1 * fa2 * _cross_block_h(x1, x3) * exp(-x2)
    h12 = N * fa1 * fb * _cross_block_h(x1, x2)
    h23 = N * fb * fa2 * _cross_block_h(x2, x3)
    h_aa = h11 + h33 + 2.0 * h13
    h_bb = h22
    h_ab = h12 + h23
    return [h_aa h_ab; h_ab h_bb]
end

"""
    triblock_aba_single_chain_h(k2; f=0.5, N=1.0, b=1.0)

Ideal single-chain correlation matrix `H(k)` of a **symmetric linear ABA
triblock** whose total A fraction is `f` (each outer A block carries `f/2`, the
middle B block carries `1-f`). Drop-in analogue of [`diblock_single_chain_h`].
"""
function triblock_aba_single_chain_h(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff = Float64(f)
    nn = Float64(N)
    bb = Float64(b)
    0.0 < ff < 1.0 || throw(ArgumentError("ABA A fraction f must be in (0, 1)"))
    nn > 0.0 || throw(ArgumentError("degree of polymerization N must be positive"))
    bb > 0.0 || throw(ArgumentError("bond length b must be positive"))
    return _triblock_aba_single_chain_h(k2, ff / 2.0, 1.0 - ff, ff / 2.0, nn, bb)
end

"""
    triblock_aba_ideal_vertex(k2; f=0.5, N=1.0, b=1.0)

Inverse single-chain correlation `H(k)⁻¹` for the symmetric ABA triblock.
Analogue of [`diblock_ideal_vertex`]; singular as `k2 → 0`.
"""
function triblock_aba_ideal_vertex(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    return inv(triblock_aba_single_chain_h(k2; f=f, N=N, b=b))
end

"""
    triblock_aba_composition_kernel(k2; f=0.5, N=1.0, b=1.0)

Per-chain BURP-TI composition kernel
`Γ̄_ψ(k²) = N vᵀ H⁻¹ v`, `v = [1, -1]`, for the symmetric ABA triblock.
Drop-in analogue of [`diblock_composition_kernel`]; returns `Inf` at `k2 = 0`.
"""
function triblock_aba_composition_kernel(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    kk = float(k2)
    kk == 0.0 && return Inf
    gamma = triblock_aba_ideal_vertex(kk; f=f, N=N, b=b)
    return Float64(N) *
        (gamma[1, 1] - gamma[1, 2] - gamma[2, 1] + gamma[2, 2])
end

"""
    triblock_aba_composition_kernel_derivative(k2; f=0.5, N=1.0, b=1.0)

`d Γ_ψ / d(k²)` for the symmetric ABA triblock (ForwardDiff), used by the
cell-size stress. Analogue of [`diblock_composition_kernel_derivative`].
"""
function triblock_aba_composition_kernel_derivative(k2::Real; f::Real=0.5,
        N::Real=1.0, b::Real=1.0)
    kk = Float64(k2)
    kk > 0.0 || throw(ArgumentError("k2 must be positive for kernel derivative"))
    return ForwardDiff.derivative(x ->
        triblock_aba_composition_kernel(x; f=f, N=N, b=b), kk)
end

"""
    triblock_aba_burp_ti_gaussian_kernel(k2; f=0.5, N=1.0, b=1.0)

Alias for [`triblock_aba_composition_kernel`], mirroring
[`diblock_burp_ti_gaussian_kernel`] so ABA slots into the same call sites.
"""
function triblock_aba_burp_ti_gaussian_kernel(k2::Real; f::Real=0.5, N::Real=1.0,
        b::Real=1.0)
    return triblock_aba_composition_kernel(k2; f=f, N=N, b=b)
end

function _periodic_k2_1d(n::Integer, L::Real)
    count = Int(n)
    count >= 2 || throw(ArgumentError("periodic grid requires at least two points"))
    length = Float64(L)
    length > 0.0 || throw(ArgumentError("periodic length L must be positive"))
    values = Vector{Float64}(undef, count)
    half = count ÷ 2
    for j in 1:count
        mode = j <= half + 1 ? j - 1 : j - 1 - count
        values[j] = (2.0 * pi * mode / length)^2
    end
    return values
end

function _diblock_nd_lengths(lengths, dims::NTuple{D,Int}) where {D}
    if lengths isa Real
        out = fill(Float64(lengths), D)
    else
        values = collect(lengths)
        length(values) == D ||
            throw(ArgumentError("lengths must have one entry per array dimension"))
        out = Float64.(values)
    end
    all(value -> value > 0.0 && isfinite(value), out) ||
        throw(ArgumentError("all periodic cell lengths must be positive and finite"))
    return out
end

function _periodic_k2_nd(dims::NTuple{D,Int}, lengths::AbstractVector{Float64}) where {D}
    all(count -> count >= 2, dims) ||
        throw(ArgumentError("periodic N-D grid requires at least two points per dimension"))
    length(lengths) == D ||
        throw(ArgumentError("lengths must have one entry per array dimension"))
    values_by_dim = [_periodic_k2_1d(dims[dim], lengths[dim]) for dim in 1:D]
    k2_values = Array{Float64}(undef, dims...)
    for index in CartesianIndices(k2_values)
        total = 0.0
        coords = Tuple(index)
        for dim in 1:D
            total += values_by_dim[dim][coords[dim]]
        end
        k2_values[index] = total
    end
    return k2_values
end

function _diblock_profile_energy_inputs_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi = Float64.(Array(phi_a))
    dims = size(phi)
    length(phi) >= 8 ||
        throw(ArgumentError("diblock N-D profile energy requires at least eight grid points"))
    all(count -> count >= 2, dims) ||
        throw(ArgumentError("diblock N-D profile energy requires at least two points per dimension"))
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    # Allow phi to reach the box edges (pure/saturated domains) or overshoot by
    # a hair; the model evaluators use the xlogy entropy limit and floor the
    # divergent eta / entropy-derivative logs.  Reject only gross excursions.
    (minimum(phi) >= -1.0e-10 && maximum(phi) <= 1.0 + 1.0e-10) ||
        throw(DomainError((minimum(phi), maximum(phi)),
            "diblock phi_A overshoot exceeds 1e-10 past [0, 1]"))
    mean_error = abs(mean(phi) - ff)
    mean_error <= Float64(mean_tolerance) ||
        throw(ArgumentError("mean phi_A must match f within mean_tolerance"))
    cell_lengths = _diblock_nd_lengths(lengths, dims)
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)
    cell_volume = prod(cell_lengths)
    dV = cell_volume / length(phi)
    return phi, dims, ff, chi, cell_lengths, nn, bb, dV
end

function _periodic_kernel_apply_1d(
        values::AbstractVector{Float64}, k2_values::AbstractVector{Float64}, kernel)
    count = length(values)
    values_hat = fft(values)
    out_hat = zeros(ComplexF64, count)
    for idx in 2:count
        out_hat[idx] = kernel(k2_values[idx]) * values_hat[idx]
    end
    return real.(ifft(out_hat))
end

# Overload for a precomputed kernel array (one value per k2_values entry)
# instead of a per-call kernel(k2) closure, so an expensive kernel (e.g. the
# BURP-TI composition kernel) can be hoisted out of hot loops that call this
# helper repeatedly with the same k2 grid.
function _periodic_kernel_apply_1d(
        values::AbstractVector{Float64}, k2_values::AbstractVector{Float64},
        kernel::AbstractVector{<:Real})
    count = length(values)
    length(kernel) == count ||
        throw(DimensionMismatch("precomputed kernel length must match values"))
    values_hat = fft(values)
    out_hat = zeros(ComplexF64, count)
    for idx in 2:count
        out_hat[idx] = kernel[idx] * values_hat[idx]
    end
    return real.(ifft(out_hat))
end

_logistic_stable(x::Real) = x >= 0 ? 1.0 / (1.0 + exp(-Float64(x))) :
    (value = exp(Float64(x)); value / (1.0 + value))

function _diblock_logit_shift(u::AbstractVector{<:Real}, f::Real)
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    lo = -80.0
    hi = 80.0
    for _ in 1:120
        mid = 0.5 * (lo + hi)
        avg = mean(_logistic_stable(mid + Float64(value)) for value in u)
        if avg < ff
            lo = mid
        else
            hi = mid
        end
    end
    return 0.5 * (lo + hi)
end

function diblock_lamella_profile_from_modes(coefficients::AbstractVector{<:Real};
        f::Real=0.5, nx::Integer=128, L::Real=1.0)
    count = Int(nx)
    count >= 8 || throw(ArgumentError("diblock lamella profile requires nx >= 8"))
    period = Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    coeffs = Float64.(collect(coefficients))
    all(isfinite, coeffs) || throw(ArgumentError("lamella mode coefficients must be finite"))
    x = [(i - 0.5) * period / count for i in 1:count]
    u = zeros(Float64, count)
    for mode in eachindex(coeffs)
        amplitude = coeffs[mode]
        @. u += amplitude * cos(2.0 * pi * mode * x / period)
    end
    shift = _diblock_logit_shift(u, ff)
    phi_a = [_logistic_stable(shift + value) for value in u]
    return x, phi_a
end

function _diblock_density_from_seed_field(seed_field::AbstractArray{<:Real}, f::Real)
    values = Float64.(vec(Array(seed_field)))
    all(isfinite, values) || throw(ArgumentError("morphology seed field must be finite"))
    shift = _diblock_logit_shift(values, f)
    phi = [_logistic_stable(shift + value) for value in values]
    return reshape(phi, size(seed_field))
end

function _diblock_seed_field_from_density(phi::AbstractArray{<:Real}, f::Real)
    values = clamp.(Float64.(vec(Array(phi))), 1.0e-12, 1.0 - 1.0e-12)
    all(isfinite, values) ||
        throw(ArgumentError("initial density field must be finite"))
    ff = Float64(f)
    0.0 < ff < 1.0 ||
        throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    logits = log.(values ./ (1.0 .- values))
    return reshape(logits, size(phi))
end

function _diblock_morphology_symbol(morphology)
    token = uppercase(String(Symbol(morphology)))
    token = replace(token, "-" => "_")
    token = replace(token, "/" => "_")
    if token in ("LAM", "LAMELLA", "LAMELLAR")
        return :LAM
    elseif token in ("CYL", "CYLINDER", "CYLINDERS", "HEX")
        return :CYL
    elseif token in ("BCC", "SPH", "SPHERE", "SPHERES", "SPH_BCC", "BCC_SPH")
        return :BCC
    elseif token in ("GYR", "GYROID")
        return :GYR
    end
    throw(ArgumentError("unsupported diblock morphology seed: $(morphology)"))
end

function _diblock_morphology_dims(dims)
    if dims isa Integer
        return (Int(dims),)
    end
    values = Tuple(Int(value) for value in dims)
    all(value -> value >= 2, values) ||
        throw(ArgumentError("morphology seed dimensions must be at least two"))
    return values
end

function _diblock_morphology_seed_field(morphology, dims::NTuple{D,Int};
        amplitude::Real=1.0) where {D}
    kind = _diblock_morphology_symbol(morphology)
    amp = Float64(amplitude)
    isfinite(amp) || throw(ArgumentError("morphology seed amplitude must be finite"))
    kind == :CYL && D >= 2 ||
        kind != :CYL ||
        throw(ArgumentError("CYL seed requires at least two dimensions"))
    (kind == :BCC || kind == :GYR) && D >= 3 ||
        !(kind == :BCC || kind == :GYR) ||
        throw(ArgumentError("BCC/SPH and GYR seeds require at least three dimensions"))

    field = Array{Float64}(undef, dims...)
    for index in CartesianIndices(field)
        coords = Tuple(index)
        s1 = (coords[1] - 0.5) / dims[1]
        if kind == :LAM
            value = cos(2.0 * pi * s1)
        elseif kind == :CYL
            s2 = (coords[2] - 0.5) / dims[2]
            value = cos(4.0 * pi * s1) + 2.0 * cos(2.0 * pi * s1) *
                cos(2.0 * pi * s2)
        else
            s2 = (coords[2] - 0.5) / dims[2]
            s3 = (coords[3] - 0.5) / dims[3]
            x = 2.0 * pi * s1
            y = 2.0 * pi * s2
            z = 2.0 * pi * s3
            if kind == :BCC
                value = cos(x) * cos(y) + cos(y) * cos(z) + cos(z) * cos(x)
            else
                value = sin(x) * cos(y) + sin(y) * cos(z) + sin(z) * cos(x)
            end
        end
        field[index] = amp * value
    end
    return field
end

function _periodic_binary_linear_site(index::NTuple{D,Int},
        dims::NTuple{D,Int}) where {D}
    site = 1
    stride = 1
    for dim in 1:D
        site += (index[dim] - 1) * stride
        stride *= dims[dim]
    end
    return site
end

function _periodic_binary_component_summary(mask::AbstractArray{Bool,D}) where {D}
    dims = size(mask)
    total_sites = length(mask)
    parents = collect(1:total_sites)
    ranks = zeros(Int, total_sites)
    wraps_by_root = [falses(D) for _ in 1:total_sites]

    function find_root(site)
        root = site
        while parents[root] != root
            root = parents[root]
        end
        while parents[site] != site
            next = parents[site]
            parents[site] = root
            site = next
        end
        return root
    end

    function union_sites(a, b, wrap_dim)
        ra = find_root(a)
        rb = find_root(b)
        if ra != rb
            if ranks[ra] < ranks[rb]
                ra, rb = rb, ra
            end
            parents[rb] = ra
            wraps_by_root[ra] .|= wraps_by_root[rb]
            ranks[ra] == ranks[rb] && (ranks[ra] += 1)
        end
        root = find_root(ra)
        wrap_dim > 0 && (wraps_by_root[root][wrap_dim] = true)
        return root
    end

    for index in CartesianIndices(mask)
        mask[index] || continue
        current = Tuple(index)
        site = _periodic_binary_linear_site(current, dims)
        for dim in 1:D
            neighbor = ntuple(axis -> axis == dim ?
                (current[axis] == dims[axis] ? 1 : current[axis] + 1) :
                current[axis], D)
            mask[neighbor...] || continue
            wrap_dim = current[dim] == dims[dim] ? dim : 0
            union_sites(site, _periodic_binary_linear_site(neighbor, dims),
                wrap_dim)
        end
    end

    component_sizes = Dict{Int,Int}()
    component_wraps = Dict{Int,BitVector}()
    for index in CartesianIndices(mask)
        mask[index] || continue
        root = find_root(_periodic_binary_linear_site(Tuple(index), dims))
        component_sizes[root] = get(component_sizes, root, 0) + 1
        component_wraps[root] = wraps_by_root[root]
    end
    isempty(component_sizes) && return (
        component_count=0,
        largest_component_fraction=0.0,
        max_wrap_dimensions=0,
    )
    largest = maximum(values(component_sizes))
    max_wraps = maximum(count(identity, wraps) for wraps in values(component_wraps))
    return (
        component_count=length(component_sizes),
        largest_component_fraction=largest / total_sites,
        max_wrap_dimensions=max_wraps,
    )
end

function _periodic_binary_cubical_euler(mask::AbstractArray{Bool,3})
    dims = size(mask)
    vertices = Set{NTuple{3,Int}}()
    edges = Set{NTuple{4,Int}}()
    faces = Set{NTuple{4,Int}}()
    cube_count = 0

    wrap(coord, dim) = mod(coord, dims[dim])

    for index in CartesianIndices(mask)
        mask[index] || continue
        cube_count += 1
        c = (index[1] - 1, index[2] - 1, index[3] - 1)
        for dx in 0:1, dy in 0:1, dz in 0:1
            push!(vertices, (wrap(c[1] + dx, 1), wrap(c[2] + dy, 2),
                wrap(c[3] + dz, 3)))
        end
        for face_offset in (0, 1)
            push!(faces, (1, wrap(c[1] + face_offset, 1), c[2], c[3]))
            push!(faces, (2, c[1], wrap(c[2] + face_offset, 2), c[3]))
            push!(faces, (3, c[1], c[2], wrap(c[3] + face_offset, 3)))
        end
        for dy in 0:1, dz in 0:1
            push!(edges, (1, c[1], wrap(c[2] + dy, 2),
                wrap(c[3] + dz, 3)))
        end
        for dx in 0:1, dz in 0:1
            push!(edges, (2, wrap(c[1] + dx, 1), c[2],
                wrap(c[3] + dz, 3)))
        end
        for dx in 0:1, dy in 0:1
            push!(edges, (3, wrap(c[1] + dx, 1),
                wrap(c[2] + dy, 2), c[3]))
        end
    end

    vertex_count = length(vertices)
    edge_count = length(edges)
    face_count = length(faces)
    return (
        vertex_count=vertex_count,
        edge_count=edge_count,
        face_count=face_count,
        cube_count=cube_count,
        euler_characteristic=vertex_count - edge_count + face_count - cube_count,
    )
end

function _periodic_binary_topology_metrics(values::AbstractArray{<:Real,3};
        threshold::Real=mean(values))
    field = Float64.(values)
    rich_a = field .>= Float64(threshold)
    rich_b = .!rich_a
    a_components = _periodic_binary_component_summary(rich_a)
    b_components = _periodic_binary_component_summary(rich_b)
    a_euler = _periodic_binary_cubical_euler(rich_a)
    b_euler = _periodic_binary_cubical_euler(rich_b)
    dims = ndims(field)
    bicontinuous = a_components.max_wrap_dimensions == dims &&
        b_components.max_wrap_dimensions == dims
    negative_double = bicontinuous &&
        a_euler.euler_characteristic < 0 &&
        b_euler.euler_characteristic < 0
    label = if negative_double
        "double_network_negative_euler"
    elseif bicontinuous
        "bicontinuous_nonnegative_euler"
    elseif a_components.max_wrap_dimensions == dims - 1 &&
            b_components.max_wrap_dimensions == dims - 1
        "lamellar_or_slab"
    elseif max(a_components.max_wrap_dimensions,
            b_components.max_wrap_dimensions) == dims
        "single_phase_network_or_cylinder"
    else
        "fragmented_or_finite_cluster"
    end
    total_sites = length(field)
    return (
        topology_threshold=Float64(threshold),
        a_rich_component_count=a_components.component_count,
        a_rich_largest_component_fraction=a_components.largest_component_fraction,
        a_rich_max_wrap_dimensions=a_components.max_wrap_dimensions,
        a_rich_euler_characteristic=a_euler.euler_characteristic,
        a_rich_euler_density=a_euler.euler_characteristic / total_sites,
        b_rich_component_count=b_components.component_count,
        b_rich_largest_component_fraction=b_components.largest_component_fraction,
        b_rich_max_wrap_dimensions=b_components.max_wrap_dimensions,
        b_rich_euler_characteristic=b_euler.euler_characteristic,
        b_rich_euler_density=b_euler.euler_characteristic / total_sites,
        bicontinuous_periodic=bicontinuous,
        negative_euler_double_network=negative_double,
        topology_label=label,
    )
end

function _periodic_fft_frequency(index::Integer, count::Integer)
    value = Int(index) - 1
    return value <= count ÷ 2 ? value : value - count
end

function _spectral_shell_label(mode::NTuple{3,Int})
    return join(sort(abs.(collect(mode)); rev=true))
end

function _dominant_spectral_shell_metrics(values::AbstractArray{<:Real,3};
        relative_mode_cutoff::Real=1.0e-8)
    field = Float64.(values)
    centered = field .- mean(field)
    spectrum = fft(centered)
    dims = size(field)
    shell_power = Dict{Int,Float64}()
    shell_labels = Dict{Int,Set{String}}()
    shell_mode_powers = Dict{Int,Vector{Float64}}()
    total_power = 0.0
    for index in CartesianIndices(spectrum)
        mode = (_periodic_fft_frequency(index[1], dims[1]),
            _periodic_fft_frequency(index[2], dims[2]),
            _periodic_fft_frequency(index[3], dims[3]))
        mode == (0, 0, 0) && continue
        power = abs2(spectrum[index])
        k2 = sum(value * value for value in mode)
        shell_power[k2] = get(shell_power, k2, 0.0) + power
        push!(get!(shell_labels, k2, Set{String}()), _spectral_shell_label(mode))
        push!(get!(shell_mode_powers, k2, Float64[]), power)
        total_power += power
    end
    if isempty(shell_power) || total_power == 0.0
        return (
            dominant_shell_k2=0,
            dominant_shell_label="000",
            dominant_shell_power_fraction=0.0,
            dominant_shell_effective_mode_count=0,
            dominant_shell_participation_ratio=0.0,
            dominant_shell_largest_mode_fraction=0.0,
            dominant_shell_uniformity=0.0,
        )
    end
    ordered_k2 = sort(collect(keys(shell_power)); by=k2 -> (-shell_power[k2], k2))
    dominant_k2 = first(ordered_k2)
    powers = sort(shell_mode_powers[dominant_k2]; rev=true)
    shell_total = shell_power[dominant_k2]
    largest = maximum(powers)
    cutoff = largest * Float64(relative_mode_cutoff)
    significant = [power for power in powers if power > cutoff]
    labels = sort(collect(shell_labels[dominant_k2]))
    participation = shell_total^2 / sum(power * power for power in powers)
    return (
        dominant_shell_k2=dominant_k2,
        dominant_shell_label=join(labels, "+"),
        dominant_shell_power_fraction=shell_total / total_power,
        dominant_shell_effective_mode_count=length(significant),
        dominant_shell_participation_ratio=participation,
        dominant_shell_largest_mode_fraction=largest / shell_total,
        dominant_shell_uniformity=isempty(significant) ? 0.0 :
            minimum(significant) / maximum(significant),
    )
end

function _shell_invariant_gyroid_support_metrics(values::AbstractArray{<:Real,3};
        threshold::Real=mean(values),
        min_dominant_shell_power_fraction::Real=0.75,
        min_effective_mode_count::Integer=10,
        max_largest_mode_fraction::Real=0.12,
        relative_mode_cutoff::Real=1.0e-8)
    topology = _periodic_binary_topology_metrics(values; threshold=threshold)
    spectral = _dominant_spectral_shell_metrics(values;
        relative_mode_cutoff=relative_mode_cutoff)
    concentrated = spectral.dominant_shell_power_fraction >=
        Float64(min_dominant_shell_power_fraction)
    many_mode = spectral.dominant_shell_effective_mode_count >=
        Int(min_effective_mode_count)
    not_single_peak = spectral.dominant_shell_largest_mode_fraction <=
        Float64(max_largest_mode_fraction)
    support = topology.negative_euler_double_network && concentrated &&
        many_mode && not_single_peak
    label = if support
        "gyroid_or_bcc_double_network_support"
    elseif topology.negative_euler_double_network
        "double_network_spectral_mismatch"
    elseif concentrated && many_mode
        "spectral_support_without_double_network_topology"
    else
        "not_gyroid_support"
    end
    return merge(topology, spectral, (
        shell_invariant_topology_support=topology.negative_euler_double_network,
        shell_invariant_spectral_support=concentrated && many_mode &&
            not_single_peak,
        shell_invariant_support=support,
        shell_invariant_support_label=label,
        phase_information_required=support,
    ))
end

function diblock_morphology_seed(morphology; f::Real=0.5, dims=(64,),
        lengths=1.0, amplitude::Real=1.0)
    grid_dims = _diblock_morphology_dims(dims)
    _diblock_nd_lengths(lengths, grid_dims)
    field = _diblock_morphology_seed_field(morphology, grid_dims;
        amplitude=amplitude)
    return _diblock_density_from_seed_field(field, f)
end

function _diblock_morphology_model_symbol(model)
    token = uppercase(String(Symbol(model)))
    token = replace(token, "-" => "_")
    if token in ("BVK1", "VK1")
        return :BVK1
    elseif token in ("BURP", "BURP_TI", "BURPTI")
        return :BURP_TI
    end
    throw(ArgumentError("unsupported morphology seed-amplitude model: $(model)"))
end

function _diblock_morphology_seed_energy(phi::AbstractArray{Float64}, model::Symbol;
        f::Float64, chiN::Float64, lengths, N::Float64, b::Float64, nquad::Integer)
    if model == :BVK1
        return diblock_bvk1_energy_nd(phi; f=f, chiN=chiN, lengths=lengths,
            N=N, b=b)
    elseif model == :BURP_TI
        return diblock_burp_ti_energy_nd(phi; f=f, chiN=chiN, lengths=lengths,
            N=N, b=b, nquad=nquad)
    end
    throw(ArgumentError("unsupported morphology seed-amplitude model: $(model)"))
end

function optimize_diblock_morphology_seed_amplitude(morphology; model=:BVK1,
        f::Real=0.5, chiN::Real=20.0, dims=(64,), lengths=1.0,
        lower_amplitude::Real=0.0, upper_amplitude::Real=2.0, N::Real=1.0,
        b::Real=1.0, nquad::Integer=4, iterations::Integer=48)
    kind = _diblock_morphology_symbol(morphology)
    model_kind = _diblock_morphology_model_symbol(model)
    model_name = model_kind == :BVK1 ? "BVK1" : "BURP-TI"
    grid_dims = _diblock_morphology_dims(dims)
    cell_lengths = _diblock_nd_lengths(lengths, grid_dims)
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    nn = Float64(N)
    bb = Float64(b)
    _, nn, bb, _ = _diblock_validate(ff, nn, bb, 1.0)
    lo = Float64(lower_amplitude)
    hi = Float64(upper_amplitude)
    0.0 <= lo < hi ||
        throw(ArgumentError("amplitude bracket must satisfy 0 <= lower < upper"))
    max_iterations = Int(iterations)
    max_iterations > 0 || throw(ArgumentError("iterations must be positive"))
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))

    function energy_at(amplitude)
        phi = diblock_morphology_seed(kind; f=ff, dims=grid_dims,
            lengths=cell_lengths, amplitude=amplitude)
        return _diblock_morphology_seed_energy(phi, model_kind; f=ff,
            chiN=chi, lengths=cell_lengths, N=nn, b=bb, nquad=qcount)
    end

    homogeneous_energy = energy_at(0.0)
    result = Optim.optimize(energy_at, lo, hi, Optim.Brent();
        iterations=max_iterations)
    amplitude = Optim.minimizer(result)
    phi = diblock_morphology_seed(kind; f=ff, dims=grid_dims,
        lengths=cell_lengths, amplitude=amplitude)
    energy = _diblock_morphology_seed_energy(phi, model_kind; f=ff, chiN=chi,
        lengths=cell_lengths, N=nn, b=bb, nquad=qcount)
    return (
        morphology=string(kind),
        model=model_name,
        amplitude=amplitude,
        energy=energy,
        homogeneous_energy=homogeneous_energy,
        energy_drop=homogeneous_energy - energy,
        mean_phi=mean(phi),
        min_phi=minimum(phi),
        max_phi=maximum(phi),
        contrast=maximum(phi) - minimum(phi),
        converged=Optim.converged(result),
        iterations=Optim.iterations(result),
        lower_amplitude=lo,
        upper_amplitude=hi,
    )
end

function _diblock_morphology_relaxation_objective(u::AbstractVector{Float64},
        dims::Tuple, model_kind::Symbol; f::Float64, chiN::Float64, lengths,
        N::Float64, b::Float64, nquad::Integer)
    phi = _diblock_density_from_seed_field(reshape(u, dims), f)
    energy = _diblock_morphology_seed_energy(phi, model_kind; f=f, chiN=chiN,
        lengths=lengths, N=N, b=b, nquad=nquad)
    return energy, phi
end

function _diblock_morphology_relaxation_gradient!(
        gradient::AbstractVector{Float64}, u::Vector{Float64},
        dims::Tuple, model_kind::Symbol; f::Float64, chiN::Float64, lengths,
        N::Float64, b::Float64, nquad::Integer, step::Float64)
    step > 0.0 && isfinite(step) ||
        throw(ArgumentError("finite_difference_step must be positive and finite"))
    for idx in eachindex(u)
        old = u[idx]
        u[idx] = old + step
        plus, _ = _diblock_morphology_relaxation_objective(u, dims, model_kind;
            f=f, chiN=chiN, lengths=lengths, N=N, b=b, nquad=nquad)
        u[idx] = old - step
        minus, _ = _diblock_morphology_relaxation_objective(u, dims, model_kind;
            f=f, chiN=chiN, lengths=lengths, N=N, b=b, nquad=nquad)
        u[idx] = old
        gradient[idx] = (plus - minus) / (2.0 * step)
    end
    gradient .-= mean(gradient)
    return gradient
end

function relax_diblock_morphology_seed_nd(morphology; model=:BVK1,
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), lengths=1.0,
        initial_amplitude::Real=1.0, N::Real=1.0, b::Real=1.0,
        nquad::Integer=4, max_iterations::Integer=4,
        gradient_step::Real=0.05, finite_difference_step::Real=1.0e-4,
        backtracking_steps::Integer=8, tolerance::Real=1.0e-10,
        initial_density=nothing)
    kind = _diblock_morphology_symbol(morphology)
    model_kind = _diblock_morphology_model_symbol(model)
    model_name = model_kind == :BVK1 ? "BVK1" : "BURP-TI"
    grid_dims = _diblock_morphology_dims(dims)
    cell_lengths = _diblock_nd_lengths(lengths, grid_dims)
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    nn = Float64(N)
    bb = Float64(b)
    _, nn, bb, _ = _diblock_validate(ff, nn, bb, 1.0)
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))
    iterations = Int(max_iterations)
    iterations >= 0 || throw(ArgumentError("max_iterations must be nonnegative"))
    descent_step = Float64(gradient_step)
    descent_step > 0.0 && isfinite(descent_step) ||
        throw(ArgumentError("gradient_step must be positive and finite"))
    fd_step = Float64(finite_difference_step)
    fd_step > 0.0 && isfinite(fd_step) ||
        throw(ArgumentError("finite_difference_step must be positive and finite"))
    backtracks = Int(backtracking_steps)
    backtracks > 0 || throw(ArgumentError("backtracking_steps must be positive"))
    tol = Float64(tolerance)
    tol >= 0.0 && isfinite(tol) || throw(ArgumentError("tolerance must be nonnegative"))

    initial_source = initial_density === nothing ? "analytic_seed" : "density_logit"
    initial_field = if initial_density === nothing
        _diblock_morphology_seed_field(kind, grid_dims;
            amplitude=initial_amplitude)
    else
        density = Float64.(Array(initial_density))
        size(density) == grid_dims ||
            throw(DimensionMismatch("initial_density must match the requested grid dimensions"))
        _diblock_seed_field_from_density(density, ff)
    end
    u = Float64.(vec(initial_field))
    initial_energy, initial_phi = _diblock_morphology_relaxation_objective(u,
        grid_dims, model_kind; f=ff, chiN=chi, lengths=cell_lengths, N=nn,
        b=bb, nquad=qcount)
    homogeneous_u = zeros(Float64, length(u))
    homogeneous_energy, _ = _diblock_morphology_relaxation_objective(
        homogeneous_u, grid_dims, model_kind; f=ff, chiN=chi,
        lengths=cell_lengths, N=nn, b=bb, nquad=qcount)
    energy = initial_energy
    phi = initial_phi
    gradient = similar(u)
    gradient_norm = 0.0
    accepted_steps = 0
    last_improvement = 0.0

    for _ in 1:iterations
        _diblock_morphology_relaxation_gradient!(gradient, u, grid_dims,
            model_kind; f=ff, chiN=chi, lengths=cell_lengths, N=nn, b=bb,
            nquad=qcount, step=fd_step)
        gradient_norm = norm(gradient)
        gradient_norm <= tol && break
        direction = gradient ./ max(gradient_norm, 1.0)
        accepted = false
        trial_step = descent_step
        for _attempt in 1:backtracks
            candidate = u .- trial_step .* direction
            candidate_energy, candidate_phi =
                _diblock_morphology_relaxation_objective(candidate, grid_dims,
                    model_kind; f=ff, chiN=chi, lengths=cell_lengths, N=nn,
                    b=bb, nquad=qcount)
            if candidate_energy < energy - tol
                last_improvement = energy - candidate_energy
                u = candidate
                energy = candidate_energy
                phi = candidate_phi
                accepted_steps += 1
                accepted = true
                break
            end
            trial_step *= 0.5
        end
        accepted || break
    end

    return (
        morphology=string(kind),
        model=model_name,
        initial_source=initial_source,
        energy=energy,
        initial_energy=initial_energy,
        homogeneous_energy=homogeneous_energy,
        energy_drop_from_initial=initial_energy - energy,
        energy_drop_from_homogeneous=homogeneous_energy - energy,
        mean_phi=mean(phi),
        min_phi=minimum(phi),
        max_phi=maximum(phi),
        contrast=maximum(phi) - minimum(phi),
        gradient_norm=gradient_norm,
        accepted_steps=accepted_steps,
        max_iterations=iterations,
        converged=gradient_norm <= tol,
        last_improvement=last_improvement,
        relaxed_field=reshape(copy(u), grid_dims),
        phi=copy(phi),
    )
end

function probe_diblock_morphology_relaxation_stationarity(morphology; model=:BVK1,
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), lengths=1.0,
        initial_amplitude::Real=1.0, N::Real=1.0, b::Real=1.0,
        nquad::Integer=4, max_iterations::Integer=4,
        gradient_step::Real=0.05, finite_difference_step::Real=1.0e-4,
        backtracking_steps::Integer=8, tolerance::Real=1.0e-10,
        probe_count::Integer=8, perturbation_scale::Real=1.0e-4,
        energy_tolerance::Real=1.0e-8, seed::Integer=1701)
    kind = _diblock_morphology_symbol(morphology)
    model_kind = _diblock_morphology_model_symbol(model)
    grid_dims = _diblock_morphology_dims(dims)
    cell_lengths = _diblock_nd_lengths(lengths, grid_dims)
    ff = Float64(f)
    chi = Float64(chiN)
    nn = Float64(N)
    bb = Float64(b)
    _, nn, bb, _ = _diblock_validate(ff, nn, bb, 1.0)
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))
    count = Int(probe_count)
    count > 0 || throw(ArgumentError("probe_count must be positive"))
    scale = Float64(perturbation_scale)
    scale > 0.0 && isfinite(scale) ||
        throw(ArgumentError("perturbation_scale must be positive and finite"))
    energy_tol = Float64(energy_tolerance)
    energy_tol >= 0.0 && isfinite(energy_tol) ||
        throw(ArgumentError("energy_tolerance must be nonnegative and finite"))

    relaxation = relax_diblock_morphology_seed_nd(kind; model=model_kind, f=ff,
        chiN=chi, dims=grid_dims, lengths=cell_lengths,
        initial_amplitude=initial_amplitude, N=nn, b=bb, nquad=qcount,
        max_iterations=max_iterations, gradient_step=gradient_step,
        finite_difference_step=finite_difference_step,
        backtracking_steps=backtracking_steps, tolerance=tolerance)
    u0 = Float64.(vec(relaxation.relaxed_field))
    base_energy = relaxation.energy
    rng = Random.MersenneTwister(Int(seed))
    forward_deltas = Float64[]
    backward_deltas = Float64[]
    symmetric_deltas = Float64[]

    for _ in 1:count
        direction = randn(rng, length(u0))
        direction .-= mean(direction)
        norm_direction = norm(direction)
        if norm_direction == 0.0
            direction[1] = 1.0
            norm_direction = 1.0
        end
        direction ./= norm_direction
        forward_energy, _ = _diblock_morphology_relaxation_objective(
            u0 .+ scale .* direction, grid_dims, model_kind; f=ff, chiN=chi,
            lengths=cell_lengths, N=nn, b=bb, nquad=qcount)
        backward_energy, _ = _diblock_morphology_relaxation_objective(
            u0 .- scale .* direction, grid_dims, model_kind; f=ff, chiN=chi,
            lengths=cell_lengths, N=nn, b=bb, nquad=qcount)
        forward_delta = forward_energy - base_energy
        backward_delta = backward_energy - base_energy
        push!(forward_deltas, forward_delta)
        push!(backward_deltas, backward_delta)
        push!(symmetric_deltas, min(forward_delta, backward_delta))
    end
    min_forward = minimum(forward_deltas)
    min_backward = minimum(backward_deltas)
    min_symmetric = minimum(symmetric_deltas)
    max_symmetric = maximum(symmetric_deltas)
    return (
        morphology=relaxation.morphology,
        model=relaxation.model,
        relaxation=relaxation,
        probe_count=count,
        perturbation_scale=scale,
        energy_tolerance=energy_tol,
        min_forward_delta=min_forward,
        min_backward_delta=min_backward,
        min_symmetric_delta=min_symmetric,
        max_symmetric_delta=max_symmetric,
        mean_symmetric_delta=mean(symmetric_deltas),
        local_stationarity_pass=min_symmetric >= -energy_tol,
        seed=Int(seed),
    )
end

"""
    DiblockBurpTiWorkspace1D(count)

Preallocated complex scratch buffers and a reusable out-of-place FFTW plan
for repeated `diblock_burp_ti_energy_1d` evaluations on a fixed grid size
`count`. Build this once (e.g. once per solver cell/geometry) and pass it
via the `workspace` keyword to reuse the same psi/eta/psi_hat/eta_hat
buffers across every quadrature point and every energy evaluation, instead
of allocating a fresh `nquad`-many `eta`/`eta_hat` arrays per call. When
`workspace` is not supplied, the function allocates one internally so the
API stays backward compatible.
"""
struct DiblockBurpTiWorkspace1D{P}
    count::Int
    psi_c::Vector{ComplexF64}
    eta_c::Vector{ComplexF64}
    psi_hat::Vector{ComplexF64}
    eta_hat::Vector{ComplexF64}
    plan::P
end

function DiblockBurpTiWorkspace1D(count::Integer)
    n = Int(count)
    n >= 2 || throw(ArgumentError("BURP-TI 1D workspace requires at least two grid points"))
    psi_c = zeros(ComplexF64, n)
    plan = plan_fft(psi_c)
    return DiblockBurpTiWorkspace1D{typeof(plan)}(n, psi_c, zeros(ComplexF64, n),
        zeros(ComplexF64, n), zeros(ComplexF64, n), plan)
end

"""
    DiblockBurpTiWorkspaceND(dims)

N-D analogue of [`DiblockBurpTiWorkspace1D`](@ref): preallocated complex
scratch arrays and a reusable out-of-place FFTW plan for repeated
`diblock_burp_ti_energy_nd` evaluations on a fixed grid `dims`.
"""
struct DiblockBurpTiWorkspaceND{D,P}
    dims::NTuple{D,Int}
    psi_c::Array{ComplexF64,D}
    eta_c::Array{ComplexF64,D}
    psi_hat::Array{ComplexF64,D}
    eta_hat::Array{ComplexF64,D}
    plan::P
end

function DiblockBurpTiWorkspaceND(dims::NTuple{D,Int}) where {D}
    all(count -> count >= 2, dims) ||
        throw(ArgumentError("BURP-TI N-D workspace requires at least two points per dimension"))
    psi_c = zeros(ComplexF64, dims...)
    plan = plan_fft(psi_c)
    return DiblockBurpTiWorkspaceND{D,typeof(plan)}(dims, psi_c,
        zeros(ComplexF64, dims...), zeros(ComplexF64, dims...),
        zeros(ComplexF64, dims...), plan)
end

# Type-stable inner reduction for the BURP-TI entropic mode sum (function
# barrier: concrete array types are passed in so this loop specializes and
# inlines cleanly instead of running inside a large, keyword-heavy outer
# function). Index 1 (the DC / k2==0 mode) is always the sole zero-k2 entry
# for the periodic grids built by `_periodic_k2_1d`/`_periodic_k2_nd` (every
# per-axis term is >= 0, so the sum is exactly 0.0 only when every axis
# index is 1), so skipping linear index 1 is exactly equivalent to the
# previous `k2_values[index] == 0.0 && continue` guard, evaluated in the same
# (column-major / CartesianIndices) traversal order.
function _burp_ti_mode_sum(psi_hat::AbstractArray{ComplexF64},
        kern::AbstractArray{<:Real}, eta_hat::AbstractArray{ComplexF64})
    total = 0.0
    @inbounds for idx in 2:length(psi_hat)
        total += real(conj(psi_hat[idx]) * kern[idx] * eta_hat[idx])
    end
    return total
end

function diblock_burp_ti_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        nquad::Integer=16, mean_tolerance::Real=1.0e-8,
        composition_kernel=nothing, workspace=nothing)
    phi = Float64.(collect(phi_a))
    count = length(phi)
    count >= 8 || throw(ArgumentError("diblock BURP energy requires at least eight grid points"))
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    # Allow phi to reach the box edges (pure/saturated domains) or overshoot by
    # a hair; the model evaluators use the xlogy entropy limit and floor the
    # divergent eta / entropy-derivative logs.  Reject only gross excursions.
    (minimum(phi) >= -1.0e-10 && maximum(phi) <= 1.0 + 1.0e-10) ||
        throw(DomainError((minimum(phi), maximum(phi)),
            "diblock phi_A overshoot exceeds 1e-10 past [0, 1]"))
    mean_error = abs(mean(phi) - ff)
    mean_error <= Float64(mean_tolerance) ||
        throw(ArgumentError("mean phi_A must match f within mean_tolerance"))
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))
    period = Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)

    # Preallocated-workspace path (see `DiblockBurpTiWorkspace1D`): reuse the
    # same complex scratch buffers and FFTW plan across every quadrature
    # point instead of allocating fresh eta/eta_hat arrays `qcount` times per
    # call. Falls back to allocating a throwaway workspace when the caller
    # does not supply one, so the public API stays backward compatible.
    ws = workspace === nothing ? DiblockBurpTiWorkspace1D(count) : workspace
    ws.count == count ||
        throw(DimensionMismatch("workspace count $(ws.count) does not match phi length $(count)"))

    psi_c = ws.psi_c
    @inbounds for i in eachindex(phi)
        psi_c[i] = phi[i] - ff
    end
    mul!(ws.psi_hat, ws.plan, psi_c)
    psi_hat = ws.psi_hat

    # The composition kernel depends only on k2 (fixed by the grid/period),
    # never on q or phi, so it is hoisted out of the quadrature loop below
    # and computed once per call instead of qcount * count times.
    kern = if composition_kernel === nothing
        k2_values = _periodic_k2_1d(count, period)
        [diblock_composition_kernel(k2_values[idx]; f=ff, N=nn, b=bb)
         for idx in eachindex(k2_values)]
    else
        composition_kernel
    end

    eta_c = ws.eta_c
    eta_hat = ws.eta_hat
    entropic = 0.0
    for q in 1:qcount
        lambda = (q - 0.5) / qcount
        @inbounds for i in eachindex(phi)
            eta_c[i] = diblock_burp_eta_psi(ff + lambda * (phi[i] - ff), ff)
        end
        mul!(eta_hat, ws.plan, eta_c)
        entropic += _burp_ti_mode_sum(psi_hat, kern, eta_hat) / qcount
    end
    dx = period / count
    entropic *= dx / count
    interaction = chi * dx * sum(value * (1.0 - value) - ff * (1.0 - ff) for value in phi)
    return entropic + interaction
end

function diblock_burp_ti_energy_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        nquad::Integer=16, mean_tolerance::Real=1.0e-8,
        composition_kernel=nothing, workspace=nothing)
    phi, dims, ff, chi, cell_lengths, nn, bb, dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))

    # Preallocated-workspace path (see `DiblockBurpTiWorkspaceND`): reuse the
    # same complex scratch arrays and FFTW plan across every quadrature point
    # instead of allocating a fresh `nx^D`-sized eta/eta_hat array `qcount`
    # times per call (the dominant allocation source on 3D grids). Falls
    # back to allocating a throwaway workspace when the caller does not
    # supply one, so the public API stays backward compatible.
    ws = workspace === nothing ? DiblockBurpTiWorkspaceND(dims) : workspace
    ws.dims == dims ||
        throw(DimensionMismatch("workspace dims $(ws.dims) do not match phi dims $(dims)"))

    psi_c = ws.psi_c
    @inbounds for i in eachindex(phi)
        psi_c[i] = phi[i] - ff
    end
    mul!(ws.psi_hat, ws.plan, psi_c)
    psi_hat = ws.psi_hat

    # Same hoist as the 1D case: the kernel depends only on k2, so compute it
    # once per call rather than once per (q, mode) pair. When the caller
    # already supplies a precomputed kernel (the solver's hot path), the
    # k2 grid itself is never recomputed either.
    kern = if composition_kernel === nothing
        k2_values = _periodic_k2_nd(dims, cell_lengths)
        map(k2 -> diblock_composition_kernel(k2; f=ff, N=nn, b=bb), k2_values)
    else
        composition_kernel
    end

    eta_c = ws.eta_c
    eta_hat = ws.eta_hat
    entropic = 0.0
    for q in 1:qcount
        lambda = (q - 0.5) / qcount
        @inbounds for i in eachindex(phi)
            eta_c[i] = diblock_burp_eta_psi(ff + lambda * (phi[i] - ff), ff)
        end
        mul!(eta_hat, ws.plan, eta_c)
        entropic += _burp_ti_mode_sum(psi_hat, kern, eta_hat) / qcount
    end
    entropic *= dV / length(phi)
    interaction = chi * dV * sum(value * (1.0 - value) - ff * (1.0 - ff)
        for value in phi)
    return entropic + interaction
end

"""
    diblock_burp_ti_cell_scale_gradient_density_nd(phi_a; f, chiN, lengths, ...)

Return the analytic derivative of the BURP-TI free-energy density with
respect to an isotropic scalar cell scale `a` at fixed aspect ratio, using
`a = lengths[1]`. This is the cell stress used for scalar cell optimization:
at a stress-free cell, the returned value is zero.

The formula applies by the envelope theorem at a converged fixed-composition
field. Away from field stationarity it is still the frozen-field explicit
cell derivative, useful for diagnostics but not a substitute for relaxing the
field at the candidate cell.
"""
function diblock_burp_ti_cell_scale_gradient_density_nd(
        phi_a::AbstractArray{<:Real}; f::Real=0.5, chiN::Real=12.0,
        lengths=1.0, N::Real=1.0, b::Real=1.0, nquad::Integer=16,
        mean_tolerance::Real=1.0e-8, workspace=nothing,
        kernel_derivative=nothing)
    phi, dims, ff, chi, cell_lengths, nn, bb, _ =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))
    scale = cell_lengths[1]
    scale > 0.0 || throw(ArgumentError("cell scale must be positive"))

    ws = workspace === nothing ? DiblockBurpTiWorkspaceND(dims) : workspace
    ws.dims == dims ||
        throw(DimensionMismatch("workspace dims $(ws.dims) do not match phi dims $(dims)"))

    psi_c = ws.psi_c
    @inbounds for i in eachindex(phi)
        psi_c[i] = phi[i] - ff
    end
    mul!(ws.psi_hat, ws.plan, psi_c)
    psi_hat = ws.psi_hat

    # Architecture enters only through κ'(k²): default to the diblock kernel
    # derivative, or use the caller-supplied `kernel_derivative(k2)` closure
    # (e.g. `triblock_aba_composition_kernel_derivative`) for other topologies.
    kderiv = kernel_derivative === nothing ?
        (k2 -> diblock_composition_kernel_derivative(k2; f=ff, N=nn, b=bb)) :
        kernel_derivative
    k2_values = _periodic_k2_nd(dims, cell_lengths)
    stress_weights = similar(k2_values)
    first = firstindex(k2_values)
    @inbounds for idx in eachindex(k2_values)
        if idx == first
            stress_weights[idx] = 0.0
        else
            k2 = k2_values[idx]
            stress_weights[idx] = k2 * kderiv(k2)
        end
    end

    eta_c = ws.eta_c
    eta_hat = ws.eta_hat
    stress_mode_sum = 0.0
    for q in 1:qcount
        lambda = (q - 0.5) / qcount
        @inbounds for i in eachindex(phi)
            eta_c[i] = diblock_burp_eta_psi(ff + lambda * (phi[i] - ff), ff)
        end
        mul!(eta_hat, ws.plan, eta_c)
        stress_mode_sum += _burp_ti_mode_sum(psi_hat, stress_weights,
            eta_hat) / qcount
    end
    return -(2.0 / (scale * length(phi)^2)) * stress_mode_sum
end

"""
    DiblockBurpTiForceWorkspace1D(count)

Preallocated real/complex scratch buffers and reusable forward/inverse FFTW
plans for repeated `_diblock_burp_ti_chemical_potential_1d` evaluations on a
fixed grid size `count`. Reusing this workspace across every objective/
gradient evaluation of an outer optimizer avoids the per-quadrature-point
`fft`/`ifft` allocations of `_periodic_kernel_apply_1d`.
"""
struct DiblockBurpTiForceWorkspace1D{PF,PI}
    count::Int
    psi::Vector{Float64}
    phi_lambda::Vector{Float64}
    eta::Vector{Float64}
    kernel_psi::Vector{Float64}
    kernel_eta::Vector{Float64}
    field_c::Vector{ComplexF64}
    field_hat::Vector{ComplexF64}
    kernel_hat::Vector{ComplexF64}
    kernel_time::Vector{ComplexF64}
    fplan::PF
    iplan::PI
end

function DiblockBurpTiForceWorkspace1D(count::Integer)
    n = Int(count)
    n >= 2 || throw(ArgumentError("BURP-TI 1D force workspace requires at least two grid points"))
    dummy = zeros(ComplexF64, n)
    fplan = plan_fft(dummy)
    iplan = plan_ifft(dummy)
    return DiblockBurpTiForceWorkspace1D{typeof(fplan),typeof(iplan)}(n,
        zeros(Float64, n), zeros(Float64, n), zeros(Float64, n),
        zeros(Float64, n), zeros(Float64, n),
        zeros(ComplexF64, n), zeros(ComplexF64, n), zeros(ComplexF64, n),
        zeros(ComplexF64, n), fplan, iplan)
end

# In-place equivalent of `_periodic_kernel_apply_1d(values, k2_values, kern)`
# writing into a preallocated real output buffer `out` via the workspace's
# scratch arrays and reusable plans, allocation-free. Reproduces the exact
# same operation order (forward FFT; zero the DC bin; multiply modes
# 2:end by the kernel; inverse FFT; take the real part) as the array-
# allocating helper, so results are bit-identical.
function _burp_ti_kernel_apply_1d!(out::AbstractVector{Float64},
        values::AbstractVector{Float64}, kern::AbstractVector{<:Real},
        ws::DiblockBurpTiForceWorkspace1D)
    field_c = ws.field_c
    @inbounds for i in eachindex(values)
        field_c[i] = values[i]
    end
    mul!(ws.field_hat, ws.fplan, field_c)
    field_hat = ws.field_hat
    kernel_hat = ws.kernel_hat
    kernel_hat[1] = 0.0
    @inbounds for idx in 2:length(field_hat)
        kernel_hat[idx] = kern[idx] * field_hat[idx]
    end
    mul!(ws.kernel_time, ws.iplan, kernel_hat)
    kernel_time = ws.kernel_time
    @inbounds for i in eachindex(out)
        out[i] = real(kernel_time[i])
    end
    return out
end

function _diblock_burp_ti_chemical_potential_1d(phi_a::AbstractVector{Float64};
        f::Float64, chiN::Float64, L::Float64, N::Float64, b::Float64,
        nquad::Integer=16, composition_kernel=nothing, workspace=nothing)
    count = length(phi_a)
    qcount = Int(nquad)
    qcount >= 2 || throw(ArgumentError("nquad must be at least 2"))
    fb = 1.0 - f
    k2_values = _periodic_k2_1d(count, L)
    # Hoist the composition kernel out of the quadrature loop: it depends only
    # on k2_values, never on q or phi, so it is computed once per call (or
    # reused from a caller-supplied precomputed array) instead of once per
    # (q, mode) pair.
    kern = composition_kernel === nothing ?
        [diblock_composition_kernel(k2; f=f, N=N, b=b) for k2 in k2_values] :
        composition_kernel

    ws = workspace === nothing ? DiblockBurpTiForceWorkspace1D(count) : workspace
    ws.count == count ||
        throw(DimensionMismatch("workspace count $(ws.count) does not match phi length $(count)"))

    psi = ws.psi
    @inbounds for i in 1:count
        psi[i] = phi_a[i] - f
    end
    kernel_psi = ws.kernel_psi
    _burp_ti_kernel_apply_1d!(kernel_psi, psi, kern, ws)

    # `force` is the function's return value, so (unlike the scratch buffers
    # above) it is always a fresh allocation -- never an aliased workspace
    # field -- so callers reusing the same workspace across repeated calls
    # never see a previously returned result mutated out from under them.
    force = zeros(Float64, count)
    phi_lambda = ws.phi_lambda
    eta = ws.eta
    kernel_eta = ws.kernel_eta
    for q in 1:qcount
        lambda = (q - 0.5) / qcount
        @inbounds for i in 1:count
            phi_lambda[i] = f + lambda * psi[i]
            eta[i] = diblock_burp_eta_psi(phi_lambda[i], f)
        end
        _burp_ti_kernel_apply_1d!(kernel_eta, eta, kern, ws)
        @inbounds for idx in 1:count
            eta_prime = 0.5 * (f / phi_lambda[idx] + fb / (1.0 - phi_lambda[idx]))
            force[idx] += kernel_eta[idx] + lambda * eta_prime * kernel_psi[idx]
        end
    end
    force ./= qcount
    @. force += chiN * (1.0 - 2.0 * phi_a)
    return force
end

include("burp_ti_newton_gmres.jl")

function _diblock_profile_energy_inputs(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8, enforce_density_bounds::Bool=true)
    phi = Float64.(collect(phi_a))
    count = length(phi)
    count >= 8 || throw(ArgumentError("diblock profile energy requires at least eight grid points"))
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    # Allow phi to reach the box edges (pure/saturated domains) or overshoot by
    # a hair; the model evaluators use the xlogy entropy limit and floor the
    # divergent eta / entropy-derivative logs.  Reject only gross excursions.
    if enforce_density_bounds
        (minimum(phi) >= -1.0e-10 && maximum(phi) <= 1.0 + 1.0e-10) ||
            throw(DomainError((minimum(phi), maximum(phi)),
                "diblock phi_A overshoot exceeds 1e-10 past [0, 1]"))
    else
        all(isfinite, phi) || throw(DomainError(phi,
            "diblock order-parameter field must be finite"))
    end
    mean_error = abs(mean(phi) - ff)
    mean_error <= Float64(mean_tolerance) ||
        throw(ArgumentError("mean phi_A must match f within mean_tolerance"))
    period = Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)
    return phi, count, ff, chi, period, nn, bb
end

function _diblock_quadratic_energy_1d(phi_a::AbstractVector{<:Real}, kernel;
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, count, ff, chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    psi_hat = fft(phi .- ff)
    k2_values = _periodic_k2_1d(count, period)
    entropic = 0.0
    for idx in 2:count
        mode_kernel = kernel(k2_values[idx], ff, nn, bb)
        entropic += real(conj(psi_hat[idx]) * mode_kernel * psi_hat[idx])
    end
    dx = period / count
    entropic *= 0.5 * dx / count
    interaction = chi * dx * sum(value * (1.0 - value) - ff * (1.0 - ff) for value in phi)
    return entropic + interaction
end

function diblock_rpa_quadratic_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    return _diblock_quadratic_energy_1d(phi_a,
        (k2, ff, nn, bb) -> diblock_composition_kernel(k2; f=ff, N=nn, b=bb);
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
end

function _diblock_uneyama_doi_a_matrix(ff::Float64, nn::Float64, bb::Float64)
    fb = 1.0 - ff
    prefactor = 9.0 / (nn^2 * bb^2 * ff^2 * fb^2)
    return [
        prefactor*fb^2 -prefactor*ff*fb
        -prefactor*ff*fb prefactor*ff^2
    ]
end

function _diblock_uneyama_doi_c_matrix(ff::Float64, nn::Float64, bb::Float64)
    fb = 1.0 - ff
    a_matrix = _diblock_uneyama_doi_a_matrix(ff, nn, bb)
    q2_a = sqrt(12.0 * ff * a_matrix[1, 1] / bb^2)
    q2_b = sqrt(12.0 * fb * a_matrix[2, 2] / bb^2)
    g_a = inv(diblock_single_chain_h(q2_a; f=ff, N=nn, b=bb))
    g_b = inv(diblock_single_chain_h(q2_b; f=ff, N=nn, b=bb))
    c_aa = g_a[1, 1] - a_matrix[1, 1] / q2_a - bb^2 * q2_a / (12.0 * ff)
    c_bb = g_b[2, 2] - a_matrix[2, 2] / q2_b - bb^2 * q2_b / (12.0 * fb)
    c_ab = -1.0 / (4.0 * nn * ff * fb)
    return [c_aa c_ab; c_ab c_bb]
end

function diblock_uneyama_doi_coefficients(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    # The closed-form Uneyama--Doi matrices are raw per-segment vertices.
    # Reduced functionals use free energy per chain, so normalize the ideal
    # matrices by N before pairing them with the `chiN` interaction.
    a_matrix = nn .* _diblock_uneyama_doi_a_matrix(ff, nn, bb)
    c_matrix = nn .* _diblock_uneyama_doi_c_matrix(ff, nn, bb)
    common = nn * ff * (1.0 - ff)
    return (
        A=a_matrix,
        C=c_matrix,
        s_f=common * c_matrix[1, 1],
        s_one_minus_f=common * c_matrix[2, 2],
    )
end

function diblock_bvk1_eta_psi(phi_a::Real; f::Real=0.5)
    return diblock_burp_eta_psi(phi_a, f)
end

function diblock_bvk1_coefficients(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    direction = [1.0, -1.0]
    a_psi = dot(direction, coeffs.A * direction)
    c_psi = dot(direction, coeffs.C * direction)
    return (
        f=ff,
        N=nn,
        b=bb,
        A_psi=a_psi,
        C_psi=c_psi,
        M_psi=c_psi * ff * (1.0 - ff),
        K_psi0=nn * bb^2 / 24.0,
    )
end

"""
    diblock_uneyama_doi_composition_kernel(k2; f=0.5, N=1.0, b=1.0)

Return the constrained homogeneous Hessian of the literal nonlinear
Uneyama--Doi energy implemented by [`diblock_uneyama_doi_energy_1d`] and
[`diblock_uneyama_doi_energy_nd`], excluding the Flory contact interaction.
Under `phi_b = 1 - phi_a`, the square-root cross term contributes
`-C_ab / (f(1-f))`; consequently this Hessian is generally distinct from the
nominal BVK1 projected Gaussian kernel returned by
[`diblock_bvk1_gaussian_kernel`].
"""
function diblock_uneyama_doi_composition_kernel(k2::Real;
        f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, kk = _diblock_validate(f, N, b, k2)
    kk == 0.0 && return Inf
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    direction = [1.0, -1.0]
    a_psi = dot(direction, coeffs.A * direction)
    local_hessian = coeffs.C[1, 1] + coeffs.C[2, 2] -
        coeffs.C[1, 2] / (ff * (1.0 - ff))
    gradient = nn * bb^2 * kk / (12.0 * ff * (1.0 - ff))
    return a_psi / kk + local_hessian + gradient
end

"""
    diblock_bvk1_gaussian_kernel(k2; f=0.5, N=1.0, b=1.0)

Return the nominal reduced BVK1 Gaussian composition kernel
`A_psi/k2 + C_psi + b^2*k2/(12f(1-f))`, where `A_psi` and `C_psi` are the
direct projections of the BVK1 coefficient matrices along `(1, -1)`.
This nominal Gaussian kernel is not the homogeneous Hessian of the literal
nonlinear Uneyama--Doi square-root functional; use
[`diblock_uneyama_doi_composition_kernel`] for that Hessian.
"""
function diblock_bvk1_gaussian_kernel(k2::Real;
        f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, kk = _diblock_validate(f, N, b, k2)
    kk == 0.0 && return Inf
    coeffs = diblock_bvk1_coefficients(; f=ff, N=nn, b=bb)
    gradient = nn * bb^2 * kk / (12.0 * ff * (1.0 - ff))
    return coeffs.A_psi / kk + coeffs.C_psi + gradient
end

function diblock_burp_ti_gaussian_kernel(k2::Real;
        f::Real=0.5, N::Real=1.0, b::Real=1.0)
    return diblock_composition_kernel(k2; f=f, N=N, b=b)
end

function _periodic_inverse_laplacian_pair_integral_1d(
        left::AbstractVector{Float64}, right::AbstractVector{Float64},
        k2_values::AbstractVector{Float64}, dx::Float64)
    count = length(left)
    left_hat = fft(left)
    right_hat = fft(right)
    total = 0.0
    for idx in 2:count
        total += real(conj(left_hat[idx]) * right_hat[idx]) / k2_values[idx]
    end
    return dx * total / count
end

function _periodic_inverse_laplacian_pair_integral_nd(
        left::AbstractArray{Float64}, right::AbstractArray{Float64},
        k2_values::AbstractArray{Float64}, dV::Float64)
    size(left) == size(right) == size(k2_values) ||
        throw(DimensionMismatch("inverse-Laplacian inputs must have the same size"))
    left_hat = fft(left)
    right_hat = left === right ? left_hat : fft(right)
    total = 0.0
    for index in CartesianIndices(k2_values)
        k2 = k2_values[index]
        k2 == 0.0 && continue
        total += real(conj(left_hat[index]) * right_hat[index]) / k2
    end
    return dV * total / length(left)
end

function _periodic_gradient_square_integral_1d(
        values::AbstractVector{Float64}, k2_values::AbstractVector{Float64}, dx::Float64)
    count = length(values)
    values_hat = fft(values)
    total = 0.0
    for idx in 2:count
        total += k2_values[idx] * abs2(values_hat[idx])
    end
    return dx * total / count
end

function _periodic_gradient_square_integral_nd(
        values::AbstractArray{Float64}, k2_values::AbstractArray{Float64}, dV::Float64)
    size(values) == size(k2_values) ||
        throw(DimensionMismatch("gradient-square inputs must have the same size"))
    values_hat = fft(values)
    total = 0.0
    for index in CartesianIndices(k2_values)
        total += k2_values[index] * abs2(values_hat[index])
    end
    return dV * total / length(values)
end

function _periodic_inverse_laplacian_apply_1d(
        values::AbstractVector{Float64}, k2_values::AbstractVector{Float64})
    count = length(values)
    values_hat = fft(values)
    out_hat = zeros(ComplexF64, count)
    for idx in 2:count
        out_hat[idx] = values_hat[idx] / k2_values[idx]
    end
    return real.(ifft(out_hat))
end

function _periodic_inverse_laplacian_apply_nd(
        values::AbstractArray{Float64}, k2_values::AbstractArray{Float64})
    size(values) == size(k2_values) ||
        throw(DimensionMismatch("inverse-Laplacian inputs must have the same size"))
    values_hat = fft(values)
    out_hat = zeros(ComplexF64, size(values)...)
    for index in CartesianIndices(k2_values)
        k2 = k2_values[index]
        k2 == 0.0 && continue
        out_hat[index] = values_hat[index] / k2
    end
    return real.(ifft(out_hat))
end

function _periodic_laplacian_apply_1d(
        values::AbstractVector{Float64}, k2_values::AbstractVector{Float64})
    values_hat = fft(values)
    out_hat = similar(values_hat)
    for idx in eachindex(values_hat)
        out_hat[idx] = -k2_values[idx] * values_hat[idx]
    end
    return real.(ifft(out_hat))
end

function _periodic_laplacian_apply_nd(
        values::AbstractArray{Float64}, k2_values::AbstractArray{Float64})
    size(values) == size(k2_values) ||
        throw(DimensionMismatch("Laplacian inputs must have the same size"))
    values_hat = fft(values)
    out_hat = similar(values_hat)
    for index in CartesianIndices(k2_values)
        out_hat[index] = -k2_values[index] * values_hat[index]
    end
    return real.(ifft(out_hat))
end

function _diblock_relative_entropy(phi::Float64, f::Float64)
    fb = 1.0 - f
    # xlogy convention: the mixing entropy of a pure domain is finite
    # (0*log 0 = 0), so phi may reach 0 or 1 (or overshoot slightly) without
    # producing a NaN.  Unchanged for phi strictly inside (0, 1).
    term_a = phi <= 0.0 ? 0.0 : phi * log(phi / f)
    term_b = phi >= 1.0 ? 0.0 : (1.0 - phi) * log((1.0 - phi) / fb)
    return term_a + term_b
end

@inline function _periodic_shift_index(index::CartesianIndex{D},
        dims::NTuple{D,Int}, dim::Integer, step::Integer) where {D}
    coords = Tuple(index)
    axis = Int(dim)
    shifted = ntuple(Val(D)) do coordinate
        coordinate == axis ?
            mod1(coords[coordinate] + Int(step), dims[coordinate]) :
            coords[coordinate]
    end
    return CartesianIndex(shifted)
end

@inline function _diblock_bvk1_regularized_abs_pair(value::Real,
        smoothing::Real)
    x = Float64(value)
    epsilon = Float64(smoothing)
    if epsilon == 0.0
        derivative = x > 0.0 ? 1.0 : (x < 0.0 ? -1.0 : 0.0)
        return abs(x), derivative
    end
    radius = hypot(x, epsilon)
    # Subtracting epsilon keeps the regularized |x| term exactly zero at the
    # kink while retaining the same derivative as sqrt(x^2 + epsilon^2).
    return radius - epsilon, x / radius
end

function _diblock_bvk1_kpsi_1d(phi::AbstractVector{Float64}, f::Float64,
        period::Float64, N::Float64, b::Float64; adaptive::Bool=true,
        vk1_scale::Real=0.046, eta_floor::Real=1.0e-12,
        laplacian_smoothing::Real=0.0)
    count = length(phi)
    k0 = N * b^2 / 24.0
    !adaptive && return fill(k0, count)
    dx = period / count
    scale = N * Float64(vk1_scale)
    floor_value = Float64(eta_floor)
    smoothing = Float64(laplacian_smoothing)
    scale >= 0.0 && isfinite(scale) ||
        throw(ArgumentError("vk1_scale must be nonnegative and finite"))
    floor_value > 0.0 && isfinite(floor_value) ||
        throw(ArgumentError("eta_floor must be positive and finite"))
    smoothing >= 0.0 && isfinite(smoothing) ||
        throw(ArgumentError("laplacian_smoothing must be nonnegative and finite"))
    eta = [diblock_bvk1_eta_psi(value; f=f) for value in phi]
    out = Vector{Float64}(undef, count)
    for idx in 1:count
        left = idx == 1 ? count : idx - 1
        right = idx == count ? 1 : idx + 1
        grad = (eta[right] - eta[left]) / (2.0 * dx)
        lap = (eta[right] - 2.0 * eta[idx] + eta[left]) / dx^2
        denominator = max(abs(eta[idx]), floor_value)
        abs_lap, _ = _diblock_bvk1_regularized_abs_pair(lap, smoothing)
        g = scale * (2.0 * abs_lap / denominator + grad^2 / denominator^2)
        activation = tanh(eta[idx]^2 / (f * (1.0 - f)))
        out[idx] = k0 * (1.0 + 0.5 * activation * tanh(g))
    end
    return out
end

_diblock_bvk1_kpsi_1d(phi::AbstractVector{Float64}, f::Float64,
    period::Float64, b::Float64; kwargs...) =
    _diblock_bvk1_kpsi_1d(phi, f, period, 1.0, b; kwargs...)

function _diblock_bvk1_kpsi_nd(phi::AbstractArray{Float64}, f::Float64,
        lengths::AbstractVector{Float64}, N::Float64, b::Float64; adaptive::Bool=true,
        vk1_scale::Real=0.046, eta_floor::Real=1.0e-12,
        laplacian_smoothing::Real=0.0)
    dims = size(phi)
    k0 = N * b^2 / 24.0
    !adaptive && return fill(k0, dims)
    length(lengths) == length(dims) ||
        throw(ArgumentError("lengths must have one entry per array dimension"))
    spacings = [lengths[dim] / dims[dim] for dim in eachindex(dims)]
    scale = N * Float64(vk1_scale)
    floor_value = Float64(eta_floor)
    smoothing = Float64(laplacian_smoothing)
    scale >= 0.0 && isfinite(scale) ||
        throw(ArgumentError("vk1_scale must be nonnegative and finite"))
    floor_value > 0.0 && isfinite(floor_value) ||
        throw(ArgumentError("eta_floor must be positive and finite"))
    smoothing >= 0.0 && isfinite(smoothing) ||
        throw(ArgumentError("laplacian_smoothing must be nonnegative and finite"))
    eta = similar(phi)
    for index in CartesianIndices(phi)
        eta[index] = diblock_bvk1_eta_psi(phi[index]; f=f)
    end
    out = Array{Float64}(undef, dims)
    for index in CartesianIndices(phi)
        grad2 = 0.0
        lap = 0.0
        for dim in eachindex(dims)
            left = _periodic_shift_index(index, dims, dim, -1)
            right = _periodic_shift_index(index, dims, dim, 1)
            h = spacings[dim]
            derivative = (eta[right] - eta[left]) / (2.0 * h)
            grad2 += derivative^2
            lap += (eta[right] - 2.0 * eta[index] + eta[left]) / h^2
        end
        denominator = max(abs(eta[index]), floor_value)
        abs_lap, _ = _diblock_bvk1_regularized_abs_pair(lap, smoothing)
        g = scale * (2.0 * abs_lap / denominator + grad2 / denominator^2)
        activation = tanh(eta[index]^2 / (f * (1.0 - f)))
        out[index] = k0 * (1.0 + 0.5 * activation * tanh(g))
    end
    return out
end

_diblock_bvk1_kpsi_nd(phi::AbstractArray{Float64}, f::Float64,
    lengths::AbstractVector{Float64}, b::Float64; kwargs...) =
    _diblock_bvk1_kpsi_nd(phi, f, lengths, 1.0, b; kwargs...)

function diblock_bvk1_kpsi_profile_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        adaptive::Bool=true, vk1_scale::Real=0.046,
        laplacian_smoothing::Real=0.0, mean_tolerance::Real=1.0e-8)
    phi, _count, ff, _chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=0.0, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    return _diblock_bvk1_kpsi_1d(phi, ff, period, nn, bb; adaptive=adaptive,
        vk1_scale=vk1_scale, laplacian_smoothing=laplacian_smoothing)
end

function _diblock_bvk1_gradient_integral_1d(phi::AbstractVector{Float64},
        kpsi::AbstractVector{Float64}, dx::Float64; denominator_floor::Real=1.0e-12)
    count = length(phi)
    length(kpsi) == count || throw(DimensionMismatch("K_psi length must match phi"))
    floor_value = Float64(denominator_floor)
    floor_value > 0.0 && isfinite(floor_value) ||
        throw(ArgumentError("denominator_floor must be positive and finite"))
    total = 0.0
    for idx in 1:count
        right = idx == count ? 1 : idx + 1
        edge_phi = 0.5 * (phi[idx] + phi[right])
        denominator = max(edge_phi * (1.0 - edge_phi), floor_value)
        gradient = (phi[right] - phi[idx]) / dx
        edge_k = 0.5 * (kpsi[idx] + kpsi[right])
        total += dx * edge_k * gradient^2 / denominator
    end
    return total
end

function _diblock_bvk1_gradient_integral_nd(phi::AbstractArray{Float64},
        kpsi::AbstractArray{Float64}, lengths::AbstractVector{Float64}, dV::Float64;
        denominator_floor::Real=1.0e-12)
    dims = size(phi)
    size(kpsi) == dims || throw(DimensionMismatch("K_psi size must match phi"))
    length(lengths) == length(dims) ||
        throw(ArgumentError("lengths must have one entry per array dimension"))
    spacings = [lengths[dim] / dims[dim] for dim in eachindex(dims)]
    floor_value = Float64(denominator_floor)
    floor_value > 0.0 && isfinite(floor_value) ||
        throw(ArgumentError("denominator_floor must be positive and finite"))
    total = 0.0
    for index in CartesianIndices(phi)
        for dim in eachindex(dims)
            right = _periodic_shift_index(index, dims, dim, 1)
            edge_phi = 0.5 * (phi[index] + phi[right])
            denominator = max(edge_phi * (1.0 - edge_phi), floor_value)
            gradient = (phi[right] - phi[index]) / spacings[dim]
            edge_k = 0.5 * (kpsi[index] + kpsi[right])
            total += dV * edge_k * gradient^2 / denominator
        end
    end
    return total
end

function diblock_bvk1_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        adaptive::Bool=true, vk1_scale::Real=0.046,
        laplacian_smoothing::Real=0.0, mean_tolerance::Real=1.0e-8)
    phi, count, ff, chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    dx = period / count
    k2_values = _periodic_k2_1d(count, period)
    coeffs = diblock_bvk1_coefficients(; f=ff, N=nn, b=bb)
    psi = phi .- ff
    connectivity = 0.5 * coeffs.A_psi *
        _periodic_inverse_laplacian_pair_integral_1d(psi, psi, k2_values, dx)
    local_entropy = coeffs.M_psi * dx * sum(_diblock_relative_entropy(value, ff)
        for value in phi)
    kpsi = _diblock_bvk1_kpsi_1d(phi, ff, period, nn, bb; adaptive=adaptive,
        vk1_scale=vk1_scale, laplacian_smoothing=laplacian_smoothing)
    gradient = _diblock_bvk1_gradient_integral_1d(phi, kpsi, dx)
    interaction = chi * dx * sum(value * (1.0 - value) - ff * (1.0 - ff)
        for value in phi)
    return connectivity + local_entropy + gradient + interaction
end

function diblock_bvk1_energy_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        adaptive::Bool=true, vk1_scale::Real=0.046,
        laplacian_smoothing::Real=0.0, mean_tolerance::Real=1.0e-8)
    phi, dims, ff, chi, cell_lengths, nn, bb, dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    k2_values = _periodic_k2_nd(dims, cell_lengths)
    coeffs = diblock_bvk1_coefficients(; f=ff, N=nn, b=bb)
    psi = phi .- ff
    connectivity = 0.5 * coeffs.A_psi *
        _periodic_inverse_laplacian_pair_integral_nd(psi, psi, k2_values, dV)
    local_entropy = coeffs.M_psi * dV * sum(_diblock_relative_entropy(value, ff)
        for value in phi)
    kpsi = _diblock_bvk1_kpsi_nd(phi, ff, cell_lengths, nn, bb; adaptive=adaptive,
        vk1_scale=vk1_scale, laplacian_smoothing=laplacian_smoothing)
    gradient = _diblock_bvk1_gradient_integral_nd(phi, kpsi, cell_lengths, dV)
    interaction = chi * dV * sum(value * (1.0 - value) - ff * (1.0 - ff)
        for value in phi)
    return connectivity + local_entropy + gradient + interaction
end

# ---------------------------------------------------------------------------
# ABA triblock BVK1 / Uneyama–Doi (Case A). BVK1 approximates the exact
# composition kernel by its asymptotics Γ_ψ ≈ A_ψ/k² + C_ψ + b²k²/[12 f(1-f)].
# Architecture enters through the small-k coefficients A_ψ, C_ψ only; the
# large-k gradient term is architecture-independent for fixed chemical
# fractions (the local Debye tail gives H⁻¹ → (b²k²/12)·diag(1/f_A, 1/f_B)
# for any topology). See docs/burp_ti_bvk1_arbitrary_architecture.md §3.2.
#
# A matrix (small-k 1/k² coefficient of H⁻¹): the general null-space formula
#   A = w wᵀ / (wᵀ H₁ w),  w = (f_B, -f_A) ∈ ker H(0),  H₁ = dH/dk²|₀,
# which reproduces the diblock A matrix exactly. C matrix: the Uneyama–Doi
# crossover-matching — diagonal matched at the per-species crossover
# wavevector using the ABA H, off-diagonal the chemistry-only closed form
# -1/(4 N f_A f_B). Every piece uses the ABA correlation and reduces to the
# diblock construction as fa2 → 0.
# ---------------------------------------------------------------------------
function _triblock_aba_ud_coefficients(fa1::Real, fb::Real, fa2::Real,
        nn::Float64, bb::Float64)
    fA = fa1 + fa2
    hfun(s) = _triblock_aba_single_chain_h(s, fa1, fb, fa2, nn, bb)
    h1 = ForwardDiff.derivative(hfun, 0.0)          # H₁ = dH/dk²|₀
    w = [fb, -fA]                                     # ker H(0) = N f_chem f_chemᵀ
    a_matrix = (w * transpose(w)) / dot(w, h1 * w)
    q2_a = sqrt(12.0 * fA * a_matrix[1, 1] / bb^2)    # per-species crossover k²
    q2_b = sqrt(12.0 * fb * a_matrix[2, 2] / bb^2)
    g_a = inv(hfun(q2_a))
    g_b = inv(hfun(q2_b))
    c_aa = g_a[1, 1] - a_matrix[1, 1] / q2_a - bb^2 * q2_a / (12.0 * fA)
    c_bb = g_b[2, 2] - a_matrix[2, 2] / q2_b - bb^2 * q2_b / (12.0 * fb)
    c_ab = -1.0 / (4.0 * nn * fA * fb)
    c_matrix = [c_aa c_ab; c_ab c_bb]
    common = nn * fA * fb
    return (A=a_matrix, C=c_matrix,
        s_f=common * c_matrix[1, 1], s_one_minus_f=common * c_matrix[2, 2])
end

"""
    triblock_aba_uneyama_doi_coefficients(; f=0.5, N=1.0, b=1.0)

Uneyama–Doi A/C matrices for the symmetric ABA triblock. Analogue of
[`diblock_uneyama_doi_coefficients`]; the diblock is the `fa2 → 0` limit.
"""
function triblock_aba_uneyama_doi_coefficients(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    raw = _triblock_aba_ud_coefficients(ff / 2.0, 1.0 - ff, ff / 2.0, nn, bb)
    return merge(raw, (A=nn .* raw.A, C=nn .* raw.C,
        s_f=nn * raw.s_f, s_one_minus_f=nn * raw.s_one_minus_f))
end

"""
    triblock_aba_bvk1_coefficients(; f=0.5, N=1.0, b=1.0)

Projected BVK1 coefficients `(A_ψ, C_ψ, M_ψ, K_ψ0)` for the symmetric ABA
triblock. Analogue of [`diblock_bvk1_coefficients`].
"""
function triblock_aba_bvk1_coefficients(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    coeffs = triblock_aba_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    direction = [1.0, -1.0]
    a_psi = dot(direction, coeffs.A * direction)
    c_psi = dot(direction, coeffs.C * direction)
    return (f=ff, N=nn, b=bb, A_psi=a_psi, C_psi=c_psi,
        M_psi=c_psi * ff * (1.0 - ff), K_psi0=nn * bb^2 / 24.0)
end

"""
    triblock_aba_bvk1_gaussian_kernel(k2; f=0.5, N=1.0, b=1.0)

BVK1 nominal Gaussian composition kernel
`A_ψ/k² + C_ψ + b²k²/[12 f(1-f)]` for the symmetric ABA triblock. This is the
architecture-specific analogue of [`diblock_bvk1_gaussian_kernel`] and returns
`Inf` at `k2 = 0`.
"""
function triblock_aba_bvk1_gaussian_kernel(k2::Real;
        f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, kk = _diblock_validate(f, N, b, k2)
    kk == 0.0 && return Inf
    coeffs = triblock_aba_bvk1_coefficients(; f=ff, N=nn, b=bb)
    gradient = nn * bb^2 * kk / (12.0 * ff * (1.0 - ff))
    return coeffs.A_psi / kk + coeffs.C_psi + gradient
end

"""
    triblock_aba_uneyama_doi_composition_kernel(k2; f=0.5, N=1.0, b=1.0)

Legacy name for [`triblock_aba_bvk1_gaussian_kernel`]. No literal nonlinear
ABA Uneyama--Doi energy is implemented, so this name must not be interpreted
as the Hessian of such a functional.
"""
function triblock_aba_uneyama_doi_composition_kernel(k2::Real;
        f::Real=0.5, N::Real=1.0,
        b::Real=1.0)
    return triblock_aba_bvk1_gaussian_kernel(k2; f=f, N=N, b=b)
end

"""
    triblock_aba_bvk1_energy_1d(phi_a; f, chiN, L, ...)
    triblock_aba_bvk1_energy_nd(phi_a; f, chiN, lengths, ...)

BVK1 free energy for the symmetric ABA triblock: the same connectivity /
local-entropy / adaptive-gradient / interaction decomposition as
[`diblock_bvk1_energy_1d`] / [`diblock_bvk1_energy_nd`], built from the ABA
BVK1 coefficients (A_ψ, M_ψ). The adaptive gradient (kpsi) machinery is
architecture-independent.
"""
function triblock_aba_bvk1_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        adaptive::Bool=true, vk1_scale::Real=0.046,
        laplacian_smoothing::Real=0.0, mean_tolerance::Real=1.0e-8)
    phi, count, ff, chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    dx = period / count
    k2_values = _periodic_k2_1d(count, period)
    coeffs = triblock_aba_bvk1_coefficients(; f=ff, N=nn, b=bb)
    psi = phi .- ff
    connectivity = 0.5 * coeffs.A_psi *
        _periodic_inverse_laplacian_pair_integral_1d(psi, psi, k2_values, dx)
    local_entropy = coeffs.M_psi * dx * sum(_diblock_relative_entropy(value, ff)
        for value in phi)
    kpsi = _diblock_bvk1_kpsi_1d(phi, ff, period, nn, bb; adaptive=adaptive,
        vk1_scale=vk1_scale, laplacian_smoothing=laplacian_smoothing)
    gradient = _diblock_bvk1_gradient_integral_1d(phi, kpsi, dx)
    interaction = chi * dx * sum(value * (1.0 - value) - ff * (1.0 - ff)
        for value in phi)
    return connectivity + local_entropy + gradient + interaction
end

function triblock_aba_bvk1_energy_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        adaptive::Bool=true, vk1_scale::Real=0.046,
        laplacian_smoothing::Real=0.0, mean_tolerance::Real=1.0e-8)
    phi, dims, ff, chi, cell_lengths, nn, bb, dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    k2_values = _periodic_k2_nd(dims, cell_lengths)
    coeffs = triblock_aba_bvk1_coefficients(; f=ff, N=nn, b=bb)
    psi = phi .- ff
    connectivity = 0.5 * coeffs.A_psi *
        _periodic_inverse_laplacian_pair_integral_nd(psi, psi, k2_values, dV)
    local_entropy = coeffs.M_psi * dV * sum(_diblock_relative_entropy(value, ff)
        for value in phi)
    kpsi = _diblock_bvk1_kpsi_nd(phi, ff, cell_lengths, nn, bb; adaptive=adaptive,
        vk1_scale=vk1_scale, laplacian_smoothing=laplacian_smoothing)
    gradient = _diblock_bvk1_gradient_integral_nd(phi, kpsi, cell_lengths, dV)
    interaction = chi * dV * sum(value * (1.0 - value) - ff * (1.0 - ff)
        for value in phi)
    return connectivity + local_entropy + gradient + interaction
end

function _diblock_uneyama_doi_energy_raw_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, count, ff, _chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    fb = 1.0 - ff
    chi = Float64(chiN)
    dx = period / count
    k2_values = _periodic_k2_1d(count, period)
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    a_matrix = coeffs.A
    c_matrix = coeffs.C

    psi_a = sqrt.(phi)
    psi_b = sqrt.(1.0 .- phi)
    psi = (psi_a, psi_b)
    fractions = (ff, fb)

    long_range = 0.0
    for i in 1:2, j in 1:2
        long_range += 2.0 * sqrt(fractions[i] * fractions[j]) * a_matrix[i, j] *
            _periodic_inverse_laplacian_pair_integral_1d(psi[i], psi[j], k2_values, dx)
    end

    local_entropy = dx * sum(
        2.0 * ff * c_matrix[1, 1] * psi_a[idx]^2 * log(psi_a[idx]) +
        2.0 * fb * c_matrix[2, 2] * psi_b[idx]^2 * log(psi_b[idx]) +
        4.0 * sqrt(ff * fb) * c_matrix[1, 2] * psi_a[idx] * psi_b[idx]
        for idx in 1:count)
    gradient = nn * bb^2 / 6.0 * (
        _periodic_gradient_square_integral_1d(psi_a, k2_values, dx) +
        _periodic_gradient_square_integral_1d(psi_b, k2_values, dx))
    interaction = chi * dx * sum(value * (1.0 - value) for value in phi)
    return long_range + local_entropy + gradient + interaction
end

function diblock_uneyama_doi_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, count, ff, _chi, period, nn, bb = _diblock_profile_energy_inputs(phi_a;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
    energy = _diblock_uneyama_doi_energy_raw_1d(phi; f=ff, chiN=chiN, L=period,
        N=nn, b=bb, mean_tolerance=mean_tolerance)
    homogeneous = _diblock_uneyama_doi_energy_raw_1d(fill(ff, count); f=ff,
        chiN=chiN, L=period, N=nn, b=bb, mean_tolerance=mean_tolerance)
    return energy - homogeneous
end

"""
    diblock_uneyama_doi_cell_scale_gradient_density_1d(phi_a;
        f, chiN, L, N=1, b=1)

Return the analytic frozen-profile derivative of the original one-dimensional
Uneyama--Doi excess free-energy density with respect to the cell length `L`.
The density samples are held fixed in fractional cell coordinates:

```
d/dL [diblock_uneyama_doi_energy_1d(phi_a; L=L) / L].
```

Only the spectral inverse-Laplacian and gradient densities depend explicitly
on `L`.  Their wave numbers scale as `k^2 ~ L^-2`, so their derivatives are
respectively `2/L` and `-2/L` times the corresponding density.  Local entropy,
contact interaction, and the homogeneous reference have zero derivative after
division by `L`.

At a converged fixed-composition profile this frozen-profile derivative is the
cell-stationarity condition by the envelope theorem.  Away from field
stationarity it remains the exact explicit derivative of the implemented
spectral functional, but is only a diagnostic cell stress.
"""
function diblock_uneyama_doi_cell_scale_gradient_density_1d(
        phi_a::AbstractVector{<:Real}; f::Real=0.5, chiN::Real=12.0,
        L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, count, ff, _chi, period, nn, bb =
        _diblock_profile_energy_inputs(phi_a; f=f, chiN=chiN, L=L, N=N,
            b=b, mean_tolerance=mean_tolerance)
    fb = 1.0 - ff
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    k2_values = _periodic_k2_1d(count, period)
    psi_a_hat = fft(sqrt.(phi))
    psi_b_hat = fft(sqrt.(1.0 .- phi))

    long_range_mode_sum = 0.0
    gradient_mode_sum = 0.0
    root_fraction_product = sqrt(ff * fb)
    @inbounds for index in 2:count
        a_hat = psi_a_hat[index]
        b_hat = psi_b_hat[index]
        long_range_mode_sum += (
            2.0 * ff * coeffs.A[1, 1] * abs2(a_hat) +
            4.0 * root_fraction_product * coeffs.A[1, 2] *
                real(conj(a_hat) * b_hat) +
            2.0 * fb * coeffs.A[2, 2] * abs2(b_hat)
        ) / k2_values[index]
        gradient_mode_sum +=
            k2_values[index] * (abs2(a_hat) + abs2(b_hat))
    end

    inverse_count_squared = inv(Float64(count)^2)
    long_range_density = inverse_count_squared * long_range_mode_sum
    gradient_density = nn * bb^2 / 6.0 * inverse_count_squared * gradient_mode_sum
    return 2.0 * (long_range_density - gradient_density) / period
end

function _diblock_uneyama_doi_energy_raw_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, dims, ff, _chi, cell_lengths, nn, bb, dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    fb = 1.0 - ff
    chi = Float64(chiN)
    k2_values = _periodic_k2_nd(dims, cell_lengths)
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    a_matrix = coeffs.A
    c_matrix = coeffs.C

    psi_a = sqrt.(phi)
    psi_b = sqrt.(1.0 .- phi)
    psi = (psi_a, psi_b)
    fractions = (ff, fb)

    long_range = 0.0
    for i in 1:2, j in 1:2
        long_range += 2.0 * sqrt(fractions[i] * fractions[j]) * a_matrix[i, j] *
            _periodic_inverse_laplacian_pair_integral_nd(psi[i], psi[j],
                k2_values, dV)
    end

    local_entropy = dV * sum(
        2.0 * ff * c_matrix[1, 1] * psi_a[index]^2 * log(psi_a[index]) +
        2.0 * fb * c_matrix[2, 2] * psi_b[index]^2 * log(psi_b[index]) +
        4.0 * sqrt(ff * fb) * c_matrix[1, 2] * psi_a[index] * psi_b[index]
        for index in CartesianIndices(phi))
    gradient = nn * bb^2 / 6.0 * (
        _periodic_gradient_square_integral_nd(psi_a, k2_values, dV) +
        _periodic_gradient_square_integral_nd(psi_b, k2_values, dV))
    interaction = chi * dV * sum(value * (1.0 - value) for value in phi)
    return long_range + local_entropy + gradient + interaction
end

function diblock_uneyama_doi_energy_nd(phi_a::AbstractArray{<:Real};
        f::Real=0.5, chiN::Real=12.0, lengths=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    phi, dims, ff, _chi, cell_lengths, nn, bb, _dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b, mean_tolerance=mean_tolerance)
    energy = _diblock_uneyama_doi_energy_raw_nd(phi; f=ff, chiN=chiN,
        lengths=cell_lengths, N=nn, b=bb, mean_tolerance=mean_tolerance)
    homogeneous = _diblock_uneyama_doi_energy_raw_nd(fill(ff, dims);
        f=ff, chiN=chiN, lengths=cell_lengths, N=nn, b=bb,
        mean_tolerance=mean_tolerance)
    return energy - homogeneous
end

function _diblock_ohta_kawasaki_coefficients(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    k2_star = _diblock_kernel_minimum_k2(; f=ff, N=nn, b=bb)
    step = max(1.0e-4 * k2_star, 1.0e-7)
    left = max(k2_star - step, 0.5 * k2_star)
    right = k2_star + step
    center_value = diblock_composition_kernel(k2_star; f=ff, N=nn, b=bb)
    curvature = (
        diblock_composition_kernel(right; f=ff, N=nn, b=bb) -
        2.0 * center_value +
        diblock_composition_kernel(left; f=ff, N=nn, b=bb)
    ) / ((0.5 * (right - left))^2)
    if !isfinite(curvature) || curvature <= 0.0
        wider = 1.0e-2 * k2_star
        left = max(k2_star - wider, 0.5 * k2_star)
        right = k2_star + wider
        curvature = (
            diblock_composition_kernel(right; f=ff, N=nn, b=bb) -
            2.0 * center_value +
            diblock_composition_kernel(left; f=ff, N=nn, b=bb)
        ) / ((0.5 * (right - left))^2)
    end
    curvature > 0.0 || throw(ArgumentError("Ohta-Kawasaki kernel fit needs positive RPA curvature"))
    k2_coefficient = 0.5 * k2_star * curvature
    inverse_k2_coefficient = k2_coefficient * k2_star^2
    constant = center_value - 2.0 * k2_coefficient * k2_star
    return (
        k2_coefficient=k2_coefficient,
        inverse_k2_coefficient=inverse_k2_coefficient,
        constant=constant,
        k2_star=k2_star,
    )
end

"""
    diblock_ohta_kawasaki_kernel(k2; f=0.5, N=1, b=1)

Return the diagnostic local surrogate fitted to the value, position, and
curvature of the RPA minimum. This historical helper is not the published
Liu-2019 Ohta--Kawasaki comparator; use
`diblock_liu2019_ok_gaussian_kernel` for that model.
"""
function diblock_ohta_kawasaki_kernel(k2::Real; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    kk = Float64(k2)
    kk < 0.0 && throw(ArgumentError("k2 must be nonnegative"))
    kk == 0.0 && return Inf
    coeffs = _diblock_ohta_kawasaki_coefficients(; f=f, N=N, b=b)
    return coeffs.k2_coefficient * kk + coeffs.inverse_k2_coefficient / kk +
        coeffs.constant
end

function diblock_ohta_kawasaki_energy_1d(phi_a::AbstractVector{<:Real};
        f::Real=0.5, chiN::Real=12.0, L::Real=1.0, N::Real=1.0, b::Real=1.0,
        mean_tolerance::Real=1.0e-8)
    coeffs = _diblock_ohta_kawasaki_coefficients(; f=f, N=N, b=b)
    return _diblock_quadratic_energy_1d(phi_a,
        (k2, _ff, _nn, _bb) -> coeffs.k2_coefficient * k2 +
            coeffs.inverse_k2_coefficient / k2 + coeffs.constant;
        f=f, chiN=chiN, L=L, N=N, b=b, mean_tolerance=mean_tolerance)
end

function _diblock_ohta_kawasaki_chemical_potential_1d(phi_a::AbstractVector{Float64};
        f::Float64, chiN::Float64, L::Float64, N::Float64, b::Float64)
    coeffs = _diblock_ohta_kawasaki_coefficients(; f=f, N=N, b=b)
    k2_values = _periodic_k2_1d(length(phi_a), L)
    kernel(k2) = coeffs.k2_coefficient * k2 + coeffs.inverse_k2_coefficient / k2 +
        coeffs.constant
    force = _periodic_kernel_apply_1d(phi_a .- f, k2_values, kernel)
    @. force += chiN * (1.0 - 2.0 * phi_a)
    return force
end

function _diblock_kernel_minimum_k2(; f::Real=0.5, N::Real=1.0, b::Real=1.0)
    objective(log_k2) = diblock_composition_kernel(exp(log_k2); f=f, N=N, b=b)
    result = Optim.optimize(objective, log(1.0e-6), log(1.0e6), Optim.GoldenSection())
    return exp(Optim.minimizer(result))
end

function _minimize_diblock_lamella_model(energy_function; f::Real=0.5, chiN::Real=12.0,
        L=nothing, nx::Integer=128, mode_count::Integer=3, initial_amplitude::Real=0.2,
        N::Real=1.0, b::Real=1.0, nquad=nothing, max_iterations::Integer=2_000,
        kwargs...)
    modes = Int(mode_count)
    modes >= 1 || throw(ArgumentError("mode_count must be positive"))
    count = Int(nx)
    count >= 8 || throw(ArgumentError("nx must be at least 8"))
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    period = L === nothing ? 2.0 * pi / sqrt(_diblock_kernel_minimum_k2(; f=ff, N=nn, b=bb)) :
        Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))
    initial = zeros(Float64, modes)
    initial[1] = Float64(initial_amplitude)

    function model_energy(phi)
        if nquad === nothing
            return energy_function(phi; f=ff, chiN=chi, L=period, N=nn, b=bb,
                kwargs...)
        end
        return energy_function(phi; f=ff, chiN=chi, L=period, N=nn, b=bb,
            nquad=Int(nquad), kwargs...)
    end
    objective(coeffs) = begin
        _, phi = diblock_lamella_profile_from_modes(coeffs; f=ff, nx=count, L=period)
        return model_energy(phi)
    end
    result = Optim.optimize(objective, initial, Optim.NelderMead(),
        Optim.Options(iterations=Int(max_iterations), f_reltol=1.0e-10,
            x_abstol=1.0e-10))
    coeffs = Vector{Float64}(Optim.minimizer(result))
    x, phi = diblock_lamella_profile_from_modes(coeffs; f=ff, nx=count, L=period)
    energy = model_energy(phi)
    homogeneous = model_energy(fill(ff, count))
    return DiblockBurpLamellaResult(ff, chi, period, count, modes, x, phi, coeffs,
        energy, homogeneous, Optim.converged(result), Optim.iterations(result),
        minimum(phi), maximum(phi), mean(phi), NaN, NaN)
end

function minimize_diblock_bvk1_lamella(; f::Real=0.5, chiN::Real=12.0,
        L=nothing, nx::Integer=128, mode_count::Integer=3, initial_amplitude::Real=0.2,
        N::Real=1.0, b::Real=1.0, adaptive::Bool=true, vk1_scale::Real=0.046,
        max_iterations::Integer=10_000)
    return _minimize_diblock_lamella_model(diblock_bvk1_energy_1d; f=f,
        chiN=chiN, L=L, nx=nx, mode_count=mode_count,
        initial_amplitude=initial_amplitude, N=N, b=b, adaptive=adaptive,
        vk1_scale=vk1_scale, max_iterations=max_iterations)
end

function minimize_diblock_burp_lamella(; f::Real=0.5, chiN::Real=12.0,
        L=nothing, nx::Integer=128, mode_count::Integer=3, initial_amplitude::Real=0.2,
        N::Real=1.0, b::Real=1.0, nquad::Integer=16, max_iterations::Integer=10_000,
        relaxation_step::Real=1.0e-2, tolerance::Real=1.0e-8,
        gradient_tolerance::Real=5.0e-4)
    return _minimize_diblock_relaxed_lamella(diblock_burp_ti_energy_1d,
        _diblock_burp_ti_chemical_potential_1d; f=f, chiN=chiN, L=L, nx=nx,
        mode_count=mode_count, initial_amplitude=initial_amplitude, N=N, b=b,
        nquad=nquad, max_iterations=max_iterations, relaxation_step=relaxation_step,
        tolerance=tolerance, gradient_tolerance=gradient_tolerance)
end

function _project_diblock_theta_mean!(theta::Vector{Float64}, f::Float64)
    epsilon = 1.0e-10
    function logit_correct!()
        phi = cos.(theta).^2
        @. phi = clamp(phi, epsilon, 1.0 - epsilon)
        logits = log.(phi ./ (1.0 .- phi))
        shift = _diblock_logit_shift(logits, f)
        @. phi = _logistic_stable(shift + logits)
        @. theta = acos(sqrt(clamp(phi, epsilon, 1.0 - epsilon)))
        return theta
    end
    lo = -maximum(theta) + epsilon
    hi = (0.5 * pi - epsilon) - minimum(theta)
    mean_phi(shift) = mean(cos(value + shift)^2 for value in theta)
    if mean_phi(lo) < f || mean_phi(hi) > f
        return logit_correct!()
    end
    # g(shift) = mean(cos^2(theta+shift)) - f is smooth and, on this bracket
    # (every theta+shift stays in (0, pi/2) where cos^2 is monotone), strictly
    # decreasing, so a safeguarded Newton iteration (analytic derivative
    # mean(-sin(2(theta+shift)))) converges in a handful of steps versus the old
    # fixed 120-step bisection.
    shift = 0.5 * (lo + hi)
    theta_count = length(theta)
    for _ in 1:80
        g = 0.0
        gp = 0.0
        @inbounds for value in theta
            a = value + shift
            c = cos(a)
            g += c * c
            gp += -sin(2.0 * a)
        end
        g = g / theta_count - f
        gp = gp / theta_count
        if g > 0.0                       # mean too high -> larger shift needed
            lo = shift
        else
            hi = shift
        end
        abs(g) <= 1.0e-13 && break
        st = gp != 0.0 ? g / gp : 0.0
        shift_new = shift - st
        if st == 0.0 || !(lo < shift_new < hi)
            shift_new = 0.5 * (lo + hi)   # Newton left the bracket -> bisect
        end
        converged = abs(shift_new - shift) <= 1.0e-15 * (abs(shift) + 1.0)
        shift = shift_new
        converged && break
    end
    @. theta = clamp(theta + shift, epsilon, 0.5 * pi - epsilon)
    abs(mean(cos.(theta).^2) - f) > 1.0e-12 && logit_correct!()
    return theta
end

function _diblock_theta_gradient_projection(theta::AbstractVector{Float64},
        mu_a::AbstractVector{Float64}, mu_b::AbstractVector{Float64})
    length(theta) == length(mu_a) == length(mu_b) ||
        throw(ArgumentError("theta and chemical-potential vectors must match"))
    psi_a = cos.(theta)
    psi_b = sin.(theta)
    gradient = @. -mu_a * psi_b + mu_b * psi_a
    constraint_gradient = @. -2.0 * psi_a * psi_b
    denom = dot(constraint_gradient, constraint_gradient)
    if denom <= eps(Float64)
        return gradient, copy(gradient)
    end
    projected = gradient .- (dot(gradient, constraint_gradient) / denom) .*
        constraint_gradient
    return gradient, projected
end

function _diblock_descent_direction_symbol(direction)
    symbol = Symbol(direction)
    symbol in (:raw, :projected) ||
        throw(ArgumentError("descent_direction must be :raw or :projected"))
    return symbol
end

function _diblock_uneyama_doi_chemical_potentials_1d(phi_a::AbstractVector{Float64};
        f::Float64, chiN::Float64, L::Float64, N::Float64, b::Float64)
    count = length(phi_a)
    fb = 1.0 - f
    chi = chiN
    k2_values = _periodic_k2_1d(count, L)
    coeffs = diblock_uneyama_doi_coefficients(; f=f, N=N, b=b)
    a_matrix = coeffs.A
    c_matrix = coeffs.C
    psi_a = sqrt.(phi_a)
    psi_b = sqrt.(1.0 .- phi_a)
    green_a = _periodic_inverse_laplacian_apply_1d(psi_a, k2_values)
    green_b = _periodic_inverse_laplacian_apply_1d(psi_b, k2_values)
    lap_a = _periodic_laplacian_apply_1d(psi_a, k2_values)
    lap_b = _periodic_laplacian_apply_1d(psi_b, k2_values)

    mu_a = Vector{Float64}(undef, count)
    mu_b = Vector{Float64}(undef, count)
    for idx in 1:count
        mu_a[idx] =
            4.0 * f * a_matrix[1, 1] * green_a[idx] +
            4.0 * sqrt(f * fb) * a_matrix[1, 2] * green_b[idx] +
            2.0 * f * c_matrix[1, 1] * (2.0 * psi_a[idx] * log(psi_a[idx]) + psi_a[idx]) +
            4.0 * sqrt(f * fb) * c_matrix[1, 2] * psi_b[idx] -
            N * b^2 / 3.0 * lap_a[idx] +
            2.0 * chi * psi_a[idx] * psi_b[idx]^2
        mu_b[idx] =
            4.0 * sqrt(f * fb) * a_matrix[2, 1] * green_a[idx] +
            4.0 * fb * a_matrix[2, 2] * green_b[idx] +
            2.0 * fb * c_matrix[2, 2] * (2.0 * psi_b[idx] * log(psi_b[idx]) + psi_b[idx]) +
            4.0 * sqrt(f * fb) * c_matrix[2, 1] * psi_a[idx] -
            N * b^2 / 3.0 * lap_b[idx] +
            2.0 * chi * psi_b[idx] * psi_a[idx]^2
    end
    return mu_a, mu_b
end

function _diblock_uneyama_doi_chemical_potentials_nd(phi_a::AbstractArray{Float64};
        f::Float64, chiN::Float64, lengths, N::Float64, b::Float64)
    phi, dims, ff, _chi, cell_lengths, nn, bb, _dV =
        _diblock_profile_energy_inputs_nd(phi_a; f=f, chiN=chiN,
            lengths=lengths, N=N, b=b)
    fb = 1.0 - ff
    chi = Float64(chiN)
    k2_values = _periodic_k2_nd(dims, cell_lengths)
    coeffs = diblock_uneyama_doi_coefficients(; f=ff, N=nn, b=bb)
    a_matrix = coeffs.A
    c_matrix = coeffs.C
    psi_a = sqrt.(phi)
    psi_b = sqrt.(1.0 .- phi)
    green_a = _periodic_inverse_laplacian_apply_nd(psi_a, k2_values)
    green_b = _periodic_inverse_laplacian_apply_nd(psi_b, k2_values)
    lap_a = _periodic_laplacian_apply_nd(psi_a, k2_values)
    lap_b = _periodic_laplacian_apply_nd(psi_b, k2_values)

    mu_a = Array{Float64}(undef, dims...)
    mu_b = Array{Float64}(undef, dims...)
    for index in CartesianIndices(phi)
        mu_a[index] =
            4.0 * ff * a_matrix[1, 1] * green_a[index] +
            4.0 * sqrt(ff * fb) * a_matrix[1, 2] * green_b[index] +
            2.0 * ff * c_matrix[1, 1] *
                (2.0 * psi_a[index] * log(psi_a[index]) + psi_a[index]) +
            4.0 * sqrt(ff * fb) * c_matrix[1, 2] * psi_b[index] -
            nn * bb^2 / 3.0 * lap_a[index] +
            2.0 * chi * psi_a[index] * psi_b[index]^2
        mu_b[index] =
            4.0 * sqrt(ff * fb) * a_matrix[2, 1] * green_a[index] +
            4.0 * fb * a_matrix[2, 2] * green_b[index] +
            2.0 * fb * c_matrix[2, 2] *
                (2.0 * psi_b[index] * log(psi_b[index]) + psi_b[index]) +
            4.0 * sqrt(ff * fb) * c_matrix[2, 1] * psi_a[index] -
            nn * bb^2 / 3.0 * lap_b[index] +
            2.0 * chi * psi_b[index] * psi_a[index]^2
    end
    return mu_a, mu_b
end

function relax_diblock_uneyama_doi_morphology_seed_nd(morphology; f::Real=0.5,
        chiN::Real=20.0, dims=(16, 16), lengths=1.0, initial_amplitude::Real=1.0,
        N::Real=1.0, b::Real=1.0, max_iterations::Integer=20,
        relaxation_step::Real=1.0e-2, backtracking_steps::Integer=30,
        tolerance::Real=1.0e-8, descent_direction=:raw, initial_theta=nothing)
    kind = _diblock_morphology_symbol(morphology)
    direction = _diblock_descent_direction_symbol(descent_direction)
    grid_dims = _diblock_morphology_dims(dims)
    cell_lengths = _diblock_nd_lengths(lengths, grid_dims)
    ff = Float64(f)
    0.0 < ff < 1.0 || throw(ArgumentError("diblock fraction f must be in (0, 1)"))
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    nn = Float64(N)
    bb = Float64(b)
    _, nn, bb, _ = _diblock_validate(ff, nn, bb, 1.0)
    iterations = Int(max_iterations)
    iterations >= 0 || throw(ArgumentError("max_iterations must be nonnegative"))
    step = Float64(relaxation_step)
    step > 0.0 && isfinite(step) ||
        throw(ArgumentError("relaxation_step must be positive and finite"))
    backtracks = Int(backtracking_steps)
    backtracks > 0 || throw(ArgumentError("backtracking_steps must be positive"))
    tol = Float64(tolerance)
    tol > 0.0 && isfinite(tol) ||
        throw(ArgumentError("tolerance must be positive and finite"))

    initial_source = initial_theta === nothing ? "seed" : "theta"
    theta = if initial_theta === nothing
        initial_phi = diblock_morphology_seed(kind; f=ff, dims=grid_dims,
            lengths=cell_lengths, amplitude=initial_amplitude)
        acos.(sqrt.(clamp.(vec(initial_phi), 1.0e-10, 1.0 - 1.0e-10)))
    else
        values = Float64.(vec(initial_theta))
        length(values) == prod(grid_dims) ||
            throw(ArgumentError("initial_theta must match the requested grid dimensions"))
        all(isfinite, values) || throw(ArgumentError("initial_theta must be finite"))
        clamp.(values, 1.0e-10, 0.5 * pi - 1.0e-10)
    end
    _project_diblock_theta_mean!(theta, ff)
    theta_to_phi(values) = reshape(cos.(values).^2, grid_dims)

    phi = theta_to_phi(theta)
    initial_energy = diblock_uneyama_doi_energy_nd(phi; f=ff, chiN=chi,
        lengths=cell_lengths, N=nn, b=bb)
    homogeneous_energy = diblock_uneyama_doi_energy_nd(fill(ff, grid_dims);
        f=ff, chiN=chi, lengths=cell_lengths, N=nn, b=bb)
    energy = initial_energy
    gradient_norm = 0.0
    projected_gradient_norm = 0.0
    accepted_steps = 0
    last_improvement = 0.0
    completed_iterations = 0
    converged = false

    for iter in 1:iterations
        phi = theta_to_phi(theta)
        mu_a, mu_b = _diblock_uneyama_doi_chemical_potentials_nd(phi; f=ff,
            chiN=chi, lengths=cell_lengths, N=nn, b=bb)
        gradient_theta, projected_gradient =
            _diblock_theta_gradient_projection(theta, vec(mu_a), vec(mu_b))
        gradient_norm = norm(gradient_theta) / sqrt(length(gradient_theta))
        projected_gradient_norm = norm(projected_gradient) /
            sqrt(length(projected_gradient))
        projected_gradient_norm <= tol && (converged = true; break)
        update_direction = direction == :projected ? projected_gradient : gradient_theta
        accepted = false
        trial_step = step
        trial_theta = similar(theta)
        trial_energy = energy
        for _ in 1:backtracks
            @. trial_theta = theta - trial_step * update_direction
            _project_diblock_theta_mean!(trial_theta, ff)
            trial_phi = theta_to_phi(trial_theta)
            trial_energy = diblock_uneyama_doi_energy_nd(trial_phi; f=ff,
                chiN=chi, lengths=cell_lengths, N=nn, b=bb)
            if isfinite(trial_energy) &&
                    trial_energy <= energy + 1.0e-12 * max(1.0, abs(energy))
                accepted = true
                break
            end
            trial_step *= 0.5
        end
        if !accepted
            step *= 0.5
            step < 1.0e-12 && break
            continue
        end
        last_improvement = energy - trial_energy
        theta .= trial_theta
        energy = trial_energy
        accepted_steps += 1
        completed_iterations = iter
        step = min(1.15 * trial_step, 0.1)
    end

    phi = theta_to_phi(theta)
    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_theta_relaxation",
        descent_direction=string(direction),
        initial_source=initial_source,
        energy=energy,
        initial_energy=initial_energy,
        homogeneous_energy=homogeneous_energy,
        energy_drop_from_initial=initial_energy - energy,
        energy_drop_from_homogeneous=homogeneous_energy - energy,
        mean_phi=mean(phi),
        min_phi=minimum(phi),
        max_phi=maximum(phi),
        contrast=maximum(phi) - minimum(phi),
        gradient_norm=gradient_norm,
        projected_gradient_norm=projected_gradient_norm,
        accepted_steps=accepted_steps,
        iterations=completed_iterations,
        max_iterations=iterations,
        converged=converged,
        last_improvement=last_improvement,
        dims=grid_dims,
        lengths=Tuple(cell_lengths),
        phi=copy(phi),
        theta=reshape(copy(theta), grid_dims),
    )
end

function scan_diblock_uneyama_doi_morphology_cell_scales(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        scale_factors=(0.9, 1.0, 1.1), initial_amplitude::Real=1.0,
        N::Real=1.0, b::Real=1.0, max_iterations::Integer=30,
        relaxation_step::Real=1.0e-2, backtracking_steps::Integer=30,
        tolerance::Real=1.0e-8, local_check_tolerance::Real=1.0e-8)
    kind = _diblock_morphology_symbol(morphology)
    grid_dims = _diblock_morphology_dims(dims)
    base = _diblock_nd_lengths(base_lengths, grid_dims)
    factors = sort(unique(Float64.(collect(scale_factors))))
    length(factors) >= 3 ||
        throw(ArgumentError("scale_factors must contain at least three values"))
    all(value -> value > 0.0 && isfinite(value), factors) ||
        throw(ArgumentError("scale_factors must be positive and finite"))
    ff = Float64(f)
    chi = Float64(chiN)
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)
    local_tol = Float64(local_check_tolerance)
    local_tol >= 0.0 && isfinite(local_tol) ||
        throw(ArgumentError("local_check_tolerance must be nonnegative and finite"))

    evaluations = NamedTuple[]
    for factor in factors
        lengths = Tuple(factor .* base)
        result = relax_diblock_uneyama_doi_morphology_seed_nd(kind; f=ff,
            chiN=chi, dims=grid_dims, lengths=lengths,
            initial_amplitude=initial_amplitude, N=nn, b=bb,
            max_iterations=max_iterations, relaxation_step=relaxation_step,
            backtracking_steps=backtracking_steps, tolerance=tolerance)
        volume = prod(lengths)
        push!(evaluations, (
            factor=factor,
            lengths=lengths,
            cell_volume=volume,
            energy=result.energy,
            energy_density=result.energy / volume,
            accepted_steps=result.accepted_steps,
            iterations=result.iterations,
            converged=result.converged,
            gradient_norm=result.gradient_norm,
            projected_gradient_norm=result.projected_gradient_norm,
            min_phi=result.min_phi,
            max_phi=result.max_phi,
            mean_phi=result.mean_phi,
            saturation_warning=result.min_phi < 0.02 || result.max_phi > 0.98,
            result=result,
        ))
    end

    selected_index = argmin([row.energy_density for row in evaluations])
    selected = evaluations[selected_index]
    boundary_limited = selected_index == firstindex(evaluations) ||
        selected_index == lastindex(evaluations)
    left = selected_index > firstindex(evaluations) ? evaluations[selected_index - 1] :
        nothing
    right = selected_index < lastindex(evaluations) ? evaluations[selected_index + 1] :
        nothing
    tolerance_value = local_tol * max(1.0, abs(selected.energy_density))
    local_minimum_check_pass = !boundary_limited &&
        left !== nothing && right !== nothing &&
        left.energy_density > selected.energy_density + tolerance_value &&
        right.energy_density > selected.energy_density + tolerance_value

    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_cell_scale_scan",
        selected_factor=selected.factor,
        selected_lengths=selected.lengths,
        selected_energy=selected.energy,
        selected_energy_density=selected.energy_density,
        selected_result=selected.result,
        evaluations=evaluations,
        local_left_factor=left === nothing ? NaN : left.factor,
        local_left_energy_density=left === nothing ? Inf : left.energy_density,
        local_right_factor=right === nothing ? NaN : right.factor,
        local_right_energy_density=right === nothing ? Inf : right.energy_density,
        local_minimum_check_pass=local_minimum_check_pass,
        boundary_limited=boundary_limited,
        scale_factors=Tuple(factors),
        base_lengths=Tuple(base),
    )
end

function _default_diblock_cell_shape_factors(dimension::Integer, shape_delta::Real)
    dim = Int(dimension)
    dim >= 1 || throw(ArgumentError("cell-shape dimension must be positive"))
    delta = Float64(shape_delta)
    delta > 0.0 && isfinite(delta) ||
        throw(ArgumentError("shape_delta must be positive and finite"))
    isapprox(delta, 1.0; rtol=1.0e-12, atol=1.0e-14) && return [Tuple(ones(dim))]
    if dim == 1
        return [(1.0,)]
    elseif dim == 2
        return [
            (1.0, 1.0),
            (delta, 1.0 / delta),
            (1.0 / delta, delta),
        ]
    end
    transverse = 1.0 / sqrt(delta)
    inverse_transverse = sqrt(delta)
    shapes = [Tuple(ones(dim))]
    for axis in 1:dim
        factors = fill(transverse, dim)
        factors[axis] = delta
        push!(shapes, Tuple(factors))
    end
    for axis in 1:dim
        factors = fill(inverse_transverse, dim)
        factors[axis] = 1.0 / delta
        push!(shapes, Tuple(factors))
    end
    return shapes
end

function _checked_cell_shape_factors(shape_factors, dims::NTuple{D,Int};
        shape_delta::Real=1.15) where {D}
    raw_shapes = shape_factors === nothing ?
        _default_diblock_cell_shape_factors(D, shape_delta) : collect(shape_factors)
    isempty(raw_shapes) && throw(ArgumentError("shape_factors must not be empty"))
    shapes = NTuple{D,Float64}[]
    for raw in raw_shapes
        values = raw isa Real ? (Float64(raw),) : Tuple(Float64(value) for value in raw)
        length(values) == D ||
            throw(ArgumentError("each shape factor must have one entry per cell dimension"))
        all(value -> value > 0.0 && isfinite(value), values) ||
            throw(ArgumentError("shape_factors must contain only positive finite values"))
        shape = Tuple(values)
        if !any(existing -> all(isapprox(existing[idx], shape[idx];
                    rtol=1.0e-12, atol=1.0e-14) for idx in 1:D), shapes)
            push!(shapes, shape)
        end
    end
    return shapes
end

function scan_diblock_uneyama_doi_morphology_cell_shapes(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        shape_factors=nothing, shape_delta::Real=1.15, initial_amplitudes=(0.5, 1.0),
        N::Real=1.0, b::Real=1.0, max_iterations::Integer=30,
        relaxation_step::Real=1.0e-2, backtracking_steps::Integer=30,
        tolerance::Real=1.0e-8)
    kind = _diblock_morphology_symbol(morphology)
    grid_dims = _diblock_morphology_dims(dims)
    base = _diblock_nd_lengths(base_lengths, grid_dims)
    shapes = _checked_cell_shape_factors(shape_factors, grid_dims;
        shape_delta=shape_delta)
    amplitudes = _checked_initial_amplitudes(initial_amplitudes)
    ff = Float64(f)
    chi = Float64(chiN)
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)

    evaluations = NamedTuple[]
    for amplitude in amplitudes
        for shape in shapes
            lengths = Tuple(base[dim] * shape[dim] for dim in eachindex(base))
            result = relax_diblock_uneyama_doi_morphology_seed_nd(kind; f=ff,
                chiN=chi, dims=grid_dims, lengths=lengths,
                initial_amplitude=amplitude, N=nn, b=bb,
                max_iterations=max_iterations, relaxation_step=relaxation_step,
                backtracking_steps=backtracking_steps, tolerance=tolerance)
            volume = prod(lengths)
            push!(evaluations, (
                initial_amplitude=amplitude,
                shape_factors=shape,
                lengths=lengths,
                cell_volume=volume,
                volume_factor=prod(shape),
                energy=result.energy,
                energy_density=result.energy / volume,
                accepted_steps=result.accepted_steps,
                iterations=result.iterations,
                converged=result.converged,
                gradient_norm=result.gradient_norm,
                projected_gradient_norm=result.projected_gradient_norm,
                min_phi=result.min_phi,
                max_phi=result.max_phi,
                mean_phi=result.mean_phi,
                saturation_warning=result.min_phi < 0.02 || result.max_phi > 0.98,
                result=result,
            ))
        end
    end
    selected = evaluations[argmin([row.energy_density for row in evaluations])]
    isotropic_rows = [row for row in evaluations if all(isapprox(value, 1.0;
        rtol=1.0e-12, atol=1.0e-14) for value in row.shape_factors)]
    isotropic_energy_density = isempty(isotropic_rows) ? NaN :
        minimum(row.energy_density for row in isotropic_rows)
    shape_improvement = isfinite(isotropic_energy_density) ?
        isotropic_energy_density - selected.energy_density : NaN

    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_cell_shape_scan",
        selected_amplitude=selected.initial_amplitude,
        selected_shape_factors=selected.shape_factors,
        selected_lengths=selected.lengths,
        selected_energy=selected.energy,
        selected_energy_density=selected.energy_density,
        selected_result=selected.result,
        isotropic_energy_density=isotropic_energy_density,
        shape_improvement_over_isotropic=shape_improvement,
        selected_is_isotropic=all(isapprox(value, 1.0; rtol=1.0e-12,
            atol=1.0e-14) for value in selected.shape_factors),
        evaluations=evaluations,
        shape_count=length(shapes),
        amplitude_count=length(amplitudes),
        shape_factors=Tuple(shapes),
        initial_amplitudes=Tuple(amplitudes),
        base_lengths=Tuple(base),
    )
end

function _checked_cell_shape_direction(direction, dims::NTuple{D,Int}) where {D}
    raw = if direction === nothing
        if D == 1
            zeros(Float64, 1)
        elseif D == 2
            [-1.0, 1.0]
        else
            values = fill(1.0 / (D - 1), D)
            values[1] = -1.0
            values
        end
    else
        values = collect(direction)
        length(values) == D ||
            throw(ArgumentError("shape_direction must have one entry per cell dimension"))
        Float64.(values)
    end
    all(isfinite, raw) || throw(ArgumentError("shape_direction must be finite"))
    D == 1 && return (0.0,)
    centered = raw .- mean(raw)
    scale = maximum(abs, centered)
    scale > 0.0 ||
        throw(ArgumentError("shape_direction must contain a non-isotropic component"))
    centered ./= scale
    return Tuple(centered)
end

function _cell_shape_factors_from_alpha(alpha::Real, direction::NTuple{D,Float64}) where {D}
    values = [exp(Float64(alpha) * direction[dim]) for dim in 1:D]
    volume_factor = prod(values)^(1.0 / D)
    @. values = values / volume_factor
    return Tuple(values)
end

function optimize_diblock_uneyama_doi_morphology_cell_shape_coordinate(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        shape_direction=nothing, initial_alpha::Real=0.0,
        initial_alpha_step::Real=0.1, min_alpha::Real=-0.8, max_alpha::Real=0.8,
        max_shape_expansions::Integer=8, max_refinement_iterations::Integer=4,
        initial_amplitudes=(0.5, 1.0), N::Real=1.0, b::Real=1.0,
        max_iterations::Integer=30, relaxation_step::Real=1.0e-2,
        backtracking_steps::Integer=30, tolerance::Real=1.0e-8,
        local_check_tolerance::Real=1.0e-8)
    kind = _diblock_morphology_symbol(morphology)
    grid_dims = _diblock_morphology_dims(dims)
    base = _diblock_nd_lengths(base_lengths, grid_dims)
    direction = _checked_cell_shape_direction(shape_direction, grid_dims)
    amplitudes = _checked_initial_amplitudes(initial_amplitudes)
    center = Float64(initial_alpha)
    isfinite(center) || throw(ArgumentError("initial_alpha must be finite"))
    step = Float64(initial_alpha_step)
    step > 0.0 && isfinite(step) ||
        throw(ArgumentError("initial_alpha_step must be positive and finite"))
    alpha_min = Float64(min_alpha)
    alpha_max = Float64(max_alpha)
    alpha_min < alpha_max ||
        throw(ArgumentError("min_alpha and max_alpha must satisfy min < max"))
    alpha_min <= center <= alpha_max ||
        throw(ArgumentError("initial_alpha must lie inside alpha bounds"))
    expansions_allowed = Int(max_shape_expansions)
    expansions_allowed >= 0 ||
        throw(ArgumentError("max_shape_expansions must be nonnegative"))
    refinements_allowed = Int(max_refinement_iterations)
    refinements_allowed >= 0 ||
        throw(ArgumentError("max_refinement_iterations must be nonnegative"))
    local_tol = Float64(local_check_tolerance)
    local_tol >= 0.0 && isfinite(local_tol) ||
        throw(ArgumentError("local_check_tolerance must be nonnegative and finite"))
    ff = Float64(f)
    chi = Float64(chiN)
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)

    all_evaluations = NamedTuple[]
    amplitude_results = NamedTuple[]

    for amplitude in amplitudes
        alpha_values = Float64[]
        evaluations = NamedTuple[]

        function has_alpha(alpha::Float64)
            return any(existing -> isapprox(existing, alpha; rtol=1.0e-12,
                atol=1.0e-14), alpha_values)
        end

        function evaluate_alpha!(alpha::Float64)
            clipped = clamp(alpha, alpha_min, alpha_max)
            if has_alpha(clipped)
                index = findfirst(existing -> isapprox(existing, clipped;
                    rtol=1.0e-12, atol=1.0e-14), alpha_values)
                return evaluations[index]
            end
            shape = _cell_shape_factors_from_alpha(clipped, direction)
            lengths = Tuple(base[dim] * shape[dim] for dim in eachindex(base))
            result = relax_diblock_uneyama_doi_morphology_seed_nd(kind; f=ff,
                chiN=chi, dims=grid_dims, lengths=lengths,
                initial_amplitude=amplitude, N=nn, b=bb,
                max_iterations=max_iterations, relaxation_step=relaxation_step,
                backtracking_steps=backtracking_steps, tolerance=tolerance)
            volume = prod(lengths)
            row = (
                initial_amplitude=amplitude,
                alpha=clipped,
                shape_direction=direction,
                shape_factors=shape,
                lengths=lengths,
                cell_volume=volume,
                volume_factor=prod(shape),
                energy=result.energy,
                energy_density=result.energy / volume,
                accepted_steps=result.accepted_steps,
                iterations=result.iterations,
                converged=result.converged,
                gradient_norm=result.gradient_norm,
                projected_gradient_norm=result.projected_gradient_norm,
                min_phi=result.min_phi,
                max_phi=result.max_phi,
                mean_phi=result.mean_phi,
                saturation_warning=result.min_phi < 0.02 || result.max_phi > 0.98,
                result=result,
            )
            push!(alpha_values, clipped)
            push!(evaluations, row)
            push!(all_evaluations, row)
            return row
        end

        function sorted_evaluations()
            order = sortperm(alpha_values)
            return evaluations[order]
        end

        selected_index(rows) = argmin([row.energy_density for row in rows])

        evaluate_alpha!(center)
        evaluate_alpha!(center - step)
        evaluate_alpha!(center + step)

        expansion_count = 0
        for _ in 1:expansions_allowed
            rows = sorted_evaluations()
            index = selected_index(rows)
            if firstindex(rows) < index < lastindex(rows)
                break
            end
            if index == firstindex(rows)
                candidate = rows[firstindex(rows)].alpha - step
                candidate >= alpha_min || break
                evaluate_alpha!(candidate)
            else
                candidate = rows[lastindex(rows)].alpha + step
                candidate <= alpha_max || break
                evaluate_alpha!(candidate)
            end
            expansion_count += 1
        end

        refinement_count = 0
        for _ in 1:refinements_allowed
            rows = sorted_evaluations()
            index = selected_index(rows)
            firstindex(rows) < index < lastindex(rows) || break
            left = rows[index - 1]
            selected = rows[index]
            right = rows[index + 1]
            old_count = length(evaluations)
            evaluate_alpha!(0.5 * (left.alpha + selected.alpha))
            evaluate_alpha!(0.5 * (selected.alpha + right.alpha))
            length(evaluations) == old_count && break
            refinement_count += 1
        end

        rows = sorted_evaluations()
        index = selected_index(rows)
        selected = rows[index]
        boundary_limited = index == firstindex(rows) || index == lastindex(rows)
        left = index > firstindex(rows) ? rows[index - 1] : nothing
        right = index < lastindex(rows) ? rows[index + 1] : nothing
        tolerance_value = local_tol * max(1.0, abs(selected.energy_density))
        local_minimum_check_pass = !boundary_limited &&
            left !== nothing && right !== nothing &&
            left.energy_density > selected.energy_density + tolerance_value &&
            right.energy_density > selected.energy_density + tolerance_value
        push!(amplitude_results, (
            initial_amplitude=amplitude,
            selected=selected,
            evaluations=rows,
            local_left_alpha=left === nothing ? NaN : left.alpha,
            local_left_energy_density=left === nothing ? Inf : left.energy_density,
            local_right_alpha=right === nothing ? NaN : right.alpha,
            local_right_energy_density=right === nothing ? Inf : right.energy_density,
            local_minimum_check_pass=local_minimum_check_pass,
            boundary_limited=boundary_limited,
            expansion_count=expansion_count,
            refinement_iterations=refinement_count,
        ))
    end

    selected_amplitude = amplitude_results[argmin([row.selected.energy_density
        for row in amplitude_results])]
    selected = selected_amplitude.selected
    isotropic_rows = [row for row in all_evaluations if isapprox(row.alpha, 0.0;
        rtol=1.0e-12, atol=1.0e-14)]
    isotropic_energy_density = isempty(isotropic_rows) ? NaN :
        minimum(row.energy_density for row in isotropic_rows)
    improvement = isfinite(isotropic_energy_density) ?
        isotropic_energy_density - selected.energy_density : NaN

    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_cell_shape_coordinate_optimization",
        selected_amplitude=selected.initial_amplitude,
        selected_alpha=selected.alpha,
        selected_shape_factors=selected.shape_factors,
        selected_lengths=selected.lengths,
        selected_energy=selected.energy,
        selected_energy_density=selected.energy_density,
        selected_result=selected.result,
        isotropic_energy_density=isotropic_energy_density,
        shape_improvement_over_isotropic=improvement,
        selected_is_isotropic=isapprox(selected.alpha, 0.0; rtol=1.0e-12,
            atol=1.0e-14),
        local_left_alpha=selected_amplitude.local_left_alpha,
        local_left_energy_density=selected_amplitude.local_left_energy_density,
        local_right_alpha=selected_amplitude.local_right_alpha,
        local_right_energy_density=selected_amplitude.local_right_energy_density,
        local_minimum_check_pass=selected_amplitude.local_minimum_check_pass,
        boundary_limited=selected_amplitude.boundary_limited,
        expansion_count=sum(row.expansion_count for row in amplitude_results),
        refinement_iterations=sum(row.refinement_iterations for row in amplitude_results),
        evaluations=all_evaluations,
        amplitude_results=amplitude_results,
        shape_direction=direction,
        initial_alpha=center,
        initial_alpha_step=step,
        min_alpha=alpha_min,
        max_alpha=alpha_max,
        initial_amplitudes=Tuple(amplitudes),
        base_lengths=Tuple(base),
    )
end

function _default_diblock_cell_shape_directions(dims::NTuple{D,Int}) where {D}
    if D == 1
        return [(0.0,)]
    elseif D == 2
        return [(-1.0, 1.0)]
    end
    directions = NTuple{D,Float64}[]
    for axis in 2:D
        values = zeros(Float64, D)
        values[1] = -1.0
        values[axis] = 1.0
        push!(directions, Tuple(values))
    end
    return directions
end

function _checked_cell_shape_directions(directions, dims::NTuple{D,Int}) where {D}
    raw = directions === nothing ? _default_diblock_cell_shape_directions(dims) :
        collect(directions)
    isempty(raw) && throw(ArgumentError("shape_directions must not be empty"))
    checked = NTuple{D,Float64}[]
    for direction in raw
        value = _checked_cell_shape_direction(direction, dims)
        if !any(existing -> all(isapprox(existing[idx], value[idx];
                    rtol=1.0e-12, atol=1.0e-14) for idx in 1:D), checked)
            push!(checked, value)
        end
    end
    return checked
end

function optimize_diblock_uneyama_doi_morphology_cell_shape_multicoordinate(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        shape_directions=nothing, coordinate_passes::Integer=1,
        initial_alpha_step::Real=0.1, min_alpha::Real=-0.8, max_alpha::Real=0.8,
        max_shape_expansions::Integer=8, max_refinement_iterations::Integer=4,
        initial_amplitudes=(0.5, 1.0), N::Real=1.0, b::Real=1.0,
        max_iterations::Integer=30, relaxation_step::Real=1.0e-2,
        backtracking_steps::Integer=30, tolerance::Real=1.0e-8,
        local_check_tolerance::Real=1.0e-8)
    kind = _diblock_morphology_symbol(morphology)
    grid_dims = _diblock_morphology_dims(dims)
    initial_lengths = _diblock_nd_lengths(base_lengths, grid_dims)
    directions = _checked_cell_shape_directions(shape_directions, grid_dims)
    passes = Int(coordinate_passes)
    passes >= 1 || throw(ArgumentError("coordinate_passes must be positive"))
    current_lengths = Tuple(initial_lengths)
    ff = Float64(f)
    chi = Float64(chiN)
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)
    all_evaluations = NamedTuple[]
    pass_results = NamedTuple[]
    initial_cell_energy_density = NaN

    for pass_index in 1:passes
        for direction_index in eachindex(directions)
            direction = directions[direction_index]
            result = optimize_diblock_uneyama_doi_morphology_cell_shape_coordinate(
                kind; f=ff, chiN=chi, dims=grid_dims, base_lengths=current_lengths,
                shape_direction=direction, initial_alpha=0.0,
                initial_alpha_step=initial_alpha_step, min_alpha=min_alpha,
                max_alpha=max_alpha, max_shape_expansions=max_shape_expansions,
                max_refinement_iterations=max_refinement_iterations,
                initial_amplitudes=initial_amplitudes, N=nn, b=bb,
                max_iterations=max_iterations, relaxation_step=relaxation_step,
                backtracking_steps=backtracking_steps, tolerance=tolerance,
                local_check_tolerance=local_check_tolerance)
            if isnan(initial_cell_energy_density)
                initial_cell_energy_density = result.isotropic_energy_density
            end
            start_lengths = current_lengths
            current_lengths = result.selected_lengths
            push!(pass_results, (
                pass_index=pass_index,
                direction_index=direction_index,
                shape_direction=direction,
                start_lengths=start_lengths,
                selected_alpha=result.selected_alpha,
                selected_shape_factors=result.selected_shape_factors,
                selected_lengths=result.selected_lengths,
                selected_energy=result.selected_energy,
                selected_energy_density=result.selected_energy_density,
                start_cell_energy_density=result.isotropic_energy_density,
                shape_improvement_over_start_cell=result.shape_improvement_over_isotropic,
                local_left_alpha=result.local_left_alpha,
                local_left_energy_density=result.local_left_energy_density,
                local_right_alpha=result.local_right_alpha,
                local_right_energy_density=result.local_right_energy_density,
                local_minimum_check_pass=result.local_minimum_check_pass,
                boundary_limited=result.boundary_limited,
                expansion_count=result.expansion_count,
                refinement_iterations=result.refinement_iterations,
                selected_result=result.selected_result,
            ))
            for row in result.evaluations
                push!(all_evaluations, merge(row, (
                    pass_index=pass_index,
                    direction_index=direction_index,
                    start_lengths=start_lengths,
                )))
            end
        end
    end

    selected_pass = pass_results[end]
    selected_result = selected_pass.selected_result
    total_shape = Tuple(current_lengths[dim] / initial_lengths[dim]
        for dim in eachindex(initial_lengths))
    improvement = isfinite(initial_cell_energy_density) ?
        initial_cell_energy_density - selected_pass.selected_energy_density : NaN

    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_cell_shape_multicoordinate_optimization",
        selected_lengths=current_lengths,
        selected_energy=selected_pass.selected_energy,
        selected_energy_density=selected_pass.selected_energy_density,
        selected_result=selected_result,
        initial_cell_energy_density=initial_cell_energy_density,
        shape_improvement_over_initial_cell=improvement,
        total_shape_factors=total_shape,
        local_pass_count=count(row -> row.local_minimum_check_pass, pass_results),
        boundary_limited_count=count(row -> row.boundary_limited, pass_results),
        pass_results=pass_results,
        evaluations=all_evaluations,
        direction_count=length(directions),
        coordinate_passes=passes,
        shape_directions=Tuple(directions),
        initial_amplitudes=Tuple(_checked_initial_amplitudes(initial_amplitudes)),
        base_lengths=Tuple(initial_lengths),
    )
end

function optimize_diblock_uneyama_doi_morphology_cell_scale(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        initial_scale_factor::Real=1.0, initial_log_step::Real=0.1,
        min_scale_factor::Real=0.25, max_scale_factor::Real=4.0,
        max_scale_expansions::Integer=8, max_refinement_iterations::Integer=6,
        initial_amplitude::Real=1.0, N::Real=1.0, b::Real=1.0,
        max_iterations::Integer=30, relaxation_step::Real=1.0e-2,
        backtracking_steps::Integer=30, tolerance::Real=1.0e-8,
        local_check_tolerance::Real=1.0e-8)
    kind = _diblock_morphology_symbol(morphology)
    grid_dims = _diblock_morphology_dims(dims)
    base = _diblock_nd_lengths(base_lengths, grid_dims)
    center = Float64(initial_scale_factor)
    center > 0.0 && isfinite(center) ||
        throw(ArgumentError("initial_scale_factor must be positive and finite"))
    log_step = Float64(initial_log_step)
    log_step > 0.0 && isfinite(log_step) ||
        throw(ArgumentError("initial_log_step must be positive and finite"))
    min_factor = Float64(min_scale_factor)
    max_factor = Float64(max_scale_factor)
    0.0 < min_factor < max_factor ||
        throw(ArgumentError("min_scale_factor and max_scale_factor must satisfy 0 < min < max"))
    min_factor <= center <= max_factor ||
        throw(ArgumentError("initial_scale_factor must lie inside the scale-factor bounds"))
    expansions_allowed = Int(max_scale_expansions)
    expansions_allowed >= 0 ||
        throw(ArgumentError("max_scale_expansions must be nonnegative"))
    refinements_allowed = Int(max_refinement_iterations)
    refinements_allowed >= 0 ||
        throw(ArgumentError("max_refinement_iterations must be nonnegative"))
    ff = Float64(f)
    chi = Float64(chiN)
    _, nn, bb, _ = _diblock_validate(ff, N, b, 1.0)
    local_tol = Float64(local_check_tolerance)
    local_tol >= 0.0 && isfinite(local_tol) ||
        throw(ArgumentError("local_check_tolerance must be nonnegative and finite"))

    evaluations = NamedTuple[]
    factors = Float64[]

    function has_factor(factor::Float64)
        return any(existing -> isapprox(existing, factor; rtol=1.0e-12, atol=1.0e-14),
            factors)
    end

    function evaluate_factor!(factor::Float64)
        clipped = clamp(factor, min_factor, max_factor)
        if has_factor(clipped)
            index = findfirst(existing -> isapprox(existing, clipped; rtol=1.0e-12,
                atol=1.0e-14), factors)
            return evaluations[index]
        end
        lengths = Tuple(clipped .* base)
        result = relax_diblock_uneyama_doi_morphology_seed_nd(kind; f=ff,
            chiN=chi, dims=grid_dims, lengths=lengths,
            initial_amplitude=initial_amplitude, N=nn, b=bb,
            max_iterations=max_iterations, relaxation_step=relaxation_step,
            backtracking_steps=backtracking_steps, tolerance=tolerance)
        volume = prod(lengths)
        row = (
            factor=clipped,
            lengths=lengths,
            cell_volume=volume,
            energy=result.energy,
            energy_density=result.energy / volume,
            accepted_steps=result.accepted_steps,
            iterations=result.iterations,
            converged=result.converged,
            gradient_norm=result.gradient_norm,
            projected_gradient_norm=result.projected_gradient_norm,
            min_phi=result.min_phi,
            max_phi=result.max_phi,
            mean_phi=result.mean_phi,
            saturation_warning=result.min_phi < 0.02 || result.max_phi > 0.98,
            result=result,
        )
        push!(factors, clipped)
        push!(evaluations, row)
        return row
    end

    function sorted_evaluations()
        order = sortperm(factors)
        return evaluations[order]
    end

    function selected_index(rows)
        return argmin([row.energy_density for row in rows])
    end

    evaluate_factor!(center)
    evaluate_factor!(center * exp(-log_step))
    evaluate_factor!(center * exp(log_step))

    expansion_count = 0
    for _ in 1:expansions_allowed
        rows = sorted_evaluations()
        index = selected_index(rows)
        if firstindex(rows) < index < lastindex(rows)
            break
        end
        if index == firstindex(rows)
            candidate = rows[firstindex(rows)].factor * exp(-log_step)
            candidate > min_factor || break
            evaluate_factor!(candidate)
        else
            candidate = rows[lastindex(rows)].factor * exp(log_step)
            candidate < max_factor || break
            evaluate_factor!(candidate)
        end
        expansion_count += 1
    end

    refinement_count = 0
    for _ in 1:refinements_allowed
        rows = sorted_evaluations()
        index = selected_index(rows)
        firstindex(rows) < index < lastindex(rows) || break
        left = rows[index - 1]
        selected = rows[index]
        right = rows[index + 1]
        left_mid = sqrt(left.factor * selected.factor)
        right_mid = sqrt(selected.factor * right.factor)
        old_count = length(evaluations)
        evaluate_factor!(left_mid)
        evaluate_factor!(right_mid)
        length(evaluations) == old_count && break
        refinement_count += 1
    end

    rows = sorted_evaluations()
    index = selected_index(rows)
    selected = rows[index]
    boundary_limited = index == firstindex(rows) || index == lastindex(rows)
    left = index > firstindex(rows) ? rows[index - 1] : nothing
    right = index < lastindex(rows) ? rows[index + 1] : nothing
    tolerance_value = local_tol * max(1.0, abs(selected.energy_density))
    local_minimum_check_pass = !boundary_limited &&
        left !== nothing && right !== nothing &&
        left.energy_density > selected.energy_density + tolerance_value &&
        right.energy_density > selected.energy_density + tolerance_value

    return (
        morphology=string(kind),
        model="Uneyama-Doi",
        method="psi_adaptive_cell_scale",
        selected_factor=selected.factor,
        selected_lengths=selected.lengths,
        selected_energy=selected.energy,
        selected_energy_density=selected.energy_density,
        selected_result=selected.result,
        evaluations=rows,
        local_left_factor=left === nothing ? NaN : left.factor,
        local_left_energy_density=left === nothing ? Inf : left.energy_density,
        local_right_factor=right === nothing ? NaN : right.factor,
        local_right_energy_density=right === nothing ? Inf : right.energy_density,
        local_minimum_check_pass=local_minimum_check_pass,
        boundary_limited=boundary_limited,
        expansion_count=expansion_count,
        refinement_iterations=refinement_count,
        initial_scale_factor=center,
        initial_log_step=log_step,
        min_scale_factor=min_factor,
        max_scale_factor=max_factor,
        scale_factors=Tuple(row.factor for row in rows),
        base_lengths=Tuple(base),
    )
end

function optimize_diblock_uneyama_doi_morphology_cell_scale_multistart(morphology;
        f::Real=0.5, chiN::Real=20.0, dims=(16, 16), base_lengths=1.0,
        initial_scale_factor::Real=1.0, initial_log_step::Real=0.1,
        min_scale_factor::Real=0.25, max_scale_factor::Real=4.0,
        max_scale_expansions::Integer=8, max_refinement_iterations::Integer=6,
        initial_amplitudes=(0.5, 1.0), N::Real=1.0, b::Real=1.0,
        max_iterations::Integer=30, relaxation_step::Real=1.0e-2,
        backtracking_steps::Integer=30, tolerance::Real=1.0e-8,
        local_check_tolerance::Real=1.0e-8)
    amplitudes = _checked_initial_amplitudes(initial_amplitudes)
    amplitude_results = NamedTuple[]
    evaluations = NamedTuple[]
    for amplitude in amplitudes
        result = optimize_diblock_uneyama_doi_morphology_cell_scale(morphology;
            f=f, chiN=chiN, dims=dims, base_lengths=base_lengths,
            initial_scale_factor=initial_scale_factor,
            initial_log_step=initial_log_step, min_scale_factor=min_scale_factor,
            max_scale_factor=max_scale_factor,
            max_scale_expansions=max_scale_expansions,
            max_refinement_iterations=max_refinement_iterations,
            initial_amplitude=amplitude, N=N, b=b,
            max_iterations=max_iterations, relaxation_step=relaxation_step,
            backtracking_steps=backtracking_steps, tolerance=tolerance,
            local_check_tolerance=local_check_tolerance)
        push!(amplitude_results, merge(result, (initial_amplitude=amplitude,)))
        for row in result.evaluations
            push!(evaluations, merge(row, (initial_amplitude=amplitude,)))
        end
    end
    selected = amplitude_results[argmin([row.selected_energy_density
        for row in amplitude_results])]
    selected_result = selected.selected_result
    return (
        morphology=selected.morphology,
        model="Uneyama-Doi",
        method="psi_adaptive_cell_scale_multistart",
        selected_amplitude=selected.initial_amplitude,
        selected_factor=selected.selected_factor,
        selected_lengths=selected.selected_lengths,
        selected_energy=selected.selected_energy,
        selected_energy_density=selected.selected_energy_density,
        selected_result=selected_result,
        evaluations=evaluations,
        amplitude_results=amplitude_results,
        local_left_factor=selected.local_left_factor,
        local_left_energy_density=selected.local_left_energy_density,
        local_right_factor=selected.local_right_factor,
        local_right_energy_density=selected.local_right_energy_density,
        local_minimum_check_pass=selected.local_minimum_check_pass,
        boundary_limited=selected.boundary_limited,
        expansion_count=sum(row.expansion_count for row in amplitude_results),
        refinement_iterations=sum(row.refinement_iterations for row in amplitude_results),
        initial_scale_factor=selected.initial_scale_factor,
        initial_log_step=selected.initial_log_step,
        min_scale_factor=selected.min_scale_factor,
        max_scale_factor=selected.max_scale_factor,
        scale_factors=Tuple(sort(unique(row.factor for row in evaluations))),
        initial_amplitudes=Tuple(amplitudes),
        base_lengths=selected.base_lengths,
    )
end

function _diblock_cosine_coefficients_from_profile(phi::AbstractVector{Float64};
        f::Float64, L::Float64, mode_count::Integer)
    count = length(phi)
    modes = Int(mode_count)
    x = [(idx - 0.5) * L / count for idx in 1:count]
    coeffs = zeros(Float64, modes)
    for mode in 1:modes
        coeffs[mode] = 2.0 * mean((phi[idx] - f) * cos(2.0 * pi * mode * x[idx] / L)
            for idx in 1:count)
    end
    return coeffs
end

function _minimize_diblock_relaxed_lamella(energy_function, chemical_potential_function;
        f::Real=0.5, chiN::Real=12.0, L=nothing, nx::Integer=128,
        mode_count::Integer=3, initial_amplitude::Real=0.2, N::Real=1.0,
        b::Real=1.0, nquad=nothing, max_iterations::Integer=10_000,
        relaxation_step::Real=1.0e-2, tolerance::Real=1.0e-8,
        gradient_tolerance::Real=5.0e-4,
        model_kwargs...)
    modes = Int(mode_count)
    modes >= 1 || throw(ArgumentError("mode_count must be positive"))
    count = Int(nx)
    count >= 8 || throw(ArgumentError("nx must be at least 8"))
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    period = L === nothing ? 2.0 * pi / sqrt(_diblock_kernel_minimum_k2(; f=ff, N=nn, b=bb)) :
        Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))

    _, initial_phi = diblock_lamella_profile_from_modes([Float64(initial_amplitude);
                                                         zeros(Float64, modes - 1)];
        f=ff, nx=count, L=period)
    theta = acos.(sqrt.(clamp.(initial_phi, 1.0e-10, 1.0 - 1.0e-10)))
    _project_diblock_theta_mean!(theta, ff)

    # The BURP-TI composition kernel depends only on (k2, f, N, b), all of
    # which are fixed for the whole relaxation at this fixed period.  Precompute
    # it once here and thread it through every model_energy/model_force call
    # below (instead of letting each call recompute it internally), since this
    # loop can run thousands of energy/force evaluations per solve.
    kernel_kwargs = energy_function === diblock_burp_ti_energy_1d ?
        (composition_kernel=[diblock_composition_kernel(k2; f=ff, N=nn, b=bb)
                              for k2 in _periodic_k2_1d(count, period)],) :
        NamedTuple()
    call_kwargs = merge(kernel_kwargs, (; model_kwargs...))

    function model_energy(phi)
        if nquad === nothing
            return energy_function(phi; f=ff, chiN=chi, L=period, N=nn, b=bb,
                call_kwargs...)
        end
        return energy_function(phi; f=ff, chiN=chi, L=period, N=nn, b=bb,
            nquad=Int(nquad), call_kwargs...)
    end

    function model_force(phi)
        if nquad === nothing
            return chemical_potential_function(phi; f=ff, chiN=chi, L=period, N=nn, b=bb,
                call_kwargs...)
        end
        return chemical_potential_function(phi; f=ff, chiN=chi, L=period, N=nn,
            b=bb, nquad=Int(nquad), call_kwargs...)
    end

    phi = cos.(theta).^2
    energy = model_energy(phi)
    step = Float64(relaxation_step)
    step > 0.0 || throw(ArgumentError("relaxation_step must be positive"))
    tol = Float64(tolerance)
    tol > 0.0 || throw(ArgumentError("tolerance must be positive"))
    grad_tol = Float64(gradient_tolerance)
    grad_tol > 0.0 && isfinite(grad_tol) || throw(ArgumentError(
        "gradient_tolerance must be positive and finite"))
    converged = false
    completed_iterations = 0

    # Barzilai-Borwein spectral-step accelerated projected gradient descent.
    #
    # This keeps the exact same manifold-feasible structure as the original
    # hand-rolled relaxation (project theta after every trial step via the
    # existing `_project_diblock_theta_mean!`, only ever accept a trial step
    # that does not increase the energy, backtrack by halving otherwise, and
    # declare convergence via the same two criteria: the step became smaller
    # than `tolerance` in theta-space, or the relative energy drop has gone
    # flat).  Plain L-BFGS on this constrained problem was tried first and
    # found finicky: Optim's line searches (HagerZhang, BackTracking) either
    # stall/hang or silently misconverge when the retraction's non-smooth
    # region is probed by a large trial step, and this is a real risk here
    # because `mode_count`-seeded strongly-segregated profiles push theta
    # close to the region where `_project_diblock_theta_mean!` needs its
    # logit-space fallback.  A Barzilai-Borwein step size is the sanctioned
    # fallback ("a well-tuned accelerated/Barzilai-Borwein gradient") and,
    # crucially, only ever changes the *step size* fed into the existing
    # proven backtracking/projection loop -- it cannot make the iteration
    # less correct than the original, only faster, since a bad BB guess is
    # simply halved back down by the same backtracking safeguard.
    gradient_theta = similar(theta)
    trial_theta = similar(theta)
    gradient_trial = similar(theta)
    constraint_gradient = similar(theta)

    function _theta_gradient!(out, th, phi_th)
        mu_phi = model_force(phi_th)
        @. out = -2.0 * cos(th) * sin(th) * mu_phi
        @. constraint_gradient = -2.0 * cos(th) * sin(th)
        denominator = dot(constraint_gradient, constraint_gradient)
        if denominator > eps(Float64)
            multiplier = dot(out, constraint_gradient) / denominator
            @. out -= multiplier * constraint_gradient
        end
        return out
    end

    _theta_gradient!(gradient_theta, theta, phi)
    step = clamp(1.0 / max(norm(gradient_theta), 1.0e-8), 1.0e-6, 0.5)

    for iter in 1:Int(max_iterations)
        accepted = false
        trial_energy = energy
        trial_step = step
        local trial_phi
        for _ in 1:40
            @. trial_theta = theta - trial_step * gradient_theta
            _project_diblock_theta_mean!(trial_theta, ff)
            trial_phi = cos.(trial_theta).^2
            trial_energy = model_energy(trial_phi)
            if isfinite(trial_energy) &&
                    trial_energy <= energy + 1.0e-12 * max(1.0, abs(energy))
                accepted = true
                break
            end
            trial_step *= 0.5
        end
        if !accepted
            step *= 0.5
            step < 1.0e-12 && break
            continue
        end
        max_update = maximum(abs.(trial_theta .- theta))
        relative_drop = abs(energy - trial_energy) / max(1.0, abs(energy))

        # Barzilai-Borwein step size for the next iteration: alpha = <s,s>/<s,y>
        # (short BB step), s = theta step just taken, y = gradient change.
        _theta_gradient!(gradient_trial, trial_theta, trial_phi)
        s_dot_s = 0.0
        s_dot_y = 0.0
        @inbounds for idx in eachindex(theta)
            s_val = trial_theta[idx] - theta[idx]
            y_val = gradient_trial[idx] - gradient_theta[idx]
            s_dot_s += s_val * s_val
            s_dot_y += s_val * y_val
        end
        bb_step = s_dot_y > 1.0e-14 ? s_dot_s / s_dot_y : trial_step
        bb_step = clamp(bb_step, 1.0e-10, 0.5)

        theta .= trial_theta
        energy = trial_energy
        gradient_theta .= gradient_trial
        step = bb_step
        completed_iterations = iter
        gradient_rms = sqrt(mean(abs2, gradient_theta))
        if iter > 20 && gradient_rms <= grad_tol &&
                (max_update < sqrt(tol) || relative_drop < sqrt(tol))
            converged = true
            break
        end
    end

    x = [(idx - 0.5) * period / count for idx in 1:count]
    phi = cos.(theta).^2
    _theta_gradient!(gradient_theta, theta, phi)
    projected_force_norm = sqrt(mean(abs2, gradient_theta))
    projected_force_maxabs = maximum(abs, gradient_theta)
    coefficients = _diblock_cosine_coefficients_from_profile(phi; f=ff, L=period,
        mode_count=modes)
    homogeneous = model_energy(fill(ff, count))
    return DiblockBurpLamellaResult(ff, chi, period, count, modes, x, phi,
        coefficients, energy, homogeneous, converged, completed_iterations,
        minimum(phi), maximum(phi), mean(phi), projected_force_norm,
        projected_force_maxabs)
end

mutable struct _DiblockUD1DHotLoop
    count::Int
    f::Float64
    fb::Float64
    chi::Float64
    period::Float64
    dx::Float64
    N::Float64
    b::Float64
    a11::Float64
    a12::Float64
    a22::Float64
    c11::Float64
    c12::Float64
    c22::Float64
    homogeneous::Float64
    k2::Vector{Float64}
    buffer::Vector{ComplexF64}
    spectrum_a::Vector{ComplexF64}
    spectrum_b::Vector{ComplexF64}
    psi_a::Vector{Float64}
    psi_b::Vector{Float64}
    green_a::Vector{Float64}
    green_b::Vector{Float64}
    lap_a::Vector{Float64}
    lap_b::Vector{Float64}
    raw_gradient::Vector{Float64}
    forward::Any
    inverse::Any
end

function _diblock_ud_1d_hotloop(count::Int, f::Float64, chiN::Float64,
        period::Float64, N::Float64, b::Float64)
    fb = 1.0 - f
    chi = chiN
    dx = period / count
    coeffs = diblock_uneyama_doi_coefficients(; f=f, N=N, b=b)
    buffer = zeros(ComplexF64, count)
    psi_a0 = sqrt(f)
    psi_b0 = sqrt(fb)
    homogeneous_density =
        2.0 * f * coeffs.C[1, 1] * f * log(psi_a0) +
        2.0 * fb * coeffs.C[2, 2] * fb * log(psi_b0) +
        4.0 * sqrt(f * fb) * coeffs.C[1, 2] * psi_a0 * psi_b0 +
        chi * f * fb
    return _DiblockUD1DHotLoop(count, f, fb, chi, period, dx, N, b,
        coeffs.A[1, 1], coeffs.A[1, 2], coeffs.A[2, 2],
        coeffs.C[1, 1], coeffs.C[1, 2], coeffs.C[2, 2],
        period * homogeneous_density, _periodic_k2_1d(count, period), buffer,
        similar(buffer), similar(buffer), zeros(count), zeros(count), zeros(count),
        zeros(count), zeros(count), zeros(count), zeros(count), plan_fft!(buffer),
        plan_ifft!(buffer))
end

function _diblock_ud_1d_value_gradient!(gradient, hotloop::_DiblockUD1DHotLoop,
        theta::AbstractVector{<:Real})
    length(theta) == hotloop.count || throw(DimensionMismatch(
        "UD theta field length does not match its spectral workspace"))
    lower = 1.0e-10
    upper = 0.5 * pi - lower
    @inbounds for index in eachindex(theta)
        value = Float64(theta[index])
        if !isfinite(value) || value <= lower || value >= upper
            gradient === nothing || fill!(gradient, 0.0)
            return Inf
        end
        hotloop.psi_a[index] = cos(value)
        hotloop.psi_b[index] = sin(value)
        hotloop.buffer[index] = complex(hotloop.psi_a[index])
    end
    hotloop.forward * hotloop.buffer
    copyto!(hotloop.spectrum_a, hotloop.buffer)
    @inbounds @simd for index in eachindex(hotloop.buffer)
        hotloop.buffer[index] = complex(hotloop.psi_b[index])
    end
    hotloop.forward * hotloop.buffer
    copyto!(hotloop.spectrum_b, hotloop.buffer)

    spectral_long_range = 0.0
    spectral_gradient = 0.0
    @inbounds for index in 2:hotloop.count
        a_hat = hotloop.spectrum_a[index]
        b_hat = hotloop.spectrum_b[index]
        cross = real(conj(a_hat) * b_hat)
        spectral_long_range += (
            2.0 * hotloop.f * hotloop.a11 * abs2(a_hat) +
            4.0 * sqrt(hotloop.f * hotloop.fb) * hotloop.a12 * cross +
            2.0 * hotloop.fb * hotloop.a22 * abs2(b_hat)
        ) / hotloop.k2[index]
        spectral_gradient += hotloop.k2[index] * (abs2(a_hat) + abs2(b_hat))
    end
    normalization = hotloop.dx / hotloop.count
    energy = normalization * spectral_long_range +
        hotloop.N * hotloop.b^2 / 6.0 * normalization * spectral_gradient
    local_and_interaction = 0.0
    @inbounds for index in eachindex(hotloop.psi_a)
        psi_a = hotloop.psi_a[index]
        psi_b = hotloop.psi_b[index]
        local_and_interaction +=
            2.0 * hotloop.f * hotloop.c11 * psi_a^2 * log(psi_a) +
            2.0 * hotloop.fb * hotloop.c22 * psi_b^2 * log(psi_b) +
            4.0 * sqrt(hotloop.f * hotloop.fb) * hotloop.c12 * psi_a * psi_b +
            hotloop.chi * psi_a^2 * psi_b^2
    end
    energy += hotloop.dx * local_and_interaction - hotloop.homogeneous
    gradient === nothing && return energy

    fill!(hotloop.buffer, zero(ComplexF64))
    @inbounds for index in 2:hotloop.count
        hotloop.buffer[index] = hotloop.spectrum_a[index] / hotloop.k2[index]
    end
    hotloop.inverse * hotloop.buffer
    @inbounds @simd for index in eachindex(hotloop.green_a)
        hotloop.green_a[index] = real(hotloop.buffer[index])
    end
    fill!(hotloop.buffer, zero(ComplexF64))
    @inbounds for index in 2:hotloop.count
        hotloop.buffer[index] = hotloop.spectrum_b[index] / hotloop.k2[index]
    end
    hotloop.inverse * hotloop.buffer
    @inbounds @simd for index in eachindex(hotloop.green_b)
        hotloop.green_b[index] = real(hotloop.buffer[index])
    end
    @inbounds @simd for index in eachindex(hotloop.buffer)
        hotloop.buffer[index] = -hotloop.k2[index] * hotloop.spectrum_a[index]
    end
    hotloop.inverse * hotloop.buffer
    @inbounds @simd for index in eachindex(hotloop.lap_a)
        hotloop.lap_a[index] = real(hotloop.buffer[index])
    end
    @inbounds @simd for index in eachindex(hotloop.buffer)
        hotloop.buffer[index] = -hotloop.k2[index] * hotloop.spectrum_b[index]
    end
    hotloop.inverse * hotloop.buffer
    @inbounds @simd for index in eachindex(hotloop.lap_b)
        hotloop.lap_b[index] = real(hotloop.buffer[index])
    end

    root_fraction_product = sqrt(hotloop.f * hotloop.fb)
    @inbounds for index in eachindex(hotloop.psi_a)
        psi_a = hotloop.psi_a[index]
        psi_b = hotloop.psi_b[index]
        mu_a =
            4.0 * hotloop.f * hotloop.a11 * hotloop.green_a[index] +
            4.0 * root_fraction_product * hotloop.a12 * hotloop.green_b[index] +
            2.0 * hotloop.f * hotloop.c11 *
                (2.0 * psi_a * log(psi_a) + psi_a) +
            4.0 * root_fraction_product * hotloop.c12 * psi_b -
            hotloop.N * hotloop.b^2 / 3.0 * hotloop.lap_a[index] +
            2.0 * hotloop.chi * psi_a * psi_b^2
        mu_b =
            4.0 * root_fraction_product * hotloop.a12 * hotloop.green_a[index] +
            4.0 * hotloop.fb * hotloop.a22 * hotloop.green_b[index] +
            2.0 * hotloop.fb * hotloop.c22 *
                (2.0 * psi_b * log(psi_b) + psi_b) +
            4.0 * root_fraction_product * hotloop.c12 * psi_a -
            hotloop.N * hotloop.b^2 / 3.0 * hotloop.lap_b[index] +
            2.0 * hotloop.chi * psi_b * psi_a^2
        raw = -mu_a * psi_b + mu_b * psi_a
        hotloop.raw_gradient[index] = raw
        gradient[index] = hotloop.dx * raw
    end
    return energy
end

function _diblock_ud_projected_residual!(hotloop::_DiblockUD1DHotLoop,
        theta::AbstractVector{<:Real})
    _diblock_ud_1d_value_gradient!(hotloop.lap_a, hotloop, theta)
    normal2 = 0.0
    normal_dot_gradient = 0.0
    @inbounds for index in eachindex(theta)
        normal = sin(2.0 * theta[index])
        normal2 += normal^2
        normal_dot_gradient += normal * hotloop.raw_gradient[index]
    end
    multiplier = normal_dot_gradient / max(normal2, eps(Float64))
    sum2 = 0.0
    maxabs = 0.0
    @inbounds for index in eachindex(theta)
        projected = hotloop.raw_gradient[index] - multiplier * sin(2.0 * theta[index])
        sum2 += projected^2
        maxabs = max(maxabs, abs(projected))
    end
    return sqrt(sum2 / hotloop.count), maxabs
end

function minimize_diblock_uneyama_doi_lamella(; f::Real=0.5, chiN::Real=12.0,
        L=nothing, nx::Integer=128, mode_count::Integer=3, initial_amplitude::Real=0.5,
        N::Real=1.0, b::Real=1.0, max_iterations::Integer=10_000,
        relaxation_step::Real=2.0e-2, tolerance::Real=1.0e-8,
        gradient_tolerance::Real=5.0e-4, initial_profile=nothing)
    modes = Int(mode_count)
    modes >= 1 || throw(ArgumentError("mode_count must be positive"))
    count = Int(nx)
    count >= 8 || throw(ArgumentError("nx must be at least 8"))
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    period = L === nothing ? 2.0 * pi / sqrt(_diblock_kernel_minimum_k2(; f=ff, N=nn, b=bb)) :
        Float64(L)
    period > 0.0 || throw(ArgumentError("lamella period L must be positive"))

    initial_phi = if initial_profile === nothing
        last(diblock_lamella_profile_from_modes([Float64(initial_amplitude);
                                                  zeros(Float64, modes - 1)];
            f=ff, nx=count, L=period))
    else
        values = Float64.(vec(initial_profile))
        length(values) == count || throw(ArgumentError(
            "initial_profile must contain exactly nx values"))
        all(isfinite, values) || throw(ArgumentError("initial_profile must be finite"))
        all(value -> 0.0 <= value <= 1.0, values) || throw(ArgumentError(
            "initial_profile values must lie in [0, 1]"))
        values
    end
    theta = acos.(sqrt.(clamp.(initial_phi, 1.0e-10, 1.0 - 1.0e-10)))
    _project_diblock_theta_mean!(theta, ff)
    phi = cos.(theta).^2
    step = Float64(relaxation_step)
    step > 0.0 || throw(ArgumentError("relaxation_step must be positive"))
    tol = Float64(tolerance)
    tol > 0.0 || throw(ArgumentError("tolerance must be positive"))
    grad_tol = Float64(gradient_tolerance)
    grad_tol > 0.0 && isfinite(grad_tol) || throw(ArgumentError(
        "gradient_tolerance must be positive and finite"))
    hotloop = _diblock_ud_1d_hotloop(count, ff, chi, period, nn, bb)
    function objective_gradient!(F, G, values)
        energy_value = _diblock_ud_1d_value_gradient!(G, hotloop, values)
        return F === nothing ? nothing : energy_value
    end
    function projected_residual_callback(state)
        gradient = state.g_x
        residual_rms = norm(gradient) / (hotloop.dx * sqrt(hotloop.count))
        residual_maxabs = maximum(abs, gradient) / hotloop.dx
        return residual_rms <= grad_tol && residual_maxabs <= 10.0 * grad_tol
    end
    # theta represents phi_A=cos(theta)^2.  The shared UD-theta manifold uses
    # sin(theta)^2, so targeting 1-f imposes the same composition constraint.
    manifold = DiblockBVK2UDThetaMean(1.0 - ff, 1, (count,))
    optimization = Optim.optimize(
        Optim.NLSolversBase.only_fg!(objective_gradient!), theta,
        Optim.LBFGS(m=20, manifold=manifold,
            linesearch=Optim.LineSearches.BackTracking(order=3)),
        Optim.Options(iterations=Int(max_iterations),
            g_tol=-1.0,
            # The campaign contract is residual-based.  An energy-change stop
            # or an exactly unchanged iterate can otherwise stop L-BFGS before
            # the requested projected force is reached.  Optim uses negative
            # tolerances to disable those convergence channels.
            x_abstol=-1.0, x_reltol=-1.0,
            f_abstol=-1.0, f_reltol=-1.0,
            callback=projected_residual_callback,
            show_trace=false,
            store_trace=false, extended_trace=false))
    theta .= Optim.minimizer(optimization)
    Optim.retract!(manifold, theta)
    energy = _diblock_ud_1d_value_gradient!(nothing, hotloop, theta)
    completed_iterations = Optim.iterations(optimization)

    x = [(idx - 0.5) * period / count for idx in 1:count]
    phi = cos.(theta).^2
    projected_force_norm, projected_force_maxabs =
        _diblock_ud_projected_residual!(hotloop, theta)
    converged = projected_force_norm <= grad_tol
    coefficients = _diblock_cosine_coefficients_from_profile(phi; f=ff, L=period,
        mode_count=modes)
    homogeneous = diblock_uneyama_doi_energy_1d(fill(ff, count); f=ff, chiN=chi,
        L=period, N=nn, b=bb)
    return DiblockBurpLamellaResult(ff, chi, period, count, modes, x, phi,
        coefficients, energy, homogeneous, converged, completed_iterations,
        minimum(phi), maximum(phi), mean(phi), projected_force_norm,
        projected_force_maxabs)
end

function minimize_diblock_ohta_kawasaki_lamella(; f::Real=0.5, chiN::Real=12.0,
        L=nothing, nx::Integer=128, mode_count::Integer=3, initial_amplitude::Real=0.2,
        N::Real=1.0, b::Real=1.0, max_iterations::Integer=10_000,
        relaxation_step::Real=1.0e-2, tolerance::Real=1.0e-8,
        gradient_tolerance::Real=5.0e-4)
    return _minimize_diblock_relaxed_lamella(diblock_ohta_kawasaki_energy_1d,
        _diblock_ohta_kawasaki_chemical_potential_1d; f=f, chiN=chiN, L=L, nx=nx,
        mode_count=mode_count, initial_amplitude=initial_amplitude, N=N, b=b,
        max_iterations=max_iterations, relaxation_step=relaxation_step,
        tolerance=tolerance, gradient_tolerance=gradient_tolerance)
end

function _checked_positive_factor(value::Real, name::AbstractString)
    factor = Float64(value)
    factor > 0.0 && isfinite(factor) ||
        throw(ArgumentError("$(name) must be positive and finite"))
    return factor
end

function _checked_initial_amplitudes(values)
    amplitudes = Float64.(collect(values))
    isempty(amplitudes) && throw(ArgumentError("initial_amplitudes must not be empty"))
    all(value -> value > 0.0 && isfinite(value), amplitudes) ||
        throw(ArgumentError("initial_amplitudes must be positive and finite"))
    return sort(unique(amplitudes))
end

function _checked_period_factor_list(values, name::AbstractString)
    raw_values = collect(values)
    isempty(raw_values) && return Float64[]
    factors = Float64.(raw_values)
    all(value -> value > 0.0 && isfinite(value), factors) ||
        throw(ArgumentError("$(name) must contain only positive finite values"))
    return sort(unique(factors))
end

function _diblock_lamellar_dominant_nonzero_mode(phi::AbstractVector{<:Real};
        maximum_mode::Integer=8)
    values = Float64.(phi)
    count = length(values)
    count >= 4 || throw(ArgumentError("lamellar profile must contain at least four values"))
    modes = min(Int(maximum_mode), count ÷ 2)
    modes >= 1 || throw(ArgumentError("maximum_mode must be positive"))
    centered = values .- mean(values)
    amplitudes = [abs(sum(centered[index] * cis(-2.0 * pi * mode *
        (index - 1) / count) for index in eachindex(centered))) for mode in 1:modes]
    return argmax(amplitudes)
end

function _diblock_lamellar_domain_count(phi::AbstractVector{<:Real};
        contrast_tolerance::Real=1.0e-4)
    values = Float64.(phi)
    all(isfinite, values) || return 0
    contrast = maximum(values) - minimum(values)
    contrast > Float64(contrast_tolerance) || return 0
    # A primitive lamellar repeat contains one connected A-enriched interval.
    # Counting at the conserved mean resolves weak secondary domains that a
    # midrange threshold can hide in strongly asymmetric profiles.
    threshold = mean(values)
    count = 0
    @inbounds for index in eachindex(values)
        previous = values[index == firstindex(values) ? lastindex(values) : index - 1]
        count += previous <= threshold && values[index] > threshold
    end
    return count
end

function _diblock_one_period_lamellar_profile(phi::AbstractVector{<:Real};
        contrast_tolerance::Real=1.0e-4)
    return _diblock_lamellar_domain_count(phi;
        contrast_tolerance=contrast_tolerance) == 1
end

function _period_optimization_brackets(lo::Float64, hi::Float64,
        bootstrap_factors::AbstractVector{Float64}, bootstrap_window::Float64)
    brackets = [(lo=lo, hi=hi, bootstrap_factor=NaN)]
    for factor in bootstrap_factors
        center = clamp(factor, lo, hi)
        left = max(lo, center * (1.0 - bootstrap_window))
        right = min(hi, center * (1.0 + bootstrap_window))
        if right > left && (right - left) > 1.0e-10 * max(abs(center), 1.0)
            push!(brackets, (lo=left, hi=right, bootstrap_factor=center))
        end
    end
    return brackets
end

function _period_progress(progress_label::AbstractString, message::AbstractString)
    isempty(progress_label) && return nothing
    println("[", Libc.strftime("%H:%M:%S", time()), "] ", progress_label, " | ", message)
    flush(stdout)
    return nothing
end

function _period_strategy_symbol(value)
    strategy = value isa Symbol ? value :
        Symbol(replace(lowercase(String(value)), "-" => "_"))
    strategy in (:auto, :brent, :direct_bootstrap, :bootstrap_local) ||
        throw(ArgumentError(
            "period_strategy must be :auto, :brent, :direct_bootstrap, or :bootstrap_local"))
    return strategy
end

function _diblock_period_field_converged(result,
        residual_tolerance, maximum_residual_tolerance)
    result.converged && return true
    residual_tolerance === nothing && return false
    maximum_residual_tolerance === nothing && return false
    return hasproperty(result, :projected_force_norm) &&
        hasproperty(result, :projected_force_maxabs) &&
        isfinite(result.projected_force_norm) &&
        result.projected_force_norm <= Float64(residual_tolerance) &&
        isfinite(result.projected_force_maxabs) &&
        result.projected_force_maxabs <= Float64(maximum_residual_tolerance)
end

function _minimize_diblock_lamella_stress_free(model::AbstractString, fixed_period_solver;
        f::Real=0.5, chiN::Real=12.0, nx::Integer=128, mode_count::Integer=3,
        N::Real=1.0, b::Real=1.0, lower_factor::Real=0.75,
        upper_factor::Real=1.5, initial_amplitudes=(0.2, 0.5, 1.0),
        max_iterations::Integer=10_000, max_period_iterations::Integer=24,
        bootstrap_period_factors=(), bootstrap_window::Real=0.12,
        local_check_fraction::Real=0.01, local_check_tolerance::Real=1.0e-8,
        period_strategy=:auto, progress_label::AbstractString="",
        reference_period=nothing, initial_profile=nothing,
        warm_start_profiles::Bool=false, result_filter=nothing,
        physical_residual_tolerance=nothing,
        physical_max_residual_tolerance=nothing,
        kwargs...)
    lo = _checked_positive_factor(lower_factor, "lower_factor")
    hi = _checked_positive_factor(upper_factor, "upper_factor")
    lo < hi || throw(ArgumentError("lower_factor must be smaller than upper_factor"))
    amplitudes = _checked_initial_amplitudes(initial_amplitudes)
    bootstrap_factors = _checked_period_factor_list(bootstrap_period_factors,
        "bootstrap_period_factors")
    boot_window = Float64(bootstrap_window)
    boot_window > 0.0 && boot_window < 1.0 && isfinite(boot_window) ||
        throw(ArgumentError("bootstrap_window must be finite and between 0 and 1"))
    check_fraction = Float64(local_check_fraction)
    check_fraction > 0.0 && check_fraction < 1.0 && isfinite(check_fraction) ||
        throw(ArgumentError("local_check_fraction must be finite and between 0 and 1"))
    correction_fraction = min(0.05, max(check_fraction, boot_window / 4.0))
    check_tolerance = Float64(local_check_tolerance)
    check_tolerance >= 0.0 && isfinite(check_tolerance) ||
        throw(ArgumentError("local_check_tolerance must be nonnegative and finite"))
    period_iterations = Int(max_period_iterations)
    period_iterations > 0 || throw(ArgumentError("max_period_iterations must be positive"))
    requested_strategy = _period_strategy_symbol(period_strategy)
    strategy = requested_strategy == :auto ?
        (isempty(bootstrap_factors) ? :brent : :bootstrap_local) :
        requested_strategy
    strategy in (:direct_bootstrap, :bootstrap_local) && isempty(bootstrap_factors) &&
        throw(ArgumentError("direct bootstrap period optimization requires bootstrap_period_factors"))
    ff, nn, bb, _ = _diblock_validate(f, N, b, 1.0)
    chi = Float64(chiN)
    isfinite(chi) || throw(ArgumentError("chiN must be finite"))
    # Center the period search on the kernel actually being minimized. Default:
    # the diblock composition-kernel minimum. For other architectures (e.g. ABA
    # triblock) the caller passes `reference_period` from that kernel's own
    # minimum, otherwise the diblock reference misplaces the bracket and it can
    # straddle the 2-period basin.
    reference_period = reference_period === nothing ?
        2.0 * pi / sqrt(_diblock_kernel_minimum_k2(; f=ff, N=nn, b=bb)) :
        Float64(reference_period)
    reference_period > 0.0 || throw(ArgumentError("reference_period must be positive"))
    rg_scale = sqrt(6.0 / (nn * bb^2))
    brackets = _period_optimization_brackets(lo, hi, bootstrap_factors, boot_window)
    continuation_profile = initial_profile === nothing ? nothing :
        Float64.(vec(initial_profile))
    if continuation_profile !== nothing
        length(continuation_profile) == Int(nx) || throw(ArgumentError(
            "initial_profile must contain exactly nx values"))
        all(isfinite, continuation_profile) || throw(ArgumentError(
            "initial_profile must be finite"))
    end
    continuation_amplitude = maximum(amplitudes)
    branch_profiles = Dict{Float64,Vector{NamedTuple}}()
    _period_progress(progress_label, @sprintf(
        "start %s f=%.6g chiN=%.6g strategy=%s brackets=%d amplitudes=%d factor_range=%.6g..%.6g",
        model, ff, chi, string(strategy), length(brackets), length(amplitudes), lo, hi))

    function evaluate_factor!(evaluations, factor::Real, amplitude::Float64)
        period_factor = Float64(factor)
        period = reference_period * period_factor
        seed_profile = nothing
        seed_source = "amplitude"
        if warm_start_profiles
            branch = get!(branch_profiles, amplitude, NamedTuple[])
            if !isempty(branch)
                nearest = branch[argmin(abs(item.factor - period_factor)
                    for item in branch)]
                seed_profile = nearest.profile
                seed_source = @sprintf("period:%.8g", nearest.factor)
            elseif continuation_profile !== nothing &&
                    amplitude == continuation_amplitude
                seed_profile = continuation_profile
                seed_source = "chiN-continuation"
            end
        end
        _period_progress(progress_label, @sprintf(
            "eval amplitude=%.6g factor=%.8g L/Rg=%.8g seed=%s",
            amplitude, period_factor, period * rg_scale, seed_source))
        started = time()
        try
            eval_result = if warm_start_profiles && seed_profile !== nothing
                fixed_period_solver(; f=ff, chiN=chi, L=period, nx=nx,
                    mode_count=mode_count, initial_amplitude=amplitude, N=nn, b=bb,
                    max_iterations=max_iterations, initial_profile=seed_profile,
                    kwargs...)
            else
                fixed_period_solver(; f=ff, chiN=chi, L=period, nx=nx,
                    mode_count=mode_count, initial_amplitude=amplitude, N=nn, b=bb,
                    max_iterations=max_iterations, kwargs...)
            end
            branch_valid = result_filter === nothing || result_filter(eval_result)
            field_converged = _diblock_period_field_converged(eval_result,
                physical_residual_tolerance, physical_max_residual_tolerance)
            if seed_profile !== nothing && !field_converged
                _period_progress(progress_label, @sprintf(
                    "retry amplitude=%.6g factor=%.8g seed=amplitude reason=warm-start-residual",
                    amplitude, period_factor))
                cold_result = fixed_period_solver(; f=ff, chiN=chi, L=period, nx=nx,
                    mode_count=mode_count, initial_amplitude=amplitude, N=nn, b=bb,
                    max_iterations=max_iterations, kwargs...)
                cold_branch_valid = result_filter === nothing || result_filter(cold_result)
                cold_field_converged = _diblock_period_field_converged(cold_result,
                    physical_residual_tolerance, physical_max_residual_tolerance)
                warm_value = eval_result.energy / eval_result.L
                cold_value = cold_result.energy / cold_result.L
                warm_rank = (branch_valid && field_converged ? 0 :
                    branch_valid ? 1 : 2, isfinite(warm_value) ? warm_value : Inf)
                cold_rank = (cold_branch_valid && cold_field_converged ? 0 :
                    cold_branch_valid ? 1 : 2, isfinite(cold_value) ? cold_value : Inf)
                if cold_rank < warm_rank
                    eval_result = cold_result
                    branch_valid = cold_branch_valid
                    field_converged = cold_field_converged
                    seed_source = "amplitude-retry"
                end
            end
            value = eval_result.energy / eval_result.L
            finite_value = isfinite(value) && branch_valid ? value : Inf
            item = (factor=period_factor, objective=finite_value, result=eval_result,
                amplitude=amplitude)
            push!(evaluations, item)
            if warm_start_profiles && field_converged && branch_valid &&
                    isfinite(finite_value)
                branch = get!(branch_profiles, amplitude, NamedTuple[])
                push!(branch, (factor=period_factor,
                    profile=Float64.(eval_result.phi_a)))
            end
            _period_progress(progress_label, @sprintf(
                "done amplitude=%.6g factor=%.8g objective=%.10g converged=%s branch_valid=%s iterations=%d elapsed=%.2fs",
                amplitude, period_factor, finite_value, string(eval_result.converged),
                string(branch_valid), eval_result.iterations, time() - started))
            return item
        catch err
            item = (factor=period_factor, objective=Inf, result=nothing,
                amplitude=amplitude)
            push!(evaluations, item)
            _period_progress(progress_label, @sprintf(
                "failed amplitude=%.6g factor=%.8g elapsed=%.2fs error=%s",
                amplitude, period_factor, time() - started, sprint(showerror, err)))
            return item
        end
    end

    finite_period_items(items) = [item for item in items if isfinite(item.objective) &&
        item.result !== nothing]

    function best_period_item(items)
        finite = finite_period_items(items)
        isempty(finite) && return nothing
        converged = [item for item in finite if
            _diblock_period_field_converged(item.result,
                physical_residual_tolerance, physical_max_residual_tolerance)]
        candidates = isempty(converged) ? finite : converged
        return candidates[argmin([item.objective for item in candidates])]
    end

    function maybe_parabolic_period_item!(evaluations, left, center, right, amplitude)
        all(item -> item !== nothing && isfinite(item.objective), (left, center, right)) ||
            return nothing
        x1, y1 = left.factor, left.objective
        x2, y2 = center.factor, center.objective
        x3, y3 = right.factor, right.objective
        denominator = (x1 - x2) * (x1 - x3) * (x2 - x3)
        abs(denominator) > eps(Float64) || return nothing
        quadratic = (x3 * (y2 - y1) + x2 * (y1 - y3) + x1 * (y3 - y2)) /
            denominator
        linear = (x3^2 * (y1 - y2) + x2^2 * (y3 - y1) +
            x1^2 * (y2 - y3)) / denominator
        quadratic > 0.0 && isfinite(quadratic) && isfinite(linear) || return nothing
        candidate_factor = -linear / (2.0 * quadratic)
        lower = min(x1, x2, x3)
        upper = max(x1, x2, x3)
        lower < candidate_factor < upper || return nothing
        if minimum(abs(candidate_factor - item.factor) for item in (left, center, right)) <=
                1.0e-6 * max(1.0, abs(candidate_factor))
            return nothing
        end
        return evaluate_factor!(evaluations, candidate_factor, amplitude)
    end

    function bootstrap_local_candidate!(evaluations, target_factor::Float64,
            amplitude::Float64)
        center = evaluate_factor!(evaluations, target_factor, amplitude)
        left_factor = target_factor * (1.0 - check_fraction)
        right_factor = target_factor * (1.0 + check_fraction)
        left = left_factor > lo ?
            evaluate_factor!(evaluations, left_factor, amplitude) : nothing
        right = right_factor < hi ?
            evaluate_factor!(evaluations, right_factor, amplitude) : nothing
        best = best_period_item([item for item in (center, left, right) if item !== nothing])
        center_finite = isfinite(center.objective)
        if center_finite && left !== nothing && right !== nothing
            maybe_item = maybe_parabolic_period_item!(evaluations, left, center, right,
                amplitude)
            if maybe_item !== nothing
                best = best_period_item([item for item in (best, maybe_item)
                    if item !== nothing])
            end
        end
        center_finite || return best

        direction = 0
        if left !== nothing && isfinite(left.objective) &&
           left.objective < center.objective &&
           (right === nothing || !isfinite(right.objective) || left.objective <= right.objective)
            direction = -1
            current = left
            previous = center
        elseif right !== nothing && isfinite(right.objective) &&
               right.objective < center.objective
            direction = 1
            current = right
            previous = center
        else
            return best
        end

        for _ in 2:period_iterations
            next_factor = current.factor * (1.0 + direction * correction_fraction)
            lo < next_factor < hi || break
            next_item = evaluate_factor!(evaluations, next_factor, amplitude)
            if !isfinite(next_item.objective)
                break
            end
            if next_item.objective < current.objective
                previous, current = current, next_item
                best = best_period_item([item for item in (best, current) if item !== nothing])
            else
                left_bracket, center_bracket, right_bracket =
                    direction < 0 ? (next_item, current, previous) :
                    (previous, current, next_item)
                maybe_item = maybe_parabolic_period_item!(evaluations, left_bracket,
                    center_bracket, right_bracket, amplitude)
                best = best_period_item([item for item in (best, current, maybe_item)
                    if item !== nothing])
                break
            end
        end
        return best
    end

    best = nothing
    optimizer_name = "Brent"
    optimizer_converged = false
    outer_iterations = 0
    if strategy in (:direct_bootstrap, :bootstrap_local)
        target_factor = clamp(bootstrap_factors[end], lo, hi)
        evaluations = Vector{NamedTuple}()
        _period_progress(progress_label, @sprintf(
            "%s factor=%.8g correction_step=%.6g source_factors=%s",
            strategy == :direct_bootstrap ? "direct bootstrap" : "bootstrap local",
            target_factor, correction_fraction, join(string.(bootstrap_factors), ",")))
        for amplitude in amplitudes
            if strategy == :direct_bootstrap
                evaluate_factor!(evaluations, target_factor, amplitude)
            else
                bootstrap_local_candidate!(evaluations, target_factor, amplitude)
            end
        end
        finite = finite_period_items(evaluations)
        isempty(finite) && throw(ErrorException(
            "all $(strategy == :direct_bootstrap ? "direct-bootstrap" : "bootstrap-local") $(model) evaluations failed"))
        selected = best_period_item(evaluations)
        best = (
            selected=selected,
            amplitude=selected.amplitude,
            bootstrap_factor=target_factor,
        )
        optimizer_name = strategy == :direct_bootstrap ? "DirectBootstrap" : "BootstrapLocal"
        optimizer_converged = _diblock_period_field_converged(selected.result,
            physical_residual_tolerance, physical_max_residual_tolerance)
        outer_iterations = length(evaluations)
    else
        for amplitude in amplitudes
            for bracket in brackets
                evaluations = Vector{NamedTuple}()
                _period_progress(progress_label, @sprintf(
                    "bracket start amplitude=%.6g range=%.8g..%.8g bootstrap_factor=%.8g",
                    amplitude, bracket.lo, bracket.hi, bracket.bootstrap_factor))
                function objective(factor)
                    return evaluate_factor!(evaluations, factor, amplitude).objective
                end
                bracket_started = time()
                opt = Optim.optimize(objective, bracket.lo, bracket.hi, Optim.Brent();
                    iterations=period_iterations)
                finite = [item for item in evaluations if isfinite(item.objective) &&
                    item.result !== nothing]
                isempty(finite) && continue
                converged = [item for item in finite if
                    _diblock_period_field_converged(item.result,
                        physical_residual_tolerance,
                        physical_max_residual_tolerance)]
                candidates = isempty(converged) ? finite : converged
                selected = candidates[argmin([item.objective for item in candidates])]
                candidate = (
                    selected=selected,
                    opt=opt,
                    amplitude=amplitude,
                    bootstrap_factor=bracket.bootstrap_factor,
                )
                _period_progress(progress_label, @sprintf(
                    "bracket done amplitude=%.6g range=%.8g..%.8g evals=%d selected_factor=%.8g selected_objective=%.10g elapsed=%.2fs",
                    amplitude, bracket.lo, bracket.hi, length(evaluations),
                    selected.factor, selected.objective, time() - bracket_started))
                if best === nothing || selected.objective < best.selected.objective
                    best = candidate
                    optimizer_converged = Optim.converged(opt)
                    outer_iterations = Optim.iterations(opt)
                end
            end
        end
        best === nothing && throw(ErrorException(
            "all stress-free $(model) period optimization evaluations failed"))
    end

    selected_result = best.selected.result
    validation_evaluations = Vector{NamedTuple}()
    selected_factor = best.selected.factor
    left_factor = selected_factor * (1.0 - check_fraction)
    right_factor = selected_factor * (1.0 + check_fraction)
    left_inside = left_factor > lo
    right_inside = right_factor < hi
    center_item = best.selected
    left_item = left_inside ?
        evaluate_factor!(validation_evaluations, left_factor, best.amplitude) :
        (factor=NaN, objective=Inf, result=nothing)
    right_item = right_inside ?
        evaluate_factor!(validation_evaluations, right_factor, best.amplitude) :
        (factor=NaN, objective=Inf, result=nothing)
    tolerance = check_tolerance * max(1.0, abs(best.selected.objective))
    boundary_limited = !(left_inside && right_inside)
    local_minimum_check_pass = !boundary_limited &&
        isfinite(left_item.objective) && isfinite(right_item.objective) &&
        left_item.objective > best.selected.objective + tolerance &&
        right_item.objective > best.selected.objective + tolerance
    if !local_minimum_check_pass && length(amplitudes) > 1
        validation_amplitudes = [amplitude for amplitude in amplitudes
            if amplitude != best.amplitude]
        if left_inside
            left_items = Any[left_item]
            for amplitude in validation_amplitudes
                push!(left_items,
                    evaluate_factor!(validation_evaluations, left_factor, amplitude))
            end
            left_item = best_period_item(left_items)
            left_item === nothing &&
                (left_item = (factor=NaN, objective=Inf, result=nothing))
        end
        if right_inside
            right_items = Any[right_item]
            for amplitude in validation_amplitudes
                push!(right_items,
                    evaluate_factor!(validation_evaluations, right_factor, amplitude))
            end
            right_item = best_period_item(right_items)
            right_item === nothing &&
                (right_item = (factor=NaN, objective=Inf, result=nothing))
        end
        local_minimum_check_pass = !boundary_limited &&
            isfinite(left_item.objective) && isfinite(right_item.objective) &&
            left_item.objective > best.selected.objective + tolerance &&
            right_item.objective > best.selected.objective + tolerance
    end
    bootstrap_hint = best.bootstrap_factor
    _period_progress(progress_label, @sprintf(
        "selected factor=%.8g L/Rg=%.8g objective=%.10g local_left=%.10g local_right=%.10g local_pass=%s boundary=%s",
        best.selected.factor, selected_result.L * rg_scale, best.selected.objective,
        left_item.objective, right_item.objective,
        string(local_minimum_check_pass), string(boundary_limited)))
    return DiblockLamellaPeriodOptimizationResult(string(model), selected_result,
        reference_period, best.selected.factor, selected_result.L, selected_result.L * rg_scale,
        best.selected.objective, optimizer_name, optimizer_converged,
        outer_iterations, best.amplitude, lo, hi,
        !isempty(bootstrap_factors), bootstrap_hint, boot_window,
        center_item.factor, center_item.objective,
        left_inside ? left_factor : NaN, left_item.objective,
        right_inside ? right_factor : NaN, right_item.objective,
        check_fraction, local_minimum_check_pass, boundary_limited)
end

function minimize_diblock_burp_lamella_stress_free(; f::Real=0.5,
        chiN::Real=12.0, nx::Integer=128, mode_count::Integer=3,
        initial_amplitudes=(0.2, 0.5, 1.0), N::Real=1.0, b::Real=1.0,
        nquad::Integer=16, max_iterations::Integer=10_000,
        max_period_iterations::Integer=24, lower_factor::Real=0.75,
        upper_factor::Real=1.5, relaxation_step::Real=1.0e-2,
        tolerance::Real=1.0e-8, gradient_tolerance::Real=5.0e-4,
        bootstrap_period_factors=(),
        bootstrap_window::Real=0.12, local_check_fraction::Real=0.01,
        local_check_tolerance::Real=1.0e-8, period_strategy=:auto,
        progress_label::AbstractString="")
    return _minimize_diblock_lamella_stress_free("BURP-TI",
        minimize_diblock_burp_lamella; f=f, chiN=chiN, nx=nx,
        mode_count=mode_count, initial_amplitudes=initial_amplitudes, N=N, b=b,
        lower_factor=lower_factor, upper_factor=upper_factor,
        max_iterations=max_iterations, max_period_iterations=max_period_iterations,
        bootstrap_period_factors=bootstrap_period_factors,
        bootstrap_window=bootstrap_window, local_check_fraction=local_check_fraction,
        local_check_tolerance=local_check_tolerance, period_strategy=period_strategy,
        progress_label=progress_label,
        nquad=nquad,
        relaxation_step=relaxation_step, tolerance=tolerance,
        gradient_tolerance=gradient_tolerance)
end

