function _slit_model_symbol(model)
    symbol = Symbol(model)
    symbol in (:urp_ti, :vk1) || throw(ArgumentError("slit model must be :urp_ti or :vk1"))
    return symbol
end

function slit_integral(values::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(values) == grid.Nz || throw(DimensionMismatch("slit vector length must match grid.Nz"))
    return sum(Float64(values[i]) * grid.weights[i] for i in 1:grid.Nz)
end

function normalize_slit_density(values::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(values) == grid.Nz || throw(DimensionMismatch("slit vector length must match grid.Nz"))
    raw = Float64.(values)
    minimum(raw) > 0.0 || throw(DomainError(minimum(raw), "slit density must be positive before normalization"))
    integral = slit_integral(raw, grid)
    integral > 0.0 || throw(DomainError(integral, "slit density integral must be positive"))
    return raw .* (grid.L / integral)
end

function _slit_validate_phi(phi::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(phi) == grid.Nz || throw(DimensionMismatch("slit density length must match grid.Nz"))
    minimum(phi) > 0.0 || throw(DomainError(minimum(phi), "slit density must be strictly positive"))
    return nothing
end

function _slit_entropy_density(phi::Real)
    value = Float64(phi)
    value <= 0.0 && throw(DomainError(value, "entropy density requires phi > 0"))
    return value * log(value) - value + 1.0
end

function _slit_local_potential_coeffs(coeffs)::NTuple{3,Float64}
    length(coeffs) == 3 || throw(ArgumentError("local_potential_coeffs must contain exactly three values"))
    values = (Float64(coeffs[1]), Float64(coeffs[2]), Float64(coeffs[3]))
    all(isfinite, values) || throw(ArgumentError("local_potential_coeffs must be finite"))
    return values
end

function _slit_lateral_gradient_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("lateral_gradient_coeff must be finite"))
    coeff >= 0.0 || throw(ArgumentError("lateral_gradient_coeff must be nonnegative"))
    return coeff
end

function _slit_lateral_variance_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("lateral_variance_coeff must be finite"))
    coeff >= 0.0 || throw(ArgumentError("lateral_variance_coeff must be nonnegative"))
    return coeff
end

function _slit_lateral_fraction_z_gradient_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("lateral_fraction_z_gradient_coeff must be finite"))
    coeff >= 0.0 || throw(ArgumentError("lateral_fraction_z_gradient_coeff must be nonnegative"))
    return coeff
end

function _slit_profile_entropy_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("profile_entropy_coeff must be finite"))
    return coeff
end

function _slit_projected_entropy_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("projected_entropy_coeff must be finite"))
    return coeff
end

function _slit_projected_local_potential_coeffs(coeffs)::NTuple{3,Float64}
    return _slit_local_potential_coeffs(coeffs)
end

_slit_has_projected_local_potential(coeffs) =
    _slit_projected_local_potential_coeffs(coeffs) != (0.0, 0.0, 0.0)

function _slit_projected_quadratic_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("projected_quadratic_coeff must be finite"))
    return coeff
end

function _slit_projected_quadratic_coeffs(values)
    values === nothing && return Float64[]
    coeffs = Float64.(collect(values))
    all(isfinite, coeffs) ||
        throw(ArgumentError("projected_quadratic_coeffs must be finite"))
    return coeffs
end

function _slit_projected_profile_kernel_matrix(values)
    values === nothing && return zeros(Float64, 0, 0)
    if values isa Tuple && isempty(values)
        return zeros(Float64, 0, 0)
    elseif values isa AbstractVector && isempty(values)
        return zeros(Float64, 0, 0)
    end
    matrix = Float64.(values)
    ndims(matrix) == 2 ||
        throw(ArgumentError("projected_profile_kernel_matrix must be a matrix"))
    size(matrix, 1) == size(matrix, 2) ||
        throw(DimensionMismatch("projected_profile_kernel_matrix must be square"))
    all(isfinite, matrix) ||
        throw(ArgumentError("projected_profile_kernel_matrix entries must be finite"))
    if !isapprox(matrix, transpose(matrix); rtol=1.0e-10, atol=1.0e-12)
        throw(ArgumentError("projected_profile_kernel_matrix must be symmetric"))
    end
    return 0.5 .* (matrix .+ transpose(matrix))
end

_slit_has_projected_profile_kernel(matrix) =
    size(_slit_projected_profile_kernel_matrix(matrix), 1) > 0

_slit_join_float_values(values) =
    join((@sprintf("%.12g", Float64(value)) for value in values), ";")

_slit_join_string_values(values) = join((String(value) for value in values), ";")

_slit_matrix_trace(matrix::AbstractMatrix{<:Real}) =
    isempty(matrix) ? 0.0 : sum(Float64(matrix[i, i]) for i in 1:min(size(matrix)...))

_slit_matrix_max_abs(matrix::AbstractMatrix{<:Real}) =
    isempty(matrix) ? 0.0 : maximum(abs.(Float64.(matrix)))

function _slit_projected_entropy_reference(reference, grid::SlitGrid1D)
    reference === nothing && return nothing
    length(reference) == grid.Nz ||
        throw(DimensionMismatch("projected entropy reference length must match slit grid"))
    values = Float64.(reference)
    minimum(values) > 0.0 ||
        throw(DomainError(minimum(values), "projected entropy reference must be positive"))
    integral = slit_integral(values, grid)
    isapprox(integral, grid.L; atol=1.0e-8, rtol=1.0e-8) ||
        throw(ArgumentError("projected entropy reference must be normalized on the slit grid"))
    return values
end

function _slit_projected_quadratic_reference(reference, grid::SlitGrid1D)
    reference === nothing && return nothing
    return _slit_projected_entropy_reference(reference, grid)
end

function _slit_projected_local_potential_reference(reference, grid::SlitGrid1D)
    reference === nothing && return nothing
    return _slit_projected_entropy_reference(reference, grid)
end

function _slit_projected_profile_kernel_reference(reference, grid::SlitGrid1D)
    reference === nothing && return nothing
    return _slit_projected_entropy_reference(reference, grid)
end

function _slit_normalized_projected_weight(values::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(values) == grid.Nz ||
        throw(DimensionMismatch("projected quadratic weight length must match slit grid"))
    weights = Float64.(values)
    all(isfinite, weights) || throw(ArgumentError("projected quadratic weights must be finite"))
    minimum(weights) >= 0.0 ||
        throw(DomainError(minimum(weights), "projected quadratic weights must be nonnegative"))
    integral = slit_integral(weights, grid)
    integral > 0.0 || throw(ArgumentError("projected quadratic weights must have positive integral"))
    return weights .* (grid.L / integral)
end

function _slit_projected_quadratic_weight(weight, grid::SlitGrid1D; wall_width::Real=0.2)
    if weight === nothing || weight === :uniform || weight == "uniform"
        return ones(Float64, grid.Nz)
    elseif weight === :wall || weight == "wall"
        width = Float64(wall_width)
        width > 0.0 || throw(ArgumentError("projected_quadratic_wall_width must be positive"))
        values = [exp(-z / width) + exp(-(grid.L - z) / width) for z in grid.z]
        return _slit_normalized_projected_weight(values, grid)
    elseif weight === :center || weight == "center"
        width = Float64(wall_width)
        width > 0.0 || throw(ArgumentError("projected_quadratic_wall_width must be positive"))
        center = 0.5 * grid.L
        values = [exp(-0.5 * ((z - center) / width)^2) for z in grid.z]
        return _slit_normalized_projected_weight(values, grid)
    elseif weight isa AbstractVector
        return _slit_normalized_projected_weight(weight, grid)
    end
    throw(ArgumentError(
        "projected_quadratic_weight must be :uniform, :wall, :center, nothing, or a nonnegative vector"))
end

function _slit_resolve_projected_entropy_reference(
    reference,
    coeff::Real,
    saddle_phi::AbstractVector{<:Real},
    grid::SlitGrid1D,
)
    projected_coeff = _slit_projected_entropy_coeff(coeff)
    if projected_coeff == 0.0
        return nothing, "none"
    end
    if reference === nothing || reference === :saddle || reference == "saddle"
        values = normalize_slit_density(saddle_phi, grid)
        return _slit_projected_entropy_reference(values, grid), "saddle"
    elseif reference isa AbstractVector
        return _slit_projected_entropy_reference(reference, grid), "explicit_vector"
    elseif reference === :none || reference == "none"
        throw(ArgumentError(
            "projected_entropy_reference cannot be :none when projected_entropy_coeff is nonzero"))
    end
    throw(ArgumentError(
        "projected_entropy_reference must be :saddle, :none, nothing, or a positive normalized vector"))
end

function _slit_resolve_projected_local_potential_reference(
    reference,
    coeffs,
    saddle_phi::AbstractVector{<:Real},
    grid::SlitGrid1D,
)
    if !_slit_has_projected_local_potential(coeffs)
        return nothing, "none"
    end
    if reference === nothing || reference === :saddle || reference == "saddle"
        values = normalize_slit_density(saddle_phi, grid)
        return _slit_projected_local_potential_reference(values, grid), "saddle"
    elseif reference isa AbstractVector
        return _slit_projected_local_potential_reference(reference, grid), "explicit_vector"
    elseif reference === :none || reference == "none"
        throw(ArgumentError(
            "projected_local_potential_reference cannot be :none when projected_local_potential_coeffs are nonzero"))
    end
    throw(ArgumentError(
        "projected_local_potential_reference must be :saddle, :none, nothing, or a positive normalized vector"))
end

function _slit_resolve_projected_quadratic_reference(
    reference,
    coeff::Real,
    saddle_phi::AbstractVector{<:Real},
    grid::SlitGrid1D,
)
    projected_coeff = _slit_projected_quadratic_coeff(coeff)
    if projected_coeff == 0.0
        return nothing, "none"
    end
    if reference === nothing || reference === :saddle || reference == "saddle"
        values = normalize_slit_density(saddle_phi, grid)
        return _slit_projected_quadratic_reference(values, grid), "saddle"
    elseif reference isa AbstractVector
        return _slit_projected_quadratic_reference(reference, grid), "explicit_vector"
    elseif reference === :none || reference == "none"
        throw(ArgumentError(
            "projected_quadratic_reference cannot be :none when projected_quadratic_coeff is nonzero"))
    end
    throw(ArgumentError(
        "projected_quadratic_reference must be :saddle, :none, nothing, or a positive normalized vector"))
end

function _slit_resolve_projected_profile_kernel_reference(
    reference,
    matrix,
    saddle_phi::AbstractVector{<:Real},
    grid::SlitGrid1D,
)
    kernel = _slit_projected_profile_kernel_matrix(matrix)
    if size(kernel, 1) == 0
        return nothing, "none"
    end
    if reference === nothing || reference === :saddle || reference == "saddle"
        values = normalize_slit_density(saddle_phi, grid)
        return _slit_projected_profile_kernel_reference(values, grid), "saddle"
    elseif reference isa AbstractVector
        return _slit_projected_profile_kernel_reference(reference, grid), "explicit_vector"
    elseif reference === :none || reference == "none"
        throw(ArgumentError(
            "projected_profile_kernel_reference cannot be :none when projected_profile_kernel_matrix is nonempty"))
    end
    throw(ArgumentError(
        "projected_profile_kernel_reference must be :saddle, :none, nothing, or a positive normalized vector"))
end

function _slit_resolve_projected_quadratic_weight(
    weight,
    coeff::Real,
    grid::SlitGrid1D;
    wall_width::Real=0.2,
)
    projected_coeff = _slit_projected_quadratic_coeff(coeff)
    if projected_coeff == 0.0
        return nothing, "none"
    end
    source = if weight === nothing
        "uniform"
    elseif weight isa Symbol
        String(weight)
    elseif weight isa AbstractString
        String(weight)
    elseif weight isa AbstractVector
        "explicit_vector"
    else
        "unknown"
    end
    values = _slit_projected_quadratic_weight(weight, grid; wall_width=wall_width)
    return values, source
end

function _slit_projected_weight_source(weight)
    if weight === nothing
        return "uniform"
    elseif weight isa Symbol
        return String(weight)
    elseif weight isa AbstractString
        return String(weight)
    elseif weight isa AbstractVector
        return "explicit_vector"
    end
    return "unknown"
end

function _slit_numeric_vector(value, grid::SlitGrid1D)
    value isa AbstractVector || return false
    length(value) == grid.Nz || return false
    return all(item -> item isa Real, value)
end

function _slit_resolve_projected_quadratic_terms(
    coeffs,
    reference,
    weights,
    saddle_phi::AbstractVector{<:Real},
    grid::SlitGrid1D;
    wall_width::Real=0.2,
)
    values = _slit_projected_quadratic_coeffs(coeffs)
    isempty(values) && return values, Vector{Float64}[], Vector{Float64}[], "none", "none"
    base_reference, reference_source =
        _slit_resolve_projected_quadratic_reference(reference, 1.0, saddle_phi, grid)
    references = [copy(base_reference) for _ in eachindex(values)]

    weight_items = if weights === nothing || (weights isa Tuple && isempty(weights)) ||
                      (weights isa AbstractVector && isempty(weights))
        fill(:uniform, length(values))
    elseif _slit_numeric_vector(weights, grid)
        fill(weights, length(values))
    else
        collected = collect(weights)
        length(collected) == length(values) ||
            throw(DimensionMismatch(
                "projected_quadratic_weights length must match projected_quadratic_coeffs"))
        collected
    end
    resolved_weights = [
        _slit_projected_quadratic_weight(item, grid; wall_width=wall_width)
        for item in weight_items
    ]
    weight_sources = [_slit_projected_weight_source(item) for item in weight_items]
    return values, references, resolved_weights, reference_source,
           _slit_join_string_values(weight_sources)
end

function _slit_local_potential_density(phi::Real, coeffs::NTuple{3,Float64})
    value = Float64(phi)
    value <= 0.0 && throw(DomainError(value, "local potential requires phi > 0"))
    eta = value - 1.0
    a1, a2, a3 = coeffs
    return a1 * _slit_entropy_density(value) + 0.5 * a2 * eta^2 +
           a3 * (eta - atan(eta))
end

function _slit_local_potential_derivative(phi::Real, coeffs::NTuple{3,Float64})
    value = Float64(phi)
    value <= 0.0 && throw(DomainError(value, "local potential derivative requires phi > 0"))
    eta = value - 1.0
    a1, a2, a3 = coeffs
    return a1 * log(value) + a2 * eta + a3 * eta^2 / (1.0 + eta^2)
end

function _slit_local_potential_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    coeffs,
)
    local_coeffs = _slit_local_potential_coeffs(coeffs)
    local_coeffs == (0.0, 0.0, 0.0) && return 0.0
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    return sum(grid.weights[i] * _slit_local_potential_density(density[i], local_coeffs)
        for i in 1:grid.Nz)
end

function _slit_projected_local_potential_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
    coeffs,
)
    local_coeffs = _slit_projected_local_potential_coeffs(coeffs)
    local_coeffs == (0.0, 0.0, 0.0) && return 0.0
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    _slit_validate_phi(density, grid)
    ref = _slit_projected_local_potential_reference(reference, grid)
    ref === nothing && throw(ArgumentError("projected local-potential reference is required"))
    derivatives = [_slit_local_potential_derivative(value, local_coeffs) for value in ref]
    mu_bar = slit_integral(derivatives, grid) / grid.L
    total = 0.0
    for i in 1:grid.Nz
        phi_i = Float64(density[i])
        ref_i = ref[i]
        tangent_i = derivatives[i] - mu_bar
        total += grid.weights[i] *
                 (_slit_local_potential_density(phi_i, local_coeffs) -
                  _slit_local_potential_density(ref_i, local_coeffs) -
                  tangent_i * (phi_i - ref_i))
    end
    return total
end

function _slit_profile_entropy_integral(density::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    _slit_validate_phi(density, grid)
    values = Float64.(density)
    return slit_integral(values .* log.(values), grid)
end

function _slit_projected_entropy_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
)
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    _slit_validate_phi(density, grid)
    ref = _slit_projected_entropy_reference(reference, grid)
    ref === nothing && throw(ArgumentError("projected entropy reference is required"))
    mu_bar = slit_integral(log.(ref) .+ 1.0, grid) / grid.L
    total = 0.0
    for i in 1:grid.Nz
        phi_i = Float64(density[i])
        ref_i = ref[i]
        total += grid.weights[i] *
                 (phi_i * log(phi_i) - ref_i * log(ref_i) -
                  (log(ref_i) + 1.0 - mu_bar) * (phi_i - ref_i))
    end
    return total
end

function _slit_projected_quadratic_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
    weight,
)
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    _slit_validate_phi(density, grid)
    ref = _slit_projected_quadratic_reference(reference, grid)
    ref === nothing && throw(ArgumentError("projected quadratic reference is required"))
    weights = _slit_projected_quadratic_weight(weight, grid)
    mu_bar = slit_integral(weights .* ref, grid) / grid.L
    total = 0.0
    for i in 1:grid.Nz
        phi_i = Float64(density[i])
        ref_i = ref[i]
        weight_i = weights[i]
        total += grid.weights[i] *
                 (0.5 * weight_i * (phi_i^2 - ref_i^2) -
                  (weight_i * ref_i - mu_bar) * (phi_i - ref_i))
    end
    return total
end

function _slit_projected_quadratic_terms_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    coeffs,
    references,
    weights,
)
    coeff_values = _slit_projected_quadratic_coeffs(coeffs)
    isempty(coeff_values) && return 0.0
    length(references) == length(coeff_values) ||
        throw(DimensionMismatch(
            "projected quadratic references length must match coefficient length"))
    length(weights) == length(coeff_values) ||
        throw(DimensionMismatch(
            "projected quadratic weights length must match coefficient length"))
    total = 0.0
    for idx in eachindex(coeff_values)
        total += coeff_values[idx] *
                 _slit_projected_quadratic_integral(
                     density, grid, references[idx], weights[idx])
    end
    return total
end

function _slit_projected_profile_kernel_shape(grid::SlitGrid1D, mode::Integer)
    m = Int(mode)
    m >= 1 || throw(ArgumentError("projected profile-kernel mode must be positive"))
    shape = [
        cos(2.0 * pi * m * (grid.z[k] / grid.L - 0.5))
        for k in 1:grid.Nz
    ]
    shape .-= slit_integral(shape, grid) / grid.L
    return shape
end

function _slit_projected_profile_kernel_shape_matrix(grid::SlitGrid1D, mode_count::Integer)
    count = Int(mode_count)
    count >= 0 || throw(ArgumentError("projected profile-kernel mode count must be nonnegative"))
    count <= max(1, grid.Nz - 1) ||
        throw(DimensionMismatch("projected profile-kernel mode count exceeds the slit grid"))
    matrix = Matrix{Float64}(undef, grid.Nz, count)
    for mode in 1:count
        matrix[:, mode] .= _slit_projected_profile_kernel_shape(grid, mode)
    end
    return matrix
end

function _slit_projected_profile_kernel_gram(grid::SlitGrid1D, mode_count::Integer)
    shapes = _slit_projected_profile_kernel_shape_matrix(grid, mode_count)
    count = size(shapes, 2)
    gram = zeros(Float64, count, count)
    for row in 1:count, col in row:count
        value = slit_integral(shapes[:, row] .* shapes[:, col], grid) / grid.L
        gram[row, col] = value
        gram[col, row] = value
    end
    return gram
end

function _slit_profile_from_projected_profile_kernel_coefficients(
    coeffs::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
)
    values = Float64.(coeffs)
    ref = _slit_projected_profile_kernel_reference(reference, grid)
    ref === nothing && throw(ArgumentError("projected profile-kernel reference is required"))
    isempty(values) && return copy(ref)
    shapes = _slit_projected_profile_kernel_shape_matrix(grid, length(values))
    gram = _slit_projected_profile_kernel_gram(grid, length(values))
    amplitudes = gram \ values
    profile = copy(ref)
    for mode in eachindex(amplitudes)
        @views profile .+= amplitudes[mode] .* shapes[:, mode]
    end
    _slit_validate_phi(profile, grid)
    integral = slit_integral(profile, grid)
    isapprox(integral, grid.L; atol=1.0e-10, rtol=1.0e-10) ||
        throw(ArgumentError("projected profile-kernel coefficient profile is not normalized"))
    return profile
end

function _slit_projected_profile_kernel_coefficients(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
    matrix,
)
    kernel = _slit_projected_profile_kernel_matrix(matrix)
    mode_count = size(kernel, 1)
    mode_count == 0 && return Float64[]
    mode_count <= max(1, grid.Nz - 1) ||
        throw(DimensionMismatch("projected_profile_kernel_matrix has more modes than the slit grid"))
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    _slit_validate_phi(density, grid)
    ref = _slit_projected_profile_kernel_reference(reference, grid)
    ref === nothing && throw(ArgumentError("projected profile-kernel reference is required"))
    delta = Float64.(density) .- ref
    coeffs = Vector{Float64}(undef, mode_count)
    for mode in 1:mode_count
        shape = _slit_projected_profile_kernel_shape(grid, mode)
        coeffs[mode] = slit_integral(shape .* delta, grid) / grid.L
    end
    return coeffs
end

function _slit_projected_profile_kernel_integral(
    density::AbstractVector{<:Real},
    grid::SlitGrid1D,
    reference,
    matrix,
)
    kernel = _slit_projected_profile_kernel_matrix(matrix)
    size(kernel, 1) == 0 && return 0.0
    coeffs = _slit_projected_profile_kernel_coefficients(
        density, grid, reference, kernel)
    return 0.5 * sum(coeffs .* (kernel * coeffs))
end

function _slit_3d_field_from_profile_and_lateral_coefficients(
    profile::AbstractVector{<:Real},
    lateral_coeffs::AbstractVector{<:Real},
    lateral_basis::AbstractMatrix{<:Real},
    grid::SlitGrid3D,
)
    _slit_projected_profile_kernel_reference(profile, grid.slit_grid)
    size(lateral_basis, 1) == grid.Nx * grid.Ny * grid.Nz ||
        throw(DimensionMismatch("lateral basis row count must match grid cell count"))
    size(lateral_basis, 2) == length(lateral_coeffs) ||
        throw(DimensionMismatch("lateral basis column count must match lateral coefficient length"))
    lateral_logits = size(lateral_basis, 2) == 0 ?
                     zeros(Float64, grid.Nx * grid.Ny * grid.Nz) :
                     Float64.(lateral_basis) * Float64.(lateral_coeffs)
    field = Array{Float64,3}(undef, grid.Nx, grid.Ny, grid.Nz)
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    for k in 1:grid.Nz
        plane_max = maximum(lateral_logits[linear[i, j, k]]
            for i in 1:grid.Nx, j in 1:grid.Ny)
        plane_raw = Array{Float64,2}(undef, grid.Nx, grid.Ny)
        plane_sum = 0.0
        for i in 1:grid.Nx, j in 1:grid.Ny
            value = exp(lateral_logits[linear[i, j, k]] - plane_max)
            plane_raw[i, j] = value
            plane_sum += value
        end
        plane_mean = plane_sum / (grid.Nx * grid.Ny)
        plane_mean > 0.0 ||
            throw(DomainError(plane_mean, "lateral plane normalization must be positive"))
        for i in 1:grid.Nx, j in 1:grid.Ny
            field[i, j, k] = Float64(profile[k]) * plane_raw[i, j] / plane_mean
        end
    end
    return field
end

function _regularized_lateral_logdet(
    eigenvalues::AbstractVector{<:Real};
    curvature_floor::Real=1.0e-12,
    curvature_regularization::Real=0.0,
)
    lambda = Float64(curvature_regularization)
    isfinite(lambda) && lambda >= 0.0 ||
        throw(ArgumentError("curvature_regularization must be nonnegative and finite"))
    floor_value = max(Float64(curvature_floor), floatmin(Float64))
    isfinite(floor_value) && floor_value > 0.0 ||
        throw(ArgumentError("curvature_floor must be positive and finite"))
    values = Float64.(eigenvalues)
    all(isfinite, values) ||
        throw(ArgumentError("lateral determinant eigenvalues must be finite"))
    if lambda == 0.0
        return 0.5 * sum(log(max(value, floor_value)) for value in values)
    end
    shifted = values .+ lambda
    minimum(shifted) > 0.0 || return Inf
    return 0.5 * sum(log(value) for value in shifted)
end

function _slit_lateral_logdet_for_projected_profile_kernel_coefficients(
    profile_coeffs::AbstractVector{<:Real},
    grid::SlitGrid3D,
    params::SlitParams,
    reference;
    lateral_mode_count::Integer=1,
    lateral_z_basis_count::Integer=0,
    hessian_step::Real=1.0e-4,
    curvature_floor::Real=1.0e-12,
    curvature_regularization::Real=0.0,
)
    lateral_basis = _slit_3d_lateral_spectral_basis(grid;
        lateral_mode_count=lateral_mode_count,
        lateral_z_basis_count=lateral_z_basis_count)
    lateral_count = size(lateral_basis, 2)
    lateral_count > 0 ||
        throw(ArgumentError("lateral determinant requires at least one lateral mode"))
    profile = _slit_profile_from_projected_profile_kernel_coefficients(
        profile_coeffs, grid.slit_grid, reference)
    objective(lateral_coeffs) = slit_hevk1_energy_3d(
        _slit_3d_field_from_profile_and_lateral_coefficients(
            profile, lateral_coeffs, lateral_basis, grid),
        grid, params)
    hessian = _finite_difference_hessian(
        objective, zeros(Float64, lateral_count); step=hessian_step)
    eig = eigvals(Symmetric(0.5 .* (hessian .+ transpose(hessian))))
    return (
        logdet=_regularized_lateral_logdet(eig;
            curvature_floor=curvature_floor,
            curvature_regularization=curvature_regularization),
        min_eigenvalue=minimum(eig),
        max_eigenvalue=maximum(eig),
        negative_eigenvalue_count=count(<(0.0), eig),
        lateral_coefficient_count=lateral_count,
        curvature_regularization=Float64(curvature_regularization),
    )
end

function _slit_projected_profile_kernel_lateral_logdet_matrix(
    grid::SlitGrid3D,
    params::SlitParams,
    reference;
    mode_count::Integer=4,
    lateral_mode_count::Integer=1,
    lateral_z_basis_count::Integer=0,
    lateral_hessian_step::Real=1.0e-4,
    profile_hessian_step::Real=1.0e-4,
    curvature_floor::Real=1.0e-12,
    curvature_regularization::Real=0.0,
)
    count = Int(mode_count)
    count >= 1 || throw(ArgumentError("mode_count must be positive"))
    _slit_projected_profile_kernel_shape_matrix(grid.slit_grid, count)
    ref = _slit_projected_profile_kernel_reference(reference, grid.slit_grid)
    ref === nothing && throw(ArgumentError("projected profile-kernel reference is required"))
    objective(coeffs) =
        _slit_lateral_logdet_for_projected_profile_kernel_coefficients(
            coeffs, grid, params, ref;
            lateral_mode_count=lateral_mode_count,
            lateral_z_basis_count=lateral_z_basis_count,
            hessian_step=lateral_hessian_step,
            curvature_floor=curvature_floor,
            curvature_regularization=curvature_regularization).logdet
    zeros_coeffs = zeros(Float64, count)
    reference_diag =
        _slit_lateral_logdet_for_projected_profile_kernel_coefficients(
            zeros_coeffs, grid, params, ref;
            lateral_mode_count=lateral_mode_count,
            lateral_z_basis_count=lateral_z_basis_count,
            hessian_step=lateral_hessian_step,
            curvature_floor=curvature_floor,
            curvature_regularization=curvature_regularization)
    gradient = _finite_difference_gradient_vector(
        objective, zeros_coeffs; step=profile_hessian_step)
    projected(coeffs) = objective(coeffs) - reference_diag.logdet -
                        dot(gradient, Float64.(coeffs))
    matrix = _finite_difference_hessian(projected, zeros_coeffs;
        step=profile_hessian_step)
    symmetric = 0.5 .* (matrix .+ transpose(matrix))
    return (
        matrix=symmetric,
        reference_gradient=gradient,
        reference_logdet=reference_diag.logdet,
        reference_min_eigenvalue=reference_diag.min_eigenvalue,
        reference_max_eigenvalue=reference_diag.max_eigenvalue,
        reference_negative_eigenvalue_count=reference_diag.negative_eigenvalue_count,
        lateral_coefficient_count=reference_diag.lateral_coefficient_count,
        curvature_regularization=reference_diag.curvature_regularization,
    )
end

function _slit_3d_local_potential_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    coeffs,
)
    local_coeffs = _slit_local_potential_coeffs(coeffs)
    local_coeffs == (0.0, 0.0, 0.0) && return 0.0
    size(density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D density shape must match SlitGrid3D"))
    return grid.cell_volume * sum(_slit_local_potential_density(density[idx], local_coeffs)
        for idx in eachindex(density))
end

function _slit_3d_projected_entropy_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    reference,
)
    size(density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D density shape must match SlitGrid3D"))
    _slit_3d_validate_phi(density, grid)
    ref = _slit_projected_entropy_reference(reference, grid.slit_grid)
    ref === nothing && throw(ArgumentError("projected entropy reference is required"))
    mu_bar = slit_integral(log.(ref) .+ 1.0, grid.slit_grid) / grid.Lz
    total = 0.0
    for k in 1:grid.Nz
        ref_k = ref[k]
        tangent_k = log(ref_k) + 1.0 - mu_bar
        reference_entropy = ref_k * log(ref_k)
        for j in 1:grid.Ny, i in 1:grid.Nx
            phi_ijk = Float64(density[i, j, k])
            total += phi_ijk * log(phi_ijk) - reference_entropy -
                     tangent_k * (phi_ijk - ref_k)
        end
    end
    return grid.cell_volume * total
end

function _slit_3d_projected_local_potential_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    reference,
    coeffs,
)
    local_coeffs = _slit_projected_local_potential_coeffs(coeffs)
    local_coeffs == (0.0, 0.0, 0.0) && return 0.0
    size(density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D density shape must match SlitGrid3D"))
    _slit_3d_validate_phi(density, grid)
    ref = _slit_projected_local_potential_reference(reference, grid.slit_grid)
    ref === nothing && throw(ArgumentError("projected local-potential reference is required"))
    derivatives = [_slit_local_potential_derivative(value, local_coeffs) for value in ref]
    mu_bar = slit_integral(derivatives, grid.slit_grid) / grid.Lz
    total = 0.0
    for k in 1:grid.Nz
        ref_k = ref[k]
        tangent_k = derivatives[k] - mu_bar
        reference_value = _slit_local_potential_density(ref_k, local_coeffs)
        for j in 1:grid.Ny, i in 1:grid.Nx
            phi_ijk = Float64(density[i, j, k])
            total += _slit_local_potential_density(phi_ijk, local_coeffs) -
                     reference_value - tangent_k * (phi_ijk - ref_k)
        end
    end
    return grid.cell_volume * total
end

function _slit_3d_projected_quadratic_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    reference,
    weight,
)
    size(density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D density shape must match SlitGrid3D"))
    _slit_3d_validate_phi(density, grid)
    ref = _slit_projected_quadratic_reference(reference, grid.slit_grid)
    ref === nothing && throw(ArgumentError("projected quadratic reference is required"))
    weights = _slit_projected_quadratic_weight(weight, grid.slit_grid)
    mu_bar = slit_integral(weights .* ref, grid.slit_grid) / grid.Lz
    total = 0.0
    for k in 1:grid.Nz
        ref_k = ref[k]
        weight_k = weights[k]
        tangent_k = weight_k * ref_k - mu_bar
        reference_value = 0.5 * weight_k * ref_k^2
        for j in 1:grid.Ny, i in 1:grid.Nx
            phi_ijk = Float64(density[i, j, k])
            total += 0.5 * weight_k * phi_ijk^2 - reference_value -
                     tangent_k * (phi_ijk - ref_k)
        end
    end
    return grid.cell_volume * total
end

function _slit_3d_projected_quadratic_terms_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    coeffs,
    references,
    weights,
)
    coeff_values = _slit_projected_quadratic_coeffs(coeffs)
    isempty(coeff_values) && return 0.0
    length(references) == length(coeff_values) ||
        throw(DimensionMismatch(
            "projected quadratic references length must match coefficient length"))
    length(weights) == length(coeff_values) ||
        throw(DimensionMismatch(
            "projected quadratic weights length must match coefficient length"))
    total = 0.0
    for idx in eachindex(coeff_values)
        total += coeff_values[idx] *
                 _slit_3d_projected_quadratic_integral(
                     density, grid, references[idx], weights[idx])
    end
    return total
end

function _slit_3d_projected_profile_kernel_integral(
    density::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    reference,
    matrix,
)
    kernel = _slit_projected_profile_kernel_matrix(matrix)
    size(kernel, 1) == 0 && return 0.0
    size(density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D density shape must match SlitGrid3D"))
    _slit_3d_validate_phi(density, grid)
    profile = _slit_3d_xy_profile(density, grid)
    return _slit_projected_profile_kernel_integral(
        profile, grid.slit_grid, reference, kernel)
end

function _slit_j_density(phi::Real)
    value = Float64(phi)
    eta = value - 1.0
    if abs(eta) < 1.0e-6
        return eta / 2.0 - eta^2 / 6.0 + eta^3 / 12.0 - eta^4 / 20.0
    end
    return _slit_entropy_density(value) / eta
end

function slit_low_density_profile(grid::SlitGrid1D)
    profile = [2.0 * sin(pi * z / grid.L)^2 for z in grid.z]
    return normalize_slit_density(profile, grid)
end

function _slit_profile_shape(z::AbstractVector{<:Real}, L::Real, xi::Real, psi::Real)
    length = Float64(L)
    corr = max(Float64(xi), eps(Float64))
    psim = max(Float64(psi), eps(Float64))
    a = psim / (2.0 * corr)
    return [psim^2 * (tanh(a * Float64(zi)) + tanh(a * (length - Float64(zi))) - tanh(a * length))^2 for zi in z]
end

function _slit_midpoint_weights(z::AbstractVector{<:Real}, L::Real)
    isempty(z) && throw(ArgumentError("z cannot be empty"))
    return fill(Float64(L) / length(z), length(z))
end

function _weighted_integral(values::AbstractVector{<:Real}, weights::AbstractVector{<:Real})
    length(values) == length(weights) || throw(DimensionMismatch("values and weights must have the same length"))
    return sum(Float64(values[i]) * Float64(weights[i]) for i in eachindex(values))
end

function slit_reference_profile(z::AbstractVector{<:Real}; B::Real, C::Real, L::Real=1.0, xi=nothing)
    length = Float64(L)
    corr = xi === nothing ? 1.0 / sqrt(max(2.0 * Float64(B) * Float64(C), eps(Float64))) : Float64(xi)
    weights = _slit_midpoint_weights(z, length)
    target = length
    lo = 1.0e-8
    hi = 1.0
    while _weighted_integral(_slit_profile_shape(z, length, corr, hi), weights) < target
        hi *= 2.0
        hi > 1.0e6 && throw(ErrorException("failed to bracket slit reference normalization"))
    end
    for _ in 1:80
        mid = 0.5 * (lo + hi)
        integral = _weighted_integral(_slit_profile_shape(z, length, corr, mid), weights)
        if integral < target
            lo = mid
        else
            hi = mid
        end
    end
    return _slit_profile_shape(z, length, corr, 0.5 * (lo + hi))
end

function _golden_section_minimize(f, lo::Real, hi::Real; iterations::Int=80)
    a = Float64(lo)
    b = Float64(hi)
    a < b || throw(ArgumentError("golden-section interval must satisfy lo < hi"))
    result = Optim.optimize(f, a, b, Optim.GoldenSection(); iterations=iterations)
    return Optim.minimizer(result), Optim.minimum(result)
end

function fit_slit_xi_eff(z::AbstractVector{<:Real}, phi::AbstractVector{<:Real}; L::Real=1.0)
    length(z) == length(phi) || throw(DimensionMismatch("z and phi must have the same length"))
    values = Float64.(phi)
    objective(xi) = begin
        candidate = slit_reference_profile(z; B=1.0, C=1.0, L=L, xi=xi)
        return mean((candidate .- values) .^ 2)
    end
    lo = max(1.0e-3 * Float64(L), 1.0e-5)
    hi = 3.0 * Float64(L)
    scan = exp.(range(log(lo), log(hi); length=96))
    errors = [objective(xi) for xi in scan]
    best = argmin(errors)
    local_lo = best == 1 ? scan[1] : scan[best - 1]
    local_hi = best == length(scan) ? scan[end] : scan[best + 1]
    xi, err = _golden_section_minimize(objective, local_lo, local_hi; iterations=70)
    if errors[best] < err
        xi = scan[best]
        err = errors[best]
    end
    return xi, err
end

function _linear_interpolate_sorted(xs::AbstractVector{<:Real}, ys::AbstractVector{<:Real}, x::Real)
    length(xs) == length(ys) || throw(DimensionMismatch("xs and ys must have the same length"))
    isempty(xs) && throw(ArgumentError("interpolation grid cannot be empty"))
    values = Float64.(xs)
    ordinates = Float64.(ys)
    value = Float64(x)
    value <= values[1] && return ordinates[1]
    value >= values[end] && return ordinates[end]
    idx = searchsortedlast(values, value)
    idx >= length(values) && return ordinates[end]
    t = (value - values[idx]) / (values[idx + 1] - values[idx])
    return (1.0 - t) * ordinates[idx] + t * ordinates[idx + 1]
end

function slit_reference_profile_at_points(
    z::AbstractVector{<:Real};
    B::Real,
    C::Real,
    L::Real=1.0,
    xi::Real,
    normalization_Nz::Integer=2000,
)
    grid = SlitGrid1D(max(16, Int(normalization_Nz)), L)
    profile = slit_reference_profile(grid.z; B=B, C=C, L=L, xi=xi)
    return [_linear_interpolate_sorted(grid.z, profile, zi) for zi in z]
end

function fit_slit_xi_eff_reference_grid(
    z::AbstractVector{<:Real},
    phi::AbstractVector{<:Real};
    B::Real=1.0,
    C::Real=1.0,
    L::Real=1.0,
    normalization_Nz::Integer=2000,
)
    length(z) == length(phi) || throw(DimensionMismatch("z and phi must have the same length"))
    values = Float64.(phi)
    objective(xi) = begin
        candidate = slit_reference_profile_at_points(z; B=B, C=C, L=L, xi=xi,
            normalization_Nz=normalization_Nz)
        return mean((candidate .- values) .^ 2)
    end
    lo = max(1.0e-3 * Float64(L), 1.0e-5)
    hi = 3.0 * Float64(L)
    scan = exp.(range(log(lo), log(hi); length=96))
    errors = [objective(xi) for xi in scan]
    best = argmin(errors)
    local_lo = best == 1 ? scan[1] : scan[best - 1]
    local_hi = best == length(scan) ? scan[end] : scan[best + 1]
    xi, err = _golden_section_minimize(objective, local_lo, local_hi; iterations=70)
    if errors[best] < err
        xi = scan[best]
        err = errors[best]
    end
    return xi, err
end

function _slit_profile_fit_diagnostics(
    observed::AbstractVector{<:Real},
    fitted::AbstractVector{<:Real};
    wall_count::Integer=2,
)
    length(observed) == length(fitted) ||
        throw(DimensionMismatch("observed and fitted profiles must have the same length"))
    values = Float64.(observed)
    predictions = Float64.(fitted)
    residuals = values .- predictions
    mse = mean(residuals .^ 2)
    rmse = sqrt(mse)
    mae = mean(abs.(residuals))
    max_abs_error = maximum(abs.(residuals))
    sse = sum(residuals .^ 2)
    sst = sum((values .- mean(values)) .^ 2)
    r2 = sst <= eps(Float64) ? (sse <= eps(Float64) ? 1.0 : -Inf) : 1.0 - sse / sst
    span = maximum(values) - minimum(values)
    nrmse_range = span <= eps(Float64) ? (rmse <= eps(Float64) ? 0.0 : Inf) : rmse / span
    mean_scale = abs(mean(values))
    nrmse_mean = mean_scale <= eps(Float64) ? (rmse <= eps(Float64) ? 0.0 : Inf) : rmse / mean_scale
    n = length(values)
    count = clamp(Int(wall_count), 1, max(1, fld(n, 2)))
    wall_indices = unique(vcat(collect(1:count), collect((n - count + 1):n)))
    wall_rms = sqrt(mean(residuals[wall_indices] .^ 2))
    quality_pass = (isfinite(r2) && r2 >= 0.95 && nrmse_range <= 0.10) ? 1.0 : 0.0
    return (
        mse=mse,
        rmse=rmse,
        mae=mae,
        max_abs_error=max_abs_error,
        r2=r2,
        nrmse_range=nrmse_range,
        nrmse_mean=nrmse_mean,
        wall_rms=wall_rms,
        quality_pass=quality_pass,
    )
end

function _symmetrize_slit_profile(profile::AbstractVector{<:Real})
    values = Float64.(profile)
    n = length(values)
    return [0.5 * (values[i] + values[n - i + 1]) for i in 1:n]
end

function _symmetrize_profile_traces(profile_traces::Vector{Vector{Float64}})
    n = length(profile_traces)
    n == 0 && return Vector{Vector{Float64}}()
    sample_count = length(profile_traces[1])
    all(length(trace) == sample_count for trace in profile_traces) ||
        throw(DimensionMismatch("all profile traces must have the same sample count"))
    out = [Vector{Float64}(undef, sample_count) for _ in 1:n]
    for i in 1:n
        j = n - i + 1
        for sample in 1:sample_count
            out[i][sample] = 0.5 * (profile_traces[i][sample] + profile_traces[j][sample])
        end
    end
    return out
end

function _profile_mean_and_stderr(profile_traces::Vector{Vector{Float64}})
    return (
        mean_phi=[mean(trace) for trace in profile_traces],
        stderr_phi=[_markov_mean_stderr(trace) for trace in profile_traces],
    )
end

function _write_slit_3d_block_diagnostics(
    outdir::AbstractString,
    chain_profile_traces::Vector{Vector{Vector{Float64}}},
    grid::SlitGrid3D;
    max_blocks::Integer=8,
)
    mkpath(outdir)
    profile_rows = NamedTuple[]
    xi_rows = NamedTuple[]
    block_cap = max(1, Int(max_blocks))
    for (chain_idx, chain_traces) in enumerate(chain_profile_traces)
        length(chain_traces) == grid.Nz ||
            throw(DimensionMismatch("chain profile traces must have one trace per z bin"))
        sample_count = isempty(chain_traces) ? 0 : length(chain_traces[1])
        all(length(trace) == sample_count for trace in chain_traces) ||
            throw(DimensionMismatch("all z traces in a chain must have the same sample count"))
        sample_count == 0 && continue
        block_count = min(block_cap, sample_count)
        block_size = cld(sample_count, block_count)
        for block_idx in 1:block_count
            sample_start = (block_idx - 1) * block_size + 1
            sample_start > sample_count && break
            sample_stop = min(block_idx * block_size, sample_count)
            count = sample_stop - sample_start + 1
            profile = [
                mean(@view chain_traces[k][sample_start:sample_stop])
                for k in 1:grid.Nz
            ]
            xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, profile; L=grid.Lz)
            push!(xi_rows, (
                chain=chain_idx,
                block=block_idx,
                sample_start=sample_start,
                sample_stop=sample_stop,
                sample_count=count,
                xi_eff=xi_eff,
                xi_fit_error=xi_fit_error,
            ))
            for k in 1:grid.Nz
                push!(profile_rows, (
                    chain=chain_idx,
                    block=block_idx,
                    sample_start=sample_start,
                    sample_stop=sample_stop,
                    sample_count=count,
                    z_over_L=grid.z[k] / grid.Lz,
                    phi=profile[k],
                    xi_eff=xi_eff,
                    xi_fit_error=xi_fit_error,
                ))
            end
        end
    end
    profile_blocks_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile_blocks.csv"), profile_rows)
    xi_blocks_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_xi_blocks.csv"), xi_rows)
    return profile_blocks_csv, xi_blocks_csv
end

function _max_finite_or_nan(values)
    finite_values = Float64[v for v in values if isfinite(v)]
    return isempty(finite_values) ? NaN : maximum(finite_values)
end

function _slit_profile_chain_convergence(
    chain_profile_traces::Vector{Vector{Vector{Float64}}},
    pooled_mean::AbstractVector{<:Real},
)
    chain_count = length(chain_profile_traces)
    chain_count < 1 && throw(ArgumentError("at least one profile chain is required"))
    nz = length(pooled_mean)
    all(length(chain_trace) == nz for chain_trace in chain_profile_traces) ||
        throw(DimensionMismatch("chain profile traces must have one trace per z bin"))
    profile_rhats = [
        _chain_rhat([chain_profile_traces[chain_idx][k] for chain_idx in 1:chain_count])
        for k in 1:nz
    ]
    split_profile_rhats = [
        _split_chain_rhat([chain_profile_traces[chain_idx][k] for chain_idx in 1:chain_count])
        for k in 1:nz
    ]
    pooled = Float64.(pooled_mean)
    chain_mean_profiles = [
        [mean(chain_profile_traces[chain_idx][k]) for k in 1:nz]
        for chain_idx in 1:chain_count
    ]
    rmse_values = [
        sqrt(mean((chain_mean_profiles[chain_idx] .- pooled) .^ 2))
        for chain_idx in 1:chain_count
    ]
    max_abs_values = [
        maximum(abs.(chain_mean_profiles[chain_idx] .- pooled))
        for chain_idx in 1:chain_count
    ]
    return (
        profile_chain_rhat_max=_max_finite_or_nan(profile_rhats),
        profile_split_rhat_max=_max_finite_or_nan(split_profile_rhats),
        profile_chain_rmse_max=maximum(rmse_values),
        profile_chain_max_abs_deviation=maximum(max_abs_values),
    )
end

function _slit_profile_observable_convergence(
    chain_profile_traces::Vector{Vector{Vector{Float64}}},
    pooled_mean::AbstractVector{<:Real},
    grid::SlitGrid3D,
    target_phi::AbstractVector{<:Real},
    target_xi_eff::Real;
    central_density_floor::Real=0.05,
)
    chain_count = length(chain_profile_traces)
    chain_count < 1 && throw(ArgumentError("at least one profile chain is required"))
    nz = length(pooled_mean)
    length(target_phi) == nz ||
        throw(DimensionMismatch("target profile length must match pooled mean"))
    all(length(chain_trace) == nz for chain_trace in chain_profile_traces) ||
        throw(DimensionMismatch("chain profile traces must have one trace per z bin"))
    chain_xis = Float64[]
    for chain_trace in chain_profile_traces
        chain_mean = [mean(chain_trace[k]) for k in 1:nz]
        xi, _ = fit_slit_xi_eff(grid.z, chain_mean; L=grid.Lz)
        push!(chain_xis, xi)
    end
    leave_one_xis = Float64[]
    if chain_count > 1
        for omitted in 1:chain_count
            leave_one_traces = [Float64[] for _ in 1:nz]
            for chain_idx in 1:chain_count
                chain_idx == omitted && continue
                for k in 1:nz
                    append!(leave_one_traces[k], chain_profile_traces[chain_idx][k])
                end
            end
            leave_one_mean = [mean(trace) for trace in leave_one_traces]
            xi, _ = fit_slit_xi_eff(grid.z, leave_one_mean; L=grid.Lz)
            push!(leave_one_xis, xi)
        end
    end
    central_indices = findall(value -> Float64(value) >= Float64(central_density_floor),
        target_phi)
    if isempty(central_indices)
        central_indices = collect(1:nz)
    end
    central_rhats = [
        _chain_rhat([chain_profile_traces[chain_idx][k] for chain_idx in 1:chain_count])
        for k in central_indices
    ]
    central_split_rhats = [
        _split_chain_rhat([chain_profile_traces[chain_idx][k] for chain_idx in 1:chain_count])
        for k in central_indices
    ]
    pooled_xi, _ = fit_slit_xi_eff(grid.z, pooled_mean; L=grid.Lz)
    target = Float64(target_xi_eff)
    return (
        observable_xi_eff=pooled_xi,
        observable_abs_xi_error=abs(pooled_xi - target),
        observable_chain_xi_mean=mean(chain_xis),
        observable_chain_xi_sd=length(chain_xis) > 1 ? std(chain_xis) : 0.0,
        observable_chain_xi_min=minimum(chain_xis),
        observable_chain_xi_max=maximum(chain_xis),
        observable_leave_one_chain_xi_min=isempty(leave_one_xis) ? NaN : minimum(leave_one_xis),
        observable_leave_one_chain_xi_max=isempty(leave_one_xis) ? NaN : maximum(leave_one_xis),
        observable_central_density_floor=Float64(central_density_floor),
        observable_central_bin_count=length(central_indices),
        observable_central_rhat_max=_max_finite_or_nan(central_rhats),
        observable_central_split_rhat_max=_max_finite_or_nan(central_split_rhats),
    )
end

function _slit_sine_coefficients(values::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(values) == grid.Nz || throw(DimensionMismatch("slit vector length must match grid.Nz"))
    coeffs = zeros(Float64, grid.Nz)
    for m in 1:grid.Nz
        total = 0.0
        for i in 1:grid.Nz
            total += Float64(values[i]) * sin(m * pi * grid.z[i] / grid.L)
        end
        coeffs[m] = 2.0 * total / grid.Nz
    end
    return coeffs
end

function _slit_sine_reconstruct(coeffs::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(coeffs) == grid.Nz || throw(DimensionMismatch("sine coefficient length must match grid.Nz"))
    out = zeros(Float64, grid.Nz)
    for i in 1:grid.Nz
        total = 0.0
        for m in 1:grid.Nz
            total += Float64(coeffs[m]) * sin(m * pi * grid.z[i] / grid.L)
        end
        out[i] = total
    end
    return out
end

function apply_slit_debye_inverse(values::AbstractVector{<:Real}, grid::SlitGrid1D; alpha::Real=0.0)
    coeffs = _slit_sine_coefficients(values, grid)
    regularized = similar(coeffs)
    for m in eachindex(coeffs)
        k2 = (m * pi / grid.L)^2
        denom = debye(k2) * exp(-Float64(alpha)^2 * k2)
        regularized[m] = coeffs[m] / max(denom, floatmin(Float64))
    end
    return _slit_sine_reconstruct(regularized, grid)
end

function slit_heurp_ti_energy(phi::AbstractVector{<:Real}, grid::SlitGrid1D, params::SlitParams)
    _slit_validate_phi(phi, grid)
    density = Float64.(phi)
    real_term = 0.5 * params.B * params.C^2 * slit_integral(density .^ 2, grid)
    delta = density .- 1.0
    jfield = [_slit_j_density(value) for value in density]
    lj = apply_slit_debye_inverse(jfield, grid; alpha=params.alpha)
    saddle_term = params.C * sum(grid.weights[i] * delta[i] * lj[i] for i in 1:grid.Nz)
    correction = -params.A * slit_integral([_slit_entropy_density(value) for value in density], grid)
    return real_term + saddle_term + correction
end

function _slit_first_derivative(values::AbstractVector{<:Real}, grid::SlitGrid1D; left::Real=0.0, right::Real=0.0)
    out = zeros(Float64, grid.Nz)
    inv_2dz = 1.0 / (2.0 * grid.dz)
    for i in 1:grid.Nz
        prev = i == 1 ? Float64(left) : Float64(values[i - 1])
        next = i == grid.Nz ? Float64(right) : Float64(values[i + 1])
        out[i] = (next - prev) * inv_2dz
    end
    return out
end

function _slit_laplacian(values::AbstractVector{<:Real}, grid::SlitGrid1D; left::Real=0.0, right::Real=0.0)
    out = zeros(Float64, grid.Nz)
    inv_dz2 = 1.0 / grid.dz^2
    for i in 1:grid.Nz
        prev = i == 1 ? Float64(left) : Float64(values[i - 1])
        next = i == grid.Nz ? Float64(right) : Float64(values[i + 1])
        out[i] = (prev + next - 2.0 * Float64(values[i])) * inv_dz2
    end
    return out
end

function _slit_vk1_coefficient(phi::AbstractVector{<:Real}, grid::SlitGrid1D; log_floor=1.0e-12)
    _slit_validate_phi(phi, grid)
    density = Float64.(phi)
    floor_value = max(Float64(log_floor), eps(Float64))
    log_phi = log.(density)
    log_wall = log(floor_value)
    grad_log = _slit_first_derivative(log_phi, grid; left=log_wall, right=log_wall)
    lap_log = _slit_laplacian(log_phi, grid; left=log_wall, right=log_wall)
    out = similar(density)
    for i in eachindex(density)
        denominator = max(abs(log_phi[i]), floor_value)
        g = 0.046 * (2.0 * abs(lap_log[i]) / denominator + grad_log[i]^2 / denominator^2)
        out[i] = 1.0 / 6.0 + tanh(g) / 12.0
    end
    return out
end

function _slit_vk1_gradient_integral(density::AbstractVector{<:Real}, k1::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(density) == grid.Nz || throw(DimensionMismatch("density length must match grid.Nz"))
    length(k1) == grid.Nz || throw(DimensionMismatch("K1 length must match grid.Nz"))
    total = 0.0
    for edge in 1:(grid.Nz + 1)
        left_phi = edge == 1 ? 0.0 : Float64(density[edge - 1])
        right_phi = edge == grid.Nz + 1 ? 0.0 : Float64(density[edge])
        edge_phi = max(0.5 * (left_phi + right_phi), eps(Float64))
        edge_k1 = if edge == 1
            Float64(k1[1])
        elseif edge == grid.Nz + 1
            Float64(k1[end])
        else
            0.5 * (Float64(k1[edge - 1]) + Float64(k1[edge]))
        end
        edge_length = (edge == 1 || edge == grid.Nz + 1) ? 0.5 * grid.dz : grid.dz
        grad_phi = (right_phi - left_phi) / edge_length
        total += edge_length * edge_k1 * grad_phi^2 / edge_phi
    end
    return total
end

function slit_hevk1_energy(phi::AbstractVector{<:Real}, grid::SlitGrid1D, params::SlitParams)
    _slit_validate_phi(phi, grid)
    density = Float64.(phi)
    real_term = 0.5 * params.B * params.C^2 * slit_integral(density .^ 2, grid)
    k1 = _slit_vk1_coefficient(density, grid)
    gradient_term = params.C * _slit_vk1_gradient_integral(density, k1, grid)
    entropy_integral = _slit_profile_entropy_integral(density, grid)
    entropy_term = (params.C - params.A) * entropy_integral
    profile_entropy_coeff = _slit_profile_entropy_coeff(params.profile_entropy_coeff)
    profile_entropy_term = profile_entropy_coeff * entropy_integral
    projected_entropy_coeff = _slit_projected_entropy_coeff(params.projected_entropy_coeff)
    projected_entropy_term = projected_entropy_coeff == 0.0 ? 0.0 :
                             projected_entropy_coeff *
                             _slit_projected_entropy_integral(
                                 density, grid, params.projected_entropy_reference)
    projected_quadratic_coeff =
        _slit_projected_quadratic_coeff(params.projected_quadratic_coeff)
    projected_quadratic_term = projected_quadratic_coeff == 0.0 ? 0.0 :
                               projected_quadratic_coeff *
                               _slit_projected_quadratic_integral(
                                   density, grid, params.projected_quadratic_reference,
                                   params.projected_quadratic_weight)
    projected_quadratic_terms = _slit_projected_quadratic_terms_integral(
        density, grid, params.projected_quadratic_coeffs,
        params.projected_quadratic_references, params.projected_quadratic_weights)
    local_potential = _slit_local_potential_integral(density, grid, params.local_potential_coeffs)
    projected_local_potential = _slit_projected_local_potential_integral(
        density, grid, params.projected_local_potential_reference,
        params.projected_local_potential_coeffs)
    projected_profile_kernel = _slit_projected_profile_kernel_integral(
        density, grid, params.projected_profile_kernel_reference,
        params.projected_profile_kernel_matrix)
    return real_term + gradient_term + entropy_term + projected_entropy_term +
           projected_quadratic_term + projected_quadratic_terms +
           projected_local_potential + projected_profile_kernel -
           profile_entropy_term - local_potential
end

function _slit_3d_validate_phi(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    size(phi) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("3D slit density shape must match SlitGrid3D"))
    minimum(phi) > 0.0 || throw(DomainError(minimum(phi), "3D slit density must be strictly positive"))
    return nothing
end

function slit_3d_field_from_profile(profile::AbstractVector{<:Real}, grid::SlitGrid3D)
    length(profile) == grid.Nz || throw(DimensionMismatch("profile length must match grid.Nz"))
    _slit_validate_phi(profile, grid.slit_grid)
    field = Array{Float64,3}(undef, grid.Nx, grid.Ny, grid.Nz)
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        field[i, j, k] = Float64(profile[k])
    end
    return field
end

function _slit_3d_xy_profile(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    _slit_3d_validate_phi(phi, grid)
    return [mean(@view phi[:, :, k]) for k in 1:grid.Nz]
end

function _slit_3d_xy_profile!(
    profile::AbstractVector{Float64},
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
)
    length(profile) == grid.Nz ||
        throw(DimensionMismatch("profile workspace length must match grid.Nz"))
    for k in 1:grid.Nz
        total = 0.0
        for i in 1:grid.Nx, j in 1:grid.Ny
            total += Float64(phi[i, j, k])
        end
        profile[k] = total / (grid.Nx * grid.Ny)
    end
    return profile
end

function _slit_3d_lateral_variance(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    _slit_3d_validate_phi(phi, grid)
    profile = _slit_3d_xy_profile(phi, grid)
    total = 0.0
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        total += (Float64(phi[i, j, k]) - profile[k])^2
    end
    return total / length(phi)
end

function _slit_3d_lateral_variance_integral(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    _slit_3d_validate_phi(phi, grid)
    profile = _slit_3d_xy_profile(phi, grid)
    total = 0.0
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        plane_mean = max(profile[k], eps(Float64))
        deviation = Float64(phi[i, j, k]) - profile[k]
        total += grid.cell_volume * deviation^2 / plane_mean
    end
    return total
end

function _slit_3d_lateral_fraction_z_gradient_integral(
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
)
    _slit_3d_validate_phi(phi, grid)
    profile = _slit_3d_xy_profile(phi, grid)
    total = 0.0
    area = grid.dx * grid.dy
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:(grid.Nz - 1)
        left_mean = max(profile[k], eps(Float64))
        right_mean = max(profile[k + 1], eps(Float64))
        left_fraction = Float64(phi[i, j, k]) / left_mean
        right_fraction = Float64(phi[i, j, k + 1]) / right_mean
        grad_fraction = (right_fraction - left_fraction) / grid.dz
        edge_mean = 0.5 * (left_mean + right_mean)
        total += area * grid.dz * edge_mean * grad_fraction^2
    end
    return total
end

function _slit_3d_profile_entropy_integral(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    profile = _slit_3d_xy_profile(phi, grid)
    return _slit_profile_entropy_integral(profile, grid.slit_grid)
end

function _slit_3d_lateral_gradient_integral(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D)
    _slit_3d_validate_phi(phi, grid)
    total = 0.0
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        ip = _periodic_next(i, grid.Nx)
        edge_phi = max(0.5 * (Float64(phi[i, j, k]) + Float64(phi[ip, j, k])), eps(Float64))
        grad_phi = (Float64(phi[ip, j, k]) - Float64(phi[i, j, k])) / grid.dx
        total += grid.cell_volume * grad_phi^2 / edge_phi

        jp = _periodic_next(j, grid.Ny)
        edge_phi = max(0.5 * (Float64(phi[i, j, k]) + Float64(phi[i, jp, k])), eps(Float64))
        grad_phi = (Float64(phi[i, jp, k]) - Float64(phi[i, j, k])) / grid.dy
        total += grid.cell_volume * grad_phi^2 / edge_phi
    end
    return total
end

function _slit_3d_profile_measure_symbol(profile_measure)
    symbol = Symbol(profile_measure)
    symbol in (:flat_cell, :cell, :density_cell) && return :flat_cell
    symbol in (:flat_profile, :profile, :plane_mean) && return :flat_profile
    throw(ArgumentError("profile_measure must be :flat_cell or :flat_profile, got $(profile_measure)"))
end

function _slit_3d_profile_log_jacobian(
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D;
    log_floor::Real=1.0e-300,
)
    _slit_3d_validate_phi(phi, grid)
    floor_value = max(Float64(log_floor), floatmin(Float64))
    lateral_dof = grid.Nx * grid.Ny
    lateral_dof > 1 || return 0.0
    profile = _slit_3d_xy_profile(phi, grid)
    return (lateral_dof - 1) * sum(log(max(value, floor_value)) for value in profile)
end

function _slit_profile_roughness(profile::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(profile) == grid.Nz || throw(DimensionMismatch("profile length must match grid.Nz"))
    grid.Nz <= 1 && return 0.0
    return mean(((Float64(profile[i + 1]) - Float64(profile[i])) / grid.dz)^2
        for i in 1:(grid.Nz - 1))
end

function _slit_3d_log_gradient_squared(log_phi::Array{Float64,3}, grid::SlitGrid3D, log_wall::Real)
    out = Array{Float64,3}(undef, size(log_phi))
    return _slit_3d_log_gradient_squared!(out, log_phi, grid, log_wall)
end

function _slit_3d_log_gradient_squared!(
    out::Array{Float64,3},
    log_phi::Array{Float64,3},
    grid::SlitGrid3D,
    log_wall::Real,
)
    size(out) == size(log_phi) && size(out) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("log-gradient workspace shape must match SlitGrid3D"))
    inv_2dx = 1.0 / (2.0 * grid.dx)
    inv_2dy = 1.0 / (2.0 * grid.dy)
    inv_2dz = 1.0 / (2.0 * grid.dz)
    wall = Float64(log_wall)
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        im, ip = _periodic_prev(i, grid.Nx), _periodic_next(i, grid.Nx)
        jm, jp = _periodic_prev(j, grid.Ny), _periodic_next(j, grid.Ny)
        prev_z = k == 1 ? wall : log_phi[i, j, k - 1]
        next_z = k == grid.Nz ? wall : log_phi[i, j, k + 1]
        gx = (log_phi[ip, j, k] - log_phi[im, j, k]) * inv_2dx
        gy = (log_phi[i, jp, k] - log_phi[i, jm, k]) * inv_2dy
        gz = (next_z - prev_z) * inv_2dz
        out[i, j, k] = gx^2 + gy^2 + gz^2
    end
    return out
end

function _slit_3d_log_laplacian(log_phi::Array{Float64,3}, grid::SlitGrid3D, log_wall::Real)
    out = Array{Float64,3}(undef, size(log_phi))
    return _slit_3d_log_laplacian!(out, log_phi, grid, log_wall)
end

function _slit_3d_log_laplacian!(
    out::Array{Float64,3},
    log_phi::Array{Float64,3},
    grid::SlitGrid3D,
    log_wall::Real,
)
    size(out) == size(log_phi) && size(out) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("log-laplacian workspace shape must match SlitGrid3D"))
    inv_dx2 = 1.0 / grid.dx^2
    inv_dy2 = 1.0 / grid.dy^2
    inv_dz2 = 1.0 / grid.dz^2
    wall = Float64(log_wall)
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        im, ip = _periodic_prev(i, grid.Nx), _periodic_next(i, grid.Nx)
        jm, jp = _periodic_prev(j, grid.Ny), _periodic_next(j, grid.Ny)
        prev_z = k == 1 ? wall : log_phi[i, j, k - 1]
        next_z = k == grid.Nz ? wall : log_phi[i, j, k + 1]
        center = log_phi[i, j, k]
        out[i, j, k] = (log_phi[ip, j, k] + log_phi[im, j, k] - 2.0 * center) * inv_dx2 +
                       (log_phi[i, jp, k] + log_phi[i, jm, k] - 2.0 * center) * inv_dy2 +
                       (prev_z + next_z - 2.0 * center) * inv_dz2
    end
    return out
end

mutable struct Slit3DHEVK1EnergyWorkspace
    density::Array{Float64,3}
    log_phi::Array{Float64,3}
    grad_log_sq::Array{Float64,3}
    lap_log::Array{Float64,3}
    k1::Array{Float64,3}
    profile::Vector{Float64}
end

function Slit3DHEVK1EnergyWorkspace(grid::SlitGrid3D)
    shape = (grid.Nx, grid.Ny, grid.Nz)
    return Slit3DHEVK1EnergyWorkspace(
        zeros(Float64, shape),
        zeros(Float64, shape),
        zeros(Float64, shape),
        zeros(Float64, shape),
        zeros(Float64, shape),
        zeros(Float64, grid.Nz),
    )
end

function _slit_3d_vk1_coefficient!(
    out::Array{Float64,3},
    density::Array{Float64,3},
    log_phi::Array{Float64,3},
    grad_log_sq::Array{Float64,3},
    lap_log::Array{Float64,3},
    grid::SlitGrid3D;
    log_floor=1.0e-12,
)
    size(out) == size(density) && size(out) == size(log_phi) &&
        size(out) == size(grad_log_sq) && size(out) == size(lap_log) &&
        size(out) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("VK1 coefficient workspaces must match SlitGrid3D"))
    floor_value = max(Float64(log_floor), eps(Float64))
    log_wall = log(floor_value)
    _slit_3d_log_gradient_squared!(grad_log_sq, log_phi, grid, log_wall)
    _slit_3d_log_laplacian!(lap_log, log_phi, grid, log_wall)
    for idx in eachindex(density)
        denominator = max(abs(log_phi[idx]), floor_value)
        g = 0.046 * (2.0 * abs(lap_log[idx]) / denominator +
                     grad_log_sq[idx] / denominator^2)
        out[idx] = 1.0 / 6.0 + tanh(g) / 12.0
    end
    return out
end

function _slit_3d_local_potential_integral_unchecked(
    density::Array{Float64,3},
    grid::SlitGrid3D,
    coeffs,
)
    local_coeffs = _slit_local_potential_coeffs(coeffs)
    total = 0.0
    for idx in eachindex(density)
        total += _slit_local_potential_density(density[idx], local_coeffs)
    end
    return grid.cell_volume * total
end

function _slit_3d_profile_log_jacobian!(
    workspace::Slit3DHEVK1EnergyWorkspace,
    density::Array{Float64,3},
    grid::SlitGrid3D;
    log_floor::Real=1.0e-300,
)
    floor_value = max(Float64(log_floor), floatmin(Float64))
    lateral_dof = grid.Nx * grid.Ny
    lateral_dof > 1 || return 0.0
    _slit_3d_xy_profile!(workspace.profile, density, grid)
    total = 0.0
    for value in workspace.profile
        total += log(max(value, floor_value))
    end
    return (lateral_dof - 1) * total
end

function _slit_hevk1_energy_3d!(
    workspace::Slit3DHEVK1EnergyWorkspace,
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    params::SlitParams,
)
    params.model == :vk1 || throw(ArgumentError("3D slit HE-VK1 energy requires params.model == :vk1"))
    _slit_3d_validate_phi(phi, grid)
    size(workspace.density) == (grid.Nx, grid.Ny, grid.Nz) ||
        throw(DimensionMismatch("energy workspace shape must match SlitGrid3D"))
    real_sum = 0.0
    entropy_sum = 0.0
    for idx in eachindex(workspace.density)
        value = Float64(phi[idx])
        workspace.density[idx] = value
        log_value = log(value)
        workspace.log_phi[idx] = log_value
        real_sum += value^2
        entropy_sum += value * log_value
    end
    real_term = 0.5 * params.B * params.C^2 * grid.cell_volume * real_sum
    _slit_3d_vk1_coefficient!(workspace.k1, workspace.density, workspace.log_phi,
        workspace.grad_log_sq, workspace.lap_log, grid)
    gradient_term = params.C * _slit_3d_vk1_gradient_integral(
        workspace.density, workspace.k1, grid)
    entropy_term = (params.C - params.A) * grid.cell_volume * entropy_sum
    local_potential = _slit_3d_local_potential_integral_unchecked(
        workspace.density, grid, params.local_potential_coeffs)
    lateral_coeff = _slit_lateral_gradient_coeff(params.lateral_gradient_coeff)
    lateral_gradient_term = lateral_coeff == 0.0 ? 0.0 :
                            lateral_coeff * _slit_3d_lateral_gradient_integral(
                                workspace.density, grid)
    lateral_variance_coeff = _slit_lateral_variance_coeff(params.lateral_variance_coeff)
    lateral_variance_term = lateral_variance_coeff == 0.0 ? 0.0 :
                            lateral_variance_coeff * _slit_3d_lateral_variance_integral(
                                workspace.density, grid)
    lateral_z_coeff =
        _slit_lateral_fraction_z_gradient_coeff(params.lateral_fraction_z_gradient_coeff)
    lateral_z_term = lateral_z_coeff == 0.0 ? 0.0 :
                     lateral_z_coeff * _slit_3d_lateral_fraction_z_gradient_integral(
                         workspace.density, grid)
    profile_entropy_coeff = _slit_profile_entropy_coeff(params.profile_entropy_coeff)
    profile_entropy_term = profile_entropy_coeff == 0.0 ? 0.0 :
                           profile_entropy_coeff * _slit_3d_profile_entropy_integral(
                               workspace.density, grid)
    projected_entropy_coeff = _slit_projected_entropy_coeff(params.projected_entropy_coeff)
    projected_entropy_term = projected_entropy_coeff == 0.0 ? 0.0 :
                             projected_entropy_coeff *
                             _slit_3d_projected_entropy_integral(
                                 workspace.density, grid, params.projected_entropy_reference)
    projected_quadratic_coeff =
        _slit_projected_quadratic_coeff(params.projected_quadratic_coeff)
    projected_quadratic_term = projected_quadratic_coeff == 0.0 ? 0.0 :
                               projected_quadratic_coeff *
                               _slit_3d_projected_quadratic_integral(
                                   workspace.density, grid,
                                   params.projected_quadratic_reference,
                                   params.projected_quadratic_weight)
    projected_quadratic_terms = _slit_3d_projected_quadratic_terms_integral(
        workspace.density, grid, params.projected_quadratic_coeffs,
        params.projected_quadratic_references, params.projected_quadratic_weights)
    projected_local_potential = _slit_3d_projected_local_potential_integral(
        workspace.density, grid, params.projected_local_potential_reference,
        params.projected_local_potential_coeffs)
    projected_profile_kernel = _slit_3d_projected_profile_kernel_integral(
        workspace.density, grid, params.projected_profile_kernel_reference,
        params.projected_profile_kernel_matrix)
    return real_term + gradient_term + entropy_term + lateral_gradient_term +
           lateral_variance_term + lateral_z_term + projected_entropy_term +
           projected_quadratic_term + projected_quadratic_terms +
           projected_local_potential + projected_profile_kernel -
           profile_entropy_term - local_potential
end

function _slit_hevk1_energy_3d_blocked_profile_measure!(
    workspace::Slit3DHEVK1EnergyWorkspace,
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    params::SlitParams;
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
)
    base_energy = _slit_hevk1_energy_3d!(workspace, phi, grid, params)
    power = Float64(profile_measure_power)
    isfinite(power) || throw(ArgumentError("profile_measure_power must be finite"))
    power == 1.0 && return base_energy
    log_jacobian = _slit_3d_profile_log_jacobian!(workspace, workspace.density, grid;
        log_floor=profile_measure_log_floor)
    return base_energy + (power - 1.0) * log_jacobian
end

function _slit_3d_vk1_coefficient(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D; log_floor=1.0e-12)
    _slit_3d_validate_phi(phi, grid)
    floor_value = max(Float64(log_floor), eps(Float64))
    density = Float64.(phi)
    log_phi = log.(density)
    log_wall = log(floor_value)
    grad_log_sq = _slit_3d_log_gradient_squared(log_phi, grid, log_wall)
    lap_log = _slit_3d_log_laplacian(log_phi, grid, log_wall)
    out = Array{Float64,3}(undef, size(density))
    for idx in eachindex(density)
        denominator = max(abs(log_phi[idx]), floor_value)
        g = 0.046 * (2.0 * abs(lap_log[idx]) / denominator + grad_log_sq[idx] / denominator^2)
        out[idx] = 1.0 / 6.0 + tanh(g) / 12.0
    end
    return out
end

function _slit_3d_vk1_gradient_integral(phi::Array{Float64,3}, k1::Array{Float64,3}, grid::SlitGrid3D)
    total = 0.0
    yz_area = grid.dy * grid.dz
    xz_area = grid.dx * grid.dz
    xy_area = grid.dx * grid.dy
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        ip = _periodic_next(i, grid.Nx)
        edge_phi = max(0.5 * (phi[i, j, k] + phi[ip, j, k]), eps(Float64))
        edge_k1 = 0.5 * (k1[i, j, k] + k1[ip, j, k])
        grad_phi = (phi[ip, j, k] - phi[i, j, k]) / grid.dx
        total += yz_area * grid.dx * edge_k1 * grad_phi^2 / edge_phi

        jp = _periodic_next(j, grid.Ny)
        edge_phi = max(0.5 * (phi[i, j, k] + phi[i, jp, k]), eps(Float64))
        edge_k1 = 0.5 * (k1[i, j, k] + k1[i, jp, k])
        grad_phi = (phi[i, jp, k] - phi[i, j, k]) / grid.dy
        total += xz_area * grid.dy * edge_k1 * grad_phi^2 / edge_phi
    end
    for i in 1:grid.Nx, j in 1:grid.Ny
        for edge in 1:(grid.Nz + 1)
            left_phi = edge == 1 ? 0.0 : phi[i, j, edge - 1]
            right_phi = edge == grid.Nz + 1 ? 0.0 : phi[i, j, edge]
            edge_phi = max(0.5 * (left_phi + right_phi), eps(Float64))
            edge_k1 = if edge == 1
                k1[i, j, 1]
            elseif edge == grid.Nz + 1
                k1[i, j, end]
            else
                0.5 * (k1[i, j, edge - 1] + k1[i, j, edge])
            end
            edge_length = (edge == 1 || edge == grid.Nz + 1) ? 0.5 * grid.dz : grid.dz
            grad_phi = (right_phi - left_phi) / edge_length
            total += xy_area * edge_length * edge_k1 * grad_phi^2 / edge_phi
        end
    end
    return total
end

function slit_hevk1_energy_3d(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D, params::SlitParams)
    params.model == :vk1 || throw(ArgumentError("3D slit HE-VK1 energy requires params.model == :vk1"))
    _slit_3d_validate_phi(phi, grid)
    density = Float64.(phi)
    real_term = 0.5 * params.B * params.C^2 * grid.cell_volume * sum(abs2, density)
    k1 = _slit_3d_vk1_coefficient(density, grid)
    gradient_term = params.C * _slit_3d_vk1_gradient_integral(density, k1, grid)
    entropy_term = (params.C - params.A) * grid.cell_volume *
                   sum(density[idx] * log(density[idx]) for idx in eachindex(density))
    local_potential = _slit_3d_local_potential_integral(density, grid, params.local_potential_coeffs)
    lateral_coeff = _slit_lateral_gradient_coeff(params.lateral_gradient_coeff)
    lateral_gradient_term = lateral_coeff == 0.0 ? 0.0 :
                            lateral_coeff * _slit_3d_lateral_gradient_integral(density, grid)
    lateral_variance_coeff = _slit_lateral_variance_coeff(params.lateral_variance_coeff)
    lateral_variance_term = lateral_variance_coeff == 0.0 ? 0.0 :
                            lateral_variance_coeff * _slit_3d_lateral_variance_integral(density, grid)
    lateral_z_coeff =
        _slit_lateral_fraction_z_gradient_coeff(params.lateral_fraction_z_gradient_coeff)
    lateral_z_term = lateral_z_coeff == 0.0 ? 0.0 :
                     lateral_z_coeff * _slit_3d_lateral_fraction_z_gradient_integral(density, grid)
    profile_entropy_coeff = _slit_profile_entropy_coeff(params.profile_entropy_coeff)
    profile_entropy_term = profile_entropy_coeff == 0.0 ? 0.0 :
                           profile_entropy_coeff * _slit_3d_profile_entropy_integral(density, grid)
    projected_entropy_coeff = _slit_projected_entropy_coeff(params.projected_entropy_coeff)
    projected_entropy_term = projected_entropy_coeff == 0.0 ? 0.0 :
                             projected_entropy_coeff *
                             _slit_3d_projected_entropy_integral(
                                 density, grid, params.projected_entropy_reference)
    projected_quadratic_coeff =
        _slit_projected_quadratic_coeff(params.projected_quadratic_coeff)
    projected_quadratic_term = projected_quadratic_coeff == 0.0 ? 0.0 :
                               projected_quadratic_coeff *
                               _slit_3d_projected_quadratic_integral(
                                   density, grid, params.projected_quadratic_reference,
                                   params.projected_quadratic_weight)
    projected_quadratic_terms = _slit_3d_projected_quadratic_terms_integral(
        density, grid, params.projected_quadratic_coeffs,
        params.projected_quadratic_references, params.projected_quadratic_weights)
    projected_local_potential = _slit_3d_projected_local_potential_integral(
        density, grid, params.projected_local_potential_reference,
        params.projected_local_potential_coeffs)
    projected_profile_kernel = _slit_3d_projected_profile_kernel_integral(
        density, grid, params.projected_profile_kernel_reference,
        params.projected_profile_kernel_matrix)
    return real_term + gradient_term + entropy_term + lateral_gradient_term +
           lateral_variance_term + lateral_z_term + projected_entropy_term +
           projected_quadratic_term + projected_quadratic_terms +
           projected_local_potential + projected_profile_kernel -
           profile_entropy_term - local_potential
end

function slit_hevk1_energy_3d_profile_measure(
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    params::SlitParams;
    profile_measure=:flat_cell,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
)
    base_energy = slit_hevk1_energy_3d(phi, grid, params)
    symbol = _slit_3d_profile_measure_symbol(profile_measure)
    symbol == :flat_cell && return base_energy
    power = Float64(profile_measure_power)
    isfinite(power) || throw(ArgumentError("profile_measure_power must be finite"))
    log_jacobian = _slit_3d_profile_log_jacobian(phi, grid; log_floor=profile_measure_log_floor)
    return base_energy + power * log_jacobian
end

function slit_hevk1_energy_3d_blocked_profile_measure(
    phi::AbstractArray{<:Real,3},
    grid::SlitGrid3D,
    params::SlitParams;
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
)
    base_energy = slit_hevk1_energy_3d(phi, grid, params)
    power = Float64(profile_measure_power)
    isfinite(power) || throw(ArgumentError("profile_measure_power must be finite"))
    log_jacobian = _slit_3d_profile_log_jacobian(phi, grid; log_floor=profile_measure_log_floor)
    return base_energy + (power - 1.0) * log_jacobian
end

function slit_gsd_profile(B::Real, C::Real, L::Real, Nz::Integer)
    grid = SlitGrid1D(Nz, L)
    bc = Float64(B) * Float64(C)
    bc < 0.05 && return slit_low_density_profile(grid)
    return slit_reference_profile(grid.z; B=B, C=C, L=L)
end

function _slit_energy_for_model(model::Symbol, phi::AbstractVector{<:Real}, grid::SlitGrid1D, params::SlitParams)
    if model == :urp_ti
        return slit_heurp_ti_energy(phi, grid, params)
    elseif model == :vk1
        return slit_hevk1_energy(phi, grid, params)
    end
    throw(ArgumentError("unsupported slit model: $model"))
end

function _slit_bulk_xi(B::Real, C::Real)
    bc = Float64(B) * Float64(C)
    return 1.0 / sqrt(max(2.0 * bc, eps(Float64)))
end

function _slit_mu_estimate(B::Real, C::Real, phi::AbstractVector{<:Real}, grid::SlitGrid1D)
    bc = Float64(B) * Float64(C)
    if bc < 1.0
        return (pi / grid.L)^2 + (2.0 / 3.0) * bc
    end
    return bc * maximum(phi)
end

function _slit_status(params::SlitParams)
    params.A <= 0.0 && return "stable_saddle"
    threshold = sqrt(max(params.A / max(params.B, eps(Float64)), 0.0))
    if params.C + 1.0e-12 < threshold
        return "unstable_or_outside_validated_A_regime"
    end
    return "A_correction_overlay"
end

function minimize_slit_density(
    model,
    B::Real,
    C::Real,
    A::Real;
    Nz::Integer=80,
    L::Real=1.0,
    alpha::Real=0.0,
)
    symbol = _slit_model_symbol(model)
    grid = SlitGrid1D(Nz, L)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha), model=symbol)
    xi_bulk = _slit_bulk_xi(B, C)
    xi_lo = max(0.02 * grid.L, min(0.25 * xi_bulk, 0.25 * grid.L))
    xi_hi = min(3.0 * grid.L, max(4.0 * xi_bulk, 1.5 * grid.L))
    objective(xi) = begin
        profile = slit_reference_profile(grid.z; B=B, C=C, L=grid.L, xi=xi)
        return _slit_energy_for_model(symbol, profile, grid, params)
    end
    xi_best, _ = _golden_section_minimize(objective, xi_lo, xi_hi; iterations=70)
    candidates = Vector{Vector{Float64}}()
    push!(candidates, slit_reference_profile(grid.z; B=B, C=C, L=grid.L, xi=xi_best))
    push!(candidates, slit_reference_profile(grid.z; B=B, C=C, L=grid.L, xi=xi_bulk))
    push!(candidates, slit_low_density_profile(grid))
    energies = [_slit_energy_for_model(symbol, candidate, grid, params) for candidate in candidates]
    best = argmin(energies)
    phi = candidates[best]
    reference = slit_reference_profile(grid.z; B=B, C=C, L=grid.L)
    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, phi; L=grid.L)
    rms = sqrt(mean((phi .- reference) .^ 2))
    return SlitSaddleResult(
        symbol,
        grid,
        params,
        phi,
        reference,
        energies[best],
        xi_eff,
        xi_fit_error,
        xi_bulk,
        _slit_mu_estimate(B, C, phi, grid),
        rms,
        _slit_status(params),
    )
end

function _slit_profile_from_logits(logits::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(logits) == grid.Nz || throw(DimensionMismatch("logit length must match grid.Nz"))
    shifted = clamp.(logits .- maximum(logits), -60.0, 0.0)
    raw = exp.(shifted)
    norm = slit_integral(raw, grid)
    norm > 0.0 || throw(DomainError(norm, "normalized slit field has zero weight"))
    return raw .* (grid.L / norm)
end

function _slit_profile_from_free_log_density(free::AbstractVector{<:Real}, grid::SlitGrid1D)
    length(free) == grid.Nz - 1 || throw(DimensionMismatch("free slit field must have Nz - 1 entries"))
    logits = Vector{Float64}(undef, grid.Nz)
    for i in 1:(grid.Nz - 1)
        logits[i] = Float64(free[i])
    end
    logits[grid.Nz] = 0.0
    return _slit_profile_from_logits(logits, grid)
end

function _slit_free_log_density_from_profile(phi::AbstractVector{<:Real}, grid::SlitGrid1D)
    _slit_validate_phi(phi, grid)
    log_phi = log.(Float64.(phi))
    return log_phi[1:(grid.Nz - 1)] .- log_phi[grid.Nz]
end

function _slit_cosine_basis_matrix(grid::SlitGrid1D, basis_count::Integer)
    count = Int(basis_count)
    count >= 1 || throw(ArgumentError("basis_count must be positive"))
    matrix = Matrix{Float64}(undef, grid.Nz, count)
    for mode in 1:count
        for i in 1:grid.Nz
            x = grid.z[i] / grid.L - 0.5
            matrix[i, mode] = cos(2.0 * pi * mode * x)
        end
    end
    return matrix
end

function _slit_profile_from_smooth_coefficients(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D,
)
    length(base_profile) == grid.Nz || throw(DimensionMismatch("base profile length must match grid.Nz"))
    size(basis, 1) == grid.Nz || throw(DimensionMismatch("basis row count must match grid.Nz"))
    size(basis, 2) == length(coeffs) || throw(DimensionMismatch("basis column count must match coefficient length"))
    _slit_validate_phi(base_profile, grid)
    logits = log.(Float64.(base_profile)) .+ Float64.(basis) * Float64.(coeffs)
    return _slit_profile_from_logits(logits, grid)
end

function _normalise_spectral_basis_column!(column::AbstractVector{Float64})
    column .-= mean(column)
    rms = sqrt(mean(abs2, column))
    rms > sqrt(eps(Float64)) || return false
    column ./= rms
    return true
end

function _slit_3d_spectral_basis(
    grid::SlitGrid3D;
    z_basis_count::Integer=4,
    lateral_mode_count::Integer=0,
    lateral_z_basis_count::Integer=0,
)
    z_count = max(0, Int(z_basis_count))
    lateral_count = max(0, Int(lateral_mode_count))
    lateral_z_count = max(0, Int(lateral_z_basis_count))
    columns = Vector{Vector{Float64}}()
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    cell_count = grid.Nx * grid.Ny * grid.Nz

    for mode in 1:z_count
        column = zeros(Float64, cell_count)
        for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
            z = grid.z[k] / grid.Lz - 0.5
            column[linear[i, j, k]] = cos(2.0 * pi * mode * z)
        end
        _normalise_spectral_basis_column!(column) && push!(columns, column)
    end

    for mx in 0:lateral_count, my in 0:lateral_count
        (mx == 0 && my == 0) && continue
        for zmode in 0:lateral_z_count
            for phase_kind in (:cos, :sin)
                column = zeros(Float64, cell_count)
                for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
                    x = (i - 0.5) / grid.Nx
                    y = (j - 0.5) / grid.Ny
                    z = grid.z[k] / grid.Lz - 0.5
                    lateral_phase = 2.0 * pi * (mx * x + my * y)
                    lateral_shape = phase_kind == :cos ? cos(lateral_phase) : sin(lateral_phase)
                    z_shape = zmode == 0 ? 1.0 : cos(2.0 * pi * zmode * z)
                    column[linear[i, j, k]] = lateral_shape * z_shape
                end
                _normalise_spectral_basis_column!(column) && push!(columns, column)
            end
        end
    end

    isempty(columns) && throw(ArgumentError("spectral basis must contain at least one mode"))
    basis = Matrix{Float64}(undef, cell_count, length(columns))
    for (column_index, column) in enumerate(columns)
        basis[:, column_index] .= column
    end
    return basis
end

function _slit_3d_lateral_spectral_basis(
    grid::SlitGrid3D;
    lateral_mode_count::Integer=1,
    lateral_z_basis_count::Integer=0,
)
    lateral_count = max(0, Int(lateral_mode_count))
    lateral_z_count = max(0, Int(lateral_z_basis_count))
    cell_count = grid.Nx * grid.Ny * grid.Nz
    lateral_count == 0 && return zeros(Float64, cell_count, 0)
    columns = Vector{Vector{Float64}}()
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    for mx in 0:lateral_count, my in 0:lateral_count
        (mx == 0 && my == 0) && continue
        for zmode in 0:lateral_z_count
            for phase_kind in (:cos, :sin)
                column = zeros(Float64, cell_count)
                for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
                    x = (i - 0.5) / grid.Nx
                    y = (j - 0.5) / grid.Ny
                    z = grid.z[k] / grid.Lz - 0.5
                    lateral_phase = 2.0 * pi * (mx * x + my * y)
                    lateral_shape = phase_kind == :cos ? cos(lateral_phase) : sin(lateral_phase)
                    z_shape = zmode == 0 ? 1.0 : cos(2.0 * pi * zmode * z)
                    column[linear[i, j, k]] = lateral_shape * z_shape
                end
                _normalise_spectral_basis_column!(column) && push!(columns, column)
            end
        end
    end
    basis = Matrix{Float64}(undef, cell_count, length(columns))
    for (column_index, column) in enumerate(columns)
        basis[:, column_index] .= column
    end
    return basis
end

function _slit_3d_lateral_spectral_mode_metadata(
    grid::SlitGrid3D;
    lateral_mode_count::Integer=1,
    lateral_z_basis_count::Integer=0,
)
    lateral_count = max(0, Int(lateral_mode_count))
    lateral_z_count = max(0, Int(lateral_z_basis_count))
    metadata = NamedTuple{(:mx, :my, :zmode, :phase_kind),Tuple{Int,Int,Int,Symbol}}[]
    lateral_count == 0 && return metadata
    cell_count = grid.Nx * grid.Ny * grid.Nz
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    for mx in 0:lateral_count, my in 0:lateral_count
        (mx == 0 && my == 0) && continue
        for zmode in 0:lateral_z_count
            for phase_kind in (:cos, :sin)
                column = zeros(Float64, cell_count)
                for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
                    x = (i - 0.5) / grid.Nx
                    y = (j - 0.5) / grid.Ny
                    z = grid.z[k] / grid.Lz - 0.5
                    lateral_phase = 2.0 * pi * (mx * x + my * y)
                    lateral_shape = phase_kind == :cos ? cos(lateral_phase) : sin(lateral_phase)
                    z_shape = zmode == 0 ? 1.0 : cos(2.0 * pi * zmode * z)
                    column[linear[i, j, k]] = lateral_shape * z_shape
                end
                _normalise_spectral_basis_column!(column) &&
                    push!(metadata, (mx=mx, my=my, zmode=zmode, phase_kind=phase_kind))
            end
        end
    end
    return metadata
end

function _slit_lateral_mode_quadratic_coeffs(value, lateral_count::Integer)
    return _slit_spectral_mode_quadratic_coeffs(value, lateral_count;
        name="lateral_mode_quadratic_coeffs",
        count_name="lateral spectral basis count")
end

function _slit_spectral_mode_quadratic_coeffs(
    value,
    mode_count::Integer;
    name::AbstractString="spectral_mode_quadratic_coeffs",
    count_name::AbstractString="spectral basis count",
)
    count = Int(mode_count)
    count >= 0 || throw(ArgumentError("mode count must be nonnegative"))
    value === nothing && return zeros(Float64, count)
    coeffs = Float64.(collect(value))
    isempty(coeffs) && return zeros(Float64, count)
    length(coeffs) == count ||
        throw(DimensionMismatch("$name length must match $count_name"))
    all(isfinite, coeffs) ||
        throw(ArgumentError("$name must be finite"))
    all(>=(0.0), coeffs) ||
        throw(ArgumentError("$name must be nonnegative"))
    return coeffs
end

function _slit_spectral_mode_quadratic_energy(
    coeffs::AbstractVector{<:Real},
    weights::AbstractVector{<:Real},
)
    length(coeffs) == length(weights) ||
        throw(DimensionMismatch("spectral coefficient and quadratic-weight lengths must match"))
    isempty(weights) && return 0.0
    energy = 0.0
    @inbounds for i in eachindex(weights)
        energy += Float64(weights[i]) * Float64(coeffs[i])^2
    end
    return 0.5 * energy
end

function _slit_lateral_mode_quadratic_energy(
    lateral_coeffs::AbstractVector{<:Real},
    weights::AbstractVector{<:Real},
)
    return _slit_spectral_mode_quadratic_energy(lateral_coeffs, weights)
end

function _slit_profile_coordinate_jacobian_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("profile_coordinate_jacobian_coeff must be finite"))
    coeff >= 0.0 ||
        throw(ArgumentError("profile_coordinate_jacobian_coeff must be nonnegative"))
    return coeff
end

function _slit_profile_coordinate_log_jacobian(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D;
    eigenvalue_floor::Real=1.0e-14,
)
    count = length(coeffs)
    size(basis, 1) == grid.Nz || throw(DimensionMismatch("basis row count must match grid.Nz"))
    size(basis, 2) == count || throw(DimensionMismatch("basis column count must match coefficients"))
    count == 0 && return 0.0
    profile = _slit_profile_from_smooth_coefficients(coeffs, base_profile, basis, grid)
    basis_values = Float64.(basis)
    means = Vector{Float64}(undef, count)
    for mode in 1:count
        total = 0.0
        for i in 1:grid.Nz
            total += grid.weights[i] * profile[i] * basis_values[i, mode]
        end
        means[mode] = total / grid.L
    end
    metric = zeros(Float64, count, count)
    for row in 1:grid.Nz
        weighted_phi2 = grid.weights[row] * profile[row]^2
        for a in 1:count
            da = basis_values[row, a] - means[a]
            for b in a:count
                metric[a, b] += weighted_phi2 * da * (basis_values[row, b] - means[b])
            end
        end
    end
    for a in 1:count, b in 1:(a - 1)
        metric[a, b] = metric[b, a]
    end
    floor_value = max(Float64(eigenvalue_floor), floatmin(Float64))
    isfinite(floor_value) && floor_value > 0.0 ||
        throw(ArgumentError("eigenvalue_floor must be positive and finite"))
    values = eigvals(Symmetric(metric))
    all(isfinite, values) || throw(ArgumentError("profile-coordinate metric is not finite"))
    return 0.5 * sum(log(max(value, floor_value)) for value in values)
end

function _slit_profile_coordinate_log_jacobian_gradient(
    reference_coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D;
    finite_difference_step::Real=1.0e-5,
    eigenvalue_floor::Real=1.0e-14,
)
    count = length(reference_coeffs)
    step = Float64(finite_difference_step)
    isfinite(step) && step > 0.0 ||
        throw(ArgumentError("finite_difference_step must be positive and finite"))
    ref = Float64.(reference_coeffs)
    gradient = zeros(Float64, count)
    for mode in 1:count
        plus = copy(ref)
        minus = copy(ref)
        plus[mode] += step
        minus[mode] -= step
        gradient[mode] = (_slit_profile_coordinate_log_jacobian(
                              plus, base_profile, basis, grid;
                              eigenvalue_floor=eigenvalue_floor) -
                          _slit_profile_coordinate_log_jacobian(
                              minus, base_profile, basis, grid;
                              eigenvalue_floor=eigenvalue_floor)) / (2.0 * step)
    end
    return gradient
end

function _slit_projected_profile_coordinate_log_jacobian(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D;
    reference_coeffs=nothing,
    finite_difference_step::Real=1.0e-5,
    eigenvalue_floor::Real=1.0e-14,
)
    values = Float64.(coeffs)
    reference = reference_coeffs === nothing ? zeros(Float64, length(values)) :
                Float64.(collect(reference_coeffs))
    length(reference) == length(values) ||
        throw(DimensionMismatch("reference coefficient length must match coefficients"))
    log_j = _slit_profile_coordinate_log_jacobian(
        values, base_profile, basis, grid; eigenvalue_floor=eigenvalue_floor)
    reference_log_j = _slit_profile_coordinate_log_jacobian(
        reference, base_profile, basis, grid; eigenvalue_floor=eigenvalue_floor)
    reference_gradient = _slit_profile_coordinate_log_jacobian_gradient(
        reference, base_profile, basis, grid;
        finite_difference_step=finite_difference_step,
        eigenvalue_floor=eigenvalue_floor)
    return log_j - reference_log_j - dot(reference_gradient, values .- reference)
end

function _slit_profile_coordinate_log_jacobian_energy(
    coeffs::AbstractVector{<:Real},
    profile_coordinate_jacobian_coeff::Real,
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D;
    reference_coeffs=nothing,
    finite_difference_step::Real=1.0e-5,
    eigenvalue_floor::Real=1.0e-14,
)
    coeff = _slit_profile_coordinate_jacobian_coeff(profile_coordinate_jacobian_coeff)
    coeff == 0.0 && return 0.0
    projected_log_j = _slit_projected_profile_coordinate_log_jacobian(
        coeffs, base_profile, basis, grid;
        reference_coeffs=reference_coeffs,
        finite_difference_step=finite_difference_step,
        eigenvalue_floor=eigenvalue_floor)
    return -coeff * projected_log_j
end

function _slit_profile_xi_potential_coeff(value)
    coeff = Float64(value)
    isfinite(coeff) || throw(ArgumentError("profile_xi_potential_coeff must be finite"))
    return coeff
end

function _slit_profile_xi_potential_table(xi_values, potential_values; allow_empty::Bool=false)
    xs = Float64.(collect(xi_values))
    ys = Float64.(collect(potential_values))
    if isempty(xs) && isempty(ys) && allow_empty
        return xs, ys
    end
    length(xs) == length(ys) ||
        throw(DimensionMismatch("profile xi potential table columns must have the same length"))
    length(xs) >= 2 ||
        throw(ArgumentError("profile xi potential table must contain at least two points"))
    all(isfinite, xs) || throw(ArgumentError("profile xi potential xi values must be finite"))
    all(isfinite, ys) || throw(ArgumentError("profile xi potential values must be finite"))
    all(>(0.0), xs) ||
        throw(ArgumentError("profile xi potential xi values must be positive"))
    issorted(xs) || throw(ArgumentError("profile xi potential xi values must be sorted"))
    any(diff(xs) .<= 0.0) &&
        throw(ArgumentError("profile xi potential xi values must be strictly increasing"))
    return xs, ys
end

function _slit_profile_xi_potential_value(
    xi::Real,
    xi_values,
    potential_values,
)
    x = Float64(xi)
    isfinite(x) || throw(ArgumentError("profile xi potential query must be finite"))
    xs, ys = _slit_profile_xi_potential_table(xi_values, potential_values)
    x <= first(xs) && return first(ys)
    x >= last(xs) && return last(ys)
    upper = searchsortedfirst(xs, x)
    lower = upper - 1
    t = (x - xs[lower]) / (xs[upper] - xs[lower])
    return (1.0 - t) * ys[lower] + t * ys[upper]
end

function _slit_profile_xi_potential(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D,
    xi_values,
    potential_values,
)
    profile = _slit_profile_from_smooth_coefficients(coeffs, base_profile, basis, grid)
    xi_eff, _ = fit_slit_xi_eff(grid.z, profile; L=grid.L)
    return _slit_profile_xi_potential_value(xi_eff, xi_values, potential_values)
end

function _slit_profile_xi_potential_gradient(
    reference_coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D,
    xi_values,
    potential_values;
    finite_difference_step::Real=1.0e-4,
)
    count = length(reference_coeffs)
    step = Float64(finite_difference_step)
    isfinite(step) && step > 0.0 ||
        throw(ArgumentError("finite_difference_step must be positive and finite"))
    ref = Float64.(reference_coeffs)
    gradient = zeros(Float64, count)
    for mode in 1:count
        plus = copy(ref)
        minus = copy(ref)
        plus[mode] += step
        minus[mode] -= step
        gradient[mode] =
            (_slit_profile_xi_potential(
                 plus, base_profile, basis, grid, xi_values, potential_values) -
             _slit_profile_xi_potential(
                 minus, base_profile, basis, grid, xi_values, potential_values)) /
            (2.0 * step)
    end
    return gradient
end

function _slit_projected_profile_xi_potential(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D,
    xi_values,
    potential_values;
    reference_coeffs=nothing,
    finite_difference_step::Real=1.0e-4,
)
    values = Float64.(coeffs)
    reference = reference_coeffs === nothing ? zeros(Float64, length(values)) :
                Float64.(collect(reference_coeffs))
    length(reference) == length(values) ||
        throw(DimensionMismatch("reference coefficient length must match coefficients"))
    potential = _slit_profile_xi_potential(
        values, base_profile, basis, grid, xi_values, potential_values)
    reference_potential = _slit_profile_xi_potential(
        reference, base_profile, basis, grid, xi_values, potential_values)
    reference_gradient = _slit_profile_xi_potential_gradient(
        reference, base_profile, basis, grid, xi_values, potential_values;
        finite_difference_step=finite_difference_step)
    return potential - reference_potential - dot(reference_gradient, values .- reference)
end

function _slit_profile_xi_potential_energy(
    coeffs::AbstractVector{<:Real},
    profile_xi_potential_coeff::Real,
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid1D,
    xi_values,
    potential_values;
    reference_coeffs=nothing,
    finite_difference_step::Real=1.0e-4,
)
    coeff = _slit_profile_xi_potential_coeff(profile_xi_potential_coeff)
    coeff == 0.0 && return 0.0
    projected = _slit_projected_profile_xi_potential(
        coeffs, base_profile, basis, grid, xi_values, potential_values;
        reference_coeffs=reference_coeffs,
        finite_difference_step=finite_difference_step)
    return coeff * projected
end

function _slit_profile_mode_quadratic_matrix(values, z_count::Integer)
    count = max(0, Int(z_count))
    raw = values === nothing ? Any[] : collect(values)
    isempty(raw) && return zeros(Float64, count, count)
    matrix = Float64.(values)
    ndims(matrix) == 2 ||
        throw(ArgumentError("profile_mode_quadratic_matrix must be a matrix"))
    size(matrix, 1) == count && size(matrix, 2) == count ||
        throw(DimensionMismatch("profile_mode_quadratic_matrix dimensions must match z_basis_count"))
    all(isfinite, matrix) ||
        throw(ArgumentError("profile_mode_quadratic_matrix entries must be finite"))
    if !isapprox(matrix, transpose(matrix); rtol=1.0e-10, atol=1.0e-12)
        throw(ArgumentError("profile_mode_quadratic_matrix must be symmetric"))
    end
    return 0.5 .* (matrix .+ transpose(matrix))
end

function _slit_profile_mode_quadratic_energy(
    coeffs::AbstractVector{<:Real},
    matrix::AbstractMatrix{<:Real},
)
    values = Float64.(coeffs)
    size(matrix, 1) == length(values) && size(matrix, 2) == length(values) ||
        throw(DimensionMismatch("profile quadratic matrix dimensions must match profile coefficients"))
    isempty(values) && return 0.0
    return 0.5 * dot(values, Float64.(matrix) * values)
end

function _slit_blocked_spectral_mode_quadratic_coeffs(
    spectral_mode_weights::AbstractVector{<:Real},
    lateral_mode_weights::AbstractVector{<:Real},
    z_count::Integer,
    lateral_count::Integer,
)
    z_n = Int(z_count)
    lateral_n = Int(lateral_count)
    total_n = z_n + lateral_n
    length(spectral_mode_weights) == total_n ||
        throw(DimensionMismatch("spectral_mode_quadratic_coeffs length must match blocked spectral basis count"))
    length(lateral_mode_weights) == lateral_n ||
        throw(DimensionMismatch("lateral_mode_quadratic_coeffs length must match lateral spectral basis count"))
    combined = Float64.(collect(spectral_mode_weights))
    if lateral_n > 0
        @views combined[(z_n + 1):total_n] .+= Float64.(lateral_mode_weights)
    end
    return combined
end

function _slit_3d_blocked_spectral_mode_metadata(
    z_basis_count::Integer,
    lateral_metadata,
)
    z_count = max(0, Int(z_basis_count))
    metadata = NamedTuple{(:mode_index, :mode_family, :z_basis_index, :mx, :my, :lateral_zmode, :phase_kind),
        Tuple{Int,String,Int,Int,Int,Int,String}}[]
    for mode in 1:z_count
        push!(metadata, (
            mode_index=length(metadata) + 1,
            mode_family="profile_z",
            z_basis_index=mode,
            mx=-1,
            my=-1,
            lateral_zmode=-1,
            phase_kind="",
        ))
    end
    for mode in lateral_metadata
        push!(metadata, (
            mode_index=length(metadata) + 1,
            mode_family="lateral",
            z_basis_index=0,
            mx=mode.mx,
            my=mode.my,
            lateral_zmode=mode.zmode,
            phase_kind=String(mode.phase_kind),
        ))
    end
    return metadata
end

function _slit_3d_field_from_spectral_coefficients(
    coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real},
    grid::SlitGrid3D,
)
    length(base_profile) == grid.Nz ||
        throw(DimensionMismatch("base profile length must match grid.Nz"))
    size(basis, 1) == grid.Nx * grid.Ny * grid.Nz ||
        throw(DimensionMismatch("spectral basis row count must match grid cell count"))
    size(basis, 2) == length(coeffs) ||
        throw(DimensionMismatch("spectral basis column count must match coefficient length"))
    _slit_validate_phi(base_profile, grid.slit_grid)
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    logits = Vector{Float64}(undef, grid.Nx * grid.Ny * grid.Nz)
    log_profile = log.(Float64.(base_profile))
    for i in 1:grid.Nx, j in 1:grid.Ny, k in 1:grid.Nz
        logits[linear[i, j, k]] = log_profile[k]
    end
    logits .+= Float64.(basis) * Float64.(coeffs)
    offset = maximum(logits)
    raw = exp.(logits .- offset)
    norm = grid.cell_volume * sum(raw)
    norm > 0.0 || throw(DomainError(norm, "spectral density normalization must be positive"))
    return reshape(raw .* (grid.volume / norm), grid.Nx, grid.Ny, grid.Nz)
end

function _slit_3d_field_from_blocked_spectral_coefficients(
    profile_coeffs::AbstractVector{<:Real},
    lateral_coeffs::AbstractVector{<:Real},
    base_profile::AbstractVector{<:Real},
    z_basis::AbstractMatrix{<:Real},
    lateral_basis::AbstractMatrix{<:Real},
    grid::SlitGrid3D,
)
    size(z_basis, 1) == grid.Nz ||
        throw(DimensionMismatch("z basis row count must match grid.Nz"))
    size(z_basis, 2) == length(profile_coeffs) ||
        throw(DimensionMismatch("z basis column count must match profile coefficient length"))
    size(lateral_basis, 1) == grid.Nx * grid.Ny * grid.Nz ||
        throw(DimensionMismatch("lateral basis row count must match grid cell count"))
    size(lateral_basis, 2) == length(lateral_coeffs) ||
        throw(DimensionMismatch("lateral basis column count must match lateral coefficient length"))
    profile = _slit_profile_from_smooth_coefficients(
        profile_coeffs, base_profile, z_basis, grid.slit_grid)
    lateral_logits = size(lateral_basis, 2) == 0 ?
                     zeros(Float64, grid.Nx * grid.Ny * grid.Nz) :
                     Float64.(lateral_basis) * Float64.(lateral_coeffs)
    field = Array{Float64,3}(undef, grid.Nx, grid.Ny, grid.Nz)
    linear = LinearIndices((grid.Nx, grid.Ny, grid.Nz))
    for k in 1:grid.Nz
        plane_max = maximum(lateral_logits[linear[i, j, k]] for i in 1:grid.Nx, j in 1:grid.Ny)
        plane_raw = Array{Float64,2}(undef, grid.Nx, grid.Ny)
        plane_sum = 0.0
        for i in 1:grid.Nx, j in 1:grid.Ny
            value = exp(lateral_logits[linear[i, j, k]] - plane_max)
            plane_raw[i, j] = value
            plane_sum += value
        end
        plane_mean = plane_sum / (grid.Nx * grid.Ny)
        plane_mean > 0.0 || throw(DomainError(plane_mean, "lateral plane normalization must be positive"))
        for i in 1:grid.Nx, j in 1:grid.Ny
            field[i, j, k] = profile[k] * plane_raw[i, j] / plane_mean
        end
    end
    return field
end

function _finite_difference_projected_gradient(objective, free::AbstractVector{<:Real}; step::Real=1.0e-5)
    x = Float64.(free)
    isempty(x) && return (rms=0.0, max_abs=0.0)
    grad = zeros(Float64, length(x))
    for i in eachindex(x)
        h = Float64(step) * max(1.0, abs(x[i]))
        plus = copy(x)
        minus = copy(x)
        plus[i] += h
        minus[i] -= h
        grad[i] = (objective(plus) - objective(minus)) / (2.0 * h)
    end
    return (rms=sqrt(mean(abs2, grad)), max_abs=maximum(abs.(grad)))
end

function _finite_difference_gradient_vector(objective, free::AbstractVector{<:Real}; step::Real=1.0e-5)
    x = Float64.(free)
    hscale = Float64(step)
    hscale > 0.0 || throw(ArgumentError("finite-difference gradient step must be positive"))
    gradient = zeros(Float64, length(x))
    for i in eachindex(x)
        h = hscale * max(1.0, abs(x[i]))
        plus = copy(x)
        minus = copy(x)
        plus[i] += h
        minus[i] -= h
        gradient[i] = (objective(plus) - objective(minus)) / (2.0 * h)
    end
    return gradient
end

function _projected_scalar_functional_value(
    objective,
    coeffs::AbstractVector{<:Real};
    reference_coeffs=nothing,
    finite_difference_step::Real=1.0e-5,
)
    values = Float64.(coeffs)
    reference = reference_coeffs === nothing ? zeros(Float64, length(values)) :
                Float64.(collect(reference_coeffs))
    length(reference) == length(values) ||
        throw(DimensionMismatch("reference coefficient length must match coefficients"))
    reference_value = objective(reference)
    isfinite(reference_value) ||
        throw(DomainError(reference_value, "projected scalar functional must be finite at reference"))
    value = objective(values)
    isfinite(value) ||
        throw(DomainError(value, "projected scalar functional must be finite at coefficients"))
    reference_gradient = _finite_difference_gradient_vector(
        objective, reference; step=finite_difference_step)
    return value - reference_value - dot(reference_gradient, values .- reference)
end

function _profile_coefficient_trust_region_barrier(
    coeffs::AbstractVector{<:Real},
    radius::Real;
    strength::Real=0.0,
    exponent::Real=2.0,
)
    r = Float64(radius)
    isfinite(r) && r > 0.0 ||
        throw(ArgumentError("trust-region radius must be positive and finite"))
    s = Float64(strength)
    isfinite(s) && s >= 0.0 ||
        throw(ArgumentError("trust-region strength must be nonnegative and finite"))
    p = Float64(exponent)
    isfinite(p) && p > 0.0 ||
        throw(ArgumentError("trust-region exponent must be positive and finite"))
    values = Float64.(coeffs)
    norm_value = sqrt(sum(abs2, values))
    norm_value <= r && return 0.0
    s == 0.0 && return Inf
    return s * (norm_value / r - 1.0)^p
end

function _finite_difference_hessian(objective, free::AbstractVector{<:Real}; step::Real=1.0e-4)
    x = Float64.(free)
    hscale = Float64(step)
    hscale > 0.0 || throw(ArgumentError("finite-difference Hessian step must be positive"))
    n = length(x)
    hessian = zeros(Float64, n, n)
    n == 0 && return hessian
    f0 = objective(x)
    isfinite(f0) || throw(DomainError(f0, "finite-difference Hessian objective must be finite at the expansion point"))
    steps = [hscale * max(1.0, abs(x[i])) for i in 1:n]
    for i in 1:n
        hi = steps[i]
        plus = copy(x)
        minus = copy(x)
        plus[i] += hi
        minus[i] -= hi
        hessian[i, i] = (objective(plus) - 2.0 * f0 + objective(minus)) / hi^2
        for j in (i + 1):n
            hj = steps[j]
            pp = copy(x)
            pm = copy(x)
            mp = copy(x)
            mm = copy(x)
            pp[i] += hi; pp[j] += hj
            pm[i] += hi; pm[j] -= hj
            mp[i] -= hi; mp[j] += hj
            mm[i] -= hi; mm[j] -= hj
            value = (objective(pp) - objective(pm) - objective(mp) + objective(mm)) /
                    (4.0 * hi * hj)
            hessian[i, j] = value
            hessian[j, i] = value
        end
    end
    return hessian
end

function _slit_hevk1_functional_derivative(
    phi::AbstractVector{<:Real},
    grid::SlitGrid1D,
    params::SlitParams;
    step::Real=1.0e-5,
)
    _slit_validate_phi(phi, grid)
    density = Float64.(phi)
    hscale = Float64(step)
    hscale > 0.0 || throw(ArgumentError("finite-difference step must be positive"))
    force = zeros(Float64, grid.Nz)
    for i in 1:grid.Nz
        raw_h = hscale * max(1.0, abs(density[i]))
        h = min(raw_h, 0.45 * density[i])
        h > 0.0 || throw(DomainError(density[i], "density perturbation step must remain positive"))
        plus = copy(density)
        minus = copy(density)
        plus[i] += h
        minus[i] -= h
        force[i] = (slit_hevk1_energy(plus, grid, params) -
                    slit_hevk1_energy(minus, grid, params)) / (2.0 * h * grid.weights[i])
    end
    return force
end

function fit_slit_vk1_local_potential(;
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    Nz::Integer=40,
    L::Real=1.0,
    alpha::Real=0.0,
    target_xi_eff::Real=0.32705597929753805,
    target_profile=nothing,
    finite_difference_step::Real=1.0e-5,
    target_source::AbstractString="Alexander-Katz Fig. 3 Eq. 22 fit to digitized filled-square CL points",
)
    grid = SlitGrid1D(Nz, L)
    target_phi = if target_profile === nothing
        slit_reference_profile(grid.z; B=B, C=C, L=grid.L, xi=target_xi_eff)
    else
        length(target_profile) == grid.Nz ||
            throw(DimensionMismatch("target_profile length must match Nz"))
        normalize_slit_density(Float64.(target_profile), grid)
    end
    base_params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A),
        alpha=Float64(alpha), model=:vk1, local_potential_coeffs=(0.0, 0.0, 0.0))
    vk1_force = _slit_hevk1_functional_derivative(target_phi, grid, base_params;
        step=finite_difference_step)
    design = Matrix{Float64}(undef, grid.Nz, 4)
    for i in 1:grid.Nz
        eta = target_phi[i] - 1.0
        design[i, 1] = 1.0
        design[i, 2] = log(target_phi[i])
        design[i, 3] = eta
        design[i, 4] = eta^2 / (1.0 + eta^2)
    end
    beta = design \ vk1_force
    mu = beta[1]
    coeffs = (beta[2], beta[3], beta[4])
    residual_force = vk1_force .- mu
    fitted_force = [
        _slit_local_potential_derivative(target_phi[i], coeffs)
        for i in 1:grid.Nz
    ]
    fit_residual = residual_force .- fitted_force
    rmse = sqrt(mean(abs2, fit_residual))
    sst = sum((residual_force .- mean(residual_force)) .^ 2)
    sse = sum(abs2, fit_residual)
    r2 = sst <= eps(Float64) ? (sse <= eps(Float64) ? 1.0 : -Inf) : 1.0 - sse / sst
    corrected_params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A),
        alpha=Float64(alpha), model=:vk1, local_potential_coeffs=coeffs)
    return SlitLocalPotentialFitResult(
        grid,
        corrected_params,
        target_phi,
        residual_force,
        fitted_force,
        coeffs,
        mu,
        rmse,
        r2,
        Float64(target_xi_eff),
        String(target_source),
    )
end

function minimize_slit_vk1_field_saddle(
    B::Real,
    C::Real,
    A::Real;
    Nz::Integer=80,
    L::Real=1.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    max_iterations::Integer=300,
    initial_profile=nothing,
)
    grid = SlitGrid1D(Nz, L)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs)
    ansatz = minimize_slit_density(:vk1, B, C, A; Nz=Nz, L=L, alpha=alpha)
    reference = slit_reference_profile(grid.z; B=B, C=C, L=grid.L)
    reference_energy = slit_hevk1_energy(reference, grid, params)
    initial_phi = copy(ansatz.phi)
    initial_energy = ansatz.energy
    if initial_profile !== nothing
        candidate_initial = normalize_slit_density(Float64.(initial_profile), grid)
        _slit_validate_phi(candidate_initial, grid)
        candidate_initial_energy = slit_hevk1_energy(candidate_initial, grid, params)
        if isfinite(candidate_initial_energy) && candidate_initial_energy <= initial_energy
            initial_phi = candidate_initial
            initial_energy = candidate_initial_energy
        end
    end
    initial_free = _slit_free_log_density_from_profile(initial_phi, grid)
    objective_calls = Ref(0)
    objective(free) = begin
        objective_calls[] += 1
        profile = _slit_profile_from_free_log_density(free, grid)
        energy = slit_hevk1_energy(profile, grid, params)
        return isfinite(energy) ? energy : floatmax(Float64) / 4.0
    end
    result = Optim.optimize(
        objective,
        initial_free,
        Optim.LBFGS(),
        Optim.Options(iterations=max(1, Int(max_iterations))),
    )
    candidate_phi = _slit_profile_from_free_log_density(Optim.minimizer(result), grid)
    candidate_energy = slit_hevk1_energy(candidate_phi, grid, params)
    if !isfinite(candidate_energy) || candidate_energy > initial_energy
        candidate_phi = copy(initial_phi)
        candidate_energy = initial_energy
    end
    final_free = _slit_free_log_density_from_profile(candidate_phi, grid)
    gradient = _finite_difference_projected_gradient(objective, final_free)
    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, candidate_phi; L=grid.L)
    rms = sqrt(mean((candidate_phi .- reference) .^ 2))
    max_abs_error = maximum(abs.(candidate_phi .- reference))
    return SlitFieldSaddleResult(
        :vk1,
        "full_field_log_density_lbfgs",
        grid,
        params,
        candidate_phi,
        reference,
        copy(ansatz.phi),
        candidate_energy,
        reference_energy,
        ansatz.energy,
        xi_eff,
        xi_fit_error,
        _slit_bulk_xi(B, C),
        rms,
        max_abs_error,
        ansatz.rms_reference_error,
        gradient.rms,
        gradient.max_abs,
        Optim.converged(result) && candidate_energy <= ansatz.energy + 1.0e-10,
        Optim.iterations(result),
        objective_calls[],
        _slit_status(params),
    )
end

function minimize_slit_vk1_smooth_basis_saddle(
    B::Real,
    C::Real,
    A::Real;
    Nz::Integer=160,
    L::Real=1.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    basis_count::Integer=24,
    max_iterations::Integer=30000,
)
    grid = SlitGrid1D(Nz, L)
    count = min(max(1, Int(basis_count)), grid.Nz - 1)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs)
    ansatz = minimize_slit_density(:vk1, B, C, A; Nz=Nz, L=L, alpha=alpha)
    reference = slit_reference_profile(grid.z; B=B, C=C, L=grid.L)
    reference_energy = slit_hevk1_energy(reference, grid, params)
    basis = _slit_cosine_basis_matrix(grid, count)
    initial_coeffs = zeros(Float64, count)
    objective_calls = Ref(0)
    objective(coeffs) = begin
        objective_calls[] += 1
        profile = _slit_profile_from_smooth_coefficients(coeffs, ansatz.phi, basis, grid)
        energy = slit_hevk1_energy(profile, grid, params)
        return isfinite(energy) ? energy : floatmax(Float64) / 4.0
    end
    result = Optim.optimize(
        objective,
        initial_coeffs,
        Optim.NelderMead(),
        Optim.Options(iterations=max(1, Int(max_iterations)), x_abstol=1.0e-8, f_reltol=1.0e-10),
    )
    candidate_coeffs = Float64.(Optim.minimizer(result))
    candidate_phi = _slit_profile_from_smooth_coefficients(candidate_coeffs, ansatz.phi, basis, grid)
    candidate_energy = slit_hevk1_energy(candidate_phi, grid, params)
    if !isfinite(candidate_energy) || candidate_energy > ansatz.energy
        candidate_coeffs = initial_coeffs
        candidate_phi = copy(ansatz.phi)
        candidate_energy = ansatz.energy
    end
    gradient = _finite_difference_projected_gradient(objective, candidate_coeffs)
    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, candidate_phi; L=grid.L)
    rms = sqrt(mean((candidate_phi .- reference) .^ 2))
    max_abs_error = maximum(abs.(candidate_phi .- reference))
    return SlitFieldSaddleResult(
        :vk1,
        "smooth_log_density_cosine_nelder_mead_$(count)",
        grid,
        params,
        candidate_phi,
        reference,
        copy(ansatz.phi),
        candidate_energy,
        reference_energy,
        ansatz.energy,
        xi_eff,
        xi_fit_error,
        _slit_bulk_xi(B, C),
        rms,
        max_abs_error,
        ansatz.rms_reference_error,
        gradient.rms,
        gradient.max_abs,
        Optim.converged(result) && candidate_energy <= ansatz.energy + 1.0e-10,
        Optim.iterations(result),
        objective_calls[],
        _slit_status(params),
    )
end

function run_slit_noise_profile_mc(
    B::Real,
    C::Real,
    A::Real;
    Nz::Integer=80,
    L::Real=1.0,
    alpha::Real=0.0,
    basis_count::Integer=4,
    steps::Integer=80_000,
    burnin_steps::Integer=20_000,
    sample_stride::Integer=20,
    proposal_width::Real=0.03,
    temperature::Real=1.0,
    seed::Integer=1701,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    grid = SlitGrid1D(Nz, L)
    count = min(max(1, Int(basis_count)), grid.Nz - 1)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha), model=:vk1)
    xi_bulk = _slit_bulk_xi(B, C)
    saddle_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.L, xi=xi_bulk)
    basis = _slit_cosine_basis_matrix(grid, count)
    coeffs = zeros(Float64, count)
    phi = _slit_profile_from_smooth_coefficients(coeffs, saddle_phi, basis, grid)
    energy = slit_hevk1_energy(phi, grid, params)
    rng = StableRNG(seed)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    accepted = 0
    attempted = 0

    for step in 1:total_steps
        attempted += 1
        proposal_coeffs = copy(coeffs)
        mode = rand(rng, 1:count)
        proposal_coeffs[mode] += randn(rng) * width / sqrt(Float64(mode))
        proposed_phi = _slit_profile_from_smooth_coefficients(proposal_coeffs, saddle_phi, basis, grid)
        proposed_energy = slit_hevk1_energy(proposed_phi, grid, params)
        if isfinite(proposed_energy)
            log_acceptance = -(proposed_energy - energy) / temp
            if log(rand(rng)) < min(0.0, log_acceptance)
                coeffs = proposal_coeffs
                phi = proposed_phi
                energy = proposed_energy
                accepted += 1
            end
        end
        if step > burn && (step - burn) % stride == 0
            for i in 1:grid.Nz
                push!(profile_traces[i], phi[i])
            end
            push!(energy_trace, energy)
        end
    end

    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("MC run produced no stored samples; reduce burnin_steps or sample_stride"))
    mean_phi = [mean(trace) for trace in profile_traces]
    stderr_phi = [_markov_mean_stderr(trace) for trace in profile_traces]
    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.L)
    energy_summary = batch_summary(energy_trace)
    return SlitNoiseMCResult(
        grid,
        params,
        copy(saddle_phi),
        mean_phi,
        stderr_phi,
        accepted / max(attempted, 1),
        attempted,
        accepted,
        sample_count,
        total_steps,
        burn,
        stride,
        width,
        temp,
        count,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        xi_eff,
        xi_fit_error,
        xi_bulk,
    )
end

function _run_slit_3d_profile_mode_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    proposal_width::Real,
    temperature::Real,
    seed::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    count = size(basis, 2)
    count >= 1 || throw(ArgumentError("profile-mode basis must contain at least one mode"))

    coeffs = zeros(Float64, count)
    profile = _slit_profile_from_smooth_coefficients(coeffs, saddle_phi, basis, grid.slit_grid)
    energy = slit_hevk1_energy(profile, grid.slit_grid, params)
    rng = StableRNG(seed)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    coefficient_traces = [Float64[] for _ in 1:count]
    accepted = 0

    for step in 1:total_steps
        proposal_coeffs = copy(coeffs)
        mode = rand(rng, 1:count)
        proposal_coeffs[mode] += randn(rng) * width / sqrt(Float64(mode))
        proposed_profile = _slit_profile_from_smooth_coefficients(
            proposal_coeffs, saddle_phi, basis, grid.slit_grid)
        proposed_energy = slit_hevk1_energy(proposed_profile, grid.slit_grid, params)
        if isfinite(proposed_energy)
            log_acceptance = -(proposed_energy - energy) / temp
            if log(rand(rng)) < min(0.0, log_acceptance)
                coeffs = proposal_coeffs
                profile = proposed_profile
                energy = proposed_energy
                accepted += 1
            end
        end
        if step > burn && (step - burn) % stride == 0
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, energy)
            push!(density_variance_trace, var(profile; corrected=false))
            push!(lateral_variance_trace, 0.0)
            push!(xy_profile_roughness_trace, _slit_profile_roughness(profile, grid.slit_grid))
        end
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("profile-mode 3D MC stored no profile samples"))
    return (
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        sample_count=sample_count,
        accepted_moves=accepted,
        attempted_moves=total_steps,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
    )
end

function _run_slit_3d_spectral_mode_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    basis::AbstractMatrix{<:Real};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    proposal_width::Real,
    temperature::Real,
    seed::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    count = size(basis, 2)
    count >= 1 || throw(ArgumentError("spectral basis must contain at least one mode"))

    coeffs = zeros(Float64, count)
    field = _slit_3d_field_from_spectral_coefficients(coeffs, saddle_phi, basis, grid)
    energy = slit_hevk1_energy_3d(field, grid, params)
    rng = StableRNG(seed)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    coefficient_traces = [Float64[] for _ in 1:count]
    accepted = 0

    for step in 1:total_steps
        proposal_coeffs = copy(coeffs)
        mode = rand(rng, 1:count)
        proposal_coeffs[mode] += randn(rng) * width / sqrt(Float64(mode))
        proposed_field = _slit_3d_field_from_spectral_coefficients(
            proposal_coeffs, saddle_phi, basis, grid)
        proposed_energy = slit_hevk1_energy_3d(proposed_field, grid, params)
        if isfinite(proposed_energy)
            log_acceptance = -(proposed_energy - energy) / temp
            if log(rand(rng)) < min(0.0, log_acceptance)
                coeffs = proposal_coeffs
                field = proposed_field
                energy = proposed_energy
                accepted += 1
            end
        end
        if step > burn && (step - burn) % stride == 0
            profile = _slit_3d_xy_profile(field, grid)
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, energy)
            push!(density_variance_trace, var(vec(field); corrected=false))
            push!(lateral_variance_trace, _slit_3d_lateral_variance(field, grid))
            push!(xy_profile_roughness_trace, _slit_profile_roughness(profile, grid.slit_grid))
            for mode in 1:count
                push!(coefficient_traces[mode], coeffs[mode])
            end
        end
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("spectral-mode 3D MC stored no profile samples"))
    return (
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        coefficient_traces=coefficient_traces,
        sample_count=sample_count,
        accepted_moves=accepted,
        attempted_moves=total_steps,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
    )
end

function _run_slit_3d_blocked_spectral_mode_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    z_basis::AbstractMatrix{<:Real},
    lateral_basis::AbstractMatrix{<:Real};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    proposal_width::Real,
    profile_proposal_width=nothing,
    lateral_proposal_width=nothing,
    temperature::Real,
    seed::Integer,
    lateral_mode_quadratic_coeffs=(),
    spectral_mode_quadratic_coeffs=(),
    profile_mode_quadratic_matrix=(),
    profile_coordinate_jacobian_coeff::Real=0.0,
    profile_xi_potential_coeff::Real=0.0,
    profile_xi_potential_xi_values=(),
    profile_xi_potential_values=(),
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    profile_width = profile_proposal_width === nothing ? width : Float64(profile_proposal_width)
    lateral_width = lateral_proposal_width === nothing ? width : Float64(lateral_proposal_width)
    profile_width > 0.0 || throw(ArgumentError("profile_proposal_width must be positive"))
    lateral_width > 0.0 || throw(ArgumentError("lateral_proposal_width must be positive"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    z_count = size(z_basis, 2)
    lateral_count = size(lateral_basis, 2)
    count = z_count + lateral_count
    count >= 1 || throw(ArgumentError("blocked spectral basis must contain at least one mode"))
    lateral_mode_weights =
        _slit_lateral_mode_quadratic_coeffs(lateral_mode_quadratic_coeffs, lateral_count)
    spectral_mode_weights =
        _slit_spectral_mode_quadratic_coeffs(spectral_mode_quadratic_coeffs, count)
    total_mode_weights = _slit_blocked_spectral_mode_quadratic_coeffs(
        spectral_mode_weights, lateral_mode_weights, z_count, lateral_count)
    profile_quadratic_matrix =
        _slit_profile_mode_quadratic_matrix(profile_mode_quadratic_matrix, z_count)
    profile_log_jacobian_coeff =
        _slit_profile_coordinate_jacobian_coeff(profile_coordinate_jacobian_coeff)
    profile_xi_coeff = _slit_profile_xi_potential_coeff(profile_xi_potential_coeff)
    profile_xi_values, profile_xi_potential_table_values =
        _slit_profile_xi_potential_table(
            profile_xi_potential_xi_values, profile_xi_potential_values;
            allow_empty=profile_xi_coeff == 0.0)
    profile_xi_coeff == 0.0 || z_count > 0 ||
        throw(ArgumentError("profile_xi_potential_coeff requires at least one profile z basis mode"))
    reference_profile_coeffs = zeros(Float64, z_count)
    reference_profile_log_jacobian =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? 0.0 :
        _slit_profile_coordinate_log_jacobian(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
    reference_profile_log_jacobian_gradient =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? Float64[] :
        _slit_profile_coordinate_log_jacobian_gradient(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
    reference_profile_xi_potential =
        z_count == 0 || profile_xi_coeff == 0.0 ? 0.0 :
        _slit_profile_xi_potential(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
            profile_xi_values, profile_xi_potential_table_values)
    reference_profile_xi_potential_gradient =
        z_count == 0 || profile_xi_coeff == 0.0 ? Float64[] :
        _slit_profile_xi_potential_gradient(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
            profile_xi_values, profile_xi_potential_table_values)

    field_from_coeffs(coeffs) = _slit_3d_field_from_blocked_spectral_coefficients(
        z_count == 0 ? Float64[] : @view(coeffs[1:z_count]),
        lateral_count == 0 ? Float64[] : @view(coeffs[(z_count + 1):count]),
        saddle_phi,
        z_basis,
        lateral_basis,
        grid,
    )
    lateral_coeffs_from(coeffs) =
        lateral_count == 0 ? Float64[] : @view(coeffs[(z_count + 1):count])
    profile_log_jacobian_energy(coeffs) =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? 0.0 :
        begin
            profile_coeffs = @view(coeffs[1:z_count])
            log_j = _slit_profile_coordinate_log_jacobian(
                profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
            -profile_log_jacobian_coeff *
            (log_j - reference_profile_log_jacobian -
             dot(reference_profile_log_jacobian_gradient, profile_coeffs))
        end
    profile_quadratic_energy(coeffs) =
        z_count == 0 ? 0.0 :
        _slit_profile_mode_quadratic_energy(
            @view(coeffs[1:z_count]), profile_quadratic_matrix)
    profile_xi_potential_energy(coeffs) =
        z_count == 0 || profile_xi_coeff == 0.0 ? 0.0 :
        begin
            profile_coeffs = @view(coeffs[1:z_count])
            potential = _slit_profile_xi_potential(
                profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
                profile_xi_values, profile_xi_potential_table_values)
            profile_xi_coeff *
            (potential - reference_profile_xi_potential -
             dot(reference_profile_xi_potential_gradient, profile_coeffs))
        end

    coeffs = zeros(Float64, count)
    field = field_from_coeffs(coeffs)
    energy = slit_hevk1_energy_3d(field, grid, params) +
             _slit_spectral_mode_quadratic_energy(coeffs, total_mode_weights) +
             profile_quadratic_energy(coeffs) +
             profile_log_jacobian_energy(coeffs) +
             profile_xi_potential_energy(coeffs)
    rng = StableRNG(seed)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    coefficient_traces = [Float64[] for _ in 1:count]
    accepted = 0

    for step in 1:total_steps
        proposal_coeffs = copy(coeffs)
        mode = rand(rng, 1:count)
        mode_width = mode <= z_count ? profile_width : lateral_width
        proposal_coeffs[mode] += randn(rng) * mode_width / sqrt(Float64(mode))
        proposed_field = field_from_coeffs(proposal_coeffs)
        proposed_energy = slit_hevk1_energy_3d(proposed_field, grid, params) +
                          _slit_spectral_mode_quadratic_energy(
                              proposal_coeffs, total_mode_weights) +
                          profile_quadratic_energy(proposal_coeffs) +
                          profile_log_jacobian_energy(proposal_coeffs) +
                          profile_xi_potential_energy(proposal_coeffs)
        if isfinite(proposed_energy)
            log_acceptance = -(proposed_energy - energy) / temp
            if log(rand(rng)) < min(0.0, log_acceptance)
                coeffs = proposal_coeffs
                field = proposed_field
                energy = proposed_energy
                accepted += 1
            end
        end
        if step > burn && (step - burn) % stride == 0
            profile = _slit_3d_xy_profile(field, grid)
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, energy)
            push!(density_variance_trace, var(vec(field); corrected=false))
            push!(lateral_variance_trace, _slit_3d_lateral_variance(field, grid))
            push!(xy_profile_roughness_trace, _slit_profile_roughness(profile, grid.slit_grid))
            for mode in 1:count
                push!(coefficient_traces[mode], coeffs[mode])
            end
        end
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("blocked spectral-mode 3D MC stored no profile samples"))
    return (
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        coefficient_traces=coefficient_traces,
        sample_count=sample_count,
        accepted_moves=accepted,
        attempted_moves=total_steps,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
    )
end

function _slit_replica_temperature_values(replica_temperatures, target_temperature::Real)
    target = Float64(target_temperature)
    target > 0.0 && isfinite(target) ||
        throw(ArgumentError("target replica temperature must be positive and finite"))
    values = Float64.(collect(replica_temperatures))
    isempty(values) && return [target]
    all(value -> value > 0.0 && isfinite(value), values) ||
        throw(ArgumentError("replica_temperatures must be positive and finite"))
    if !any(value -> isapprox(value, target; rtol=0.0, atol=1.0e-12), values)
        push!(values, target)
    end
    values = sort(unique(values))
    return values
end

function _run_slit_3d_blocked_spectral_replica_exchange_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    z_basis::AbstractMatrix{<:Real},
    lateral_basis::AbstractMatrix{<:Real};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    proposal_width::Real,
    profile_proposal_width=nothing,
    lateral_proposal_width=nothing,
    target_temperature::Real,
    replica_temperatures,
    replica_swap_interval::Integer,
    seed::Integer,
    lateral_mode_quadratic_coeffs=(),
    spectral_mode_quadratic_coeffs=(),
    profile_mode_quadratic_matrix=(),
    profile_coordinate_jacobian_coeff::Real=0.0,
    profile_xi_potential_coeff::Real=0.0,
    profile_xi_potential_xi_values=(),
    profile_xi_potential_values=(),
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    profile_width = profile_proposal_width === nothing ? width : Float64(profile_proposal_width)
    lateral_width = lateral_proposal_width === nothing ? width : Float64(lateral_proposal_width)
    profile_width > 0.0 || throw(ArgumentError("profile_proposal_width must be positive"))
    lateral_width > 0.0 || throw(ArgumentError("lateral_proposal_width must be positive"))
    temperatures = _slit_replica_temperature_values(replica_temperatures, target_temperature)
    beta_values = 1.0 ./ temperatures
    target_temp = Float64(target_temperature)
    target_idx = findfirst(value -> isapprox(value, target_temp; rtol=0.0, atol=1.0e-12),
        temperatures)
    target_idx === nothing && throw(ArgumentError("replica temperature ladder must include target_temperature"))
    swap_every = max(1, Int(replica_swap_interval))
    z_count = size(z_basis, 2)
    lateral_count = size(lateral_basis, 2)
    count = z_count + lateral_count
    count >= 1 || throw(ArgumentError("blocked spectral basis must contain at least one mode"))
    lateral_mode_weights =
        _slit_lateral_mode_quadratic_coeffs(lateral_mode_quadratic_coeffs, lateral_count)
    spectral_mode_weights =
        _slit_spectral_mode_quadratic_coeffs(spectral_mode_quadratic_coeffs, count)
    total_mode_weights = _slit_blocked_spectral_mode_quadratic_coeffs(
        spectral_mode_weights, lateral_mode_weights, z_count, lateral_count)
    profile_quadratic_matrix =
        _slit_profile_mode_quadratic_matrix(profile_mode_quadratic_matrix, z_count)
    profile_log_jacobian_coeff =
        _slit_profile_coordinate_jacobian_coeff(profile_coordinate_jacobian_coeff)
    profile_xi_coeff = _slit_profile_xi_potential_coeff(profile_xi_potential_coeff)
    profile_xi_values, profile_xi_potential_table_values =
        _slit_profile_xi_potential_table(
            profile_xi_potential_xi_values, profile_xi_potential_values;
            allow_empty=profile_xi_coeff == 0.0)
    profile_xi_coeff == 0.0 || z_count > 0 ||
        throw(ArgumentError("profile_xi_potential_coeff requires at least one profile z basis mode"))
    reference_profile_coeffs = zeros(Float64, z_count)
    reference_profile_log_jacobian =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? 0.0 :
        _slit_profile_coordinate_log_jacobian(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
    reference_profile_log_jacobian_gradient =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? Float64[] :
        _slit_profile_coordinate_log_jacobian_gradient(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
    reference_profile_xi_potential =
        z_count == 0 || profile_xi_coeff == 0.0 ? 0.0 :
        _slit_profile_xi_potential(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
            profile_xi_values, profile_xi_potential_table_values)
    reference_profile_xi_potential_gradient =
        z_count == 0 || profile_xi_coeff == 0.0 ? Float64[] :
        _slit_profile_xi_potential_gradient(
            reference_profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
            profile_xi_values, profile_xi_potential_table_values)

    field_from_coeffs(coeffs) = _slit_3d_field_from_blocked_spectral_coefficients(
        z_count == 0 ? Float64[] : @view(coeffs[1:z_count]),
        lateral_count == 0 ? Float64[] : @view(coeffs[(z_count + 1):count]),
        saddle_phi,
        z_basis,
        lateral_basis,
        grid,
    )
    lateral_coeffs_from(coeffs) =
        lateral_count == 0 ? Float64[] : @view(coeffs[(z_count + 1):count])
    profile_log_jacobian_energy(coeffs) =
        z_count == 0 || profile_log_jacobian_coeff == 0.0 ? 0.0 :
        begin
            profile_coeffs = @view(coeffs[1:z_count])
            log_j = _slit_profile_coordinate_log_jacobian(
                profile_coeffs, saddle_phi, z_basis, grid.slit_grid)
            -profile_log_jacobian_coeff *
            (log_j - reference_profile_log_jacobian -
             dot(reference_profile_log_jacobian_gradient, profile_coeffs))
        end
    profile_quadratic_energy(coeffs) =
        z_count == 0 ? 0.0 :
        _slit_profile_mode_quadratic_energy(
            @view(coeffs[1:z_count]), profile_quadratic_matrix)
    profile_xi_potential_energy(coeffs) =
        z_count == 0 || profile_xi_coeff == 0.0 ? 0.0 :
        begin
            profile_coeffs = @view(coeffs[1:z_count])
            potential = _slit_profile_xi_potential(
                profile_coeffs, saddle_phi, z_basis, grid.slit_grid,
                profile_xi_values, profile_xi_potential_table_values)
            profile_xi_coeff *
            (potential - reference_profile_xi_potential -
             dot(reference_profile_xi_potential_gradient, profile_coeffs))
        end
    energy_from_coeffs(coeffs) = begin
        field = field_from_coeffs(coeffs)
        slit_hevk1_energy_3d(field, grid, params) +
            _slit_spectral_mode_quadratic_energy(coeffs, total_mode_weights) +
            profile_quadratic_energy(coeffs) +
            profile_log_jacobian_energy(coeffs) +
            profile_xi_potential_energy(coeffs)
    end

    rng = StableRNG(seed)
    nreplicas = length(temperatures)
    states = [zeros(Float64, count) for _ in 1:nreplicas]
    fields = [field_from_coeffs(states[replica_idx]) for replica_idx in 1:nreplicas]
    energies = [energy_from_coeffs(states[replica_idx]) for replica_idx in 1:nreplicas]
    replica_labels = collect(1:nreplicas)
    label_min_seen = falses(nreplicas)
    label_max_seen = falses(nreplicas)
    label_round_trips = zeros(Int, nreplicas)
    label_min_seen[replica_labels[1]] = true
    label_max_seen[replica_labels[end]] = true

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    coefficient_traces = [Float64[] for _ in 1:count]
    accepted = 0
    attempted = 0
    swap_attempts = 0
    swap_accepts = 0

    for step in 1:total_steps
        for replica_idx in 1:nreplicas
            attempted += 1
            proposal_coeffs = copy(states[replica_idx])
            mode = rand(rng, 1:count)
            mode_width = mode <= z_count ? profile_width : lateral_width
            proposal_coeffs[mode] += randn(rng) * mode_width / sqrt(Float64(mode))
            proposed_field = field_from_coeffs(proposal_coeffs)
            proposed_energy = slit_hevk1_energy_3d(proposed_field, grid, params) +
                              _slit_spectral_mode_quadratic_energy(
                                  proposal_coeffs, total_mode_weights) +
                              profile_quadratic_energy(proposal_coeffs) +
                              profile_log_jacobian_energy(proposal_coeffs) +
                              profile_xi_potential_energy(proposal_coeffs)
            if isfinite(proposed_energy)
                log_acceptance = -beta_values[replica_idx] *
                                 (proposed_energy - energies[replica_idx])
                if log(rand(rng)) < min(0.0, log_acceptance)
                    states[replica_idx] = proposal_coeffs
                    fields[replica_idx] = proposed_field
                    energies[replica_idx] = proposed_energy
                    accepted += 1
                end
            end
        end
        if nreplicas > 1 && step % swap_every == 0
            for replica_idx in 1:(nreplicas - 1)
                beta_i = beta_values[replica_idx]
                beta_j = beta_values[replica_idx + 1]
                energy_i = energies[replica_idx]
                energy_j = energies[replica_idx + 1]
                log_swap = (beta_i - beta_j) * (energy_i - energy_j)
                swap_attempts += 1
                if log(rand(rng)) < min(0.0, log_swap)
                    states[replica_idx], states[replica_idx + 1] =
                        states[replica_idx + 1], states[replica_idx]
                    fields[replica_idx], fields[replica_idx + 1] =
                        fields[replica_idx + 1], fields[replica_idx]
                    energies[replica_idx], energies[replica_idx + 1] =
                        energies[replica_idx + 1], energies[replica_idx]
                    replica_labels[replica_idx], replica_labels[replica_idx + 1] =
                        replica_labels[replica_idx + 1], replica_labels[replica_idx]
                    swap_accepts += 1
                end
            end
            for slot in 1:nreplicas
                label = replica_labels[slot]
                if slot == 1
                    if label_max_seen[label]
                        label_round_trips[label] += 1
                        label_max_seen[label] = false
                    end
                    label_min_seen[label] = true
                elseif slot == nreplicas
                    if label_min_seen[label]
                        label_round_trips[label] += 1
                        label_min_seen[label] = false
                    end
                    label_max_seen[label] = true
                end
            end
        end
        if step > burn && (step - burn) % stride == 0
            field = fields[target_idx]
            coeffs = states[target_idx]
            profile = _slit_3d_xy_profile(field, grid)
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, energies[target_idx])
            push!(density_variance_trace, var(vec(field); corrected=false))
            push!(lateral_variance_trace, _slit_3d_lateral_variance(field, grid))
            push!(xy_profile_roughness_trace, _slit_profile_roughness(profile, grid.slit_grid))
            for mode in 1:count
                push!(coefficient_traces[mode], coeffs[mode])
            end
        end
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("replica-exchange spectral-mode 3D MC stored no profile samples"))
    return (
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        coefficient_traces=coefficient_traces,
        sample_count=sample_count,
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
        replica_count=nreplicas,
        replica_temperatures=temperatures,
        replica_swap_interval=swap_every,
        replica_swap_attempts=swap_attempts,
        replica_swap_accepts=swap_accepts,
        replica_round_trips=sum(label_round_trips),
        replica_min_round_trips=minimum(label_round_trips),
        replica_max_round_trips=maximum(label_round_trips),
    )
end

function _slit_3d_blocked_spectral_energy_from_coefficients(
    coeffs::AbstractVector{<:Real},
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    z_basis::AbstractMatrix{<:Real},
    lateral_basis::AbstractMatrix{<:Real},
    spectral_mode_weights::AbstractVector{<:Real};
    profile_mode_quadratic_matrix=(),
    profile_coordinate_jacobian_coeff::Real=0.0,
    profile_xi_potential_coeff::Real=0.0,
    profile_xi_potential_xi_values=(),
    profile_xi_potential_values=(),
)
    z_count = size(z_basis, 2)
    lateral_count = size(lateral_basis, 2)
    count = z_count + lateral_count
    length(coeffs) == count ||
        throw(DimensionMismatch("coefficient length must match blocked spectral basis count"))
    length(spectral_mode_weights) == count ||
        throw(DimensionMismatch("spectral quadratic weight length must match blocked spectral basis count"))
    profile_quadratic_matrix =
        _slit_profile_mode_quadratic_matrix(profile_mode_quadratic_matrix, z_count)
    lateral_coeffs = lateral_count == 0 ? Float64[] : @view(coeffs[(z_count + 1):count])
    field = _slit_3d_field_from_blocked_spectral_coefficients(
        z_count == 0 ? Float64[] : @view(coeffs[1:z_count]),
        lateral_coeffs,
        saddle_phi,
        z_basis,
        lateral_basis,
        grid,
    )
    profile_log_jacobian_energy = z_count == 0 ? 0.0 :
                                  _slit_profile_coordinate_log_jacobian_energy(
                                      @view(coeffs[1:z_count]),
                                      profile_coordinate_jacobian_coeff,
                                      saddle_phi, z_basis, grid.slit_grid)
    profile_quadratic_energy = z_count == 0 ? 0.0 :
                               _slit_profile_mode_quadratic_energy(
                                   @view(coeffs[1:z_count]),
                                   profile_quadratic_matrix)
    profile_xi_potential_energy = z_count == 0 ? 0.0 :
                                  _slit_profile_xi_potential_energy(
                                      @view(coeffs[1:z_count]),
                                      profile_xi_potential_coeff,
                                      saddle_phi, z_basis, grid.slit_grid,
                                      profile_xi_potential_xi_values,
                                      profile_xi_potential_values)
    return slit_hevk1_energy_3d(field, grid, params) +
           _slit_spectral_mode_quadratic_energy(coeffs, spectral_mode_weights) +
           profile_quadratic_energy +
           profile_log_jacobian_energy +
           profile_xi_potential_energy
end

function _write_slit_3d_spectral_coefficient_trace(
    outdir::AbstractString,
    traces,
    mode_metadata,
)
    rows = NamedTuple[]
    global_sample = 0
    for (chain_idx, trace) in enumerate(traces)
        coefficient_traces = trace.coefficient_traces
        length(coefficient_traces) == length(mode_metadata) ||
            throw(DimensionMismatch("coefficient trace count must match spectral mode metadata count"))
        sample_count = isempty(coefficient_traces) ? 0 : length(coefficient_traces[1])
        all(length(values) == sample_count for values in coefficient_traces) ||
            throw(DimensionMismatch("all coefficient traces in a chain must have the same sample count"))
        for sample_idx in 1:sample_count
            global_sample += 1
            for mode_idx in eachindex(mode_metadata)
                mode = mode_metadata[mode_idx]
                push!(rows, (
                    chain=chain_idx,
                    sample=sample_idx,
                    global_sample=global_sample,
                    mode_index=mode.mode_index,
                    mode_family=mode.mode_family,
                    z_basis_index=mode.z_basis_index,
                    mx=mode.mx,
                    my=mode.my,
                    lateral_zmode=mode.lateral_zmode,
                    phase_kind=mode.phase_kind,
                    coefficient=coefficient_traces[mode_idx][sample_idx],
                ))
            end
        end
    end
    return _write_dataframe(joinpath(outdir, "slit_3d_mc_coefficients.csv"), rows)
end

function _write_slit_3d_spectral_hessian(
    outdir::AbstractString,
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    z_basis::AbstractMatrix{<:Real},
    lateral_basis::AbstractMatrix{<:Real},
    spectral_mode_weights::AbstractVector{<:Real},
    mode_metadata;
    finite_difference_step::Real=1.0e-4,
    profile_mode_quadratic_matrix=(),
    profile_coordinate_jacobian_coeff::Real=0.0,
    profile_xi_potential_coeff::Real=0.0,
    profile_xi_potential_xi_values=(),
    profile_xi_potential_values=(),
)
    count = length(mode_metadata)
    count == size(z_basis, 2) + size(lateral_basis, 2) ||
        throw(DimensionMismatch("spectral mode metadata count must match blocked basis count"))
    objective(coeffs) = _slit_3d_blocked_spectral_energy_from_coefficients(
        coeffs, grid, params, saddle_phi, z_basis, lateral_basis, spectral_mode_weights;
        profile_mode_quadratic_matrix=profile_mode_quadratic_matrix,
        profile_coordinate_jacobian_coeff=profile_coordinate_jacobian_coeff,
        profile_xi_potential_coeff=profile_xi_potential_coeff,
        profile_xi_potential_xi_values=profile_xi_potential_xi_values,
        profile_xi_potential_values=profile_xi_potential_values)
    hessian = _finite_difference_hessian(objective, zeros(Float64, count);
        step=finite_difference_step)
    symmetric_hessian = Symmetric(0.5 .* (hessian .+ hessian'))
    eig = eigen(symmetric_hessian)
    rows = NamedTuple[]
    for eigen_index in eachindex(eig.values)
        vector = eig.vectors[:, eigen_index]
        dominant_mode_index = argmax(abs.(vector))
        mode = mode_metadata[dominant_mode_index]
        push!(rows, (
            eigen_index=eigen_index,
            eigenvalue=eig.values[eigen_index],
            dominant_mode_index=mode.mode_index,
            dominant_mode_family=mode.mode_family,
            dominant_z_basis_index=mode.z_basis_index,
            dominant_mx=mode.mx,
            dominant_my=mode.my,
            dominant_lateral_zmode=mode.lateral_zmode,
            dominant_phase_kind=mode.phase_kind,
            dominant_component=vector[dominant_mode_index],
            dominant_abs_component=abs(vector[dominant_mode_index]),
        ))
    end
    return _write_dataframe(joinpath(outdir, "slit_3d_spectral_hessian.csv"), rows)
end

function _slit_branch_label(xi_eff::Real, xi_branch_threshold::Real)
    xi = Float64(xi_eff)
    threshold = Float64(xi_branch_threshold)
    isfinite(threshold) && threshold > 0.0 ||
        throw(ArgumentError("xi_branch_threshold must be positive and finite"))
    isfinite(xi) || return "invalid"
    return xi <= threshold ? "narrow" : "broad"
end

function _write_slit_3d_spectral_branch_diagnostics(
    outdir::AbstractString,
    traces,
    mode_metadata,
    xi_blocks_csv::AbstractString;
    xi_branch_threshold::Real=0.55,
)
    blocks = CSV.read(xi_blocks_csv, DataFrames.DataFrame)
    branch_rows = NamedTuple[]
    summary = Dict{String,NamedTuple}()
    threshold = Float64(xi_branch_threshold)
    threshold > 0.0 && isfinite(threshold) ||
        throw(ArgumentError("xi_branch_threshold must be positive and finite"))
    for row in eachrow(blocks)
        chain_idx = Int(row.chain)
        sample_start = Int(row.sample_start)
        sample_stop = Int(row.sample_stop)
        sample_count = Int(row.sample_count)
        xi_eff = Float64(row.xi_eff)
        branch = _slit_branch_label(xi_eff, threshold)
        coefficient_traces = traces[chain_idx].coefficient_traces
        length(coefficient_traces) == length(mode_metadata) ||
            throw(DimensionMismatch("coefficient trace count must match spectral mode metadata count"))
        for mode_idx in eachindex(mode_metadata)
            values = @view coefficient_traces[mode_idx][sample_start:sample_stop]
            mode = mode_metadata[mode_idx]
            push!(branch_rows, (
                branch=branch,
                chain=chain_idx,
                block=Int(row.block),
                sample_start=sample_start,
                sample_stop=sample_stop,
                sample_count=sample_count,
                xi_eff=xi_eff,
                xi_fit_error=Float64(row.xi_fit_error),
                mode_index=mode.mode_index,
                mode_family=mode.mode_family,
                z_basis_index=mode.z_basis_index,
                mx=mode.mx,
                my=mode.my,
                lateral_zmode=mode.lateral_zmode,
                phase_kind=mode.phase_kind,
                coefficient_mean=mean(values),
                coefficient_std=length(values) > 1 ? std(values) : 0.0,
                coefficient_min=minimum(values),
                coefficient_max=maximum(values),
            ))
        end
        current = get(summary, branch, (
            block_count=0,
            sample_count=0,
            xi_sum=0.0,
            xi_min=Inf,
            xi_max=-Inf,
        ))
        summary[branch] = (
            block_count=current.block_count + 1,
            sample_count=current.sample_count + sample_count,
            xi_sum=current.xi_sum + xi_eff,
            xi_min=min(current.xi_min, xi_eff),
            xi_max=max(current.xi_max, xi_eff),
        )
    end
    summary_rows = NamedTuple[]
    total_blocks = sum(value.block_count for value in values(summary))
    total_samples = sum(value.sample_count for value in values(summary))
    for branch in sort(collect(keys(summary)))
        value = summary[branch]
        push!(summary_rows, (
            branch=branch,
            block_count=value.block_count,
            block_fraction=value.block_count / max(total_blocks, 1),
            sample_count=value.sample_count,
            sample_fraction=value.sample_count / max(total_samples, 1),
            mean_xi_eff=value.xi_sum / max(value.block_count, 1),
            min_xi_eff=value.xi_min,
            max_xi_eff=value.xi_max,
            xi_branch_threshold=threshold,
        ))
    end
    branch_blocks_csv = _write_dataframe(
        joinpath(outdir, "slit_3d_spectral_branch_blocks.csv"), branch_rows)
    branch_summary_csv = _write_dataframe(
        joinpath(outdir, "slit_3d_spectral_branch_summary.csv"), summary_rows)
    return branch_blocks_csv, branch_summary_csv
end

function _run_slit_3d_profile_direct_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    initial_profile::AbstractVector{<:Real};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    proposal_width::Real,
    temperature::Real,
    phi_min::Real,
    seed::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    width = Float64(proposal_width)
    width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    lower = max(Float64(phi_min), 0.0)
    lower < 1.0 || throw(ArgumentError("phi_min must be less than one"))

    profile = normalize_slit_density(initial_profile, grid.slit_grid)
    minimum(profile) > lower ||
        throw(DomainError(minimum(profile), "initial profile must be above phi_min"))
    energy = slit_hevk1_energy(profile, grid.slit_grid, params)
    rng = StableRNG(seed)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    accepted = 0

    for step in 1:total_steps
        k_from = rand(rng, 1:grid.Nz)
        k_to = rand(rng, 1:grid.Nz)
        while k_to == k_from
            k_to = rand(rng, 1:grid.Nz)
        end
        δ = (2.0 * rand(rng) - 1.0) * width
        proposed_profile = copy(profile)
        proposed_profile[k_from] += δ
        proposed_profile[k_to] -= δ
        if minimum(proposed_profile) > lower
            proposed_energy = slit_hevk1_energy(proposed_profile, grid.slit_grid, params)
            if isfinite(proposed_energy)
                log_acceptance = -(proposed_energy - energy) / temp
                if log(rand(rng)) < min(0.0, log_acceptance)
                    profile = proposed_profile
                    energy = proposed_energy
                    accepted += 1
                end
            end
        end
        if step > burn && (step - burn) % stride == 0
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, energy)
            push!(density_variance_trace, var(profile; corrected=false))
            push!(lateral_variance_trace, 0.0)
            push!(xy_profile_roughness_trace, _slit_profile_roughness(profile, grid.slit_grid))
        end
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("profile-direct 3D MC stored no profile samples"))
    return (
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        sample_count=sample_count,
        accepted_moves=accepted,
        attempted_moves=total_steps,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
    )
end

function _write_slit_3d_profile_mode_text(outdir::AbstractString, result::Slit3DMCResult, z_basis_count::Integer)
    path = joinpath(outdir, "slit_3d_profile_mode_validation.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 profile-mode Metropolis slit validation")
        println(io)
        println(io, "This artifact samples smooth normalized slit density profiles on a 3D grid. The sampled profile is lifted to an `Nx x Ny x Nz` field; because it is z-only, the code uses the exact 1D reduction of the 3D HE-VK1 energy. The Metropolis measure is over smooth profile-mode coefficients rather than over all density cells.")
        println(io)
        println(io, @sprintf("Parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`, grid = `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`, z-basis modes = %d.",
            result.params.B, result.params.C, result.params.A, result.grid.Nx,
            result.grid.Ny, result.grid.Nz, result.grid.Lxy, result.grid.Lz,
            Int(z_basis_count)))
        println(io)
        println(io, @sprintf("MC diagnostics: chains = %d, stored profiles = %d, attempted coefficient moves = %d, acceptance = %.6g, mean energy = %.6g +/- %.3g.",
            result.chain_count, result.sample_count, result.attempted_moves,
            result.acceptance_rate, result.energy_mean, result.energy_stderr))
        println(io, @sprintf("Profile fit: `xi_bulk = %.6g`, profile-mode MC `xi_eff = %.6g`, fit RMSE = %.6g, fit R2 = %.6g, wall RMS residual = %.6g, fit-quality pass = %.0f.",
            result.xi_bulk, result.xi_eff, result.xi_fit_rmse, result.xi_fit_r2,
            result.xi_fit_wall_rms, result.xi_fit_quality_pass))
        println(io)
        println(io, "Scope: this is the first corrected-measure 3D VK1 MC baseline after rejecting the unrestricted flat density-cell sampler. It is not yet a full lateral fluctuation theory; lateral variance is intentionally zero in this profile-mode baseline.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_profile_blocks.csv` and `slit_3d_mc_xi_blocks.csv`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function _write_slit_3d_spectral_mode_text(
    outdir::AbstractString,
    result::Slit3DMCResult,
    z_basis_count::Integer,
    lateral_mode_count::Integer,
    lateral_z_basis_count::Integer,
    spectral_basis_count::Integer,
    plane_normalized_lateral::Bool,
)
    path = joinpath(outdir, "slit_3d_spectral_mode_validation.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 spectral-mode Metropolis slit validation")
        println(io)
        println(io, "This artifact samples a positive normalized 3D density field represented by low-order log-density spectral coefficients. The field is evaluated on the slit grid and uses the full 3D HE-VK1 energy, but the sampled measure is over controlled smooth modes rather than all density cells.")
        println(io)
        println(io, @sprintf("Parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`, grid = `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`.",
            result.params.B, result.params.C, result.params.A, result.grid.Nx,
            result.grid.Ny, result.grid.Nz, result.grid.Lxy, result.grid.Lz))
        println(io, @sprintf("Basis: z-only modes = %d, lateral shell = %d, lateral-z modes = %d, total coefficients = %d.",
            Int(z_basis_count), Int(lateral_mode_count), Int(lateral_z_basis_count),
            Int(spectral_basis_count)))
        println(io, @sprintf("Lateral representation: plane-normalized = %s.",
            plane_normalized_lateral ? "true" : "false"))
        println(io)
        println(io, @sprintf("MC diagnostics: chains = %d, stored profiles = %d, attempted coefficient moves = %d, acceptance = %.6g, mean energy = %.6g +/- %.3g.",
            result.chain_count, result.sample_count, result.attempted_moves,
            result.acceptance_rate, result.energy_mean, result.energy_stderr))
        println(io, @sprintf("Profile fit: `xi_bulk = %.6g`, spectral-mode MC `xi_eff = %.6g`, fit RMSE = %.6g, fit R2 = %.6g, wall RMS residual = %.6g, fit-quality pass = %.0f.",
            result.xi_bulk, result.xi_eff, result.xi_fit_rmse, result.xi_fit_r2,
            result.xi_fit_wall_rms, result.xi_fit_quality_pass))
        println(io, @sprintf("Lateral fluctuation diagnostic: mean lateral variance = %.6g; mean xy-profile roughness = %.6g.",
            result.lateral_variance_mean, result.xy_profile_roughness_mean))
        println(io)
        println(io, "Scope: this is a controlled-mode 3D diagnostic between the z-only profile-mode sampler and the unrestricted density-cell sampler. It tests whether adding a finite lateral mode set preserves the AK-profile agreement before opening the full cell measure.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_profile_blocks.csv` and `slit_3d_mc_xi_blocks.csv`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function _write_slit_3d_profile_direct_text(outdir::AbstractString, result::Slit3DMCResult)
    path = joinpath(outdir, "slit_3d_profile_direct_validation.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 profile-direct Metropolis slit validation")
        println(io)
        println(io, "This artifact samples the positive normalized plane-mean density profile directly and lifts every sampled profile to the `Nx x Ny x Nz` slit grid. For z-only fields this uses the exact 3D HE-VK1 reduction, so it controls the plane-profile measure without opening the lateral density-cell simplex.")
        println(io)
        println(io, @sprintf("Parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`, grid = `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`.",
            result.params.B, result.params.C, result.params.A, result.grid.Nx, result.grid.Ny,
            result.grid.Nz, result.grid.Lxy, result.grid.Lz))
        println(io)
        println(io, @sprintf("MC diagnostics: chains = %d, stored profiles = %d, attempted profile moves = %d, acceptance = %.6g, mean energy = %.6g +/- %.3g.",
            result.chain_count, result.sample_count, result.attempted_moves, result.acceptance_rate,
            result.energy_mean, result.energy_stderr))
        println(io, @sprintf("Profile fit: `xi_bulk = %.6g`, profile-direct MC `xi_eff = %.6g`, fit RMSE = %.6g, fit R2 = %.6g, wall RMS residual = %.6g, fit-quality pass = %.0f.",
            result.xi_bulk, result.xi_eff, result.xi_fit_rmse, result.xi_fit_r2,
            result.xi_fit_wall_rms, result.xi_fit_quality_pass))
        println(io)
        println(io, "Scope: this is the controlled profile-measure baseline for VK1 slit MC. Lateral variance is intentionally zero; lateral fluctuation modes must be added only after this baseline is stationary.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_profile_blocks.csv` and `slit_3d_mc_xi_blocks.csv`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function run_slit_3d_profile_direct_vk1_mc(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    reference_width_xi::Real=0.0,
    steps::Integer=80_000,
    burnin_steps::Integer=20_000,
    sample_stride::Integer=20,
    proposal_width::Real=0.01,
    temperature::Real=1.0,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    phi_min::Real=1.0e-10,
    seed::Integer=1701,
    initial_profile=:eq22,
)
    mkpath(outdir)
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs)
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) :
                                  max(1.5 * _slit_bulk_xi(B, C), eps(Float64))
    profile_mode = Symbol(initial_profile)
    saddle_phi = if profile_mode == :eq22
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz)
    elseif profile_mode == :reference_width
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=resolved_reference_width_xi)
    elseif profile_mode == :low_density
        slit_low_density_profile(grid.slit_grid)
    elseif profile_mode == :vk1_smooth
        minimize_slit_vk1_smooth_basis_saddle(B, C, A; Nz=grid.Nz, L=grid.Lz,
            alpha=alpha, local_potential_coeffs=local_coeffs,
            basis_count=min(12, grid.Nz - 1), max_iterations=3000).phi
    else
        throw(ArgumentError("initial_profile must be :eq22, :reference_width, :low_density, or :vk1_smooth"))
    end
    chain_count = max(1, Int(chains))
    traces = [
        _run_slit_3d_profile_direct_trace(
            grid,
            params,
            saddle_phi;
            steps=steps,
            burnin_steps=burnin_steps,
            sample_stride=sample_stride,
            proposal_width=proposal_width,
            temperature=temperature,
            phi_min=phi_min,
            seed=Int(seed) + 100_000 * (chain_idx - 1),
        ) for chain_idx in 1:chain_count
    ]

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "profile_direct_mirror_symmetrized" : "profile_direct_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    roughness_mean = mean(xy_profile_roughness_trace)

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(B, C)
    fit_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=saddle_phi[k], stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="profile_direct_metropolis_raw"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    diagnostics_rows = [(
        sampler="profile_direct_metropolis",
        A=params.A,
        B=params.B,
        C=params.C,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=traces[1].steps,
        burnin_steps=traces[1].burnin_steps,
        sample_stride=traces[1].sample_stride,
        proposals_per_sweep=grid.Nz,
        total_sweeps=Float64(traces[1].steps) / grid.Nz,
        production_sweeps=Float64(traces[1].steps - traces[1].burnin_steps) / grid.Nz,
        burnin_sweeps=Float64(traces[1].burnin_steps) / grid.Nz,
        sample_stride_sweeps=Float64(traces[1].sample_stride) / grid.Nz,
        proposal_width=Float64(proposal_width),
        temperature=Float64(temperature),
        phi_min=Float64(phi_min),
        chain_count=chain_count,
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"), diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)

    proposals_per_sweep = grid.Nz
    total_sweeps = Float64(traces[1].steps) / proposals_per_sweep
    production_sweeps = Float64(traces[1].steps - traces[1].burnin_steps) / proposals_per_sweep
    burnin_sweeps = Float64(traces[1].burnin_steps) / proposals_per_sweep
    stride_sweeps = Float64(traces[1].sample_stride) / proposals_per_sweep
    result = Slit3DMCResult(
        grid,
        params,
        saddle_phi,
        mean_phi,
        stderr_phi,
        raw_mean_phi,
        raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1),
        attempted_moves,
        accepted_moves,
        sample_count,
        chain_count,
        traces[1].steps,
        traces[1].burnin_steps,
        traces[1].sample_stride,
        proposals_per_sweep,
        total_sweeps,
        production_sweeps,
        burnin_sweeps,
        stride_sweeps,
        symmetrize_profile,
        profile_estimator,
        Float64(proposal_width),
        0.0,
        0.0,
        NaN,
        0,
        0,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        density_variance_summary.mean,
        density_variance_summary.stderr,
        lateral_variance_summary.mean,
        lateral_variance_summary.stderr,
        roughness_mean,
        xi_eff,
        xi_fit_error,
        fit_diagnostics.rmse,
        fit_diagnostics.r2,
        fit_diagnostics.max_abs_error,
        fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass,
        profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max,
        profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation,
        xi_bulk,
        "profile_direct_metropolis",
        profile_csv,
        diagnostics_csv,
        profile_svg,
        "",
        "",
    )
    markdown_path = _write_slit_3d_profile_direct_text(outdir, result)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_hevk1_profile_direct_metropolis",
            "sampler" => "profile_direct_metropolis",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
            "initial_profile" => String(profile_mode),
        ),
        "sampling" => Dict{String,Any}(
            "state_space" => "positive_normalized_plane_profile",
            "steps" => traces[1].steps,
            "burnin_steps" => traces[1].burnin_steps,
            "sample_stride" => traces[1].sample_stride,
            "proposals_per_sweep" => proposals_per_sweep,
            "total_sweeps" => total_sweeps,
            "production_sweeps" => production_sweeps,
            "burnin_sweeps" => burnin_sweeps,
            "sample_stride_sweeps" => stride_sweeps,
            "proposal_width" => Float64(proposal_width),
            "temperature" => Float64(temperature),
            "phi_min" => Float64(phi_min),
            "chain_count" => chain_count,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "accepted_moves" => accepted_moves,
            "attempted_moves" => attempted_moves,
            "energy_mean" => energy_summary.mean,
            "energy_stderr" => energy_summary.stderr,
            "density_variance_mean" => density_variance_summary.mean,
            "lateral_variance_mean" => lateral_variance_summary.mean,
            "xy_profile_roughness_mean" => roughness_mean,
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_error" => xi_fit_error,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
            "xi_fit_mae" => fit_diagnostics.mae,
            "xi_fit_max_abs_error" => fit_diagnostics.max_abs_error,
            "xi_fit_wall_rms" => fit_diagnostics.wall_rms,
            "xi_fit_nrmse_range" => fit_diagnostics.nrmse_range,
            "xi_fit_nrmse_mean" => fit_diagnostics.nrmse_mean,
            "xi_fit_quality_pass" => fit_diagnostics.quality_pass,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
            "profile_chain_rmse_max" => profile_convergence.profile_chain_rmse_max,
            "profile_chain_max_abs_deviation" => profile_convergence.profile_chain_max_abs_deviation,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMCResult(
        grid,
        params,
        saddle_phi,
        mean_phi,
        stderr_phi,
        raw_mean_phi,
        raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1),
        attempted_moves,
        accepted_moves,
        sample_count,
        chain_count,
        traces[1].steps,
        traces[1].burnin_steps,
        traces[1].sample_stride,
        proposals_per_sweep,
        total_sweeps,
        production_sweeps,
        burnin_sweeps,
        stride_sweeps,
        symmetrize_profile,
        profile_estimator,
        Float64(proposal_width),
        0.0,
        0.0,
        NaN,
        0,
        0,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        density_variance_summary.mean,
        density_variance_summary.stderr,
        lateral_variance_summary.mean,
        lateral_variance_summary.stderr,
        roughness_mean,
        xi_eff,
        xi_fit_error,
        fit_diagnostics.rmse,
        fit_diagnostics.r2,
        fit_diagnostics.max_abs_error,
        fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass,
        profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max,
        profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation,
        xi_bulk,
        "profile_direct_metropolis",
        profile_csv,
        diagnostics_csv,
        profile_svg,
        markdown_path,
        metadata_path,
    )
end

function run_slit_3d_profile_mode_vk1_mc(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    z_basis_count::Integer=4,
    steps::Integer=80_000,
    burnin_steps::Integer=20_000,
    sample_stride::Integer=20,
    proposal_width::Real=0.03,
    temperature::Real=1.0,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    seed::Integer=1701,
)
    mkpath(outdir)
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha), model=:vk1)
    count = min(max(1, Int(z_basis_count)), grid.Nz - 1)
    saddle_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz)
    basis = _slit_cosine_basis_matrix(grid.slit_grid, count)
    chain_count = max(1, Int(chains))
    traces = [
        _run_slit_3d_profile_mode_trace(
            grid,
            params,
            saddle_phi,
            basis;
            steps=steps,
            burnin_steps=burnin_steps,
            sample_stride=sample_stride,
            proposal_width=proposal_width,
            temperature=temperature,
            seed=Int(seed) + 100_000 * (chain_idx - 1),
        ) for chain_idx in 1:chain_count
    ]

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "profile_mode_mirror_symmetrized" : "profile_mode_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    roughness_mean = mean(xy_profile_roughness_trace)

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(B, C)
    fit_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=saddle_phi[k], stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="profile_mode_metropolis_raw"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    diagnostics_rows = [(
        sampler="profile_mode_metropolis",
        A=params.A,
        B=params.B,
        C=params.C,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=traces[1].steps,
        burnin_steps=traces[1].burnin_steps,
        sample_stride=traces[1].sample_stride,
        z_basis_count=count,
        proposal_width=Float64(proposal_width),
        temperature=Float64(temperature),
        chain_count=chain_count,
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"), diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)

    proposals_per_sweep = count
    total_sweeps = Float64(traces[1].steps) / proposals_per_sweep
    production_sweeps = Float64(traces[1].steps - traces[1].burnin_steps) / proposals_per_sweep
    burnin_sweeps = Float64(traces[1].burnin_steps) / proposals_per_sweep
    stride_sweeps = Float64(traces[1].sample_stride) / proposals_per_sweep
    result = Slit3DMCResult(
        grid,
        params,
        saddle_phi,
        mean_phi,
        stderr_phi,
        raw_mean_phi,
        raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1),
        attempted_moves,
        accepted_moves,
        sample_count,
        chain_count,
        traces[1].steps,
        traces[1].burnin_steps,
        traces[1].sample_stride,
        proposals_per_sweep,
        total_sweeps,
        production_sweeps,
        burnin_sweeps,
        stride_sweeps,
        symmetrize_profile,
        profile_estimator,
        Float64(proposal_width),
        0.0,
        0.0,
        NaN,
        0,
        0,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        density_variance_summary.mean,
        density_variance_summary.stderr,
        lateral_variance_summary.mean,
        lateral_variance_summary.stderr,
        roughness_mean,
        xi_eff,
        xi_fit_error,
        fit_diagnostics.rmse,
        fit_diagnostics.r2,
        fit_diagnostics.max_abs_error,
        fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass,
        profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max,
        profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation,
        xi_bulk,
        "profile_mode_metropolis",
        profile_csv,
        diagnostics_csv,
        profile_svg,
        "",
        "",
    )
    markdown_path = _write_slit_3d_profile_mode_text(outdir, result, count)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_hevk1_profile_mode_metropolis",
            "sampler" => "profile_mode_metropolis",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
        ),
        "sampling" => Dict{String,Any}(
            "steps" => traces[1].steps,
            "burnin_steps" => traces[1].burnin_steps,
            "sample_stride" => traces[1].sample_stride,
            "z_basis_count" => count,
            "proposal_width" => Float64(proposal_width),
            "temperature" => Float64(temperature),
            "chain_count" => chain_count,
            "sample_count" => sample_count,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "energy_mean" => energy_summary.mean,
            "energy_stderr" => energy_summary.stderr,
            "density_variance_mean" => density_variance_summary.mean,
            "lateral_variance_mean" => lateral_variance_summary.mean,
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
            "xi_fit_quality_pass" => fit_diagnostics.quality_pass,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMCResult(
        result.grid,
        result.params,
        result.saddle_phi,
        result.mean_phi,
        result.stderr_phi,
        result.raw_mean_phi,
        result.raw_stderr_phi,
        result.acceptance_rate,
        result.attempted_moves,
        result.accepted_moves,
        result.sample_count,
        result.chain_count,
        result.steps,
        result.burnin_steps,
        result.sample_stride,
        result.proposals_per_sweep,
        result.total_sweeps,
        result.production_sweeps,
        result.burnin_sweeps,
        result.sample_stride_sweeps,
        result.profile_symmetrized,
        result.profile_estimator,
        result.pair_proposal_amplitude,
        result.plane_proposal_amplitude,
        result.global_field_amplitude,
        result.tuning_acceptance_rate,
        result.tune_rounds,
        result.tune_steps,
        result.seed,
        result.energy_mean,
        result.energy_stderr,
        result.density_variance_mean,
        result.density_variance_stderr,
        result.lateral_variance_mean,
        result.lateral_variance_stderr,
        result.xy_profile_roughness_mean,
        result.xi_eff,
        result.xi_fit_error,
        result.xi_fit_rmse,
        result.xi_fit_r2,
        result.xi_fit_max_abs_error,
        result.xi_fit_wall_rms,
        result.xi_fit_quality_pass,
        result.profile_chain_rhat_max,
        result.profile_split_rhat_max,
        result.profile_chain_rmse_max,
        result.profile_chain_max_abs_deviation,
        result.xi_bulk,
        result.sampler,
        result.profile_csv,
        result.diagnostics_csv,
        result.profile_svg,
        markdown_path,
        metadata_path,
    )
end

function run_slit_3d_spectral_mode_vk1_mc(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    lateral_gradient_coeff::Real=0.0,
    lateral_variance_coeff::Real=0.0,
    lateral_fraction_z_gradient_coeff::Real=0.0,
    lateral_mode_quadratic_coeffs=(),
    spectral_mode_quadratic_coeffs=(),
    profile_mode_quadratic_matrix=(),
    profile_coordinate_jacobian_coeff::Real=0.0,
    profile_xi_potential_coeff::Real=0.0,
    profile_xi_potential_xi_values=(),
    profile_xi_potential_values=(),
    profile_entropy_coeff::Real=0.0,
    z_basis_count::Integer=4,
    lateral_mode_count::Integer=1,
    lateral_z_basis_count::Integer=1,
    steps::Integer=80_000,
    burnin_steps::Integer=20_000,
    sample_stride::Integer=20,
    proposal_width::Real=0.03,
    profile_proposal_width=nothing,
    lateral_proposal_width=nothing,
    temperature::Real=1.0,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    plane_normalized_lateral::Bool=true,
    seed::Integer=2701,
    initial_profile=:eq22,
    reference_width_xi::Real=0.0,
    write_coefficient_diagnostics::Bool=true,
    write_hessian_diagnostics::Bool=true,
    write_branch_diagnostics::Bool=true,
    xi_branch_threshold::Real=0.55,
    hessian_step::Real=1.0e-4,
    replica_temperatures=(),
    replica_swap_interval::Integer=10,
)
    mkpath(outdir)
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    lateral_gradient = _slit_lateral_gradient_coeff(lateral_gradient_coeff)
    lateral_variance = _slit_lateral_variance_coeff(lateral_variance_coeff)
    lateral_fraction_z_gradient =
        _slit_lateral_fraction_z_gradient_coeff(lateral_fraction_z_gradient_coeff)
    profile_coordinate_jacobian =
        _slit_profile_coordinate_jacobian_coeff(profile_coordinate_jacobian_coeff)
    profile_xi_potential =
        _slit_profile_xi_potential_coeff(profile_xi_potential_coeff)
    profile_xi_values, profile_xi_potential_table_values =
        _slit_profile_xi_potential_table(
            profile_xi_potential_xi_values, profile_xi_potential_values;
            allow_empty=profile_xi_potential == 0.0)
    profile_entropy = _slit_profile_entropy_coeff(profile_entropy_coeff)
    base_proposal_width = Float64(proposal_width)
    base_proposal_width > 0.0 || throw(ArgumentError("proposal_width must be positive"))
    resolved_profile_proposal_width =
        profile_proposal_width === nothing ? base_proposal_width : Float64(profile_proposal_width)
    resolved_lateral_proposal_width =
        lateral_proposal_width === nothing ? base_proposal_width : Float64(lateral_proposal_width)
    resolved_profile_proposal_width > 0.0 ||
        throw(ArgumentError("profile_proposal_width must be positive"))
    resolved_lateral_proposal_width > 0.0 ||
        throw(ArgumentError("lateral_proposal_width must be positive"))
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs,
        lateral_gradient_coeff=lateral_gradient,
        lateral_variance_coeff=lateral_variance,
        lateral_fraction_z_gradient_coeff=lateral_fraction_z_gradient,
        profile_entropy_coeff=profile_entropy)
    profile_mode = Symbol(initial_profile)
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) :
                                  max(1.5 * _slit_bulk_xi(B, C), eps(Float64))
    saddle_phi = if profile_mode == :eq22
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz)
    elseif profile_mode == :reference_width
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=resolved_reference_width_xi)
    elseif profile_mode == :low_density
        slit_low_density_profile(grid.slit_grid)
    elseif profile_mode == :vk1_smooth
        minimize_slit_vk1_smooth_basis_saddle(B, C, A; Nz=grid.Nz, L=grid.Lz,
            alpha=alpha, local_potential_coeffs=local_coeffs,
            basis_count=min(12, grid.Nz - 1), max_iterations=3000).phi
    else
        throw(ArgumentError("initial_profile must be :eq22, :reference_width, :low_density, or :vk1_smooth"))
    end
    z_count = max(0, Int(z_basis_count))
    lateral_count = max(0, Int(lateral_mode_count))
    lateral_z_count = max(0, Int(lateral_z_basis_count))
    chain_count = max(1, Int(chains))
    plane_normalized = Bool(plane_normalized_lateral)
    replica_temperature_values = _slit_replica_temperature_values(replica_temperatures, temperature)
    replica_count = length(replica_temperature_values)
    sampler_name = replica_count > 1 ? "spectral_mode_replica_exchange" :
                   "spectral_mode_metropolis"
    lateral_mode_quadratic = Float64[]
    spectral_mode_quadratic = Float64[]
    total_spectral_mode_quadratic = Float64[]
    profile_mode_quadratic = Float64[]
    lateral_total_mode_quadratic = Float64[]
    profile_mode_quadratic_matrix_values = zeros(Float64, 0, 0)
    z_basis = zeros(Float64, grid.Nz, 0)
    lateral_basis = zeros(Float64, grid.Nx * grid.Ny * grid.Nz, 0)
    mode_metadata = _slit_3d_blocked_spectral_mode_metadata(0, ())
    if plane_normalized
        z_basis = z_count == 0 ? zeros(Float64, grid.Nz, 0) :
                  _slit_cosine_basis_matrix(grid.slit_grid, z_count)
        lateral_basis = _slit_3d_lateral_spectral_basis(grid;
            lateral_mode_count=lateral_count, lateral_z_basis_count=lateral_z_count)
        lateral_metadata = _slit_3d_lateral_spectral_mode_metadata(grid;
            lateral_mode_count=lateral_count, lateral_z_basis_count=lateral_z_count)
        length(lateral_metadata) == size(lateral_basis, 2) ||
            throw(DimensionMismatch("lateral spectral metadata count must match lateral basis count"))
        mode_metadata = _slit_3d_blocked_spectral_mode_metadata(size(z_basis, 2), lateral_metadata)
        lateral_mode_quadratic =
            _slit_lateral_mode_quadratic_coeffs(lateral_mode_quadratic_coeffs,
                size(lateral_basis, 2))
        spectral_basis_count = size(z_basis, 2) + size(lateral_basis, 2)
        spectral_mode_quadratic =
            _slit_spectral_mode_quadratic_coeffs(spectral_mode_quadratic_coeffs,
                spectral_basis_count)
        total_spectral_mode_quadratic =
            _slit_blocked_spectral_mode_quadratic_coeffs(
                spectral_mode_quadratic, lateral_mode_quadratic,
                size(z_basis, 2), size(lateral_basis, 2))
        profile_mode_quadratic_matrix_values =
            _slit_profile_mode_quadratic_matrix(
                profile_mode_quadratic_matrix, size(z_basis, 2))
        profile_mode_quadratic = size(z_basis, 2) == 0 ? Float64[] :
                                 collect(@view(total_spectral_mode_quadratic[1:size(z_basis, 2)]))
        lateral_total_mode_quadratic = size(lateral_basis, 2) == 0 ? Float64[] :
                                       collect(@view(total_spectral_mode_quadratic[(size(z_basis, 2) + 1):spectral_basis_count]))
        traces = if replica_count > 1
            [
                _run_slit_3d_blocked_spectral_replica_exchange_trace(
                    grid,
                    params,
                    saddle_phi,
                    z_basis,
                    lateral_basis;
                    steps=steps,
                    burnin_steps=burnin_steps,
                    sample_stride=sample_stride,
                    proposal_width=proposal_width,
                    profile_proposal_width=resolved_profile_proposal_width,
                    lateral_proposal_width=resolved_lateral_proposal_width,
                    target_temperature=temperature,
                    replica_temperatures=replica_temperature_values,
                    replica_swap_interval=replica_swap_interval,
                    seed=Int(seed) + 100_000 * (chain_idx - 1),
                    lateral_mode_quadratic_coeffs=lateral_mode_quadratic,
                    spectral_mode_quadratic_coeffs=spectral_mode_quadratic,
                    profile_mode_quadratic_matrix=profile_mode_quadratic_matrix_values,
                    profile_coordinate_jacobian_coeff=profile_coordinate_jacobian,
                    profile_xi_potential_coeff=profile_xi_potential,
                    profile_xi_potential_xi_values=profile_xi_values,
                    profile_xi_potential_values=profile_xi_potential_table_values,
                ) for chain_idx in 1:chain_count
            ]
        else
            [
                _run_slit_3d_blocked_spectral_mode_trace(
                    grid,
                    params,
                    saddle_phi,
                    z_basis,
                    lateral_basis;
                    steps=steps,
                    burnin_steps=burnin_steps,
                    sample_stride=sample_stride,
                    proposal_width=proposal_width,
                    profile_proposal_width=resolved_profile_proposal_width,
                    lateral_proposal_width=resolved_lateral_proposal_width,
                    temperature=temperature,
                    seed=Int(seed) + 100_000 * (chain_idx - 1),
                    lateral_mode_quadratic_coeffs=lateral_mode_quadratic,
                    spectral_mode_quadratic_coeffs=spectral_mode_quadratic,
                    profile_mode_quadratic_matrix=profile_mode_quadratic_matrix_values,
                    profile_coordinate_jacobian_coeff=profile_coordinate_jacobian,
                    profile_xi_potential_coeff=profile_xi_potential,
                    profile_xi_potential_xi_values=profile_xi_values,
                    profile_xi_potential_values=profile_xi_potential_table_values,
                ) for chain_idx in 1:chain_count
            ]
        end
    else
        profile_xi_potential == 0.0 ||
            throw(ArgumentError("profile_xi_potential_coeff requires plane_normalized_lateral=true"))
        replica_count == 1 ||
            throw(ArgumentError("replica_temperatures require plane_normalized_lateral=true"))
        _slit_profile_mode_quadratic_matrix(profile_mode_quadratic_matrix, 0)
        _slit_lateral_mode_quadratic_coeffs(lateral_mode_quadratic_coeffs, 0)
        _slit_spectral_mode_quadratic_coeffs(spectral_mode_quadratic_coeffs, 0)
        basis = _slit_3d_spectral_basis(grid; z_basis_count=z_count,
            lateral_mode_count=lateral_count, lateral_z_basis_count=lateral_z_count)
        spectral_basis_count = size(basis, 2)
        traces = [
            _run_slit_3d_spectral_mode_trace(
                grid,
                params,
                saddle_phi,
                basis;
                steps=steps,
                burnin_steps=burnin_steps,
                sample_stride=sample_stride,
                proposal_width=proposal_width,
                temperature=temperature,
                seed=Int(seed) + 100_000 * (chain_idx - 1),
            ) for chain_idx in 1:chain_count
        ]
    end

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "spectral_mode_mirror_symmetrized" : "spectral_mode_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)
    coefficient_trace_csv = plane_normalized && Bool(write_coefficient_diagnostics) ?
                            _write_slit_3d_spectral_coefficient_trace(
                                outdir, traces, mode_metadata) : ""
    hessian_csv = plane_normalized && Bool(write_hessian_diagnostics) ?
                  _write_slit_3d_spectral_hessian(
                      outdir, grid, params, saddle_phi, z_basis, lateral_basis,
                      total_spectral_mode_quadratic, mode_metadata;
                      finite_difference_step=hessian_step,
                      profile_mode_quadratic_matrix=profile_mode_quadratic_matrix_values,
                      profile_coordinate_jacobian_coeff=profile_coordinate_jacobian,
                      profile_xi_potential_coeff=profile_xi_potential,
                      profile_xi_potential_xi_values=profile_xi_values,
                      profile_xi_potential_values=profile_xi_potential_table_values) : ""
    branch_blocks_csv, branch_summary_csv =
        plane_normalized && Bool(write_branch_diagnostics) ?
        _write_slit_3d_spectral_branch_diagnostics(
            outdir, traces, mode_metadata, xi_blocks_csv;
            xi_branch_threshold=xi_branch_threshold) : ("", "")

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    roughness_mean = mean(xy_profile_roughness_trace)
    trace_value(trace, name::Symbol, default) =
        hasproperty(trace, name) ? getproperty(trace, name) : default
    replica_swap_attempts =
        sum(trace_value(trace, :replica_swap_attempts, 0) for trace in traces)
    replica_swap_accepts =
        sum(trace_value(trace, :replica_swap_accepts, 0) for trace in traces)
    replica_swap_acceptance_rate =
        replica_swap_accepts / max(replica_swap_attempts, 1)
    replica_round_trips =
        sum(trace_value(trace, :replica_round_trips, 0) for trace in traces)
    replica_min_round_trips = minimum(
        trace_value(trace, :replica_min_round_trips, 0) for trace in traces)
    replica_max_round_trips = maximum(
        trace_value(trace, :replica_max_round_trips, 0) for trace in traces)
    replica_temperatures_text =
        join((@sprintf("%.6g", value) for value in replica_temperature_values), ";")
    profile_mode_quadratic_matrix_trace =
        size(profile_mode_quadratic_matrix_values, 1) == 0 ? 0.0 :
        sum(profile_mode_quadratic_matrix_values[i, i]
            for i in 1:size(profile_mode_quadratic_matrix_values, 1))
    profile_mode_quadratic_matrix_max_abs =
        isempty(profile_mode_quadratic_matrix_values) ? 0.0 :
        maximum(abs.(profile_mode_quadratic_matrix_values))
    profile_mode_quadratic_matrix_values_text =
        join((@sprintf("%.12g", value) for value in vec(profile_mode_quadratic_matrix_values)), ";")

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(B, C)
    fit_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=saddle_phi[k], stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="spectral_mode_metropolis_raw"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    diagnostics_rows = [(
        sampler=sampler_name,
        A=params.A,
        B=params.B,
        C=params.C,
        local_potential_a1=params.local_potential_coeffs[1],
        local_potential_a2=params.local_potential_coeffs[2],
        local_potential_a3=params.local_potential_coeffs[3],
        lateral_gradient_coeff=params.lateral_gradient_coeff,
        lateral_variance_coeff=params.lateral_variance_coeff,
        lateral_fraction_z_gradient_coeff=params.lateral_fraction_z_gradient_coeff,
        lateral_mode_quadratic_coeff_count=length(lateral_mode_quadratic),
        lateral_mode_quadratic_coeff_sum=sum(lateral_mode_quadratic),
        lateral_mode_quadratic_coeff_max=
            isempty(lateral_mode_quadratic) ? 0.0 : maximum(lateral_mode_quadratic),
        spectral_mode_quadratic_coeff_count=length(spectral_mode_quadratic),
        spectral_mode_quadratic_coeff_sum=sum(spectral_mode_quadratic),
        spectral_mode_quadratic_coeff_max=
            isempty(spectral_mode_quadratic) ? 0.0 : maximum(spectral_mode_quadratic),
        total_spectral_mode_quadratic_coeff_sum=sum(total_spectral_mode_quadratic),
        total_spectral_mode_quadratic_coeff_max=
            isempty(total_spectral_mode_quadratic) ? 0.0 : maximum(total_spectral_mode_quadratic),
        profile_mode_quadratic_coeff_sum=sum(profile_mode_quadratic),
        profile_mode_quadratic_coeff_max=
            isempty(profile_mode_quadratic) ? 0.0 : maximum(profile_mode_quadratic),
        profile_mode_quadratic_matrix_coeff_count=length(profile_mode_quadratic_matrix_values),
        profile_mode_quadratic_matrix_trace=profile_mode_quadratic_matrix_trace,
        profile_mode_quadratic_matrix_max_abs=profile_mode_quadratic_matrix_max_abs,
        lateral_total_mode_quadratic_coeff_sum=sum(lateral_total_mode_quadratic),
        lateral_total_mode_quadratic_coeff_max=
            isempty(lateral_total_mode_quadratic) ? 0.0 : maximum(lateral_total_mode_quadratic),
        profile_coordinate_jacobian_coeff=profile_coordinate_jacobian,
        profile_xi_potential_coeff=profile_xi_potential,
        profile_xi_potential_point_count=length(profile_xi_values),
        profile_entropy_coeff=params.profile_entropy_coeff,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=traces[1].steps,
        burnin_steps=traces[1].burnin_steps,
        sample_stride=traces[1].sample_stride,
        initial_profile=String(profile_mode),
        z_basis_count=z_count,
        lateral_mode_count=lateral_count,
        lateral_z_basis_count=lateral_z_count,
        spectral_basis_count=spectral_basis_count,
        plane_normalized_lateral=plane_normalized,
        proposal_width=Float64(proposal_width),
        profile_proposal_width=resolved_profile_proposal_width,
        lateral_proposal_width=resolved_lateral_proposal_width,
        temperature=Float64(temperature),
        replica_count=replica_count,
        replica_temperatures=replica_temperatures_text,
        replica_swap_interval=max(1, Int(replica_swap_interval)),
        replica_swap_attempts=replica_swap_attempts,
        replica_swap_accepts=replica_swap_accepts,
        replica_swap_acceptance_rate=replica_swap_acceptance_rate,
        replica_round_trips=replica_round_trips,
        replica_min_round_trips=replica_min_round_trips,
        replica_max_round_trips=replica_max_round_trips,
        chain_count=chain_count,
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        coefficient_trace_csv=coefficient_trace_csv,
        hessian_csv=hessian_csv,
        branch_blocks_csv=branch_blocks_csv,
        branch_summary_csv=branch_summary_csv,
        xi_branch_threshold=Float64(xi_branch_threshold),
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"), diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)

    proposals_per_sweep = spectral_basis_count
    total_sweeps = Float64(traces[1].steps) / proposals_per_sweep
    production_sweeps = Float64(traces[1].steps - traces[1].burnin_steps) / proposals_per_sweep
    burnin_sweeps = Float64(traces[1].burnin_steps) / proposals_per_sweep
    stride_sweeps = Float64(traces[1].sample_stride) / proposals_per_sweep
    result = Slit3DMCResult(
        grid, params, saddle_phi, mean_phi, stderr_phi, raw_mean_phi, raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1), attempted_moves, accepted_moves,
        sample_count, chain_count, traces[1].steps, traces[1].burnin_steps,
        traces[1].sample_stride, proposals_per_sweep, total_sweeps, production_sweeps,
        burnin_sweeps, stride_sweeps, symmetrize_profile, profile_estimator,
        Float64(proposal_width), 0.0, 0.0, NaN, 0, 0, Int(seed),
        energy_summary.mean, energy_summary.stderr,
        density_variance_summary.mean, density_variance_summary.stderr,
        lateral_variance_summary.mean, lateral_variance_summary.stderr, roughness_mean,
        xi_eff, xi_fit_error, fit_diagnostics.rmse, fit_diagnostics.r2,
        fit_diagnostics.max_abs_error, fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass, profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max, profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation, xi_bulk,
        sampler_name, profile_csv, diagnostics_csv, profile_svg, "", "")
    markdown_path = _write_slit_3d_spectral_mode_text(outdir, result, z_count,
        lateral_count, lateral_z_count, spectral_basis_count, plane_normalized)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_hevk1_spectral_mode_metropolis",
            "sampler" => sampler_name,
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
            "local_potential_a1" => params.local_potential_coeffs[1],
            "local_potential_a2" => params.local_potential_coeffs[2],
            "local_potential_a3" => params.local_potential_coeffs[3],
            "lateral_gradient_coeff" => params.lateral_gradient_coeff,
            "lateral_variance_coeff" => params.lateral_variance_coeff,
            "lateral_fraction_z_gradient_coeff" => params.lateral_fraction_z_gradient_coeff,
            "lateral_mode_quadratic_coeff_count" => length(lateral_mode_quadratic),
            "lateral_mode_quadratic_coeff_sum" => sum(lateral_mode_quadratic),
            "lateral_mode_quadratic_coeff_max" =>
                isempty(lateral_mode_quadratic) ? 0.0 : maximum(lateral_mode_quadratic),
            "spectral_mode_quadratic_coeff_count" => length(spectral_mode_quadratic),
            "spectral_mode_quadratic_coeff_sum" => sum(spectral_mode_quadratic),
            "spectral_mode_quadratic_coeff_max" =>
                isempty(spectral_mode_quadratic) ? 0.0 : maximum(spectral_mode_quadratic),
            "total_spectral_mode_quadratic_coeff_sum" => sum(total_spectral_mode_quadratic),
            "total_spectral_mode_quadratic_coeff_max" =>
                isempty(total_spectral_mode_quadratic) ? 0.0 :
                maximum(total_spectral_mode_quadratic),
            "profile_mode_quadratic_coeff_sum" => sum(profile_mode_quadratic),
            "profile_mode_quadratic_coeff_max" =>
                isempty(profile_mode_quadratic) ? 0.0 : maximum(profile_mode_quadratic),
            "profile_mode_quadratic_matrix_coeff_count" =>
                length(profile_mode_quadratic_matrix_values),
            "profile_mode_quadratic_matrix_trace" =>
                profile_mode_quadratic_matrix_trace,
            "profile_mode_quadratic_matrix_max_abs" =>
                profile_mode_quadratic_matrix_max_abs,
            "profile_mode_quadratic_matrix_values" =>
                profile_mode_quadratic_matrix_values_text,
            "lateral_total_mode_quadratic_coeff_sum" => sum(lateral_total_mode_quadratic),
            "lateral_total_mode_quadratic_coeff_max" =>
                isempty(lateral_total_mode_quadratic) ? 0.0 :
                maximum(lateral_total_mode_quadratic),
            "profile_coordinate_jacobian_coeff" => profile_coordinate_jacobian,
            "profile_xi_potential_coeff" => profile_xi_potential,
            "profile_xi_potential_point_count" => length(profile_xi_values),
            "profile_xi_potential_xi_values" =>
                join((@sprintf("%.12g", value) for value in profile_xi_values), ";"),
            "profile_xi_potential_values" =>
                join((@sprintf("%.12g", value) for value in profile_xi_potential_table_values), ";"),
            "profile_entropy_coeff" => params.profile_entropy_coeff,
            "initial_profile" => String(profile_mode),
        ),
        "sampling" => Dict{String,Any}(
            "steps" => traces[1].steps,
            "burnin_steps" => traces[1].burnin_steps,
            "sample_stride" => traces[1].sample_stride,
            "z_basis_count" => z_count,
            "lateral_mode_count" => lateral_count,
            "lateral_z_basis_count" => lateral_z_count,
            "spectral_basis_count" => spectral_basis_count,
            "plane_normalized_lateral" => plane_normalized,
            "proposal_width" => Float64(proposal_width),
            "profile_proposal_width" => resolved_profile_proposal_width,
            "lateral_proposal_width" => resolved_lateral_proposal_width,
            "temperature" => Float64(temperature),
            "replica_count" => replica_count,
            "replica_temperatures" => replica_temperatures_text,
            "replica_swap_interval" => max(1, Int(replica_swap_interval)),
            "chain_count" => chain_count,
            "sample_count" => sample_count,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
            "coefficient_trace_csv" => coefficient_trace_csv,
            "hessian_csv" => hessian_csv,
            "branch_blocks_csv" => branch_blocks_csv,
            "branch_summary_csv" => branch_summary_csv,
            "xi_branch_threshold" => Float64(xi_branch_threshold),
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "energy_mean" => energy_summary.mean,
            "energy_stderr" => energy_summary.stderr,
            "density_variance_mean" => density_variance_summary.mean,
            "lateral_variance_mean" => lateral_variance_summary.mean,
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
            "xi_fit_quality_pass" => fit_diagnostics.quality_pass,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
            "replica_swap_attempts" => replica_swap_attempts,
            "replica_swap_accepts" => replica_swap_accepts,
            "replica_swap_acceptance_rate" => replica_swap_acceptance_rate,
            "replica_round_trips" => replica_round_trips,
            "replica_min_round_trips" => replica_min_round_trips,
            "replica_max_round_trips" => replica_max_round_trips,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
            "coefficient_trace_csv" => coefficient_trace_csv,
            "hessian_csv" => hessian_csv,
            "branch_blocks_csv" => branch_blocks_csv,
            "branch_summary_csv" => branch_summary_csv,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMCResult(
        result.grid, result.params, result.saddle_phi, result.mean_phi, result.stderr_phi,
        result.raw_mean_phi, result.raw_stderr_phi, result.acceptance_rate,
        result.attempted_moves, result.accepted_moves, result.sample_count,
        result.chain_count, result.steps, result.burnin_steps, result.sample_stride,
        result.proposals_per_sweep, result.total_sweeps, result.production_sweeps,
        result.burnin_sweeps, result.sample_stride_sweeps, result.profile_symmetrized,
        result.profile_estimator, result.pair_proposal_amplitude,
        result.plane_proposal_amplitude, result.global_field_amplitude,
        result.tuning_acceptance_rate, result.tune_rounds, result.tune_steps,
        result.seed, result.energy_mean, result.energy_stderr,
        result.density_variance_mean, result.density_variance_stderr,
        result.lateral_variance_mean, result.lateral_variance_stderr,
        result.xy_profile_roughness_mean, result.xi_eff, result.xi_fit_error,
        result.xi_fit_rmse, result.xi_fit_r2, result.xi_fit_max_abs_error,
        result.xi_fit_wall_rms, result.xi_fit_quality_pass,
        result.profile_chain_rhat_max, result.profile_split_rhat_max,
        result.profile_chain_rmse_max, result.profile_chain_max_abs_deviation,
        result.xi_bulk, result.sampler, result.profile_csv, result.diagnostics_csv,
        result.profile_svg, markdown_path, metadata_path)
end

function _profile_mode_scan_label(temperature::Real)
    label = replace(@sprintf("%.6g", Float64(temperature)), "-" => "m", "." => "p", "+" => "")
    return "temperature_" * label
end

function _xml_text(text)
    return replace(String(text), "&" => "&amp;", "<" => "&lt;", ">" => "&gt;",
        "\"" => "&quot;", "'" => "&apos;")
end

function _ak_target_label(target_source::AbstractString; target_label=nothing)
    target_label !== nothing && return String(target_label)
    source = lowercase(String(target_source))
    if occursin("fig. 4", source) || occursin("fig 4", source) || occursin("fig4", source)
        return "AK Fig. 4"
    elseif occursin("fig. 3", source) || occursin("fig 3", source) || occursin("fig3", source)
        return "AK Fig. 3"
    end
    return "AK target"
end

function _ak_target_slug(target_label::AbstractString)
    label = lowercase(String(target_label))
    if occursin("fig. 4", label) || occursin("fig 4", label) || occursin("fig4", label)
        return "ak_fig4"
    elseif occursin("fig. 3", label) || occursin("fig 3", label) || occursin("fig3", label)
        return "ak_fig3"
    end
    return "ak_target"
end

function _write_slit_3d_profile_mode_scan_svg(summary_csv::AbstractString, outdir::AbstractString;
    target_label="AK Fig. 3")
    header, rows = _read_csv_strings(summary_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "profile_mode_temperature_scan.svg")
    isempty(rows) && return svg_path
    label = _xml_text(target_label)
    idx(name) = findfirst(==(name), header)
    temp_idx = idx("temperature")
    xi_idx = idx("xi_eff")
    target_idx = idx("target_xi_eff")
    rank_idx = idx("selection_rank")
    parsed = [
        (
            temperature=parse(Float64, row[temp_idx]),
            xi_eff=parse(Float64, row[xi_idx]),
            target=parse(Float64, row[target_idx]),
            rank=parse(Int, row[rank_idx]),
        ) for row in rows
    ]
    target = parsed[1].target
    xmin, xmax = _expand_plot_range(minimum(row.temperature for row in parsed),
        maximum(row.temperature for row in parsed))
    ymin, ymax = _expand_plot_range(minimum(vcat([row.xi_eff for row in parsed], [target])),
        maximum(vcat([row.xi_eff for row in parsed], [target])))
    ymin = min(0.0, ymin)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=9)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    sorted = sort(parsed; by=row -> row.temperature)
    points = [(x_plot(row.temperature), y_plot(row.xi_eff)) for row in sorted]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>3D VK1 profile-mode $(label) xi scan</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>3D VK1 profile-mode $(label) xi scan</text>")
        println(io, @sprintf("<text x='35' y='52' font-size='12' fill='#555'>Target effective xi = %.6g; points are independent 3D profile-mode MC runs</text>", target))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>profile-mode fluctuation scale</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>effective xi</text>")
        println(io, @sprintf("<line x1='70' y1='%.3f' x2='600' y2='%.3f' stroke='#555' stroke-width='1.8' stroke-dasharray='6 4'/>",
            y_plot(target), y_plot(target)))
        println(io, "<polyline fill='none' stroke='#1f77b4' stroke-width='2.4' points='$(_svg_polyline(points))'/>")
        for row in sorted
            fill = row.rank == 1 ? "#d62728" : "white"
            stroke = row.rank == 1 ? "#d62728" : "#1f77b4"
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4.0' fill='%s' stroke='%s' stroke-width='1.5'/>",
                x_plot(row.temperature), y_plot(row.xi_eff), fill, stroke))
        end
        println(io, "<line x1='410' y1='76' x2='446' y2='76' stroke='#555' stroke-width='1.8' stroke-dasharray='6 4'/>")
        println(io, "<text x='454' y='80' font-size='12'>$(label) target xi</text>")
        println(io, "<line x1='410' y1='96' x2='446' y2='96' stroke='#1f77b4' stroke-width='2.4'/>")
        println(io, "<text x='454' y='100' font-size='12'>3D VK1 MC xi_eff</text>")
        println(io, "<circle cx='428' cy='116' r='4.0' fill='#d62728' stroke='#d62728' stroke-width='1.5'/>")
        println(io, "<text x='454' y='120' font-size='12'>selected run</text>")
        println(io, "</svg>")
    end
    return svg_path
end

function _write_slit_3d_profile_mode_scan_text(
    outdir::AbstractString,
    rows,
    best_row,
    target_source::AbstractString;
    target_label="AK Fig. 3",
)
    path = joinpath(outdir, _ak_target_slug(target_label) * "_3d_profile_mode_scan.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 profile-mode $(target_label) scan")
        println(io)
        println(io, "This artifact is a calibration scan for the $(target_label) with-fluctuation slit profile. The comparison observable is the effective correlation length obtained by fitting Eq. 22 to the sampled density profile, matching the procedure described in the reference paper.")
        println(io)
        println(io, "Target source: $(target_source).")
        println(io)
        println(io, @sprintf("Best scanned run: fluctuation scale = %.6g, `xi_eff = %.6g`, target `xi_eff = %.6g`, absolute error = %.6g.",
            best_row.temperature, best_row.xi_eff, best_row.target_xi_eff,
            best_row.abs_xi_error))
        println(io, @sprintf("Best-run diagnostics: fit R2 = %.6g, target-profile RMSE = %.6g, target-profile R2 = %.6g, fit-quality pass = %.0f, profile R-hat = %.6g, split R-hat = %.6g, acceptance = %.6g.",
            best_row.xi_fit_r2, best_row.target_profile_rmse,
            best_row.target_profile_r2, best_row.xi_fit_quality_pass,
            best_row.profile_chain_rhat_max, best_row.profile_split_rhat_max,
            best_row.acceptance_rate))
        println(io)
        println(io, "Scope and limitation: this is a 3D profile-mode real-density HE-VK1 Metropolis calibration artifact. The sampled profile is lifted to the Alexander-Katz 3D grid, but the sampled state space is a smooth normalized slit-profile basis, not the unrestricted all-cell density measure and not the original complex-Langevin auxiliary-field simulation.")
        println(io)
        println(io, "The scan is useful for deciding whether the VK1 real Hamiltonian can reproduce the CL effective density profile after introducing a controlled inhomogeneous fluctuation scale. It is not, by itself, a derivation of the missing fluctuation correction.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `profile_mode_temperature_scan.csv`")
        println(io, "- `profile_mode_temperature_scan.svg`")
        println(io, "- one subdirectory per scanned fluctuation scale, each containing the profile CSV/SVG and diagnostics")
    end
    return path
end

function run_slit_3d_profile_mode_ak_scan(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    target_xi_eff::Real=0.3270559793,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL points digitized from the local PDF rendering",
    temperatures=[1.0, 1.5, 1.75, 2.0],
    xi_tolerance::Real=0.05,
    rhat_threshold::Real=1.2,
    z_basis_count::Integer=4,
    steps::Integer=80_000,
    burnin_steps::Integer=20_000,
    sample_stride::Integer=20,
    proposal_width::Real=0.03,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    seed::Integer=1701,
    target_label=nothing,
)
    mkpath(outdir)
    resolved_target_label = _ak_target_label(target_source; target_label=target_label)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    temp_values = Float64.(collect(temperatures))
    isempty(temp_values) && throw(ArgumentError("temperatures must contain at least one value"))
    all(temp -> temp > 0.0, temp_values) ||
        throw(ArgumentError("all profile-mode fluctuation scales must be positive"))
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    raw_rows = NamedTuple[]
    results = Slit3DMCResult[]
    for (idx, temp) in enumerate(temp_values)
        run_outdir = joinpath(outdir, _profile_mode_scan_label(temp))
        result = run_slit_3d_profile_mode_vk1_mc(run_outdir;
            Nx=Nx, Ny=Ny, Nz=Nz, Lxy=Lxy, Lz=Lz, B=B, C=C, A=A, alpha=alpha,
            z_basis_count=z_basis_count, steps=steps, burnin_steps=burnin_steps,
            sample_stride=sample_stride, proposal_width=proposal_width,
            temperature=temp, chains=chains, symmetrize_profile=symmetrize_profile,
            seed=Int(seed) + 10_000 * (idx - 1))
        push!(results, result)
        abs_xi_error = abs(result.xi_eff - target)
        target_phi = slit_reference_profile(result.grid.z; B=B, C=C, L=result.grid.Lz, xi=target)
        target_profile = _slit_profile_fit_diagnostics(result.mean_phi, target_phi)
        rhat_ok = isfinite(result.profile_chain_rhat_max) ? result.profile_chain_rhat_max <= rhat_gate : result.chain_count == 1
        split_rhat_ok = isfinite(result.profile_split_rhat_max) ? result.profile_split_rhat_max <= rhat_gate : result.chain_count == 1
        calibration_pass = (abs_xi_error <= tol && result.xi_fit_quality_pass == 1.0 && rhat_ok && split_rhat_ok) ? 1.0 : 0.0
        push!(raw_rows, (
            temperature=temp,
            target_xi_eff=target,
            target_source=String(target_source),
            xi_eff=result.xi_eff,
            abs_xi_error=abs_xi_error,
            xi_tolerance=tol,
            calibration_pass=calibration_pass,
            xi_bulk=result.xi_bulk,
            xi_fit_rmse=result.xi_fit_rmse,
            xi_fit_r2=result.xi_fit_r2,
            xi_fit_quality_pass=result.xi_fit_quality_pass,
            target_profile_rmse=target_profile.rmse,
            target_profile_r2=target_profile.r2,
            target_profile_max_abs_error=target_profile.max_abs_error,
            target_profile_wall_rms=target_profile.wall_rms,
            target_profile_nrmse_range=target_profile.nrmse_range,
            profile_chain_rhat_max=result.profile_chain_rhat_max,
            profile_split_rhat_max=result.profile_split_rhat_max,
            acceptance_rate=result.acceptance_rate,
            sample_count=Float64(result.sample_count),
            steps=Float64(result.steps),
            burnin_steps=Float64(result.burnin_steps),
            sample_stride=Float64(result.sample_stride),
            chain_count=Float64(result.chain_count),
            z_basis_count=Float64(z_basis_count),
            proposal_width=Float64(proposal_width),
            energy_mean=result.energy_mean,
            energy_stderr=result.energy_stderr,
            density_variance_mean=result.density_variance_mean,
            lateral_variance_mean=result.lateral_variance_mean,
            run_outdir=run_outdir,
            profile_csv=result.profile_csv,
            diagnostics_csv=result.diagnostics_csv,
            profile_svg=result.profile_svg,
        ))
    end
    order = sortperm(eachindex(raw_rows); by=i -> (
        raw_rows[i].abs_xi_error,
        isfinite(raw_rows[i].profile_split_rhat_max) ? raw_rows[i].profile_split_rhat_max : Inf,
        raw_rows[i].temperature,
    ))
    rank_by_idx = fill(0, length(raw_rows))
    for (rank, idx) in enumerate(order)
        rank_by_idx[idx] = rank
    end
    scan_rows = [merge(raw_rows[i], (selection_rank=rank_by_idx[i],)) for i in eachindex(raw_rows)]
    summary_csv = _write_dataframe(joinpath(outdir, "profile_mode_temperature_scan.csv"), scan_rows)
    scan_svg = _write_slit_3d_profile_mode_scan_svg(summary_csv, outdir;
        target_label=resolved_target_label)
    best_idx = order[1]
    best_row = scan_rows[best_idx]
    best_result = results[best_idx]
    markdown_path = _write_slit_3d_profile_mode_scan_text(outdir, scan_rows, best_row,
        target_source; target_label=resolved_target_label)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_profile_mode_ak_scan",
            "sampler" => "profile_mode_metropolis",
            "seed" => Int(seed),
        ),
        "target" => Dict{String,Any}(
            "observable" => resolved_target_label * " effective xi",
            "target_xi_eff" => target,
            "target_source" => String(target_source),
            "target_label" => resolved_target_label,
            "xi_tolerance" => tol,
        ),
        "grid" => Dict{String,Any}(
            "Nx" => Int(Nx),
            "Ny" => Int(Ny),
            "Nz" => Int(Nz),
            "Lxy" => Float64(Lxy),
            "Lz" => Float64(Lz),
        ),
        "parameters" => Dict{String,Any}(
            "A" => Float64(A),
            "B" => Float64(B),
            "C" => Float64(C),
            "alpha" => Float64(alpha),
            "model" => "HE-VK1",
        ),
        "scan" => Dict{String,Any}(
            "temperatures" => temp_values,
            "z_basis_count" => Int(z_basis_count),
            "steps" => Int(steps),
            "burnin_steps" => Int(burnin_steps),
            "sample_stride" => Int(sample_stride),
            "proposal_width" => Float64(proposal_width),
            "chains" => Int(chains),
            "rhat_threshold" => rhat_gate,
        ),
        "best" => Dict{String,Any}(
            "temperature" => best_row.temperature,
            "xi_eff" => best_row.xi_eff,
            "abs_xi_error" => best_row.abs_xi_error,
            "target_profile_rmse" => best_row.target_profile_rmse,
            "target_profile_r2" => best_row.target_profile_r2,
            "calibration_pass" => best_row.calibration_pass,
            "profile_csv" => best_result.profile_csv,
            "diagnostics_csv" => best_result.diagnostics_csv,
            "profile_svg" => best_result.profile_svg,
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "scan_svg" => scan_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DProfileModeScanResult(
        summary_csv,
        scan_svg,
        markdown_path,
        metadata_path,
        best_row.run_outdir,
        best_result.profile_csv,
        best_result.diagnostics_csv,
        best_result.profile_svg,
        best_row.temperature,
        best_row.xi_eff,
        best_row.abs_xi_error,
        target,
        length(temp_values),
	    )
end

function _profile_mode_basis_scan_label(z_basis_count::Integer, temperature::Real)
    return @sprintf("basis_%02d", Int(z_basis_count)) * "/" * _profile_mode_scan_label(temperature)
end

function _write_slit_3d_profile_mode_basis_scan_text(
    outdir::AbstractString,
    rows,
    best_row,
    target_source::AbstractString;
    target_label="AK Fig. 3",
)
    path = joinpath(outdir, _ak_target_slug(target_label) * "_3d_profile_mode_basis_scan.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 profile-mode $(target_label) basis scan")
        println(io)
        println(io, "This artifact scans both smooth slit-profile basis dimension and profile-mode fluctuation scale for the $(target_label) with-fluctuation profile.")
        println(io)
        println(io, "Target source: $(target_source).")
        println(io)
        println(io, @sprintf("Best scanned run: `z_basis_count = %d`, fluctuation scale = %.6g, `xi_eff = %.6g`, target `xi_eff = %.6g`, absolute error = %.6g.",
            Int(best_row.z_basis_count), best_row.temperature, best_row.xi_eff,
            best_row.target_xi_eff, best_row.abs_xi_error))
        println(io, @sprintf("Best-run diagnostics: calibration pass = %.0f, fit R2 = %.6g, target-profile RMSE = %.6g, target-profile R2 = %.6g, profile R-hat = %.6g, split R-hat = %.6g, acceptance = %.6g.",
            best_row.calibration_pass, best_row.xi_fit_r2,
            best_row.target_profile_rmse, best_row.target_profile_r2,
            best_row.profile_chain_rhat_max, best_row.profile_split_rhat_max,
            best_row.acceptance_rate))
        println(io)
        println(io, "Selection rule: passing rows are preferred first; ties are ordered by effective-xi error, split R-hat, target-profile RMSE, smaller basis dimension, and fluctuation scale. This prevents a visually close but nonstationary row from hiding a more stable candidate.")
        println(io)
        println(io, "Scope: this remains a controlled 3D profile-mode HE-VK1 Metropolis calibration route. It is the next reproducibility check after the unrestricted all-cell density measure was rejected by the lateral-simplex bias diagnostics.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `profile_mode_basis_temperature_scan.csv`")
        println(io, "- `profile_mode_temperature_scan.svg`")
        println(io, "- one subdirectory per basis count and fluctuation scale, each containing profile and diagnostic files")
    end
    return path
end

function run_slit_3d_profile_mode_basis_ak_scan(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    target_xi_eff::Real=0.3270559793,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL points digitized from the local PDF rendering",
    temperatures=[1.2, 1.35, 1.45, 1.55, 1.7],
    z_basis_counts=[2, 3, 4],
    xi_tolerance::Real=0.03,
    rhat_threshold::Real=1.2,
    target_profile_r2_threshold::Real=0.995,
    steps::Integer=160_000,
    burnin_steps::Integer=40_000,
    sample_stride::Integer=40,
    proposal_width::Real=0.05,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    seed::Integer=270625,
    target_label=nothing,
)
    mkpath(outdir)
    resolved_target_label = _ak_target_label(target_source; target_label=target_label)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    temp_values = Float64.(collect(temperatures))
    isempty(temp_values) && throw(ArgumentError("temperatures must contain at least one value"))
    all(temp -> temp > 0.0, temp_values) ||
        throw(ArgumentError("all profile-mode fluctuation scales must be positive"))
    basis_values = Int.(collect(z_basis_counts))
    isempty(basis_values) && throw(ArgumentError("z_basis_counts must contain at least one value"))
    all(count -> count >= 1, basis_values) ||
        throw(ArgumentError("all z_basis_counts must be positive"))
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    r2_gate = Float64(target_profile_r2_threshold)
    raw_rows = NamedTuple[]
    for (basis_idx, basis_count) in enumerate(basis_values)
        for (temp_idx, temp) in enumerate(temp_values)
            run_outdir = joinpath(outdir, _profile_mode_basis_scan_label(basis_count, temp))
            result = run_slit_3d_profile_mode_vk1_mc(run_outdir;
                Nx=Nx, Ny=Ny, Nz=Nz, Lxy=Lxy, Lz=Lz, B=B, C=C, A=A, alpha=alpha,
                z_basis_count=basis_count, steps=steps, burnin_steps=burnin_steps,
                sample_stride=sample_stride, proposal_width=proposal_width,
                temperature=temp, chains=chains, symmetrize_profile=symmetrize_profile,
                seed=Int(seed) + 100_000 * (basis_idx - 1) + 10_000 * (temp_idx - 1))
            abs_xi_error = abs(result.xi_eff - target)
            target_phi = slit_reference_profile(result.grid.z; B=B, C=C, L=result.grid.Lz, xi=target)
            target_profile = _slit_profile_fit_diagnostics(result.mean_phi, target_phi)
            rhat_ok = isfinite(result.profile_chain_rhat_max) ?
                      result.profile_chain_rhat_max <= rhat_gate :
                      result.chain_count == 1
            split_rhat_ok = isfinite(result.profile_split_rhat_max) ?
                            result.profile_split_rhat_max <= rhat_gate :
                            result.chain_count == 1
            r2_ok = target_profile.r2 >= r2_gate
            calibration_pass = (abs_xi_error <= tol && r2_ok &&
                                result.xi_fit_quality_pass == 1.0 &&
                                rhat_ok && split_rhat_ok) ? 1.0 : 0.0
            push!(raw_rows, (
                z_basis_count=Int(basis_count),
                temperature=temp,
                target_xi_eff=target,
                target_source=String(target_source),
                xi_eff=result.xi_eff,
                abs_xi_error=abs_xi_error,
                xi_tolerance=tol,
                calibration_pass=calibration_pass,
                xi_bulk=result.xi_bulk,
                xi_fit_rmse=result.xi_fit_rmse,
                xi_fit_r2=result.xi_fit_r2,
                xi_fit_quality_pass=result.xi_fit_quality_pass,
                target_profile_rmse=target_profile.rmse,
                target_profile_r2=target_profile.r2,
                target_profile_max_abs_error=target_profile.max_abs_error,
                target_profile_wall_rms=target_profile.wall_rms,
                target_profile_r2_threshold=r2_gate,
                profile_chain_rhat_max=result.profile_chain_rhat_max,
                profile_split_rhat_max=result.profile_split_rhat_max,
                profile_chain_rmse_max=result.profile_chain_rmse_max,
                acceptance_rate=result.acceptance_rate,
                sample_count=Float64(result.sample_count),
                steps=Float64(result.steps),
                burnin_steps=Float64(result.burnin_steps),
                sample_stride=Float64(result.sample_stride),
                chain_count=Float64(result.chain_count),
                proposal_width=Float64(proposal_width),
                energy_mean=result.energy_mean,
                energy_stderr=result.energy_stderr,
                density_variance_mean=result.density_variance_mean,
                lateral_variance_mean=result.lateral_variance_mean,
                run_outdir=run_outdir,
                profile_csv=result.profile_csv,
                diagnostics_csv=result.diagnostics_csv,
                profile_svg=result.profile_svg,
            ))
        end
    end
    order = sortperm(eachindex(raw_rows); by=i -> (
        raw_rows[i].calibration_pass == 1.0 ? 0 : 1,
        raw_rows[i].abs_xi_error,
        isfinite(raw_rows[i].profile_split_rhat_max) ? raw_rows[i].profile_split_rhat_max : Inf,
        raw_rows[i].target_profile_rmse,
        raw_rows[i].z_basis_count,
        raw_rows[i].temperature,
    ))
    rank_by_idx = fill(0, length(raw_rows))
    for (rank, idx) in enumerate(order)
        rank_by_idx[idx] = rank
    end
    scan_rows = [merge(raw_rows[i], (selection_rank=rank_by_idx[i],)) for i in eachindex(raw_rows)]
    summary_csv = _write_dataframe(joinpath(outdir, "profile_mode_basis_temperature_scan.csv"), scan_rows)
    scan_svg = _write_slit_3d_profile_mode_scan_svg(summary_csv, outdir;
        target_label=resolved_target_label)
    best_idx = order[1]
    best_row = scan_rows[best_idx]
    markdown_path = _write_slit_3d_profile_mode_basis_scan_text(outdir, scan_rows,
        best_row, target_source; target_label=resolved_target_label)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_profile_mode_basis_ak_scan",
            "sampler" => "profile_mode_metropolis",
            "seed" => Int(seed),
        ),
        "target" => Dict{String,Any}(
            "observable" => resolved_target_label * " effective xi",
            "target_xi_eff" => target,
            "target_source" => String(target_source),
            "target_label" => resolved_target_label,
            "xi_tolerance" => tol,
            "target_profile_r2_threshold" => r2_gate,
        ),
        "grid" => Dict{String,Any}(
            "Nx" => Int(Nx),
            "Ny" => Int(Ny),
            "Nz" => Int(Nz),
            "Lxy" => Float64(Lxy),
            "Lz" => Float64(Lz),
        ),
        "parameters" => Dict{String,Any}(
            "A" => Float64(A),
            "B" => Float64(B),
            "C" => Float64(C),
            "alpha" => Float64(alpha),
            "model" => "HE-VK1",
        ),
        "scan" => Dict{String,Any}(
            "temperatures" => temp_values,
            "z_basis_counts" => basis_values,
            "steps" => Int(steps),
            "burnin_steps" => Int(burnin_steps),
            "sample_stride" => Int(sample_stride),
            "proposal_width" => Float64(proposal_width),
            "chains" => Int(chains),
            "rhat_threshold" => rhat_gate,
            "selection_rule" => "pass_first_then_xi_error_split_rhat_target_rmse_basis_temperature",
        ),
        "best" => Dict{String,Any}(
            "z_basis_count" => Int(best_row.z_basis_count),
            "temperature" => best_row.temperature,
            "xi_eff" => best_row.xi_eff,
            "abs_xi_error" => best_row.abs_xi_error,
            "target_profile_rmse" => best_row.target_profile_rmse,
            "target_profile_r2" => best_row.target_profile_r2,
            "calibration_pass" => best_row.calibration_pass,
            "profile_csv" => best_row.profile_csv,
            "diagnostics_csv" => best_row.diagnostics_csv,
            "profile_svg" => best_row.profile_svg,
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "scan_svg" => scan_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DProfileModeBasisScanResult(
        summary_csv,
        scan_svg,
        markdown_path,
        metadata_path,
        best_row.run_outdir,
        best_row.profile_csv,
        best_row.diagnostics_csv,
        best_row.profile_svg,
        Int(best_row.z_basis_count),
        best_row.temperature,
        best_row.xi_eff,
        best_row.abs_xi_error,
        best_row.calibration_pass,
        target,
        length(scan_rows),
    )
end

function _write_slit_3d_profile_mode_a_scan_svg(summary_csv::AbstractString,
    outdir::AbstractString; target_label="AK Fig. 3")
    header, rows = _read_csv_strings(summary_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "profile_mode_a_scan.svg")
    label = _xml_text(target_label)
    idx(name) = findfirst(==(name), header)
    A_idx = idx("A")
    xi_idx = idx("xi_eff")
    target_idx = idx("target_xi_eff")
    rank_idx = idx("selection_rank")
    if A_idx === nothing || xi_idx === nothing || target_idx === nothing || isempty(rows)
        open(svg_path, "w") do io
            println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420'></svg>")
        end
        return svg_path
    end
    A_values = [parse(Float64, row[A_idx]) for row in rows]
    xi_values = [parse(Float64, row[xi_idx]) for row in rows]
    target = parse(Float64, rows[1][target_idx])
    selected = rank_idx === nothing ? 1 : findfirst(row -> row[rank_idx] == "1", rows)
    selected === nothing && (selected = 1)
    xmin, xmax = extrema(A_values)
    ymin, ymax = extrema(vcat(xi_values, [target]))
    xrange = max(xmax - xmin, 1.0)
    yrange = max(ymax - ymin, 1.0e-6)
    xmin -= 0.08 * xrange
    xmax += 0.08 * xrange
    ymin -= 0.12 * yrange
    ymax += 0.12 * yrange
    x_plot(x) = 70.0 + (Float64(x) - xmin) / (xmax - xmin) * 500.0
    y_plot(y) = 350.0 - (Float64(y) - ymin) / (ymax - ymin) * 280.0
    points = join((@sprintf("%.3f,%.3f", x_plot(A_values[i]), y_plot(xi_values[i]))
                   for i in eachindex(A_values)), " ")
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420' viewBox='0 0 640 420'>")
        println(io, "<style>text{font-family:Arial,sans-serif;fill:#222}.axis{stroke:#222;stroke-width:1}.grid{stroke:#ddd;stroke-width:0.8}.series{fill:none;stroke:#1f77b4;stroke-width:2.4}.target{stroke:#555;stroke-width:1.8;stroke-dasharray:6 4}.selected{fill:#d62728;stroke:#d62728}</style>")
        println(io, "<title>3D VK1 profile-mode A scan for $(label)</title>")
        println(io, "<rect x='0' y='0' width='640' height='420' fill='white'/>")
        println(io, "<text x='35' y='32' font-size='18'>3D VK1 profile-mode $(label) A scan</text>")
        println(io, "<text x='260' y='400' font-size='13'>A correction</text>")
        println(io, "<text transform='translate(18 250) rotate(-90)' font-size='13'>xi_eff</text>")
        println(io, "<line class='axis' x1='70' y1='350' x2='570' y2='350'/>")
        println(io, "<line class='axis' x1='70' y1='70' x2='70' y2='350'/>")
        for frac in 0:0.25:1
            xval = xmin + frac * (xmax - xmin)
            xpos = x_plot(xval)
            println(io, @sprintf("<line class='grid' x1='%.3f' y1='70' x2='%.3f' y2='350'/>", xpos, xpos))
            println(io, @sprintf("<text x='%.3f' y='370' font-size='11' text-anchor='middle'>%.3g</text>", xpos, xval))
            yval = ymin + frac * (ymax - ymin)
            ypos = y_plot(yval)
            println(io, @sprintf("<line class='grid' x1='70' y1='%.3f' x2='570' y2='%.3f'/>", ypos, ypos))
            println(io, @sprintf("<text x='62' y='%.3f' font-size='11' text-anchor='end' dominant-baseline='middle'>%.3g</text>", ypos, yval))
        end
        target_y = y_plot(target)
        println(io, @sprintf("<line class='target' x1='70' y1='%.3f' x2='570' y2='%.3f'/>", target_y, target_y))
        println(io, "<polyline class='series' points='$(points)'/>")
        for i in eachindex(A_values)
            cls = i == selected ? "selected" : "series-point"
            fill = i == selected ? "#d62728" : "#1f77b4"
            println(io, @sprintf("<circle class='%s' cx='%.3f' cy='%.3f' r='4.0' fill='%s'/>",
                cls, x_plot(A_values[i]), y_plot(xi_values[i]), fill))
        end
        println(io, "<line x1='410' y1='76' x2='446' y2='76' stroke='#555' stroke-width='1.8' stroke-dasharray='6 4'/>")
        println(io, "<text x='454' y='80' font-size='12'>$(label) target xi</text>")
        println(io, "<line x1='410' y1='96' x2='446' y2='96' stroke='#1f77b4' stroke-width='2.4'/>")
        println(io, "<text x='454' y='100' font-size='12'>T=1 VK1 MC xi_eff</text>")
        println(io, "<circle cx='428' cy='116' r='4.0' fill='#d62728'/>")
        println(io, "<text x='454' y='120' font-size='12'>selected run</text>")
        println(io, "</svg>")
    end
    return svg_path
end

function _write_slit_3d_profile_mode_a_scan_text(
    outdir::AbstractString,
    rows,
    best_row,
    target_source::AbstractString;
    target_label="AK Fig. 3",
)
    path = joinpath(outdir, _ak_target_slug(target_label) * "_3d_profile_mode_a_scan.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 profile-mode $(target_label) A scan")
        println(io)
        println(io, "This artifact scans the VK1 entropy-correction coefficient `A` at canonical Metropolis temperature `T_MC = 1` for the $(target_label) with-fluctuation profile.")
        println(io)
        println(io, "Target source: $(target_source).")
        println(io)
        println(io, @sprintf("Best scanned run: `A = %.6g`, `z_basis_count = %d`, `xi_eff = %.6g`, target `xi_eff = %.6g`, absolute error = %.6g.",
            best_row.A, Int(best_row.z_basis_count), best_row.xi_eff,
            best_row.target_xi_eff, best_row.abs_xi_error))
        println(io, @sprintf("Best-run diagnostics: calibration pass = %.0f, fit R2 = %.6g, target-profile RMSE = %.6g, target-profile R2 = %.6g, profile R-hat = %.6g, split R-hat = %.6g, acceptance = %.6g.",
            best_row.calibration_pass, best_row.xi_fit_r2,
            best_row.target_profile_rmse, best_row.target_profile_r2,
            best_row.profile_chain_rhat_max, best_row.profile_split_rhat_max,
            best_row.acceptance_rate))
        println(io)
        println(io, "Selection rule: passing rows are preferred first; ties are ordered by effective-xi error, split R-hat, target-profile RMSE, `A`, and basis dimension.")
        println(io)
        println(io, "Scope: unlike the older temperature scans, this scan keeps the Metropolis temperature fixed at one. The scanned `A` is a Hamiltonian parameter representing the real entropy-like fluctuation correction.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `profile_mode_a_scan.csv`")
        println(io, "- `profile_mode_a_scan.svg`")
        println(io, "- one subdirectory per A value containing profile and diagnostic files")
    end
    return path
end

function run_slit_3d_profile_mode_a_ak_scan(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    target_xi_eff::Real=0.3270559793,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL points digitized from the local PDF rendering",
    A_values=[0.0, 0.5, 1.0, 1.5, 2.0],
    z_basis_count::Integer=4,
    xi_tolerance::Real=0.03,
    rhat_threshold::Real=1.2,
    target_profile_r2_threshold::Real=0.995,
    temperature::Real=1.0,
    steps::Integer=160_000,
    burnin_steps::Integer=40_000,
    sample_stride::Integer=80,
    proposal_width::Real=0.8,
    chains::Integer=4,
    symmetrize_profile::Bool=true,
    seed::Integer=300625,
    target_label=nothing,
)
    mkpath(outdir)
    resolved_target_label = _ak_target_label(target_source; target_label=target_label)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    a_values = Float64.(collect(A_values))
    isempty(a_values) && throw(ArgumentError("A_values must contain at least one value"))
    all(isfinite, a_values) || throw(ArgumentError("all A_values must be finite"))
    temp = Float64(temperature)
    temp > 0.0 || throw(ArgumentError("temperature must be positive"))
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    r2_gate = Float64(target_profile_r2_threshold)
    basis_count = max(1, Int(z_basis_count))
    raw_rows = NamedTuple[]
    for (idx, A) in enumerate(a_values)
        label = replace(@sprintf("%.7g", A), "-" => "m", "." => "p", "+" => "")
        run_outdir = joinpath(outdir, "A_" * label)
        result = run_slit_3d_profile_mode_vk1_mc(run_outdir;
            Nx=Nx, Ny=Ny, Nz=Nz, Lxy=Lxy, Lz=Lz, B=B, C=C, A=A,
            z_basis_count=basis_count, steps=steps, burnin_steps=burnin_steps,
            sample_stride=sample_stride, proposal_width=proposal_width,
            temperature=temp, chains=chains, symmetrize_profile=symmetrize_profile,
            seed=Int(seed) + 10_000 * (idx - 1))
        abs_xi_error = abs(result.xi_eff - target)
        target_phi = slit_reference_profile(result.grid.z; B=B, C=C, L=result.grid.Lz, xi=target)
        target_profile = _slit_profile_fit_diagnostics(result.mean_phi, target_phi)
        rhat_ok = isfinite(result.profile_chain_rhat_max) ?
                  result.profile_chain_rhat_max <= rhat_gate :
                  result.chain_count == 1
        split_rhat_ok = isfinite(result.profile_split_rhat_max) ?
                        result.profile_split_rhat_max <= rhat_gate :
                        result.chain_count == 1
        r2_ok = target_profile.r2 >= r2_gate
        calibration_pass = (abs_xi_error <= tol && r2_ok &&
                            result.xi_fit_quality_pass == 1.0 &&
                            rhat_ok && split_rhat_ok) ? 1.0 : 0.0
        push!(raw_rows, (
            A=A,
            temperature=temp,
            target_xi_eff=target,
            target_source=String(target_source),
            xi_eff=result.xi_eff,
            abs_xi_error=abs_xi_error,
            xi_tolerance=tol,
            calibration_pass=calibration_pass,
            xi_bulk=result.xi_bulk,
            xi_fit_rmse=result.xi_fit_rmse,
            xi_fit_r2=result.xi_fit_r2,
            xi_fit_quality_pass=result.xi_fit_quality_pass,
            target_profile_rmse=target_profile.rmse,
            target_profile_r2=target_profile.r2,
            target_profile_max_abs_error=target_profile.max_abs_error,
            target_profile_wall_rms=target_profile.wall_rms,
            target_profile_r2_threshold=r2_gate,
            profile_chain_rhat_max=result.profile_chain_rhat_max,
            profile_split_rhat_max=result.profile_split_rhat_max,
            profile_chain_rmse_max=result.profile_chain_rmse_max,
            acceptance_rate=result.acceptance_rate,
            sample_count=Float64(result.sample_count),
            steps=Float64(result.steps),
            burnin_steps=Float64(result.burnin_steps),
            sample_stride=Float64(result.sample_stride),
            chain_count=Float64(result.chain_count),
            z_basis_count=Int(basis_count),
            proposal_width=Float64(proposal_width),
            energy_mean=result.energy_mean,
            energy_stderr=result.energy_stderr,
            density_variance_mean=result.density_variance_mean,
            lateral_variance_mean=result.lateral_variance_mean,
            run_outdir=run_outdir,
            profile_csv=result.profile_csv,
            diagnostics_csv=result.diagnostics_csv,
            profile_svg=result.profile_svg,
        ))
    end
    order = sortperm(eachindex(raw_rows); by=i -> (
        raw_rows[i].calibration_pass == 1.0 ? 0 : 1,
        raw_rows[i].abs_xi_error,
        isfinite(raw_rows[i].profile_split_rhat_max) ? raw_rows[i].profile_split_rhat_max : Inf,
        raw_rows[i].target_profile_rmse,
        raw_rows[i].A,
        raw_rows[i].z_basis_count,
    ))
    rank_by_idx = fill(0, length(raw_rows))
    for (rank, idx) in enumerate(order)
        rank_by_idx[idx] = rank
    end
    scan_rows = [merge(raw_rows[i], (selection_rank=rank_by_idx[i],)) for i in eachindex(raw_rows)]
    summary_csv = _write_dataframe(joinpath(outdir, "profile_mode_a_scan.csv"), scan_rows)
    scan_svg = _write_slit_3d_profile_mode_a_scan_svg(summary_csv, outdir;
        target_label=resolved_target_label)
    best_idx = order[1]
    best_row = scan_rows[best_idx]
    markdown_path = _write_slit_3d_profile_mode_a_scan_text(outdir, scan_rows,
        best_row, target_source; target_label=resolved_target_label)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_profile_mode_a_ak_scan",
            "sampler" => "profile_mode_metropolis",
            "seed" => Int(seed),
        ),
        "target" => Dict{String,Any}(
            "observable" => resolved_target_label * " effective xi",
            "target_xi_eff" => target,
            "target_source" => String(target_source),
            "target_label" => resolved_target_label,
            "xi_tolerance" => tol,
            "target_profile_r2_threshold" => r2_gate,
        ),
        "grid" => Dict{String,Any}(
            "Nx" => Int(Nx),
            "Ny" => Int(Ny),
            "Nz" => Int(Nz),
            "Lxy" => Float64(Lxy),
            "Lz" => Float64(Lz),
        ),
        "parameters" => Dict{String,Any}(
            "B" => Float64(B),
            "C" => Float64(C),
            "model" => "HE-VK1",
        ),
        "scan" => Dict{String,Any}(
            "A_values" => a_values,
            "temperature" => temp,
            "z_basis_count" => basis_count,
            "steps" => Int(steps),
            "burnin_steps" => Int(burnin_steps),
            "sample_stride" => Int(sample_stride),
            "proposal_width" => Float64(proposal_width),
            "chains" => Int(chains),
            "rhat_threshold" => rhat_gate,
            "selection_rule" => "pass_first_then_xi_error_split_rhat_target_rmse_A_basis",
        ),
        "best" => Dict{String,Any}(
            "A" => best_row.A,
            "temperature" => best_row.temperature,
            "z_basis_count" => Int(best_row.z_basis_count),
            "xi_eff" => best_row.xi_eff,
            "abs_xi_error" => best_row.abs_xi_error,
            "target_profile_rmse" => best_row.target_profile_rmse,
            "target_profile_r2" => best_row.target_profile_r2,
            "calibration_pass" => best_row.calibration_pass,
            "profile_csv" => best_row.profile_csv,
            "diagnostics_csv" => best_row.diagnostics_csv,
            "profile_svg" => best_row.profile_svg,
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "scan_svg" => scan_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DProfileModeAScanResult(
        summary_csv,
        scan_svg,
        markdown_path,
        metadata_path,
        best_row.run_outdir,
        best_row.profile_csv,
        best_row.diagnostics_csv,
        best_row.profile_svg,
        best_row.A,
        best_row.temperature,
        Int(best_row.z_basis_count),
        best_row.xi_eff,
        best_row.abs_xi_error,
        best_row.calibration_pass,
        target,
        length(scan_rows),
    )
end

function _measure_corrected_scan_label(power::Real, amplitude::Real)
    p = replace(@sprintf("%.7g", Float64(power)), "-" => "m", "." => "p", "+" => "")
    a = replace(@sprintf("%.7g", Float64(amplitude)), "-" => "m", "." => "p", "+" => "")
    return "power_" * p * "_amp_" * a
end

function _write_slit_3d_measure_corrected_scan_svg(summary_csv::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_strings(summary_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "measure_corrected_scan.svg")
    isempty(rows) && return svg_path
    idx(name) = findfirst(==(name), header)
    power_idx = idx("profile_measure_power")
    amp_idx = idx("profile_mode_amplitude")
    xi_idx = idx("xi_eff")
    target_idx = idx("target_xi_eff")
    rank_idx = idx("selection_rank")
    parsed = [
        (
            power=parse(Float64, row[power_idx]),
            amplitude=parse(Float64, row[amp_idx]),
            xi_eff=parse(Float64, row[xi_idx]),
            target=parse(Float64, row[target_idx]),
            rank=parse(Int, row[rank_idx]),
        ) for row in rows
    ]
    target = parsed[1].target
    xmin, xmax = _expand_plot_range(minimum(row.power for row in parsed),
        maximum(row.power for row in parsed))
    ymin, ymax = _expand_plot_range(minimum(vcat([row.xi_eff for row in parsed], [target])),
        maximum(vcat([row.xi_eff for row in parsed], [target])))
    ymin = min(0.0, ymin)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=9)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    sorted = sort(parsed; by=row -> (row.amplitude, row.power))
    amplitudes = sort(unique(row.amplitude for row in sorted))
    colors = ["#1f77b4", "#2ca02c", "#9467bd", "#ff7f0e", "#17becf", "#8c564b"]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>3D VK1 measure-corrected AK Fig. 3 xi scan</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>3D VK1 measure-corrected AK Fig. 3 scan</text>")
        println(io, @sprintf("<text x='35' y='52' font-size='12' fill='#555'>Target effective xi = %.6g; points are full-cell Arianna MC runs</text>", target))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>profile-measure power</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>effective xi</text>")
        println(io, @sprintf("<line x1='70' y1='%.3f' x2='600' y2='%.3f' stroke='#555' stroke-width='1.8' stroke-dasharray='6 4'/>",
            y_plot(target), y_plot(target)))
        for (amp_idx_local, amp) in enumerate(amplitudes)
            selected = [row for row in sorted if row.amplitude == amp]
            points = [(x_plot(row.power), y_plot(row.xi_eff)) for row in selected]
            color = colors[mod1(amp_idx_local, length(colors))]
            length(points) > 1 &&
                println(io, "<polyline fill='none' stroke='$color' stroke-width='2.0' points='$(_svg_polyline(points))'/>")
            for row in selected
                fill = row.rank == 1 ? "#d62728" : "white"
                stroke = row.rank == 1 ? "#d62728" : color
                println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4.0' fill='%s' stroke='%s' stroke-width='1.5'/>",
                    x_plot(row.power), y_plot(row.xi_eff), fill, stroke))
            end
        end
        println(io, "<line x1='395' y1='76' x2='431' y2='76' stroke='#555' stroke-width='1.8' stroke-dasharray='6 4'/>")
        println(io, "<text x='439' y='80' font-size='12'>AK Fig. 3 target xi</text>")
        for (i, amp) in enumerate(amplitudes[1:min(end, 4)])
            color = colors[mod1(i, length(colors))]
            y = 100 + 20 * (i - 1)
            println(io, @sprintf("<line x1='395' y1='%d' x2='431' y2='%d' stroke='%s' stroke-width='2.0'/>", y - 4, y - 4, color))
            println(io, @sprintf("<text x='439' y='%d' font-size='12'>amp %.3g</text>", y, amp))
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_slit_3d_measure_corrected_scan_text(
    outdir::AbstractString,
    rows,
    best_row,
    target_source::AbstractString,
)
    path = joinpath(outdir, "measure_corrected_scan.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 measure-corrected AK Fig. 3 scan")
        println(io)
        println(io, "This artifact scans the full-cell 3D Arianna/Metropolis HE-VK1 sampler after correcting the leading lateral simplex measure bias. The target observable is the Eq. 22 effective correlation length fitted to the digitized Alexander-Katz Fig. 3 CL profile.")
        println(io)
        println(io, "Target source: $(target_source).")
        println(io)
        println(io, @sprintf("Best scanned run: profile-measure power = %.7g, profile-mode amplitude = %.7g, `xi_eff = %.6g`, target `xi_eff = %.6g`, absolute error = %.6g, calibration pass = %.0f.",
            best_row.profile_measure_power, best_row.profile_mode_amplitude,
            best_row.xi_eff, best_row.target_xi_eff, best_row.abs_xi_error,
            best_row.calibration_pass))
        println(io, @sprintf("Best-run diagnostics: fit R2 = %.6g, target-profile RMSE = %.6g, target-profile R2 = %.6g, profile R-hat = %.6g, split R-hat = %.6g, profile-mode acceptance = %.6g, reference-width acceptance = %.6g, total acceptance = %.6g.",
            best_row.xi_fit_r2, best_row.target_profile_rmse,
            best_row.target_profile_r2, best_row.profile_chain_rhat_max,
            best_row.profile_split_rhat_max, best_row.profile_mode_acceptance_rate,
            best_row.reference_width_acceptance_rate, best_row.acceptance_rate))
        println(io)
        println(io, "Scope and limitation: this scan uses the full 3D density-cell sampler, not the profile-mode-only surrogate. Rows must satisfy the convergence and fit gates before they can be used as manuscript evidence for CL reproduction.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `measure_corrected_scan.csv`")
        println(io, "- `measure_corrected_scan.svg`")
        println(io, "- one subdirectory per scanned measure-power/profile-move-amplitude pair")
    end
    return path
end

function _diagnostic_value(path::AbstractString, name::AbstractString)
    header, rows = _read_csv_strings(path)
    isempty(rows) && return NaN
    return _row_value_or(header, rows[1], name, NaN)
end

function _slit_xi_block_drift_diagnostics(
    xi_blocks_csv::AbstractString;
    drift_tolerance::Real=0.03,
)
    tol = max(Float64(drift_tolerance), 0.0)
    if !isfile(xi_blocks_csv)
        return (
            max_abs_start_end_delta=NaN,
            max_abs_slope=NaN,
            monotone_chain_fraction=NaN,
            block_drift_pass=0.0,
            chain_count=0,
            min_block_count=0,
            max_block_count=0,
        )
    end
    blocks = CSV.read(xi_blocks_csv, DataFrames.DataFrame)
    if DataFrames.nrow(blocks) == 0 || !("chain" in names(blocks)) ||
       !("block" in names(blocks)) || !("xi_eff" in names(blocks))
        return (
            max_abs_start_end_delta=NaN,
            max_abs_slope=NaN,
            monotone_chain_fraction=NaN,
            block_drift_pass=0.0,
            chain_count=0,
            min_block_count=0,
            max_block_count=0,
        )
    end

    deltas = Float64[]
    slopes = Float64[]
    block_counts = Int[]
    monotone_drift_count = 0
    for chain_df in DataFrames.groupby(blocks, :chain)
        sorted = sort(chain_df, :block)
        xis = Float64.(sorted.xi_eff)
        filter!(isfinite, xis)
        n = length(xis)
        push!(block_counts, n)
        n == 0 && continue
        delta = xis[end] - xis[1]
        push!(deltas, abs(delta))
        if n > 1
            xs = collect(1:n)
            xbar = mean(xs)
            ybar = mean(xis)
            denom = sum((x - xbar)^2 for x in xs)
            slope = denom <= eps(Float64) ? 0.0 :
                    sum((xs[i] - xbar) * (xis[i] - ybar) for i in 1:n) / denom
            push!(slopes, abs(slope))
            diffs = diff(xis)
            monotone = all(value -> value >= 0.0, diffs) ||
                       all(value -> value <= 0.0, diffs)
            monotone && abs(delta) > tol && (monotone_drift_count += 1)
        else
            push!(slopes, 0.0)
        end
    end
    chain_count = length(block_counts)
    max_delta = isempty(deltas) ? NaN : maximum(deltas)
    max_slope = isempty(slopes) ? NaN : maximum(slopes)
    monotone_fraction = chain_count == 0 ? NaN : monotone_drift_count / chain_count
    pass = isfinite(max_delta) && max_delta <= tol ? 1.0 : 0.0
    return (
        max_abs_start_end_delta=max_delta,
        max_abs_slope=max_slope,
        monotone_chain_fraction=monotone_fraction,
        block_drift_pass=pass,
        chain_count=chain_count,
        min_block_count=isempty(block_counts) ? 0 : minimum(block_counts),
        max_block_count=isempty(block_counts) ? 0 : maximum(block_counts),
    )
end

_slit_3d_chunk_manifest_path(outdir::AbstractString) =
    joinpath(outdir, "chunk_manifest.csv")

_slit_3d_chunk_trace_dir(outdir::AbstractString) =
    joinpath(outdir, "chunk_traces")

_slit_3d_chunk_state_dir(outdir::AbstractString) =
    joinpath(outdir, "chunk_state")

_slit_3d_chunk_trace_path(outdir::AbstractString, chain_idx::Integer, chunk_idx::Integer) =
    joinpath(_slit_3d_chunk_trace_dir(outdir),
        @sprintf("chain_%03d_chunk_%05d.jls", Int(chain_idx), Int(chunk_idx)))

_slit_3d_chunk_state_path(outdir::AbstractString, chain_idx::Integer) =
    joinpath(_slit_3d_chunk_state_dir(outdir),
        @sprintf("chain_%03d_field.jls", Int(chain_idx)))

function _serialize_jls(path::AbstractString, value)
    mkpath(dirname(path))
    open(path, "w") do io
        serialize(io, value)
    end
    return path
end

function _deserialize_jls(path::AbstractString)
    open(path, "r") do io
        return deserialize(io)
    end
end

function _slit_3d_chunk_manifest(path::AbstractString)
    if !isfile(path) || filesize(path) == 0
        return DataFrames.DataFrame()
    end
    return CSV.read(path, DataFrames.DataFrame)
end

function _slit_3d_next_chunk_index(manifest_path::AbstractString, chain_idx::Integer)
    manifest = _slit_3d_chunk_manifest(manifest_path)
    if DataFrames.nrow(manifest) == 0 || !("chain" in names(manifest)) ||
       !("chunk" in names(manifest))
        return 1
    end
    chain_rows = manifest[manifest.chain .== Int(chain_idx), :]
    DataFrames.nrow(chain_rows) == 0 && return 1
    return maximum(Int.(chain_rows.chunk)) + 1
end

function _slit_3d_chunk_counts(manifest_path::AbstractString, chain_count::Integer)
    manifest = _slit_3d_chunk_manifest(manifest_path)
    counts = Int[]
    if DataFrames.nrow(manifest) == 0 || !("chain" in names(manifest)) ||
       !("chunk" in names(manifest))
        return counts
    end
    for chain_idx in 1:Int(chain_count)
        chain_rows = manifest[manifest.chain .== chain_idx, :]
        DataFrames.nrow(chain_rows) == 0 && continue
        push!(counts, length(unique(Int.(chain_rows.chunk))))
    end
    return counts
end

function _slit_3d_select_chain_indices(chain_indices, chain_count::Integer)
    total = max(1, Int(chain_count))
    selected = chain_indices === nothing ? collect(1:total) : Int.(collect(chain_indices))
    isempty(selected) && throw(ArgumentError("chain_indices must select at least one chain"))
    all(idx -> 1 <= idx <= total, selected) ||
        throw(ArgumentError("chain_indices must be between 1 and chains"))
    return unique(selected)
end

function _slit_3d_measure_corrected_saddle_profile(
    grid::SlitGrid3D,
    params::SlitParams,
    initial_profile,
    reference_width_xi::Real,
)
    profile_mode = Symbol(initial_profile)
    if profile_mode == :eq22
        return slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz)
    elseif profile_mode == :reference_width
        return slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz,
            xi=max(Float64(reference_width_xi), eps(Float64)))
    elseif profile_mode == :low_density
        return slit_low_density_profile(grid.slit_grid)
    elseif profile_mode == :vk1_smooth
        return minimize_slit_vk1_smooth_basis_saddle(params.B, params.C, params.A;
            Nz=grid.Nz, L=grid.Lz, alpha=params.alpha,
            local_potential_coeffs=params.local_potential_coeffs,
            basis_count=min(12, grid.Nz - 1), max_iterations=3000).phi
    end
    throw(ArgumentError("initial_profile must be :eq22, :reference_width, :low_density, or :vk1_smooth"))
end

_slit_trace_property(trace, name::Symbol, default) =
    hasproperty(trace, name) ? getproperty(trace, name) : default

function _merge_slit_3d_trace_chunks(chunks)
    isempty(chunks) && throw(ArgumentError("at least one trace chunk is required"))
    nz = length(chunks[1].profile_traces)
    profile_traces = [Float64[] for _ in 1:nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    profile_measure_log_jacobian_trace = Float64[]
    for chunk in chunks
        length(chunk.profile_traces) == nz ||
            throw(DimensionMismatch("trace chunks must have the same Nz"))
        for k in 1:nz
            append!(profile_traces[k], chunk.profile_traces[k])
        end
        append!(energy_trace, chunk.energy_trace)
        append!(density_variance_trace, chunk.density_variance_trace)
        append!(lateral_variance_trace, chunk.lateral_variance_trace)
        append!(xy_profile_roughness_trace, chunk.xy_profile_roughness_trace)
        append!(profile_measure_log_jacobian_trace,
            chunk.profile_measure_log_jacobian_trace)
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("trace chunks contain no stored samples"))
    accepted = sum(chunk.accepted_moves for chunk in chunks)
    attempted = sum(chunk.attempted_moves for chunk in chunks)
    pair_accepted = sum(chunk.pair_accepted_moves for chunk in chunks)
    pair_attempted = sum(chunk.pair_attempted_moves for chunk in chunks)
    plane_accepted = sum(chunk.plane_accepted_moves for chunk in chunks)
    plane_attempted = sum(chunk.plane_attempted_moves for chunk in chunks)
    global_accepted = sum(chunk.global_accepted_moves for chunk in chunks)
    global_attempted = sum(chunk.global_attempted_moves for chunk in chunks)
    profile_mode_accepted = sum(chunk.profile_mode_accepted_moves for chunk in chunks)
    profile_mode_attempted = sum(chunk.profile_mode_attempted_moves for chunk in chunks)
    reference_width_accepted = sum(chunk.reference_width_accepted_moves for chunk in chunks)
    reference_width_attempted = sum(chunk.reference_width_attempted_moves for chunk in chunks)
    reference_width_reflection_accepted =
        sum(_slit_trace_property(chunk, :reference_width_reflection_accepted_moves, 0)
            for chunk in chunks)
    reference_width_reflection_attempted =
        sum(_slit_trace_property(chunk, :reference_width_reflection_attempted_moves, 0)
            for chunk in chunks)
    return (
        mean_phi=[mean(trace) for trace in profile_traces],
        stderr_phi=[_markov_mean_stderr(trace) for trace in profile_traces],
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        profile_measure_log_jacobian_trace=profile_measure_log_jacobian_trace,
        sample_count=sample_count,
        acceptance_rate=accepted / max(attempted, 1),
        pair_acceptance_rate=pair_accepted / max(pair_attempted, 1),
        plane_acceptance_rate=plane_accepted / max(plane_attempted, 1),
        global_acceptance_rate=global_accepted / max(global_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted /
                                        max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        pair_accepted_moves=pair_accepted,
        pair_attempted_moves=pair_attempted,
        plane_accepted_moves=plane_accepted,
        plane_attempted_moves=plane_attempted,
        global_accepted_moves=global_accepted,
        global_attempted_moves=global_attempted,
        profile_mode_accepted_moves=profile_mode_accepted,
        profile_mode_attempted_moves=profile_mode_attempted,
        reference_width_accepted_moves=reference_width_accepted,
        reference_width_attempted_moves=reference_width_attempted,
        reference_width_reflection_accepted_moves=reference_width_reflection_accepted,
        reference_width_reflection_attempted_moves=reference_width_reflection_attempted,
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=sum(chunk.steps for chunk in chunks),
        burnin_steps=sum(chunk.burnin_steps for chunk in chunks),
        sample_stride=chunks[1].sample_stride,
        pair_proposal_amplitude=mean(chunk.pair_proposal_amplitude for chunk in chunks),
        plane_proposal_amplitude=mean(chunk.plane_proposal_amplitude for chunk in chunks),
        global_field_amplitude=mean(chunk.global_field_amplitude for chunk in chunks),
        profile_mode_amplitude=mean(chunk.profile_mode_amplitude for chunk in chunks),
        profile_mode_count=chunks[1].profile_mode_count,
        reference_width_amplitude=mean(chunk.reference_width_amplitude for chunk in chunks),
        reference_width_xi=chunks[1].reference_width_xi,
        tuning_acceptance_rate=mean(chunk.tuning_acceptance_rate for chunk in chunks),
        tune_rounds=sum(chunk.tune_rounds for chunk in chunks),
        tune_steps=chunks[1].tune_steps,
        arianna_path=join((chunk.arianna_path for chunk in chunks), ";"),
        final_phi=copy(chunks[end].final_phi),
    )
end

function _merge_slit_3d_blocked_trace_chunks(chunks)
    isempty(chunks) && throw(ArgumentError("at least one blocked trace chunk is required"))
    nz = length(chunks[1].profile_traces)
    profile_traces = [Float64[] for _ in 1:nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    profile_measure_log_jacobian_trace = Float64[]
    for chunk in chunks
        length(chunk.profile_traces) == nz ||
            throw(DimensionMismatch("blocked trace chunks must have the same Nz"))
        for k in 1:nz
            append!(profile_traces[k], chunk.profile_traces[k])
        end
        append!(energy_trace, chunk.energy_trace)
        append!(density_variance_trace, chunk.density_variance_trace)
        append!(lateral_variance_trace, chunk.lateral_variance_trace)
        append!(xy_profile_roughness_trace, chunk.xy_profile_roughness_trace)
        append!(profile_measure_log_jacobian_trace,
            chunk.profile_measure_log_jacobian_trace)
    end
    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError("blocked trace chunks contain no stored samples"))
    accepted = sum(chunk.accepted_moves for chunk in chunks)
    attempted = sum(chunk.attempted_moves for chunk in chunks)
    lateral_fraction_accepted = sum(chunk.lateral_fraction_accepted_moves for chunk in chunks)
    lateral_fraction_attempted = sum(chunk.lateral_fraction_attempted_moves for chunk in chunks)
    profile_transfer_accepted = sum(chunk.profile_transfer_accepted_moves for chunk in chunks)
    profile_transfer_attempted = sum(chunk.profile_transfer_attempted_moves for chunk in chunks)
    profile_mode_accepted = sum(chunk.profile_mode_accepted_moves for chunk in chunks)
    profile_mode_attempted = sum(chunk.profile_mode_attempted_moves for chunk in chunks)
    reference_width_accepted = sum(chunk.reference_width_accepted_moves for chunk in chunks)
    reference_width_attempted = sum(chunk.reference_width_attempted_moves for chunk in chunks)
    reference_width_reflection_accepted =
        sum(_slit_trace_property(chunk, :reference_width_reflection_accepted_moves, 0)
            for chunk in chunks)
    reference_width_reflection_attempted =
        sum(_slit_trace_property(chunk, :reference_width_reflection_attempted_moves, 0)
            for chunk in chunks)
    replica_counts = [
        _slit_trace_property(chunk, :replica_count, 1)
        for chunk in chunks
    ]
    replica_temperatures = _slit_trace_property(chunks[1], :replica_temperatures, [1.0])
    replica_swap_interval = _slit_trace_property(chunks[1], :replica_swap_interval, 0)
    replica_swap_attempts =
        sum(_slit_trace_property(chunk, :replica_swap_attempts, 0) for chunk in chunks)
    replica_swap_accepts =
        sum(_slit_trace_property(chunk, :replica_swap_accepts, 0) for chunk in chunks)
    replica_round_trips =
        sum(_slit_trace_property(chunk, :replica_round_trips, 0) for chunk in chunks)
    replica_min_round_trips =
        minimum(_slit_trace_property(chunk, :replica_min_round_trips, 0) for chunk in chunks)
    replica_max_round_trips =
        maximum(_slit_trace_property(chunk, :replica_max_round_trips, 0) for chunk in chunks)
    return (
        mean_phi=[mean(trace) for trace in profile_traces],
        stderr_phi=[_markov_mean_stderr(trace) for trace in profile_traces],
        profile_traces=profile_traces,
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        profile_measure_log_jacobian_trace=profile_measure_log_jacobian_trace,
        sample_count=sample_count,
        acceptance_rate=accepted / max(attempted, 1),
        lateral_fraction_acceptance_rate=lateral_fraction_accepted /
                                          max(lateral_fraction_attempted, 1),
        profile_transfer_acceptance_rate=profile_transfer_accepted /
                                         max(profile_transfer_attempted, 1),
        profile_mode_acceptance_rate=profile_mode_accepted /
                                     max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted /
                                        max(reference_width_attempted, 1),
        lateral_fraction_accepted_moves=lateral_fraction_accepted,
        lateral_fraction_attempted_moves=lateral_fraction_attempted,
        profile_transfer_accepted_moves=profile_transfer_accepted,
        profile_transfer_attempted_moves=profile_transfer_attempted,
        profile_mode_accepted_moves=profile_mode_accepted,
        profile_mode_attempted_moves=profile_mode_attempted,
        reference_width_accepted_moves=reference_width_accepted,
        reference_width_attempted_moves=reference_width_attempted,
        reference_width_reflection_accepted_moves=reference_width_reflection_accepted,
        reference_width_reflection_attempted_moves=reference_width_reflection_attempted,
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=sum(chunk.steps for chunk in chunks),
        burnin_steps=sum(chunk.burnin_steps for chunk in chunks),
        sample_stride=chunks[1].sample_stride,
        lateral_fraction_amplitude=mean(chunk.lateral_fraction_amplitude for chunk in chunks),
        profile_transfer_amplitude=mean(chunk.profile_transfer_amplitude for chunk in chunks),
        profile_mode_amplitude=mean(chunk.profile_mode_amplitude for chunk in chunks),
        profile_mode_count=chunks[1].profile_mode_count,
        reference_width_amplitude=mean(chunk.reference_width_amplitude for chunk in chunks),
        reference_width_xi=chunks[1].reference_width_xi,
        replica_count=maximum(replica_counts),
        replica_temperatures=replica_temperatures,
        replica_swap_interval=replica_swap_interval,
        replica_swap_attempts=replica_swap_attempts,
        replica_swap_accepts=replica_swap_accepts,
        replica_round_trips=replica_round_trips,
        replica_min_round_trips=replica_min_round_trips,
        replica_max_round_trips=replica_max_round_trips,
        arianna_path=join((chunk.arianna_path for chunk in chunks), ";"),
        final_phi=copy(chunks[end].final_phi),
    )
end

function _slit_3d_analysis_chunk_rows(
    sorted_chain_rows::DataFrames.DataFrame;
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
)
    discard = max(0, Int(analysis_discard_initial_chunks))
    rows = sorted_chain_rows
    if discard > 0
        rows = rows[rows.chunk .> discard, :]
    end
    if analysis_tail_chunks !== nothing
        tail = max(1, Int(analysis_tail_chunks))
        n = DataFrames.nrow(rows)
        start = max(1, n - tail + 1)
        rows = rows[start:n, :]
    end
    DataFrames.nrow(rows) > 0 ||
        throw(ArgumentError("analysis chunk filter removed all completed chunks"))
    return rows
end

function _load_slit_3d_chunk_traces(
    manifest_path::AbstractString,
    chain_count::Integer;
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
)
    manifest = _slit_3d_chunk_manifest(manifest_path)
    if DataFrames.nrow(manifest) == 0 || !("chain" in names(manifest)) ||
       !("chunk" in names(manifest)) || !("trace_path" in names(manifest))
        return (traces=Any[], chain_indices=Int[], chunk_counts=Int[],
            completed_chunk_counts=Int[])
    end
    traces = Any[]
    chain_indices = Int[]
    chunk_counts = Int[]
    completed_chunk_counts = Int[]
    for chain_idx in 1:Int(chain_count)
        chain_rows = manifest[manifest.chain .== chain_idx, :]
        DataFrames.nrow(chain_rows) == 0 && continue
        sorted = sort(chain_rows, :chunk)
        completed_count = length(unique(Int.(sorted.chunk)))
        analysis_rows = _slit_3d_analysis_chunk_rows(sorted;
            analysis_tail_chunks=analysis_tail_chunks,
            analysis_discard_initial_chunks=analysis_discard_initial_chunks)
        chunks = Any[]
        for row in eachrow(analysis_rows)
            trace_path = String(row.trace_path)
            isfile(trace_path) ||
                throw(ArgumentError("missing serialized trace chunk: $(trace_path)"))
            push!(chunks, _deserialize_jls(trace_path))
        end
        push!(traces, _merge_slit_3d_trace_chunks(chunks))
        push!(chain_indices, chain_idx)
        push!(chunk_counts, length(chunks))
        push!(completed_chunk_counts, completed_count)
    end
    return (traces=traces, chain_indices=chain_indices, chunk_counts=chunk_counts,
        completed_chunk_counts=completed_chunk_counts)
end

function _load_slit_3d_blocked_chunk_traces(
    manifest_path::AbstractString,
    chain_count::Integer;
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
)
    manifest = _slit_3d_chunk_manifest(manifest_path)
    if DataFrames.nrow(manifest) == 0 || !("chain" in names(manifest)) ||
       !("chunk" in names(manifest)) || !("trace_path" in names(manifest))
        return (traces=Any[], chain_indices=Int[], chunk_counts=Int[],
            completed_chunk_counts=Int[])
    end
    traces = Any[]
    chain_indices = Int[]
    chunk_counts = Int[]
    completed_chunk_counts = Int[]
    for chain_idx in 1:Int(chain_count)
        chain_rows = manifest[manifest.chain .== chain_idx, :]
        DataFrames.nrow(chain_rows) == 0 && continue
        sorted = sort(chain_rows, :chunk)
        completed_count = length(unique(Int.(sorted.chunk)))
        analysis_rows = _slit_3d_analysis_chunk_rows(sorted;
            analysis_tail_chunks=analysis_tail_chunks,
            analysis_discard_initial_chunks=analysis_discard_initial_chunks)
        chunks = Any[]
        for row in eachrow(analysis_rows)
            trace_path = String(row.trace_path)
            isfile(trace_path) ||
                throw(ArgumentError("missing serialized blocked trace chunk: $(trace_path)"))
            push!(chunks, _deserialize_jls(trace_path))
        end
        push!(traces, _merge_slit_3d_blocked_trace_chunks(chunks))
        push!(chain_indices, chain_idx)
        push!(chunk_counts, length(chunks))
        push!(completed_chunk_counts, completed_count)
    end
    return (traces=traces, chain_indices=chain_indices, chunk_counts=chunk_counts,
        completed_chunk_counts=completed_chunk_counts)
end

function _finalize_slit_3d_measure_corrected_chunks(
    outdir::AbstractString,
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    traces,
    chain_indices::AbstractVector{<:Integer},
    chunk_counts::AbstractVector{<:Integer};
    completed_chunk_counts::AbstractVector{<:Integer}=chunk_counts,
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
    target_xi_eff::Real,
    target_source::AbstractString,
    xi_tolerance::Real,
    rhat_threshold::Real,
    r2_threshold::Real,
    block_drift_tolerance::Real,
    symmetrize_profile::Bool,
    profile_measure,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    profile_mode_move_weight::Real,
    reference_width_move_weight::Real,
    reference_width_reflection_move_weight::Real,
    reference_width_xi::Real,
    initial_profile,
    initial_state_outdir,
    initial_state_mode::AbstractString,
    seed::Integer,
    chunk_steps::Integer,
    first_burnin_steps::Integer,
    sample_stride::Integer,
)
    isempty(traces) && throw(ArgumentError("no chunk traces are available to finalize"))
    mkpath(outdir)
    resolved_profile_measure = _slit_3d_profile_measure_symbol(profile_measure)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "xy_average_mirror_symmetrized" : "xy_average_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)
    xi_block_drift = _slit_xi_block_drift_diagnostics(xi_blocks_csv;
        drift_tolerance=block_drift_tolerance)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    pair_accepted = sum(trace.pair_accepted_moves for trace in traces)
    pair_attempted = sum(trace.pair_attempted_moves for trace in traces)
    plane_accepted = sum(trace.plane_accepted_moves for trace in traces)
    plane_attempted = sum(trace.plane_attempted_moves for trace in traces)
    global_accepted = sum(trace.global_accepted_moves for trace in traces)
    global_attempted = sum(trace.global_attempted_moves for trace in traces)
    profile_mode_accepted = sum(trace.profile_mode_accepted_moves for trace in traces)
    profile_mode_attempted = sum(trace.profile_mode_attempted_moves for trace in traces)
    reference_width_accepted = sum(trace.reference_width_accepted_moves for trace in traces)
    reference_width_attempted = sum(trace.reference_width_attempted_moves for trace in traces)
    reference_width_reflection_accepted =
        sum(_slit_trace_property(trace, :reference_width_reflection_accepted_moves, 0)
            for trace in traces)
    reference_width_reflection_attempted =
        sum(_slit_trace_property(trace, :reference_width_reflection_attempted_moves, 0)
            for trace in traces)
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    profile_measure_log_jacobian_trace = reduce(vcat,
        (trace.profile_measure_log_jacobian_trace for trace in traces))

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(params.B, params.C)
    fit_phi = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    target = Float64(target_xi_eff)
    target_phi = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz,
        xi=target)
    target_profile = _slit_profile_fit_diagnostics(mean_phi, target_phi)
    observable_convergence = _slit_profile_observable_convergence(
        chain_estimator_traces, mean_phi, grid, target_phi, target)
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    r2_gate = Float64(r2_threshold)
    rhat_ok = isfinite(profile_convergence.profile_chain_rhat_max) ?
              profile_convergence.profile_chain_rhat_max <= rhat_gate :
              length(traces) == 1
    split_rhat_ok = isfinite(profile_convergence.profile_split_rhat_max) ?
                    profile_convergence.profile_split_rhat_max <= rhat_gate :
                    length(traces) == 1
    r2_ok = isfinite(fit_diagnostics.r2) && fit_diagnostics.r2 >= r2_gate
    abs_xi_error = abs(xi_eff - target)
    drift_ok = xi_block_drift.block_drift_pass == 1.0
    observable_xi_ok = observable_convergence.observable_abs_xi_error <= tol
    observable_chain_xi_ok =
        abs(observable_convergence.observable_chain_xi_min - target) <= tol &&
        abs(observable_convergence.observable_chain_xi_max - target) <= tol
    observable_leave_one_min = observable_convergence.observable_leave_one_chain_xi_min
    observable_leave_one_max = observable_convergence.observable_leave_one_chain_xi_max
    observable_leave_one_xi_ok =
        (!isfinite(observable_leave_one_min) && !isfinite(observable_leave_one_max)) ||
        (abs(observable_leave_one_min - target) <= tol &&
         abs(observable_leave_one_max - target) <= tol)
    observable_target_profile_r2_ok =
        isfinite(target_profile.r2) && target_profile.r2 >= r2_gate
    observable_fit_quality_ok = fit_diagnostics.quality_pass == 1.0
    observable_calibration_pass =
        (observable_xi_ok && observable_chain_xi_ok && observable_leave_one_xi_ok &&
         observable_target_profile_r2_ok && observable_fit_quality_ok && drift_ok) ? 1.0 : 0.0
    observable_convergence = merge(observable_convergence, (
        observable_xi_pass=observable_xi_ok ? 1.0 : 0.0,
        observable_chain_xi_pass=observable_chain_xi_ok ? 1.0 : 0.0,
        observable_leave_one_chain_xi_pass=observable_leave_one_xi_ok ? 1.0 : 0.0,
        observable_target_profile_r2_pass=observable_target_profile_r2_ok ? 1.0 : 0.0,
        observable_fit_quality_pass=observable_fit_quality_ok ? 1.0 : 0.0,
        observable_block_drift_pass=drift_ok ? 1.0 : 0.0,
        observable_calibration_pass=observable_calibration_pass,
    ))
    calibration_pass = (abs_xi_error <= tol && r2_ok &&
                        fit_diagnostics.quality_pass == 1.0 &&
                        rhat_ok && split_rhat_ok && drift_ok) ? 1.0 : 0.0
    min_chunk_count = isempty(chunk_counts) ? 0 : minimum(Int.(chunk_counts))
    max_chunk_count = isempty(chunk_counts) ? 0 : maximum(Int.(chunk_counts))
    chunk_count = min_chunk_count
    min_completed_chunk_count = isempty(completed_chunk_counts) ? 0 :
                                minimum(Int.(completed_chunk_counts))
    max_completed_chunk_count = isempty(completed_chunk_counts) ? 0 :
                                maximum(Int.(completed_chunk_counts))
    completed_chunk_count = min_completed_chunk_count
    analysis_tail_chunk_count = analysis_tail_chunks === nothing ? 0 :
                                max(1, Int(analysis_tail_chunks))
    discarded_initial_chunks = max(0, Int(analysis_discard_initial_chunks))
    proposals_per_sweep = _proposals_per_sweep(grid)
    aggregate_steps = traces[1].steps
    aggregate_burnin_steps = traces[1].burnin_steps
    total_sweeps = _sweeps_from_steps(grid, aggregate_steps)
    production_sweeps = _sweeps_from_steps(grid, aggregate_steps - aggregate_burnin_steps)
    resolved_burnin_sweeps = _sweeps_from_steps(grid, aggregate_burnin_steps)
    resolved_sample_stride_sweeps = _sweeps_from_steps(grid, sample_stride)

    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=Float64(saddle_phi[k]), stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="arianna_metropolis_raw_chunked"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
        push!(profile_rows, (series="ak_target_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=target_phi[k], stderr=0.0, xi=target,
            sampler="target_reference"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    observable_convergence_csv = _write_dataframe(
        joinpath(outdir, "slit_3d_mc_observable_convergence.csv"),
        [merge((profile_estimator=profile_estimator,), observable_convergence)])
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    profile_measure_log_jacobian_summary = batch_summary(profile_measure_log_jacobian_trace)
    roughness_mean = mean(xy_profile_roughness_trace)
    diagnostics_rows = [(
        sampler="arianna_metropolis_measure_corrected_chunked",
        chunked_sampler=true,
        chunk_count=Float64(chunk_count),
        min_chunk_count=Float64(min_chunk_count),
        max_chunk_count=Float64(max_chunk_count),
        completed_chunk_count=Float64(completed_chunk_count),
        min_completed_chunk_count=Float64(min_completed_chunk_count),
        max_completed_chunk_count=Float64(max_completed_chunk_count),
        analysis_tail_chunks=Float64(analysis_tail_chunk_count),
        analysis_discard_initial_chunks=Float64(discarded_initial_chunks),
        initial_state_mode=String(initial_state_mode),
        initial_state_outdir=initial_state_outdir === nothing ? "" : String(initial_state_outdir),
        chain_indices=join(Int.(chain_indices), ";"),
        profile_measure=String(resolved_profile_measure),
        profile_measure_power=Float64(profile_measure_power),
        profile_measure_log_floor=max(Float64(profile_measure_log_floor), floatmin(Float64)),
        A=params.A,
        B=params.B,
        C=params.C,
        local_potential_a1=params.local_potential_coeffs[1],
        local_potential_a2=params.local_potential_coeffs[2],
        local_potential_a3=params.local_potential_coeffs[3],
        lateral_gradient_coeff=params.lateral_gradient_coeff,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=aggregate_steps,
        chunk_steps=Int(chunk_steps),
        burnin_steps=aggregate_burnin_steps,
        first_burnin_steps=Int(first_burnin_steps),
        sample_stride=Int(sample_stride),
        proposals_per_sweep=proposals_per_sweep,
        total_sweeps=total_sweeps,
        production_sweeps=production_sweeps,
        burnin_sweeps=resolved_burnin_sweeps,
        sample_stride_sweeps=resolved_sample_stride_sweeps,
        chain_count=length(traces),
        requested_chain_count=maximum(Int.(chain_indices)),
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        pair_acceptance_rate=pair_accepted / max(pair_attempted, 1),
        plane_acceptance_rate=plane_accepted / max(plane_attempted, 1),
        global_acceptance_rate=global_accepted / max(global_attempted, 1),
        profile_mode_acceptance_rate=profile_mode_accepted / max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted / max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        pair_proposal_amplitude=mean(trace.pair_proposal_amplitude for trace in traces),
        plane_proposal_amplitude=mean(trace.plane_proposal_amplitude for trace in traces),
        global_field_amplitude=mean(trace.global_field_amplitude for trace in traces),
        profile_mode_amplitude=Float64(profile_mode_amplitude),
        profile_mode_count=max(1, Int(profile_mode_count)),
        reference_width_amplitude=mean(trace.reference_width_amplitude for trace in traces),
        reference_width_xi=Float64(reference_width_xi),
        tuning_acceptance_rate=mean(trace.tuning_acceptance_rate for trace in traces),
        tune_rounds=sum(trace.tune_rounds for trace in traces),
        tune_steps=traces[1].tune_steps,
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        profile_measure_log_jacobian_mean=profile_measure_log_jacobian_summary.mean,
        profile_measure_log_jacobian_stderr=profile_measure_log_jacobian_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        target_xi_eff=target,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        abs_xi_error=abs_xi_error,
        xi_tolerance=tol,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        target_profile_rmse=target_profile.rmse,
        target_profile_r2=target_profile.r2,
        target_profile_max_abs_error=target_profile.max_abs_error,
        target_profile_wall_rms=target_profile.wall_rms,
        observable_xi_eff=observable_convergence.observable_xi_eff,
        observable_abs_xi_error=observable_convergence.observable_abs_xi_error,
        observable_chain_xi_mean=observable_convergence.observable_chain_xi_mean,
        observable_chain_xi_sd=observable_convergence.observable_chain_xi_sd,
        observable_chain_xi_min=observable_convergence.observable_chain_xi_min,
        observable_chain_xi_max=observable_convergence.observable_chain_xi_max,
        observable_leave_one_chain_xi_min=observable_convergence.observable_leave_one_chain_xi_min,
        observable_leave_one_chain_xi_max=observable_convergence.observable_leave_one_chain_xi_max,
        observable_central_density_floor=observable_convergence.observable_central_density_floor,
        observable_central_bin_count=Float64(observable_convergence.observable_central_bin_count),
        observable_central_rhat_max=observable_convergence.observable_central_rhat_max,
        observable_central_split_rhat_max=observable_convergence.observable_central_split_rhat_max,
        observable_xi_pass=observable_convergence.observable_xi_pass,
        observable_chain_xi_pass=observable_convergence.observable_chain_xi_pass,
        observable_leave_one_chain_xi_pass=observable_convergence.observable_leave_one_chain_xi_pass,
        observable_target_profile_r2_pass=observable_convergence.observable_target_profile_r2_pass,
        observable_fit_quality_pass=observable_convergence.observable_fit_quality_pass,
        observable_block_drift_pass=observable_convergence.observable_block_drift_pass,
        observable_calibration_pass=observable_convergence.observable_calibration_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
        rhat_threshold=rhat_gate,
        r2_threshold=r2_gate,
        xi_block_drift_pass=xi_block_drift.block_drift_pass,
        xi_block_max_abs_start_end_delta=xi_block_drift.max_abs_start_end_delta,
        xi_block_max_abs_slope=xi_block_drift.max_abs_slope,
        xi_block_monotone_chain_fraction=xi_block_drift.monotone_chain_fraction,
        xi_block_min_block_count=Float64(xi_block_drift.min_block_count),
        xi_block_max_block_count=Float64(xi_block_drift.max_block_count),
        block_drift_tolerance=max(Float64(block_drift_tolerance), 0.0),
        calibration_pass=calibration_pass,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"),
        diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)
    summary_rows = [(
        profile_measure_power=Float64(profile_measure_power),
        profile_mode_amplitude=Float64(profile_mode_amplitude),
        profile_mode_count=Float64(profile_mode_count),
        profile_mode_move_weight=Float64(profile_mode_move_weight),
        reference_width_move_weight=Float64(reference_width_move_weight),
        reference_width_reflection_move_weight=Float64(reference_width_reflection_move_weight),
        reference_width_xi=Float64(reference_width_xi),
        target_xi_eff=target,
        target_source=String(target_source),
        xi_eff=xi_eff,
        abs_xi_error=abs_xi_error,
        xi_tolerance=tol,
        block_drift_tolerance=max(Float64(block_drift_tolerance), 0.0),
        calibration_pass=calibration_pass,
        xi_bulk=xi_bulk,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        r2_threshold=r2_gate,
        target_profile_rmse=target_profile.rmse,
        target_profile_r2=target_profile.r2,
        target_profile_max_abs_error=target_profile.max_abs_error,
        target_profile_wall_rms=target_profile.wall_rms,
        observable_xi_eff=observable_convergence.observable_xi_eff,
        observable_abs_xi_error=observable_convergence.observable_abs_xi_error,
        observable_chain_xi_mean=observable_convergence.observable_chain_xi_mean,
        observable_chain_xi_sd=observable_convergence.observable_chain_xi_sd,
        observable_chain_xi_min=observable_convergence.observable_chain_xi_min,
        observable_chain_xi_max=observable_convergence.observable_chain_xi_max,
        observable_leave_one_chain_xi_min=observable_convergence.observable_leave_one_chain_xi_min,
        observable_leave_one_chain_xi_max=observable_convergence.observable_leave_one_chain_xi_max,
        observable_central_density_floor=observable_convergence.observable_central_density_floor,
        observable_central_bin_count=Float64(observable_convergence.observable_central_bin_count),
        observable_central_rhat_max=observable_convergence.observable_central_rhat_max,
        observable_central_split_rhat_max=observable_convergence.observable_central_split_rhat_max,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        rhat_threshold=rhat_gate,
        xi_block_drift_pass=xi_block_drift.block_drift_pass,
        xi_block_max_abs_start_end_delta=xi_block_drift.max_abs_start_end_delta,
        xi_block_max_abs_slope=xi_block_drift.max_abs_slope,
        xi_block_monotone_chain_fraction=xi_block_drift.monotone_chain_fraction,
        xi_block_min_block_count=Float64(xi_block_drift.min_block_count),
        xi_block_max_block_count=Float64(xi_block_drift.max_block_count),
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        profile_mode_acceptance_rate=profile_mode_accepted / max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted / max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        sample_count=Float64(sample_count),
        chunk_count=Float64(chunk_count),
        min_chunk_count=Float64(min_chunk_count),
        max_chunk_count=Float64(max_chunk_count),
        completed_chunk_count=Float64(completed_chunk_count),
        min_completed_chunk_count=Float64(min_completed_chunk_count),
        max_completed_chunk_count=Float64(max_completed_chunk_count),
        analysis_tail_chunks=Float64(analysis_tail_chunk_count),
        analysis_discard_initial_chunks=Float64(discarded_initial_chunks),
        initial_state_mode=String(initial_state_mode),
        initial_state_outdir=initial_state_outdir === nothing ? "" : String(initial_state_outdir),
        chain_count=Float64(length(traces)),
        steps=Float64(aggregate_steps),
        chunk_steps=Float64(chunk_steps),
        burnin_steps=Float64(aggregate_burnin_steps),
        sample_stride=Float64(sample_stride),
        total_sweeps=total_sweeps,
        production_sweeps=production_sweeps,
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        lateral_variance_mean=lateral_variance_summary.mean,
        profile_measure_log_jacobian_mean=profile_measure_log_jacobian_summary.mean,
        run_outdir=outdir,
        profile_csv=profile_csv,
        diagnostics_csv=diagnostics_csv,
        profile_svg=profile_svg,
    )]
    summary_csv = _write_dataframe(joinpath(outdir, "measure_corrected_chunked_summary.csv"),
        summary_rows)
    manifest_path = _slit_3d_chunk_manifest_path(outdir)
    state_paths = [_slit_3d_chunk_state_path(outdir, idx) for idx in Int.(chain_indices)]
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_measure_corrected_chunked",
            "sampler" => "arianna_metropolis_measure_corrected_chunked",
            "seed" => Int(seed),
        ),
        "target" => Dict{String,Any}(
            "observable" => "AK Fig. 3 effective xi",
            "target_xi_eff" => target,
            "target_source" => String(target_source),
            "xi_tolerance" => tol,
            "rhat_threshold" => rhat_gate,
            "r2_threshold" => r2_gate,
            "block_drift_tolerance" => max(Float64(block_drift_tolerance), 0.0),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
            "volume" => grid.volume,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
            "local_potential_a1" => params.local_potential_coeffs[1],
            "local_potential_a2" => params.local_potential_coeffs[2],
            "local_potential_a3" => params.local_potential_coeffs[3],
            "initial_profile" => String(Symbol(initial_profile)),
        ),
        "sampling" => Dict{String,Any}(
            "chunked_sampler" => true,
            "chunk_count" => chunk_count,
            "min_chunk_count" => min_chunk_count,
            "max_chunk_count" => max_chunk_count,
            "completed_chunk_count" => completed_chunk_count,
            "min_completed_chunk_count" => min_completed_chunk_count,
            "max_completed_chunk_count" => max_completed_chunk_count,
            "analysis_tail_chunks" => analysis_tail_chunk_count,
            "analysis_discard_initial_chunks" => discarded_initial_chunks,
            "initial_state_mode" => String(initial_state_mode),
            "initial_state_outdir" => initial_state_outdir === nothing ? "" : String(initial_state_outdir),
            "chain_count" => length(traces),
            "chain_indices" => Int.(chain_indices),
            "chunk_steps" => Int(chunk_steps),
            "first_burnin_steps" => Int(first_burnin_steps),
            "sample_stride" => Int(sample_stride),
            "proposals_per_sweep" => proposals_per_sweep,
            "total_sweeps" => total_sweeps,
            "production_sweeps" => production_sweeps,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
            "profile_measure" => String(resolved_profile_measure),
            "profile_measure_power" => Float64(profile_measure_power),
            "profile_measure_log_floor" => max(Float64(profile_measure_log_floor), floatmin(Float64)),
            "profile_mode_amplitude" => Float64(profile_mode_amplitude),
            "profile_mode_count" => max(1, Int(profile_mode_count)),
            "profile_mode_move_weight" => Float64(profile_mode_move_weight),
            "reference_width_move_weight" => Float64(reference_width_move_weight),
            "reference_width_reflection_move_weight" => Float64(reference_width_reflection_move_weight),
            "reference_width_xi" => Float64(reference_width_xi),
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "reference_width_reflection_acceptance_rate" =>
                reference_width_reflection_accepted / max(reference_width_reflection_attempted, 1),
            "sample_count" => sample_count,
            "xi_eff" => xi_eff,
            "abs_xi_error" => abs_xi_error,
            "xi_fit_r2" => fit_diagnostics.r2,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
            "xi_block_drift_pass" => xi_block_drift.block_drift_pass,
            "xi_block_max_abs_start_end_delta" => xi_block_drift.max_abs_start_end_delta,
            "calibration_pass" => calibration_pass,
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "chunk_manifest_csv" => manifest_path,
            "chunk_trace_dir" => _slit_3d_chunk_trace_dir(outdir),
            "chunk_state_dir" => _slit_3d_chunk_state_dir(outdir),
        ),
        "environment" => _metadata_environment(),
    ))
    return (
        outdir=outdir,
        params=params,
        summary_csv=summary_csv,
        profile_csv=profile_csv,
        profile_blocks_csv=profile_blocks_csv,
        xi_blocks_csv=xi_blocks_csv,
        diagnostics_csv=diagnostics_csv,
        profile_svg=profile_svg,
        metadata_path=metadata_path,
        chunk_manifest_csv=manifest_path,
        final_state_paths=state_paths,
        chunk_count=chunk_count,
        min_chunk_count=min_chunk_count,
        max_chunk_count=max_chunk_count,
        completed_chunk_count=completed_chunk_count,
        min_completed_chunk_count=min_completed_chunk_count,
        max_completed_chunk_count=max_completed_chunk_count,
        analysis_tail_chunks=analysis_tail_chunk_count,
        analysis_discard_initial_chunks=discarded_initial_chunks,
        chain_count=length(traces),
        sample_count=sample_count,
        xi_eff=xi_eff,
        abs_xi_error=abs_xi_error,
        calibration_pass=calibration_pass,
    )
end

function run_slit_3d_measure_corrected_chunk!(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    target_xi_eff::Real=0.34956193172308436,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL points digitized from Fig. 4-consistent local rendering",
    profile_measure_power::Real=0.999,
    profile_measure_log_floor::Real=1.0e-300,
    profile_mode_amplitude::Real=1.0e-4,
    profile_mode_count::Integer=4,
    xi_tolerance::Real=0.03,
    rhat_threshold::Real=1.25,
    r2_threshold::Real=0.995,
    block_drift_tolerance::Real=0.03,
    chunk_steps::Integer=512_000,
    first_burnin_steps::Integer=128_000,
    sample_stride::Integer=16_000,
    chunk_sweeps=nothing,
    first_burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=4,
    chain_indices=nothing,
    parallel_chains::Bool=false,
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
    symmetrize_profile::Bool=true,
    initial_pair_amplitude::Real=0.01,
    initial_plane_amplitude::Real=0.001,
    initial_global_amplitude::Real=0.0002,
    initial_reference_width_amplitude::Real=1.0e-3,
    pair_move_weight::Real=0.10,
    plane_move_weight::Real=0.05,
    global_move_weight::Real=0.05,
    profile_mode_move_weight::Real=0.20,
    reference_width_move_weight::Real=0.60,
    reference_width_reflection_move_weight::Real=0.0,
    reference_width_xi::Real=0.0,
    tune_rounds::Integer=0,
    tune_steps::Integer=200,
    target_acceptance::Real=0.44,
    phi_min::Real=1.0e-10,
    profile_measure=:flat_profile,
    seed::Integer=260625,
    initial_profile=:eq22,
    initial_state_outdir=nothing,
)
    mkpath(outdir)
    mkpath(_slit_3d_chunk_trace_dir(outdir))
    mkpath(_slit_3d_chunk_state_dir(outdir))
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) : target
    saddle_phi = _slit_3d_measure_corrected_saddle_profile(grid, params, initial_profile,
        resolved_reference_width_xi)
    base_field = slit_3d_field_from_profile(saddle_phi, grid)
    initial_state_mode = initial_state_outdir === nothing ?
                         "saddle_profile" : "external_chunk_state"
    resolved_steps = chunk_sweeps === nothing ? max(1, Int(chunk_steps)) :
                     _steps_from_sweeps(grid, chunk_sweeps)
    resolved_first_burnin_steps = first_burnin_sweeps === nothing ?
                                  max(0, Int(first_burnin_steps)) :
                                  max(0, ceil(Int,
                                      Float64(first_burnin_sweeps) *
                                      _proposals_per_sweep(grid)))
    resolved_sample_stride = sample_stride_sweeps === nothing ?
                             max(1, Int(sample_stride)) :
                             max(1, ceil(Int,
                                 Float64(sample_stride_sweeps) *
                                 _proposals_per_sweep(grid)))
    selected_chain_indices = _slit_3d_select_chain_indices(chain_indices, chains)
    manifest_path = _slit_3d_chunk_manifest_path(outdir)
    manifest_header = [
        "chain",
        "chunk",
        "seed",
        "steps",
        "burnin_steps",
        "sample_stride",
        "sample_count",
        "accepted_moves",
        "attempted_moves",
        "acceptance_rate",
        "trace_path",
        "state_path",
    ]
    for chain_idx in selected_chain_indices
        next_chunk = _slit_3d_next_chunk_index(manifest_path, chain_idx)
        state_path = _slit_3d_chunk_state_path(outdir, chain_idx)
        if next_chunk > 1 && !isfile(state_path)
            throw(ArgumentError("missing chunk state for chain $(chain_idx): $(state_path)"))
        elseif next_chunk == 1 && isfile(state_path)
            throw(ArgumentError("state exists for chain $(chain_idx) but manifest has no completed chunk"))
        end
        initial_field = if next_chunk == 1 && initial_state_outdir !== nothing
            source_state_path = _slit_3d_chunk_state_path(String(initial_state_outdir), chain_idx)
            isfile(source_state_path) ||
                throw(ArgumentError("missing initial state for chain $(chain_idx): $(source_state_path)"))
            _deserialize_jls(source_state_path)
        elseif next_chunk == 1
            copy(base_field)
        else
            _deserialize_jls(state_path)
        end
        _slit_3d_validate_phi(initial_field, grid)
        burn = next_chunk == 1 ? resolved_first_burnin_steps : 0
        chunk_tune_rounds = next_chunk == 1 ? Int(tune_rounds) : 0
        chunk_seed = Int(seed) + 100_000 * (chain_idx - 1) + 1_000 * (next_chunk - 1)
        trace = _run_slit_3d_arianna_trace(
            grid,
            params,
            initial_field;
            steps=resolved_steps,
            burnin_steps=burn,
            sample_stride=resolved_sample_stride,
            pair_amplitude=initial_pair_amplitude,
            plane_amplitude=initial_plane_amplitude,
            global_amplitude=initial_global_amplitude,
            profile_mode_amplitude=profile_mode_amplitude,
            profile_mode_count=profile_mode_count,
            reference_width_amplitude=initial_reference_width_amplitude,
            reference_width_xi=resolved_reference_width_xi,
            pair_weight=pair_move_weight,
            plane_weight=plane_move_weight,
            global_weight=global_move_weight,
            profile_mode_weight=profile_mode_move_weight,
            reference_width_weight=reference_width_move_weight,
            reference_width_reflection_weight=reference_width_reflection_move_weight,
            tune_rounds=chunk_tune_rounds,
            tune_steps=tune_steps,
            target_acceptance=target_acceptance,
            phi_min=phi_min,
            profile_measure=profile_measure,
            profile_measure_power=profile_measure_power,
            profile_measure_log_floor=profile_measure_log_floor,
            seed=chunk_seed,
        )
        trace_path = _slit_3d_chunk_trace_path(outdir, chain_idx, next_chunk)
        _serialize_jls(trace_path, trace)
        _serialize_jls(state_path, trace.final_phi)
        _append_table_row(manifest_path, manifest_header, [
            chain_idx,
            next_chunk,
            chunk_seed,
            trace.steps,
            trace.burnin_steps,
            trace.sample_stride,
            trace.sample_count,
            trace.accepted_moves,
            trace.attempted_moves,
            trace.acceptance_rate,
            trace_path,
            state_path,
        ])
    end
    loaded = _load_slit_3d_chunk_traces(manifest_path, max(1, Int(chains));
        analysis_tail_chunks=analysis_tail_chunks,
        analysis_discard_initial_chunks=analysis_discard_initial_chunks)
    return _finalize_slit_3d_measure_corrected_chunks(
        outdir,
        grid,
        params,
        saddle_phi,
        loaded.traces,
        loaded.chain_indices,
        loaded.chunk_counts;
        completed_chunk_counts=loaded.completed_chunk_counts,
        analysis_tail_chunks=analysis_tail_chunks,
        analysis_discard_initial_chunks=analysis_discard_initial_chunks,
        target_xi_eff=target,
        target_source=target_source,
        xi_tolerance=xi_tolerance,
        rhat_threshold=rhat_threshold,
        r2_threshold=r2_threshold,
        block_drift_tolerance=block_drift_tolerance,
        symmetrize_profile=symmetrize_profile,
        profile_measure=profile_measure,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor,
        profile_mode_amplitude=profile_mode_amplitude,
        profile_mode_count=profile_mode_count,
        profile_mode_move_weight=profile_mode_move_weight,
        reference_width_move_weight=reference_width_move_weight,
        reference_width_reflection_move_weight=reference_width_reflection_move_weight,
        reference_width_xi=resolved_reference_width_xi,
        initial_profile=initial_profile,
        initial_state_outdir=initial_state_outdir,
        initial_state_mode=initial_state_mode,
        seed=seed,
        chunk_steps=resolved_steps,
        first_burnin_steps=resolved_first_burnin_steps,
        sample_stride=resolved_sample_stride)
end

function run_slit_3d_measure_corrected_scan(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    target_xi_eff::Real=0.3270559793,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL points digitized from the local PDF rendering",
    profile_measure_powers=[1.0, 1.0001, 1.0002, 1.0003],
    profile_mode_amplitudes=[5.0e-5, 1.0e-4, 2.0e-4],
    profile_mode_count::Integer=4,
    xi_tolerance::Real=0.03,
    rhat_threshold::Real=1.25,
    r2_threshold::Real=0.995,
    block_drift_tolerance::Real=0.03,
    steps::Integer=512_000,
    burnin_steps::Integer=128_000,
    sample_stride::Integer=16_000,
    sweeps=nothing,
    burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=4,
    parallel_chains::Bool=false,
    symmetrize_profile::Bool=true,
    initial_pair_amplitude::Real=0.01,
    initial_plane_amplitude::Real=0.001,
    initial_global_amplitude::Real=0.0002,
    initial_reference_width_amplitude::Real=1.0e-3,
    pair_move_weight::Real=0.10,
    plane_move_weight::Real=0.05,
    global_move_weight::Real=0.05,
    profile_mode_move_weight::Real=0.20,
    reference_width_move_weight::Real=0.60,
    reference_width_reflection_move_weight::Real=0.0,
    reference_width_xi::Real=0.0,
    tune_rounds::Integer=0,
    tune_steps::Integer=200,
    seed::Integer=260625,
)
    mkpath(outdir)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    powers = Float64.(collect(profile_measure_powers))
    amplitudes = Float64.(collect(profile_mode_amplitudes))
    isempty(powers) && throw(ArgumentError("profile_measure_powers must contain at least one value"))
    isempty(amplitudes) && throw(ArgumentError("profile_mode_amplitudes must contain at least one value"))
    all(isfinite, powers) || throw(ArgumentError("all profile_measure_powers must be finite"))
    all(amp -> isfinite(amp) && amp > 0.0, amplitudes) ||
        throw(ArgumentError("all profile_mode_amplitudes must be positive"))
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    r2_gate = Float64(r2_threshold)
    drift_gate = max(Float64(block_drift_tolerance), 0.0)
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) : target
    raw_rows = NamedTuple[]
    results = Slit3DMCResult[]
    run_index = 0
    for power in powers, amplitude in amplitudes
        run_index += 1
        run_outdir = joinpath(outdir, _measure_corrected_scan_label(power, amplitude))
        result = run_slit_3d_vk1_mc(run_outdir;
            Nx=Nx, Ny=Ny, Nz=Nz, Lxy=Lxy, Lz=Lz, B=B, C=C, A=A, alpha=alpha,
            steps=steps, burnin_steps=burnin_steps, sample_stride=sample_stride,
            sweeps=sweeps, burnin_sweeps=burnin_sweeps,
            sample_stride_sweeps=sample_stride_sweeps, chains=chains,
            parallel_chains=parallel_chains,
            symmetrize_profile=symmetrize_profile,
            initial_pair_amplitude=initial_pair_amplitude,
            initial_plane_amplitude=initial_plane_amplitude,
            initial_global_amplitude=initial_global_amplitude,
            initial_profile_mode_amplitude=amplitude,
            initial_reference_width_amplitude=initial_reference_width_amplitude,
            pair_move_weight=pair_move_weight,
            plane_move_weight=plane_move_weight,
            global_move_weight=global_move_weight,
            profile_mode_move_weight=profile_mode_move_weight,
            reference_width_move_weight=reference_width_move_weight,
            reference_width_reflection_move_weight=reference_width_reflection_move_weight,
            profile_mode_count=profile_mode_count,
            reference_width_xi=resolved_reference_width_xi,
            tune_rounds=tune_rounds, tune_steps=tune_steps,
            profile_measure=:flat_profile,
            profile_measure_power=power,
            seed=Int(seed) + 10_000 * (run_index - 1))
        push!(results, result)
        abs_xi_error = abs(result.xi_eff - target)
        target_phi = slit_reference_profile(result.grid.z; B=B, C=C, L=result.grid.Lz, xi=target)
        target_profile = _slit_profile_fit_diagnostics(result.mean_phi, target_phi)
        rhat_ok = isfinite(result.profile_chain_rhat_max) ? result.profile_chain_rhat_max <= rhat_gate : result.chain_count == 1
        split_rhat_ok = isfinite(result.profile_split_rhat_max) ? result.profile_split_rhat_max <= rhat_gate : result.chain_count == 1
        r2_ok = isfinite(result.xi_fit_r2) && result.xi_fit_r2 >= r2_gate
        xi_block_drift = _slit_xi_block_drift_diagnostics(
            joinpath(run_outdir, "slit_3d_mc_xi_blocks.csv");
            drift_tolerance=drift_gate)
        drift_ok = xi_block_drift.block_drift_pass == 1.0
        calibration_pass = (abs_xi_error <= tol && r2_ok &&
                            result.xi_fit_quality_pass == 1.0 &&
                            rhat_ok && split_rhat_ok && drift_ok) ? 1.0 : 0.0
        push!(raw_rows, (
            profile_measure_power=power,
            profile_mode_amplitude=amplitude,
            profile_mode_count=Float64(profile_mode_count),
            profile_mode_move_weight=Float64(profile_mode_move_weight),
            reference_width_move_weight=Float64(reference_width_move_weight),
            reference_width_reflection_move_weight=Float64(reference_width_reflection_move_weight),
            reference_width_xi=resolved_reference_width_xi,
            target_xi_eff=target,
            target_source=String(target_source),
            xi_eff=result.xi_eff,
            abs_xi_error=abs_xi_error,
            xi_tolerance=tol,
            block_drift_tolerance=drift_gate,
            calibration_pass=calibration_pass,
            xi_bulk=result.xi_bulk,
            xi_fit_rmse=result.xi_fit_rmse,
            xi_fit_r2=result.xi_fit_r2,
            xi_fit_quality_pass=result.xi_fit_quality_pass,
            r2_threshold=r2_gate,
            target_profile_rmse=target_profile.rmse,
            target_profile_r2=target_profile.r2,
            target_profile_max_abs_error=target_profile.max_abs_error,
            target_profile_wall_rms=target_profile.wall_rms,
            profile_chain_rhat_max=result.profile_chain_rhat_max,
            profile_split_rhat_max=result.profile_split_rhat_max,
            rhat_threshold=rhat_gate,
            xi_block_drift_pass=xi_block_drift.block_drift_pass,
            xi_block_max_abs_start_end_delta=xi_block_drift.max_abs_start_end_delta,
            xi_block_max_abs_slope=xi_block_drift.max_abs_slope,
            xi_block_monotone_chain_fraction=xi_block_drift.monotone_chain_fraction,
            xi_block_min_block_count=Float64(xi_block_drift.min_block_count),
            xi_block_max_block_count=Float64(xi_block_drift.max_block_count),
            acceptance_rate=result.acceptance_rate,
            profile_mode_acceptance_rate=_diagnostic_value(result.diagnostics_csv, "profile_mode_acceptance_rate"),
            reference_width_acceptance_rate=_diagnostic_value(result.diagnostics_csv, "reference_width_acceptance_rate"),
            reference_width_reflection_acceptance_rate=_diagnostic_value(result.diagnostics_csv,
                "reference_width_reflection_acceptance_rate"),
            reference_width_amplitude=_diagnostic_value(result.diagnostics_csv, "reference_width_amplitude"),
            sample_count=Float64(result.sample_count),
            steps=Float64(result.steps),
            burnin_steps=Float64(result.burnin_steps),
            sample_stride=Float64(result.sample_stride),
            total_sweeps=result.total_sweeps,
            production_sweeps=result.production_sweeps,
            chain_count=Float64(result.chain_count),
            parallel_chains=Bool(parallel_chains),
            energy_mean=result.energy_mean,
            energy_stderr=result.energy_stderr,
            density_variance_mean=result.density_variance_mean,
            lateral_variance_mean=result.lateral_variance_mean,
            profile_measure_log_jacobian_mean=_diagnostic_value(result.diagnostics_csv, "profile_measure_log_jacobian_mean"),
            run_outdir=run_outdir,
            profile_csv=result.profile_csv,
            diagnostics_csv=result.diagnostics_csv,
            profile_svg=result.profile_svg,
        ))
    end
    order = sortperm(eachindex(raw_rows); by=i -> (
        raw_rows[i].calibration_pass == 1.0 ? 0 : 1,
        raw_rows[i].abs_xi_error,
        isfinite(raw_rows[i].profile_split_rhat_max) ? raw_rows[i].profile_split_rhat_max : Inf,
        raw_rows[i].profile_measure_power,
        raw_rows[i].profile_mode_amplitude,
    ))
    rank_by_idx = fill(0, length(raw_rows))
    for (rank, idx) in enumerate(order)
        rank_by_idx[idx] = rank
    end
    scan_rows = [merge(raw_rows[i], (selection_rank=rank_by_idx[i],)) for i in eachindex(raw_rows)]
    summary_csv = _write_dataframe(joinpath(outdir, "measure_corrected_scan.csv"), scan_rows)
    scan_svg = _write_slit_3d_measure_corrected_scan_svg(summary_csv, outdir)
    best_idx = order[1]
    best_row = scan_rows[best_idx]
    best_result = results[best_idx]
    markdown_path = _write_slit_3d_measure_corrected_scan_text(outdir, scan_rows, best_row, target_source)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_measure_corrected_scan",
            "sampler" => "arianna_metropolis_measure_corrected",
            "seed" => Int(seed),
        ),
        "target" => Dict{String,Any}(
            "observable" => "AK Fig. 3 effective xi",
            "target_xi_eff" => target,
            "target_source" => String(target_source),
            "xi_tolerance" => tol,
            "rhat_threshold" => rhat_gate,
            "r2_threshold" => r2_gate,
            "block_drift_tolerance" => drift_gate,
        ),
        "grid" => Dict{String,Any}(
            "Nx" => Int(Nx),
            "Ny" => Int(Ny),
            "Nz" => Int(Nz),
            "Lxy" => Float64(Lxy),
            "Lz" => Float64(Lz),
        ),
        "parameters" => Dict{String,Any}(
            "A" => Float64(A),
            "B" => Float64(B),
            "C" => Float64(C),
            "alpha" => Float64(alpha),
            "model" => "HE-VK1",
        ),
        "scan" => Dict{String,Any}(
            "profile_measure" => "flat_profile",
            "profile_measure_powers" => powers,
            "profile_mode_amplitudes" => amplitudes,
            "profile_mode_count" => Int(profile_mode_count),
            "profile_mode_move_weight" => Float64(profile_mode_move_weight),
            "reference_width_move_weight" => Float64(reference_width_move_weight),
            "reference_width_reflection_move_weight" => Float64(reference_width_reflection_move_weight),
            "reference_width_xi" => resolved_reference_width_xi,
            "initial_reference_width_amplitude" => Float64(initial_reference_width_amplitude),
            "steps" => Int(steps),
            "burnin_steps" => Int(burnin_steps),
            "sample_stride" => Int(sample_stride),
            "sweeps" => sweeps === nothing ? "nothing" : Float64(sweeps),
            "burnin_sweeps" => burnin_sweeps === nothing ? "nothing" : Float64(burnin_sweeps),
            "sample_stride_sweeps" => sample_stride_sweeps === nothing ? "nothing" : Float64(sample_stride_sweeps),
            "chains" => Int(chains),
            "parallel_chains" => Bool(parallel_chains),
        ),
        "best" => Dict{String,Any}(
            "profile_measure_power" => best_row.profile_measure_power,
            "profile_mode_amplitude" => best_row.profile_mode_amplitude,
            "xi_eff" => best_row.xi_eff,
            "abs_xi_error" => best_row.abs_xi_error,
            "calibration_pass" => best_row.calibration_pass,
            "profile_csv" => best_result.profile_csv,
            "diagnostics_csv" => best_result.diagnostics_csv,
            "profile_svg" => best_result.profile_svg,
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "scan_svg" => scan_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMeasureCorrectedScanResult(
        summary_csv,
        scan_svg,
        markdown_path,
        metadata_path,
        best_row.run_outdir,
        best_result.profile_csv,
        best_result.diagnostics_csv,
        best_result.profile_svg,
        best_row.profile_measure_power,
        best_row.profile_mode_amplitude,
        best_row.xi_eff,
        best_row.abs_xi_error,
        best_row.calibration_pass,
        target,
        length(scan_rows),
    )
end

function dfm_pressure(A::Real, B::Real, C::Real)
    Af, Bf, Cf = Float64.((A, B, C))
    radicand = 2.0 * Bf * Cf - 2.0 * Af / Cf
    radicand < 0.0 && throw(DomainError(radicand, "DFM pressure requires 2BC - 2A/C >= 0"))
    return Cf + 0.5 * Bf * Cf^2 -
           (1.0 / (24.0 * pi)) * (2.0 * Bf * Cf + 10.0 * Af / Cf) * sqrt(radicand)
end

function dfm_pressure_smeared(A::Real, B::Real, C::Real; alpha=0.1, n=1001, kmax=100.0)
    Af, Bf, Cf = Float64.((A, B, C))
    α = Float64(alpha)
    kmin = sqrt(2.0 * Af / Cf)
    kmin >= kmax && throw(DomainError(kmin, "DFM integration requires kmin < kmax"))
    step = (kmax - kmin) / (n - 1)
    integral = 0.0
    for idx in 1:n
        k = kmin + (idx - 1) * step
        x = k^2
        gD = debye(x)
        smear = exp(-α^2 * x)
        BCgDs = Bf * Cf * gD * smear
        ACgDs = Af / Cf * gD * smear
        y = BCgDs / (1.0 - ACgDs)
        z = (1.0 - 2.0 * ACgDs) / (1.0 - ACgDs)
        value = x * (log(1.0 + y) - y / (1.0 + y) * z)
        weight = (idx == 1 || idx == n) ? 0.5 : 1.0
        integral += weight * value
    end
    return Cf + 0.5 * Bf * Cf^2 - 0.25 * step * integral / pi^2
end

mean_field_pressure(B::Real, C::Real) = Float64(C) + 0.5 * Float64(B) * Float64(C)^2

function _dfm_pressure_mode_contributions(params::HEURPParams, grid::Grid3D)
    contributions = Float64[]
    for term in _dfm_pressure_mode_terms(params, grid)
        push!(contributions, term.mean_contribution)
    end
    return contributions
end

function _dfm_pressure_mode_terms(params::HEURPParams, grid::Grid3D)
    Af, Bf, Cf = params.A, params.B, params.C
    α = params.alpha
    kmin2 = 2.0 * Af / Cf
    terms = NamedTuple{(:log1py,:yz,:precision,:mean_contribution),NTuple{4,Float64}}[]
    for k2 in vec(wavenumber_squared(grid))
        (k2 == 0.0 || k2 < kmin2) && continue
        gD = debye(k2)
        smear = exp(-α^2 * k2)
        BCgDs = Bf * Cf * gD * smear
        ACgDs = Af / Cf * gD * smear
        denominator = 1.0 - ACgDs
        denominator <= 0.0 && continue
        y = BCgDs / denominator
        z = (1.0 - 2.0 * ACgDs) / denominator
        precision = 1.0 + y
        log1py = log1p(y)
        mean_contribution = -0.5 * (log1py - y / precision * z) / grid.volume
        push!(terms, (
            log1py=log1py,
            yz=y * z,
            precision=precision,
            mean_contribution=mean_contribution,
        ))
    end
    return terms
end

function dfm_pressure_discrete(A::Real, B::Real, C::Real, grid::Grid3D; alpha=0.1)
    params = HEURPParams(A=A, B=B, C=C, alpha=alpha)
    return mean_field_pressure(B, C) + sum(_dfm_pressure_mode_contributions(params, grid))
end

function one_loop_pressure_smeared(B::Real, C::Real; alpha=0.1, n=1001, kmax=100.0)
    Bf, Cf = Float64.((B, C))
    α = Float64(alpha)
    step = Float64(kmax) / (n - 1)
    integral = 0.0
    for idx in 1:n
        k = (idx - 1) * step
        x = k^2
        gD = debye(x)
        smear = exp(-α^2 * x)
        BCgDs = Bf * Cf * gD * smear
        value = x * (log(1.0 + BCgDs) - BCgDs / (1.0 + BCgDs))
        weight = (idx == 1 || idx == n) ? 0.5 : 1.0
        integral += weight * value
    end
    return mean_field_pressure(Bf, Cf) - 0.25 * step * integral / pi^2
end

function _safe_dfm_pressure(A, B, C; alpha=0.1)
    try
        return dfm_pressure_smeared(A, B, C; alpha=alpha)
    catch
        return NaN
    end
end

function _k_component(i::Int, Nx::Int, L::Float64)
    n = i <= fld(Nx, 2) + 1 ? i - 1 : i - 1 - Nx
    return 2.0 * pi * n / L
end

function wavenumber_squared(grid::Grid3D)
    out = Array{Float64}(undef, grid.Nx, grid.Nx, grid.Nx)
    for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
        kx = _k_component(i, grid.Nx, grid.L)
        ky = _k_component(j, grid.Nx, grid.L)
        kz = _k_component(k, grid.Nx, grid.L)
        out[i, j, k] = kx^2 + ky^2 + kz^2
    end
    return out
end

function _discrete_mode_index(i::Int, n::Int)
    return i <= fld(n, 2) + 1 ? i - 1 : i - 1 - n
end

function low_mode_structure_factor(phi::AbstractArray{<:Real,3})
    nx, ny, nz = size(phi)
    nx == ny == nz || throw(DimensionMismatch("low-mode structure factor requires a cubic 3D field"))
    nx <= 1 && return 0.0
    delta = Float64.(phi) .- mean(phi)
    delta_hat = fft(delta)
    min_q2 = typemax(Int)
    shell_sum = 0.0
    shell_count = 0
    scale = Float64(length(phi))^2
    for i in 1:nx, j in 1:ny, k in 1:nz
        qx = _discrete_mode_index(i, nx)
        qy = _discrete_mode_index(j, ny)
        qz = _discrete_mode_index(k, nz)
        q2 = qx^2 + qy^2 + qz^2
        q2 == 0 && continue
        if q2 < min_q2
            min_q2 = q2
            shell_sum = abs2(delta_hat[i, j, k])
            shell_count = 1
        elseif q2 == min_q2
            shell_sum += abs2(delta_hat[i, j, k])
            shell_count += 1
        end
    end
    shell_count == 0 && return 0.0
    return shell_sum / (scale * shell_count)
end

function _dft3(field::AbstractArray{<:Real,3})
    nx, ny, nz = size(field)
    out = Array{ComplexF64}(undef, nx, ny, nz)
    for p in 0:nx-1, q in 0:ny-1, r in 0:nz-1
        total = 0.0 + 0.0im
        for x in 0:nx-1, y in 0:ny-1, z in 0:nz-1
            angle = -2.0 * pi * (p * x / nx + q * y / ny + r * z / nz)
            total += field[x + 1, y + 1, z + 1] * cis(angle)
        end
        out[p + 1, q + 1, r + 1] = total
    end
    return out
end

function _validate_phi(phi)
    minimum(phi) <= 0.0 && throw(DomainError(minimum(phi), "density field must be strictly positive"))
    return nothing
end

function _spectral_discretization_prefactor(grid::Grid3D)
    M = grid.Nx^3
    return grid.volume / M^2
end

function _regularized_debye(k2::Real, params::HEURPParams)
    value = debye(k2) * exp(-params.alpha^2 * Float64(k2))
    return max(value, floatmin(Float64))
end

function _heurp_spectral_coefficient(k2::Real, params::HEURPParams)
    return params.C / _regularized_debye(k2, params) - params.A
end

function heurp_energy(phi::AbstractArray{<:Real,3}, grid::Grid3D, params::HEURPParams)
    size(phi) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("phi shape must match grid"))
    _validate_phi(phi)
    M = length(phi)
    cell = grid.volume / M
    real_term = 0.5 * params.B * params.C^2 * cell * sum(abs2, phi)
    delta_hat = _dft3(phi .- 1.0)
    log_hat = _dft3(log.(phi))
    k2 = wavenumber_squared(grid)
    spectral = 0.0 + 0.0im
    for idx in eachindex(k2)
        coefficient = _heurp_spectral_coefficient(k2[idx], params)
        spectral += coefficient * conj(delta_hat[idx]) * log_hat[idx]
    end
    return real(real_term + spectral * _spectral_discretization_prefactor(grid))
end

function _heurp_energy_fft(phi::AbstractArray{<:Real,3}, grid::Grid3D, params::HEURPParams)
    size(phi) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("phi shape must match grid"))
    _validate_phi(phi)
    M = length(phi)
    cell = grid.volume / M
    real_term = 0.5 * params.B * params.C^2 * cell * sum(abs2, phi)
    delta_hat = fft(phi .- 1.0)
    log_hat = fft(log.(phi))
    k2 = wavenumber_squared(grid)
    spectral = 0.0 + 0.0im
    for idx in eachindex(k2)
        coefficient = _heurp_spectral_coefficient(k2[idx], params)
        spectral += coefficient * conj(delta_hat[idx]) * log_hat[idx]
    end
    return real(real_term + spectral * _spectral_discretization_prefactor(grid))
end

function _sparse_density_entries(phi::AbstractArray{<:Real,3}; atol=1.0e-14)
    entries = Tuple{Int,Int,Int,Float64,Float64}[]
    nx, ny, nz = size(phi)
    for i in 1:nx, j in 1:ny, k in 1:nz
        δ = Float64(phi[i, j, k]) - 1.0
        if abs(δ) > atol
            push!(entries, (i - 1, j - 1, k - 1, δ, log(Float64(phi[i, j, k]))))
        end
    end
    return entries
end

function _sparse_spectral_term(entries, grid::Grid3D, params::HEURPParams)
    isempty(entries) && return 0.0
    nx = grid.Nx
    spectral = 0.0 + 0.0im
    for a in 1:nx, b in 1:nx, c in 1:nx
        ka = _k_component(a, nx, grid.L)
        kb = _k_component(b, nx, grid.L)
        kc = _k_component(c, nx, grid.L)
        coefficient = _heurp_spectral_coefficient(ka^2 + kb^2 + kc^2, params)
        delta_hat = 0.0 + 0.0im
        log_hat = 0.0 + 0.0im
        for (i, j, k, δ, logφ) in entries
            angle = -(ka * (i * grid.dx) + kb * (j * grid.dx) + kc * (k * grid.dx))
            phase = cis(angle)
            delta_hat += δ * phase
            log_hat += logφ * phase
        end
        spectral += coefficient * conj(delta_hat) * log_hat
    end
    return real(spectral * _spectral_discretization_prefactor(grid))
end

function _heurp_energy_sparse(phi::AbstractArray{<:Real,3}, grid::Grid3D, params::HEURPParams)
    size(phi) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("phi shape must match grid"))
    _validate_phi(phi)
    M = length(phi)
    cell = grid.volume / M
    real_term = 0.5 * params.B * params.C^2 * cell * sum(abs2, phi)
    return real_term + _sparse_spectral_term(_sparse_density_entries(phi), grid, params)
end

_energy_backend(grid::Grid3D) = grid.Nx >= 8 ? :fft : :dense

function _heurp_energy_adaptive(phi::AbstractArray{<:Real,3}, grid::Grid3D, params::HEURPParams)
    return _energy_backend(grid) == :fft ? _heurp_energy_fft(phi, grid, params) : heurp_energy(phi, grid, params)
end

_periodic_prev(i::Integer, n::Integer) = i == 1 ? Int(n) : Int(i) - 1
_periodic_next(i::Integer, n::Integer) = i == n ? 1 : Int(i) + 1

function _central_gradient_squared(field::AbstractArray{<:Real,3}, grid::Grid3D)
    size(field) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("field shape must match grid"))
    out = Array{Float64}(undef, size(field))
    inv_2dx = 1.0 / (2.0 * grid.dx)
    for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
        im, ip = _periodic_prev(i, grid.Nx), _periodic_next(i, grid.Nx)
        jm, jp = _periodic_prev(j, grid.Nx), _periodic_next(j, grid.Nx)
        km, kp = _periodic_prev(k, grid.Nx), _periodic_next(k, grid.Nx)
        gx = (Float64(field[ip, j, k]) - Float64(field[im, j, k])) * inv_2dx
        gy = (Float64(field[i, jp, k]) - Float64(field[i, jm, k])) * inv_2dx
        gz = (Float64(field[i, j, kp]) - Float64(field[i, j, km])) * inv_2dx
        out[i, j, k] = gx^2 + gy^2 + gz^2
    end
    return out
end

function _periodic_laplacian(field::AbstractArray{<:Real,3}, grid::Grid3D)
    size(field) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("field shape must match grid"))
    out = Array{Float64}(undef, size(field))
    inv_dx2 = 1.0 / grid.dx^2
    for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
        im, ip = _periodic_prev(i, grid.Nx), _periodic_next(i, grid.Nx)
        jm, jp = _periodic_prev(j, grid.Nx), _periodic_next(j, grid.Nx)
        km, kp = _periodic_prev(k, grid.Nx), _periodic_next(k, grid.Nx)
        out[i, j, k] = (
            Float64(field[ip, j, k]) + Float64(field[im, j, k]) +
            Float64(field[i, jp, k]) + Float64(field[i, jm, k]) +
            Float64(field[i, j, kp]) + Float64(field[i, j, km]) -
            6.0 * Float64(field[i, j, k])
        ) * inv_dx2
    end
    return out
end

function _vk1_coefficient_field(phi::AbstractArray{<:Real,3}, grid::Grid3D; log_floor=1.0e-12)
    size(phi) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("phi shape must match grid"))
    _validate_phi(phi)
    floor_value = max(Float64(log_floor), eps(Float64))
    log_phi = log.(Float64.(phi))
    grad_log_sq = _central_gradient_squared(log_phi, grid)
    lap_log = _periodic_laplacian(log_phi, grid)
    out = Array{Float64}(undef, size(phi))
    for idx in eachindex(phi)
        denominator = max(abs(log_phi[idx]), floor_value)
        g = 0.046 * (2.0 * abs(lap_log[idx]) / denominator + grad_log_sq[idx] / denominator^2)
        out[idx] = 1.0 / 6.0 + tanh(g) / 12.0
    end
    return out
end

function hevk1_energy(phi::AbstractArray{<:Real,3}, grid::Grid3D, params::HEURPParams)
    size(phi) == (grid.Nx, grid.Nx, grid.Nx) || throw(DimensionMismatch("phi shape must match grid"))
    _validate_phi(phi)
    phi64 = Float64.(phi)
    M = length(phi64)
    cell = grid.volume / M
    real_term = 0.5 * params.B * params.C^2 * cell * sum(abs2, phi64)
    k1 = _vk1_coefficient_field(phi64, grid)
    grad_phi_sq = _central_gradient_squared(phi64, grid)
    gradient_term = params.C * cell * sum(k1[idx] * grad_phi_sq[idx] / phi64[idx] for idx in eachindex(phi64))
    entropy_term = (params.C - params.A) * cell * sum(phi64[idx] * log(phi64[idx]) for idx in eachindex(phi64))
    return real_term + gradient_term + entropy_term
end

function pair_conserving_proposal(rng::AbstractRNG, phi::Array{Float64,3}, amplitude::Real; phi_min=1.0e-8)
    proposed = copy(phi)
    n = length(phi)
    i = rand(rng, 1:n)
    j = rand(rng, 1:n)
    while j == i
        j = rand(rng, 1:n)
    end
    delta = (2.0 * rand(rng) - 1.0) * Float64(amplitude)
    proposed[i] += delta
    proposed[j] -= delta
    ok = proposed[i] > phi_min && proposed[j] > phi_min
    return ok ? proposed : phi, ok
end

function fourier_mode_proposal(rng::AbstractRNG, phi::Array{Float64,3}, amplitude::Real; phi_min=1.0e-8)
    nx = size(phi, 1)
    ax, ay, az = rand(rng, 1:2), rand(rng, 1:2), rand(rng, 1:2)
    phase = 2.0 * pi * rand(rng)
    proposed = copy(phi)
    for i in 1:nx, j in 1:nx, k in 1:nx
        proposed[i, j, k] += Float64(amplitude) *
                             cos(2pi * (ax * (i - 1) + ay * (j - 1) + az * (k - 1)) / nx + phase)
    end
    proposed .-= mean(proposed) - 1.0
    ok = minimum(proposed) > phi_min
    return ok ? proposed : phi, ok
end

function load_pressure_contract(path::AbstractString)
    raw = TOML.parsefile(path)
    return PressureContract(
        String(raw["measure"]),
        Int(raw["dimension"]),
        String(raw["fourier_normalization"]),
        String(raw["volume_derivative"]),
        String.(raw["fixed_quantities"]),
        String(raw["observable_formula_id"]),
        String(raw["cl_column_mapping"]),
    )
end

function _check_contract(contract::PressureContract)
    contract.measure == "phi_direct" || throw(ArgumentError("unsupported pressure measure: $(contract.measure)"))
    contract.dimension == 3 || throw(ArgumentError("pressure estimator requires dimension = 3"))
    contract.fourier_normalization == "forward_unscaled_inverse_1_over_M" ||
        throw(ArgumentError("unsupported Fourier normalization: $(contract.fourier_normalization)"))
    contract.volume_derivative == "finite_difference_log_volume_fixed_A_B_C_times_V_grid_count_density_normalization" ||
        throw(ArgumentError("unsupported volume derivative convention: $(contract.volume_derivative)"))
    contract.observable_formula_id == "heurp_logvolume_fixed_cv_alpha_central_difference_v3" ||
        throw(ArgumentError("unsupported pressure formula: $(contract.observable_formula_id)"))
    required = Set(["A", "B", "C_times_V", "Nx", "mean_phi", "dimension", "alpha"])
    required ⊆ Set(contract.fixed_quantities) ||
        throw(ArgumentError("pressure contract fixed_quantities missing required entries"))
    return nothing
end

function _fixed_chain_volume_perturbation(grid::Grid3D, params::HEURPParams, eps::Real)
    volume_scale = exp(Float64(eps))
    length_scale = exp(Float64(eps) / grid.dimension)
    plus = Grid3D(grid.Nx, grid.L * length_scale)
    minus = Grid3D(grid.Nx, grid.L / length_scale)
    plus_params = HEURPParams(A=params.A, B=params.B, C=params.C / volume_scale, alpha=params.alpha)
    minus_params = HEURPParams(A=params.A, B=params.B, C=params.C * volume_scale, alpha=params.alpha)
    return plus, minus, plus_params, minus_params
end

function pressure_observable(phi, grid::Grid3D, params::HEURPParams, contract::PressureContract; eps=1.0e-4)
    _check_contract(contract)
    plus, minus, plus_params, minus_params = _fixed_chain_volume_perturbation(grid, params, eps)
    dH_dlogV = (heurp_energy(phi, plus, plus_params) - heurp_energy(phi, minus, minus_params)) / (2.0 * eps)
    return params.C - dH_dlogV / grid.volume
end

function _pressure_observable_sparse(phi, grid::Grid3D, params::HEURPParams, contract::PressureContract; eps=1.0e-4)
    _check_contract(contract)
    plus, minus, plus_params, minus_params = _fixed_chain_volume_perturbation(grid, params, eps)
    dH_dlogV = (_heurp_energy_sparse(phi, plus, plus_params) -
                _heurp_energy_sparse(phi, minus, minus_params)) / (2.0 * eps)
    return params.C - dH_dlogV / grid.volume
end

function _pressure_observable_fft(phi, grid::Grid3D, params::HEURPParams, contract::PressureContract; eps=1.0e-4)
    _check_contract(contract)
    plus, minus, plus_params, minus_params = _fixed_chain_volume_perturbation(grid, params, eps)
    dH_dlogV = (_heurp_energy_fft(phi, plus, plus_params) -
                _heurp_energy_fft(phi, minus, minus_params)) / (2.0 * eps)
    return params.C - dH_dlogV / grid.volume
end

function _pressure_observable_adaptive(phi, grid::Grid3D, params::HEURPParams, contract::PressureContract; eps=1.0e-4)
    return _energy_backend(grid) == :fft ? _pressure_observable_fft(phi, grid, params, contract; eps=eps) :
           pressure_observable(phi, grid, params, contract; eps=eps)
end

function hevk1_pressure_observable(phi, grid::Grid3D, params::HEURPParams; eps=1.0e-4)
    plus, minus, plus_params, minus_params = _fixed_chain_volume_perturbation(grid, params, eps)
    dH_dlogV = (hevk1_energy(phi, plus, plus_params) - hevk1_energy(phi, minus, minus_params)) / (2.0 * eps)
    return params.C - dH_dlogV / grid.volume
end

function frozen_pressure_fields(grid::Grid3D)
    fields = Array{Float64,3}[]
    base = ones(grid.Nx, grid.Nx, grid.Nx)
    push!(fields, copy(base))
    for amp in (0.01, 0.02)
        phi = copy(base)
        for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
            phi[i, j, k] += amp * cos(2pi * (i - 1) / grid.Nx) * cos(2pi * (j - 1) / grid.Nx)
        end
        phi .-= mean(phi) - 1.0
        push!(fields, phi)
    end
    return fields
end

function _cosine_direction(grid::Grid3D, mode)
    ax, ay, az = Int(mode[1]), Int(mode[2]), Int(mode[3])
    (ax == 0 && ay == 0 && az == 0) && throw(ArgumentError("stability probe mode cannot be zero"))
    eta = zeros(grid.Nx, grid.Nx, grid.Nx)
    for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
        eta[i, j, k] = cos(2pi * (ax * (i - 1) + ay * (j - 1) + az * (k - 1)) / grid.Nx)
    end
    eta .-= mean(eta)
    scale = maximum(abs.(eta))
    scale > 0.0 || throw(ArgumentError("stability probe mode generated a zero direction"))
    eta ./= scale
    return eta
end

function _basin_variance_cap(value)
    value === nothing && return Inf
    cap = Float64(value)
    cap >= 0.0 || throw(ArgumentError("basin_variance_max must be nonnegative"))
    return cap
end

function _density_lower_bound(value)
    lower = Float64(value)
    0.0 <= lower < 1.0 || throw(ArgumentError("phi_min must be in [0, 1)"))
    return lower
end

function _initial_density_mode_symbol(initialization)
    mode = initialization isa Symbol ? initialization : Symbol(String(initialization))
    mode in (:uniform, :overdispersed, :mixed) ||
        throw(ArgumentError("initial_density_mode must be :uniform, :overdispersed, or :mixed"))
    return mode
end

function _chain_initial_density_mode(initialization, chain_idx::Integer, chain_count::Integer)
    mode = _initial_density_mode_symbol(initialization)
    chain_total = max(1, Int(chain_count))
    idx = Int(chain_idx)
    1 <= idx <= chain_total || throw(ArgumentError("chain_idx must be in 1:chain_count"))
    mode != :mixed && return mode
    chain_total >= 2 || throw(ArgumentError("initial_density_mode=:mixed requires at least two chains"))
    return idx == 1 ? :uniform : :overdispersed
end

function _initial_density_field(
    rng::AbstractRNG,
    grid::Grid3D;
    initialization=:uniform,
    initial_density_amplitude=0.0,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
)
    mode = _initial_density_mode_symbol(initialization)
    mode == :mixed && throw(ArgumentError("initial_density_mode=:mixed must be resolved per chain before field construction"))
    mode == :uniform && return ones(grid.Nx, grid.Nx, grid.Nx)
    amplitude = max(0.0, Float64(initial_density_amplitude))
    lower_bound = _density_lower_bound(phi_min)
    basin_cap = _basin_variance_cap(basin_variance_max)
    direction = randn(rng, grid.Nx, grid.Nx, grid.Nx)
    direction .-= mean(direction)
    direction_std = std(vec(direction); corrected=false)
    direction_std > eps(Float64) || return ones(grid.Nx, grid.Nx, grid.Nx)
    direction ./= direction_std
    target_std = amplitude
    if isfinite(basin_cap)
        nsites = length(direction)
        corrected_variance_scale = nsites <= 1 ? 0.0 : (nsites - 1) / nsites
        target_std = min(target_std, sqrt(max(0.0, basin_cap) * corrected_variance_scale))
    end
    min_direction = minimum(direction)
    if min_direction < 0.0
        target_std = min(target_std, 0.999 * (1.0 - lower_bound) / (-min_direction))
    end
    phi = ones(grid.Nx, grid.Nx, grid.Nx) .+ target_std .* direction
    phi .*= 1.0 / mean(phi)
    minimum(phi) > lower_bound || throw(ArgumentError("overdispersed initialization violated positivity support"))
    isfinite(basin_cap) && var(vec(phi)) > basin_cap + 1.0e-12 &&
        throw(ArgumentError("overdispersed initialization violated basin support"))
    return phi
end

function _basin_constraint_pass(phi::AbstractArray{<:Real}, basin_variance_max::Real)
    cap = Float64(basin_variance_max)
    return !isfinite(cap) || var(vec(phi)) <= cap + 1.0e-14 ? 1.0 : 0.0
end

function _boundary_barrier_strength(value)
    value === nothing && return 0.0
    strength = Float64(value)
    isfinite(strength) && strength >= 0.0 ||
        throw(ArgumentError("boundary_barrier_strength must be finite and nonnegative"))
    return strength
end

function _boundary_barrier_energy(phi::AbstractArray{<:Real}, boundary_barrier_strength)
    strength = _boundary_barrier_strength(boundary_barrier_strength)
    strength == 0.0 && return 0.0
    minimum(phi) > 0.0 || return Inf
    return -strength * sum(log, phi)
end

function _direct_target_model_symbol(target_model)
    normalized = replace(lowercase(String(target_model)), "-" => "_")
    model = Symbol(normalized)
    model in (:heurp, :he_urp) && return :heurp
    model in (:hevk1, :he_vk1, :vk1) && return :hevk1
    throw(ArgumentError("target_model must be :heurp or :hevk1"))
end

_direct_target_model_label(target_model) =
    _direct_target_model_symbol(target_model) == :hevk1 ? "HE-VK1" : "HE-URP"

_direct_target_model_code(target_model) =
    _direct_target_model_symbol(target_model) == :hevk1 ? 2.0 : 1.0

function _direct_target_energy(
    phi::AbstractArray{<:Real,3},
    grid::Grid3D,
    params::HEURPParams,
    target_model,
    boundary_barrier_strength=0.0,
)
    model = _direct_target_model_symbol(target_model)
    target_energy = model == :hevk1 ? hevk1_energy(phi, grid, params) :
                    _heurp_energy_adaptive(phi, grid, params)
    return target_energy + _boundary_barrier_energy(phi, boundary_barrier_strength)
end

function _direct_target_pressure(
    phi::AbstractArray{<:Real,3},
    grid::Grid3D,
    params::HEURPParams,
    contract::PressureContract,
    target_model,
)
    model = _direct_target_model_symbol(target_model)
    return model == :hevk1 ? hevk1_pressure_observable(phi, grid, params) :
           _pressure_observable_adaptive(phi, grid, params, contract)
end

function _target_energy_with_basin(
    phi::AbstractArray{<:Real,3},
    grid::Grid3D,
    params::HEURPParams,
    basin_variance_max::Real,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
)
    _basin_constraint_pass(phi, basin_variance_max) >= 0.5 || return Inf
    return _direct_target_energy(phi, grid, params, target_model, boundary_barrier_strength)
end

function _direct_stability_summary(
    grid::Grid3D,
    params::HEURPParams;
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=8,
    boundary_margin=1.0e-3,
    energy_tolerance=1.0e-8,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    boundary_barrier_strength=0.0,
    pressure_contract=nothing,
)
    uniform = ones(grid.Nx, grid.Nx, grid.Nx)
    basin_cap = _basin_variance_cap(basin_variance_max)
    barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
    uniform_energy = _target_energy_with_basin(uniform, grid, params, basin_cap, :heurp, barrier_strength)
    lower_bound = _density_lower_bound(phi_min)
    margin = max(Float64(boundary_margin), lower_bound)
    0.0 < margin < 1.0 || throw(ArgumentError("effective stability lower bound must be in (0, 1)"))
    count = max(2, Int(amplitude_count))
    tolerance = max(0.0, Float64(energy_tolerance))
    points = 0
    worst_delta = Inf
    worst_min_phi = NaN
    worst_mode = (0, 0, 0)
    pressure_at_worst = NaN
    for mode in modes
        eta = try
            _cosine_direction(grid, mode)
        catch err
            err isa ArgumentError || rethrow()
            continue
        end
        negative_scale = max(0.0, -minimum(eta))
        negative_scale > 0.0 || continue
        max_amplitude = (1.0 - margin) / negative_scale
        for amplitude in range(0.0, max_amplitude; length=count)
            phi = uniform .+ Float64(amplitude) .* eta
            _basin_constraint_pass(phi, basin_cap) >= 0.5 || continue
            energy_delta = _target_energy_with_basin(phi, grid, params, basin_cap, :heurp, barrier_strength) -
                           uniform_energy
            points += 1
            if energy_delta < worst_delta
                worst_delta = energy_delta
                worst_min_phi = minimum(phi)
                worst_mode = (Int(mode[1]), Int(mode[2]), Int(mode[3]))
                pressure_at_worst = pressure_contract === nothing ? NaN :
                                    _pressure_observable_adaptive(phi, grid, params, pressure_contract)
            end
        end
    end
    if points == 0
        return (
            pass=0.0,
            min_energy_delta=NaN,
            min_phi=NaN,
            mode_ax=0.0,
            mode_ay=0.0,
            mode_az=0.0,
            points=0.0,
            boundary_margin=margin,
            phi_min=lower_bound,
            energy_tolerance=tolerance,
            pressure_at_min_energy=NaN,
        )
    end
    pass = worst_delta >= -tolerance ? 1.0 : 0.0
    return (
        pass=pass,
        min_energy_delta=worst_delta,
        min_phi=worst_min_phi,
        mode_ax=Float64(worst_mode[1]),
        mode_ay=Float64(worst_mode[2]),
        mode_az=Float64(worst_mode[3]),
        points=Float64(points),
        boundary_margin=margin,
        phi_min=lower_bound,
        energy_tolerance=tolerance,
        pressure_at_min_energy=pressure_at_worst,
    )
end

function _direct_stability_summary_for_energy(
    grid::Grid3D,
    params::HEURPParams,
    energy_function,
    pressure_function;
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=8,
    boundary_margin=1.0e-3,
    energy_tolerance=1.0e-8,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
)
    uniform = ones(grid.Nx, grid.Nx, grid.Nx)
    uniform_energy = energy_function(uniform, grid, params)
    basin_cap = _basin_variance_cap(basin_variance_max)
    lower_bound = _density_lower_bound(phi_min)
    margin = max(Float64(boundary_margin), lower_bound)
    0.0 < margin < 1.0 || throw(ArgumentError("effective stability lower bound must be in (0, 1)"))
    count = max(2, Int(amplitude_count))
    tolerance = max(0.0, Float64(energy_tolerance))
    points = 0
    worst_delta = Inf
    worst_min_phi = NaN
    worst_mode = (0, 0, 0)
    pressure_at_worst = NaN
    for mode in modes
        eta = try
            _cosine_direction(grid, mode)
        catch err
            err isa ArgumentError || rethrow()
            continue
        end
        negative_scale = max(0.0, -minimum(eta))
        negative_scale > 0.0 || continue
        max_amplitude = (1.0 - margin) / negative_scale
        for amplitude in range(0.0, max_amplitude; length=count)
            phi = uniform .+ Float64(amplitude) .* eta
            _basin_constraint_pass(phi, basin_cap) >= 0.5 || continue
            energy_delta = energy_function(phi, grid, params) - uniform_energy
            points += 1
            if energy_delta < worst_delta
                worst_delta = energy_delta
                worst_min_phi = minimum(phi)
                worst_mode = (Int(mode[1]), Int(mode[2]), Int(mode[3]))
                pressure_at_worst = pressure_function === nothing ? NaN : pressure_function(phi, grid, params)
            end
        end
    end
    if points == 0
        return (
            pass=0.0,
            min_energy_delta=NaN,
            min_phi=NaN,
            mode_ax=0.0,
            mode_ay=0.0,
            mode_az=0.0,
            points=0.0,
            boundary_margin=margin,
            phi_min=lower_bound,
            energy_tolerance=tolerance,
            pressure_at_min_energy=NaN,
        )
    end
    pass = worst_delta >= -tolerance ? 1.0 : 0.0
    return (
        pass=pass,
        min_energy_delta=worst_delta,
        min_phi=worst_min_phi,
        mode_ax=Float64(worst_mode[1]),
        mode_ay=Float64(worst_mode[2]),
        mode_az=Float64(worst_mode[3]),
        points=Float64(points),
        boundary_margin=margin,
        phi_min=lower_bound,
        energy_tolerance=tolerance,
        pressure_at_min_energy=pressure_at_worst,
    )
end

function run_direct_stability_probe(
    outdir::AbstractString;
    Nx=4,
    L=6.4,
    A=300.0,
    B=1.0,
    C=20.0,
    alpha=0.1,
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=12,
    boundary_margin=1.0e-3,
    basin_variance_max=nothing,
)
    mkpath(outdir)
    grid = Grid3D(Nx, L)
    params = HEURPParams(A=A, B=B, C=C, alpha=alpha)
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    uniform = ones(grid.Nx, grid.Nx, grid.Nx)
    uniform_energy = _heurp_energy_adaptive(uniform, grid, params)
    margin = Float64(boundary_margin)
    0.0 < margin < 1.0 || throw(ArgumentError("boundary_margin must be in (0, 1)"))
    basin_cap = basin_variance_max === nothing ? Inf : Float64(basin_variance_max)
    basin_cap >= 0.0 || throw(ArgumentError("basin_variance_max must be nonnegative"))
    count = max(2, Int(amplitude_count))
    rows = Any[]
    worst_delta = Inf
    worst_mode = ""
    worst_amplitude = NaN
    worst_min_phi = NaN
    basin_points = 0
    worst_basin_delta = Inf
    worst_basin_mode = ""
    worst_basin_amplitude = NaN
    worst_basin_min_phi = NaN
    for mode in modes
        eta = _cosine_direction(grid, mode)
        negative_scale = max(0.0, -minimum(eta))
        negative_scale > 0.0 || continue
        max_amplitude = (1.0 - margin) / negative_scale
        for (amp_idx, amplitude) in enumerate(range(0.0, max_amplitude; length=count))
            phi = uniform .+ Float64(amplitude) .* eta
            min_phi = minimum(phi)
            density_variance = var(vec(phi))
            inside_basin = density_variance <= basin_cap + 1.0e-14
            energy = _heurp_energy_adaptive(phi, grid, params)
            pressure = _pressure_observable_adaptive(phi, grid, params, contract)
            energy_delta = energy - uniform_energy
            push!(rows, (
                Int(mode[1]),
                Int(mode[2]),
                Int(mode[3]),
                amp_idx,
                Float64(amplitude),
                min_phi,
                maximum(phi),
                density_variance,
                energy,
                energy_delta,
                pressure,
                params.alpha,
                basin_cap,
                inside_basin ? 1.0 : 0.0,
            ))
            if energy_delta < worst_delta
                worst_delta = energy_delta
                worst_mode = "$(Int(mode[1])),$(Int(mode[2])),$(Int(mode[3]))"
                worst_amplitude = Float64(amplitude)
                worst_min_phi = min_phi
            end
            if inside_basin
                basin_points += 1
                if energy_delta < worst_basin_delta
                    worst_basin_delta = energy_delta
                    worst_basin_mode = "$(Int(mode[1])),$(Int(mode[2])),$(Int(mode[3]))"
                    worst_basin_amplitude = Float64(amplitude)
                    worst_basin_min_phi = min_phi
                end
            end
        end
    end
    csv_path = _write_table(joinpath(outdir, "direct_stability_probe.csv"),
        [
            "mode_ax",
            "mode_ay",
            "mode_az",
            "amplitude_index",
            "amplitude",
            "min_phi",
            "max_phi",
            "density_variance",
            "energy",
            "energy_delta",
            "pressure_observable",
            "alpha",
            "basin_variance_max",
            "inside_basin",
        ], rows)
    summary_path = joinpath(outdir, "direct_stability_probe.md")
    open(summary_path, "w") do io
        println(io, "direct-density HE-URP stability probe")
        println(io, "======================================")
        println(io)
        println(io, "This deterministic probe scans normalized cosine density rays from phi = 1 toward the positivity boundary.")
        println(io, "It uses the same full nonlinear target Hamiltonian and fixed-CV pressure observable as the direct-density Arianna sampler.")
        println(io, @sprintf("Grid Nx = %d, L = %.4g, A = %.4g, B = %.4g, C = %.4g, alpha = %.4g.", grid.Nx, grid.L, params.A, params.B, params.C, params.alpha))
        println(io, @sprintf("Uniform-field energy was %.6g.", uniform_energy))
        println(io, @sprintf("The scan evaluated %.0f points across %.0f Fourier-mode rays with boundary margin %.3g.", length(rows), length(modes), margin))
        if isfinite(basin_cap)
            println(io, @sprintf("Basin restriction: density_variance <= %.6g.", basin_cap))
            println(io, @sprintf("Basin-restricted scan kept %.0f of %.0f ray points.", basin_points, length(rows)))
            if isfinite(worst_basin_delta)
                println(io, @sprintf("The lowest in-basin point had energy change %.6g at mode (%s), amplitude %.6g, and min(phi) %.6g.", worst_basin_delta, worst_basin_mode, worst_basin_amplitude, worst_basin_min_phi))
                if worst_basin_delta < 0.0
                    println(io, "Current basin status: the constrained nonlinear target is still downhill inside this variance basin; a tighter basin or different regularization is needed before production direct MC.")
                else
                    println(io, "Current basin status: no downhill direction was detected inside this finite variance basin.")
                end
            end
        end
        if isfinite(worst_delta)
            println(io, @sprintf("The lowest point had energy change %.6g at mode (%s), amplitude %.6g, and min(phi) %.6g.", worst_delta, worst_mode, worst_amplitude, worst_min_phi))
            if worst_delta < 0.0
                println(io, "Current status: the full nonlinear target has a downhill direction toward the positivity boundary on this grid. This explains why direct Arianna chains can drift outside the Gaussian perturbation basin even when the move implementation is functional.")
            else
                println(io, "Current status: no downhill direction was detected in this finite ray set; sampler tuning remains the likely direct-MC bottleneck.")
            end
        end
    end
    return (csv_path=csv_path, summary_path=summary_path)
end

function run_direct_stability_scan(
    outdir::AbstractString;
    Nx=4,
    L=6.4,
    A=300.0,
    B=1.0,
    C_values=[20.0],
    alpha=0.1,
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=12,
    boundary_margin=1.0e-3,
    energy_tolerance=1.0e-8,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
)
    mkpath(outdir)
    grid = Grid3D(Nx, L)
    Af = Float64(A)
    Bf = Float64(B)
    α = Float64(alpha)
    basin_cap = _basin_variance_cap(basin_variance_max)
    C_list = Float64.(collect(C_values))
    isempty(C_list) && throw(ArgumentError("C_values must not be empty"))
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))

    rows = Any[]
    downhill_count = 0
    for C in C_list
        C > 0.0 || throw(ArgumentError("C_values must be positive"))
        params = HEURPParams(A=Af, B=Bf, C=C, alpha=α)
        summary = _direct_stability_summary(
            grid,
            params;
            modes=modes,
            amplitude_count=amplitude_count,
            boundary_margin=boundary_margin,
            energy_tolerance=energy_tolerance,
            basin_variance_max=basin_cap,
            phi_min=phi_min,
            pressure_contract=contract,
        )
        mean_field = mean_field_pressure(Bf, C)
        dfm = dfm_pressure_discrete(Af, Bf, C, grid; alpha=α)
        summary.pass < 0.5 && (downhill_count += 1)
        push!(rows, (
            C,
            summary.pass,
            summary.min_energy_delta,
            summary.min_phi,
            summary.mode_ax,
            summary.mode_ay,
            summary.mode_az,
            summary.points,
            summary.boundary_margin,
            summary.phi_min,
            summary.energy_tolerance,
            2.0 * Af / C,
            mean_field,
            dfm,
            summary.pressure_at_min_energy,
            summary.pressure_at_min_energy - mean_field,
            summary.pressure_at_min_energy - dfm,
            basin_cap,
            α,
        ))
    end
    csv_path = _write_table(joinpath(outdir, "direct_stability_scan.csv"),
        [
            "C",
            "stability_pass",
            "min_energy_delta",
            "min_phi",
            "mode_ax",
            "mode_ay",
            "mode_az",
            "points",
            "boundary_margin",
            "phi_min",
            "energy_tolerance",
            "stable_fourier_min_k2",
            "mean_field_pressure",
            "dfm_pressure",
            "pressure_at_min_energy",
            "pressure_minus_mean_field",
            "pressure_minus_dfm",
            "basin_variance_max",
            "alpha",
        ], rows)
    markdown_path = joinpath(outdir, "direct_stability_scan.md")
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear stability scan")
        println(io, "================================")
        println(io)
        println(io, "This deterministic scan evaluates the full nonlinear HE-URP target along normalized cosine density rays from phi = 1 toward the positivity boundary.")
        println(io, @sprintf("Grid Nx = %d, L = %.4g, A = %.4g, B = %.4g, alpha = %.4g.", grid.Nx, grid.L, Af, Bf, α))
        println(io, @sprintf("The scan used %d concentration value(s), %d amplitude points per ray, boundary margin %.3g, phi_min %.3g, and energy tolerance %.3g.", length(C_list), max(2, Int(amplitude_count)), Float64(boundary_margin), _density_lower_bound(phi_min), Float64(energy_tolerance)))
        if isfinite(basin_cap)
            println(io, @sprintf("A hard-wall basin restriction density_variance <= %.6g was active.", basin_cap))
        end
        println(io, @sprintf("Downhill target directions were detected for %d of %d concentration value(s).", downhill_count, length(C_list)))
        println(io)
        for row in rows
            status = Float64(row[2]) >= 0.5 ? "pass" : "downhill"
            println(io, @sprintf(
                "C = %.6g: %s, min Delta H = %.6g at mode (%.0f,%.0f,%.0f), min(phi) = %.6g, pressure observable at that point = %.6g, k_stable^2 >= %.6g, Pi_DFM_grid = %.6g.",
                Float64(row[1]),
                status,
                Float64(row[3]),
                Float64(row[5]),
                Float64(row[6]),
                Float64(row[7]),
                Float64(row[4]),
                Float64(row[15]),
                Float64(row[12]),
                Float64(row[14]),
            ))
        end
        println(io)
        println(io, "Rows with negative minimum energy change indicate that longer unconstrained direct Arianna sampling can leave the perturbative DFM basin instead of converging to the DFM pressure curve.")
        println(io, "Machine-readable scan: `$(basename(csv_path))`.")
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "direct_stability_scan",
        ),
        "grid" => Dict{String,Any}(
            "dimension" => grid.dimension,
            "Nx" => grid.Nx,
            "L" => grid.L,
        ),
        "params" => Dict{String,Any}(
            "A" => Af,
            "B" => Bf,
            "C_values" => _toml_value(C_list),
            "alpha" => α,
        ),
        "scan" => Dict{String,Any}(
            "amplitude_count" => max(2, Int(amplitude_count)),
            "boundary_margin" => Float64(boundary_margin),
            "energy_tolerance" => Float64(energy_tolerance),
            "basin_variance_max" => _toml_value(basin_cap),
            "phi_min" => _density_lower_bound(phi_min),
            "downhill_count" => downhill_count,
        ),
        "outputs" => Dict{String,Any}(
            "stability_scan_csv" => csv_path,
            "stability_scan_markdown" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return (csv_path=csv_path, markdown_path=markdown_path)
end

function run_direct_vk1_stability_scan(
    outdir::AbstractString;
