function run_direct_boundary_scan(
    outdir::AbstractString;
    Nx=4,
    L=6.4,
    A=300.0,
    B=1.0,
    C=20.0,
    alpha=0.1,
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=12,
    boundary_margins=[0.1, 0.01, 0.001],
    energy_tolerance=1.0e-8,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
)
    mkpath(outdir)
    grid = Grid3D(Nx, L)
    params = HEURPParams(A=A, B=B, C=C, alpha=alpha)
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    margins = Float64.(collect(boundary_margins))
    isempty(margins) && throw(ArgumentError("boundary_margins must not be empty"))
    basin_cap = _basin_variance_cap(basin_variance_max)
    lower_bound = _density_lower_bound(phi_min)
    rows = Any[]
    downhill_count = 0
    for margin in margins
        summary = _direct_stability_summary(
            grid,
            params;
            modes=modes,
            amplitude_count=amplitude_count,
            boundary_margin=margin,
            energy_tolerance=energy_tolerance,
            basin_variance_max=basin_cap,
            phi_min=lower_bound,
            pressure_contract=contract,
        )
        mean_field = mean_field_pressure(params.B, params.C)
        dfm = dfm_pressure_discrete(params.A, params.B, params.C, grid; alpha=params.alpha)
        summary.pass < 0.5 && (downhill_count += 1)
        push!(rows, (
            summary.boundary_margin,
            summary.pass,
            summary.min_energy_delta,
            summary.min_phi,
            summary.mode_ax,
            summary.mode_ay,
            summary.mode_az,
            summary.points,
            summary.phi_min,
            summary.energy_tolerance,
            params.C,
            2.0 * params.A / params.C,
            mean_field,
            dfm,
            summary.pressure_at_min_energy,
            summary.pressure_at_min_energy - mean_field,
            summary.pressure_at_min_energy - dfm,
            basin_cap,
            params.alpha,
        ))
    end
    csv_path = _write_table(joinpath(outdir, "direct_boundary_scan.csv"),
        [
            "boundary_margin",
            "stability_pass",
            "min_energy_delta",
            "min_phi",
            "mode_ax",
            "mode_ay",
            "mode_az",
            "points",
            "phi_min",
            "energy_tolerance",
            "C",
            "stable_fourier_min_k2",
            "mean_field_pressure",
            "dfm_pressure",
            "pressure_at_min_energy",
            "pressure_minus_mean_field",
            "pressure_minus_dfm",
            "basin_variance_max",
            "alpha",
        ], rows)
    markdown_path = joinpath(outdir, "direct_boundary_scan.md")
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear boundary scan")
        println(io, "==============================")
        println(io)
        println(io, "This deterministic scan evaluates the full nonlinear HE-URP target along normalized density rays while moving the positivity wall.")
        println(io, @sprintf("Grid Nx = %d, L = %.4g, A = %.4g, B = %.4g, C = %.4g, alpha = %.4g.", grid.Nx, grid.L, params.A, params.B, params.C, params.alpha))
        println(io, @sprintf("The scan used %d boundary margin(s), %d amplitude points per ray, phi_min %.3g, and energy tolerance %.3g.", length(margins), max(2, Int(amplitude_count)), lower_bound, Float64(energy_tolerance)))
        if isfinite(basin_cap)
            println(io, @sprintf("A hard-wall basin restriction density_variance <= %.6g was active.", basin_cap))
        end
        println(io, @sprintf("Downhill target directions were detected for %d of %d boundary margin(s).", downhill_count, length(margins)))
        println(io, "The CSV records the pressure observable at the same minimum-energy points so the target instability can be compared directly with the osmotic-pressure estimator.")
        println(io)
        for row in rows
            status = Float64(row[2]) >= 0.5 ? "pass" : "downhill"
            println(io, @sprintf(
                "boundary margin = %.6g: %s, min delta H = %.6g at mode (%.0f,%.0f,%.0f), min(phi) = %.6g, pressure observable = %.6g.",
                Float64(row[1]),
                status,
                Float64(row[3]),
                Float64(row[5]),
                Float64(row[6]),
                Float64(row[7]),
                Float64(row[4]),
                Float64(row[15]),
            ))
        end
        println(io)
        println(io, "If the minimum energy keeps decreasing as the positivity wall approaches zero, the unconstrained direct nonlinear measure is boundary dominated and longer Arianna sampling will not recover the Gaussian DFM pressure.")
        println(io, "Machine-readable scan: `$(basename(csv_path))`.")
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "direct_boundary_scan",
        ),
        "grid" => Dict{String,Any}(
            "dimension" => grid.dimension,
            "Nx" => grid.Nx,
            "L" => grid.L,
        ),
        "params" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
        ),
        "scan" => Dict{String,Any}(
            "boundary_margins" => _toml_value(margins),
            "amplitude_count" => max(2, Int(amplitude_count)),
            "energy_tolerance" => Float64(energy_tolerance),
            "basin_variance_max" => _toml_value(basin_cap),
            "phi_min" => lower_bound,
            "downhill_count" => downhill_count,
        ),
        "outputs" => Dict{String,Any}(
            "boundary_scan_csv" => csv_path,
            "boundary_scan_markdown" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return (csv_path=csv_path, markdown_path=markdown_path)
end

function _direct_boundary_log_slope(
    grid::Grid3D,
    params::HEURPParams,
    mode;
    minimum_tolerance=1.0e-12,
)
    eta = _cosine_direction(grid, mode)
    min_eta = minimum(eta)
    negative_scale = -min_eta
    negative_scale > 0.0 || throw(ArgumentError("boundary asymptotic mode must have a negative lobe"))
    delta_limit = eta ./ negative_scale
    tol = max(Float64(minimum_tolerance), eps(Float64))
    mask = abs.(eta .- min_eta) .<= tol
    min_cells = count(identity, vec(mask))
    min_cells > 0 || throw(ArgumentError("boundary asymptotic mode has no minimum cells"))
    delta_hat = fft(delta_limit)
    mask_hat = fft(Float64.(mask))
    k2 = wavenumber_squared(grid)
    spectral = 0.0 + 0.0im
    for idx in eachindex(k2)
        coefficient = _heurp_spectral_coefficient(k2[idx], params)
        spectral += coefficient * conj(delta_hat[idx]) * mask_hat[idx]
    end
    log_boundary_slope = real(spectral * _spectral_discretization_prefactor(grid))
    jacobian_slope = Float64(min_cells)
    return (
        log_boundary_slope=log_boundary_slope,
        min_cells=Float64(min_cells),
        log_coordinate_jacobian_slope=jacobian_slope,
        jacobian_corrected_log_slope=log_boundary_slope - jacobian_slope,
        min_eta=min_eta,
        max_eta=maximum(eta),
    )
end

function run_direct_boundary_asymptotic_scan(
    outdir::AbstractString;
    Nx=4,
    L=6.4,
    A=300.0,
    B=1.0,
    C_values=[20.0],
    alpha=0.1,
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    slope_tolerance=1.0e-8,
    minimum_tolerance=1.0e-12,
)
    mkpath(outdir)
    grid = Grid3D(Nx, L)
    Af = Float64(A)
    Bf = Float64(B)
    α = Float64(alpha)
    C_list = Float64.(collect(C_values))
    isempty(C_list) && throw(ArgumentError("C_values must not be empty"))
    tolerance = max(0.0, Float64(slope_tolerance))
    rows = Any[]
    unbounded_count = 0
    for C in C_list
        C > 0.0 || throw(ArgumentError("C_values must be positive"))
        params = HEURPParams(A=Af, B=Bf, C=C, alpha=α)
        for mode in modes
            ax, ay, az = Int(mode[1]), Int(mode[2]), Int(mode[3])
            (ax == 0 && ay == 0 && az == 0) && continue
            summary = _direct_boundary_log_slope(
                grid,
                params,
                (ax, ay, az);
                minimum_tolerance=minimum_tolerance,
            )
            unbounded = summary.log_boundary_slope > tolerance ? 1.0 : 0.0
            jacobian_corrected_unbounded =
                summary.jacobian_corrected_log_slope > tolerance ? 1.0 : 0.0
            unbounded > 0.5 && (unbounded_count += 1)
            push!(rows, (
                C,
                ax,
                ay,
                az,
                summary.log_boundary_slope,
                summary.min_cells,
                summary.log_coordinate_jacobian_slope,
                summary.jacobian_corrected_log_slope,
                jacobian_corrected_unbounded,
                summary.min_eta,
                summary.max_eta,
                unbounded,
                tolerance,
                2.0 * Af / C,
                mean_field_pressure(Bf, C),
                dfm_pressure_discrete(Af, Bf, C, grid; alpha=α),
                α,
            ))
        end
    end
    csv_path = _write_table(joinpath(outdir, "direct_boundary_asymptotic_scan.csv"),
        [
            "C",
            "mode_ax",
            "mode_ay",
            "mode_az",
            "log_boundary_slope",
            "min_cells",
            "log_coordinate_jacobian_slope",
            "jacobian_corrected_log_slope",
            "jacobian_corrected_unbounded_below",
            "min_eta",
            "max_eta",
            "asymptotic_unbounded_below",
            "slope_tolerance",
            "stable_fourier_min_k2",
            "mean_field_pressure",
            "dfm_pressure",
            "alpha",
        ], rows)
    markdown_path = joinpath(outdir, "direct_boundary_asymptotic_scan.md")
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear boundary asymptotic scan")
        println(io, "========================================")
        println(io)
        println(io, "This deterministic scan evaluates the singular log-boundary coefficient of the full nonlinear HE-URP target.")
        println(io, "For a density ray with epsilon = min(phi), the singular part is H ~ slope * log(epsilon) + O(1).")
        println(io, "Because log(epsilon) -> -Inf, a positive slope means the target is asymptotically unbounded below along that ray.")
        println(io, "For direct-density MC written in log-density coordinates, the softmax/log-coordinate Jacobian contributes min_cells * log(epsilon), so the corrected singular energy is (slope - min_cells) * log(epsilon) + O(1).")
        println(io, @sprintf("Grid Nx = %d, L = %.4g, A = %.4g, B = %.4g, alpha = %.4g.", grid.Nx, grid.L, Af, Bf, α))
        println(io, @sprintf("The scan evaluated %d concentration value(s), %d mode(s), and found %d unbounded-below row(s) using slope tolerance %.3g.", length(C_list), length(modes), unbounded_count, tolerance))
        println(io)
        for row in rows
            status = Float64(row[12]) >= 0.5 ? "unbounded below" : "not flagged"
            corrected_status = Float64(row[9]) >= 0.5 ? "still unbounded after log-coordinate Jacobian" :
                               "not flagged after log-coordinate Jacobian"
            println(io, @sprintf(
                "C = %.6g, mode (%.0f,%.0f,%.0f): slope = %.6g, min cells = %.0f, corrected slope = %.6g, %s; %s.",
                Float64(row[1]),
                Float64(row[2]),
                Float64(row[3]),
                Float64(row[4]),
                Float64(row[5]),
                Float64(row[6]),
                Float64(row[8]),
                status,
                corrected_status,
            ))
        end
        println(io)
        println(io, "Rows flagged as unbounded below cannot be repaired by longer unconstrained Arianna sampling; they require a reformulated or explicitly constrained nonlinear target.")
        println(io, "Machine-readable scan: `$(basename(csv_path))`.")
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "direct_boundary_asymptotic_scan",
        ),
        "grid" => Dict{String,Any}(
            "dimension" => grid.dimension,
            "Nx" => grid.Nx,
            "L" => grid.L,
        ),
        "params" => Dict{String,Any}(
            "A" => Af,
            "B" => Bf,
            "C_values" => _toml_value(C_list),
            "alpha" => α,
        ),
        "scan" => Dict{String,Any}(
            "slope_tolerance" => tolerance,
            "minimum_tolerance" => Float64(minimum_tolerance),
            "unbounded_below_count" => unbounded_count,
        ),
        "outputs" => Dict{String,Any}(
            "boundary_asymptotic_scan_csv" => csv_path,
            "boundary_asymptotic_scan_markdown" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return (csv_path=csv_path, markdown_path=markdown_path)
end

function _boundary_ray_field(grid::Grid3D, mode, epsilon::Real)
    eps_value = Float64(epsilon)
    0.0 < eps_value < 1.0 || throw(ArgumentError("epsilon must be in (0, 1)"))
    eta = _cosine_direction(grid, mode)
    min_eta = minimum(eta)
    min_eta < 0.0 || throw(ArgumentError("boundary ray mode must have a negative lobe"))
    amplitude = (1.0 - eps_value) / (-min_eta)
    phi = ones(grid.Nx, grid.Nx, grid.Nx) .+ amplitude .* eta
    minimum(phi) > 0.0 || throw(ArgumentError("boundary ray generated a nonpositive field"))
    return phi, amplitude
end

function _boundary_ray_log_target(
    log_epsilon::Real,
    grid::Grid3D,
    params::HEURPParams,
    mode,
    contract::Union{Nothing,PressureContract},
    min_cells::Real,
)
    epsilon = exp(Float64(log_epsilon))
    phi, amplitude = _boundary_ray_field(grid, mode, epsilon)
    energy = _heurp_energy_adaptive(phi, grid, params)
    pressure = contract === nothing ? NaN : _pressure_observable_adaptive(phi, grid, params, contract)
    log_weight_phi = -energy
    log_weight_log_epsilon = log_weight_phi + Float64(min_cells) * Float64(log_epsilon)
    return (
        epsilon=epsilon,
        amplitude=amplitude,
        energy=energy,
        pressure=pressure,
        log_weight_phi=log_weight_phi,
        log_weight_log_epsilon=log_weight_log_epsilon,
        density_variance=var(vec(phi)),
        min_phi=minimum(phi),
    )
end

function _boundary_ray_cl_reference(C::Real)
    path = _analysis_cl_path()
    if !isfile(path)
        return (pressure=NaN, error=NaN, path=path)
    end
    pressure, error = _nearest_cl(read_cl_pressure(path), C)
    return (pressure=pressure, error=error, path=path)
end

function run_direct_boundary_ray_mc(
    outdir::AbstractString;
    seed=1,
    steps=20_000,
    burn_fraction=0.5,
    sample_stride=10,
    Nx=8,
    L=6.4,
    A=300.0,
    B=1.0,
    C=20.0,
    alpha=0.1,
    mode=(2, 0, 0),
    epsilon_min=1.0e-8,
    epsilon_max=0.2,
    initial_epsilon=0.1,
    log_epsilon_proposal_width=0.5,
)
    mkpath(outdir)
    total_steps = max(1, Int(steps))
    burn = clamp(floor(Int, total_steps * Float64(burn_fraction)), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    eps_min = Float64(epsilon_min)
    eps_max = Float64(epsilon_max)
    0.0 < eps_min < eps_max < 1.0 ||
        throw(ArgumentError("epsilon bounds must satisfy 0 < epsilon_min < epsilon_max < 1"))
    eps_initial = clamp(Float64(initial_epsilon), eps_min, eps_max)
    proposal_width = max(Float64(log_epsilon_proposal_width), eps(Float64))
    grid = Grid3D(Int(Nx), Float64(L))
    params = HEURPParams(A=Float64(A), B=Float64(B), C=Float64(C), alpha=Float64(alpha))
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    mode_tuple = (Int(mode[1]), Int(mode[2]), Int(mode[3]))
    slope = _direct_boundary_log_slope(grid, params, mode_tuple)
    log_min = log(eps_min)
    log_max = log(eps_max)
    rng = StableRNG(seed)
    current_log_epsilon = log(eps_initial)
    current = _boundary_ray_log_target(current_log_epsilon, grid, params, mode_tuple, nothing, slope.min_cells)
    attempts = 0
    accepts = 0
    samples = Any[]
    pressures = Float64[]
    epsilons = Float64[]
    log_weights = Float64[]

    for step in 1:total_steps
        proposed_log_epsilon = current_log_epsilon + (2.0 * rand(rng) - 1.0) * proposal_width
        attempts += 1
        if log_min <= proposed_log_epsilon <= log_max
            proposed = _boundary_ray_log_target(proposed_log_epsilon, grid, params, mode_tuple, nothing, slope.min_cells)
            log_accept = proposed.log_weight_log_epsilon - current.log_weight_log_epsilon
            if log(rand(rng)) < min(0.0, log_accept)
                current_log_epsilon = proposed_log_epsilon
                current = proposed
                accepts += 1
            end
        end
        if step > burn && (step - burn) % stride == 0
            sampled = _boundary_ray_log_target(current_log_epsilon, grid, params, mode_tuple, contract, slope.min_cells)
            sample_idx = length(samples) + 1
            push!(samples, (
                sample_idx,
                step,
                current_log_epsilon,
                sampled.epsilon,
                sampled.amplitude,
                sampled.energy,
                sampled.pressure,
                sampled.log_weight_phi,
                sampled.log_weight_log_epsilon,
                sampled.density_variance,
                sampled.min_phi,
            ))
            push!(pressures, sampled.pressure)
            push!(epsilons, sampled.epsilon)
            push!(log_weights, sampled.log_weight_log_epsilon)
        end
    end
    isempty(samples) && throw(ArgumentError("boundary-ray MC produced no stored samples; reduce burn_fraction or sample_stride"))

    pressure_summary = batch_summary(pressures)
    epsilon_summary = batch_summary(epsilons)
    log_weight_summary = batch_summary(log_weights)
    cl_ref = _boundary_ray_cl_reference(params.C)
    dfm = dfm_pressure_discrete(params.A, params.B, params.C, grid; alpha=params.alpha)
    mean_field = mean_field_pressure(params.B, params.C)
    acceptance_rate = attempts == 0 ? NaN : accepts / attempts
    minimum_sample_epsilon = minimum(epsilons)
    lower_cutoff_hit_fraction = mean(eps <= eps_min * 1.01 for eps in epsilons)
    jacobian_corrected_unbounded = slope.jacobian_corrected_log_slope > 1.0e-8 ? 1.0 : 0.0
    cutoff_dominated = lower_cutoff_hit_fraction >= 0.5 ? 1.0 : 0.0

    samples_csv = _write_table(joinpath(outdir, "direct_boundary_ray_samples.csv"),
        [
            "sample_index",
            "step",
            "log_epsilon",
            "epsilon",
            "ray_amplitude",
            "energy",
            "pressure",
            "log_weight_phi_measure",
            "log_weight_log_epsilon_measure",
            "density_variance",
            "min_phi",
        ], samples)
    summary_csv = _write_table(joinpath(outdir, "direct_boundary_ray_summary.csv"),
        [
            "C",
            "mode_ax",
            "mode_ay",
            "mode_az",
            "steps",
            "burn_fraction",
            "sample_stride",
            "stored_samples",
            "acceptance_rate",
            "epsilon_min",
            "epsilon_max",
            "minimum_sample_epsilon",
            "mean_epsilon",
            "epsilon_stderr",
            "epsilon_effective_sample_size",
            "lower_cutoff_hit_fraction",
            "cutoff_dominated",
            "pressure_mean",
            "pressure_stderr",
            "pressure_effective_sample_size",
            "mean_field_pressure",
            "dfm_pressure",
            "cl_pressure_nearest",
            "cl_error_nearest",
            "pressure_minus_dfm",
            "pressure_minus_cl",
            "log_weight_mean",
            "log_weight_stderr",
            "log_weight_effective_sample_size",
            "log_boundary_slope",
            "min_cells",
            "log_coordinate_jacobian_slope",
            "jacobian_corrected_log_slope",
            "jacobian_corrected_unbounded_below",
            "alpha",
        ], [(
            params.C,
            mode_tuple[1],
            mode_tuple[2],
            mode_tuple[3],
            total_steps,
            Float64(burn_fraction),
            stride,
            length(samples),
            acceptance_rate,
            eps_min,
            eps_max,
            minimum_sample_epsilon,
            epsilon_summary.mean,
            epsilon_summary.stderr,
            epsilon_summary.effective_sample_size,
            lower_cutoff_hit_fraction,
            cutoff_dominated,
            pressure_summary.mean,
            pressure_summary.stderr,
            pressure_summary.effective_sample_size,
            mean_field,
            dfm,
            cl_ref.pressure,
            cl_ref.error,
            pressure_summary.mean - dfm,
            pressure_summary.mean - cl_ref.pressure,
            log_weight_summary.mean,
            log_weight_summary.stderr,
            log_weight_summary.effective_sample_size,
            slope.log_boundary_slope,
            slope.min_cells,
            slope.log_coordinate_jacobian_slope,
            slope.jacobian_corrected_log_slope,
            jacobian_corrected_unbounded,
            params.alpha,
        )])
    markdown_path = joinpath(outdir, "direct_boundary_ray_mc.md")
    open(markdown_path, "w") do io
        println(io, "Direct HE-URP boundary-ray Monte Carlo")
        println(io, "======================================")
        println(io)
        println(io, "This diagnostic samples the full nonlinear HE-URP Hamiltonian on the density ray identified by the stability and asymptotic scans.")
        println(io, "The Markov variable is log(epsilon), where epsilon = min(phi). The target includes the direct-measure log-coordinate Jacobian contribution min_cells * log(epsilon).")
        println(io, @sprintf("Mode = (%d,%d,%d), Nx = %d, C = %.6g, epsilon in [%.3g, %.3g].", mode_tuple[1], mode_tuple[2], mode_tuple[3], grid.Nx, params.C, eps_min, eps_max))
        println(io, @sprintf("Boundary asymptotic slope = %.6g, min_cells = %.0f, Jacobian-corrected slope = %.6g.", slope.log_boundary_slope, slope.min_cells, slope.jacobian_corrected_log_slope))
        println(io, @sprintf("Stored samples = %d after %.0f burn-in steps, acceptance = %.4g.", length(samples), Float64(burn), acceptance_rate))
        println(io, @sprintf("Mean epsilon = %.6g +/- %.3g; minimum sampled epsilon = %.6g; lower-cutoff hit fraction = %.3g.", epsilon_summary.mean, epsilon_summary.stderr, minimum_sample_epsilon, lower_cutoff_hit_fraction))
        println(io, @sprintf("Pressure on this ray = %.6g +/- %.3g; DFM = %.6g; nearest CL = %.6g +/- %.3g.", pressure_summary.mean, pressure_summary.stderr, dfm, cl_ref.pressure, cl_ref.error))
        println(io)
        if jacobian_corrected_unbounded >= 0.5
            println(io, "Interpretation: the Jacobian-corrected ray target is asymptotically unbounded below. If the sampled trace is cutoff-dominated, this is target-level evidence against treating unconstrained HE-URP direct MC as manuscript-ready.")
        else
            println(io, "Interpretation: this ray was not flagged as Jacobian-corrected unbounded below by the asymptotic scan; inspect the full MC diagnostics before drawing target-level conclusions.")
        end
        println(io, "This is not Gaussian perturbation MC and it does not change the HE-URP target; it is a direct nonlinear slice diagnostic.")
        println(io, "Machine-readable samples: `$(basename(samples_csv))`; summary: `$(basename(summary_csv))`.")
    end
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "direct_boundary_ray_mc",
            "seed" => Int(seed),
            "sampler" => "log_epsilon_metropolis",
            "target_model" => "HE-URP",
        ),
        "grid" => Dict{String,Any}(
            "dimension" => grid.dimension,
            "Nx" => grid.Nx,
            "L" => grid.L,
        ),
        "params" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
        ),
        "sampling" => Dict{String,Any}(
            "steps" => total_steps,
            "burn_fraction" => Float64(burn_fraction),
            "sample_stride" => stride,
            "epsilon_min" => eps_min,
            "epsilon_max" => eps_max,
            "initial_epsilon" => eps_initial,
            "log_epsilon_proposal_width" => proposal_width,
            "acceptance_rate" => acceptance_rate,
        ),
        "boundary_ray" => Dict{String,Any}(
            "mode" => _toml_value([mode_tuple[1], mode_tuple[2], mode_tuple[3]]),
            "log_boundary_slope" => slope.log_boundary_slope,
            "min_cells" => slope.min_cells,
            "log_coordinate_jacobian_slope" => slope.log_coordinate_jacobian_slope,
            "jacobian_corrected_log_slope" => slope.jacobian_corrected_log_slope,
            "jacobian_corrected_unbounded_below" => jacobian_corrected_unbounded >= 0.5,
            "lower_cutoff_hit_fraction" => lower_cutoff_hit_fraction,
            "cutoff_dominated" => cutoff_dominated >= 0.5,
        ),
        "outputs" => Dict{String,Any}(
            "boundary_ray_samples_csv" => samples_csv,
            "boundary_ray_summary_csv" => summary_csv,
            "boundary_ray_markdown" => markdown_path,
            "cl_source" => cl_ref.path,
        ),
        "environment" => _metadata_environment(),
    ))
    return (
        samples_csv=samples_csv,
        summary_csv=summary_csv,
        markdown_path=markdown_path,
        metadata_path=metadata_path,
    )
end

function run_basin_variance_scan(
    outdir::AbstractString;
    Nx=4,
    L=6.4,
    A=300.0,
    B=1.0,
    C=20.0,
    alpha=0.1,
    modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    amplitude_count=12,
    boundary_margin=1.0e-3,
    variance_caps=[0.0, 0.001, 0.002, 0.005, 0.01, 0.02],
    energy_tolerance=1.0e-8,
)
    mkpath(outdir)
    grid = Grid3D(Nx, L)
    params = HEURPParams(A=A, B=B, C=C, alpha=alpha)
    uniform = ones(grid.Nx, grid.Nx, grid.Nx)
    uniform_energy = _heurp_energy_adaptive(uniform, grid, params)
    margin = Float64(boundary_margin)
    0.0 < margin < 1.0 || throw(ArgumentError("boundary_margin must be in (0, 1)"))
    count = max(2, Int(amplitude_count))
    tolerance = max(0.0, Float64(energy_tolerance))

    ray_points = Any[]
    for mode in modes
        eta = try
            _cosine_direction(grid, mode)
        catch err
            err isa ArgumentError || rethrow()
            continue
        end
        negative_scale = max(0.0, -minimum(eta))
        negative_scale > 0.0 || continue
        max_amplitude = (1.0 - margin) / negative_scale
        for (amp_idx, amplitude) in enumerate(range(0.0, max_amplitude; length=count))
            phi = uniform .+ Float64(amplitude) .* eta
            energy_delta = _heurp_energy_adaptive(phi, grid, params) - uniform_energy
            push!(ray_points, (
                mode=(Int(mode[1]), Int(mode[2]), Int(mode[3])),
                amplitude_index=amp_idx,
                amplitude=Float64(amplitude),
                min_phi=minimum(phi),
                density_variance=var(vec(phi)),
                energy_delta=energy_delta,
            ))
        end
    end

    rows = Any[]
    largest_stable_cap = NaN
    sorted_caps = sort(Float64.(collect(variance_caps)))
    for cap in sorted_caps
        cap >= 0.0 || throw(ArgumentError("variance_caps must be nonnegative"))
        inside_count = 0
        min_delta = Inf
        worst_point = nothing
        for point in ray_points
            if point.density_variance <= cap + 1.0e-14
                inside_count += 1
                if point.energy_delta < min_delta
                    min_delta = point.energy_delta
                    worst_point = point
                end
            end
        end
        if inside_count == 0
            push!(rows, (cap, 0, length(ray_points), NaN, NaN, 0, 0, 0, NaN, 0.0, params.alpha))
            continue
        end
        pass = min_delta >= -tolerance ? 1.0 : 0.0
        pass == 1.0 && (largest_stable_cap = cap)
        push!(rows, (
            cap,
            inside_count,
            length(ray_points),
            min_delta,
            worst_point.min_phi,
            worst_point.mode[1],
            worst_point.mode[2],
            worst_point.mode[3],
            worst_point.amplitude,
            pass,
            params.alpha,
        ))
    end

    csv_path = _write_table(joinpath(outdir, "basin_variance_scan.csv"),
        [
            "basin_variance_max",
            "in_basin_points",
            "total_points",
            "min_in_basin_energy_delta",
            "min_in_basin_phi",
            "mode_ax",
            "mode_ay",
            "mode_az",
            "amplitude",
            "basin_stability_pass",
            "alpha",
        ], rows)
    summary_path = joinpath(outdir, "basin_variance_scan.md")
    open(summary_path, "w") do io
        println(io, "basin variance scan")
        println(io, "===================")
        println(io)
        println(io, "This deterministic scan reuses the direct-density HE-URP stability rays and evaluates hard-wall Gaussian-basin caps in density variance.")
        println(io, @sprintf("Grid Nx = %d, L = %.4g, A = %.4g, B = %.4g, C = %.4g, alpha = %.4g.", grid.Nx, grid.L, params.A, params.B, params.C, params.alpha))
        println(io, @sprintf("The scan evaluated %.0f ray points for %.0f variance caps with boundary margin %.3g.", length(ray_points), length(sorted_caps), margin))
        if isfinite(largest_stable_cap)
            println(io, @sprintf("The largest stable variance cap in this deterministic ray set is %.6g.", largest_stable_cap))
        else
            println(io, "No tested variance cap passed the deterministic ray stability check.")
        end
        println(io)
        println(io, "A cap passes only when every scanned in-basin point has energy change greater than or equal to the negative energy tolerance.")
        for row in rows
            cap, inside_count, total_points, min_delta, min_phi, ax, ay, az, amplitude, pass, _ = row
            if inside_count == 0
                println(io, @sprintf("- cap %.6g: no in-basin ray points out of %.0f total.", cap, total_points))
            else
                println(io, @sprintf("- cap %.6g: %.0f/%.0f in-basin points, minimum energy change %.6g at mode (%d,%d,%d), amplitude %.6g, min(phi) %.6g, pass %.0f.",
                    cap, inside_count, total_points, min_delta, ax, ay, az, amplitude, min_phi, pass))
            end
        end
    end
    return (csv_path=csv_path, summary_path=summary_path)
end

function _blocking_stderr(data::AbstractVector{<:Real})
    n = length(data)
    n <= 1 && return 0.0
    block_count = max(1, min(8, floor(Int, sqrt(n))))
    block_size = max(1, fld(n, block_count))
    block_means = Float64[]
    for start in 1:block_size:n
        stop = min(start + block_size - 1, n)
        push!(block_means, mean(@view data[start:stop]))
    end
    return length(block_means) == 1 ? std(data; corrected=true) / sqrt(n) :
           std(block_means; corrected=true) / sqrt(length(block_means))
end

function _integrated_autocorrelation_time(data::AbstractVector{<:Real})
    n = length(data)
    n <= 1 && return 0.5
    μ = mean(data)
    centered = Float64.(data) .- μ
    c0 = sum(abs2, centered) / n
    c0 <= eps(Float64) && return 0.5
    max_lag = min(n - 1, max(1, n ÷ 2))
    τ = 0.5
    for lag in 1:max_lag
        c_lag = 0.0
        for i in 1:(n - lag)
            c_lag += centered[i] * centered[i + lag]
        end
        ρ = c_lag / ((n - lag) * c0)
        ρ <= 0.0 && break
        τ += ρ
    end
    return max(0.5, τ)
end

function _markov_mean_stderr(data::AbstractVector{<:Real})
    n = length(data)
    n <= 1 && return 0.0
    independent_se = std(data; corrected=true) / sqrt(n)
    autocorr_se = independent_se * sqrt(2.0 * _integrated_autocorrelation_time(data))
    return max(_blocking_stderr(data), autocorr_se)
end

function batch_summary(values::AbstractVector{<:Real})
    n = length(values)
    n == 0 && throw(ArgumentError("cannot summarize empty trace"))
    data = Float64.(values)
    μ = mean(data)
    τ = _integrated_autocorrelation_time(data)
    ess = min(Float64(n), max(1.0, Float64(n) / (2.0 * τ)))
    independent_se = n == 1 ? 0.0 : std(data; corrected=true) / sqrt(n)
    se = _markov_mean_stderr(data)
    return (
        mean=μ,
        stderr=se,
        independent_stderr=independent_se,
        integrated_autocorrelation_time=τ,
        effective_sample_size=ess,
        trace_drift_zscore=_trace_drift_zscore(data),
        n=n,
    )
end

_trace_samples_pass(summary, min_trace_samples::Real) =
    summary.n >= max(1, Int(ceil(Float64(min_trace_samples)))) ? 1.0 : 0.0

function _pressure_error_pass(summary, pressure_tolerance::Real)
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    return !isfinite(tolerance) || summary.stderr <= tolerance ? 1.0 : 0.0
end

function _trace_drift_zscore(values::AbstractVector{<:Real})
    n = length(values)
    n < 4 && return NaN
    data = Float64.(values)
    q = max(1, n ÷ 4)
    first_block = data[1:q]
    last_block = data[(n - q + 1):n]
    first_mean = mean(first_block)
    last_mean = mean(last_block)
    se = sqrt(_markov_mean_stderr(first_block)^2 + _markov_mean_stderr(last_block)^2)
    delta = abs(last_mean - first_mean)
    se <= eps(Float64) && return delta <= eps(Float64) ? 0.0 : Inf
    return delta / se
end

function _drift_pass(summary, drift_threshold::Real)
    threshold = Float64(drift_threshold)
    threshold >= 0.0 || throw(ArgumentError("drift_threshold must be nonnegative"))
    drift = Float64(summary.trace_drift_zscore)
    return isnan(drift) || drift <= threshold ? 1.0 : 0.0
end

function _combined_chain_trace_drift_zscore(summaries)
    isempty(summaries) && return NaN
    zscores = Float64[Float64(summary.trace_drift_zscore) for summary in summaries]
    finite_zscores = Float64[z for z in zscores if isfinite(z)]
    return any(isinf, zscores) ? Inf : isempty(finite_zscores) ? NaN : maximum(finite_zscores)
end

function _required_steps_for_trace_samples(required_trace_samples::Integer, burn_fraction::Real, sample_stride::Integer)
    required_trace = max(1, Int(required_trace_samples))
    burn_fraction_value = Float64(burn_fraction)
    0.0 <= burn_fraction_value < 1.0 || throw(ArgumentError("burn_fraction must be in [0, 1)"))
    stride = max(1, Int(sample_stride))
    steps = max(1, ceil(Int, required_trace * stride / (1.0 - burn_fraction_value)))
    while true
        burn = clamp(floor(Int, steps * burn_fraction_value), 0, max(steps - 1, 0))
        stored = max(1, fld(max(steps - burn, 0), stride))
        stored >= required_trace && return steps
        steps += 1
    end
end

function _sampling_budget_estimate(
    summary;
    production_steps,
    proposals_per_sweep,
    burn_fraction,
    sample_stride,
    ess_target,
    min_trace_samples,
    pressure_tolerance,
    chain_count=1,
)
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    observed_ess = max(1.0, Float64(summary.effective_sample_size))
    pressure_target_ess = if !isfinite(tolerance)
        0.0
    elseif tolerance == 0.0
        Float64(summary.stderr) <= 0.0 ? 0.0 : Inf
    else
        observed_ess * (max(0.0, Float64(summary.stderr)) / tolerance)^2
    end
    required_ess = max(0.0, Float64(ess_target), pressure_target_ess)
    τ = max(0.5, Float64(summary.integrated_autocorrelation_time))
    decorrelation_stride = max(1, ceil(Int, 2.0 * τ))
    required_trace = max(
        max(1, Int(ceil(Float64(min_trace_samples)))),
        isfinite(required_ess) ? ceil(Int, decorrelation_stride * required_ess) : typemax(Int),
    )
    chains = max(1, Int(chain_count))
    per_chain_required_trace = isfinite(required_ess) ?
                               max(1, ceil(Int, required_trace / chains)) :
                               typemax(Int)
    required_steps = isfinite(required_ess) ?
                     _required_steps_for_trace_samples(per_chain_required_trace, burn_fraction, Int(sample_stride)) :
                     Inf
    sweep_denominator = max(1.0, Float64(proposals_per_sweep))
    required_sweeps = isfinite(required_steps) ? Float64(required_steps) / sweep_denominator : Inf
    current_steps = max(0.0, Float64(production_steps))
    shortfall = current_steps <= 0.0 ? Inf : max(1.0, Float64(required_steps) / current_steps)
    budget_pass = isfinite(required_steps) && current_steps >= Float64(required_steps) ? 1.0 : 0.0
    return (
        pressure_target_effective_sample_size=pressure_target_ess,
        required_effective_sample_size=required_ess,
        required_trace_samples=Float64(required_trace),
        estimated_required_steps=Float64(required_steps),
        estimated_required_sweeps=required_sweeps,
        production_budget_shortfall=shortfall,
        sampling_budget_pass=budget_pass,
    )
end

function _decorrelation_diagnostics(
    summary;
    sample_stride,
    production_steps,
    equilibration_steps,
    required_effective_sample_size,
)
    τ = max(0.5, Float64(summary.integrated_autocorrelation_time))
    trace_length = max(0, Int(summary.n))
    stride = max(1, Int(sample_stride))
    decorrelation_stride_samples = max(1, ceil(Int, 2.0 * τ))
    decorrelation_stride_steps = decorrelation_stride_samples * stride
    decorrelated_sample_count = fld(trace_length, decorrelation_stride_samples)
    burn_steps = max(0.0, Float64(equilibration_steps))
    post_burn_steps = max(0.0, Float64(production_steps) - burn_steps)
    step_scale = max(1.0, Float64(decorrelation_stride_steps))
    required = Float64(required_effective_sample_size)
    pass = isfinite(required) && Float64(decorrelated_sample_count) >= max(0.0, required) ? 1.0 : 0.0
    return (
        decorrelation_stride_samples=Float64(decorrelation_stride_samples),
        decorrelation_stride_steps=Float64(decorrelation_stride_steps),
        decorrelated_sample_count=Float64(decorrelated_sample_count),
        equilibration_autocorrelation_windows=burn_steps / step_scale,
        production_autocorrelation_windows=post_burn_steps / step_scale,
        decorrelation_pass=pass,
    )
end

function _equilibration_sensitivity_diagnostics(
    values::AbstractVector{<:Real},
    summary;
    threshold=3.0,
)
    limit = Float64(threshold)
    limit >= 0.0 || throw(ArgumentError("equilibration sensitivity threshold must be nonnegative"))
    data = Float64[v for v in values if isfinite(Float64(v))]
    n = length(data)
    tail_fraction = 0.5
    if n < 4
        return (
            equilibration_tail_fraction=tail_fraction,
            equilibration_tail_sample_count=Float64(max(0, n)),
            equilibration_head_mean=NaN,
            equilibration_tail_mean=NaN,
            equilibration_tail_stderr=NaN,
            equilibration_sensitivity_zscore=NaN,
            equilibration_sensitivity_threshold=limit,
            equilibration_sensitivity_pass=1.0,
        )
    end
    head = @view data[1:fld(n, 2)]
    tail = @view data[(fld(n, 2) + 1):n]
    head_summary = batch_summary(head)
    tail_summary = batch_summary(tail)
    head_mean = head_summary.mean
    tail_mean = tail_summary.mean
    se = sqrt(head_summary.stderr^2 + tail_summary.stderr^2)
    delta = abs(tail_mean - head_mean)
    zscore = se <= eps(Float64) ? (delta <= eps(Float64) ? 0.0 : Inf) : delta / se
    pass = isnan(zscore) || zscore <= limit ? 1.0 : 0.0
    return (
        equilibration_tail_fraction=tail_fraction,
        equilibration_tail_sample_count=Float64(length(tail)),
        equilibration_head_mean=head_mean,
        equilibration_tail_mean=tail_mean,
        equilibration_tail_stderr=tail_summary.stderr,
        equilibration_sensitivity_zscore=zscore,
        equilibration_sensitivity_threshold=limit,
        equilibration_sensitivity_pass=pass,
    )
end

function _combine_equilibration_sensitivity_diagnostics(diagnostics)
    isempty(diagnostics) && throw(ArgumentError("cannot combine empty equilibration diagnostics"))
    zscores = Float64[getproperty(diagnostic, :equilibration_sensitivity_zscore) for diagnostic in diagnostics]
    finite_zscores = Float64[z for z in zscores if isfinite(z)]
    zscore = any(isinf, zscores) ? Inf : isempty(finite_zscores) ? NaN : maximum(finite_zscores)
    tail_counts = Float64[getproperty(diagnostic, :equilibration_tail_sample_count) for diagnostic in diagnostics]
    thresholds = Float64[getproperty(diagnostic, :equilibration_sensitivity_threshold) for diagnostic in diagnostics]
    tail_stderrs = Float64[
        getproperty(diagnostic, :equilibration_tail_stderr)
        for diagnostic in diagnostics
        if isfinite(Float64(getproperty(diagnostic, :equilibration_tail_stderr)))
    ]
    return (
        equilibration_tail_fraction=maximum(Float64(getproperty(diagnostic, :equilibration_tail_fraction)) for diagnostic in diagnostics),
        equilibration_tail_sample_count=minimum(tail_counts),
        equilibration_head_mean=_mean_finite(getproperty(diagnostic, :equilibration_head_mean) for diagnostic in diagnostics),
        equilibration_tail_mean=_mean_finite(getproperty(diagnostic, :equilibration_tail_mean) for diagnostic in diagnostics),
        equilibration_tail_stderr=isempty(tail_stderrs) ? NaN : maximum(tail_stderrs),
        equilibration_sensitivity_zscore=zscore,
        equilibration_sensitivity_threshold=maximum(thresholds),
        equilibration_sensitivity_pass=minimum(Float64(getproperty(diagnostic, :equilibration_sensitivity_pass)) for diagnostic in diagnostics),
    )
end

function _observable_stationarity_diagnostics(sample; threshold=3.0)
    limit = Float64(threshold)
    limit >= 0.0 || throw(ArgumentError("observable stationarity threshold must be nonnegative"))
    energy_z = _trace_drift_zscore(getproperty(sample, :energy_trace))
    variance_z = _trace_drift_zscore(getproperty(sample, :density_variance_trace))
    structure_z = _trace_drift_zscore(getproperty(sample, :low_mode_structure_trace))
    zscores = (energy_z, variance_z, structure_z)
    finite_zscores = Float64[z for z in zscores if isfinite(z)]
    max_zscore = any(isinf, zscores) ? Inf : isempty(finite_zscores) ? NaN : maximum(finite_zscores)
    pass = isnan(max_zscore) || max_zscore <= limit ? 1.0 : 0.0
    return (
        energy_drift_zscore=energy_z,
        density_variance_drift_zscore=variance_z,
        low_mode_structure_drift_zscore=structure_z,
        max_observable_drift_zscore=max_zscore,
        observable_stationarity_pass=pass,
    )
end

function _combine_observable_stationarity_diagnostics(samples)
    isempty(samples) && throw(ArgumentError("cannot combine empty observable diagnostics"))
    function combine_field(name::Symbol)
        values = Float64[getproperty(sample, name) for sample in samples]
        finite_values = Float64[value for value in values if isfinite(value)]
        return any(isinf, values) ? Inf : isempty(finite_values) ? NaN : maximum(finite_values)
    end
    energy_z = combine_field(:energy_drift_zscore)
    variance_z = combine_field(:density_variance_drift_zscore)
    structure_z = combine_field(:low_mode_structure_drift_zscore)
    zscores = (energy_z, variance_z, structure_z)
    finite_zscores = Float64[z for z in zscores if isfinite(z)]
    max_zscore = any(isinf, zscores) ? Inf : isempty(finite_zscores) ? NaN : maximum(finite_zscores)
    return (
        energy_drift_zscore=energy_z,
        density_variance_drift_zscore=variance_z,
        low_mode_structure_drift_zscore=structure_z,
        max_observable_drift_zscore=max_zscore,
        observable_stationarity_pass=minimum(Float64(getproperty(sample, :observable_stationarity_pass)) for sample in samples),
    )
end

function _mean_finite(values)
    finite_values = Float64[v for v in values if isfinite(v)]
    return isempty(finite_values) ? NaN : mean(finite_values)
end

function _chain_rhat(traces::AbstractVector)
    m = length(traces)
    m < 2 && return NaN
    lengths = [length(trace) for trace in traces]
    n = minimum(lengths)
    n < 2 && return NaN
    truncated = [Float64.(trace[(length(trace) - n + 1):end]) for trace in traces]
    chain_means = [mean(trace) for trace in truncated]
    chain_vars = [var(trace; corrected=true) for trace in truncated]
    W = mean(chain_vars)
    B = n * var(chain_means; corrected=true)
    if W <= eps(Float64)
        return B <= eps(Float64) ? 1.0 : Inf
    end
    var_hat = ((n - 1) / n) * W + B / n
    return max(1.0, sqrt(max(var_hat, 0.0) / W))
end

function _split_chain_rhat(traces::AbstractVector)
    length(traces) < 2 && return NaN
    lengths = [length(trace) for trace in traces]
    n = minimum(lengths)
    n < 4 && return NaN
    half = fld(n, 2)
    half < 2 && return NaN
    split_traces = Vector{Float64}[]
    for trace in traces
        tail = Float64.(trace[(length(trace) - n + 1):end])
        push!(split_traces, tail[1:half])
        push!(split_traces, tail[(end - half + 1):end])
    end
    return _chain_rhat(split_traces)
end

function _rhat_value_pass(value::Real, threshold::Real)
    rhat = Float64(value)
    limit = Float64(threshold)
    return isnan(rhat) || rhat <= limit ? 1.0 : 0.0
end

function read_cl_pressure(path::AbstractString)
    rows = readdlm(path, comments=true, comment_char='#')
    data = Float64.(rows)
    return CLPressureData(data[:, 1], data[:, 6], data[:, 7])
end

function run_config(mode::Symbol)
    if mode == :quick
        analysis = analysis_reference_config()
        return RunConfig(:quick, 3, 2, analysis.target_Nx, analysis.L, analysis.A, analysis.B, [20.0, 30.0],
            false, analysis.alpha, analysis.analysis_source)
    elseif mode == :production
        analysis = analysis_reference_config()
        return RunConfig(:production, 3, analysis.target_Nx, analysis.target_Nx, analysis.L, analysis.A, analysis.B,
            analysis.C_values, true, analysis.alpha, analysis.analysis_source)
    else
        throw(ArgumentError("unknown run mode: $mode"))
    end
end

function _analysis_cl_path()
    return joinpath(@__DIR__, "..", "..", "Analysis", "GREM_CL_a0.1_B1.0_L6.4_Nx64_dt0.1ETD.dat")
end

function _parse_analysis_filename(path::AbstractString)
    name = basename(path)
    m = match(r"a([0-9.]+)_B([0-9.]+)_L([0-9.]+)_Nx([0-9]+)_dt([0-9.]+)", name)
    m === nothing && throw(ArgumentError("cannot parse Analysis CL parameters from $name"))
    return (
        alpha=parse(Float64, m.captures[1]),
        B=parse(Float64, m.captures[2]),
        L=parse(Float64, m.captures[3]),
        Nx=parse(Int, m.captures[4]),
        dt=parse(Float64, m.captures[5]),
    )
end

function analysis_reference_config(path::AbstractString=_analysis_cl_path())
    parsed = _parse_analysis_filename(path)
    cl = read_cl_pressure(path)
    # The representative pressure-vs-C comparison in Analysis/perturbation.py
    # fixes A=300 for this CL dataset and uses rawdata[10:, 0].
    return RunConfig(:analysis, 3, parsed.Nx, parsed.Nx, parsed.L, 300.0, parsed.B,
        cl.C[11:end], true, parsed.alpha, path)
end

function _analysis_dir()
    return normpath(joinpath(@__DIR__, "..", "..", "Analysis"))
end

function _parse_analysis_figure(path::AbstractString)
    stem = splitext(basename(path))[1]
    if (m = match(r"^PivsC_B([0-9.]+)_A([0-9.]+)_([0-9.]+)$", stem)) !== nothing
        return AnalysisFigureSpec(
            name=stem,
            kind=:PivsC,
            B=parse(Float64, m.captures[1]),
            A=parse(Float64, m.captures[2]),
            Cmax=parse(Float64, m.captures[3]),
            source_path=path,
        )
    elseif (m = match(r"^dPivsC_B([0-9.]+)_A([0-9.]+)_([0-9.]+)$", stem)) !== nothing
        return AnalysisFigureSpec(
            name=stem,
            kind=:dPivsC,
            B=parse(Float64, m.captures[1]),
            A=parse(Float64, m.captures[2]),
            Cmax=parse(Float64, m.captures[3]),
            source_path=path,
        )
    elseif (m = match(r"^PivsA_B([0-9.]+)_C([0-9.]+)$", stem)) !== nothing
        return AnalysisFigureSpec(
            name=stem,
            kind=:PivsA,
            B=parse(Float64, m.captures[1]),
            C=parse(Float64, m.captures[2]),
            source_path=path,
        )
    end
    return nothing
end

function analysis_figure_specs(dir::AbstractString=_analysis_dir())
    specs = AnalysisFigureSpec[]
    for path in sort(readdir(dir; join=true))
        lowercase(splitext(path)[2]) == ".pdf" || continue
        spec = _parse_analysis_figure(path)
        spec === nothing || push!(specs, spec)
    end
    return specs
end

function _select_evenly(values::AbstractVector{<:Real}, max_points::Integer)
    n = length(values)
    max_points <= 1 && return [Float64(values[clamp(cld(n, 2), 1, n)])]
    n <= max_points && return Float64.(values)
    idxs = unique(round.(Int, range(1, n; length=max_points)))
    return Float64.(values[idxs])
end

function _axis_values(spec::AnalysisFigureSpec, cl_data::CLPressureData, max_points::Integer)
    if spec.kind == :PivsC
        lower = spec.A > 0 && spec.B > 0 ? sqrt(spec.A / spec.B) + 0.01 : minimum(cl_data.C)
        candidates = [c for c in cl_data.C if c >= lower && c <= spec.Cmax]
        isempty(candidates) && (candidates = max_points <= 1 ? [(lower + spec.Cmax) / 2] :
                                collect(range(lower, spec.Cmax; length=max_points)))
        return _select_evenly(candidates, max_points)
    elseif spec.kind == :dPivsC
        candidates = [c for c in cl_data.C if c <= spec.Cmax]
        isempty(candidates) && (candidates = max_points <= 1 ? [(0.1 + spec.Cmax) / 2] :
                                collect(range(0.1, spec.Cmax; length=max_points)))
        return _select_evenly(candidates, max_points)
    elseif spec.kind == :PivsA
        amin = 1.0
        amax = spec.B * spec.C^2
        return _select_evenly(collect(range(amin, amax; length=max(2, max_points))), max_points)
    else
        throw(ArgumentError("unsupported Analysis figure kind: $(spec.kind)"))
    end
end

function _nearest_cl(cl_data::CLPressureData, C::Real)
    nearest = argmin(abs.(cl_data.C .- Float64(C)))
    return cl_data.pressure[nearest], cl_data.pressure_error[nearest]
end

function _expand_plot_range(lo::Real, hi::Real)
    lo_f = Float64(lo)
    hi_f = Float64(hi)
    if lo_f == hi_f
        pad = max(abs(lo_f) * 0.05, 0.5)
        return lo_f - pad, hi_f + pad
    end
    return lo_f, hi_f
end

function _major_ticks(lo::Real, hi::Real; count::Int=9)
    count >= 2 || throw(ArgumentError("major tick count must be at least 2"))
    lo_f, hi_f = _expand_plot_range(lo, hi)
    return collect(range(lo_f, hi_f; length=count))
end

function _minor_ticks(major_ticks::AbstractVector{<:Real}; subdivisions::Int=5)
    subdivisions >= 2 || throw(ArgumentError("minor tick subdivisions must be at least 2"))
    ticks = Float64[]
    for i in 1:(length(major_ticks) - 1)
        lo = Float64(major_ticks[i])
        hi = Float64(major_ticks[i + 1])
        lo == hi && continue
        for j in 1:(subdivisions - 1)
            push!(ticks, lo + (hi - lo) * j / subdivisions)
        end
    end
    return ticks
end

function _format_tick_label(value::Real)
    value_f = Float64(value)
    abs_value = abs(value_f)
    if abs_value >= 1000.0 || (abs_value > 0.0 && abs_value < 0.01)
        return @sprintf("%.1e", value_f)
    elseif abs_value >= 100.0
        return @sprintf("%.0f", value_f)
    elseif abs_value >= 10.0
        return @sprintf("%.1f", value_f)
    else
        return @sprintf("%.3g", value_f)
    end
end

function _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
                               x_label=_format_tick_label, y_label=_format_tick_label)
    for tick in x_minor_ticks
        x = x_plot(tick)
        println(io, @sprintf("<line class='x-minor-tick' x1='%.3f' y1='360' x2='%.3f' y2='363' stroke='black'/>", x, x))
    end
    for tick in y_minor_ticks
        y = y_plot(tick)
        println(io, @sprintf("<line class='y-minor-tick' x1='67' y1='%.3f' x2='70' y2='%.3f' stroke='black'/>", y, y))
    end
    for tick in xticks
        x = x_plot(tick)
        println(io, @sprintf("<line class='x-major-tick' x1='%.3f' y1='360' x2='%.3f' y2='366' stroke='black'/>", x, x))
        println(io, @sprintf("<text class='x-tick-label' x='%.3f' y='382' font-size='11' text-anchor='middle'>%s</text>", x, x_label(tick)))
    end
    for tick in yticks
        y = y_plot(tick)
        println(io, @sprintf("<line class='y-major-tick' x1='64' y1='%.3f' x2='70' y2='%.3f' stroke='black'/>", y, y))
        println(io, @sprintf("<text class='y-tick-label' x='58' y='%.3f' font-size='11' text-anchor='end'>%s</text>", y + 4, y_label(tick)))
    end
end

function _svg_escape_text(text)
    escaped = replace(String(text), "&" => "&amp;")
    escaped = replace(escaped, "<" => "&lt;")
    escaped = replace(escaped, ">" => "&gt;")
    escaped = replace(escaped, "\"" => "&quot;")
    return replace(escaped, "'" => "&#39;")
end

function _density_visual_color(value::Real, min_value::Real, max_value::Real)
    lo = Float64(min_value)
    hi = Float64(max_value)
    t = hi > lo ? clamp((Float64(value) - lo) / (hi - lo), 0.0, 1.0) : 0.5
    if t <= 0.5
        u = 2.0 * t
        r = round(Int, (1.0 - u) * 49 + u * 245)
        g = round(Int, (1.0 - u) * 96 + u * 245)
        b = round(Int, (1.0 - u) * 160 + u * 245)
    else
        u = 2.0 * (t - 0.5)
        r = round(Int, (1.0 - u) * 245 + u * 178)
        g = round(Int, (1.0 - u) * 245 + u * 60)
        b = round(Int, (1.0 - u) * 245 + u * 46)
    end
    return @sprintf("#%02x%02x%02x", clamp(r, 0, 255), clamp(g, 0, 255),
        clamp(b, 0, 255))
end

function _density_visual_selected_indices(values::Array{Float64,3},
        threshold::Float64, phase::Symbol, max_voxels::Int)
    selected = CartesianIndex{3}[]
    for index in CartesianIndices(values)
        value = values[index]
        keep = phase == :above ? value >= threshold :
            phase == :below ? value <= threshold :
            abs(value - threshold) >= 0.0
        keep && push!(selected, index)
    end
    if length(selected) <= max_voxels
        return selected
    end
    stride = max(1, ceil(Int, (length(selected) / max_voxels)^(1 / 3)))
    return [index for index in selected
        if (index[1] - 1) % stride == 0 &&
           (index[2] - 1) % stride == 0 &&
           (index[3] - 1) % stride == 0]
end

function _write_density_slice_svg(io, values::Array{Float64,3}, plane::Symbol,
        fixed_index::Int, x0::Real, y0::Real, cell::Real, min_value::Real,
        max_value::Real)
    nx, ny, nz = size(values)
    if plane == :xy
        xcount, ycount = nx, ny
        xlabel, ylabel = "x", "y"
    elseif plane == :xz
        xcount, ycount = nx, nz
        xlabel, ylabel = "x", "z"
    elseif plane == :yz
        xcount, ycount = ny, nz
        xlabel, ylabel = "y", "z"
    else
        throw(ArgumentError("unsupported slice plane $(plane)"))
    end
    println(io, @sprintf("<text x='%.3f' y='%.3f' font-family='Arial' font-size='13' font-weight='bold'>central %s slice</text>",
        Float64(x0), Float64(y0) - 10.0, uppercase(String(plane))))
    for j in 1:ycount, i in 1:xcount
        value = plane == :xy ? values[i, j, fixed_index] :
            plane == :xz ? values[i, fixed_index, j] :
            values[fixed_index, i, j]
        color = _density_visual_color(value, min_value, max_value)
        xx = Float64(x0) + (i - 1) * Float64(cell)
        yy = Float64(y0) + (ycount - j) * Float64(cell)
        println(io, @sprintf("<rect x='%.3f' y='%.3f' width='%.3f' height='%.3f' fill='%s' stroke='white' stroke-width='0.2'/>",
            xx, yy, Float64(cell), Float64(cell), color))
    end
    println(io, @sprintf("<rect x='%.3f' y='%.3f' width='%.3f' height='%.3f' fill='none' stroke='#333' stroke-width='1'/>",
        Float64(x0), Float64(y0), xcount * Float64(cell), ycount * Float64(cell)))
    println(io, @sprintf("<text x='%.3f' y='%.3f' font-family='Arial' font-size='10'>%s</text>",
        Float64(x0) + xcount * Float64(cell) / 2, Float64(y0) + ycount * Float64(cell) + 15.0, xlabel))
    println(io, @sprintf("<text x='%.3f' y='%.3f' font-family='Arial' font-size='10'>%s</text>",
        Float64(x0) - 14.0, Float64(y0) + ycount * Float64(cell) / 2, ylabel))
end

function write_density_field_visual_svg(field::AbstractArray{<:Real,3},
        svg_path::AbstractString; title::AbstractString="3D density field",
        threshold::Real=mean(field), phase::Symbol=:above,
        max_voxels::Integer=1400)
    values = Float64.(field)
    all(isfinite, values) || throw(ArgumentError("density field must be finite"))
    phase in (:above, :below, :all) ||
        throw(ArgumentError("phase must be :above, :below, or :all"))
    nx, ny, nz = size(values)
    nx > 1 && ny > 1 && nz > 1 ||
        throw(ArgumentError("density visual requires a 3D field with all dimensions > 1"))
    mkpath(dirname(svg_path))
    lo = minimum(values)
    hi = maximum(values)
    mean_value = mean(values)
    threshold_value = Float64(threshold)
    selected = _density_visual_selected_indices(values, threshold_value, phase,
        Int(max_voxels))
    selected = sort(selected; by=index -> (index[1] + index[2] + index[3],
        index[3], index[1]))

    width = 1120
    height = 720
    iso_cx = 290.0
    iso_y0 = 430.0
    sx = 13.0
    sy = 7.2
    sz = 13.8
    radius = max(2.2, min(6.0, 54.0 / maximum(size(values))))
    slice_cell = min(15.0, 176.0 / maximum(size(values)))
    slice_x = 650.0
    slice_y = 108.0
    slice_gap = 204.0
    title_text = _svg_escape_text(title)
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='$(width)' height='$(height)' viewBox='0 0 $(width) $(height)'>")
        println(io, "<rect x='0' y='0' width='$(width)' height='$(height)' fill='white'/>")
        println(io, "<text x='$(width / 2)' y='34' text-anchor='middle' font-family='Arial' font-size='20' font-weight='bold'>$(title_text)</text>")
        println(io, @sprintf("<text x='%d' y='58' text-anchor='middle' font-family='Arial' font-size='12'>dims %dx%dx%d, min %.6g, mean %.6g, max %.6g, threshold %.6g, phase %s</text>",
            width ÷ 2, nx, ny, nz, lo, mean_value, hi, threshold_value,
            String(phase)))
        println(io, "<text x='70' y='88' font-family='Arial' font-size='15' font-weight='bold'>isometric voxel projection</text>")
        println(io, "<text x='70' y='108' font-family='Arial' font-size='11'>selected voxels are density $(phase == :above ? ">=" : phase == :below ? "<=" : "relative to") threshold; color encodes density</text>")
        println(io, "<line x1='$(iso_cx)' y1='$(iso_y0)' x2='$(iso_cx + nx * sx)' y2='$(iso_y0 + nx * sy)' stroke='#777'/>")
        println(io, "<line x1='$(iso_cx)' y1='$(iso_y0)' x2='$(iso_cx - ny * sx)' y2='$(iso_y0 + ny * sy)' stroke='#777'/>")
        println(io, "<line x1='$(iso_cx)' y1='$(iso_y0)' x2='$(iso_cx)' y2='$(iso_y0 - nz * sz)' stroke='#777'/>")
        println(io, "<text x='$(iso_cx + nx * sx + 12)' y='$(iso_y0 + nx * sy + 4)' font-family='Arial' font-size='11'>x</text>")
        println(io, "<text x='$(iso_cx - ny * sx - 18)' y='$(iso_y0 + ny * sy + 4)' font-family='Arial' font-size='11'>y</text>")
        println(io, "<text x='$(iso_cx + 8)' y='$(iso_y0 - nz * sz - 8)' font-family='Arial' font-size='11'>z</text>")
        for index in selected
            i, j, k = Tuple(index)
            x = iso_cx + (i - j) * sx
            y = iso_y0 + (i + j) * sy - k * sz
            color = _density_visual_color(values[index], lo, hi)
            opacity = phase == :all ? 0.42 : 0.72
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='%.3f' fill='%s' fill-opacity='%.3f' stroke='#222' stroke-opacity='0.25' stroke-width='0.25'/>",
                x, y, radius, color, opacity))
        end
        println(io, @sprintf("<text x='70' y='665' font-family='Arial' font-size='11'>voxel markers shown: %d of %d selected cells</text>",
            length(selected), count(index -> phase == :above ?
                values[index] >= threshold_value : phase == :below ?
                values[index] <= threshold_value : true, CartesianIndices(values))))

        cx = cld(nx, 2)
        cy = cld(ny, 2)
        cz = cld(nz, 2)
        _write_density_slice_svg(io, values, :xy, cz, slice_x, slice_y,
            slice_cell, lo, hi)
        _write_density_slice_svg(io, values, :xz, cy, slice_x,
            slice_y + slice_gap, slice_cell, lo, hi)
        _write_density_slice_svg(io, values, :yz, cx, slice_x,
            slice_y + 2 * slice_gap, slice_cell, lo, hi)

        legend_x = 930.0
        legend_y = 104.0
        println(io, "<text x='$(legend_x)' y='$(legend_y - 14)' font-family='Arial' font-size='12' font-weight='bold'>density color scale</text>")
        for n in 0:60
            value = lo + (hi - lo) * n / 60
            color = _density_visual_color(value, lo, hi)
            println(io, @sprintf("<rect x='%.3f' y='%.3f' width='3.2' height='18' fill='%s'/>",
                legend_x + 3.2 * n, legend_y, color))
        end
        println(io, @sprintf("<text x='%.3f' y='%.3f' font-family='Arial' font-size='10' text-anchor='start'>%.3g</text>",
            legend_x, legend_y + 34.0, lo))
        println(io, @sprintf("<text x='%.3f' y='%.3f' font-family='Arial' font-size='10' text-anchor='end'>%.3g</text>",
            legend_x + 3.2 * 60, legend_y + 34.0, hi))
        println(io, "</svg>")
    end
    return String(svg_path)
end

function _write_analysis_comparison_svg(csv_path::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_numeric(csv_path)
    mkpath(outdir)
    stem = splitext(basename(csv_path))[1]
    svg_path = joinpath(outdir, stem * ".svg")
    isempty(rows) && return svg_path
    is_dpivsc = startswith(basename(csv_path), "dPivsC_")
    is_pivsa = startswith(basename(csv_path), "PivsA_")
    axis_index = findfirst(==("axis"), header)
    mc_index = findfirst(==("mc_pressure"), header)
    cl_index = findfirst(==("cl_pressure"), header)
    dfm_index = findfirst(==("dfm_pressure"), header)
    one_loop_index = findfirst(==("one_loop"), header)
    transform_x(x) = is_dpivsc ? log10(x) : x
    transform_y(y) = is_dpivsc ? log10(-y) : y
    valid_y(y) = is_dpivsc ? (isfinite(y) && y < 0.0) : isfinite(y)
    xs = [transform_x(row[axis_index]) for row in rows if row[axis_index] > 0.0]
    ys = Float64[]
    for row in rows
        for idx in (mc_index, cl_index, dfm_index, one_loop_index)
            idx === nothing && continue
            idx <= length(row) && valid_y(row[idx]) && push!(ys, transform_y(row[idx]))
        end
    end
    isempty(ys) && push!(ys, 0.0)
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = _expand_plot_range(extrema(ys)...)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    label_value(v) = begin
        actual = is_dpivsc ? 10.0^v : v
        if abs(actual) >= 100 || abs(actual) < 0.01
            @sprintf("%.1e", actual)
        elseif abs(actual) >= 10
            @sprintf("%.1f", actual)
        else
            @sprintf("%.3g", actual)
        end
    end
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    xlabel = is_pivsa ? "A" : (is_dpivsc ? "C (log scale)" : "C")
    ylabel = is_dpivsc ? "-(Pi - Pi_MF) (log scale)" : "Pi"
    plot_title = replace(stem, "_" => " ")
    colors = Dict("mc_pressure" => "#1f77b4", "cl_pressure" => "#d62728", "dfm_pressure" => "#2ca02c", "one_loop" => "#9467bd")
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420' viewBox='0 0 640 420'>")
        println(io, "<title>$plot_title</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>$plot_title</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        for tick in x_minor_ticks
            x = x_plot(tick)
            println(io, @sprintf("<line class='x-minor-tick' x1='%.3f' y1='360' x2='%.3f' y2='363' stroke='black'/>", x, x))
        end
        for tick in y_minor_ticks
            y = y_plot(tick)
            println(io, @sprintf("<line class='y-minor-tick' x1='67' y1='%.3f' x2='70' y2='%.3f' stroke='black'/>", y, y))
        end
        for tick in xticks
            x = x_plot(tick)
            println(io, @sprintf("<line class='x-major-tick' x1='%.3f' y1='360' x2='%.3f' y2='366' stroke='black'/>", x, x))
            println(io, @sprintf("<text class='x-tick-label' x='%.3f' y='382' font-size='11' text-anchor='middle'>%s</text>", x, label_value(tick)))
        end
        for tick in yticks
            y = y_plot(tick)
            println(io, @sprintf("<line class='y-major-tick' x1='64' y1='%.3f' x2='70' y2='%.3f' stroke='black'/>", y, y))
            println(io, @sprintf("<text class='y-tick-label' x='58' y='%.3f' font-size='11' text-anchor='end'>%s</text>", y + 4, label_value(tick)))
        end
        for series in ("mc_pressure", "cl_pressure", "dfm_pressure", "one_loop")
            idx = findfirst(==(series), header)
            idx === nothing && continue
            points = String[]
            for row in rows
                idx <= length(row) || continue
                row[axis_index] > 0.0 || continue
                valid_y(row[idx]) || continue
                xval = transform_x(row[axis_index])
                yval = transform_y(row[idx])
                x = x_plot(xval)
                y = y_plot(yval)
                push!(points, @sprintf("%.3f,%.3f", x, y))
                println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='3' fill='%s'/>", x, y, colors[series]))
            end
            isempty(points) || println(io, "<polyline points='$(join(points, " "))' fill='none' stroke='$(colors[series])' stroke-width='1.5'/>")
        end
        println(io, "<text x='390' y='68' font-size='12' fill='#1f77b4'>MC</text>")
        println(io, "<text x='390' y='86' font-size='12' fill='#d62728'>CL</text>")
        println(io, "<text x='390' y='104' font-size='12' fill='#2ca02c'>DFM</text>")
        println(io, "<text x='390' y='122' font-size='12' fill='#9467bd'>One-loop</text>")
        println(io, "<text class='x-axis-label' x='335' y='410' font-size='13' text-anchor='middle'>$xlabel</text>")
        println(io, "<text class='y-axis-label' x='14' y='220' font-size='13' text-anchor='middle' transform='rotate(-90 14 220)'>$ylabel</text>")
        println(io, "</svg>")
    end
    return svg_path
end

function _write_direct_floor_sensitivity_svg(csv_path::AbstractString, outdir::AbstractString)
    mkpath(outdir)
    header, rows = _read_csv_numeric(csv_path)
    svg_path = joinpath(outdir, "direct_floor_sensitivity.svg")
    isempty(rows) && return svg_path

    phi_idx = findfirst(==("phi_min"), header)
    c_idx = findfirst(==("C"), header)
    mc_idx = findfirst(==("mc_pressure"), header)
    err_idx = findfirst(==("mc_error"), header)
    dfm_idx = findfirst(==("dfm_pressure"), header)
    cl_idx = findfirst(==("cl_pressure_nearest"), header)
    phi_idx === nothing && throw(ArgumentError("floor-sensitivity CSV missing phi_min"))
    c_idx === nothing && throw(ArgumentError("floor-sensitivity CSV missing C"))
    mc_idx === nothing && throw(ArgumentError("floor-sensitivity CSV missing mc_pressure"))

    valid_rows = [row for row in rows if length(row) >= max(phi_idx, c_idx, mc_idx) &&
                  isfinite(row[phi_idx]) && row[phi_idx] > 0.0 && isfinite(row[mc_idx])]
    isempty(valid_rows) && return svg_path
    sort!(valid_rows; by=row -> row[phi_idx])

    xs = log10.([row[phi_idx] for row in valid_rows])
    y_values = Float64[]
    for row in valid_rows
        push!(y_values, row[mc_idx])
        if err_idx !== nothing && length(row) >= err_idx && isfinite(row[err_idx])
            push!(y_values, row[mc_idx] - abs(row[err_idx]))
            push!(y_values, row[mc_idx] + abs(row[err_idx]))
        end
        if dfm_idx !== nothing && length(row) >= dfm_idx && isfinite(row[dfm_idx])
            push!(y_values, row[dfm_idx])
        end
        if cl_idx !== nothing && length(row) >= cl_idx && isfinite(row[cl_idx])
            push!(y_values, row[cl_idx])
        end
        push!(y_values, mean_field_pressure(1.0, row[c_idx]))
    end
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = _expand_plot_range(extrema(y_values)...)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=7)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    phi_label(v) = _format_tick_label(10.0^Float64(v))

    c_value = first(valid_rows)[c_idx]
    dfm_value = NaN
    if dfm_idx !== nothing
        for row in valid_rows
            if length(row) >= dfm_idx && isfinite(row[dfm_idx])
                dfm_value = row[dfm_idx]
                break
            end
        end
    end
    cl_value = NaN
    if cl_idx !== nothing
        for row in valid_rows
            if length(row) >= cl_idx && isfinite(row[cl_idx])
                cl_value = row[cl_idx]
                break
            end
        end
    end
    mean_field = mean_field_pressure(1.0, c_value)

    reference_line(io, value, color, dash) = begin
        isfinite(value) || return
        y = y_plot(value)
        println(io, @sprintf("<line x1='70' y1='%.3f' x2='600' y2='%.3f' stroke='%s' stroke-width='1.4' stroke-dasharray='%s'/>", y, y, color, dash))
    end

    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420' viewBox='0 0 640 420'>")
        println(io, "<title>Direct nonlinear floor sensitivity</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='40' y='35' font-size='18'>Direct nonlinear floor sensitivity</text>")
        println(io, @sprintf("<text x='40' y='54' font-size='12' fill='#555'>C = %.6g, lower-bound-regularized direct Arianna MC</text>", c_value))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
            x_label=phi_label, y_label=_format_tick_label)
        reference_line(io, cl_value, "#d62728", "6 4")
        reference_line(io, dfm_value, "#2ca02c", "4 3")
        reference_line(io, mean_field, "#9467bd", "2 3")

        points = String[]
        for row in valid_rows
            xval = log10(row[phi_idx])
            x = x_plot(xval)
            y = y_plot(row[mc_idx])
            push!(points, @sprintf("%.3f,%.3f", x, y))
            if err_idx !== nothing && length(row) >= err_idx && isfinite(row[err_idx])
                err = 280 * abs(row[err_idx]) / spany
                println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='#1f77b4'/>", x, y - err, x, y + err))
                println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='#1f77b4'/>", x - 4, y - err, x + 4, y - err))
                println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='#1f77b4'/>", x - 4, y + err, x + 4, y + err))
            end
            println(io, @sprintf("<circle class='mc-direct-point' cx='%.3f' cy='%.3f' r='4' fill='#1f77b4'/>", x, y))
        end
        isempty(points) || println(io, "<polyline class='mc-direct-line' points='$(join(points, " "))' fill='none' stroke='#1f77b4' stroke-width='2'/>")
        println(io, "<text x='405' y='76' font-size='12' fill='#1f77b4'>MC direct</text>")
        println(io, "<text x='405' y='94' font-size='12' fill='#d62728'>CL nearest</text>")
        println(io, "<text x='405' y='112' font-size='12' fill='#2ca02c'>DFM grid</text>")
        println(io, "<text x='405' y='130' font-size='12' fill='#9467bd'>Mean field</text>")
        println(io, "<text class='x-axis-label' x='335' y='410' font-size='14' text-anchor='middle'>phi_min</text>")
        println(io, "<text class='y-axis-label' x='15' y='210' font-size='14' text-anchor='middle' transform='rotate(-90 15 210)'>Pi</text>")
        println(io, "</svg>")
    end
    return svg_path
end

