function _gaussian_mode_chain_estimate(
    contributions::AbstractVector{<:Real},
    mean_field::Real,
    samples::Integer,
    rng::AbstractRNG,
)
    sample_count = max(1, Int(samples))
    mode_count = length(contributions)
    mode_count == 0 && return (pressure=Float64(mean_field), stderr=0.0, sample_count=sample_count)
    values = Vector{Float64}(undef, sample_count)
    for idx in eachindex(values)
        values[idx] = Float64(contributions[rand(rng, 1:mode_count)])
    end
    correction_mean = mode_count * mean(values)
    correction_stderr = sample_count <= 1 ? 0.0 : mode_count * std(values; corrected=true) / sqrt(sample_count)
    return (
        pressure=Float64(mean_field) + correction_mean,
        stderr=correction_stderr,
        sample_count=sample_count,
    )
end

function _gaussian_field_chain_estimate(
    terms::AbstractVector,
    mean_field::Real,
    volume::Real,
    samples::Integer,
    rng::AbstractRNG,
)
    sample_count = max(1, Int(samples))
    mode_count = length(terms)
    mode_count == 0 && return (pressure=Float64(mean_field), stderr=0.0, sample_count=sample_count)
    V = Float64(volume)
    values = Vector{Float64}(undef, sample_count)
    for idx in eachindex(values)
        term = terms[rand(rng, 1:mode_count)]
        amplitude = randn(rng) / sqrt(term.precision)
        values[idx] = mode_count * (-0.5 * (term.log1py - term.yz * abs2(amplitude)) / V)
    end
    correction_mean = mean(values)
    correction_stderr = sample_count <= 1 ? 0.0 : std(values; corrected=true) / sqrt(sample_count)
    return (
        pressure=Float64(mean_field) + correction_mean,
        stderr=correction_stderr,
        sample_count=sample_count,
    )
end

function _gaussian_field_configuration_chain_estimate(
    terms::AbstractVector,
    mean_field::Real,
    volume::Real,
    samples::Integer,
    rng::AbstractRNG,
)
    sample_count = max(1, Int(samples))
    mode_count = length(terms)
    mode_count == 0 && return (pressure=Float64(mean_field), stderr=0.0, sample_count=sample_count)
    V = Float64(volume)
    values = Vector{Float64}(undef, sample_count)
    for idx in eachindex(values)
        correction = 0.0
        for term in terms
            amplitude = randn(rng) / sqrt(term.precision)
            correction += -0.5 * (term.log1py - term.yz * abs2(amplitude)) / V
        end
        values[idx] = correction
    end
    correction_mean = mean(values)
    correction_stderr = sample_count <= 1 ? 0.0 : std(values; corrected=true) / sqrt(sample_count)
    return (
        pressure=Float64(mean_field) + correction_mean,
        stderr=correction_stderr,
        sample_count=sample_count,
    )
end

function _gaussian_mode_pressure_summary(
    params::HEURPParams,
    grid::Grid3D;
    samples=20_000,
    chains=4,
    seed=1,
    pressure_tolerance=0.5,
    reference_sigma_tolerance=5.0,
)
    sample_count = max(1, Int(samples))
    chain_count = max(1, Int(chains))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    sigma_tolerance = Float64(reference_sigma_tolerance)
    sigma_tolerance >= 0.0 || throw(ArgumentError("reference_sigma_tolerance must be nonnegative"))
    contributions = _dfm_pressure_mode_contributions(params, grid)
    mean_field = mean_field_pressure(params.B, params.C)
    exact_dfm = mean_field + sum(contributions)
    chain_estimates = Any[]
    for chain_idx in 1:chain_count
        rng = StableRNG(seed + chain_idx)
        push!(chain_estimates, _gaussian_mode_chain_estimate(contributions, mean_field, sample_count, rng))
    end
    chain_pressures = [estimate.pressure for estimate in chain_estimates]
    chain_stderrs = [estimate.stderr for estimate in chain_estimates]
    mc_pressure = mean(chain_pressures)
    within_stderr = sqrt(sum(abs2, chain_stderrs)) / chain_count
    chain_pressure_std = chain_count <= 1 ? 0.0 : std(chain_pressures; corrected=true)
    between_stderr = chain_count <= 1 ? 0.0 : chain_pressure_std / sqrt(chain_count)
    mc_error = max(within_stderr, between_stderr, 1.0e-12)
    pressure_error_pass = _pressure_error_pass((stderr=mc_error,), tolerance)
    reference_error = abs(mc_pressure - exact_dfm)
    reference_zscore = mc_error <= eps(Float64) ? (reference_error <= eps(Float64) ? 0.0 : Inf) :
                       reference_error / mc_error
    reference_limit = isfinite(tolerance) ? max(tolerance, sigma_tolerance * mc_error) : Inf
    reference_agreement_pass = reference_error <= reference_limit ? 1.0 : 0.0
    required_effective_sample_size = if !isfinite(tolerance)
        Float64(sample_count * chain_count)
    elseif tolerance == 0.0
        mc_error <= 0.0 ? Float64(sample_count * chain_count) : Inf
    else
        max(1.0, Float64(sample_count * chain_count) * (mc_error / tolerance)^2)
    end
    required_samples_per_chain = isfinite(required_effective_sample_size) ?
                                 max(1, ceil(Int, required_effective_sample_size / chain_count)) :
                                 Inf
    sampling_budget_pass = required_effective_sample_size <= Float64(sample_count * chain_count) ? 1.0 : 0.0
    diagnostic_pass = min(pressure_error_pass, reference_agreement_pass, sampling_budget_pass)
    return (
        mc_pressure=mc_pressure,
        mc_error=mc_error,
        dfm_pressure=exact_dfm,
        mean_field=mean_field,
        stable_mode_count=length(contributions),
        samples=sample_count,
        max_samples=sample_count,
        sampling_attempts=1,
        sample_growth=1.0,
        chain_count=chain_count,
        within_chain_stderr=within_stderr,
        between_chain_stderr=between_stderr,
        chain_pressure_std=chain_pressure_std,
        effective_sample_size=Float64(sample_count * chain_count),
        reference_error=reference_error,
        reference_zscore=reference_zscore,
        reference_tolerance=tolerance,
        reference_sigma_tolerance=sigma_tolerance,
        reference_agreement_pass=reference_agreement_pass,
        required_effective_sample_size=required_effective_sample_size,
        required_samples_per_chain=required_samples_per_chain,
        sampling_budget_pass=sampling_budget_pass,
        pressure_tolerance=tolerance,
        pressure_error_pass=pressure_error_pass,
        diagnostic_pass=diagnostic_pass,
        alpha=params.alpha,
        sampler="gaussian_mode_mc",
    )
end

function _gaussian_field_pressure_summary(
    params::HEURPParams,
    grid::Grid3D;
    samples=20_000,
    chains=4,
    seed=1,
    pressure_tolerance=0.5,
    reference_sigma_tolerance=5.0,
)
    sample_count = max(1, Int(samples))
    chain_count = max(1, Int(chains))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    sigma_tolerance = Float64(reference_sigma_tolerance)
    sigma_tolerance >= 0.0 || throw(ArgumentError("reference_sigma_tolerance must be nonnegative"))
    terms = _dfm_pressure_mode_terms(params, grid)
    mean_field = mean_field_pressure(params.B, params.C)
    exact_dfm = mean_field + sum((term.mean_contribution for term in terms); init=0.0)
    chain_estimates = Any[]
    for chain_idx in 1:chain_count
        rng = StableRNG(seed + chain_idx)
        push!(chain_estimates,
            _gaussian_field_chain_estimate(terms, mean_field, grid.volume, sample_count, rng))
    end
    chain_pressures = [estimate.pressure for estimate in chain_estimates]
    chain_stderrs = [estimate.stderr for estimate in chain_estimates]
    mc_pressure = mean(chain_pressures)
    within_stderr = sqrt(sum(abs2, chain_stderrs)) / chain_count
    chain_pressure_std = chain_count <= 1 ? 0.0 : std(chain_pressures; corrected=true)
    between_stderr = chain_count <= 1 ? 0.0 : chain_pressure_std / sqrt(chain_count)
    mc_error = max(within_stderr, between_stderr, 1.0e-12)
    pressure_error_pass = _pressure_error_pass((stderr=mc_error,), tolerance)
    reference_error = abs(mc_pressure - exact_dfm)
    reference_zscore = mc_error <= eps(Float64) ? (reference_error <= eps(Float64) ? 0.0 : Inf) :
                       reference_error / mc_error
    reference_limit = isfinite(tolerance) ? max(tolerance, sigma_tolerance * mc_error) : Inf
    reference_agreement_pass = reference_error <= reference_limit ? 1.0 : 0.0
    required_effective_sample_size = if !isfinite(tolerance)
        Float64(sample_count * chain_count)
    elseif tolerance == 0.0
        mc_error <= 0.0 ? Float64(sample_count * chain_count) : Inf
    else
        max(1.0, Float64(sample_count * chain_count) * (mc_error / tolerance)^2)
    end
    required_samples_per_chain = isfinite(required_effective_sample_size) ?
                                 max(1, ceil(Int, required_effective_sample_size / chain_count)) :
                                 Inf
    sampling_budget_pass = required_effective_sample_size <= Float64(sample_count * chain_count) ? 1.0 : 0.0
    diagnostic_pass = min(pressure_error_pass, reference_agreement_pass, sampling_budget_pass)
    return (
        mc_pressure=mc_pressure,
        mc_error=mc_error,
        dfm_pressure=exact_dfm,
        mean_field=mean_field,
        stable_mode_count=length(terms),
        samples=sample_count,
        max_samples=sample_count,
        sampling_attempts=1,
        sample_growth=1.0,
        chain_count=chain_count,
        within_chain_stderr=within_stderr,
        between_chain_stderr=between_stderr,
        chain_pressure_std=chain_pressure_std,
        effective_sample_size=Float64(sample_count * chain_count),
        reference_error=reference_error,
        reference_zscore=reference_zscore,
        reference_tolerance=tolerance,
        reference_sigma_tolerance=sigma_tolerance,
        reference_agreement_pass=reference_agreement_pass,
        required_effective_sample_size=required_effective_sample_size,
        required_samples_per_chain=required_samples_per_chain,
        sampling_budget_pass=sampling_budget_pass,
        pressure_tolerance=tolerance,
        pressure_error_pass=pressure_error_pass,
        diagnostic_pass=diagnostic_pass,
        alpha=params.alpha,
        sampler="gaussian_field_mc",
    )
end

