function _gaussian_mode_pressure_summary_until_pass(
    params::HEURPParams,
    grid::Grid3D;
    samples=20_000,
    max_samples=nothing,
    sample_growth=2.0,
    kwargs...,
)
    first_samples = max(1, Int(samples))
    max_sample_count = max_samples === nothing ? first_samples : max(first_samples, Int(max_samples))
    growth = max(1.1, Float64(sample_growth))
    current_samples = first_samples
    attempts = 0
    last_summary = nothing
    while true
        attempts += 1
        summary = _gaussian_mode_pressure_summary(
            params,
            grid;
            samples=current_samples,
            kwargs...,
        )
        last_summary = merge(summary, (
            max_samples=max_sample_count,
            sampling_attempts=attempts,
            sample_growth=growth,
        ))
        (summary.diagnostic_pass >= 0.5 || current_samples >= max_sample_count) && break
        required_samples = isfinite(summary.required_samples_per_chain) ?
                           ceil(Int, summary.required_samples_per_chain) :
                           current_samples + 1
        next_samples = min(
            max_sample_count,
            max(current_samples + 1, ceil(Int, current_samples * growth), required_samples),
        )
        next_samples == current_samples && break
        current_samples = next_samples
    end
    return last_summary
end

