function _gaussian_estimator_metadata(estimator)
    estimator_symbol = Symbol(estimator)
    if estimator_symbol == :mode
        return (
            symbol=estimator_symbol,
            sampler="gaussian_mode_mc",
            formula_id="finite_grid_gaussian_mode_sum",
        )
    elseif estimator_symbol == :field
        return (
            symbol=estimator_symbol,
            sampler="gaussian_field_mc",
            formula_id="finite_grid_gaussian_field_amplitude_pressure",
        )
    elseif estimator_symbol == :field_configuration
        return (
            symbol=estimator_symbol,
            sampler="gaussian_field_configuration_mc",
            formula_id="finite_grid_gaussian_field_configuration_pressure",
        )
    end
    throw(ArgumentError("estimator must be :mode, :field, or :field_configuration"))
end

function _gaussian_pressure_summary_until_pass(
    estimator_symbol::Symbol,
    params::HEURPParams,
    grid::Grid3D;
    kwargs...,
)
    if estimator_symbol == :field
        return _gaussian_field_pressure_summary_until_pass(params, grid; kwargs...)
    elseif estimator_symbol == :field_configuration
        return _gaussian_field_configuration_pressure_summary_until_pass(params, grid; kwargs...)
    elseif estimator_symbol == :mode
        return _gaussian_mode_pressure_summary_until_pass(params, grid; kwargs...)
    end
    throw(ArgumentError("estimator must be :mode, :field, or :field_configuration"))
end

const GAUSSIAN_CL_CONTEXT_HEADER = [
    "mc_minus_dfm",
    "mc_dfm_zscore",
    "mc_minus_cl",
    "dfm_minus_cl",
    "cl_model_residual",
    "mc_cl_combined_zscore",
    "cl_context_pass",
]

function _zscore_from_error(delta::Real, stderr::Real)
    err = Float64(stderr)
    abs_delta = abs(Float64(delta))
    return err <= eps(Float64) ? (abs_delta <= eps(Float64) ? 0.0 : Inf) : abs_delta / err
end

function _gaussian_cl_context(summary, cl_pressure::Real, cl_error::Real)
    mc_minus_dfm = summary.mc_pressure - summary.dfm_pressure
    mc_dfm_zscore = _zscore_from_error(mc_minus_dfm, summary.mc_error)
    if !isfinite(Float64(cl_pressure))
        return (mc_minus_dfm, mc_dfm_zscore, NaN, NaN, NaN, NaN, NaN)
    end
    mc_minus_cl = summary.mc_pressure - Float64(cl_pressure)
    dfm_minus_cl = summary.dfm_pressure - Float64(cl_pressure)
    cl_model_residual = mc_minus_cl - dfm_minus_cl
    cl_err = isfinite(Float64(cl_error)) ? Float64(cl_error) : 0.0
    combined_stderr = sqrt(summary.mc_error^2 + cl_err^2)
    mc_cl_zscore = _zscore_from_error(mc_minus_cl, combined_stderr)
    return (
        mc_minus_dfm,
        mc_dfm_zscore,
        mc_minus_cl,
        dfm_minus_cl,
        cl_model_residual,
        mc_cl_zscore,
        summary.reference_agreement_pass,
    )
end

function run_gaussian_perturbation_mc(
    outdir::AbstractString;
    mode=:production,
    Nx=nothing,
    C_values=nothing,
    samples=20_000,
    max_samples=nothing,
    sample_growth=2.0,
    chains=4,
    seed=1,
    pressure_tolerance=0.5,
    estimator=:mode,
)
    mkpath(outdir)
    cfg = run_config(mode)
    effective_Nx = Nx === nothing ? cfg.target_Nx : Int(Nx)
    effective_Nx >= 2 || throw(ArgumentError("Nx must be at least 2"))
    sample_count = max(1, Int(samples))
    chain_count = max(1, Int(chains))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    max_sample_count = max_samples === nothing ? sample_count : max(sample_count, Int(max_samples))
    growth = max(1.1, Float64(sample_growth))
    estimator_metadata = _gaussian_estimator_metadata(estimator)
    estimator_symbol = estimator_metadata.symbol
    sampler_label = estimator_metadata.sampler
    formula_id = estimator_metadata.formula_id
    sampled_C_values = C_values === nothing ? cfg.C_values : Float64.(C_values)
    effective_cfg = RunConfig(Symbol(mode), cfg.dimension, effective_Nx, cfg.target_Nx, cfg.L, cfg.A, cfg.B,
        sampled_C_values, cfg.manuscript_grade, cfg.alpha, cfg.analysis_source)
    cl_data = isfile(cfg.analysis_source) ? read_cl_pressure(cfg.analysis_source) : nothing
    pressure_rows = Any[]
    diag_rows = Any[]
    for (cidx, C) in enumerate(sampled_C_values)
        grid = Grid3D(effective_Nx, cfg.L)
        params = HEURPParams(A=cfg.A, B=cfg.B, C=C, alpha=cfg.alpha)
        summary = _gaussian_pressure_summary_until_pass(
            estimator_symbol,
            params,
            grid;
            samples=sample_count,
            max_samples=max_sample_count,
            sample_growth=growth,
            chains=chain_count,
            seed=seed + 100_000 * (cidx - 1),
            pressure_tolerance=tolerance,
        )
        if cl_data === nothing
            cl_pressure, cl_error = NaN, NaN
        else
            cl_pressure, cl_error = _nearest_cl(cl_data, C)
        end
        cl_context = _gaussian_cl_context(summary, cl_pressure, cl_error)
        push!(pressure_rows, (
            C,
            summary.mc_pressure,
            summary.mc_error,
            summary.dfm_pressure,
            cl_pressure,
            cl_error,
            summary.mean_field,
            summary.stable_mode_count,
            summary.samples,
            summary.max_samples,
            summary.sampling_attempts,
            summary.sample_growth,
            summary.chain_count,
            summary.within_chain_stderr,
            summary.between_chain_stderr,
            summary.chain_pressure_std,
            summary.effective_sample_size,
            summary.reference_error,
            summary.reference_zscore,
            summary.reference_tolerance,
            summary.reference_sigma_tolerance,
            summary.reference_agreement_pass,
            cl_context...,
            summary.required_effective_sample_size,
            summary.required_samples_per_chain,
            summary.sampling_budget_pass,
            summary.pressure_tolerance,
            summary.pressure_error_pass,
            summary.diagnostic_pass,
            summary.alpha,
            summary.sampler,
        ))
        push!(diag_rows, (
            C,
            summary.samples,
            summary.max_samples,
            summary.sampling_attempts,
            summary.sample_growth,
            summary.chain_count,
            summary.within_chain_stderr,
            summary.between_chain_stderr,
            summary.chain_pressure_std,
            summary.stable_mode_count,
            summary.mc_pressure,
            summary.mc_error,
            summary.dfm_pressure,
            cl_pressure,
            cl_error,
            summary.mean_field,
            summary.effective_sample_size,
            summary.reference_error,
            summary.reference_zscore,
            summary.reference_tolerance,
            summary.reference_sigma_tolerance,
            summary.reference_agreement_pass,
            cl_context...,
            summary.required_effective_sample_size,
            summary.required_samples_per_chain,
            summary.sampling_budget_pass,
            summary.pressure_tolerance,
            summary.pressure_error_pass,
            summary.diagnostic_pass,
            summary.alpha,
            summary.sampler,
        ))
    end
    pressure_csv = _write_table(joinpath(outdir, "gaussian_pressure_comparison.csv"),
        [
            "C",
            "mc_pressure",
            "mc_error",
            "dfm_pressure",
            "cl_pressure_nearest",
            "cl_error_nearest",
            "mean_field",
            "stable_mode_count",
            "samples",
            "max_samples",
            "sampling_attempts",
            "sample_growth",
            "chain_count",
            "within_chain_stderr",
            "between_chain_stderr",
            "chain_pressure_std",
            "effective_sample_size",
            "reference_error",
            "reference_zscore",
            "reference_tolerance",
            "reference_sigma_tolerance",
            "reference_agreement_pass",
            GAUSSIAN_CL_CONTEXT_HEADER...,
            "required_effective_sample_size",
            "required_samples_per_chain",
            "sampling_budget_pass",
            "pressure_tolerance",
            "pressure_error_pass",
            "diagnostic_pass",
            "alpha",
            "sampler",
        ], pressure_rows)
    diagnostics_csv = _write_table(joinpath(outdir, "gaussian_sampling_diagnostics.csv"),
        [
            "C",
            "samples",
            "max_samples",
            "sampling_attempts",
            "sample_growth",
            "chain_count",
            "within_chain_stderr",
            "between_chain_stderr",
            "chain_pressure_std",
            "stable_mode_count",
            "mc_pressure",
            "mc_error",
            "dfm_pressure",
            "cl_pressure_nearest",
            "cl_error_nearest",
            "mean_field",
            "effective_sample_size",
            "reference_error",
            "reference_zscore",
            "reference_tolerance",
            "reference_sigma_tolerance",
            "reference_agreement_pass",
            GAUSSIAN_CL_CONTEXT_HEADER...,
            "required_effective_sample_size",
            "required_samples_per_chain",
            "sampling_budget_pass",
            "pressure_tolerance",
            "pressure_error_pass",
            "diagnostic_pass",
            "alpha",
            "sampler",
        ], diag_rows)
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "sampler" => sampler_label,
            "mode" => string(mode),
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "dimension" => effective_cfg.dimension,
            "Nx" => effective_cfg.Nx,
            "target_Nx" => effective_cfg.target_Nx,
            "L" => effective_cfg.L,
        ),
        "params" => Dict{String,Any}(
            "A" => effective_cfg.A,
            "B" => effective_cfg.B,
            "C_values" => _toml_value(sampled_C_values),
            "alpha" => effective_cfg.alpha,
        ),
        "sampling" => Dict{String,Any}(
            "samples" => sample_count,
            "max_samples" => max_sample_count,
            "sample_growth" => growth,
            "chains" => chain_count,
            "pressure_tolerance" => _toml_value(tolerance),
            "estimator" => string(estimator_symbol),
        ),
        "estimator" => Dict{String,Any}(
            "formula_id" => formula_id,
            "reference_function" => "dfm_pressure_discrete",
            "analysis_source" => effective_cfg.analysis_source,
        ),
        "environment" => _metadata_environment(),
        "outputs" => Dict{String,Any}(
            "pressure_csv" => pressure_csv,
            "diagnostics_csv" => diagnostics_csv,
        ),
    ))
    return SweepResult(pressure_csv, diagnostics_csv, effective_cfg)
end

function _write_gaussian_sample_size_text(
    outdir::AbstractString,
    csv_path::AbstractString,
    cfg::RunConfig,
    pressure_tolerance::Real;
    sampler_label::AbstractString="gaussian_mode_mc",
)
    header, rows = _read_csv_numeric(csv_path)
    path = joinpath(outdir, "gaussian_sample_size_study.md")
    samples_idx = findfirst(==("samples"), header)
    ess_idx = findfirst(==("effective_sample_size"), header)
    mc_idx = findfirst(==("mc_pressure"), header)
    err_idx = findfirst(==("mc_error"), header)
    dfm_idx = findfirst(==("dfm_pressure"), header)
    ref_idx = findfirst(==("reference_error"), header)
    z_idx = findfirst(==("reference_zscore"), header)
    scaled_idx = findfirst(==("error_times_sqrt_effective_sample_size"), header)
    budget_idx = findfirst(==("sampling_budget_pass"), header)
    pass_idx = findfirst(==("diagnostic_pass"), header)
    chain_idx = findfirst(==("chain_count"), header)
    mode_idx = findfirst(==("stable_mode_count"), header)
    first_row = isempty(rows) ? Float64[] : first(rows)
    last_row = isempty(rows) ? Float64[] : last(rows)
    scaled_values = scaled_idx === nothing ? Float64[] :
                    [row[scaled_idx] for row in rows if length(row) >= scaled_idx && isfinite(row[scaled_idx])]
    pass_count = pass_idx === nothing ? 0 :
                 count(row -> length(row) >= pass_idx && row[pass_idx] >= 0.5, rows)
    budget_pass_count = budget_idx === nothing ? 0 :
                        count(row -> length(row) >= budget_idx && row[budget_idx] >= 0.5, rows)
    sample_kind = sampler_label == "gaussian_field_mc" ? "field-amplitude sample" :
                  sampler_label == "gaussian_field_configuration_mc" ? "field-configuration sample" :
                  "mode sample"
    sample_unit(value) = isone(round(Int, value)) ? sample_kind : string(sample_kind, "s")
    sample_budget_label = string(sample_kind, " budgets")
    estimator_sentence = sampler_label == "gaussian_field_mc" ?
                         "The estimator samples independent Gaussian field-amplitudes for stable Fourier modes, so `samples * chains` is the effective independent samples count for the Gaussian path." :
                         sampler_label == "gaussian_field_configuration_mc" ?
                         "The estimator samples independent full Gaussian field configurations over all stable Fourier modes, so `samples * chains` is the effective independent configuration count for the Gaussian path." :
                         "The estimator samples Fourier-mode pressure contributions with replacement, so `samples * chains` is the effective independent samples count for the Gaussian path."
    open(path, "w") do io
        println(io, "Gaussian sample-size convergence study")
        println(io, "======================================")
        println(io)
        println(io, @sprintf("This study reruns the finite-grid Gaussian HE-URP pressure estimator at increasing independent %s.", sample_budget_label))
        println(io, estimator_sentence)
        println(io, @sprintf("The grid was Nx = %d, L = %.4g, alpha = %.3g, and the pressure tolerance was %.3g.", cfg.Nx, cfg.L, cfg.alpha, Float64(pressure_tolerance)))
        if !isempty(last_row) && samples_idx !== nothing && ess_idx !== nothing && chain_idx !== nothing
            println(io, @sprintf("The largest row used %.0f %s per chain, %.0f chains, and %.0f effective independent samples.", last_row[samples_idx], sample_unit(last_row[samples_idx]), last_row[chain_idx], last_row[ess_idx]))
        end
        if !isempty(last_row) && mc_idx !== nothing && err_idx !== nothing && dfm_idx !== nothing && ref_idx !== nothing && z_idx !== nothing
            println(io, @sprintf("At the largest budget, Pi_MC = %.6g +/- %.3g and Pi_DFM_grid = %.6g, giving absolute MC-vs-DFM error %.3g and z-score %.3g.", last_row[mc_idx], last_row[err_idx], last_row[dfm_idx], last_row[ref_idx], last_row[z_idx]))
        end
        if !isempty(first_row) && samples_idx !== nothing && err_idx !== nothing && !isempty(last_row)
            println(io, @sprintf("The standard error decreased from %.3g at %.0f %s per chain to %.3g at %.0f %s per chain.", first_row[err_idx], first_row[samples_idx], sample_unit(first_row[samples_idx]), last_row[err_idx], last_row[samples_idx], sample_unit(last_row[samples_idx])))
        end
        if !isempty(scaled_values)
            println(io, @sprintf("For independent Monte Carlo estimates, standard errors scale as 1/sqrt(N); the CSV records `error_times_sqrt_effective_sample_size`, which ranged from %.3g to %.3g.", minimum(scaled_values), maximum(scaled_values)))
        else
            println(io, "For independent Monte Carlo estimates, standard errors scale as 1/sqrt(N); the CSV records `error_times_sqrt_effective_sample_size` for that check.")
        end
        if mode_idx !== nothing && !isempty(last_row)
            println(io, @sprintf("The sampled correction contained %.0f stable Fourier modes.", last_row[mode_idx]))
        end
        println(io, @sprintf("The sampling-budget gate passed %.0f of %.0f rows, and the full diagnostic gate passed %.0f of %.0f rows.", budget_pass_count, length(rows), pass_count, length(rows)))
        if pass_count < length(rows)
            println(io, "Rows that fail at small budgets are retained intentionally; they show why short runs are diagnostic while the largest accepted budget is the manuscript-ready evidence.")
        else
            println(io, "All rows passed the configured gate; the largest budget still provides the tightest manuscript-ready uncertainty.")
        end
    end
    return path
end

function run_gaussian_sample_size_study(
    outdir::AbstractString;
    mode=:production,
    Nx=nothing,
    C=20.0,
    sample_counts=[1_000, 5_000, 20_000, 80_000],
    chains=4,
    seed=17,
    pressure_tolerance=0.5,
    estimator=:mode,
)
    mkpath(outdir)
    cfg = run_config(mode)
    effective_Nx = Nx === nothing ? cfg.target_Nx : Int(Nx)
    effective_Nx >= 2 || throw(ArgumentError("Nx must be at least 2"))
    raw_counts = sample_counts isa Integer ? [sample_counts] : collect(sample_counts)
    isempty(raw_counts) && throw(ArgumentError("sample_counts must contain at least one value"))
    sampled_counts = sort(unique(max(1, Int(count)) for count in raw_counts))
    chain_count = max(1, Int(chains))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    estimator_metadata = _gaussian_estimator_metadata(estimator)
    estimator_symbol = estimator_metadata.symbol
    sampler_label = estimator_metadata.sampler
    formula_id = estimator_metadata.formula_id
    C_value = Float64(C)
    effective_cfg = RunConfig(Symbol(mode), cfg.dimension, effective_Nx, cfg.target_Nx, cfg.L, cfg.A, cfg.B,
        [C_value], cfg.manuscript_grade, cfg.alpha, cfg.analysis_source)
    grid = Grid3D(effective_Nx, cfg.L)
    params = HEURPParams(A=cfg.A, B=cfg.B, C=C_value, alpha=cfg.alpha)
    cl_data = isfile(cfg.analysis_source) ? read_cl_pressure(cfg.analysis_source) : nothing
    cl_pressure, cl_error = cl_data === nothing ? (NaN, NaN) : _nearest_cl(cl_data, C_value)
    rows = Any[]
    for sample_count in sampled_counts
        summary = _gaussian_pressure_summary_until_pass(
            estimator_symbol,
            params,
            grid;
            samples=sample_count,
            max_samples=sample_count,
            chains=chain_count,
            seed=seed,
            pressure_tolerance=tolerance,
        )
        cl_context = _gaussian_cl_context(summary, cl_pressure, cl_error)
        push!(rows, (
            C_value,
            summary.samples,
            summary.chain_count,
            summary.effective_sample_size,
            summary.stable_mode_count,
            summary.mc_pressure,
            summary.mc_error,
            summary.within_chain_stderr,
            summary.between_chain_stderr,
            summary.chain_pressure_std,
            summary.dfm_pressure,
            cl_pressure,
            cl_error,
            summary.mean_field,
            summary.reference_error,
            summary.reference_zscore,
            summary.reference_tolerance,
            summary.reference_sigma_tolerance,
            summary.reference_agreement_pass,
            cl_context...,
            summary.mc_error * sqrt(summary.effective_sample_size),
            summary.reference_error * sqrt(summary.effective_sample_size),
            summary.required_effective_sample_size,
            summary.required_samples_per_chain,
            summary.sampling_budget_pass,
            summary.pressure_tolerance,
            summary.pressure_error_pass,
            summary.diagnostic_pass,
            summary.alpha,
            summary.sampler,
        ))
    end
    csv_path = _write_table(joinpath(outdir, "gaussian_sample_size_study.csv"),
        [
            "C",
            "samples",
            "chain_count",
            "effective_sample_size",
            "stable_mode_count",
            "mc_pressure",
            "mc_error",
            "within_chain_stderr",
            "between_chain_stderr",
            "chain_pressure_std",
            "dfm_pressure",
            "cl_pressure_nearest",
            "cl_error_nearest",
            "mean_field",
            "reference_error",
            "reference_zscore",
            "reference_tolerance",
            "reference_sigma_tolerance",
            "reference_agreement_pass",
            GAUSSIAN_CL_CONTEXT_HEADER...,
            "error_times_sqrt_effective_sample_size",
            "reference_error_times_sqrt_effective_sample_size",
            "required_effective_sample_size",
            "required_samples_per_chain",
            "sampling_budget_pass",
            "pressure_tolerance",
            "pressure_error_pass",
            "diagnostic_pass",
            "alpha",
            "sampler",
        ], rows)
    text_path = _write_gaussian_sample_size_text(outdir, csv_path, effective_cfg, tolerance;
        sampler_label=sampler_label)
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "sampler" => sampler_label,
            "mode" => "gaussian_sample_size_study",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "dimension" => effective_cfg.dimension,
            "Nx" => effective_cfg.Nx,
            "target_Nx" => effective_cfg.target_Nx,
            "L" => effective_cfg.L,
        ),
        "params" => Dict{String,Any}(
            "A" => effective_cfg.A,
            "B" => effective_cfg.B,
            "C" => C_value,
            "C_values" => _toml_value(effective_cfg.C_values),
            "alpha" => effective_cfg.alpha,
        ),
        "sampling" => Dict{String,Any}(
            "sample_counts" => sampled_counts,
            "chains" => chain_count,
            "pressure_tolerance" => _toml_value(tolerance),
            "estimator" => string(estimator_symbol),
        ),
        "estimator" => Dict{String,Any}(
            "formula_id" => formula_id,
            "reference_function" => "dfm_pressure_discrete",
            "analysis_source" => effective_cfg.analysis_source,
        ),
        "environment" => _metadata_environment(),
        "outputs" => Dict{String,Any}(
            "sample_size_csv" => csv_path,
            "sample_size_text" => text_path,
        ),
    ))
    return (csv=csv_path, text=text_path, config=effective_cfg)
end

const GAUSSIAN_ANALYSIS_DIAGNOSTIC_HEADER = [
    "stable_mode_count",
    "samples",
    "max_samples",
    "sampling_attempts",
    "sample_growth",
    "chain_count",
    "within_chain_stderr",
    "between_chain_stderr",
    "chain_pressure_std",
    "effective_sample_size",
    "reference_error",
    "reference_zscore",
    "reference_tolerance",
    "reference_sigma_tolerance",
    "reference_agreement_pass",
    GAUSSIAN_CL_CONTEXT_HEADER...,
    "required_effective_sample_size",
    "required_samples_per_chain",
    "sampling_budget_pass",
    "pressure_tolerance",
    "pressure_error_pass",
    "diagnostic_pass",
    "alpha",
    "sampler",
]

function _gaussian_analysis_diagnostics(summary, cl_pressure, cl_error)
    return (
        summary.stable_mode_count,
        summary.samples,
        summary.max_samples,
        summary.sampling_attempts,
        summary.sample_growth,
        summary.chain_count,
        summary.within_chain_stderr,
        summary.between_chain_stderr,
        summary.chain_pressure_std,
        summary.effective_sample_size,
        summary.reference_error,
        summary.reference_zscore,
        summary.reference_tolerance,
        summary.reference_sigma_tolerance,
        summary.reference_agreement_pass,
        _gaussian_cl_context(summary, cl_pressure, cl_error)...,
        summary.required_effective_sample_size,
        summary.required_samples_per_chain,
        summary.sampling_budget_pass,
        summary.pressure_tolerance,
        summary.pressure_error_pass,
        summary.diagnostic_pass,
        summary.alpha,
        summary.sampler,
    )
end

function run_gaussian_analysis_comparison_suite(
    outdir::AbstractString;
    Nx=64,
    max_points_per_figure=3,
    figure_names=nothing,
    samples=300_000,
    max_samples=nothing,
    sample_growth=2.0,
    chains=4,
    seed=3701,
    pressure_tolerance=0.5,
    estimator=:mode,
)
    mkpath(outdir)
    cfg = analysis_reference_config()
    effective_Nx = Int(Nx)
    effective_Nx >= 2 || throw(ArgumentError("Nx must be at least 2"))
    sample_count = max(1, Int(samples))
    chain_count = max(1, Int(chains))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    max_sample_count = max_samples === nothing ? sample_count : max(sample_count, Int(max_samples))
    growth = max(1.1, Float64(sample_growth))
    estimator_metadata = _gaussian_estimator_metadata(estimator)
    estimator_symbol = estimator_metadata.symbol
    sampler_label = estimator_metadata.sampler
    formula_id = estimator_metadata.formula_id
    cl_data = read_cl_pressure(cfg.analysis_source)
    specs = analysis_figure_specs()
    if figure_names !== nothing
        wanted = Set(String.(figure_names))
        specs = [spec for spec in specs if spec.name in wanted]
    end
    header = vcat(
        ["axis", "A", "B", "C", "mc_pressure", "mc_error", "mean_field", "one_loop",
            "dfm_pressure", "cl_pressure", "cl_error"],
        GAUSSIAN_ANALYSIS_DIAGNOSTIC_HEADER,
    )
    csv_paths = String[]
    for (spec_idx, spec) in enumerate(specs)
        rows = Any[]
        axis_values = _axis_values(spec, cl_data, max_points_per_figure)
        for (point_idx, axis_value) in enumerate(axis_values)
            A = spec.kind == :PivsA ? axis_value : spec.A
            B = spec.B
            C = spec.kind == :PivsA ? spec.C : axis_value
            grid = Grid3D(effective_Nx, cfg.L)
            params = HEURPParams(A=A, B=B, C=C, alpha=cfg.alpha)
            summary = _gaussian_pressure_summary_until_pass(
                estimator_symbol,
                params,
                grid;
                samples=sample_count,
                max_samples=max_sample_count,
                sample_growth=growth,
                chains=chain_count,
                seed=seed + 100_000 * (spec_idx - 1) + point_idx,
                pressure_tolerance=tolerance,
            )
            one_loop = one_loop_pressure_smeared(B, C; alpha=cfg.alpha)
            cl_pressure, cl_error = B == 1.0 ? _nearest_cl(cl_data, C) : (NaN, NaN)
            diagnostics = _gaussian_analysis_diagnostics(summary, cl_pressure, cl_error)
            if spec.kind == :dPivsC
                push!(rows, (
                    axis_value, A, B, C,
                    summary.mc_pressure - summary.mean_field,
                    summary.mc_error,
                    0.0,
                    one_loop - summary.mean_field,
                    summary.dfm_pressure - summary.mean_field,
                    cl_pressure - summary.mean_field,
                    cl_error,
                    diagnostics...,
                ))
            else
                push!(rows, (
                    axis_value, A, B, C,
                    summary.mc_pressure,
                    summary.mc_error,
                    summary.mean_field,
                    one_loop,
                    summary.dfm_pressure,
                    cl_pressure,
                    cl_error,
                    diagnostics...,
                ))
            end
        end
        csv_path = _write_table(joinpath(outdir, spec.name * "_gaussian_mc_comparison.csv"), header, rows)
        _write_analysis_comparison_svg(csv_path, joinpath(outdir, "figures"))
        push!(csv_paths, csv_path)
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "sampler" => sampler_label,
            "mode" => "gaussian_analysis_comparison",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "dimension" => cfg.dimension,
            "Nx" => effective_Nx,
            "target_Nx" => cfg.target_Nx,
            "L" => cfg.L,
        ),
        "params" => Dict{String,Any}(
            "alpha" => cfg.alpha,
            "figure_names" => [spec.name for spec in specs],
        ),
        "sampling" => Dict{String,Any}(
            "samples" => sample_count,
            "max_samples" => max_sample_count,
            "sample_growth" => growth,
            "chains" => chain_count,
            "pressure_tolerance" => _toml_value(tolerance),
            "max_points_per_figure" => Int(max_points_per_figure),
            "estimator" => string(estimator_symbol),
        ),
        "estimator" => Dict{String,Any}(
            "formula_id" => formula_id,
            "reference_function" => "dfm_pressure_discrete",
            "analysis_source" => cfg.analysis_source,
        ),
        "environment" => _metadata_environment(),
        "outputs" => Dict{String,Any}(
            "comparison_csv_count" => length(csv_paths),
            "comparison_csvs" => csv_paths,
            "figure_dir" => joinpath(outdir, "figures"),
        ),
    ))
    return csv_paths
end

function run_analysis_comparison_suite(
    outdir::AbstractString;
    steps=20,
    sweeps=nothing,
    Nx=64,
    max_points_per_figure=3,
    figure_names=nothing,
    seed=37,
    ess_target=1.0,
    max_steps=nothing,
    max_sweeps=nothing,
    step_growth=2.0,
    min_trace_samples=1,
    pressure_tolerance=Inf,
    fourier_amplitude_scale=0.25,
    fourier_max_mode=2,
    fourier_move_weight=0.1,
    global_amplitude_scale=0.1,
    global_move_weight=0.0,
    radial_variance_amplitude_scale=0.1,
    radial_variance_move_weight=0.0,
    stable_mode_proposals=false,
    fourier_min_k2=nothing,
    burn_fraction=0.5,
    sample_stride=1,
)
    mkpath(outdir)
    cfg = analysis_reference_config()
    cl_data = read_cl_pressure(cfg.analysis_source)
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    specs = analysis_figure_specs()
    if figure_names !== nothing
        wanted = Set(String.(figure_names))
        specs = [spec for spec in specs if spec.name in wanted]
    end
    csv_paths = String[]
    for (spec_idx, spec) in enumerate(specs)
        rows = Any[]
        axis_values = _axis_values(spec, cl_data, max_points_per_figure)
        for (point_idx, axis_value) in enumerate(axis_values)
            A = spec.kind == :PivsA ? axis_value : spec.A
            B = spec.B
            C = spec.kind == :PivsA ? spec.C : axis_value
            grid = Grid3D(Nx, cfg.L)
            params = HEURPParams(A=A, B=B, C=C, alpha=cfg.alpha)
            sample, summary = _run_arianna_pressure_trace_until_ess(
                grid,
                params,
                contract;
                seed=seed + 1000 * spec_idx + point_idx,
                steps=steps,
                sweeps=sweeps,
                ess_target=ess_target,
                max_steps=max_steps,
                max_sweeps=max_sweeps,
                step_growth=step_growth,
                min_trace_samples=min_trace_samples,
                pressure_tolerance=pressure_tolerance,
                burn_fraction=burn_fraction,
                sample_stride=sample_stride,
                fourier_amplitude_scale=fourier_amplitude_scale,
                fourier_max_mode=fourier_max_mode,
                fourier_move_weight=fourier_move_weight,
                global_amplitude_scale=global_amplitude_scale,
                global_move_weight=global_move_weight,
                radial_variance_amplitude_scale=radial_variance_amplitude_scale,
                radial_variance_move_weight=radial_variance_move_weight,
            )
            mean_field = mean_field_pressure(B, C)
            one_loop = one_loop_pressure_smeared(B, C; alpha=cfg.alpha)
            dfm = _safe_dfm_pressure(A, B, C; alpha=cfg.alpha)
            cl_pressure, cl_error = B == 1.0 ? _nearest_cl(cl_data, C) : (NaN, NaN)
            if spec.kind == :dPivsC
                push!(rows, (
                    axis_value, A, B, C,
                    summary.mean - mean_field, max(summary.stderr, 1.0e-6),
                    0.0, one_loop - mean_field, dfm - mean_field,
                    cl_pressure - mean_field, cl_error, _comparison_diagnostics(summary, sample)...,
                ))
            else
                push!(rows, (
                    axis_value, A, B, C,
                    summary.mean, max(summary.stderr, 1.0e-6),
                    mean_field, one_loop, dfm, cl_pressure, cl_error,
                    _comparison_diagnostics(summary, sample)...,
                ))
            end
        end
        header = vcat(
            ["axis", "A", "B", "C", "mc_pressure", "mc_error", "mean_field", "one_loop", "dfm_pressure", "cl_pressure", "cl_error"],
            MC_COMPARISON_DIAGNOSTIC_HEADER,
        )
        csv_path = _write_table(joinpath(outdir, spec.name * "_mc_comparison.csv"), header, rows)
        _write_analysis_comparison_svg(csv_path, joinpath(outdir, "figures"))
        push!(csv_paths, csv_path)
    end
    return csv_paths
end

function run_dpivsc_all_cl_comparisons(
    outdir::AbstractString;
    steps=12,
    sweeps=nothing,
    Nx=64,
    seed=701,
    figure_names=nothing,
    ess_target=1.0,
    max_steps=nothing,
    max_sweeps=nothing,
    step_growth=2.0,
    min_trace_samples=1,
    pressure_tolerance=Inf,
    fourier_amplitude_scale=0.25,
    fourier_max_mode=2,
    fourier_move_weight=0.1,
    global_amplitude_scale=0.1,
    global_move_weight=0.0,
    radial_variance_amplitude_scale=0.1,
    radial_variance_move_weight=0.0,
    stable_mode_proposals=false,
    fourier_min_k2=nothing,
    burn_fraction=0.5,
    sample_stride=1,
)
    mkpath(outdir)
    cfg = analysis_reference_config()
    cl_data = read_cl_pressure(cfg.analysis_source)
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    specs = [spec for spec in analysis_figure_specs() if spec.kind == :dPivsC]
    if figure_names !== nothing
        wanted = Set(String.(figure_names))
        specs = [spec for spec in specs if spec.name in wanted]
    end
    header = vcat(
        ["axis", "A", "B", "C", "mc_pressure", "mc_error", "mean_field", "one_loop",
            "dfm_pressure", "cl_pressure", "cl_error"],
        MC_COMPARISON_DIAGNOSTIC_HEADER,
    )
    csv_paths = String[]
    for (spec_idx, spec) in enumerate(specs)
        csv_path = joinpath(outdir, spec.name * "_mc_comparison.csv")
        if isfile(csv_path)
            existing_header, _ = _read_csv_strings(csv_path)
            existing_header == header || rm(csv_path)
        end
        done_axes = _existing_axes(csv_path)
        for (point_idx, C) in enumerate(cl_data.C)
            C <= spec.Cmax || continue
            C in done_axes && continue
            grid = Grid3D(Nx, cfg.L)
            params = HEURPParams(A=spec.A, B=spec.B, C=C, alpha=cfg.alpha)
            sample, summary = _run_arianna_pressure_trace_until_ess(
                grid,
                params,
                contract;
                seed=seed + 1000 * spec_idx + point_idx,
                steps=steps,
                sweeps=sweeps,
                ess_target=ess_target,
                max_steps=max_steps,
                max_sweeps=max_sweeps,
                step_growth=step_growth,
                min_trace_samples=min_trace_samples,
                pressure_tolerance=pressure_tolerance,
                burn_fraction=burn_fraction,
                sample_stride=sample_stride,
                fourier_amplitude_scale=fourier_amplitude_scale,
                fourier_max_mode=fourier_max_mode,
                fourier_move_weight=fourier_move_weight,
                global_amplitude_scale=global_amplitude_scale,
                global_move_weight=global_move_weight,
                radial_variance_amplitude_scale=radial_variance_amplitude_scale,
                radial_variance_move_weight=radial_variance_move_weight,
            )
            mean_field = mean_field_pressure(spec.B, C)
            one_loop = one_loop_pressure_smeared(spec.B, C; alpha=cfg.alpha)
            dfm = _safe_dfm_pressure(spec.A, spec.B, C; alpha=cfg.alpha)
            cl_pressure, cl_error = _nearest_cl(cl_data, C)
            _append_table_row(csv_path, header, (
                C, spec.A, spec.B, C,
                summary.mean - mean_field, max(summary.stderr, 1.0e-6),
                0.0, one_loop - mean_field, dfm - mean_field,
                cl_pressure - mean_field, cl_error, _comparison_diagnostics(summary, sample)...,
            ))
            push!(done_axes, C)
        end
        _write_analysis_comparison_svg(csv_path, joinpath(outdir, "figures"))
        push!(csv_paths, csv_path)
    end
    return csv_paths
end

function _write_table(path, header, rows)
    open(path, "w") do io
        println(io, join(header, ","))
        for row in rows
            println(io, join(row, ","))
        end
    end
    return path
end

function _write_dataframe(path::AbstractString, rows)
    mkpath(dirname(path))
    data = DataFrames.DataFrame(rows)
    CSV.write(path, data)
    return path
end

function _svg_polyline(points)
    return join([@sprintf("%.3f,%.3f", p[1], p[2]) for p in points], " ")
end

function _write_slit_profile_svg(profile_csv::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_strings(profile_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "slit_density_profiles.svg")
    isempty(rows) && return svg_path
    idx(name) = findfirst(==(name), header)
    model_idx = idx("model")
    A_idx = idx("A")
    B_idx = idx("B")
    C_idx = idx("C")
    z_idx = idx("z")
    phi_idx = idx("phi")
    ref_idx = idx("reference_phi")
    status_idx = idx("status")
    parsed = [
        (
            model=row[model_idx],
            A=parse(Float64, row[A_idx]),
            B=parse(Float64, row[B_idx]),
            C=parse(Float64, row[C_idx]),
            z=parse(Float64, row[z_idx]),
            phi=parse(Float64, row[phi_idx]),
            ref=parse(Float64, row[ref_idx]),
            status=row[status_idx],
        ) for row in rows
    ]
    stable = [row for row in parsed if row.A == 0.0]
    pool = isempty(stable) ? parsed : stable
    target = argmin([abs(row.B - 25.0) + abs(row.C - 0.5) for row in pool])
    target_B = pool[target].B
    target_C = pool[target].C
    selected = [row for row in parsed if row.A == 0.0 && row.B == target_B && row.C == target_C]
    isempty(selected) && (selected = [row for row in parsed if row.B == target_B && row.C == target_C])
    xs = [row.z for row in selected]
    ys = vcat([row.phi for row in selected], [row.ref for row in selected])
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = _expand_plot_range(minimum(ys), maximum(ys))
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict("urp_ti" => "#1f77b4", "vk1" => "#d62728")
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Slit density profiles</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Slit density profiles</text>")
        println(io, @sprintf("<text x='35' y='52' font-size='12' fill='#555'>A = 0, B = %.6g, C = %.6g</text>", target_B, target_C))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        ref_groups = Dict(:reference => sort(unique([(row.z, row.ref) for row in selected])))
        for (_, pairs) in ref_groups
            points = [(x_plot(pair[1]), y_plot(pair[2])) for pair in pairs]
            println(io, "<polyline fill='none' stroke='#333333' stroke-width='2' stroke-dasharray='5 4' points='$(_svg_polyline(points))'/>")
        end
        y_legend = 78
        println(io, "<line x1='455' y1='$(y_legend)' x2='490' y2='$(y_legend)' stroke='#333333' stroke-width='2' stroke-dasharray='5 4'/>")
        println(io, "<text x='498' y='$(y_legend + 4)' font-size='12'>Eq. 22 reference</text>")
        y_legend += 18
        for model in sort(unique(row.model for row in selected))
            model_rows = sort([(row.z, row.phi) for row in selected if row.model == model])
            points = [(x_plot(pair[1]), y_plot(pair[2])) for pair in model_rows]
            color = get(colors, model, "#9467bd")
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.5' points='$(_svg_polyline(points))'/>")
            println(io, "<line x1='455' y1='$(y_legend)' x2='490' y2='$(y_legend)' stroke='$color' stroke-width='2.5'/>")
            println(io, "<text x='498' y='$(y_legend + 4)' font-size='12'>$(model)</text>")
            y_legend += 18
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_slit_xi_svg(summary_csv::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_strings(summary_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "slit_xi_eff.svg")
    isempty(rows) && return svg_path
    idx(name) = findfirst(==(name), header)
    model_idx = idx("model")
    A_idx = idx("A")
    BC_idx = idx("BC")
    xi_idx = idx("xi_eff")
    status_idx = idx("status")
    parsed = [
        (
            model=row[model_idx],
            A=parse(Float64, row[A_idx]),
            BC=parse(Float64, row[BC_idx]),
            xi=parse(Float64, row[xi_idx]),
            status=row[status_idx],
        ) for row in rows if parse(Float64, row[BC_idx]) > 0.0
    ]
    selected = [row for row in parsed if row.A == 0.0]
    isempty(selected) && (selected = parsed)
    xs = log10.([row.BC for row in selected])
    ys = [row.xi for row in selected]
    reference_y = [1.0 / sqrt(2.0 * row.BC) for row in selected]
    ymin, ymax = _expand_plot_range(minimum(vcat(ys, reference_y)), maximum(vcat(ys, reference_y)))
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict("urp_ti" => "#1f77b4", "vk1" => "#d62728")
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Effective slit correlation length</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Effective slit correlation length</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
            x_label=x -> _format_tick_label(10.0^Float64(x)))
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>B C</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>xi_eff</text>")
        ref_bcs = sort(unique(row.BC for row in selected))
        ref_points = [(x_plot(log10(bc)), y_plot(1.0 / sqrt(2.0 * bc))) for bc in ref_bcs]
        println(io, "<polyline fill='none' stroke='#333333' stroke-width='2' stroke-dasharray='5 4' points='$(_svg_polyline(ref_points))'/>")
        y_legend = 78
        println(io, "<line x1='455' y1='$(y_legend)' x2='490' y2='$(y_legend)' stroke='#333333' stroke-width='2' stroke-dasharray='5 4'/>")
        println(io, "<text x='498' y='$(y_legend + 4)' font-size='12'>xi_b=(2BC)^-1/2</text>")
        y_legend += 18
        for model in sort(unique(row.model for row in selected))
            model_rows = sort([(row.BC, row.xi) for row in selected if row.model == model])
            points = [(x_plot(log10(pair[1])), y_plot(pair[2])) for pair in model_rows]
            color = get(colors, model, "#9467bd")
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.5' points='$(_svg_polyline(points))'/>")
            println(io, "<line x1='455' y1='$(y_legend)' x2='490' y2='$(y_legend)' stroke='$color' stroke-width='2.5'/>")
            println(io, "<text x='498' y='$(y_legend + 4)' font-size='12'>$(model), A=0</text>")
            y_legend += 18
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _slit_field_summary_row(result::SlitFieldSaddleResult)
    p = result.params
    return [
        p.B,
        p.C,
        p.A,
        result.grid.Nz,
        result.grid.L,
        result.solver,
        result.converged,
        result.energy <= result.ansatz_energy + 1.0e-5 && result.rms_reference_error < 5.0e-2,
        result.iterations,
        result.objective_calls,
        result.xi_bulk,
        result.xi_eff,
        result.xi_fit_error,
        result.energy,
        result.reference_energy,
        result.ansatz_energy,
        result.energy - result.ansatz_energy,
        result.energy - result.reference_energy,
        result.rms_reference_error,
        result.max_abs_reference_error,
        result.ansatz_rms_reference_error,
        result.projected_gradient_rms,
        result.projected_gradient_max,
        result.status,
    ]
end

function _write_slit_vk1_field_profile_svg(profile_csv::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_strings(profile_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "slit_vk1_field_profiles.svg")
    isempty(rows) && return svg_path
    idx(name) = findfirst(==(name), header)
    profile_idx = idx("profile")
    B_idx = idx("B")
    C_idx = idx("C")
    z_idx = idx("z")
    phi_idx = idx("phi")
    parsed = [
        (
            profile=row[profile_idx],
            B=parse(Float64, row[B_idx]),
            C=parse(Float64, row[C_idx]),
            z=parse(Float64, row[z_idx]),
            phi=parse(Float64, row[phi_idx]),
        ) for row in rows
    ]
    xs = [row.z for row in parsed]
    ys = [row.phi for row in parsed]
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = _expand_plot_range(minimum(ys), maximum(ys))
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict(
        "eq22_reference" => "#333333",
        "vk1_eq22_family" => "#d62728",
        "vk1_smooth_basis" => "#2ca02c",
        "vk1_full_field" => "#1f77b4",
    )
    dashes = Dict(
        "eq22_reference" => " stroke-dasharray='5 4'",
        "vk1_eq22_family" => " stroke-dasharray='2 3'",
        "vk1_smooth_basis" => " stroke-dasharray='8 3'",
        "vk1_full_field" => "",
    )
    target_B = parsed[1].B
    target_C = parsed[1].C
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>HE-VK1 slit saddle profile</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>HE-VK1 slit saddle profile</text>")
        println(io, @sprintf("<text x='35' y='52' font-size='12' fill='#555'>A = 0, B = %.6g, C = %.6g</text>", target_B, target_C))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        y_legend = 78
        order = ["eq22_reference", "vk1_eq22_family", "vk1_smooth_basis", "vk1_full_field"]
        labels = Dict(
            "eq22_reference" => "Eq. 22 reference",
            "vk1_eq22_family" => "VK1 Eq. 22-family fit",
            "vk1_smooth_basis" => "VK1 smooth-basis saddle",
            "vk1_full_field" => "VK1 full-field saddle",
        )
        for profile in order
            profile_rows = sort([(row.z, row.phi) for row in parsed if row.profile == profile])
            isempty(profile_rows) && continue
            points = [(x_plot(pair[1]), y_plot(pair[2])) for pair in profile_rows]
            color = get(colors, profile, "#9467bd")
            dash = get(dashes, profile, "")
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.5'$dash points='$(_svg_polyline(points))'/>")
            println(io, "<line x1='420' y1='$(y_legend)' x2='455' y2='$(y_legend)' stroke='$color' stroke-width='2.5'$dash/>")
            println(io, "<text x='463' y='$(y_legend + 4)' font-size='12'>$(labels[profile])</text>")
            y_legend += 18
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _alexander_katz_marker_indices(n::Integer; target::Integer=30)
    count = min(max(2, Int(target)), Int(n))
    return unique(clamp.(round.(Int, range(1, Int(n); length=count)), 1, Int(n)))
end

function _write_alexander_katz_fig2_svg(rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "fig2_profiles.svg")
    line_rows = [row for row in rows if row.series == "eq22_line"]
    isempty(line_rows) && return svg_path
    xs = [row.z_over_L for row in line_rows]
    ys = [row.phi for row in line_rows]
    xmin, xmax = 0.0, 1.0
    ymin, ymax = 0.0, max(2.0, 1.05 * maximum(ys))
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=11)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict(
        1.0 => "#1f77b4",
        10.0 => "#d62728",
        100.0 => "#2ca02c",
        1000.0 => "#9467bd",
    )
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Alexander-Katz Fig. 2 reproduction</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Alexander-Katz Fig. 2 reproduction</text>")
        println(io, "<text x='35' y='52' font-size='12' fill='#555'>Saddle profiles from Eq. 22 for BC = 1, 10, 100, 1000</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        y_legend = 76
        for bc in sort(unique(row.BC for row in line_rows))
            selected = sort([(row.z_over_L, row.phi) for row in line_rows if row.BC == bc])
            points = [(x_plot(pair[1]), y_plot(pair[2])) for pair in selected]
            color = get(colors, Float64(bc), "#333333")
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.4' points='$(_svg_polyline(points))'/>")
            marker_rows = [row for row in rows if row.series == "saddle_points" && row.BC == bc]
            for row in marker_rows
                x = x_plot(row.z_over_L)
                y = y_plot(row.phi)
                if row.marker == "x"
                    println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='%s' stroke-width='1.4'/>",
                        x - 3.0, y - 3.0, x + 3.0, y + 3.0, color))
                    println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='%s' stroke-width='1.4'/>",
                        x - 3.0, y + 3.0, x + 3.0, y - 3.0, color))
                else
                    fill = row.marker == "filled_circle" ? color : "white"
                    println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='3.1' fill='%s' stroke='%s' stroke-width='1.4'/>",
                        x, y, fill, color))
                end
            end
            println(io, "<line x1='438' y1='$(y_legend)' x2='470' y2='$(y_legend)' stroke='$color' stroke-width='2.4'/>")
            println(io, @sprintf("<text x='478' y='%d' font-size='12'>BC = %.6g</text>", y_legend + 4, bc))
            y_legend += 18
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_alexander_katz_fig3_svg(rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "fig3_profiles.svg")
    line_rows = [row for row in rows if row.series in ("eq22_mean_field", "mc_eq22_fit")]
    isempty(line_rows) && return svg_path
    xs = [row.z_over_L for row in line_rows]
    ys = [row.phi for row in line_rows]
    xmin, xmax = 0.0, 1.0
    ymin, ymax = 0.0, max(2.0, 1.05 * maximum(ys))
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=11)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict(
        "eq22_mean_field" => "#333333",
        "saddle_points" => "#333333",
        "mc_eq22_fit" => "#d62728",
        "mc_noise_profile" => "#d62728",
        "mc_noise_points" => "#d62728",
    )
    labels = Dict(
        "eq22_mean_field" => "Eq. 22 saddle",
        "mc_eq22_fit" => "Eq. 22 fit to MC mean",
    )
    dashes = Dict("eq22_mean_field" => "", "mc_eq22_fit" => " stroke-dasharray='7 4'")
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Alexander-Katz Fig. 3 reproduction</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Alexander-Katz Fig. 3 reproduction</text>")
        println(io, "<text x='35' y='52' font-size='12' fill='#555'>B = 25, C = 0.5, BC = 12.5; dashed curve is the Eq. 22 fit to the MC mean</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        y_legend = 76
        for series in ("eq22_mean_field", "mc_eq22_fit")
            selected = sort([(row.z_over_L, row.phi) for row in line_rows if row.series == series])
            points = [(x_plot(pair[1]), y_plot(pair[2])) for pair in selected]
            color = colors[series]
            dash = dashes[series]
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.5'$dash points='$(_svg_polyline(points))'/>")
            println(io, "<line x1='408' y1='$(y_legend)' x2='442' y2='$(y_legend)' stroke='$color' stroke-width='2.5'$dash/>")
            println(io, "<text x='450' y='$(y_legend + 4)' font-size='12'>$(labels[series])</text>")
            y_legend += 18
        end
        println(io, "<rect x='422' y='$(y_legend - 5)' width='6.0' height='6.0' fill='#d62728' stroke='#d62728' stroke-width='1.3'/>")
        println(io, "<text x='450' y='$(y_legend + 4)' font-size='12'>MC mean points</text>")
        for row in rows
            row.series in ("saddle_points", "mc_noise_points") || continue
            color = colors[row.series]
            x = x_plot(row.z_over_L)
            y = y_plot(row.phi)
            if row.series == "mc_noise_points" && hasproperty(row, :stderr)
                err = max(0.0, Float64(row.stderr))
                if err > 0.0
                    ylo = y_plot(row.phi - err)
                    yhi = y_plot(row.phi + err)
                    println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='%s' stroke-width='1.0'/>",
                        x, ylo, x, yhi, color))
                end
            end
            fill = row.series == "mc_noise_points" ? color : "white"
            println(io, @sprintf("<rect x='%.3f' y='%.3f' width='6.0' height='6.0' fill='%s' stroke='%s' stroke-width='1.3'/>",
                x - 3.0, y - 3.0, fill, color))
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_alexander_katz_text(outdir::AbstractString, summary_rows)
    markdown_path = joinpath(outdir, "alexander_katz_figures.md")
    summary = Dict(row.metric => row.value for row in summary_rows)
    open(markdown_path, "w") do io
        println(io, "# Alexander-Katz slit figure reproduction")
        println(io)
        println(io, "This artifact reproduces the reference profiles needed before manuscript revision: Alexander-Katz et al. 2003 Fig. 2 saddle profiles at several `BC` values and Fig. 3 saddle plus with-fluctuation profile at the caption parameters.")
        println(io)
        println(io, "## Alexander-Katz Fig. 2")
        println(io)
        println(io, "Fig. 2 is generated from the closed-form saddle profile Eq. 22 at `BC = 1, 10, 100, 1000`. The CSV contains continuous `eq22_line` rows and decimated `saddle_points` marker rows so the artifact mirrors the line/point structure of the reference figure.")
        println(io)
        println(io, "## Alexander-Katz Fig. 3")
        println(io)
        println(io, @sprintf("The reference caption gives `B = %.6g`, `C = %.6g`, so `BC = %.6g` and the saddle correlation length is `xi_b = %.6g`.",
            summary["fig3_B"], summary["fig3_C"], summary["fig3_BC"], summary["fig3_xi_bulk"]))
        println(io, @sprintf("The with-fluctuation profile is generated by Monte Carlo sampling of smooth normalized HE-VK1 slit density profiles. Filled red squares are the sampled MC mean. The dashed red curve is Eq. 22 evaluated at the fitted effective correlation length `xi_eff = %.6g`.",
            summary["fig3_mc_xi_eff"]))
        println(io)
        println(io, @sprintf("MC diagnostics: `A = %.6g`, stored samples = %.0f, acceptance = %.6g, temperature = %.6g.",
            summary["fig3_mc_A"], summary["fig3_mc_sample_count"], summary["fig3_mc_acceptance_rate"], summary["fig3_mc_temperature"]))
        println(io)
        println(io, "Scope note: this is a real-density HE-VK1 Metropolis sampler in a smooth slit-profile basis. It is not the complex-Langevin field simulation used by Alexander-Katz et al.; the purpose here is to generate MC density-profile points and then use Eq. 22 only as a post-sampling fit to those points.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `fig2_profiles.csv` and `fig2_profiles.svg`")
        println(io, "- `fig3_profiles.csv` and `fig3_profiles.svg`")
        println(io, "- `summary.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return markdown_path
end

