function _write_ak_fig3_digitization_svg(profile_rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "ak_fig3_digitized_profile.svg")
    isempty(profile_rows) && return svg_path
    xs = [row.z_over_L for row in profile_rows]
    ys = vcat([row.phi for row in profile_rows], [row.fit_phi for row in profile_rows],
        [row.mean_field_phi for row in profile_rows])
    xmin, xmax = 0.0, 1.0
    ymin, ymax = _expand_plot_range(minimum(ys), maximum(ys))
    ymin = min(0.0, ymin)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=11)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    sorted = sort(profile_rows; by=row -> row.z_over_L)
    fit_points = [(x_plot(row.z_over_L), y_plot(row.fit_phi)) for row in sorted]
    mean_field_points = [(x_plot(row.z_over_L), y_plot(row.mean_field_phi)) for row in sorted]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Alexander-Katz Fig. 3 digitized profile</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Alexander-Katz Fig. 3 digitized profile</text>")
        println(io, "<text x='35' y='52' font-size='12' fill='#555'>Filled-square CL points digitized from the local PDF rendering</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        println(io, "<polyline fill='none' stroke='#333333' stroke-width='2.0' points='$(_svg_polyline(mean_field_points))'/>")
        println(io, "<polyline fill='none' stroke='#d62728' stroke-width='2.5' stroke-dasharray='7 4' points='$(_svg_polyline(fit_points))'/>")
        for row in sorted
            println(io, @sprintf("<rect x='%.3f' y='%.3f' width='6.0' height='6.0' fill='#d62728' stroke='#d62728' stroke-width='1.3'/>",
                x_plot(row.z_over_L) - 3.0, y_plot(row.phi) - 3.0))
        end
        println(io, "<line x1='410' y1='76' x2='446' y2='76' stroke='#333333' stroke-width='2.0'/>")
        println(io, "<text x='454' y='80' font-size='12'>Eq. 22 mean field</text>")
        println(io, "<line x1='410' y1='96' x2='446' y2='96' stroke='#d62728' stroke-width='2.5' stroke-dasharray='7 4'/>")
        println(io, "<text x='454' y='100' font-size='12'>Eq. 22 fit</text>")
        println(io, "<rect x='424' y='111' width='6.0' height='6.0' fill='#d62728' stroke='#d62728' stroke-width='1.3'/>")
        println(io, "<text x='454' y='118' font-size='12'>digitized CL points</text>")
        println(io, "</svg>")
    end
    return svg_path
end

function _write_ak_fig3_digitization_text(
    outdir::AbstractString,
    result_summary,
    source_image::AbstractString,
)
    path = joinpath(outdir, "ak_fig3_digitization.md")
    open(path, "w") do io
        println(io, "# Alexander-Katz Fig. 3 digitized target")
        println(io)
        println(io, "This artifact records a local digitization of the filled-square complex-Langevin density-profile points in Alexander-Katz et al. 2003 Fig. 3.")
        println(io)
        println(io, "Source rendering: `$(source_image)`.")
        println(io, @sprintf("digitized filled-square points: %.0f.", result_summary.point_count))
        println(io, @sprintf("Eq. 22 fit using full-grid normalization: `xi_eff = %.6g`, RMSE = %.6g, R2 = %.6g.",
            result_summary.xi_eff, result_summary.xi_fit_rmse, result_summary.xi_fit_r2))
        println(io)
        println(io, "The fit uses a dense midpoint normalization grid before interpolating Eq. 22 back to the sparse digitized points. This avoids the sparse-point normalization bias that appears if Eq. 22 is normalized directly on the digitized abscissae.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `ak_fig3_digitized_profile.csv`")
        println(io, "- `ak_fig3_digitized_summary.csv`")
        println(io, "- `ak_fig3_digitized_profile.svg`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function run_alexander_katz_fig3_digitization(
    outdir::AbstractString;
    B::Real=25.0,
    C::Real=0.5,
    L::Real=1.0,
    normalization_Nz::Integer=2000,
    source_image::AbstractString=normpath(joinpath(@__DIR__, "..", "results",
        "ak_reference_digitization", "ak2003_fig3_crop.png")),
    plot_frame_left_px::Real=61.0,
    plot_frame_right_px::Real=797.0,
    plot_frame_top_px::Real=47.0,
    plot_frame_bottom_px::Real=670.0,
)
    mkpath(outdir)
    left = Float64(plot_frame_left_px)
    right = Float64(plot_frame_right_px)
    top = Float64(plot_frame_top_px)
    bottom = Float64(plot_frame_bottom_px)
    right > left || throw(ArgumentError("plot frame right pixel must exceed left pixel"))
    bottom > top || throw(ArgumentError("plot frame bottom pixel must exceed top pixel"))
    pixels = _ak_fig3_digitized_filled_square_pixels()
    z = [(point.pixel_x - left) / (right - left) for point in pixels]
    phi = [2.0 * (bottom - point.pixel_y) / (bottom - top) for point in pixels]
    xi_eff, fit_error = fit_slit_xi_eff_reference_grid(z, phi; B=B, C=C, L=L,
        normalization_Nz=normalization_Nz)
    fit_phi = slit_reference_profile_at_points(z; B=B, C=C, L=L, xi=xi_eff,
        normalization_Nz=normalization_Nz)
    xi_bulk = 1.0 / sqrt(2.0 * Float64(B) * Float64(C))
    mean_field_phi = slit_reference_profile_at_points(z; B=B, C=C, L=L, xi=xi_bulk,
        normalization_Nz=normalization_Nz)
    fit_diagnostics = _slit_profile_fit_diagnostics(phi, fit_phi)
    profile_rows = NamedTuple[]
    for i in eachindex(pixels)
        push!(profile_rows, (
            source="ak_fig3_filled_square",
            pixel_x=pixels[i].pixel_x,
            pixel_y=pixels[i].pixel_y,
            z_over_L=z[i],
            phi=phi[i],
            fit_phi=fit_phi[i],
            mean_field_phi=mean_field_phi[i],
            residual=phi[i] - fit_phi[i],
            xi_eff=xi_eff,
        ))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "ak_fig3_digitized_profile.csv"), profile_rows)
    summary_rows = [
        (metric="point_count", value=Float64(length(pixels)), note="Digitized filled-square CL points"),
        (metric="B", value=Float64(B), note="AK Fig. 3 B"),
        (metric="C", value=Float64(C), note="AK Fig. 3 C"),
        (metric="BC", value=Float64(B) * Float64(C), note="AK Fig. 3 BC"),
        (metric="xi_bulk", value=xi_bulk, note="Mean-field correlation length"),
        (metric="xi_eff", value=xi_eff, note="Eq. 22 fit to digitized CL points"),
        (metric="xi_fit_mse", value=fit_error, note="Mean-square Eq. 22 fit error"),
        (metric="xi_fit_rmse", value=fit_diagnostics.rmse, note="Root-mean-square Eq. 22 fit error"),
        (metric="xi_fit_r2", value=fit_diagnostics.r2, note="Eq. 22 fit R2"),
        (metric="peak_digitized", value=maximum(phi), note="Maximum digitized reduced density"),
        (metric="peak_fit", value=maximum(fit_phi), note="Maximum fitted Eq. 22 density at digitized points"),
        (metric="normalization_Nz", value=Float64(max(16, Int(normalization_Nz))), note="Dense midpoint normalization grid"),
        (metric="plot_frame_left_px", value=left, note="Digitization plot-frame left pixel in crop coordinates"),
        (metric="plot_frame_right_px", value=right, note="Digitization plot-frame right pixel in crop coordinates"),
        (metric="plot_frame_top_px", value=top, note="Digitization plot-frame top pixel in crop coordinates"),
        (metric="plot_frame_bottom_px", value=bottom, note="Digitization plot-frame bottom pixel in crop coordinates"),
    ]
    summary_csv = _write_dataframe(joinpath(outdir, "ak_fig3_digitized_summary.csv"), summary_rows)
    profile_svg = _write_ak_fig3_digitization_svg(profile_rows, outdir)
    result_summary = (
        point_count=Float64(length(pixels)),
        xi_eff=xi_eff,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
    )
    markdown_path = _write_ak_fig3_digitization_text(outdir, result_summary, source_image)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "alexander_katz_fig3_digitization",
            "source_image" => String(source_image),
        ),
        "plot_frame" => Dict{String,Any}(
            "left_px" => left,
            "right_px" => right,
            "top_px" => top,
            "bottom_px" => bottom,
            "coordinates" => "crop image pixels; x maps to z/L and y maps to phi",
        ),
        "parameters" => Dict{String,Any}(
            "B" => Float64(B),
            "C" => Float64(C),
            "L" => Float64(L),
        ),
        "fit" => Dict{String,Any}(
            "normalization_Nz" => max(16, Int(normalization_Nz)),
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_mse" => fit_error,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "summary_csv" => summary_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return AlexanderKatzFig3DigitizationResult(profile_csv, summary_csv, profile_svg,
        markdown_path, metadata_path, xi_eff, fit_diagnostics.rmse,
        fit_diagnostics.r2, length(pixels))
end

