function _format_log10_tick(value::Real)
    return _format_tick_label(10.0 ^ Float64(value))
end

function _write_ak_fig4_digitization_svg(xi_rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "ak_fig4_digitized_xi.svg")
    isempty(xi_rows) && return svg_path
    xlogs = [log10(row.BC) for row in xi_rows]
    ylogs = [log10(row.xi_eff) for row in xi_rows]
    ref_bcs = 10 .^ collect(range(0.0, 3.0; length=160))
    ref_ylogs = [log10(1.0 / sqrt(2.0 * bc)) for bc in ref_bcs]
    xmin, xmax = 0.0, 3.0
    ymin, ymax = _expand_plot_range(minimum(vcat(ylogs, ref_ylogs)), maximum(vcat(ylogs, ref_ylogs)))
    ymin = min(ymin, -1.2)
    ymax = max(ymax, 0.05)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = collect(0.0:0.5:3.0)
    yticks = _major_ticks(ymin, ymax; count=8)
    x_minor_ticks = _minor_ticks(xticks; subdivisions=5)
    y_minor_ticks = _minor_ticks(yticks; subdivisions=5)
    colors = Dict(1.0 => "#1f77b4", 10.0 => "#2ca02c", 25.0 => "#d62728")
    labels = Dict(1.0 => "B = 1", 10.0 => "B = 10", 25.0 => "B = 25")
    ref_points = [(x_plot(log10(bc)), y_plot(log10(1.0 / sqrt(2.0 * bc)))) for bc in ref_bcs]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>Alexander-Katz Fig. 4 digitized xi_eff</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>Alexander-Katz Fig. 4 digitized xi_eff</text>")
        println(io, "<text x='35' y='52' font-size='12' fill='#555'>Approximate log-log digitization from supplied Fig. 4 image</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
            x_label=_format_log10_tick, y_label=_format_log10_tick)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>BC</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>xi_eff</text>")
        println(io, "<polyline fill='none' stroke='#333333' stroke-width='2.0' stroke-dasharray='6 4' points='$(_svg_polyline(ref_points))'/>")
        for B in (1.0, 10.0, 25.0)
            selected = sort([row for row in xi_rows if row.B == B]; by=row -> row.BC)
            color = colors[B]
            for row in selected
                x = x_plot(log10(row.BC))
                y = y_plot(log10(row.xi_eff))
                if B == 10.0
                    println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4.0' fill='white' stroke='%s' stroke-width='1.7'/>", x, y, color))
                elseif B == 25.0
                    println(io, @sprintf("<rect x='%.3f' y='%.3f' width='7.0' height='7.0' fill='%s' stroke='%s' stroke-width='1.2'/>",
                        x - 3.5, y - 3.5, color, color))
                else
                    points = @sprintf("%.3f,%.3f %.3f,%.3f %.3f,%.3f %.3f,%.3f",
                        x, y - 4.0, x + 4.0, y, x, y + 4.0, x - 4.0, y)
                    println(io, "<polygon points='$points' fill='$color' stroke='$color' stroke-width='1.2'/>")
                end
            end
        end
        println(io, "<line x1='400' y1='76' x2='436' y2='76' stroke='#333333' stroke-width='2.0' stroke-dasharray='6 4'/>")
        println(io, "<text x='444' y='80' font-size='12'>xi_b = 1 / sqrt(2BC)</text>")
        y0 = 96
        for (i, B) in enumerate((1.0, 10.0, 25.0))
            color = colors[B]
            y = y0 + 20 * (i - 1)
            if B == 10.0
                println(io, @sprintf("<circle cx='418' cy='%d' r='4.0' fill='white' stroke='%s' stroke-width='1.7'/>", y, color))
            elseif B == 25.0
                println(io, @sprintf("<rect x='414.5' y='%.1f' width='7.0' height='7.0' fill='%s' stroke='%s' stroke-width='1.2'/>",
                    y - 3.5, color, color))
            else
                points = @sprintf("418.000,%d 422.000,%d 418.000,%d 414.000,%d", y - 4, y, y + 4, y)
                println(io, "<polygon points='$points' fill='$color' stroke='$color' stroke-width='1.2'/>")
            end
            println(io, "<text x='444' y='$(y + 4)' font-size='12'>$(labels[B])</text>")
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_ak_fig4_digitization_text(
    outdir::AbstractString,
    point_count::Integer,
    source_image::AbstractString,
)
    path = joinpath(outdir, "ak_fig4_digitization.md")
    open(path, "w") do io
        println(io, "# Alexander-Katz Fig. 4 digitized xi_eff target")
        println(io)
        println(io, "This artifact records an approximate local digitization of Alexander-Katz et al. 2003 Fig. 4, the reported effective correlation length `xi_eff` as a function of `BC` for `B = 1`, `B = 10`, and `B = 25`.")
        println(io)
        println(io, "Source rendering: `$(source_image)`.")
        println(io, @sprintf("Digitized points: %.0f.", Float64(point_count)))
        println(io)
        println(io, "Fig. 4 is a log-log summary figure, so these points are lower precision than the direct Fig. 3 profile digitization. The intended use is transferability testing of VK1 3D MC trends and representative targets, not replacement of direct profile comparisons.")
        println(io)
        println(io, "The B=25 filled-square series is anchored to the Fig. 3 condition `B = 25`, `BC = 12.5`, where the supplied image gives `xi_eff` close to `0.35`.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `ak_fig4_digitized_xi.csv`")
        println(io, "- `ak_fig4_digitized_summary.csv`")
        println(io, "- `ak_fig4_digitized_xi.svg`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function run_alexander_katz_fig4_digitization(
    outdir::AbstractString;
    source_image::AbstractString=normpath(joinpath(@__DIR__, "..", "..",
        "references", "Fig4.png")),
    plot_frame_left_px::Real=198.5,
    plot_frame_right_px::Real=1009.0,
    xi_one_y_px::Real=79.0,
    plot_frame_bottom_px::Real=728.0,
    x_decade_px::Real=327.5,
    y_decade_px::Real=425.8,
)
    mkpath(outdir)
    left = Float64(plot_frame_left_px)
    right = Float64(plot_frame_right_px)
    y_one = Float64(xi_one_y_px)
    bottom = Float64(plot_frame_bottom_px)
    x_decade = Float64(x_decade_px)
    y_decade = Float64(y_decade_px)
    right > left || throw(ArgumentError("plot frame right pixel must exceed left pixel"))
    x_decade > 0.0 || throw(ArgumentError("x_decade_px must be positive"))
    y_decade > 0.0 || throw(ArgumentError("y_decade_px must be positive"))
    pixels = _ak_fig4_digitized_xi_pixels()
    xi_rows = NamedTuple[]
    for point in pixels
        log_bc = (point.pixel_x - left) / x_decade
        bc = 10.0 ^ log_bc
        log_xi = (y_one - point.pixel_y) / y_decade
        xi_eff = 10.0 ^ log_xi
        xi_bulk = 1.0 / sqrt(2.0 * bc)
        push!(xi_rows, (
            source="ak_fig4",
            series=point.series,
            B=point.B,
            marker=point.marker,
            pixel_x=point.pixel_x,
            pixel_y=point.pixel_y,
            log10_BC=log_bc,
            BC=bc,
            C=bc / point.B,
            log10_xi_eff=log_xi,
            xi_eff=xi_eff,
            xi_bulk=xi_bulk,
            xi_ratio=xi_eff / xi_bulk,
        ))
    end
    xi_csv = _write_dataframe(joinpath(outdir, "ak_fig4_digitized_xi.csv"), xi_rows)
    summary_rows = NamedTuple[
        (metric="point_count", value=Float64(length(pixels)), note="Digitized Fig. 4 points"),
        (metric="series_count", value=3.0, note="B=1, B=10, and B=25 series"),
        (metric="plot_frame_left_px", value=left, note="BC=1 vertical axis in crop coordinates"),
        (metric="plot_frame_right_px", value=right, note="Approximate right plot frame in crop coordinates"),
        (metric="xi_one_y_px", value=y_one, note="xi_eff=1 horizontal tick in crop coordinates"),
        (metric="plot_frame_bottom_px", value=bottom, note="Approximate crop-bottom plot frame"),
        (metric="x_decade_px", value=x_decade, note="Horizontal pixels per log10(BC) decade"),
        (metric="y_decade_px", value=y_decade, note="Vertical pixels per log10(xi_eff) decade"),
        (metric="min_BC", value=minimum(row.BC for row in xi_rows), note="Minimum digitized BC"),
        (metric="max_BC", value=maximum(row.BC for row in xi_rows), note="Maximum digitized BC"),
        (metric="min_xi_eff", value=minimum(row.xi_eff for row in xi_rows), note="Minimum digitized xi_eff"),
        (metric="max_xi_eff", value=maximum(row.xi_eff for row in xi_rows), note="Maximum digitized xi_eff"),
    ]
    summary_csv = _write_dataframe(joinpath(outdir, "ak_fig4_digitized_summary.csv"), summary_rows)
    xi_svg = _write_ak_fig4_digitization_svg(xi_rows, outdir)
    markdown_path = _write_ak_fig4_digitization_text(outdir, length(pixels), source_image)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "alexander_katz_fig4_digitization",
            "source_image" => String(source_image),
        ),
        "plot_calibration" => Dict{String,Any}(
            "plot_frame_left_px" => left,
            "plot_frame_right_px" => right,
            "xi_one_y_px" => y_one,
            "plot_frame_bottom_px" => bottom,
            "x_decade_px" => x_decade,
            "y_decade_px" => y_decade,
            "log10_BC_formula" => "(pixel_x - plot_frame_left_px) / x_decade_px",
            "log10_xi_eff_formula" => "(xi_one_y_px - pixel_y) / y_decade_px",
        ),
        "outputs" => Dict{String,Any}(
            "xi_csv" => xi_csv,
            "summary_csv" => summary_csv,
            "xi_svg" => xi_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return AlexanderKatzFig4DigitizationResult(xi_csv, summary_csv, xi_svg,
        markdown_path, metadata_path, length(pixels))
end

function _target_row_value(row, name::Symbol, default=nothing)
    hasproperty(row, name) && return getproperty(row, name)
    default !== nothing && return default
    throw(ArgumentError("target row missing required field $(name)"))
end

function _first_csv_row_dict(path::AbstractString)
    header, rows = _read_csv_strings(path)
    isempty(rows) && throw(ArgumentError("CSV has no data rows: $(path)"))
    return Dict(header[i] => rows[1][i] for i in eachindex(header))
end

function _dict_float(row::Dict{String,String}, key::AbstractString, path::AbstractString)
    haskey(row, key) || throw(ArgumentError("CSV $(path) missing $(key)"))
    return parse(Float64, row[key])
end

function _read_slit_profile_series(path::AbstractString, series_name::AbstractString)
    header, rows = _read_csv_strings(path)
    series_idx = findfirst(==("series"), header)
    z_idx = findfirst(==("z_over_L"), header)
    phi_idx = findfirst(==("phi"), header)
    series_idx === nothing && throw(ArgumentError("profile CSV missing series: $(path)"))
    z_idx === nothing && throw(ArgumentError("profile CSV missing z_over_L: $(path)"))
    phi_idx === nothing && throw(ArgumentError("profile CSV missing phi: $(path)"))
    selected = [row for row in rows if row[series_idx] == series_name]
    if isempty(selected) && series_name == "mc_mean_3d"
        selected = [row for row in rows if row[series_idx] == "mc_mean_3d_raw"]
    end
    isempty(selected) && throw(ArgumentError("profile CSV $(path) has no $(series_name) rows"))
    return (
        z_over_L=[parse(Float64, row[z_idx]) for row in selected],
        phi=[parse(Float64, row[phi_idx]) for row in selected],
    )
end

function _write_ak_fig4_b25_a_svg(rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "ak_fig4_B25_vk1_A_mapping.svg")
    isempty(rows) && return svg_path
    xlogs = [log10(row.BC) for row in rows]
    ylogs = [log10(row.A) for row in rows]
    xmin, xmax = _expand_plot_range(minimum(xlogs), maximum(xlogs))
    ymin, ymax = _expand_plot_range(minimum(ylogs), maximum(ylogs))
    xticks = _major_ticks(xmin, xmax; count=8)
    yticks = _major_ticks(ymin, ymax; count=8)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / (xmax - xmin)
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / (ymax - ymin)
    sorted = sort(rows; by=row -> row.BC)
    points = [(x_plot(log10(row.BC)), y_plot(log10(row.A))) for row in sorted]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>AK Fig. 4 B=25 VK1 A mapping</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>AK Fig. 4 B=25 VK1 A mapping</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
            x_label=_format_log10_tick, y_label=_format_log10_tick)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>BC</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>A</text>")
        println(io, "<polyline fill='none' stroke='#1f77b4' stroke-width='2.4' points='$(_svg_polyline(points))'/>")
        for row in sorted
            fill = row.calibration_status == "full_profile_pass" ? "#1f77b4" : "#d62728"
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4.2' fill='%s' stroke='%s' stroke-width='1.4'/>",
                x_plot(log10(row.BC)), y_plot(log10(row.A)), fill, fill))
        end
        println(io, "<text x='420' y='84' font-size='12'>blue: full profile pass</text>")
        println(io, "<text x='420' y='104' font-size='12'>red: xi pass/profile caveat</text>")
        println(io, "</svg>")
    end
    return svg_path
end

