function _write_ak_fig4_b25_mapping_text(outdir::AbstractString, rows)
    path = joinpath(outdir, "ak_fig4_B25_vk1_A_mapping.md")
    open(path, "w") do io
        println(io, "# AK Fig. 4 B=25 VK1 A mapping")
        println(io)
        println(io, "This artifact evaluates B=25 Fig. 4 transferability runs for the HE-VK1 profile-mode 3D Metropolis sampler.")
        println(io)
        for row in sort(rows; by=row -> row.BC)
            println(io, @sprintf("- BC=%.12g: A=%.6g, target xi=%.12g, MC xi=%.12g, abs error=%.6g, target-profile R2=%.6g, status=%s.",
                row.BC, row.A, row.target_xi_eff, row.production_xi_eff,
                row.abs_xi_error, row.target_profile_r2, row.calibration_status))
        end
        println(io)
        println(io, "Rows marked `not_calibrated` are production runs whose `A` values do not reproduce the current Fig. 4 target. Passing rows are calibration evidence, not yet a predictive fluctuation-correction law. A manuscript-grade correction model still needs held-out validation across BC and B.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `ak_fig4_B25_vk1_A_mapping.csv`")
        println(io, "- `ak_fig4_B25_vk1_A_mapping.svg`")
        println(io, "- `ak_fig4_B25_vk1_xi_reproduction.svg`")
    end
    return path
end

function write_ak_fig4_b25_vk1_a_mapping(
    outdir::AbstractString;
    targets,
    target_profile_r2_threshold::Real=0.995,
)
    mkpath(outdir)
    isempty(targets) && throw(ArgumentError("targets must contain at least one production run"))
    r2_gate = Float64(target_profile_r2_threshold)
    mapping_rows = NamedTuple[]
    for target_row in targets
        prod_outdir = String(_target_row_value(target_row, :production_outdir))
        diagnostics_csv = joinpath(prod_outdir, "slit_3d_mc_diagnostics.csv")
        profile_csv = joinpath(prod_outdir, "slit_3d_mc_profile.csv")
        isfile(diagnostics_csv) || throw(ArgumentError("missing diagnostics CSV: $(diagnostics_csv)"))
        isfile(profile_csv) || throw(ArgumentError("missing profile CSV: $(profile_csv)"))
        diag = _first_csv_row_dict(diagnostics_csv)
        B = _dict_float(diag, "B", diagnostics_csv)
        C = _dict_float(diag, "C", diagnostics_csv)
        A = _dict_float(diag, "A", diagnostics_csv)
        Lz = _dict_float(diag, "Lz", diagnostics_csv)
        target_xi = Float64(_target_row_value(target_row, :target_xi_eff))
        tolerance = Float64(_target_row_value(target_row, :tolerance, 0.02))
        profile = _read_slit_profile_series(profile_csv, "mc_mean_3d")
        z = profile.z_over_L .* Lz
        target_phi = slit_reference_profile(z; B=B, C=C, L=Lz, xi=target_xi)
        target_profile = _slit_profile_fit_diagnostics(profile.phi, target_phi)
        production_xi = _dict_float(diag, "xi_eff", diagnostics_csv)
        abs_xi_error = abs(production_xi - target_xi)
        xi_pass = abs_xi_error <= tolerance
        full_profile_pass = xi_pass && target_profile.r2 >= r2_gate
        status = full_profile_pass ? "full_profile_pass" :
                 xi_pass ? "xi_pass_profile_shape_caveat" : "not_calibrated"
        BC = B * C
        tag = String(_target_row_value(target_row, :tag,
            replace(@sprintf("BC%.6g", BC), "." => "p")))
        push!(mapping_rows, (
            tag=tag,
            B=B,
            BC=BC,
            C=C,
            target_xi_eff=target_xi,
            xi_bulk=_dict_float(diag, "xi_bulk", diagnostics_csv),
            A=A,
            tolerance=tolerance,
            production_xi_eff=production_xi,
            abs_xi_error=abs_xi_error,
            rel_xi_error=abs_xi_error / target_xi,
            fit_rmse=_dict_float(diag, "xi_fit_rmse", diagnostics_csv),
            fit_r2=_dict_float(diag, "xi_fit_r2", diagnostics_csv),
            target_profile_rmse=target_profile.rmse,
            target_profile_r2=target_profile.r2,
            target_profile_r2_threshold=r2_gate,
            profile_chain_rhat_max=_dict_float(diag, "profile_chain_rhat_max", diagnostics_csv),
            profile_split_rhat_max=_dict_float(diag, "profile_split_rhat_max", diagnostics_csv),
            acceptance_rate=_dict_float(diag, "acceptance_rate", diagnostics_csv),
            sample_count=_dict_float(diag, "sample_count", diagnostics_csv),
            calibration_status=status,
            production_outdir=prod_outdir,
        ))
    end
    sorted_rows = sort(mapping_rows; by=row -> row.BC)
    summary_csv = _write_dataframe(joinpath(outdir, "ak_fig4_B25_vk1_A_mapping.csv"), sorted_rows)
    a_svg = _write_ak_fig4_b25_a_svg(sorted_rows, outdir)
    xi_svg = _write_ak_fig4_b25_xi_svg(sorted_rows, outdir)
    markdown_path = _write_ak_fig4_b25_mapping_text(outdir, sorted_rows)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "ak_fig4_b25_vk1_a_mapping",
            "sampler" => "profile_mode_metropolis",
        ),
        "target" => Dict{String,Any}(
            "observable" => "AK Fig. 4 B=25 effective xi",
            "target_profile_r2_threshold" => r2_gate,
            "point_count" => length(sorted_rows),
        ),
        "outputs" => Dict{String,Any}(
            "summary_csv" => summary_csv,
            "a_svg" => a_svg,
            "xi_svg" => xi_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return AlexanderKatzFig4VK1AMappingResult(summary_csv, a_svg, xi_svg,
        markdown_path, metadata_path, length(sorted_rows))
end

function _csv_row_dicts(path::AbstractString)
    header, rows = _read_csv_strings(path)
    return [Dict(header[i] => row[i] for i in eachindex(header)) for row in rows]
end

function _read_ak_fig4_digitized_targets(path::AbstractString; B::Real=25.0)
    dicts = _csv_row_dicts(path)
    targets = NamedTuple[]
    target_B = Float64(B)
    for row in dicts
        row_B = _dict_float(row, "B", path)
        isapprox(row_B, target_B; atol=1.0e-10, rtol=1.0e-10) || continue
        BC = _dict_float(row, "BC", path)
        xi_eff = _dict_float(row, "xi_eff", path)
        BC > 0.0 || throw(ArgumentError("Fig. 4 target BC must be positive in $(path)"))
        xi_eff > 0.0 || throw(ArgumentError("Fig. 4 target xi_eff must be positive in $(path)"))
        push!(targets, (
            B=row_B,
            BC=BC,
            C=_dict_float(row, "C", path),
            xi_eff=xi_eff,
            xi_bulk=_dict_float(row, "xi_bulk", path),
            source=_dict_string(row, "source"),
            series=_dict_string(row, "series"),
        ))
    end
    isempty(targets) &&
        throw(ArgumentError("Fig. 4 target CSV has no B=$(target_B) rows: $(path)"))
    return sort(targets; by=row -> row.BC)
end

function _read_ak_fig4_b25_digitized_targets(path::AbstractString)
    return _read_ak_fig4_digitized_targets(path; B=25.0)
end

function _ak_fig4_loglog_target_xi(targets, BC::Real)
    bc = Float64(BC)
    bc > 0.0 || throw(ArgumentError("BC must be positive"))
    length(targets) >= 2 ||
        throw(ArgumentError("at least two Fig. 4 target rows are required"))
    sorted = sort(targets; by=row -> row.BC)
    xs = [log10(row.BC) for row in sorted]
    ys = [log10(row.xi_eff) for row in sorted]
    x = log10(bc)
    if x <= first(xs)
        lo = 1
    elseif x >= last(xs)
        lo = length(xs) - 1
    else
        lo = searchsortedlast(xs, x)
        lo = min(lo, length(xs) - 1)
    end
    lo = max(lo, 1)
    hi = lo + 1
    xs[hi] > xs[lo] || throw(ArgumentError("Fig. 4 target BC values must be strictly increasing"))
    weight = (x - xs[lo]) / (xs[hi] - xs[lo])
    return 10.0 ^ (ys[lo] + weight * (ys[hi] - ys[lo]))
end

function _dict_string(row::Dict{String,String}, key::AbstractString, default="")
    return haskey(row, key) ? row[key] : String(default)
end

function _predict_loglog_A(calibration_rows, BC::Real; match_rtol::Real=1.0e-8)
    bc = Float64(BC)
    bc > 0.0 || throw(ArgumentError("BC must be positive"))
    length(calibration_rows) >= 2 ||
        throw(ArgumentError("at least two calibration rows are required for A prediction"))
    sorted = sort(calibration_rows; by=row -> row.BC)
    for row in sorted
        if abs(row.BC - bc) <= match_rtol * max(abs(row.BC), abs(bc), 1.0)
            return (A=row.A, status="calibrated", lower_BC=row.BC, upper_BC=row.BC)
        end
    end
    idx = searchsortedlast([row.BC for row in sorted], bc)
    status = "interpolation"
    if idx == 0
        idx = 1
        status = "low_extrapolation"
    elseif idx >= length(sorted)
        idx = length(sorted) - 1
        status = "high_extrapolation"
    end
    lo = sorted[idx]
    hi = sorted[idx + 1]
    x_lo = log(lo.BC)
    x_hi = log(hi.BC)
    y_lo = log(lo.A)
    y_hi = log(hi.A)
    x_hi > x_lo || throw(ArgumentError("calibration BC values must be strictly increasing"))
    t = (log(bc) - x_lo) / (x_hi - x_lo)
    return (A=exp((1.0 - t) * y_lo + t * y_hi), status=status,
        lower_BC=lo.BC, upper_BC=hi.BC)
end

function _write_ak_fig4_b25_a_prediction_svg(rows, calibration_rows, outdir::AbstractString)
    mkpath(outdir)
    svg_path = joinpath(outdir, "ak_fig4_B25_A_prediction.svg")
    isempty(rows) && return svg_path
    xs = log10.(vcat([row.BC for row in rows], [row.BC for row in calibration_rows]))
    ys = log10.(vcat([row.predicted_A for row in rows], [row.A for row in calibration_rows]))
    xmin, xmax = _expand_plot_range(minimum(xs), maximum(xs))
    ymin, ymax = _expand_plot_range(minimum(ys), maximum(ys))
    xticks = _major_ticks(xmin, xmax; count=8)
    yticks = _major_ticks(ymin, ymax; count=8)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / (xmax - xmin)
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / (ymax - ymin)
    predicted = sort(rows; by=row -> row.BC)
    calibrated = sort(calibration_rows; by=row -> row.BC)
    predicted_points = [(x_plot(log10(row.BC)), y_plot(log10(row.predicted_A))) for row in predicted]
    calibrated_points = [(x_plot(log10(row.BC)), y_plot(log10(row.A))) for row in calibrated]
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>AK Fig. 4 B=25 predicted A</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>AK Fig. 4 B=25 predicted A</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot;
            x_label=_format_log10_tick, y_label=_format_log10_tick)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>BC</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>A</text>")
        println(io, "<polyline fill='none' stroke='#1f77b4' stroke-width='2.4' points='$(_svg_polyline(predicted_points))'/>")
        println(io, "<polyline fill='none' stroke='#333333' stroke-width='1.8' stroke-dasharray='6 4' points='$(_svg_polyline(calibrated_points))'/>")
        for row in predicted
            color = row.prediction_status == "calibrated" ? "#333333" :
                    row.prediction_status == "interpolation" ? "#1f77b4" : "#d62728"
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4.0' fill='%s'/>",
                x_plot(log10(row.BC)), y_plot(log10(row.predicted_A)), color))
        end
        println(io, "<text x='410' y='80' font-size='12'>black: calibrated</text>")
        println(io, "<text x='410' y='100' font-size='12'>blue: interpolation</text>")
        println(io, "<text x='410' y='120' font-size='12'>red: extrapolation</text>")
        println(io, "</svg>")
    end
    return svg_path
end

function _write_ak_fig4_b25_a_prediction_text(outdir::AbstractString, rows, calibration_rows)
    path = joinpath(outdir, "ak_fig4_B25_A_prediction.md")
    interpolated = count(row -> row.prediction_status == "interpolation", rows)
    extrapolated = count(row -> occursin("extrapolation", row.prediction_status), rows)
    calibrated = count(row -> row.prediction_status == "calibrated", rows)
    open(path, "w") do io
        println(io, "# AK Fig. 4 B=25 A(BC) prediction")
        println(io)
        println(io, "This artifact predicts the VK1 correction coefficient `A` for digitized AK Fig. 4 `B = 25` targets using piecewise log-log interpolation through production-confirmed calibration points.")
        println(io)
        println(io, @sprintf("Calibration points: %.0f; calibrated targets: %.0f; interpolated targets: %.0f; extrapolated targets: %.0f.",
            Float64(length(calibration_rows)), Float64(calibrated), Float64(interpolated),
            Float64(extrapolated)))
        println(io)
        println(io, "Predictions marked as extrapolation are exploratory and should not be used as manuscript validation until confirmed by independent MC production runs.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `ak_fig4_B25_A_prediction.csv`")
        println(io, "- `ak_fig4_B25_A_prediction.svg`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function write_ak_fig4_b25_a_prediction(
    outdir::AbstractString;
    mapping_csv::AbstractString,
    fig4_xi_csv::AbstractString,
)
    mkpath(outdir)
    mapping_dicts = _csv_row_dicts(mapping_csv)
    fig4_dicts = _csv_row_dicts(fig4_xi_csv)
    calibration_rows = NamedTuple[]
    for row in mapping_dicts
        status = _dict_string(row, "calibration_status")
        status == "not_calibrated" && continue
        B = _dict_float(row, "B", mapping_csv)
        BC = _dict_float(row, "BC", mapping_csv)
        A = _dict_float(row, "A", mapping_csv)
        B > 0.0 && BC > 0.0 && A > 0.0 ||
            throw(ArgumentError("mapping rows must have positive B, BC, and A"))
        push!(calibration_rows, (
            tag=_dict_string(row, "tag"),
            B=B,
            BC=BC,
            C=_dict_float(row, "C", mapping_csv),
            A=A,
            calibration_status=status,
        ))
    end
    length(calibration_rows) >= 2 ||
        throw(ArgumentError("prediction requires at least two calibrated mapping rows"))
    target_rows = NamedTuple[]
    for row in fig4_dicts
        B = _dict_float(row, "B", fig4_xi_csv)
        isapprox(B, 25.0; atol=1.0e-10, rtol=1.0e-10) || continue
        BC = _dict_float(row, "BC", fig4_xi_csv)
        predicted = _predict_loglog_A(calibration_rows, BC)
        push!(target_rows, (
            source=_dict_string(row, "source"),
            series=_dict_string(row, "series"),
            B=B,
            BC=BC,
            C=_dict_float(row, "C", fig4_xi_csv),
            target_xi_eff=_dict_float(row, "xi_eff", fig4_xi_csv),
            xi_bulk=_dict_float(row, "xi_bulk", fig4_xi_csv),
            predicted_A=predicted.A,
            prediction_status=predicted.status,
            lower_calibration_BC=predicted.lower_BC,
            upper_calibration_BC=predicted.upper_BC,
            model="piecewise_loglog_linear",
        ))
    end
    sorted_targets = sort(target_rows; by=row -> row.BC)
    prediction_csv = _write_dataframe(joinpath(outdir, "ak_fig4_B25_A_prediction.csv"),
        sorted_targets)
    prediction_svg = _write_ak_fig4_b25_a_prediction_svg(sorted_targets,
        calibration_rows, outdir)
    markdown_path = _write_ak_fig4_b25_a_prediction_text(outdir, sorted_targets,
        calibration_rows)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "ak_fig4_b25_a_prediction",
            "model" => "piecewise_loglog_linear",
        ),
        "inputs" => Dict{String,Any}(
            "mapping_csv" => String(mapping_csv),
            "fig4_xi_csv" => String(fig4_xi_csv),
        ),
        "outputs" => Dict{String,Any}(
            "prediction_csv" => prediction_csv,
            "prediction_svg" => prediction_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return AlexanderKatzFig4APredictionResult(prediction_csv, prediction_svg,
        markdown_path, metadata_path, length(sorted_targets))
end

function run_alexander_katz_figure_validation(
    outdir::AbstractString;
    Nz::Integer=200,
    L::Real=1.0,
    fig2_bc_values=[1.0, 10.0, 100.0, 1000.0],
    fig3_B::Real=25.0,
    fig3_C::Real=0.5,
    fig3_mc_A::Real=0.0,
    fig3_mc_steps::Integer=80_000,
    fig3_mc_burnin_steps::Integer=20_000,
    fig3_mc_sample_stride::Integer=20,
    fig3_mc_basis_count::Integer=4,
    fig3_mc_proposal_width::Real=0.03,
    fig3_mc_temperature::Real=1.0,
    fig3_mc_seed::Integer=1701,
)
    mkpath(outdir)
    grid = SlitGrid1D(Nz, L)
    marker_indices = _alexander_katz_marker_indices(grid.Nz; target=28)
    fig2_rows = NamedTuple[]
    marker_by_bc = Dict(1.0 => "open_circle", 10.0 => "filled_circle", 100.0 => "open_circle", 1000.0 => "x")
    for bc in Float64.(fig2_bc_values)
        bc > 0.0 || throw(ArgumentError("Fig. 2 BC values must be positive"))
        xi = 1.0 / sqrt(2.0 * bc)
        phi = slit_reference_profile(grid.z; B=bc, C=1.0, L=grid.L, xi=xi)
        for i in 1:grid.Nz
            push!(fig2_rows, (
                figure="fig2",
                series="eq22_line",
                marker="line",
                B=bc,
                C=1.0,
                BC=bc,
                xi=xi,
                z_over_L=grid.z[i] / grid.L,
                phi=phi[i],
            ))
        end
        marker = get(marker_by_bc, bc, "open_circle")
        for i in marker_indices
            push!(fig2_rows, (
                figure="fig2",
                series="saddle_points",
                marker=marker,
                B=bc,
                C=1.0,
                BC=bc,
                xi=xi,
                z_over_L=grid.z[i] / grid.L,
                phi=phi[i],
            ))
        end
    end
    fig3_B_f = Float64(fig3_B)
    fig3_C_f = Float64(fig3_C)
    fig3_B_f > 0.0 && fig3_C_f > 0.0 || throw(ArgumentError("Fig. 3 B and C must be positive"))
    fig3_bc = fig3_B_f * fig3_C_f
    xi_bulk = 1.0 / sqrt(2.0 * fig3_bc)
    noise = run_slit_noise_profile_mc(fig3_B_f, fig3_C_f, fig3_mc_A; Nz=grid.Nz, L=grid.L,
        basis_count=fig3_mc_basis_count, steps=fig3_mc_steps,
        burnin_steps=fig3_mc_burnin_steps, sample_stride=fig3_mc_sample_stride,
        proposal_width=fig3_mc_proposal_width, temperature=fig3_mc_temperature,
        seed=fig3_mc_seed)
    saddle_phi = noise.saddle_phi
    mc_phi = noise.mean_phi
    mc_fit_phi = slit_reference_profile(grid.z; B=fig3_B_f, C=fig3_C_f, L=grid.L, xi=noise.xi_eff)
    fig3_rows = NamedTuple[]
    for i in 1:grid.Nz
        push!(fig3_rows, (
            figure="fig3",
            series="eq22_mean_field",
            marker="line",
            B=fig3_B_f,
            C=fig3_C_f,
            BC=fig3_bc,
            xi=xi_bulk,
            z_over_L=grid.z[i] / grid.L,
            phi=saddle_phi[i],
            stderr=0.0,
        ))
        push!(fig3_rows, (
            figure="fig3",
            series="mc_noise_profile",
            marker="line",
            B=fig3_B_f,
            C=fig3_C_f,
            BC=fig3_bc,
            xi=noise.xi_eff,
            z_over_L=grid.z[i] / grid.L,
            phi=mc_phi[i],
            stderr=noise.stderr_phi[i],
        ))
        push!(fig3_rows, (
            figure="fig3",
            series="mc_eq22_fit",
            marker="line",
            B=fig3_B_f,
            C=fig3_C_f,
            BC=fig3_bc,
            xi=noise.xi_eff,
            z_over_L=grid.z[i] / grid.L,
            phi=mc_fit_phi[i],
            stderr=0.0,
        ))
    end
    for i in marker_indices
        push!(fig3_rows, (
            figure="fig3",
            series="saddle_points",
            marker="open_square",
            B=fig3_B_f,
            C=fig3_C_f,
            BC=fig3_bc,
            xi=xi_bulk,
            z_over_L=grid.z[i] / grid.L,
            phi=saddle_phi[i],
            stderr=0.0,
        ))
        push!(fig3_rows, (
            figure="fig3",
            series="mc_noise_points",
            marker="filled_square",
            B=fig3_B_f,
            C=fig3_C_f,
            BC=fig3_bc,
            xi=noise.xi_eff,
            z_over_L=grid.z[i] / grid.L,
            phi=mc_phi[i],
            stderr=noise.stderr_phi[i],
        ))
    end
    fig2_csv = _write_dataframe(joinpath(outdir, "fig2_profiles.csv"), fig2_rows)
    fig3_csv = _write_dataframe(joinpath(outdir, "fig3_profiles.csv"), fig3_rows)
    fig2_svg = _write_alexander_katz_fig2_svg(fig2_rows, outdir)
    fig3_svg = _write_alexander_katz_fig3_svg(fig3_rows, outdir)
    summary_rows = [
        (metric="fig2_bc_count", value=Float64(length(fig2_bc_values)), note="Number of Fig. 2 BC profiles"),
        (metric="fig2_min_bc", value=minimum(Float64.(fig2_bc_values)), note="Smallest Fig. 2 BC"),
        (metric="fig2_max_bc", value=maximum(Float64.(fig2_bc_values)), note="Largest Fig. 2 BC"),
        (metric="fig3_B", value=fig3_B_f, note="Reference Fig. 3 caption B"),
        (metric="fig3_C", value=fig3_C_f, note="Reference Fig. 3 caption C"),
        (metric="fig3_BC", value=fig3_bc, note="Reference Fig. 3 product BC"),
        (metric="fig3_xi_bulk", value=xi_bulk, note="Eq. 22 saddle correlation length"),
        (metric="fig3_noise_source_code", value=1.0, note="1 means MC-generated noise profile"),
        (metric="fig3_mc_A", value=Float64(fig3_mc_A), note="Stable HE-VK1 fluctuation correction used in MC target"),
        (metric="fig3_mc_temperature", value=noise.temperature, note="Metropolis sampling temperature"),
        (metric="fig3_mc_proposal_width", value=noise.proposal_width, note="Coefficient proposal width"),
        (metric="fig3_mc_basis_count", value=Float64(noise.basis_count), note="Smooth cosine basis count"),
        (metric="fig3_mc_steps", value=Float64(noise.steps), note="Total MC moves"),
        (metric="fig3_mc_burnin_steps", value=Float64(noise.burnin_steps), note="Discarded burn-in moves"),
        (metric="fig3_mc_sample_stride", value=Float64(noise.sample_stride), note="Stored-sample stride"),
        (metric="fig3_mc_sample_count", value=Float64(noise.sample_count), note="Stored MC density profiles"),
        (metric="fig3_mc_acceptance_rate", value=noise.acceptance_rate, note="Metropolis acceptance rate"),
        (metric="fig3_mc_xi_eff", value=noise.xi_eff, note="Eq. 22 effective-xi fit to MC mean profile"),
        (metric="fig3_mc_xi_fit_error", value=noise.xi_fit_error, note="Mean-square fit error for MC profile"),
        (metric="fig3_mc_energy_mean", value=noise.energy_mean, note="Mean sampled HE-VK1 energy"),
        (metric="fig3_mc_energy_stderr", value=noise.energy_stderr, note="Markov standard error for sampled energy"),
        (metric="fig3_peak_saddle", value=maximum(saddle_phi), note="Maximum saddle density"),
        (metric="fig3_peak_mc_noise", value=maximum(mc_phi), note="Maximum MC-generated with-noise density"),
        (metric="fig3_peak_mc_eq22_fit", value=maximum(mc_fit_phi), note="Maximum Eq. 22 fit to MC mean profile"),
        (metric="grid_Nz", value=Float64(grid.Nz), note="Midpoint grid cells"),
        (metric="grid_L", value=grid.L, note="Slit width"),
    ]
    summary_csv = _write_dataframe(joinpath(outdir, "summary.csv"), summary_rows)
    markdown_path = _write_alexander_katz_text(outdir, summary_rows)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "alexander_katz_figure_validation",
            "Nz" => grid.Nz,
            "L" => grid.L,
        ),
        "reference" => Dict{String,Any}(
            "paper" => "Alexander-Katz et al. 2003 - Field-theoretic simulations of confined polymer solutions",
            "fig2" => "Saddle profiles at BC = 1, 10, 100, 1000",
            "fig3" => "Caption parameters B = 25, C = 0.5; upper curve generated from a Monte Carlo density-profile average",
        ),
        "parameters" => Dict{String,Any}(
            "fig2_bc_values" => Float64.(fig2_bc_values),
            "fig3_B" => fig3_B_f,
            "fig3_C" => fig3_C_f,
            "fig3_BC" => fig3_bc,
            "fig3_xi_bulk" => xi_bulk,
            "fig3_mc_A" => Float64(fig3_mc_A),
            "fig3_mc_steps" => Int(fig3_mc_steps),
            "fig3_mc_burnin_steps" => Int(fig3_mc_burnin_steps),
            "fig3_mc_sample_stride" => Int(fig3_mc_sample_stride),
            "fig3_mc_basis_count" => Int(fig3_mc_basis_count),
            "fig3_mc_proposal_width" => Float64(fig3_mc_proposal_width),
            "fig3_mc_temperature" => Float64(fig3_mc_temperature),
            "fig3_mc_seed" => Int(fig3_mc_seed),
        ),
        "outputs" => Dict{String,Any}(
            "fig2_csv" => fig2_csv,
            "fig2_svg" => fig2_svg,
            "fig3_csv" => fig3_csv,
            "fig3_svg" => fig3_svg,
            "summary_csv" => summary_csv,
            "markdown_path" => markdown_path,
        ),
        "mc_diagnostics" => Dict{String,Any}(
            "fluctuation_source" => "Metropolis sampling of smooth normalized HE-VK1 slit density profiles",
            "sample_count" => noise.sample_count,
            "acceptance_rate" => noise.acceptance_rate,
            "xi_eff" => noise.xi_eff,
            "xi_fit_error" => noise.xi_fit_error,
            "energy_mean" => noise.energy_mean,
            "energy_stderr" => noise.energy_stderr,
            "peak_saddle" => maximum(saddle_phi),
            "peak_mc_noise" => maximum(mc_phi),
        ),
        "limitations" => Dict{String,Any}(
            "mc_sampler_scope" => "Smooth real-density HE-VK1 basis sampler; not the original complex-Langevin Omega-field algorithm.",
            "excluded_overlay" => "Bulk-fitted A = 299 slit overlay is outside the validated slit correction regime for Fig. 3.",
        ),
        "environment" => _metadata_environment(),
    ))
    return AlexanderKatzFigureResult(fig2_csv, fig2_svg, fig3_csv, fig3_svg, summary_csv, markdown_path, metadata_path)
end

function _slit_summary_row(result::SlitSaddleResult)
    p = result.params
    return [
        String(result.model),
        p.A,
        p.B,
        p.C,
        p.B * p.C,
        result.xi_eff,
        result.xi_fit_error,
        result.xi_bulk,
        result.mu_estimate,
        result.energy,
        result.rms_reference_error,
        result.status,
    ]
end

function run_slit_saddle_validation(
    outdir::AbstractString;
    Nz::Integer=80,
    L::Real=1.0,
    B_values=[1.0, 10.0, 25.0],
    C_values=[0.1, 0.2, 0.5, 1.0, 2.0, 5.0, 10.0, 25.0],
    A_values=[0.0, 299.0],
    alpha::Real=0.0,
    models=[:urp_ti, :vk1],
)
    mkpath(outdir)
    results = SlitSaddleResult[]
    for model in models, A in A_values, B in B_values, C in C_values
        push!(results, minimize_slit_density(model, B, C, A; Nz=Nz, L=L, alpha=alpha))
    end
    profile_header = ["model", "A", "B", "C", "BC", "z", "phi", "reference_phi", "xi_eff", "status"]
    profile_rows = Any[]
    for result in results
        p = result.params
        for i in 1:result.grid.Nz
            push!(profile_rows, [
                String(result.model),
                p.A,
                p.B,
                p.C,
                p.B * p.C,
                result.grid.z[i] / result.grid.L,
                result.phi[i],
                result.reference_phi[i],
                result.xi_eff,
                result.status,
            ])
        end
    end
    summary_header = ["model", "A", "B", "C", "BC", "xi_eff", "xi_fit_error", "xi_bulk",
        "mu_estimate", "energy", "rms_reference_error", "status"]
    summary_rows = [_slit_summary_row(result) for result in results]
    profile_csv = _write_table(joinpath(outdir, "slit_density_profiles.csv"), profile_header, profile_rows)
    summary_csv = _write_table(joinpath(outdir, "slit_summary.csv"), summary_header, summary_rows)
    profile_svg = _write_slit_profile_svg(profile_csv, outdir)
    xi_svg = _write_slit_xi_svg(summary_csv, outdir)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_saddle_validation",
            "models" => [String(Symbol(model)) for model in models],
            "Nz" => Int(Nz),
            "L" => Float64(L),
            "alpha" => Float64(alpha),
        ),
        "parameters" => Dict{String,Any}(
            "B_values" => Float64.(B_values),
            "C_values" => Float64.(C_values),
            "A_values" => Float64.(A_values),
        ),
        "estimator" => Dict{String,Any}(
            "profile_family" => "Alexander-Katz Eq. 22 ansatz",
            "operator" => "diagnostic_confined_sine_debye_v1",
            "primary_claim" => "HE-VK1 inhomogeneous saddle-level validation; HE-URP-TI slit branch is diagnostic only",
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "summary_csv" => summary_csv,
            "profile_svg" => profile_svg,
            "xi_svg" => xi_svg,
        ),
        "environment" => _metadata_environment(),
    ))
    markdown_path = write_slit_validation_text(outdir)
    return SlitValidationResult(profile_csv, summary_csv, profile_svg, xi_svg, markdown_path, metadata_path)
end

function write_slit_validation_text(outdir::AbstractString)
    summary_csv = joinpath(outdir, "slit_summary.csv")
    markdown_path = joinpath(outdir, "slit_validation.md")
    header, rows = isfile(summary_csv) ? _read_csv_strings(summary_csv) : (String[], Vector{Vector{String}}())
    status_counts = Dict{String,Int}()
    if !isempty(rows)
        status_idx = findfirst(==("status"), header)
        for row in rows
            status_counts[row[status_idx]] = get(status_counts, row[status_idx], 0) + 1
        end
    end
    open(markdown_path, "w") do io
        println(io, "# Slit confinement validation")
        println(io)
        println(io, "This artifact evaluates HE-VK1 as the current real density Hamiltonian for an inhomogeneous homopolymer solution confined in a slit, following Alexander-Katz et al. 2003.")
        println(io)
        println(io, "The `urp_ti` rows are retained as a diagnostic bulk-kernel extension, not as manuscript-ready confined HE-URP-TI evidence. The manuscript URP transferability tests concern the approximate saddle field `iw_URP[phi]` for prescribed periodic densities. The plotted slit `urp_ti` branch instead minimizes a straight-path scalar work functional with a sine-basis Debye inverse. For nonlinear inhomogeneous fields this scalar's first variation is not the same as the URP force, and the sine-Debye operator is not a propagator-derived hard-wall single-chain response kernel.")
        println(io)
        println(io, "Primary interpretation: `A = 0` is the saddle-level validation. `A = 299` is included as a diagnostic bulk-fitted fluctuation-correction overlay and rows outside the stable bulk criterion are explicitly marked.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_density_profiles.csv` and `slit_density_profiles.svg`")
        println(io, "- `slit_summary.csv` and `slit_xi_eff.svg`")
        println(io, "- `run_metadata.toml`")
        if !isempty(status_counts)
            println(io)
            println(io, "Status counts:")
            for key in sort(collect(keys(status_counts)))
                println(io, "- `$key`: $(status_counts[key])")
            end
        end
        println(io)
        println(io, "The confined nonlocal HE-URP-TI diagnostic operator is recorded as `diagnostic_confined_sine_debye_v1`. Its disagreement with Eq. 22 should be read as evidence that the confined URP-TI branch needs a separate derivation, not as a failure of the manuscript's periodic-density URP saddle-field tests.")
    end
    return markdown_path
end

function write_slit_vk1_field_saddle_text(outdir::AbstractString)
    summary_csv = joinpath(outdir, "slit_vk1_field_summary.csv")
    markdown_path = joinpath(outdir, "slit_vk1_field_saddle.md")
    header, rows = isfile(summary_csv) ? _read_csv_strings(summary_csv) : (String[], Vector{Vector{String}}())
    row_values = Dict{String,String}[]
    for row in rows
        values = Dict{String,String}()
        for (i, name) in pairs(header)
            values[name] = row[i]
        end
        push!(row_values, values)
    end
    open(markdown_path, "w") do io
        println(io, "# HE-VK1 slit saddle validation")
        println(io)
        println(io, "This artifact solves the HE-VK1 slit saddle by deterministic constrained minimization of the discretized one-dimensional density field. It is not a Monte Carlo trajectory and it is not restricted to the one-parameter Alexander-Katz Eq. 22 profile family.")
        println(io)
        println(io, "The density is represented on midpoint grid cells. Positivity and normalization are enforced by optimizing log-density coordinates and reconstructing a positive profile with `integral phi dz = L`. The wall condition enters through the HE-VK1 gradient term, which evaluates endpoint derivatives across half-cell wall distances against zero wall density.")
        println(io)
        println(io, "The default manuscript-grade profile CSV includes the Eq. 22 reference, the restricted Eq. 22-family VK1 fit, and a converged smooth cosine-basis log-density saddle. A free-grid full-field refinement can be requested as a diagnostic with `include_full_field=true`, but it is not the default evidence path because the high-dimensional nonsmooth optimization is harder to converge reliably. The old central-gradient Eq. 22-family result is diagnostic-only because the central stencil is unsafe for free saddle optimization.")
        if !isempty(row_values)
            println(io)
            first_values = row_values[1]
            println(io, "Representative parameters:")
            println(io, @sprintf("- `B = %.6g`, `C = %.6g`, `A = %.6g`, `Nz = %d`.",
                parse(Float64, first_values["B"]),
                parse(Float64, first_values["C"]),
                parse(Float64, first_values["A"]),
                parse(Int, first_values["Nz"])))
            println(io)
            println(io, "Solver rows:")
            for values in row_values
                println(io, @sprintf("- `%s`: RMS %.6e, `xi_eff` %.6g vs `xi_b` %.6g, energy delta vs Eq. 22-family %.6e, projected-gradient RMS %.6e, profile pass `%s`, optimizer converged `%s`.",
                    values["solver"],
                    parse(Float64, values["rms_reference_error"]),
                    parse(Float64, values["xi_eff"]),
                    parse(Float64, values["xi_bulk"]),
                    parse(Float64, values["energy_delta_vs_ansatz"]),
                    parse(Float64, values["projected_gradient_rms"]),
                    values["profile_agreement_pass"],
                    values["optimizer_converged"]))
            end
        end
        println(io)
        println(io, "Manuscript use: the converged smooth-basis row is the deterministic saddle-profile evidence for HE-VK1 in the slit. The earlier `slit_validation` Eq. 22-family scan is useful as a restricted diagnostic, and optional full-field free-grid refinement is a numerical diagnostic rather than the primary manuscript claim.")
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_vk1_field_profiles.csv`")
        println(io, "- `slit_vk1_field_summary.csv`")
        println(io, "- `slit_vk1_field_profiles.svg`")
        println(io, "- `run_metadata.toml`")
    end
    return markdown_path
end

function run_slit_vk1_field_saddle_validation(
    outdir::AbstractString;
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    Nz::Integer=160,
    L::Real=1.0,
    alpha::Real=0.0,
    max_iterations::Integer=1000,
    smooth_basis_count::Integer=24,
    smooth_max_iterations::Integer=30000,
    include_smooth_basis::Bool=true,
    include_full_field::Bool=false,
)
    mkpath(outdir)
    if !include_smooth_basis && !include_full_field
        throw(ArgumentError("at least one of include_smooth_basis or include_full_field must be true"))
    end
    smooth_result = include_smooth_basis ?
                    minimize_slit_vk1_smooth_basis_saddle(B, C, A; Nz=Nz, L=L, alpha=alpha,
                        basis_count=smooth_basis_count, max_iterations=smooth_max_iterations) :
                    nothing
    field_result = include_full_field || smooth_result === nothing ?
                   minimize_slit_vk1_field_saddle(B, C, A; Nz=Nz, L=L, alpha=alpha,
                       max_iterations=max_iterations, initial_profile=smooth_result === nothing ? nothing : smooth_result.phi) :
                   nothing
    primary_result = field_result === nothing ? smooth_result : field_result
    profile_header = ["profile", "B", "C", "A", "z", "phi", "energy", "rms_reference_error"]
    profile_rows = Any[]
    profile_specs = Any[
        ("eq22_reference", primary_result.reference_phi, primary_result.reference_energy, 0.0),
        ("vk1_eq22_family", primary_result.ansatz_phi, primary_result.ansatz_energy, primary_result.ansatz_rms_reference_error),
    ]
    if smooth_result !== nothing
        push!(profile_specs, ("vk1_smooth_basis", smooth_result.phi, smooth_result.energy, smooth_result.rms_reference_error))
    end
    if field_result !== nothing
        push!(profile_specs, ("vk1_full_field", field_result.phi, field_result.energy, field_result.rms_reference_error))
    end
    for (name, phi, energy, rms) in profile_specs
        for i in 1:primary_result.grid.Nz
            push!(profile_rows, [
                name,
                primary_result.params.B,
                primary_result.params.C,
                primary_result.params.A,
                primary_result.grid.z[i] / primary_result.grid.L,
                phi[i],
                energy,
                rms,
            ])
        end
    end
    summary_header = ["B", "C", "A", "Nz", "L", "solver", "optimizer_converged", "profile_agreement_pass", "iterations", "objective_calls",
        "xi_bulk", "xi_eff", "xi_fit_error", "energy", "reference_energy", "ansatz_energy",
        "energy_delta_vs_ansatz", "energy_delta_vs_reference", "rms_reference_error",
        "max_abs_reference_error", "ansatz_rms_reference_error", "projected_gradient_rms",
        "projected_gradient_max", "status"]
    profile_csv = _write_table(joinpath(outdir, "slit_vk1_field_profiles.csv"), profile_header, profile_rows)
    summary_rows = Any[]
    if smooth_result !== nothing
        push!(summary_rows, _slit_field_summary_row(smooth_result))
    end
    if field_result !== nothing
        push!(summary_rows, _slit_field_summary_row(field_result))
    end
    summary_csv = _write_table(joinpath(outdir, "slit_vk1_field_summary.csv"), summary_header, summary_rows)
    profile_svg = _write_slit_vk1_field_profile_svg(profile_csv, outdir)
    diagnostic_metadata = Dict{String,Any}(
        "primary_solver" => primary_result.solver,
        "optimizer_converged" => primary_result.converged,
        "profile_agreement_pass" => primary_result.energy <= primary_result.ansatz_energy + 1.0e-5 && primary_result.rms_reference_error < 5.0e-2,
        "iterations" => primary_result.iterations,
        "objective_calls" => primary_result.objective_calls,
        "rms_reference_error" => primary_result.rms_reference_error,
        "projected_gradient_rms" => primary_result.projected_gradient_rms,
        "energy_delta_vs_ansatz" => primary_result.energy - primary_result.ansatz_energy,
    )
    if smooth_result !== nothing
        diagnostic_metadata["smooth_basis_optimizer_converged"] = smooth_result.converged
        diagnostic_metadata["smooth_basis_rms_reference_error"] = smooth_result.rms_reference_error
        diagnostic_metadata["smooth_basis_energy_delta_vs_ansatz"] = smooth_result.energy - smooth_result.ansatz_energy
    end
    if field_result !== nothing
        diagnostic_metadata["full_field_optimizer_converged"] = field_result.converged
        diagnostic_metadata["full_field_rms_reference_error"] = field_result.rms_reference_error
        diagnostic_metadata["full_field_energy_delta_vs_ansatz"] = field_result.energy - field_result.ansatz_energy
    end
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_vk1_field_saddle_validation",
            "model" => "vk1",
            "solver" => primary_result.solver,
            "Nz" => Int(Nz),
            "L" => Float64(L),
            "alpha" => Float64(alpha),
            "full_field_max_iterations" => Int(max_iterations),
            "include_smooth_basis" => include_smooth_basis,
            "include_full_field" => include_full_field,
            "smooth_basis_count" => Int(smooth_basis_count),
            "smooth_max_iterations" => Int(smooth_max_iterations),
        ),
        "parameters" => Dict{String,Any}(
            "A" => Float64(A),
            "B" => Float64(B),
            "C" => Float64(C),
        ),
        "diagnostics" => diagnostic_metadata,
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "summary_csv" => summary_csv,
            "profile_svg" => profile_svg,
        ),
        "environment" => _metadata_environment(),
    ))
    markdown_path = write_slit_vk1_field_saddle_text(outdir)
    return SlitFieldValidationResult(profile_csv, summary_csv, profile_svg, markdown_path, metadata_path)
end

function _write_slit_3d_profile_svg(profile_csv::AbstractString, outdir::AbstractString)
    header, rows = _read_csv_strings(profile_csv)
    mkpath(outdir)
    svg_path = joinpath(outdir, "slit_3d_mc_profile.svg")
    isempty(rows) && return svg_path
    idx(name) = findfirst(==(name), header)
    series_idx = idx("series")
    B_idx = idx("B")
    C_idx = idx("C")
    z_idx = idx("z_over_L")
    phi_idx = idx("phi")
    stderr_idx = idx("stderr")
    parsed = [
        (
            series=row[series_idx],
            B=parse(Float64, row[B_idx]),
            C=parse(Float64, row[C_idx]),
            z=parse(Float64, row[z_idx]),
            phi=parse(Float64, row[phi_idx]),
            stderr=parse(Float64, row[stderr_idx]),
        ) for row in rows
    ]
    line_rows = [row for row in parsed if row.series in ("saddle_eq22", "mc_mean_3d_raw", "mc_mean_3d", "eq22_fit_to_3d_mc")]
    xs = [row.z for row in line_rows]
    ys = vcat([row.phi for row in line_rows],
        [row.phi + row.stderr for row in line_rows], [row.phi - row.stderr for row in line_rows])
    xmin, xmax = 0.0, 1.0
    ymin, ymax = _expand_plot_range(minimum(ys), maximum(ys))
    ymin = min(0.0, ymin)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (Float64(v) - xmin) / spanx
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = _major_ticks(xmin, xmax; count=11)
    yticks = _major_ticks(ymin, ymax; count=9)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    colors = Dict(
        "saddle_eq22" => "#333333",
        "mc_mean_3d_raw" => "#999999",
        "mc_mean_3d" => "#d62728",
        "eq22_fit_to_3d_mc" => "#1f77b4",
    )
    labels = Dict(
        "saddle_eq22" => "Eq. 22 saddle",
        "mc_mean_3d_raw" => "3D MC raw mean",
        "mc_mean_3d" => "3D MC fit profile",
        "eq22_fit_to_3d_mc" => "Eq. 22 fit to 3D MC",
    )
    dashes = Dict(
        "saddle_eq22" => "",
        "mc_mean_3d_raw" => " stroke-dasharray='2 3'",
        "mc_mean_3d" => "",
        "eq22_fit_to_3d_mc" => " stroke-dasharray='7 4'",
    )
    target_B = parsed[1].B
    target_C = parsed[1].C
    open(svg_path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='660' height='430' viewBox='0 0 660 430'>")
        println(io, "<title>3D HE-VK1 slit Metropolis profile</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='35' y='32' font-size='18'>3D HE-VK1 slit Metropolis profile</text>")
        println(io, @sprintf("<text x='35' y='52' font-size='12' fill='#555'>A = 0, B = %.6g, C = %.6g; periodic x/y, hard-wall z</text>", target_B, target_C))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        println(io, "<text class='x-axis-label' x='335' y='412' font-size='13' text-anchor='middle'>z / L</text>")
        println(io, "<text class='y-axis-label' transform='translate(22 210) rotate(-90)' font-size='13' text-anchor='middle'>phi(z)</text>")
        y_legend = 76
        for series in ("saddle_eq22", "mc_mean_3d_raw", "mc_mean_3d", "eq22_fit_to_3d_mc")
            selected = sort([(row.z, row.phi, row.stderr) for row in line_rows if row.series == series])
            isempty(selected) && continue
            color = colors[series]
            dash = dashes[series]
            points = [(x_plot(row[1]), y_plot(row[2])) for row in selected]
            println(io, "<polyline fill='none' stroke='$color' stroke-width='2.5'$dash points='$(_svg_polyline(points))'/>")
            if series == "mc_mean_3d"
                for row in selected
                    if row[3] > 0.0
                        x = x_plot(row[1])
                        ylo = y_plot(row[2] - row[3])
                        yhi = y_plot(row[2] + row[3])
                        println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='%s' stroke-width='0.9'/>",
                            x, ylo, x, yhi, color))
                    end
                end
            end
            println(io, "<line x1='398' y1='$(y_legend)' x2='432' y2='$(y_legend)' stroke='$color' stroke-width='2.5'$dash/>")
            println(io, "<text x='440' y='$(y_legend + 4)' font-size='12'>$(labels[series])</text>")
            y_legend += 18
        end
        println(io, "</svg>")
    end
    return svg_path
end

function _write_slit_3d_mc_text(outdir::AbstractString, result::Slit3DMCResult)
    path = joinpath(outdir, "slit_3d_validation.md")
    open(path, "w") do io
        println(io, "# 3D real-density HE-VK1 Metropolis slit validation")
        println(io)
        println(io, "This artifact runs a 3D real-density HE-VK1 Metropolis sampler for the confined homopolymer slit. The density field is sampled directly on an `Nx x Ny x Nz` grid with periodic x/y directions and hard-wall z boundaries.")
        println(io)
        println(io, "The transition kernel is executed by Arianna using custom density-field moves. Pair moves conserve the total density, plane-transfer moves update the z profile, and global zero-mean field moves add lateral fluctuations. The Metropolis target is `exp(-H_HE-VK1[phi])` with `A = 0`.")
        println(io)
        println(io, @sprintf("Parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`, grid = `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`.",
            result.params.B, result.params.C, result.params.A, result.grid.Nx, result.grid.Ny,
            result.grid.Nz, result.grid.Lxy, result.grid.Lz))
        println(io)
        println(io, @sprintf("MC diagnostics: chains = %d, stored profiles = %d, attempted moves = %d, acceptance = %.6g, mean energy = %.6g +/- %.3g.",
            result.chain_count, result.sample_count, result.attempted_moves, result.acceptance_rate,
            result.energy_mean, result.energy_stderr))
        println(io, @sprintf("Sweep accounting: one sweep = %d proposal attempts; total = %.6g sweeps, burn-in = %.6g sweeps, post-burn production = %.6g sweeps, sample stride = %.6g sweeps.",
            result.proposals_per_sweep, result.total_sweeps, result.burnin_sweeps,
            result.production_sweeps, result.sample_stride_sweeps))
        println(io, @sprintf("Profile estimator: `%s`; mirror symmetrization = `%s`.",
            result.profile_estimator, result.profile_symmetrized))
        println(io, @sprintf("Profile chain diagnostics: max R-hat = %.6g, max split R-hat = %.6g, max chain RMSE = %.6g, max absolute chain deviation = %.6g.",
            result.profile_chain_rhat_max, result.profile_split_rhat_max,
            result.profile_chain_rmse_max, result.profile_chain_max_abs_deviation))
        println(io)
        println(io, @sprintf("Profile fit: `xi_bulk = %.6g`, 3D MC `xi_eff = %.6g`, fit RMSE = %.6g, fit R2 = %.6g, wall RMS residual = %.6g, fit-quality pass = %.0f.",
            result.xi_bulk, result.xi_eff, result.xi_fit_rmse, result.xi_fit_r2,
            result.xi_fit_wall_rms, result.xi_fit_quality_pass))
        result.xi_fit_quality_pass < 0.5 &&
            println(io, "The Eq. 22 fit is marked unreliable for this profile; `xi_eff` should not be used as a physical broadening estimate without improving the profile statistics or changing the profile model.")
        println(io)
        println(io, @sprintf("Lateral fluctuation diagnostic: mean lateral variance = %.6g; mean xy-profile roughness = %.6g.",
            result.lateral_variance_mean, result.xy_profile_roughness_mean))
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function run_slit_3d_vk1_mc(
    outdir::AbstractString;
    Nx::Integer=8,
    Ny::Integer=Nx,
    Nz::Integer=32,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_reference=:saddle,
    lateral_gradient_coeff::Real=0.0,
    projected_entropy_coeff::Real=0.0,
    projected_entropy_reference=:saddle,
    projected_quadratic_coeff::Real=0.0,
    projected_quadratic_reference=:saddle,
    projected_quadratic_weight=:uniform,
    projected_quadratic_coeffs=(),
    projected_quadratic_weights=(),
    projected_quadratic_wall_width::Real=0.2,
    projected_profile_kernel_matrix=(),
    projected_profile_kernel_reference=:saddle,
    steps::Integer=20_000,
    burnin_steps::Integer=5_000,
    sample_stride::Integer=20,
    sweeps=nothing,
    burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=1,
    parallel_chains::Bool=false,
    symmetrize_profile::Bool=true,
    initial_pair_amplitude::Real=1.0e-3,
    initial_plane_amplitude::Real=5.0e-4,
    initial_global_amplitude::Real=2.5e-4,
    initial_profile_mode_amplitude::Real=5.0e-4,
    initial_reference_width_amplitude::Real=2.5e-4,
    pair_move_weight::Real=0.45,
    plane_move_weight::Real=0.35,
    global_move_weight::Real=0.20,
    profile_mode_move_weight::Real=0.0,
    reference_width_move_weight::Real=0.0,
    reference_width_reflection_move_weight::Real=0.0,
    profile_mode_count::Integer=4,
    reference_width_xi::Real=0.0,
    tune_rounds::Integer=3,
    tune_steps::Integer=200,
    target_acceptance::Real=0.44,
    phi_min::Real=1.0e-10,
    profile_measure=:flat_cell,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
    seed::Integer=1901,
    initial_profile=:eq22,
)
    mkpath(outdir)
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    projected_local_coeffs =
        _slit_projected_local_potential_coeffs(projected_local_potential_coeffs)
    lateral_gradient = _slit_lateral_gradient_coeff(lateral_gradient_coeff)
    projected_entropy = _slit_projected_entropy_coeff(projected_entropy_coeff)
    projected_quadratic = _slit_projected_quadratic_coeff(projected_quadratic_coeff)
    projected_profile_kernel =
        _slit_projected_profile_kernel_matrix(projected_profile_kernel_matrix)
    base_params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs,
        lateral_gradient_coeff=lateral_gradient)
    resolved_profile_measure = _slit_3d_profile_measure_symbol(profile_measure)
    resolved_profile_measure_power = Float64(profile_measure_power)
    isfinite(resolved_profile_measure_power) ||
        throw(ArgumentError("profile_measure_power must be finite"))
    resolved_profile_measure_log_floor = max(Float64(profile_measure_log_floor), floatmin(Float64))
    resolved_steps = sweeps === nothing ? max(1, Int(steps)) : _steps_from_sweeps(grid, sweeps)
    resolved_burnin_steps = burnin_sweeps === nothing ? max(0, Int(burnin_steps)) :
                            max(0, ceil(Int, Float64(burnin_sweeps) * _proposals_per_sweep(grid)))
    resolved_sample_stride = sample_stride_sweeps === nothing ? max(1, Int(sample_stride)) :
                             max(1, ceil(Int, Float64(sample_stride_sweeps) * _proposals_per_sweep(grid)))
    proposals_per_sweep = _proposals_per_sweep(grid)
    effective_burnin_steps = clamp(resolved_burnin_steps, 0, max(resolved_steps - 1, 0))
    total_sweeps = _sweeps_from_steps(grid, resolved_steps)
    production_sweeps = _sweeps_from_steps(grid, resolved_steps - effective_burnin_steps)
    resolved_burnin_sweeps = _sweeps_from_steps(grid, effective_burnin_steps)
    resolved_sample_stride_sweeps = _sweeps_from_steps(grid, resolved_sample_stride)
    profile_mode = Symbol(initial_profile)
    chain_count = max(1, Int(chains))
    resolved_profile_mode_count = max(1, Int(profile_mode_count))
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) :
                                  max(1.5 * _slit_bulk_xi(B, C), eps(Float64))
    saddle_phi = if profile_mode == :eq22
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz)
    elseif profile_mode == :reference_width
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=resolved_reference_width_xi)
    elseif profile_mode == :low_density
        slit_low_density_profile(grid.slit_grid)
    elseif profile_mode == :vk1_smooth
        minimize_slit_vk1_smooth_basis_saddle(B, C, A; Nz=grid.Nz, L=grid.Lz,
            alpha=alpha, local_potential_coeffs=local_coeffs,
            basis_count=min(12, grid.Nz - 1), max_iterations=3000).phi
    else
        throw(ArgumentError("initial_profile must be :eq22, :reference_width, :low_density, or :vk1_smooth"))
    end
    projected_reference, projected_reference_source =
        _slit_resolve_projected_entropy_reference(projected_entropy_reference,
            projected_entropy, saddle_phi, grid.slit_grid)
    projected_local_reference, projected_local_reference_source =
        _slit_resolve_projected_local_potential_reference(
            projected_local_potential_reference, projected_local_coeffs, saddle_phi,
            grid.slit_grid)
    projected_quadratic_ref, projected_quadratic_reference_source =
        _slit_resolve_projected_quadratic_reference(projected_quadratic_reference,
            projected_quadratic, saddle_phi, grid.slit_grid)
    projected_quadratic_weight_values, projected_quadratic_weight_source =
        _slit_resolve_projected_quadratic_weight(projected_quadratic_weight,
            projected_quadratic, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_quadratic_coeff_values, projected_quadratic_refs,
    projected_quadratic_weight_values_vec, projected_quadratic_terms_reference_source,
    projected_quadratic_weight_sources =
        _slit_resolve_projected_quadratic_terms(projected_quadratic_coeffs,
            projected_quadratic_reference, projected_quadratic_weights,
            saddle_phi, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_profile_kernel_ref, projected_profile_kernel_reference_source =
        _slit_resolve_projected_profile_kernel_reference(
            projected_profile_kernel_reference, projected_profile_kernel, saddle_phi,
            grid.slit_grid)
    params = SlitParams(B=base_params.B, C=base_params.C, A=base_params.A,
        alpha=base_params.alpha, model=:vk1,
        local_potential_coeffs=base_params.local_potential_coeffs,
        projected_local_potential_coeffs=projected_local_coeffs,
        projected_local_potential_reference=projected_local_reference,
        lateral_gradient_coeff=base_params.lateral_gradient_coeff,
        projected_entropy_coeff=projected_entropy,
        projected_entropy_reference=projected_reference,
        projected_quadratic_coeff=projected_quadratic,
        projected_quadratic_reference=projected_quadratic_ref,
        projected_quadratic_weight=projected_quadratic_weight_values,
        projected_quadratic_coeffs=projected_quadratic_coeff_values,
        projected_quadratic_references=projected_quadratic_refs,
        projected_quadratic_weights=projected_quadratic_weight_values_vec,
        projected_profile_kernel_matrix=projected_profile_kernel,
        projected_profile_kernel_reference=projected_profile_kernel_ref)
    initial_field = slit_3d_field_from_profile(saddle_phi, grid)
    function run_chain_trace(chain_idx)
        _run_slit_3d_arianna_trace(
            grid,
            params,
            initial_field;
            steps=resolved_steps,
            burnin_steps=effective_burnin_steps,
            sample_stride=resolved_sample_stride,
            pair_amplitude=initial_pair_amplitude,
            plane_amplitude=initial_plane_amplitude,
            global_amplitude=initial_global_amplitude,
            profile_mode_amplitude=initial_profile_mode_amplitude,
            profile_mode_count=resolved_profile_mode_count,
            reference_width_amplitude=initial_reference_width_amplitude,
            reference_width_xi=resolved_reference_width_xi,
            pair_weight=pair_move_weight,
            plane_weight=plane_move_weight,
            global_weight=global_move_weight,
            profile_mode_weight=profile_mode_move_weight,
            reference_width_weight=reference_width_move_weight,
            reference_width_reflection_weight=reference_width_reflection_move_weight,
            tune_rounds=tune_rounds,
            tune_steps=tune_steps,
            target_acceptance=target_acceptance,
            phi_min=phi_min,
            profile_measure=resolved_profile_measure,
            profile_measure_power=resolved_profile_measure_power,
            profile_measure_log_floor=resolved_profile_measure_log_floor,
            seed=Int(seed) + 100_000 * (chain_idx - 1),
        )
    end
    traces = if parallel_chains && chain_count > 1
        tasks = [
            let idx = chain_idx
                Threads.@spawn run_chain_trace(idx)
            end
            for chain_idx in 1:chain_count
        ]
        [fetch(task) for task in tasks]
    else
        [run_chain_trace(chain_idx) for chain_idx in 1:chain_count]
    end
    all(trace.sample_count > 0 for trace in traces) ||
        throw(ArgumentError("3D slit MC produced no stored samples"))

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "xy_average_mirror_symmetrized" : "xy_average_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    pair_accepted = sum(trace.pair_accepted_moves for trace in traces)
    pair_attempted = sum(trace.pair_attempted_moves for trace in traces)
    plane_accepted = sum(trace.plane_accepted_moves for trace in traces)
    plane_attempted = sum(trace.plane_attempted_moves for trace in traces)
    global_accepted = sum(trace.global_accepted_moves for trace in traces)
    global_attempted = sum(trace.global_attempted_moves for trace in traces)
    profile_mode_accepted = sum(trace.profile_mode_accepted_moves for trace in traces)
    profile_mode_attempted = sum(trace.profile_mode_attempted_moves for trace in traces)
    reference_width_accepted = sum(trace.reference_width_accepted_moves for trace in traces)
    reference_width_attempted = sum(trace.reference_width_attempted_moves for trace in traces)
    reference_width_reflection_accepted =
        sum(trace.reference_width_reflection_accepted_moves for trace in traces)
    reference_width_reflection_attempted =
        sum(trace.reference_width_reflection_attempted_moves for trace in traces)
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    profile_measure_log_jacobian_trace = reduce(vcat,
        (trace.profile_measure_log_jacobian_trace for trace in traces))

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(B, C)
    fit_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=saddle_phi[k], stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="arianna_metropolis_raw"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    profile_measure_log_jacobian_summary = batch_summary(profile_measure_log_jacobian_trace)
    roughness_mean = mean(xy_profile_roughness_trace)
    diagnostics_rows = [(
        sampler="arianna_metropolis",
        profile_measure=String(resolved_profile_measure),
        profile_measure_power=resolved_profile_measure_power,
        profile_measure_log_floor=resolved_profile_measure_log_floor,
        A=params.A,
        B=params.B,
        C=params.C,
        projected_local_potential_a1=params.projected_local_potential_coeffs[1],
        projected_local_potential_a2=params.projected_local_potential_coeffs[2],
        projected_local_potential_a3=params.projected_local_potential_coeffs[3],
        projected_local_potential_reference_source=projected_local_reference_source,
        projected_profile_kernel_matrix_count=length(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_trace=
            _slit_matrix_trace(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_max_abs=
            _slit_matrix_max_abs(params.projected_profile_kernel_matrix),
        projected_profile_kernel_reference_source=projected_profile_kernel_reference_source,
        lateral_gradient_coeff=params.lateral_gradient_coeff,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=traces[1].steps,
        burnin_steps=traces[1].burnin_steps,
        sample_stride=traces[1].sample_stride,
        proposals_per_sweep=proposals_per_sweep,
        total_sweeps=total_sweeps,
        production_sweeps=production_sweeps,
        burnin_sweeps=resolved_burnin_sweeps,
        sample_stride_sweeps=resolved_sample_stride_sweeps,
        chain_count=chain_count,
        parallel_chains=Bool(parallel_chains),
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        pair_acceptance_rate=pair_accepted / max(pair_attempted, 1),
        plane_acceptance_rate=plane_accepted / max(plane_attempted, 1),
        global_acceptance_rate=global_accepted / max(global_attempted, 1),
        profile_mode_acceptance_rate=profile_mode_accepted / max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted / max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        pair_proposal_amplitude=mean(trace.pair_proposal_amplitude for trace in traces),
        plane_proposal_amplitude=mean(trace.plane_proposal_amplitude for trace in traces),
        global_field_amplitude=mean(trace.global_field_amplitude for trace in traces),
        profile_mode_amplitude=mean(trace.profile_mode_amplitude for trace in traces),
        profile_mode_count=resolved_profile_mode_count,
        reference_width_amplitude=mean(trace.reference_width_amplitude for trace in traces),
        reference_width_xi=resolved_reference_width_xi,
        tuning_acceptance_rate=mean(trace.tuning_acceptance_rate for trace in traces),
        tune_rounds=traces[1].tune_rounds,
        tune_steps=traces[1].tune_steps,
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        profile_measure_log_jacobian_mean=profile_measure_log_jacobian_summary.mean,
        profile_measure_log_jacobian_stderr=profile_measure_log_jacobian_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"), diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)
    provisional = Slit3DMCResult(
        grid,
        params,
        saddle_phi,
        mean_phi,
        stderr_phi,
        raw_mean_phi,
        raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1),
        attempted_moves,
        accepted_moves,
        sample_count,
        chain_count,
        traces[1].steps,
        traces[1].burnin_steps,
        traces[1].sample_stride,
        proposals_per_sweep,
        total_sweeps,
        production_sweeps,
        resolved_burnin_sweeps,
        resolved_sample_stride_sweeps,
        symmetrize_profile,
        profile_estimator,
        mean(trace.pair_proposal_amplitude for trace in traces),
        mean(trace.plane_proposal_amplitude for trace in traces),
        mean(trace.global_field_amplitude for trace in traces),
        mean(trace.tuning_acceptance_rate for trace in traces),
        traces[1].tune_rounds,
        traces[1].tune_steps,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        density_variance_summary.mean,
        density_variance_summary.stderr,
        lateral_variance_summary.mean,
        lateral_variance_summary.stderr,
        roughness_mean,
        xi_eff,
        xi_fit_error,
        fit_diagnostics.rmse,
        fit_diagnostics.r2,
        fit_diagnostics.max_abs_error,
        fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass,
        profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max,
        profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation,
        xi_bulk,
        "arianna_metropolis",
        profile_csv,
        diagnostics_csv,
        profile_svg,
        "",
        "",
    )
    markdown_path = _write_slit_3d_mc_text(outdir, provisional)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_hevk1_metropolis",
            "sampler" => "arianna_metropolis",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
            "volume" => grid.volume,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
            "projected_local_potential_a1" => params.projected_local_potential_coeffs[1],
            "projected_local_potential_a2" => params.projected_local_potential_coeffs[2],
            "projected_local_potential_a3" => params.projected_local_potential_coeffs[3],
            "projected_local_potential_reference_source" => projected_local_reference_source,
            "projected_profile_kernel_matrix_count" => length(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_trace" =>
                _slit_matrix_trace(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_max_abs" =>
                _slit_matrix_max_abs(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_values" =>
                _slit_join_float_values(vec(params.projected_profile_kernel_matrix)),
            "projected_profile_kernel_reference_source" => projected_profile_kernel_reference_source,
            "lateral_gradient_coeff" => params.lateral_gradient_coeff,
            "initial_profile" => String(profile_mode),
        ),
        "sampling" => Dict{String,Any}(
            "steps" => traces[1].steps,
            "burnin_steps" => traces[1].burnin_steps,
            "sample_stride" => traces[1].sample_stride,
            "proposals_per_sweep" => proposals_per_sweep,
            "total_sweeps" => total_sweeps,
            "production_sweeps" => production_sweeps,
            "burnin_sweeps" => resolved_burnin_sweeps,
            "sample_stride_sweeps" => resolved_sample_stride_sweeps,
            "chain_count" => chain_count,
            "parallel_chains" => Bool(parallel_chains),
            "sample_count" => sample_count,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
            "pair_move_weight" => Float64(pair_move_weight),
            "plane_move_weight" => Float64(plane_move_weight),
            "global_move_weight" => Float64(global_move_weight),
            "profile_mode_move_weight" => Float64(profile_mode_move_weight),
            "profile_mode_count" => resolved_profile_mode_count,
            "reference_width_move_weight" => Float64(reference_width_move_weight),
            "reference_width_reflection_move_weight" => Float64(reference_width_reflection_move_weight),
            "reference_width_xi" => resolved_reference_width_xi,
            "target_acceptance" => Float64(target_acceptance),
            "phi_min" => Float64(phi_min),
            "profile_measure" => String(resolved_profile_measure),
            "profile_measure_power" => resolved_profile_measure_power,
            "profile_measure_log_floor" => resolved_profile_measure_log_floor,
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "pair_acceptance_rate" => pair_accepted / max(pair_attempted, 1),
            "plane_acceptance_rate" => plane_accepted / max(plane_attempted, 1),
            "global_acceptance_rate" => global_accepted / max(global_attempted, 1),
            "profile_mode_acceptance_rate" => profile_mode_accepted / max(profile_mode_attempted, 1),
            "reference_width_acceptance_rate" => reference_width_accepted / max(reference_width_attempted, 1),
            "reference_width_reflection_acceptance_rate" => reference_width_reflection_accepted /
                                                            max(reference_width_reflection_attempted, 1),
            "accepted_moves" => accepted_moves,
            "attempted_moves" => attempted_moves,
            "energy_mean" => energy_summary.mean,
            "energy_stderr" => energy_summary.stderr,
            "density_variance_mean" => density_variance_summary.mean,
            "lateral_variance_mean" => lateral_variance_summary.mean,
            "profile_measure_log_jacobian_mean" => profile_measure_log_jacobian_summary.mean,
            "profile_measure_log_jacobian_stderr" => profile_measure_log_jacobian_summary.stderr,
            "xy_profile_roughness_mean" => roughness_mean,
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_error" => xi_fit_error,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
            "xi_fit_mae" => fit_diagnostics.mae,
            "xi_fit_max_abs_error" => fit_diagnostics.max_abs_error,
            "xi_fit_wall_rms" => fit_diagnostics.wall_rms,
            "xi_fit_nrmse_range" => fit_diagnostics.nrmse_range,
            "xi_fit_nrmse_mean" => fit_diagnostics.nrmse_mean,
            "xi_fit_quality_pass" => fit_diagnostics.quality_pass,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
            "profile_chain_rmse_max" => profile_convergence.profile_chain_rmse_max,
            "profile_chain_max_abs_deviation" => profile_convergence.profile_chain_max_abs_deviation,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMCResult(
        grid,
        params,
        saddle_phi,
        mean_phi,
        stderr_phi,
        raw_mean_phi,
        raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1),
        attempted_moves,
        accepted_moves,
        sample_count,
        chain_count,
        traces[1].steps,
        traces[1].burnin_steps,
        traces[1].sample_stride,
        proposals_per_sweep,
        total_sweeps,
        production_sweeps,
        resolved_burnin_sweeps,
        resolved_sample_stride_sweeps,
        symmetrize_profile,
        profile_estimator,
        mean(trace.pair_proposal_amplitude for trace in traces),
        mean(trace.plane_proposal_amplitude for trace in traces),
        mean(trace.global_field_amplitude for trace in traces),
        mean(trace.tuning_acceptance_rate for trace in traces),
        traces[1].tune_rounds,
        traces[1].tune_steps,
        Int(seed),
        energy_summary.mean,
        energy_summary.stderr,
        density_variance_summary.mean,
        density_variance_summary.stderr,
        lateral_variance_summary.mean,
        lateral_variance_summary.stderr,
        roughness_mean,
        xi_eff,
        xi_fit_error,
        fit_diagnostics.rmse,
        fit_diagnostics.r2,
        fit_diagnostics.max_abs_error,
        fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass,
        profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max,
        profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation,
        xi_bulk,
        "arianna_metropolis",
        profile_csv,
        diagnostics_csv,
        profile_svg,
        markdown_path,
        metadata_path,
    )
end

function run_slit_3d_validation(
    outdir::AbstractString;
    Nx::Integer=8,
    Ny::Integer=Nx,
    Nz::Integer=32,
    L::Real=1.0,
    Lxy::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    model=:vk1,
    steps::Integer=20_000,
    burnin_steps::Integer=5_000,
    sample_stride::Integer=20,
    sweeps=nothing,
    burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=1,
    parallel_chains::Bool=false,
    symmetrize_profile::Bool=true,
    initial_pair_amplitude::Real=1.0e-3,
    initial_plane_amplitude::Real=5.0e-4,
    initial_global_amplitude::Real=2.5e-4,
    initial_profile_mode_amplitude::Real=5.0e-4,
    initial_reference_width_amplitude::Real=2.5e-4,
    profile_mode_move_weight::Real=0.0,
    profile_mode_count::Integer=4,
    reference_width_move_weight::Real=0.0,
    reference_width_reflection_move_weight::Real=0.0,
    reference_width_xi::Real=0.0,
    tune_rounds::Integer=3,
    tune_steps::Integer=200,
    profile_measure=:flat_cell,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
    seed::Integer=1901,
)
    symbol = _slit_model_symbol(model)
    symbol == :vk1 || throw(ArgumentError("3D slit Metropolis validation is currently implemented for HE-VK1 only"))
    return run_slit_3d_vk1_mc(outdir; Nx=Nx, Ny=Ny, Nz=Nz, Lz=L, Lxy=Lxy,
        B=B, C=C, A=A, alpha=alpha, steps=steps, burnin_steps=burnin_steps,
        sample_stride=sample_stride, sweeps=sweeps, burnin_sweeps=burnin_sweeps,
        sample_stride_sweeps=sample_stride_sweeps, chains=chains,
        parallel_chains=parallel_chains,
        symmetrize_profile=symmetrize_profile,
        initial_pair_amplitude=initial_pair_amplitude,
        initial_plane_amplitude=initial_plane_amplitude,
        initial_global_amplitude=initial_global_amplitude,
        initial_profile_mode_amplitude=initial_profile_mode_amplitude,
        initial_reference_width_amplitude=initial_reference_width_amplitude,
        profile_mode_move_weight=profile_mode_move_weight,
        profile_mode_count=profile_mode_count,
        reference_width_move_weight=reference_width_move_weight,
        reference_width_reflection_move_weight=reference_width_reflection_move_weight,
        reference_width_xi=reference_width_xi,
        tune_rounds=tune_rounds, tune_steps=tune_steps,
        profile_measure=profile_measure,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor,
        seed=seed)
end

function _existing_axes(path::AbstractString)
    isfile(path) || return Set{Float64}()
    lines = readlines(path)
    axes = Set{Float64}()
    for line in lines[2:end]
        isempty(strip(line)) && continue
        value = tryparse(Float64, first(split(line, ",")))
        value === nothing || push!(axes, value)
    end
    return axes
end

function _append_table_row(path::AbstractString, header, row)
    fresh = !isfile(path) || filesize(path) == 0
    open(path, "a") do io
        fresh && println(io, join(header, ","))
        println(io, join(row, ","))
        flush(io)
    end
    return path
end

function _toml_value(value)
    if value === nothing
        return "none"
    elseif value isa Symbol
        return String(value)
    elseif value isa AbstractString || value isa Integer || value isa Bool
        return value
    elseif value isa Real
        value_float = Float64(value)
        return isfinite(value_float) ? value_float : string(value_float)
    elseif value isa AbstractVector
        return [_toml_value(item) for item in value]
    else
        return string(value)
    end
end

function _project_version()
    project_path = normpath(joinpath(@__DIR__, "..", "Project.toml"))
    if isfile(project_path)
        raw = TOML.parsefile(project_path)
        return string(get(raw, "version", "unknown"))
    end
    return "unknown"
end

function _metadata_environment()
    return Dict{String,Any}(
        "package" => "DFMMonteCarlo",
        "package_version" => _project_version(),
        "julia_version" => string(VERSION),
        "project_path" => normpath(joinpath(@__DIR__, "..", "Project.toml")),
        "manifest_path" => normpath(joinpath(@__DIR__, "..", "Manifest.toml")),
    )
end

function _write_run_metadata(outdir::AbstractString, metadata::Dict{String,Any})
    mkpath(outdir)
    path = joinpath(outdir, "run_metadata.toml")
    open(path, "w") do io
        TOML.print(io, metadata)
    end
    return path
end

function _read_csv_strings(path)
    filesize(path) == 0 && return String[], Vector{Vector{String}}()
    table = CSV.File(path; normalizenames=false, stringtype=String)
    header = String.(propertynames(table))
    rows = Vector{Vector{String}}()
    for row in table
        push!(rows, [ismissing(row[i]) ? "" : string(row[i]) for i in eachindex(header)])
    end
    return header, rows
end

mutable struct DensityFieldSystem <: Arianna.AriannaSystem
    phi::Array{Float64,3}
    grid::Grid3D
    params::HEURPParams
    energy::Float64
    phi_min::Float64
    pressure_contract::Union{Nothing,PressureContract}
    basin_variance_max::Float64
    target_model::Symbol
    boundary_barrier_strength::Float64
end

DensityFieldSystem(
    phi::Array{Float64,3},
    grid::Grid3D,
    params::HEURPParams;
    phi_min=1.0e-8,
    pressure_contract=nothing,
    basin_variance_max=nothing,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
) = begin
    basin_cap = _basin_variance_cap(basin_variance_max)
    barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
    lower_bound = _density_lower_bound(phi_min)
    model = _direct_target_model_symbol(target_model)
    DensityFieldSystem(
        phi,
        grid,
        params,
        minimum(phi) <= lower_bound ? Inf :
        _target_energy_with_basin(phi, grid, params, basin_cap, model, barrier_strength),
        lower_bound,
        pressure_contract,
        basin_cap,
        model,
        barrier_strength,
    )
end

