function Arianna.sample_action!(
    action::PairDensityAction,
    ::PairDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
    rng,
)
    n = length(system.phi)
    action.i = rand(rng, 1:n)
    action.j = rand(rng, 1:n)
    while action.j == action.i
        action.j = rand(rng, 1:n)
    end
    action.δ = (2.0 * rand(rng) - 1.0) * Float64(parameters[1])
    return nothing
end

function Arianna.perform_action!(system::DensityFieldSystem, action::PairDensityAction)
    old_energy = system.energy
    system.phi[action.i] += action.δ
    system.phi[action.j] -= action.δ
    if system.phi[action.i] <= system.phi_min || system.phi[action.j] <= system.phi_min
        system.energy = Inf
    else
        system.energy = _target_energy_with_basin(
            system.phi,
            system.grid,
            system.params,
            system.basin_variance_max,
            system.target_model,
            system.boundary_barrier_strength,
        )
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::PairDensityAction, ::DensityFieldSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    ::PairDensityAction,
    ::PairDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
)
    n = length(system.phi)
    return -log(n * (n - 1) * 2.0 * Float64(parameters[1]))
end

function _multi_pair_count(parameters::AbstractVector{<:Real})
    return length(parameters) >= 2 ? max(2, Int(round(parameters[2]))) : 4
end

function Arianna.sample_action!(
    action::MultiPairDensityAction,
    ::MultiPairDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
    rng,
)
    n = length(system.phi)
    pair_count = _multi_pair_count(parameters)
    resize!(action.i, pair_count)
    resize!(action.j, pair_count)
    resize!(action.δ, pair_count)
    amplitude = Float64(parameters[1])
    for pair in 1:pair_count
        action.i[pair] = rand(rng, 1:n)
        action.j[pair] = rand(rng, 1:n)
        while action.j[pair] == action.i[pair]
            action.j[pair] = rand(rng, 1:n)
        end
        action.δ[pair] = (2.0 * rand(rng) - 1.0) * amplitude
    end
    return nothing
end

function Arianna.perform_action!(system::DensityFieldSystem, action::MultiPairDensityAction)
    old_energy = system.energy
    for pair in eachindex(action.δ)
        system.phi[action.i[pair]] += action.δ[pair]
        system.phi[action.j[pair]] -= action.δ[pair]
    end
    touched_positive = true
    for pair in eachindex(action.δ)
        if system.phi[action.i[pair]] <= system.phi_min || system.phi[action.j[pair]] <= system.phi_min
            touched_positive = false
            break
        end
    end
    system.energy = touched_positive ?
                    _target_energy_with_basin(system.phi, system.grid, system.params,
                        system.basin_variance_max, system.target_model,
                        system.boundary_barrier_strength) :
                    Inf
    return old_energy, system.energy
end

function Arianna.invert_action!(action::MultiPairDensityAction, ::DensityFieldSystem)
    action.δ .*= -1.0
    return nothing
end

function Arianna.log_proposal_density(
    ::MultiPairDensityAction,
    ::MultiPairDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
)
    n = length(system.phi)
    pair_count = _multi_pair_count(parameters)
    return -pair_count * log(n * (n - 1) * 2.0 * Float64(parameters[1]))
end

function Arianna.sample_action!(
    action::GlobalGaussianDensityAction,
    ::GlobalGaussianDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
    rng,
)
    if size(action.δ) != size(system.phi)
        action.δ = zeros(size(system.phi))
    end
    randn!(rng, action.δ)
    action.δ .-= mean(action.δ)
    direction_std = std(vec(action.δ); corrected=false)
    if direction_std <= eps(Float64)
        fill!(action.δ, 0.0)
    else
        action.δ .*= max(Float64(parameters[1]), 0.0) / direction_std
    end
    action.δ .-= mean(action.δ)
    return nothing
end

function Arianna.perform_action!(system::DensityFieldSystem, action::GlobalGaussianDensityAction)
    old_energy = system.energy
    system.phi .+= action.δ
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = _target_energy_with_basin(
            system.phi,
            system.grid,
            system.params,
            system.basin_variance_max,
            system.target_model,
            system.boundary_barrier_strength,
        )
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::GlobalGaussianDensityAction, ::DensityFieldSystem)
    action.δ .*= -1.0
    return nothing
end

function Arianna.log_proposal_density(
    ::GlobalGaussianDensityAction,
    ::GlobalGaussianDensityPolicy,
    ::AbstractVector{<:Real},
    ::DensityFieldSystem,
)
    return 0.0
end

function _radial_variance_direction!(direction::Array{Float64,3}, phi::Array{Float64,3})
    if size(direction) != size(phi)
        direction = zeros(size(phi))
    end
    direction .= phi
    direction .-= mean(direction)
    direction_std = std(vec(direction); corrected=false)
    if direction_std <= eps(Float64)
        fill!(direction, 0.0)
        return direction, 0.0
    end
    direction ./= direction_std
    direction .-= mean(direction)
    return direction, direction_std
end

function radial_variance_proposal(
    rng::AbstractRNG,
    phi::Array{Float64,3},
    amplitude::Real;
    phi_min=1.0e-8,
)
    direction, current_std = _radial_variance_direction!(zeros(size(phi)), phi)
    current_std <= eps(Float64) && return phi, false
    δ = (2.0 * rand(rng) - 1.0) * max(Float64(amplitude), 0.0)
    proposed = phi .+ δ .* direction
    ok = current_std + δ > eps(Float64) && minimum(proposed) > Float64(phi_min)
    return ok ? proposed : phi, ok
end

function Arianna.sample_action!(
    action::RadialVarianceDensityAction,
    ::RadialVarianceDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
    rng,
)
    action.direction, current_std = _radial_variance_direction!(action.direction, system.phi)
    if current_std <= eps(Float64)
        action.δ = 0.0
        action.valid_geometry = true
    else
        action.δ = (2.0 * rand(rng) - 1.0) * max(Float64(parameters[1]), 0.0)
        action.valid_geometry = current_std + action.δ > eps(Float64)
    end
    return nothing
end

function Arianna.perform_action!(system::DensityFieldSystem, action::RadialVarianceDensityAction)
    old_energy = system.energy
    system.phi .+= action.δ .* action.direction
    if !action.valid_geometry || minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = _target_energy_with_basin(
            system.phi,
            system.grid,
            system.params,
            system.basin_variance_max,
            system.target_model,
            system.boundary_barrier_strength,
        )
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::RadialVarianceDensityAction, ::DensityFieldSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    ::RadialVarianceDensityAction,
    ::RadialVarianceDensityPolicy,
    parameters::AbstractVector{<:Real},
    ::DensityFieldSystem,
)
    return -log(2.0 * max(Float64(parameters[1]), eps(Float64)))
end

function _fourier_max_mode(parameters::AbstractVector{<:Real}, grid::Grid3D)
    requested = length(parameters) >= 2 ? Int(round(parameters[2])) : 2
    return clamp(max(1, requested), 1, max(1, fld(grid.Nx, 2)))
end

function _fourier_min_k2(parameters::AbstractVector{<:Real})
    return length(parameters) >= 3 ? max(0.0, Float64(parameters[3])) : 0.0
end

_fourier_mode_k2(grid::Grid3D, ax::Integer, ay::Integer, az::Integer) =
    (2.0 * pi / grid.L)^2 * (Int(ax)^2 + Int(ay)^2 + Int(az)^2)

function _fourier_mode_candidates(parameters::AbstractVector{<:Real}, grid::Grid3D)
    max_mode = _fourier_max_mode(parameters, grid)
    min_k2 = _fourier_min_k2(parameters)
    candidates = Tuple{Int,Int,Int}[]
    for ax in 0:max_mode, ay in 0:max_mode, az in 0:max_mode
        (ax == 0 && ay == 0 && az == 0) && continue
        _fourier_mode_k2(grid, ax, ay, az) >= min_k2 - 1.0e-12 || continue
        push!(candidates, (ax, ay, az))
    end
    isempty(candidates) && throw(ArgumentError(
        @sprintf("no Fourier modes satisfy k^2 >= %.6g with max mode %d on Nx=%d",
            min_k2, max_mode, grid.Nx),
    ))
    sort!(candidates; by=mode -> (_fourier_mode_k2(grid, mode...), mode[1], mode[2], mode[3]))
    return candidates
end

function _fourier_mode_increment!(
    out::Array{Float64,3},
    grid::Grid3D,
    ax::Integer,
    ay::Integer,
    az::Integer,
    amplitude::Real,
    phase::Real,
)
    amp = Float64(amplitude)
    ph = Float64(phase)
    for i in 1:grid.Nx, j in 1:grid.Nx, k in 1:grid.Nx
        out[i, j, k] = amp *
                       cos(2pi * (Int(ax) * (i - 1) + Int(ay) * (j - 1) + Int(az) * (k - 1)) / grid.Nx + ph)
    end
    out .-= mean(out)
    return out
end

function Arianna.sample_action!(
    action::FourierModeDensityAction,
    ::FourierModeDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
    rng,
)
    mode = rand(rng, _fourier_mode_candidates(parameters, system.grid))
    action.ax, action.ay, action.az = mode
    action.phase = 2.0 * pi * rand(rng)
    action.amplitude = Float64(parameters[1])
    return nothing
end

function Arianna.perform_action!(system::DensityFieldSystem, action::FourierModeDensityAction)
    old_energy = system.energy
    increment = Array{Float64,3}(undef, size(system.phi))
    _fourier_mode_increment!(
        increment,
        system.grid,
        action.ax,
        action.ay,
        action.az,
        action.amplitude,
        action.phase,
    )
    system.phi .+= increment
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = _target_energy_with_basin(
            system.phi,
            system.grid,
            system.params,
            system.basin_variance_max,
            system.target_model,
            system.boundary_barrier_strength,
        )
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::FourierModeDensityAction, ::DensityFieldSystem)
    action.phase += pi
    return nothing
end

function Arianna.log_proposal_density(
    ::FourierModeDensityAction,
    ::FourierModeDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::DensityFieldSystem,
)
    mode_count = length(_fourier_mode_candidates(parameters, system.grid))
    return -log(mode_count * 2.0 * pi)
end

Arianna.unnormalised_log_target_density(energy, ::DensityFieldSystem) =
    isfinite(energy) ? -Float64(energy) : -Inf

Arianna.@callback function field_energy(system::DensityFieldSystem)
    return system.energy
end

Arianna.@callback function density_variance(system::DensityFieldSystem)
    return var(vec(system.phi))
end

Arianna.@callback function low_mode_structure_factor(system::DensityFieldSystem)
    return low_mode_structure_factor(system.phi)
end

Arianna.@callback function field_pressure(system::DensityFieldSystem)
    system.pressure_contract === nothing && return NaN
    return _direct_target_pressure(system.phi, system.grid, system.params, system.pressure_contract,
        system.target_model)
end

mutable struct SlitHEVK13DSystem <: Arianna.AriannaSystem
    phi::Array{Float64,3}
    grid::SlitGrid3D
    params::SlitParams
    energy::Float64
    phi_min::Float64
    profile_measure::Symbol
    profile_measure_power::Float64
    profile_measure_log_floor::Float64
end

function SlitHEVK13DSystem(
    phi::Array{Float64,3},
    grid::SlitGrid3D,
    params::SlitParams;
    phi_min=1.0e-10,
    profile_measure=:flat_cell,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
)
    lower = Float64(phi_min)
    0.0 <= lower < 1.0 || throw(ArgumentError("phi_min must be in [0, 1)"))
    measure = _slit_3d_profile_measure_symbol(profile_measure)
    power = Float64(profile_measure_power)
    isfinite(power) || throw(ArgumentError("profile_measure_power must be finite"))
    log_floor = max(Float64(profile_measure_log_floor), floatmin(Float64))
    energy = minimum(phi) <= lower ? Inf :
             slit_hevk1_energy_3d_profile_measure(phi, grid, params;
                 profile_measure=measure,
                 profile_measure_power=power,
                 profile_measure_log_floor=log_floor)
    return SlitHEVK13DSystem(phi, grid, params, energy, lower, measure, power, log_floor)
end

Base.length(::SlitHEVK13DSystem) = 1

mutable struct SlitHEVK13DBlockedSystem <: Arianna.AriannaSystem
    phi::Array{Float64,3}
    grid::SlitGrid3D
    params::SlitParams
    energy::Float64
    phi_min::Float64
    profile_measure_power::Float64
    profile_measure_log_floor::Float64
    energy_workspace::Slit3DHEVK1EnergyWorkspace
end

function SlitHEVK13DBlockedSystem(
    phi::Array{Float64,3},
    grid::SlitGrid3D,
    params::SlitParams;
    phi_min=1.0e-10,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
)
    lower = Float64(phi_min)
    0.0 <= lower < 1.0 || throw(ArgumentError("phi_min must be in [0, 1)"))
    power = Float64(profile_measure_power)
    isfinite(power) || throw(ArgumentError("profile_measure_power must be finite"))
    log_floor = max(Float64(profile_measure_log_floor), floatmin(Float64))
    workspace = Slit3DHEVK1EnergyWorkspace(grid)
    energy = minimum(phi) <= lower ? Inf :
             _slit_hevk1_energy_3d_blocked_profile_measure!(workspace, phi, grid, params;
                 profile_measure_power=power,
                 profile_measure_log_floor=log_floor)
    return SlitHEVK13DBlockedSystem(
        phi, grid, params, energy, lower, power, log_floor, workspace)
end

