function _slit_3d_plane_mean(phi::AbstractArray{<:Real,3}, grid::SlitGrid3D, k::Integer)
    kk = Int(k)
    1 <= kk <= grid.Nz || throw(BoundsError(phi, (:, :, kk)))
    total = 0.0
    for i in 1:grid.Nx, j in 1:grid.Ny
        total += Float64(phi[i, j, kk])
    end
    return total / (grid.Nx * grid.Ny)
end

function _slit_3d_plane_indices(grid::SlitGrid3D, a::Integer)
    aa = Int(a)
    1 <= aa <= grid.Nx * grid.Ny || throw(BoundsError(1:(grid.Nx * grid.Ny), aa))
    i = mod(aa - 1, grid.Nx) + 1
    j = fld(aa - 1, grid.Nx) + 1
    return i, j
end

function _slit_3d_scale_plane!(phi::Array{Float64,3}, grid::SlitGrid3D, k::Integer, ratio::Real)
    scale = Float64(ratio)
    for i in 1:grid.Nx, j in 1:grid.Ny
        phi[i, j, Int(k)] *= scale
    end
    return phi
end

function _slit_3d_blocked_energy(system::SlitHEVK13DBlockedSystem)
    return _slit_hevk1_energy_3d_blocked_profile_measure!(
        system.energy_workspace, system.phi, system.grid, system.params;
        profile_measure_power=system.profile_measure_power,
        profile_measure_log_floor=system.profile_measure_log_floor)
end

mutable struct SlitPlaneTransferAction <: Arianna.Action
    k_from::Int
    k_to::Int
    δ::Float64
end

struct SlitPlaneTransferPolicy <: Arianna.Policy end

mutable struct StoreSlitProfile <: Arianna.AriannaAlgorithm
    profile_traces::Vector{Vector{Float64}}
    energy_trace::Vector{Float64}
    density_variance_trace::Vector{Float64}
    lateral_variance_trace::Vector{Float64}
    xy_profile_roughness_trace::Vector{Float64}
    profile_measure_log_jacobian_trace::Vector{Float64}
end

function StoreSlitProfile(chains; path=missing, extras...)
    isempty(chains) && throw(ArgumentError("StoreSlitProfile requires at least one chain"))
    grid = chains[1].grid
    return StoreSlitProfile(
        [Float64[] for _ in 1:grid.Nz],
        Float64[],
        Float64[],
        Float64[],
        Float64[],
        Float64[],
    )
end

function Arianna.make_step!(simulation::Arianna.Simulation, algorithm::StoreSlitProfile)
    for system in simulation.chains
        profile = _slit_3d_xy_profile(system.phi, system.grid)
        for k in 1:system.grid.Nz
            push!(algorithm.profile_traces[k], profile[k])
        end
        push!(algorithm.energy_trace, system.energy)
        push!(algorithm.density_variance_trace, var(vec(system.phi)))
        push!(algorithm.lateral_variance_trace, _slit_3d_lateral_variance(system.phi, system.grid))
        push!(algorithm.xy_profile_roughness_trace, _slit_profile_roughness(profile, system.grid.slit_grid))
        push!(algorithm.profile_measure_log_jacobian_trace,
            _slit_3d_profile_log_jacobian(system.phi, system.grid;
                log_floor=system.profile_measure_log_floor))
    end
    return nothing
end

Arianna.unnormalised_log_target_density(energy, ::SlitHEVK13DSystem) =
    isfinite(energy) ? -Float64(energy) : -Inf

Arianna.@callback function slit_3d_energy(system::SlitHEVK13DSystem)
    return system.energy
end

Arianna.@callback function slit_3d_density_variance(system::SlitHEVK13DSystem)
    return var(vec(system.phi))
end

Arianna.@callback function slit_3d_lateral_variance(system::SlitHEVK13DSystem)
    return _slit_3d_lateral_variance(system.phi, system.grid)
end

Arianna.unnormalised_log_target_density(energy, ::SlitHEVK13DBlockedSystem) =
    isfinite(energy) ? -Float64(energy) : -Inf

function Arianna.sample_action!(
    action::SlitLateralFractionPairAction,
    ::SlitLateralFractionPairPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
    rng,
)
    nxy = system.grid.Nx * system.grid.Ny
    action.k = rand(rng, 1:system.grid.Nz)
    action.a = rand(rng, 1:nxy)
    action.b = rand(rng, 1:nxy)
    while action.b == action.a
        action.b = rand(rng, 1:nxy)
    end
    action.δu = (2.0 * rand(rng) - 1.0) * Float64(parameters[1])
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DBlockedSystem, action::SlitLateralFractionPairAction)
    old_energy = system.energy
    plane_mean = _slit_3d_plane_mean(system.phi, system.grid, action.k)
    i1, j1 = _slit_3d_plane_indices(system.grid, action.a)
    i2, j2 = _slit_3d_plane_indices(system.grid, action.b)
    δφ = plane_mean * action.δu
    system.phi[i1, j1, action.k] += δφ
    system.phi[i2, j2, action.k] -= δφ
    if system.phi[i1, j1, action.k] <= system.phi_min ||
       system.phi[i2, j2, action.k] <= system.phi_min
        system.energy = Inf
    else
        system.energy = _slit_3d_blocked_energy(system)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::SlitLateralFractionPairAction, ::SlitHEVK13DBlockedSystem)
    action.δu = -action.δu
    return nothing
end

function Arianna.log_proposal_density(
    ::SlitLateralFractionPairAction,
    ::SlitLateralFractionPairPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
)
    nxy = system.grid.Nx * system.grid.Ny
    return -log(system.grid.Nz * nxy * (nxy - 1) * 2.0 * Float64(parameters[1]))
end

function Arianna.sample_action!(
    action::SlitBlockedPlaneTransferAction,
    ::SlitBlockedPlaneTransferPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
    rng,
)
    nz = system.grid.Nz
    action.k_from = rand(rng, 1:nz)
    action.k_to = rand(rng, 1:nz)
    while action.k_to == action.k_from
        action.k_to = rand(rng, 1:nz)
    end
    action.δ = (2.0 * rand(rng) - 1.0) * Float64(parameters[1])
    action.valid_geometry = true
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DBlockedSystem, action::SlitBlockedPlaneTransferAction)
    old_energy = system.energy
    if !action.valid_geometry
        return old_energy, Inf
    end
    from_mean = _slit_3d_plane_mean(system.phi, system.grid, action.k_from)
    to_mean = _slit_3d_plane_mean(system.phi, system.grid, action.k_to)
    new_from = from_mean + action.δ
    new_to = to_mean - action.δ
    if new_from <= system.phi_min || new_to <= system.phi_min
        action.valid_geometry = false
        return old_energy, Inf
    end
    _slit_3d_scale_plane!(system.phi, system.grid, action.k_from, new_from / from_mean)
    _slit_3d_scale_plane!(system.phi, system.grid, action.k_to, new_to / to_mean)
    if minimum(@view system.phi[:, :, action.k_from]) <= system.phi_min ||
       minimum(@view system.phi[:, :, action.k_to]) <= system.phi_min
        system.energy = Inf
    else
        system.energy = _slit_3d_blocked_energy(system)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::SlitBlockedPlaneTransferAction, ::SlitHEVK13DBlockedSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    ::SlitBlockedPlaneTransferAction,
    ::SlitBlockedPlaneTransferPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
)
    nz = system.grid.Nz
    return -log(nz * (nz - 1) * 2.0 * Float64(parameters[1]))
end

function _slit_3d_apply_profile_scaling!(
    system::SlitHEVK13DBlockedSystem,
    new_profile::AbstractVector{<:Real},
)
    length(new_profile) == system.grid.Nz ||
        throw(DimensionMismatch("new profile length must match grid.Nz"))
    for k in 1:system.grid.Nz
        old_mean = _slit_3d_plane_mean(system.phi, system.grid, k)
        _slit_3d_scale_plane!(system.phi, system.grid, k, Float64(new_profile[k]) / old_mean)
    end
    return system
end

function _slit_3d_profile_scaling_action!(
    system::SlitHEVK13DBlockedSystem,
    shape::AbstractVector{<:Real},
    δ::Real,
    valid_geometry::Bool,
)
    old_energy = system.energy
    if !valid_geometry
        return old_energy, Inf, false
    end
    profile = _slit_3d_xy_profile(system.phi, system.grid)
    new_profile = [profile[k] + Float64(δ) * Float64(shape[k]) for k in 1:system.grid.Nz]
    if minimum(new_profile) <= system.phi_min
        return old_energy, Inf, false
    end
    _slit_3d_apply_profile_scaling!(system, new_profile)
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = _slit_3d_blocked_energy(system)
    end
    return old_energy, system.energy, true
end

function Arianna.sample_action!(
    action::SlitBlockedProfileModeAction,
    ::SlitBlockedProfileModePolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
    rng,
)
    count = _slit_profile_mode_count(parameters, system.grid)
    action.mode = rand(rng, 1:count)
    width = max(Float64(parameters[1]), eps(Float64)) / sqrt(Float64(action.mode))
    action.δ = (2.0 * rand(rng) - 1.0) * width
    action.valid_geometry = true
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DBlockedSystem, action::SlitBlockedProfileModeAction)
    shape = _slit_profile_mode_shape(system.grid, action.mode)
    old_energy, new_energy, valid = _slit_3d_profile_scaling_action!(
        system, shape, action.δ, action.valid_geometry)
    action.valid_geometry = valid
    return old_energy, new_energy
end

function Arianna.invert_action!(action::SlitBlockedProfileModeAction, ::SlitHEVK13DBlockedSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    action::SlitBlockedProfileModeAction,
    ::SlitBlockedProfileModePolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DBlockedSystem,
)
    count = _slit_profile_mode_count(parameters, system.grid)
    mode = clamp(Int(action.mode), 1, count)
    width = max(Float64(parameters[1]), eps(Float64)) / sqrt(Float64(mode))
    return -log(count * 2.0 * width)
end

