function Arianna.perform_action!(system::SlitHEVK13DBlockedSystem, action::SlitBlockedReferenceWidthAction)
    shape = _slit_reference_width_shape(system.grid, system.params, action.reference_xi)
    old_energy, new_energy, valid = _slit_3d_profile_scaling_action!(
        system, shape, action.δ, action.valid_geometry)
    action.valid_geometry = valid
    return old_energy, new_energy
end

