function _slit_profile_mode_count(parameters::AbstractVector{<:Real}, grid::SlitGrid3D)
    length(parameters) >= 2 || throw(ArgumentError("profile-mode move requires amplitude and mode count"))
    return clamp(round(Int, Float64(parameters[2])), 1, max(1, grid.Nz - 1))
end

function _slit_profile_mode_shape(grid::SlitGrid3D, mode::Integer)
    m = clamp(Int(mode), 1, max(1, grid.Nz - 1))
    shape = [
        cos(2.0 * pi * m * (grid.z[k] / grid.Lz - 0.5))
        for k in 1:grid.Nz
    ]
    shape .-= mean(shape)
    return shape
end

function Arianna.sample_action!(
    action::SlitProfileModeAction,
    ::SlitProfileModePolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
    rng,
)
    count = _slit_profile_mode_count(parameters, system.grid)
    action.mode = rand(rng, 1:count)
    width = max(Float64(parameters[1]), eps(Float64)) / sqrt(Float64(action.mode))
    action.δ = (2.0 * rand(rng) - 1.0) * width
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DSystem, action::SlitProfileModeAction)
    old_energy = system.energy
    shape = _slit_profile_mode_shape(system.grid, action.mode)
    for k in 1:system.grid.Nz
        @views system.phi[:, :, k] .+= action.δ * shape[k]
    end
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = slit_hevk1_energy_3d_profile_measure(system.phi, system.grid, system.params;
            profile_measure=system.profile_measure,
            profile_measure_power=system.profile_measure_power,
            profile_measure_log_floor=system.profile_measure_log_floor)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::SlitProfileModeAction, ::SlitHEVK13DSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    action::SlitProfileModeAction,
    ::SlitProfileModePolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
)
    count = _slit_profile_mode_count(parameters, system.grid)
    mode = clamp(Int(action.mode), 1, count)
    width = max(Float64(parameters[1]), eps(Float64)) / sqrt(Float64(mode))
    return -log(count * 2.0 * width)
end

function _slit_reference_width_shape(grid::SlitGrid3D, params::SlitParams, reference_xi::Real)
    xi = max(Float64(reference_xi), eps(Float64))
    base_xi = _slit_bulk_xi(params.B, params.C)
    base = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz, xi=base_xi)
    target = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz, xi=xi)
    shape = target .- base
    shape .-= mean(shape)
    scale = maximum(abs, shape)
    if !(isfinite(scale) && scale > eps(Float64))
        return _slit_profile_mode_shape(grid, 1)
    end
    return shape ./ scale
end

function _slit_reference_width_delta_bounds(
    phi::Array{Float64,3},
    grid::SlitGrid3D,
    params::SlitParams,
    reference_xi::Real,
    phi_min::Real;
    amplitude::Real,
)
    shape = _slit_reference_width_shape(grid, params, reference_xi)
    lower = -max(Float64(amplitude), eps(Float64))
    upper = max(Float64(amplitude), eps(Float64))
    floor_value = Float64(phi_min)
    for k in 1:grid.Nz
        sk = shape[k]
        abs(sk) <= eps(Float64) && continue
        plane_min = minimum(@view phi[:, :, k])
        if sk > 0.0
            lower = max(lower, (floor_value - plane_min) / sk)
        else
            upper = min(upper, (floor_value - plane_min) / sk)
        end
    end
    return lower, upper
end

function Arianna.sample_action!(
    action::SlitReferenceWidthAction,
    ::SlitReferenceWidthPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
    rng,
)
    width = max(Float64(parameters[1]), eps(Float64))
    action.reference_xi = length(parameters) >= 2 ? max(Float64(parameters[2]), eps(Float64)) : eps(Float64)
    lower, upper = _slit_reference_width_delta_bounds(system.phi, system.grid,
        system.params, action.reference_xi, system.phi_min; amplitude=width)
    if !(lower < upper)
        action.δ = 0.0
    else
        action.δ = lower + rand(rng) * (upper - lower)
    end
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DSystem, action::SlitReferenceWidthAction)
    old_energy = system.energy
    shape = _slit_reference_width_shape(system.grid, system.params, action.reference_xi)
    for k in 1:system.grid.Nz
        @views system.phi[:, :, k] .+= action.δ * shape[k]
    end
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = slit_hevk1_energy_3d_profile_measure(system.phi, system.grid, system.params;
            profile_measure=system.profile_measure,
            profile_measure_power=system.profile_measure_power,
            profile_measure_log_floor=system.profile_measure_log_floor)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::SlitReferenceWidthAction, ::SlitHEVK13DSystem)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    action::SlitReferenceWidthAction,
    ::SlitReferenceWidthPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
)
    width = max(Float64(parameters[1]), eps(Float64))
    reference_xi = length(parameters) >= 2 ? max(Float64(parameters[2]), eps(Float64)) :
                   max(action.reference_xi, eps(Float64))
    lower, upper = _slit_reference_width_delta_bounds(system.phi, system.grid,
        system.params, reference_xi, system.phi_min; amplitude=width)
    interval = upper - lower
    if !(interval > eps(Float64)) || action.δ < lower || action.δ > upper
        return -Inf
    end
    return -log(interval)
end

function _slit_reference_width_reflection_delta(
    phi::Array{Float64,3},
    grid::SlitGrid3D,
    params::SlitParams,
    reference_xi::Real,
)
    shape = _slit_reference_width_shape(grid, params, reference_xi)
    norm2 = sum(abs2, shape)
    norm2 > eps(Float64) || return 0.0
    target = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz,
        xi=max(Float64(reference_xi), eps(Float64)))
    profile = _slit_3d_xy_profile(phi, grid)
    return 2.0 * sum((target .- profile) .* shape) / norm2
end

function Arianna.sample_action!(
    action::SlitReferenceWidthReflectionAction,
    ::SlitReferenceWidthReflectionPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
    ::AbstractRNG,
)
    action.reference_xi = length(parameters) >= 1 ?
                          max(Float64(parameters[1]), eps(Float64)) :
                          max(action.reference_xi, eps(Float64))
    action.δ = _slit_reference_width_reflection_delta(
        system.phi, system.grid, system.params, action.reference_xi)
    return nothing
end

function Arianna.perform_action!(
    system::SlitHEVK13DSystem,
    action::SlitReferenceWidthReflectionAction,
)
    old_energy = system.energy
    shape = _slit_reference_width_shape(system.grid, system.params, action.reference_xi)
    for k in 1:system.grid.Nz
        @views system.phi[:, :, k] .+= action.δ * shape[k]
    end
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = slit_hevk1_energy_3d_profile_measure(system.phi, system.grid,
            system.params; profile_measure=system.profile_measure,
            profile_measure_power=system.profile_measure_power,
            profile_measure_log_floor=system.profile_measure_log_floor)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(
    action::SlitReferenceWidthReflectionAction,
    ::SlitHEVK13DSystem,
)
    action.δ = -action.δ
    return nothing
end

function Arianna.log_proposal_density(
    ::SlitReferenceWidthReflectionAction,
    ::SlitReferenceWidthReflectionPolicy,
    ::AbstractVector{<:Real},
    ::SlitHEVK13DSystem,
)
    return 0.0
end

function Arianna.sample_action!(
    action::GlobalGaussianDensityAction,
    ::GlobalGaussianDensityPolicy,
    parameters::AbstractVector{<:Real},
    system::SlitHEVK13DSystem,
    rng,
)
    if size(action.δ) != size(system.phi)
        action.δ = zeros(size(system.phi))
    end
    randn!(rng, action.δ)
    action.δ .-= mean(action.δ)
    direction_std = std(vec(action.δ); corrected=false)
    if direction_std <= eps(Float64)
        fill!(action.δ, 0.0)
    else
        action.δ .*= max(Float64(parameters[1]), 0.0) / direction_std
    end
    action.δ .-= mean(action.δ)
    return nothing
end

function Arianna.perform_action!(system::SlitHEVK13DSystem, action::GlobalGaussianDensityAction)
    old_energy = system.energy
    system.phi .+= action.δ
    if minimum(system.phi) <= system.phi_min
        system.energy = Inf
    else
        system.energy = slit_hevk1_energy_3d_profile_measure(system.phi, system.grid, system.params;
            profile_measure=system.profile_measure,
            profile_measure_power=system.profile_measure_power,
            profile_measure_log_floor=system.profile_measure_log_floor)
    end
    return old_energy, system.energy
end

function Arianna.invert_action!(action::GlobalGaussianDensityAction, ::SlitHEVK13DSystem)
    action.δ .*= -1.0
    return nothing
end

function Arianna.log_proposal_density(
    ::GlobalGaussianDensityAction,
    ::GlobalGaussianDensityPolicy,
    ::AbstractVector{<:Real},
    ::SlitHEVK13DSystem,
)
    return 0.0
end

function _slit3d_move_pool(
    phi::Array{Float64,3};
    pair_amplitude::Real,
    plane_amplitude::Real,
    global_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    pair_weight::Real,
    plane_weight::Real,
    global_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
)
    pweight = max(0.0, Float64(pair_weight))
    zweight = max(0.0, Float64(plane_weight))
    gweight = max(0.0, Float64(global_weight))
    mweight = max(0.0, Float64(profile_mode_weight))
    rweight = max(0.0, Float64(reference_width_weight))
    fweight = max(0.0, Float64(reference_width_reflection_weight))
    total_weight = pweight + zweight + gweight + mweight + rweight + fweight
    total_weight > 0.0 || throw(ArgumentError("at least one 3D slit move weight must be positive"))
    mode_count = max(1, Int(profile_mode_count))
    ref_xi = max(Float64(reference_width_xi), eps(Float64))
    return (
        Arianna.Move(PairDensityAction(1, 2, 0.0), PairDensityPolicy(),
            [max(Float64(pair_amplitude), eps(Float64))], pweight / total_weight),
        Arianna.Move(SlitPlaneTransferAction(1, 2, 0.0), SlitPlaneTransferPolicy(),
            [max(Float64(plane_amplitude), eps(Float64))], zweight / total_weight),
        Arianna.Move(GlobalGaussianDensityAction(zeros(size(phi))), GlobalGaussianDensityPolicy(),
            [max(Float64(global_amplitude), eps(Float64))], gweight / total_weight),
        Arianna.Move(SlitProfileModeAction(1, 0.0), SlitProfileModePolicy(),
            [max(Float64(profile_mode_amplitude), eps(Float64)), Float64(mode_count)],
            mweight / total_weight),
        Arianna.Move(SlitReferenceWidthAction(0.0, ref_xi), SlitReferenceWidthPolicy(),
            [max(Float64(reference_width_amplitude), eps(Float64)), ref_xi],
            rweight / total_weight),
        Arianna.Move(SlitReferenceWidthReflectionAction(0.0, ref_xi),
            SlitReferenceWidthReflectionPolicy(), [ref_xi],
            fweight / total_weight),
    )
end

function _slit3d_acceptance_by_move(pool)
    return [_move_acceptance(move) for move in pool]
end

function _tune_slit3d_amplitudes!(
    phi::Array{Float64,3},
    grid::SlitGrid3D,
    params::SlitParams;
    pair_amplitude::Real,
    plane_amplitude::Real,
    global_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    pair_weight::Real,
    plane_weight::Real,
    global_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
    tune_rounds::Integer,
    tune_steps::Integer,
    target_acceptance::Real,
    phi_min::Real,
    profile_measure,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    seed::Integer,
)
    pair_amp = max(Float64(pair_amplitude), eps(Float64))
    plane_amp = max(Float64(plane_amplitude), eps(Float64))
    global_amp = max(Float64(global_amplitude), eps(Float64))
    profile_amp = max(Float64(profile_mode_amplitude), eps(Float64))
    profile_count = max(1, Int(profile_mode_count))
    reference_amp = max(Float64(reference_width_amplitude), eps(Float64))
    reference_xi = max(Float64(reference_width_xi), eps(Float64))
    rounds = max(0, Int(tune_rounds))
    steps_per_round = max(1, Int(tune_steps))
    target = clamp(Float64(target_acceptance), 1.0e-3, 0.999)
    chain = SlitHEVK13DSystem(phi, grid, params; phi_min=phi_min,
        profile_measure=profile_measure,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor)
    last_acceptance = [NaN, NaN, NaN, NaN, NaN, NaN]
    for round in 1:rounds
        pool = _slit3d_move_pool(chain.phi; pair_amplitude=pair_amp,
            plane_amplitude=plane_amp, global_amplitude=global_amp,
        profile_mode_amplitude=profile_amp, profile_mode_count=profile_count,
        reference_width_amplitude=reference_amp, reference_width_xi=reference_xi,
        pair_weight=pair_weight, plane_weight=plane_weight, global_weight=global_weight,
            profile_mode_weight=profile_mode_weight, reference_width_weight=reference_width_weight,
            reference_width_reflection_weight=reference_width_reflection_weight)
        algorithms = ((algorithm=Arianna.Metropolis, pool=pool,
            seed=Int(seed) + round, parallel=false),)
        simulation = Arianna.Simulation([chain], algorithms, steps_per_round;
            path=mktempdir(), verbose=false)
        Arianna.run!(simulation)
        last_acceptance = _slit3d_acceptance_by_move(simulation.algorithms[1].pools[1])
        pair_amp = _adapt_metropolis_amplitude(pair_amp, last_acceptance[1];
            target_acceptance=target, min_amplitude=1.0e-8, max_amplitude=0.05)
        plane_amp = _adapt_metropolis_amplitude(plane_amp, last_acceptance[2];
            target_acceptance=target, min_amplitude=1.0e-8, max_amplitude=0.05)
        global_amp = _adapt_metropolis_amplitude(global_amp, last_acceptance[3];
            target_acceptance=target, min_amplitude=1.0e-8, max_amplitude=0.05)
        profile_amp = _adapt_metropolis_amplitude(profile_amp, last_acceptance[4];
            target_acceptance=target, min_amplitude=1.0e-8, max_amplitude=0.05)
        reference_amp = _adapt_metropolis_amplitude(reference_amp, last_acceptance[5];
            target_acceptance=target, min_amplitude=1.0e-8, max_amplitude=0.05)
    end
    phi .= chain.phi
    return (
        pair_proposal_amplitude=pair_amp,
        plane_proposal_amplitude=plane_amp,
        global_field_amplitude=global_amp,
        profile_mode_amplitude=profile_amp,
        reference_width_amplitude=reference_amp,
        reference_width_xi=reference_xi,
        tuning_acceptance_rate=_weighted_tuning_acceptance([
            (pair_weight, last_acceptance[1]),
            (plane_weight, last_acceptance[2]),
            (global_weight, last_acceptance[3]),
            (profile_mode_weight, last_acceptance[4]),
            (reference_width_weight, last_acceptance[5]),
            (reference_width_reflection_weight, last_acceptance[6]),
        ]),
        tune_rounds=rounds,
        tune_steps=steps_per_round,
    )
end

function _run_slit_3d_arianna_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    initial_phi::Array{Float64,3};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    pair_amplitude::Real,
    plane_amplitude::Real,
    global_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    pair_weight::Real,
    plane_weight::Real,
    global_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
    tune_rounds::Integer,
    tune_steps::Integer,
    target_acceptance::Real,
    phi_min::Real,
    profile_measure,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    seed::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    lower = Float64(phi_min)
    phi = copy(initial_phi)
    _slit_3d_validate_phi(phi, grid)
    tuning = _tune_slit3d_amplitudes!(
        phi,
        grid,
        params;
        pair_amplitude=pair_amplitude,
        plane_amplitude=plane_amplitude,
        global_amplitude=global_amplitude,
        profile_mode_amplitude=profile_mode_amplitude,
        profile_mode_count=profile_mode_count,
        reference_width_amplitude=reference_width_amplitude,
        reference_width_xi=reference_width_xi,
        pair_weight=pair_weight,
        plane_weight=plane_weight,
        global_weight=global_weight,
        profile_mode_weight=profile_mode_weight,
        reference_width_weight=reference_width_weight,
        reference_width_reflection_weight=reference_width_reflection_weight,
        tune_rounds=tune_rounds,
        tune_steps=tune_steps,
        target_acceptance=target_acceptance,
        phi_min=lower,
        profile_measure=profile_measure,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor,
        seed=Int(seed) + 10_000,
    )
    chain = SlitHEVK13DSystem(phi, grid, params; phi_min=lower,
        profile_measure=profile_measure,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor)
    pool = _slit3d_move_pool(chain.phi;
        pair_amplitude=tuning.pair_proposal_amplitude,
        plane_amplitude=tuning.plane_proposal_amplitude,
        global_amplitude=tuning.global_field_amplitude,
        profile_mode_amplitude=tuning.profile_mode_amplitude,
        profile_mode_count=profile_mode_count,
        reference_width_amplitude=tuning.reference_width_amplitude,
        reference_width_xi=tuning.reference_width_xi,
        pair_weight=pair_weight,
        plane_weight=plane_weight,
        global_weight=global_weight,
        profile_mode_weight=profile_mode_weight,
        reference_width_weight=reference_width_weight,
        reference_width_reflection_weight=reference_width_reflection_weight)
    schedule = Arianna.build_schedule(total_steps, burn, stride)
    path = mktempdir()
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=Int(seed), parallel=false),
        (algorithm=StoreSlitProfile, scheduler=schedule),
        (algorithm=Arianna.StoreCallbacks,
            callbacks=(slit_3d_energy, slit_3d_density_variance, slit_3d_lateral_variance),
            store_first=false, scheduler=schedule),
        (algorithm=Arianna.StoreAcceptance, dependencies=(Arianna.Metropolis,), scheduler=schedule),
    )
    simulation = Arianna.Simulation([chain], algorithms, total_steps; path=path, verbose=false)
    Arianna.run!(simulation)
    accepted = 0
    attempted = 0
    move_acceptance = _slit3d_acceptance_by_move(simulation.algorithms[1].pools[1])
    move_pool = simulation.algorithms[1].pools[1]
    for move in simulation.algorithms[1].pools[1]
        accepted += move.accepted_calls
        attempted += move.total_calls
    end
    accumulator = simulation.algorithms[2]
    sample_count = length(accumulator.energy_trace)
    sample_count > 0 || throw(ArgumentError("3D slit MC stored no profile samples"))
    mean_phi = [mean(trace) for trace in accumulator.profile_traces]
    stderr_phi = [_markov_mean_stderr(trace) for trace in accumulator.profile_traces]
    return (
        mean_phi=mean_phi,
        stderr_phi=stderr_phi,
        profile_traces=[copy(trace) for trace in accumulator.profile_traces],
        energy_trace=copy(accumulator.energy_trace),
        density_variance_trace=copy(accumulator.density_variance_trace),
        lateral_variance_trace=copy(accumulator.lateral_variance_trace),
        xy_profile_roughness_trace=copy(accumulator.xy_profile_roughness_trace),
        profile_measure_log_jacobian_trace=copy(accumulator.profile_measure_log_jacobian_trace),
        sample_count=sample_count,
        acceptance_rate=accepted / max(attempted, 1),
        pair_acceptance_rate=move_acceptance[1],
        plane_acceptance_rate=move_acceptance[2],
        global_acceptance_rate=move_acceptance[3],
        reference_width_acceptance_rate=move_acceptance[5],
        reference_width_reflection_acceptance_rate=move_acceptance[6],
        pair_accepted_moves=move_pool[1].accepted_calls,
        pair_attempted_moves=move_pool[1].total_calls,
        plane_accepted_moves=move_pool[2].accepted_calls,
        plane_attempted_moves=move_pool[2].total_calls,
        global_accepted_moves=move_pool[3].accepted_calls,
        global_attempted_moves=move_pool[3].total_calls,
        profile_mode_accepted_moves=move_pool[4].accepted_calls,
        profile_mode_attempted_moves=move_pool[4].total_calls,
        reference_width_accepted_moves=move_pool[5].accepted_calls,
        reference_width_attempted_moves=move_pool[5].total_calls,
        reference_width_reflection_accepted_moves=move_pool[6].accepted_calls,
        reference_width_reflection_attempted_moves=move_pool[6].total_calls,
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
        pair_proposal_amplitude=tuning.pair_proposal_amplitude,
        plane_proposal_amplitude=tuning.plane_proposal_amplitude,
        global_field_amplitude=tuning.global_field_amplitude,
        profile_mode_amplitude=tuning.profile_mode_amplitude,
        profile_mode_count=max(1, Int(profile_mode_count)),
        reference_width_amplitude=tuning.reference_width_amplitude,
        reference_width_xi=tuning.reference_width_xi,
        tuning_acceptance_rate=tuning.tuning_acceptance_rate,
        tune_rounds=tuning.tune_rounds,
        tune_steps=tuning.tune_steps,
        arianna_path=path,
        final_phi=copy(chain.phi),
    )
end

function _slit3d_blocked_move_pool(
    phi::Array{Float64,3};
    lateral_fraction_amplitude::Real,
    profile_transfer_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    lateral_fraction_weight::Real,
    profile_transfer_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
)
    lweight = max(0.0, Float64(lateral_fraction_weight))
    tweight = max(0.0, Float64(profile_transfer_weight))
    mweight = max(0.0, Float64(profile_mode_weight))
    rweight = max(0.0, Float64(reference_width_weight))
    fweight = max(0.0, Float64(reference_width_reflection_weight))
    total_weight = lweight + tweight + mweight + rweight + fweight
    total_weight > 0.0 || throw(ArgumentError("at least one blocked 3D slit move weight must be positive"))
    mode_count = max(1, Int(profile_mode_count))
    ref_xi = max(Float64(reference_width_xi), eps(Float64))
    return (
        Arianna.Move(SlitLateralFractionPairAction(1, 1, 2, 0.0),
            SlitLateralFractionPairPolicy(),
            [max(Float64(lateral_fraction_amplitude), eps(Float64))],
            lweight / total_weight),
        Arianna.Move(SlitBlockedPlaneTransferAction(1, 2, 0.0),
            SlitBlockedPlaneTransferPolicy(),
            [max(Float64(profile_transfer_amplitude), eps(Float64))],
            tweight / total_weight),
        Arianna.Move(SlitBlockedProfileModeAction(1, 0.0),
            SlitBlockedProfileModePolicy(),
            [max(Float64(profile_mode_amplitude), eps(Float64)), Float64(mode_count)],
            mweight / total_weight),
        Arianna.Move(SlitBlockedReferenceWidthAction(0.0, ref_xi),
            SlitBlockedReferenceWidthPolicy(),
            [max(Float64(reference_width_amplitude), eps(Float64)), ref_xi],
            rweight / total_weight),
        Arianna.Move(SlitBlockedReferenceWidthReflectionAction(0.0, ref_xi),
            SlitBlockedReferenceWidthReflectionPolicy(),
            [ref_xi],
            fweight / total_weight),
    )
end

function _slit3d_select_weighted_move_index(rng::AbstractRNG, pool)
    total_weight = sum(max(Float64(move.weight), 0.0) for move in pool)
    total_weight > 0.0 || throw(ArgumentError("move pool must contain positive weight"))
    threshold = rand(rng) * total_weight
    cumulative = 0.0
    fallback = firstindex(pool)
    for idx in eachindex(pool)
        weight = max(Float64(pool[idx].weight), 0.0)
        weight > 0.0 || continue
        fallback = idx
        cumulative += weight
        threshold <= cumulative && return idx
    end
    return fallback
end

function _slit3d_tempered_arianna_step!(
    system::SlitHEVK13DBlockedSystem,
    move,
    rng::AbstractRNG,
    beta::Real,
)
    Arianna.sample_action!(move.action, move.policy, move.parameters, system, rng)
    logq_forward = Arianna.log_proposal_density(
        move.action, move.policy, move.parameters, system)
    old_state, new_state = Arianna.perform_action!(system, move.action)
    delta_logp = Float64(beta) * Arianna.delta_log_target_density(
        old_state, new_state, system)
    Arianna.invert_action!(move.action, system)
    logq_backward = Arianna.log_proposal_density(
        move.action, move.policy, move.parameters, system)
    log_acceptance = delta_logp + logq_backward - logq_forward
    accepted = log(rand(rng)) < min(0.0, log_acceptance)
    if !accepted
        Arianna.revert_action!(system, move.action)
        return false
    end
    return true
end

function _slit3d_tempered_blocked_move!(
    system::SlitHEVK13DBlockedSystem,
    pool,
    rng::AbstractRNG,
    beta::Real,
)
    move_idx = _slit3d_select_weighted_move_index(rng, pool)
    move = pool[move_idx]
    accepted = _slit3d_tempered_arianna_step!(system, move, rng, beta)
    move.total_calls += 1
    move.accepted_calls += accepted ? 1 : 0
    return accepted
end

function _slit3d_update_replica_round_trips!(
    replica_labels::AbstractVector{<:Integer},
    label_min_seen::AbstractVector{Bool},
    label_max_seen::AbstractVector{Bool},
    label_round_trips::AbstractVector{<:Integer},
)
    nreplicas = length(replica_labels)
    for slot in 1:nreplicas
        label = replica_labels[slot]
        if slot == 1
            if label_max_seen[label]
                label_round_trips[label] += 1
                label_max_seen[label] = false
            end
            label_min_seen[label] = true
        elseif slot == nreplicas
            if label_min_seen[label]
                label_round_trips[label] += 1
                label_min_seen[label] = false
            end
            label_max_seen[label] = true
        end
    end
    return nothing
end

function _run_slit_3d_blocked_replica_exchange_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    initial_phi::Array{Float64,3};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    lateral_fraction_amplitude::Real,
    profile_transfer_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    lateral_fraction_weight::Real,
    profile_transfer_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
    phi_min::Real,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    seed::Integer,
    replica_temperatures,
    replica_swap_interval::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    lower = Float64(phi_min)
    _slit_3d_validate_phi(initial_phi, grid)
    temperatures = _slit_replica_temperature_values(replica_temperatures, 1.0)
    nreplicas = length(temperatures)
    nreplicas > 1 || throw(ArgumentError(
        "blocked replica-exchange trace requires at least two replica temperatures"))
    beta_values = 1.0 ./ temperatures
    target_idx = findfirst(value -> isapprox(value, 1.0; rtol=0.0, atol=1.0e-12),
        temperatures)
    target_idx === nothing && throw(ArgumentError("replica ladder must include temperature 1"))
    swap_every = max(1, Int(replica_swap_interval))

    systems = [
        SlitHEVK13DBlockedSystem(copy(initial_phi), grid, params; phi_min=lower,
            profile_measure_power=profile_measure_power,
            profile_measure_log_floor=profile_measure_log_floor)
        for _ in 1:nreplicas
    ]
    pools = [
        _slit3d_blocked_move_pool(systems[replica_idx].phi;
            lateral_fraction_amplitude=lateral_fraction_amplitude,
            profile_transfer_amplitude=profile_transfer_amplitude,
            profile_mode_amplitude=profile_mode_amplitude,
            profile_mode_count=profile_mode_count,
            reference_width_amplitude=reference_width_amplitude,
            reference_width_xi=reference_width_xi,
            lateral_fraction_weight=lateral_fraction_weight,
            profile_transfer_weight=profile_transfer_weight,
            profile_mode_weight=profile_mode_weight,
            reference_width_weight=reference_width_weight,
            reference_width_reflection_weight=reference_width_reflection_weight)
        for replica_idx in 1:nreplicas
    ]
    rng = StableRNG(seed)
    replica_labels = collect(1:nreplicas)
    label_min_seen = falses(nreplicas)
    label_max_seen = falses(nreplicas)
    label_round_trips = zeros(Int, nreplicas)
    label_min_seen[replica_labels[1]] = true
    label_max_seen[replica_labels[end]] = true

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    energy_trace = Float64[]
    density_variance_trace = Float64[]
    lateral_variance_trace = Float64[]
    xy_profile_roughness_trace = Float64[]
    profile_measure_log_jacobian_trace = Float64[]
    swap_attempts = 0
    swap_accepts = 0

    for step in 1:total_steps
        for replica_idx in 1:nreplicas
            _slit3d_tempered_blocked_move!(
                systems[replica_idx], pools[replica_idx], rng, beta_values[replica_idx])
        end
        if step % swap_every == 0
            for replica_idx in 1:(nreplicas - 1)
                beta_i = beta_values[replica_idx]
                beta_j = beta_values[replica_idx + 1]
                energy_i = systems[replica_idx].energy
                energy_j = systems[replica_idx + 1].energy
                log_swap = (beta_i - beta_j) * (energy_i - energy_j)
                swap_attempts += 1
                if log(rand(rng)) < min(0.0, log_swap)
                    systems[replica_idx], systems[replica_idx + 1] =
                        systems[replica_idx + 1], systems[replica_idx]
                    replica_labels[replica_idx], replica_labels[replica_idx + 1] =
                        replica_labels[replica_idx + 1], replica_labels[replica_idx]
                    swap_accepts += 1
                end
            end
            _slit3d_update_replica_round_trips!(
                replica_labels, label_min_seen, label_max_seen, label_round_trips)
        end
        if step > burn && (step - burn) % stride == 0
            target_system = systems[target_idx]
            profile = _slit_3d_xy_profile(target_system.phi, grid)
            for k in 1:grid.Nz
                push!(profile_traces[k], profile[k])
            end
            push!(energy_trace, target_system.energy)
            push!(density_variance_trace, var(vec(target_system.phi)))
            push!(lateral_variance_trace, _slit_3d_lateral_variance(target_system.phi, grid))
            push!(xy_profile_roughness_trace,
                _slit_profile_roughness(profile, grid.slit_grid))
            push!(profile_measure_log_jacobian_trace,
                _slit_3d_profile_log_jacobian(target_system.phi, grid;
                    log_floor=max(Float64(profile_measure_log_floor), floatmin(Float64))))
        end
    end

    sample_count = length(energy_trace)
    sample_count > 0 || throw(ArgumentError(
        "blocked replica-exchange 3D slit MC stored no profile samples"))
    accepted = sum(move.accepted_calls for pool in pools for move in pool)
    attempted = sum(move.total_calls for pool in pools for move in pool)
    accepted_by_move(idx) = sum(pool[idx].accepted_calls for pool in pools)
    attempted_by_move(idx) = sum(pool[idx].total_calls for pool in pools)
    path = mktempdir()
    return (
        mean_phi=[mean(trace) for trace in profile_traces],
        stderr_phi=[_markov_mean_stderr(trace) for trace in profile_traces],
        profile_traces=[copy(trace) for trace in profile_traces],
        energy_trace=energy_trace,
        density_variance_trace=density_variance_trace,
        lateral_variance_trace=lateral_variance_trace,
        xy_profile_roughness_trace=xy_profile_roughness_trace,
        profile_measure_log_jacobian_trace=profile_measure_log_jacobian_trace,
        sample_count=sample_count,
        acceptance_rate=accepted / max(attempted, 1),
        lateral_fraction_acceptance_rate=accepted_by_move(1) / max(attempted_by_move(1), 1),
        profile_transfer_acceptance_rate=accepted_by_move(2) / max(attempted_by_move(2), 1),
        profile_mode_acceptance_rate=accepted_by_move(3) / max(attempted_by_move(3), 1),
        reference_width_acceptance_rate=accepted_by_move(4) / max(attempted_by_move(4), 1),
        reference_width_reflection_acceptance_rate=accepted_by_move(5) /
                                                   max(attempted_by_move(5), 1),
        lateral_fraction_accepted_moves=accepted_by_move(1),
        lateral_fraction_attempted_moves=attempted_by_move(1),
        profile_transfer_accepted_moves=accepted_by_move(2),
        profile_transfer_attempted_moves=attempted_by_move(2),
        profile_mode_accepted_moves=accepted_by_move(3),
        profile_mode_attempted_moves=attempted_by_move(3),
        reference_width_accepted_moves=accepted_by_move(4),
        reference_width_attempted_moves=attempted_by_move(4),
        reference_width_reflection_accepted_moves=accepted_by_move(5),
        reference_width_reflection_attempted_moves=attempted_by_move(5),
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
        lateral_fraction_amplitude=max(Float64(lateral_fraction_amplitude), eps(Float64)),
        profile_transfer_amplitude=max(Float64(profile_transfer_amplitude), eps(Float64)),
        profile_mode_amplitude=max(Float64(profile_mode_amplitude), eps(Float64)),
        profile_mode_count=max(1, Int(profile_mode_count)),
        reference_width_amplitude=max(Float64(reference_width_amplitude), eps(Float64)),
        reference_width_xi=max(Float64(reference_width_xi), eps(Float64)),
        replica_count=nreplicas,
        replica_temperatures=temperatures,
        replica_swap_interval=swap_every,
        replica_swap_attempts=swap_attempts,
        replica_swap_accepts=swap_accepts,
        replica_round_trips=sum(label_round_trips),
        replica_min_round_trips=minimum(label_round_trips),
        replica_max_round_trips=maximum(label_round_trips),
        arianna_path=path,
        final_phi=copy(systems[target_idx].phi),
    )
end

function _run_slit_3d_blocked_arianna_trace(
    grid::SlitGrid3D,
    params::SlitParams,
    initial_phi::Array{Float64,3};
    steps::Integer,
    burnin_steps::Integer,
    sample_stride::Integer,
    lateral_fraction_amplitude::Real,
    profile_transfer_amplitude::Real,
    profile_mode_amplitude::Real,
    profile_mode_count::Integer,
    reference_width_amplitude::Real,
    reference_width_xi::Real,
    lateral_fraction_weight::Real,
    profile_transfer_weight::Real,
    profile_mode_weight::Real,
    reference_width_weight::Real,
    reference_width_reflection_weight::Real,
    phi_min::Real,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    seed::Integer,
)
    total_steps = max(1, Int(steps))
    burn = clamp(Int(burnin_steps), 0, max(total_steps - 1, 0))
    stride = max(1, Int(sample_stride))
    lower = Float64(phi_min)
    phi = copy(initial_phi)
    _slit_3d_validate_phi(phi, grid)
    chain = SlitHEVK13DBlockedSystem(phi, grid, params; phi_min=lower,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor)
    pool = _slit3d_blocked_move_pool(chain.phi;
        lateral_fraction_amplitude=lateral_fraction_amplitude,
        profile_transfer_amplitude=profile_transfer_amplitude,
        profile_mode_amplitude=profile_mode_amplitude,
        profile_mode_count=profile_mode_count,
        reference_width_amplitude=reference_width_amplitude,
        reference_width_xi=reference_width_xi,
        lateral_fraction_weight=lateral_fraction_weight,
        profile_transfer_weight=profile_transfer_weight,
        profile_mode_weight=profile_mode_weight,
        reference_width_weight=reference_width_weight,
        reference_width_reflection_weight=reference_width_reflection_weight)
    schedule = Arianna.build_schedule(total_steps, burn, stride)
    path = mktempdir()
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=Int(seed), parallel=false),
        (algorithm=StoreSlitProfile, scheduler=schedule),
        (algorithm=Arianna.StoreAcceptance, dependencies=(Arianna.Metropolis,), scheduler=schedule),
    )
    simulation = Arianna.Simulation([chain], algorithms, total_steps; path=path, verbose=false)
    Arianna.run!(simulation)
    move_pool = simulation.algorithms[1].pools[1]
    accepted = sum(move.accepted_calls for move in move_pool)
    attempted = sum(move.total_calls for move in move_pool)
    accumulator = simulation.algorithms[2]
    sample_count = length(accumulator.energy_trace)
    sample_count > 0 || throw(ArgumentError("blocked 3D slit MC stored no profile samples"))
    return (
        mean_phi=[mean(trace) for trace in accumulator.profile_traces],
        stderr_phi=[_markov_mean_stderr(trace) for trace in accumulator.profile_traces],
        profile_traces=[copy(trace) for trace in accumulator.profile_traces],
        energy_trace=copy(accumulator.energy_trace),
        density_variance_trace=copy(accumulator.density_variance_trace),
        lateral_variance_trace=copy(accumulator.lateral_variance_trace),
        xy_profile_roughness_trace=copy(accumulator.xy_profile_roughness_trace),
        profile_measure_log_jacobian_trace=copy(accumulator.profile_measure_log_jacobian_trace),
        sample_count=sample_count,
        acceptance_rate=accepted / max(attempted, 1),
        lateral_fraction_acceptance_rate=_move_acceptance(move_pool[1]),
        profile_transfer_acceptance_rate=_move_acceptance(move_pool[2]),
        profile_mode_acceptance_rate=_move_acceptance(move_pool[3]),
        reference_width_acceptance_rate=_move_acceptance(move_pool[4]),
        reference_width_reflection_acceptance_rate=_move_acceptance(move_pool[5]),
        lateral_fraction_accepted_moves=move_pool[1].accepted_calls,
        lateral_fraction_attempted_moves=move_pool[1].total_calls,
        profile_transfer_accepted_moves=move_pool[2].accepted_calls,
        profile_transfer_attempted_moves=move_pool[2].total_calls,
        profile_mode_accepted_moves=move_pool[3].accepted_calls,
        profile_mode_attempted_moves=move_pool[3].total_calls,
        reference_width_accepted_moves=move_pool[4].accepted_calls,
        reference_width_attempted_moves=move_pool[4].total_calls,
        reference_width_reflection_accepted_moves=move_pool[5].accepted_calls,
        reference_width_reflection_attempted_moves=move_pool[5].total_calls,
        accepted_moves=accepted,
        attempted_moves=attempted,
        steps=total_steps,
        burnin_steps=burn,
        sample_stride=stride,
        lateral_fraction_amplitude=max(Float64(lateral_fraction_amplitude), eps(Float64)),
        profile_transfer_amplitude=max(Float64(profile_transfer_amplitude), eps(Float64)),
        profile_mode_amplitude=max(Float64(profile_mode_amplitude), eps(Float64)),
        profile_mode_count=max(1, Int(profile_mode_count)),
        reference_width_amplitude=max(Float64(reference_width_amplitude), eps(Float64)),
        reference_width_xi=max(Float64(reference_width_xi), eps(Float64)),
        arianna_path=path,
        final_phi=copy(chain.phi),
    )
end

function _write_slit_3d_blocked_mc_text(outdir::AbstractString, result::Slit3DMCResult)
    path = joinpath(outdir, "slit_3d_blocked_validation.md")
    open(path, "w") do io
        println(io, "# 3D HE-VK1 blocked-coordinate Metropolis slit validation")
        println(io)
        println(io, "This artifact samples the real-density HE-VK1 slit Hamiltonian in transformed coordinates. The density is represented as plane means times within-plane lateral fractions, `phi(x,y,z_k) = m_k u(x,y|k)`, with each lateral fraction plane normalized to unit mean.")
        println(io)
        println(io, "The target measure is the plane-mean/lateral-fraction coordinate measure. Therefore the Jacobian term in the coordinate energy is `(p - 1) log J`, where `p = 1` corresponds to a flat plane-profile measure after integrating out the lateral simplex factor. This differs from the older all-cell sampler, whose additive profile moves saw the point energy `H + p log J` while the field stayed nearly laterally uniform.")
        println(io)
        println(io, @sprintf("Parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`, grid = `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`.",
            result.params.B, result.params.C, result.params.A, result.grid.Nx, result.grid.Ny,
            result.grid.Nz, result.grid.Lxy, result.grid.Lz))
        println(io)
        println(io, @sprintf("MC diagnostics: chains = %d, stored profiles = %d, attempted moves = %d, acceptance = %.6g, mean coordinate energy = %.6g +/- %.3g.",
            result.chain_count, result.sample_count, result.attempted_moves, result.acceptance_rate,
            result.energy_mean, result.energy_stderr))
        println(io, @sprintf("Sweep accounting: one sweep = %d blocked proposal attempts; total = %.6g sweeps, burn-in = %.6g sweeps, post-burn production = %.6g sweeps, sample stride = %.6g sweeps.",
            result.proposals_per_sweep, result.total_sweeps, result.burnin_sweeps,
            result.production_sweeps, result.sample_stride_sweeps))
        println(io, @sprintf("Profile fit: `xi_bulk = %.6g`, blocked 3D MC `xi_eff = %.6g`, fit RMSE = %.6g, fit R2 = %.6g, wall RMS residual = %.6g, fit-quality pass = %.0f.",
            result.xi_bulk, result.xi_eff, result.xi_fit_rmse, result.xi_fit_r2,
            result.xi_fit_wall_rms, result.xi_fit_quality_pass))
        println(io, @sprintf("Profile chain diagnostics: max R-hat = %.6g, max split R-hat = %.6g, max chain RMSE = %.6g, max absolute chain deviation = %.6g.",
            result.profile_chain_rhat_max, result.profile_split_rhat_max,
            result.profile_chain_rmse_max, result.profile_chain_max_abs_deviation))
        println(io)
        println(io, @sprintf("Lateral fluctuation diagnostic: mean lateral variance = %.6g; mean xy-profile roughness = %.6g.",
            result.lateral_variance_mean, result.xy_profile_roughness_mean))
        println(io)
        println(io, "Outputs:")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_profile_blocks.csv` and `slit_3d_mc_xi_blocks.csv`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function run_slit_3d_vk1_blocked_mc(
    outdir::AbstractString;
    Nx::Integer=8,
    Ny::Integer=Nx,
    Nz::Integer=32,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_reference=:saddle,
    lateral_gradient_coeff::Real=0.0,
    projected_entropy_coeff::Real=0.0,
    projected_entropy_reference=:saddle,
    projected_quadratic_coeff::Real=0.0,
    projected_quadratic_reference=:saddle,
    projected_quadratic_weight=:uniform,
    projected_quadratic_coeffs=(),
    projected_quadratic_weights=(),
    projected_quadratic_wall_width::Real=0.2,
    projected_profile_kernel_matrix=(),
    projected_profile_kernel_reference=:saddle,
    steps::Integer=20_000,
    burnin_steps::Integer=5_000,
    sample_stride::Integer=20,
    sweeps=nothing,
    burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=1,
    parallel_chains::Bool=false,
    symmetrize_profile::Bool=true,
    lateral_fraction_amplitude::Real=5.0e-3,
    profile_transfer_amplitude::Real=5.0e-4,
    profile_mode_amplitude::Real=5.0e-4,
    reference_width_amplitude::Real=2.5e-4,
    lateral_fraction_move_weight::Real=0.65,
    profile_transfer_move_weight::Real=0.20,
    profile_mode_move_weight::Real=0.05,
    reference_width_move_weight::Real=0.10,
    reference_width_reflection_move_weight::Real=0.0,
    profile_mode_count::Integer=4,
    reference_width_xi::Real=0.0,
    phi_min::Real=1.0e-10,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
    seed::Integer=2601,
    initial_profile=:eq22,
    replica_temperatures=(),
    replica_swap_interval::Integer=100,
)
    mkpath(outdir)
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    projected_local_coeffs =
        _slit_projected_local_potential_coeffs(projected_local_potential_coeffs)
    lateral_gradient = _slit_lateral_gradient_coeff(lateral_gradient_coeff)
    projected_entropy = _slit_projected_entropy_coeff(projected_entropy_coeff)
    projected_quadratic = _slit_projected_quadratic_coeff(projected_quadratic_coeff)
    projected_profile_kernel =
        _slit_projected_profile_kernel_matrix(projected_profile_kernel_matrix)
    base_params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs,
        lateral_gradient_coeff=lateral_gradient)
    resolved_steps = sweeps === nothing ? max(1, Int(steps)) : _steps_from_sweeps(grid, sweeps)
    resolved_burnin_steps = burnin_sweeps === nothing ? max(0, Int(burnin_steps)) :
                            max(0, ceil(Int, Float64(burnin_sweeps) * _proposals_per_sweep(grid)))
    resolved_sample_stride = sample_stride_sweeps === nothing ? max(1, Int(sample_stride)) :
                             max(1, ceil(Int, Float64(sample_stride_sweeps) * _proposals_per_sweep(grid)))
    proposals_per_sweep = _proposals_per_sweep(grid)
    effective_burnin_steps = clamp(resolved_burnin_steps, 0, max(resolved_steps - 1, 0))
    total_sweeps = _sweeps_from_steps(grid, resolved_steps)
    production_sweeps = _sweeps_from_steps(grid, resolved_steps - effective_burnin_steps)
    resolved_burnin_sweeps = _sweeps_from_steps(grid, effective_burnin_steps)
    resolved_sample_stride_sweeps = _sweeps_from_steps(grid, resolved_sample_stride)
    profile_mode = Symbol(initial_profile)
    chain_count = max(1, Int(chains))
    resolved_profile_mode_count = max(1, Int(profile_mode_count))
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) :
                                  max(1.5 * _slit_bulk_xi(B, C), eps(Float64))
    replica_temperature_values = _slit_replica_temperature_values(replica_temperatures, 1.0)
    replica_count = length(replica_temperature_values)
    sampler_name = replica_count > 1 ?
                   "arianna_blocked_profile_fraction_replica_exchange" :
                   "arianna_blocked_profile_fraction"
    saddle_phi = if profile_mode == :eq22
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz)
    elseif profile_mode == :reference_width
        slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=resolved_reference_width_xi)
    elseif profile_mode == :low_density
        slit_low_density_profile(grid.slit_grid)
    elseif profile_mode == :vk1_smooth
        minimize_slit_vk1_smooth_basis_saddle(B, C, A; Nz=grid.Nz, L=grid.Lz,
            alpha=alpha, local_potential_coeffs=local_coeffs,
            basis_count=min(12, grid.Nz - 1), max_iterations=3000).phi
    else
        throw(ArgumentError("initial_profile must be :eq22, :reference_width, :low_density, or :vk1_smooth"))
    end
    projected_reference, projected_reference_source =
        _slit_resolve_projected_entropy_reference(projected_entropy_reference,
            projected_entropy, saddle_phi, grid.slit_grid)
    projected_local_reference, projected_local_reference_source =
        _slit_resolve_projected_local_potential_reference(
            projected_local_potential_reference, projected_local_coeffs, saddle_phi,
            grid.slit_grid)
    projected_quadratic_ref, projected_quadratic_reference_source =
        _slit_resolve_projected_quadratic_reference(projected_quadratic_reference,
            projected_quadratic, saddle_phi, grid.slit_grid)
    projected_quadratic_weight_values, projected_quadratic_weight_source =
        _slit_resolve_projected_quadratic_weight(projected_quadratic_weight,
            projected_quadratic, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_quadratic_coeff_values, projected_quadratic_refs,
    projected_quadratic_weight_values_vec, projected_quadratic_terms_reference_source,
    projected_quadratic_weight_sources =
        _slit_resolve_projected_quadratic_terms(projected_quadratic_coeffs,
            projected_quadratic_reference, projected_quadratic_weights,
            saddle_phi, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_profile_kernel_ref, projected_profile_kernel_reference_source =
        _slit_resolve_projected_profile_kernel_reference(
            projected_profile_kernel_reference, projected_profile_kernel, saddle_phi,
            grid.slit_grid)
    params = SlitParams(B=base_params.B, C=base_params.C, A=base_params.A,
        alpha=base_params.alpha, model=:vk1,
        local_potential_coeffs=base_params.local_potential_coeffs,
        projected_local_potential_coeffs=projected_local_coeffs,
        projected_local_potential_reference=projected_local_reference,
        lateral_gradient_coeff=base_params.lateral_gradient_coeff,
        projected_entropy_coeff=projected_entropy,
        projected_entropy_reference=projected_reference,
        projected_quadratic_coeff=projected_quadratic,
        projected_quadratic_reference=projected_quadratic_ref,
        projected_quadratic_weight=projected_quadratic_weight_values,
        projected_quadratic_coeffs=projected_quadratic_coeff_values,
        projected_quadratic_references=projected_quadratic_refs,
        projected_quadratic_weights=projected_quadratic_weight_values_vec,
        projected_profile_kernel_matrix=projected_profile_kernel,
        projected_profile_kernel_reference=projected_profile_kernel_ref)
    initial_field = slit_3d_field_from_profile(saddle_phi, grid)
    function run_chain_trace(chain_idx)
        trace_seed = Int(seed) + 100_000 * (chain_idx - 1)
        if replica_count > 1
            return _run_slit_3d_blocked_replica_exchange_trace(
                grid,
                params,
                initial_field;
                steps=resolved_steps,
                burnin_steps=effective_burnin_steps,
                sample_stride=resolved_sample_stride,
                lateral_fraction_amplitude=lateral_fraction_amplitude,
                profile_transfer_amplitude=profile_transfer_amplitude,
                profile_mode_amplitude=profile_mode_amplitude,
                profile_mode_count=resolved_profile_mode_count,
                reference_width_amplitude=reference_width_amplitude,
                reference_width_xi=resolved_reference_width_xi,
                lateral_fraction_weight=lateral_fraction_move_weight,
                profile_transfer_weight=profile_transfer_move_weight,
                profile_mode_weight=profile_mode_move_weight,
                reference_width_weight=reference_width_move_weight,
                reference_width_reflection_weight=reference_width_reflection_move_weight,
                phi_min=phi_min,
                profile_measure_power=profile_measure_power,
                profile_measure_log_floor=profile_measure_log_floor,
                seed=trace_seed,
                replica_temperatures=replica_temperature_values,
                replica_swap_interval=replica_swap_interval,
            )
        end
        return _run_slit_3d_blocked_arianna_trace(
            grid,
            params,
            initial_field;
            steps=resolved_steps,
            burnin_steps=effective_burnin_steps,
            sample_stride=resolved_sample_stride,
            lateral_fraction_amplitude=lateral_fraction_amplitude,
            profile_transfer_amplitude=profile_transfer_amplitude,
            profile_mode_amplitude=profile_mode_amplitude,
            profile_mode_count=resolved_profile_mode_count,
            reference_width_amplitude=reference_width_amplitude,
            reference_width_xi=resolved_reference_width_xi,
            lateral_fraction_weight=lateral_fraction_move_weight,
            profile_transfer_weight=profile_transfer_move_weight,
            profile_mode_weight=profile_mode_move_weight,
            reference_width_weight=reference_width_move_weight,
            reference_width_reflection_weight=reference_width_reflection_move_weight,
            phi_min=phi_min,
            profile_measure_power=profile_measure_power,
            profile_measure_log_floor=profile_measure_log_floor,
            seed=trace_seed,
        )
    end
    traces = if parallel_chains && chain_count > 1
        tasks = [
            let idx = chain_idx
                Threads.@spawn run_chain_trace(idx)
            end
            for chain_idx in 1:chain_count
        ]
        [fetch(task) for task in tasks]
    else
        [run_chain_trace(chain_idx) for chain_idx in 1:chain_count]
    end
    all(trace.sample_count > 0 for trace in traces) ||
        throw(ArgumentError("blocked 3D slit MC produced no stored samples"))

    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "blocked_xy_average_mirror_symmetrized" : "blocked_xy_average_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    lateral_fraction_accepted = sum(trace.lateral_fraction_accepted_moves for trace in traces)
    lateral_fraction_attempted = sum(trace.lateral_fraction_attempted_moves for trace in traces)
    profile_transfer_accepted = sum(trace.profile_transfer_accepted_moves for trace in traces)
    profile_transfer_attempted = sum(trace.profile_transfer_attempted_moves for trace in traces)
    profile_mode_accepted = sum(trace.profile_mode_accepted_moves for trace in traces)
    profile_mode_attempted = sum(trace.profile_mode_attempted_moves for trace in traces)
    reference_width_accepted = sum(trace.reference_width_accepted_moves for trace in traces)
    reference_width_attempted = sum(trace.reference_width_attempted_moves for trace in traces)
    reference_width_reflection_accepted =
        sum(_slit_trace_property(trace, :reference_width_reflection_accepted_moves, 0)
            for trace in traces)
    reference_width_reflection_attempted =
        sum(_slit_trace_property(trace, :reference_width_reflection_attempted_moves, 0)
            for trace in traces)
    replica_count = maximum(_slit_trace_property(trace, :replica_count, 1) for trace in traces)
    replica_temperatures = _slit_trace_property(traces[1], :replica_temperatures, [1.0])
    replica_temperatures_text =
        join((@sprintf("%.6g", value) for value in replica_temperatures), ";")
    replica_swap_interval = _slit_trace_property(traces[1], :replica_swap_interval, 0)
    replica_swap_attempts =
        sum(_slit_trace_property(trace, :replica_swap_attempts, 0) for trace in traces)
    replica_swap_accepts =
        sum(_slit_trace_property(trace, :replica_swap_accepts, 0) for trace in traces)
    replica_round_trips =
        sum(_slit_trace_property(trace, :replica_round_trips, 0) for trace in traces)
    replica_min_round_trips =
        minimum(_slit_trace_property(trace, :replica_min_round_trips, 0) for trace in traces)
    replica_max_round_trips =
        maximum(_slit_trace_property(trace, :replica_max_round_trips, 0) for trace in traces)
    sampler_name = replica_count > 1 ?
                   "arianna_blocked_profile_fraction_replica_exchange" :
                   "arianna_blocked_profile_fraction"
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    profile_measure_log_jacobian_trace = reduce(vcat,
        (trace.profile_measure_log_jacobian_trace for trace in traces))

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(B, C)
    fit_phi = slit_reference_profile(grid.z; B=B, C=C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=saddle_phi[k], stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="arianna_blocked_raw"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    profile_measure_log_jacobian_summary = batch_summary(profile_measure_log_jacobian_trace)
    roughness_mean = mean(xy_profile_roughness_trace)
    coordinate_log_jacobian_power = Float64(profile_measure_power) - 1.0
    diagnostics_rows = [(
        sampler=sampler_name,
        state_space="plane_mean_lateral_fraction",
        profile_measure_power=Float64(profile_measure_power),
        coordinate_log_jacobian_power=coordinate_log_jacobian_power,
        profile_measure_log_floor=max(Float64(profile_measure_log_floor), floatmin(Float64)),
        A=params.A,
        B=params.B,
        C=params.C,
        local_potential_a1=params.local_potential_coeffs[1],
        local_potential_a2=params.local_potential_coeffs[2],
        local_potential_a3=params.local_potential_coeffs[3],
        projected_local_potential_a1=params.projected_local_potential_coeffs[1],
        projected_local_potential_a2=params.projected_local_potential_coeffs[2],
        projected_local_potential_a3=params.projected_local_potential_coeffs[3],
        projected_local_potential_reference_source=projected_local_reference_source,
        lateral_gradient_coeff=params.lateral_gradient_coeff,
        projected_entropy_coeff=params.projected_entropy_coeff,
        projected_entropy_reference_source=projected_reference_source,
        projected_quadratic_coeff=params.projected_quadratic_coeff,
        projected_quadratic_reference_source=projected_quadratic_reference_source,
        projected_quadratic_weight_source=projected_quadratic_weight_source,
        projected_quadratic_coeffs=_slit_join_float_values(params.projected_quadratic_coeffs),
        projected_quadratic_reference_sources=projected_quadratic_terms_reference_source,
        projected_quadratic_weight_sources=projected_quadratic_weight_sources,
        projected_quadratic_wall_width=Float64(projected_quadratic_wall_width),
        projected_profile_kernel_matrix_count=length(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_trace=
            _slit_matrix_trace(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_max_abs=
            _slit_matrix_max_abs(params.projected_profile_kernel_matrix),
        projected_profile_kernel_reference_source=projected_profile_kernel_reference_source,
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=traces[1].steps,
        burnin_steps=traces[1].burnin_steps,
        sample_stride=traces[1].sample_stride,
        proposals_per_sweep=proposals_per_sweep,
        total_sweeps=total_sweeps,
        production_sweeps=production_sweeps,
        burnin_sweeps=resolved_burnin_sweeps,
        sample_stride_sweeps=resolved_sample_stride_sweeps,
        chain_count=chain_count,
        parallel_chains=Bool(parallel_chains),
        replica_count=replica_count,
        replica_temperatures=replica_temperatures_text,
        replica_swap_interval=max(1, Int(replica_swap_interval)),
        replica_swap_attempts=replica_swap_attempts,
        replica_swap_accepts=replica_swap_accepts,
        replica_swap_acceptance_rate=replica_swap_accepts / max(replica_swap_attempts, 1),
        replica_round_trips=replica_round_trips,
        replica_min_round_trips=replica_min_round_trips,
        replica_max_round_trips=replica_max_round_trips,
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        lateral_fraction_acceptance_rate=lateral_fraction_accepted / max(lateral_fraction_attempted, 1),
        profile_transfer_acceptance_rate=profile_transfer_accepted / max(profile_transfer_attempted, 1),
        profile_mode_acceptance_rate=profile_mode_accepted / max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted / max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        lateral_fraction_amplitude=mean(trace.lateral_fraction_amplitude for trace in traces),
        profile_transfer_amplitude=mean(trace.profile_transfer_amplitude for trace in traces),
        profile_mode_amplitude=mean(trace.profile_mode_amplitude for trace in traces),
        profile_mode_count=resolved_profile_mode_count,
        reference_width_amplitude=mean(trace.reference_width_amplitude for trace in traces),
        reference_width_xi=resolved_reference_width_xi,
        lateral_fraction_move_weight=Float64(lateral_fraction_move_weight),
        profile_transfer_move_weight=Float64(profile_transfer_move_weight),
        profile_mode_move_weight=Float64(profile_mode_move_weight),
        reference_width_move_weight=Float64(reference_width_move_weight),
        reference_width_reflection_move_weight=Float64(reference_width_reflection_move_weight),
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        profile_measure_log_jacobian_mean=profile_measure_log_jacobian_summary.mean,
        profile_measure_log_jacobian_stderr=profile_measure_log_jacobian_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"), diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)
    provisional = Slit3DMCResult(
        grid, params, saddle_phi, mean_phi, stderr_phi, raw_mean_phi, raw_stderr_phi,
        accepted_moves / max(attempted_moves, 1), attempted_moves, accepted_moves,
        sample_count, chain_count, traces[1].steps, traces[1].burnin_steps,
        traces[1].sample_stride, proposals_per_sweep, total_sweeps, production_sweeps,
        resolved_burnin_sweeps, resolved_sample_stride_sweeps, symmetrize_profile,
        profile_estimator, mean(trace.lateral_fraction_amplitude for trace in traces),
        mean(trace.profile_transfer_amplitude for trace in traces), 0.0, NaN, 0, 0,
        Int(seed), energy_summary.mean, energy_summary.stderr,
        density_variance_summary.mean, density_variance_summary.stderr,
        lateral_variance_summary.mean, lateral_variance_summary.stderr, roughness_mean,
        xi_eff, xi_fit_error, fit_diagnostics.rmse, fit_diagnostics.r2,
        fit_diagnostics.max_abs_error, fit_diagnostics.wall_rms,
        fit_diagnostics.quality_pass, profile_convergence.profile_chain_rhat_max,
        profile_convergence.profile_split_rhat_max, profile_convergence.profile_chain_rmse_max,
        profile_convergence.profile_chain_max_abs_deviation, xi_bulk,
        sampler_name, profile_csv, diagnostics_csv, profile_svg, "", "")
    markdown_path = _write_slit_3d_blocked_mc_text(outdir, provisional)
    metadata_path = _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "mode" => "slit_3d_hevk1_blocked_profile_fraction_metropolis",
            "sampler" => sampler_name,
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "Ny" => grid.Ny,
            "Nz" => grid.Nz,
            "Lxy" => grid.Lxy,
            "Lz" => grid.Lz,
            "volume" => grid.volume,
        ),
        "parameters" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
            "model" => "HE-VK1",
            "local_potential_a1" => params.local_potential_coeffs[1],
            "local_potential_a2" => params.local_potential_coeffs[2],
            "local_potential_a3" => params.local_potential_coeffs[3],
            "projected_local_potential_a1" => params.projected_local_potential_coeffs[1],
            "projected_local_potential_a2" => params.projected_local_potential_coeffs[2],
            "projected_local_potential_a3" => params.projected_local_potential_coeffs[3],
            "projected_local_potential_reference_source" => projected_local_reference_source,
            "lateral_gradient_coeff" => params.lateral_gradient_coeff,
            "projected_entropy_coeff" => params.projected_entropy_coeff,
            "projected_entropy_reference_source" => projected_reference_source,
            "projected_quadratic_coeff" => params.projected_quadratic_coeff,
            "projected_quadratic_reference_source" => projected_quadratic_reference_source,
            "projected_quadratic_weight_source" => projected_quadratic_weight_source,
            "projected_quadratic_coeffs" => _slit_join_float_values(params.projected_quadratic_coeffs),
            "projected_quadratic_reference_sources" => projected_quadratic_terms_reference_source,
            "projected_quadratic_weight_sources" => projected_quadratic_weight_sources,
            "projected_quadratic_wall_width" => Float64(projected_quadratic_wall_width),
            "projected_profile_kernel_matrix_count" => length(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_trace" =>
                _slit_matrix_trace(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_max_abs" =>
                _slit_matrix_max_abs(params.projected_profile_kernel_matrix),
            "projected_profile_kernel_matrix_values" =>
                _slit_join_float_values(vec(params.projected_profile_kernel_matrix)),
            "projected_profile_kernel_reference_source" => projected_profile_kernel_reference_source,
            "initial_profile" => String(profile_mode),
        ),
        "sampling" => Dict{String,Any}(
            "state_space" => "plane_mean_lateral_fraction",
            "coordinate_target" => "H_HEVK1 + (profile_measure_power - 1) * logJ",
            "steps" => traces[1].steps,
            "burnin_steps" => traces[1].burnin_steps,
            "sample_stride" => traces[1].sample_stride,
            "proposals_per_sweep" => proposals_per_sweep,
            "total_sweeps" => total_sweeps,
            "production_sweeps" => production_sweeps,
            "burnin_sweeps" => resolved_burnin_sweeps,
            "sample_stride_sweeps" => resolved_sample_stride_sweeps,
            "chain_count" => chain_count,
            "parallel_chains" => Bool(parallel_chains),
            "replica_count" => replica_count,
            "replica_temperatures" => replica_temperature_values,
            "replica_swap_interval" => max(1, Int(replica_swap_interval)),
            "sample_count" => sample_count,
            "profile_estimator" => profile_estimator,
            "profile_symmetrized" => symmetrize_profile,
            "lateral_fraction_move_weight" => Float64(lateral_fraction_move_weight),
            "profile_transfer_move_weight" => Float64(profile_transfer_move_weight),
            "profile_mode_move_weight" => Float64(profile_mode_move_weight),
            "profile_mode_count" => resolved_profile_mode_count,
            "reference_width_move_weight" => Float64(reference_width_move_weight),
            "reference_width_reflection_move_weight" => Float64(reference_width_reflection_move_weight),
            "reference_width_xi" => resolved_reference_width_xi,
            "phi_min" => Float64(phi_min),
            "profile_measure_power" => Float64(profile_measure_power),
            "coordinate_log_jacobian_power" => coordinate_log_jacobian_power,
            "profile_measure_log_floor" => max(Float64(profile_measure_log_floor), floatmin(Float64)),
        ),
        "diagnostics" => Dict{String,Any}(
            "acceptance_rate" => accepted_moves / max(attempted_moves, 1),
            "lateral_fraction_acceptance_rate" => lateral_fraction_accepted / max(lateral_fraction_attempted, 1),
            "profile_transfer_acceptance_rate" => profile_transfer_accepted / max(profile_transfer_attempted, 1),
            "profile_mode_acceptance_rate" => profile_mode_accepted / max(profile_mode_attempted, 1),
            "reference_width_acceptance_rate" => reference_width_accepted / max(reference_width_attempted, 1),
            "reference_width_reflection_acceptance_rate" => reference_width_reflection_accepted /
                                                            max(reference_width_reflection_attempted, 1),
            "replica_swap_acceptance_rate" => replica_swap_accepts / max(replica_swap_attempts, 1),
            "replica_swap_attempts" => replica_swap_attempts,
            "replica_round_trips" => replica_round_trips,
            "accepted_moves" => accepted_moves,
            "attempted_moves" => attempted_moves,
            "energy_mean" => energy_summary.mean,
            "energy_stderr" => energy_summary.stderr,
            "density_variance_mean" => density_variance_summary.mean,
            "lateral_variance_mean" => lateral_variance_summary.mean,
            "profile_measure_log_jacobian_mean" => profile_measure_log_jacobian_summary.mean,
            "xy_profile_roughness_mean" => roughness_mean,
            "xi_bulk" => xi_bulk,
            "xi_eff" => xi_eff,
            "xi_fit_error" => xi_fit_error,
            "xi_fit_rmse" => fit_diagnostics.rmse,
            "xi_fit_r2" => fit_diagnostics.r2,
            "xi_fit_quality_pass" => fit_diagnostics.quality_pass,
            "profile_chain_rhat_max" => profile_convergence.profile_chain_rhat_max,
            "profile_split_rhat_max" => profile_convergence.profile_split_rhat_max,
            "profile_chain_rmse_max" => profile_convergence.profile_chain_rmse_max,
            "profile_chain_max_abs_deviation" => profile_convergence.profile_chain_max_abs_deviation,
        ),
        "outputs" => Dict{String,Any}(
            "profile_csv" => profile_csv,
            "profile_blocks_csv" => profile_blocks_csv,
            "xi_blocks_csv" => xi_blocks_csv,
            "diagnostics_csv" => diagnostics_csv,
            "profile_svg" => profile_svg,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return Slit3DMCResult(
        provisional.grid, provisional.params, provisional.saddle_phi, provisional.mean_phi,
        provisional.stderr_phi, provisional.raw_mean_phi, provisional.raw_stderr_phi,
        provisional.acceptance_rate, provisional.attempted_moves, provisional.accepted_moves,
        provisional.sample_count, provisional.chain_count, provisional.steps,
        provisional.burnin_steps, provisional.sample_stride, provisional.proposals_per_sweep,
        provisional.total_sweeps, provisional.production_sweeps, provisional.burnin_sweeps,
        provisional.sample_stride_sweeps, provisional.profile_symmetrized,
        provisional.profile_estimator, provisional.pair_proposal_amplitude,
        provisional.plane_proposal_amplitude, provisional.global_field_amplitude,
        provisional.tuning_acceptance_rate, provisional.tune_rounds, provisional.tune_steps,
        provisional.seed, provisional.energy_mean, provisional.energy_stderr,
        provisional.density_variance_mean, provisional.density_variance_stderr,
        provisional.lateral_variance_mean, provisional.lateral_variance_stderr,
        provisional.xy_profile_roughness_mean, provisional.xi_eff, provisional.xi_fit_error,
        provisional.xi_fit_rmse, provisional.xi_fit_r2, provisional.xi_fit_max_abs_error,
        provisional.xi_fit_wall_rms, provisional.xi_fit_quality_pass,
        provisional.profile_chain_rhat_max, provisional.profile_split_rhat_max,
        provisional.profile_chain_rmse_max, provisional.profile_chain_max_abs_deviation,
        provisional.xi_bulk, provisional.sampler, provisional.profile_csv,
        provisional.diagnostics_csv, provisional.profile_svg, markdown_path, metadata_path)
end

function _write_slit_3d_blocked_chunked_text(
    outdir::AbstractString,
    diagnostics_row,
)
    path = joinpath(outdir, "slit_3d_blocked_chunked_validation.md")
    open(path, "w") do io
        println(io, "# Chunked 3D HE-VK1 blocked-coordinate Metropolis validation")
        println(io)
        println(io, "This artifact resumes Arianna/Metropolis sampling in the plane-mean/lateral-fraction coordinates. Each chunk starts from the serialized final density of the previous chunk for the same chain.")
        println(io)
        println(io, @sprintf("Grid: `%d x %d x %d`, `Lxy = %.6g`, `Lz = %.6g`; parameters: `B = %.6g`, `C = %.6g`, `A = %.6g`.",
            diagnostics_row.Nx, diagnostics_row.Ny, diagnostics_row.Nz,
            diagnostics_row.Lxy, diagnostics_row.Lz,
            diagnostics_row.B, diagnostics_row.C, diagnostics_row.A))
        println(io, @sprintf("Chunks analyzed: %.0f per chain, completed range %.0f-%.0f; stored profiles = %.0f; acceptance = %.6g.",
            diagnostics_row.chunk_count, diagnostics_row.min_completed_chunk_count,
            diagnostics_row.max_completed_chunk_count, diagnostics_row.sample_count,
            diagnostics_row.acceptance_rate))
        println(io, @sprintf("Profile width: target `xi_eff = %.6g`, MC `xi_eff = %.6g`, absolute error = %.6g, target-profile R2 = %.6g.",
            diagnostics_row.target_xi_eff, diagnostics_row.xi_eff,
            diagnostics_row.abs_xi_error, diagnostics_row.target_profile_r2))
        println(io, @sprintf("Convergence gate: profile R-hat = %.6g, split R-hat = %.6g, block-drift pass = %.0f, calibration pass = %.0f.",
            diagnostics_row.profile_chain_rhat_max, diagnostics_row.profile_split_rhat_max,
            diagnostics_row.xi_block_drift_pass, diagnostics_row.calibration_pass))
        println(io, @sprintf("Manuscript-observable gate: xi pass = %.0f, chain-xi pass = %.0f, leave-one-chain xi pass = %.0f, target-profile R2 pass = %.0f, observable calibration pass = %.0f.",
            diagnostics_row.observable_xi_pass, diagnostics_row.observable_chain_xi_pass,
            diagnostics_row.observable_leave_one_chain_xi_pass,
            diagnostics_row.observable_target_profile_r2_pass,
            diagnostics_row.observable_calibration_pass))
        println(io)
        println(io, "Outputs:")
        println(io, "- `blocked_chunked_summary.csv`")
        println(io, "- `slit_3d_mc_profile.csv` and `slit_3d_mc_profile.svg`")
        println(io, "- `slit_3d_mc_profile_blocks.csv` and `slit_3d_mc_xi_blocks.csv`")
        println(io, "- `slit_3d_mc_diagnostics.csv`")
        println(io, "- `chunk_manifest.csv`, `chunk_traces/`, and `chunk_state/`")
        println(io, "- `run_metadata.toml`")
    end
    return path
end

function _finalize_slit_3d_blocked_chunks(
    outdir::AbstractString,
    grid::SlitGrid3D,
    params::SlitParams,
    saddle_phi::AbstractVector{<:Real},
    traces,
    chain_indices::AbstractVector{<:Integer},
    chunk_counts::AbstractVector{<:Integer};
    completed_chunk_counts::AbstractVector{<:Integer}=chunk_counts,
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
    target_xi_eff::Real,
    target_source::AbstractString,
    xi_tolerance::Real,
    rhat_threshold::Real,
    r2_threshold::Real,
    block_drift_tolerance::Real,
    symmetrize_profile::Bool,
    profile_measure_power::Real,
    profile_measure_log_floor::Real,
    lateral_fraction_amplitude::Real,
    profile_transfer_amplitude::Real,
    profile_mode_amplitude::Real,
    reference_width_amplitude::Real,
    profile_mode_count::Integer,
    lateral_fraction_move_weight::Real,
    profile_transfer_move_weight::Real,
    profile_mode_move_weight::Real,
    reference_width_move_weight::Real,
    reference_width_reflection_move_weight::Real,
    reference_width_xi::Real,
    phi_min::Real,
    projected_entropy_reference_source::AbstractString,
    projected_local_potential_reference_source::AbstractString,
    projected_quadratic_reference_source::AbstractString,
    projected_quadratic_weight_source::AbstractString,
    projected_quadratic_terms_reference_source::AbstractString,
    projected_quadratic_weight_sources::AbstractString,
    projected_quadratic_wall_width::Real,
    projected_profile_kernel_reference_source::AbstractString,
    initial_profile,
    initial_state_outdir,
    initial_state_mode::AbstractString,
    parallel_chains::Bool,
    seed::Integer,
    chunk_steps::Integer,
    first_burnin_steps::Integer,
    sample_stride::Integer,
)
    isempty(traces) && throw(ArgumentError("no blocked chunk traces are available to finalize"))
    mkpath(outdir)
    profile_traces = [Float64[] for _ in 1:grid.Nz]
    for trace in traces, k in 1:grid.Nz
        append!(profile_traces[k], trace.profile_traces[k])
    end
    raw_profile_summary = _profile_mean_and_stderr(profile_traces)
    estimator_traces = symmetrize_profile ? _symmetrize_profile_traces(profile_traces) : profile_traces
    chain_estimator_traces = [
        symmetrize_profile ? _symmetrize_profile_traces(trace.profile_traces) : trace.profile_traces
        for trace in traces
    ]
    profile_summary = _profile_mean_and_stderr(estimator_traces)
    raw_mean_phi = raw_profile_summary.mean_phi
    raw_stderr_phi = raw_profile_summary.stderr_phi
    mean_phi = profile_summary.mean_phi
    stderr_phi = profile_summary.stderr_phi
    profile_estimator = symmetrize_profile ? "blocked_xy_average_mirror_symmetrized" :
                        "blocked_xy_average_raw"
    profile_convergence = _slit_profile_chain_convergence(chain_estimator_traces, mean_phi)
    profile_blocks_csv, xi_blocks_csv =
        _write_slit_3d_block_diagnostics(outdir, chain_estimator_traces, grid)
    xi_block_drift = _slit_xi_block_drift_diagnostics(xi_blocks_csv;
        drift_tolerance=block_drift_tolerance)

    sample_count = sum(trace.sample_count for trace in traces)
    accepted_moves = sum(trace.accepted_moves for trace in traces)
    attempted_moves = sum(trace.attempted_moves for trace in traces)
    lateral_fraction_accepted = sum(trace.lateral_fraction_accepted_moves for trace in traces)
    lateral_fraction_attempted = sum(trace.lateral_fraction_attempted_moves for trace in traces)
    profile_transfer_accepted = sum(trace.profile_transfer_accepted_moves for trace in traces)
    profile_transfer_attempted = sum(trace.profile_transfer_attempted_moves for trace in traces)
    profile_mode_accepted = sum(trace.profile_mode_accepted_moves for trace in traces)
    profile_mode_attempted = sum(trace.profile_mode_attempted_moves for trace in traces)
    reference_width_accepted = sum(trace.reference_width_accepted_moves for trace in traces)
    reference_width_attempted = sum(trace.reference_width_attempted_moves for trace in traces)
    reference_width_reflection_accepted =
        sum(_slit_trace_property(trace, :reference_width_reflection_accepted_moves, 0)
            for trace in traces)
    reference_width_reflection_attempted =
        sum(_slit_trace_property(trace, :reference_width_reflection_attempted_moves, 0)
            for trace in traces)
    replica_count = maximum(_slit_trace_property(trace, :replica_count, 1) for trace in traces)
    replica_temperatures = _slit_trace_property(traces[1], :replica_temperatures, [1.0])
    replica_temperatures_text =
        join((@sprintf("%.6g", value) for value in replica_temperatures), ";")
    replica_swap_interval = _slit_trace_property(traces[1], :replica_swap_interval, 0)
    replica_swap_attempts =
        sum(_slit_trace_property(trace, :replica_swap_attempts, 0) for trace in traces)
    replica_swap_accepts =
        sum(_slit_trace_property(trace, :replica_swap_accepts, 0) for trace in traces)
    replica_round_trips =
        sum(_slit_trace_property(trace, :replica_round_trips, 0) for trace in traces)
    replica_min_round_trips =
        minimum(_slit_trace_property(trace, :replica_min_round_trips, 0) for trace in traces)
    replica_max_round_trips =
        maximum(_slit_trace_property(trace, :replica_max_round_trips, 0) for trace in traces)
    sampler_name = replica_count > 1 ?
                   "arianna_blocked_profile_fraction_replica_exchange_chunked" :
                   "arianna_blocked_profile_fraction_chunked"
    energy_trace = reduce(vcat, (trace.energy_trace for trace in traces))
    density_variance_trace = reduce(vcat, (trace.density_variance_trace for trace in traces))
    lateral_variance_trace = reduce(vcat, (trace.lateral_variance_trace for trace in traces))
    xy_profile_roughness_trace = reduce(vcat, (trace.xy_profile_roughness_trace for trace in traces))
    profile_measure_log_jacobian_trace = reduce(vcat,
        (trace.profile_measure_log_jacobian_trace for trace in traces))

    xi_eff, xi_fit_error = fit_slit_xi_eff(grid.z, mean_phi; L=grid.Lz)
    xi_bulk = _slit_bulk_xi(params.B, params.C)
    fit_phi = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz, xi=xi_eff)
    fit_diagnostics = _slit_profile_fit_diagnostics(mean_phi, fit_phi)
    target = Float64(target_xi_eff)
    target_phi = slit_reference_profile(grid.z; B=params.B, C=params.C, L=grid.Lz,
        xi=target)
    target_profile = _slit_profile_fit_diagnostics(mean_phi, target_phi)
    observable_convergence = _slit_profile_observable_convergence(
        chain_estimator_traces, mean_phi, grid, target_phi, target)
    tol = max(Float64(xi_tolerance), 0.0)
    rhat_gate = Float64(rhat_threshold)
    r2_gate = Float64(r2_threshold)
    rhat_ok = isfinite(profile_convergence.profile_chain_rhat_max) ?
              profile_convergence.profile_chain_rhat_max <= rhat_gate :
              length(traces) == 1
    split_rhat_ok = isfinite(profile_convergence.profile_split_rhat_max) ?
                    profile_convergence.profile_split_rhat_max <= rhat_gate :
                    length(traces) == 1
    r2_ok = isfinite(fit_diagnostics.r2) && fit_diagnostics.r2 >= r2_gate
    abs_xi_error = abs(xi_eff - target)
    drift_ok = xi_block_drift.block_drift_pass == 1.0
    observable_xi_ok = observable_convergence.observable_abs_xi_error <= tol
    observable_chain_xi_ok =
        abs(observable_convergence.observable_chain_xi_min - target) <= tol &&
        abs(observable_convergence.observable_chain_xi_max - target) <= tol
    observable_leave_one_min = observable_convergence.observable_leave_one_chain_xi_min
    observable_leave_one_max = observable_convergence.observable_leave_one_chain_xi_max
    observable_leave_one_xi_ok =
        (!isfinite(observable_leave_one_min) && !isfinite(observable_leave_one_max)) ||
        (abs(observable_leave_one_min - target) <= tol &&
         abs(observable_leave_one_max - target) <= tol)
    observable_target_profile_r2_ok =
        isfinite(target_profile.r2) && target_profile.r2 >= r2_gate
    observable_fit_quality_ok = fit_diagnostics.quality_pass == 1.0
    observable_calibration_pass =
        (observable_xi_ok && observable_chain_xi_ok && observable_leave_one_xi_ok &&
         observable_target_profile_r2_ok && observable_fit_quality_ok && drift_ok) ? 1.0 : 0.0
    observable_convergence = merge(observable_convergence, (
        observable_xi_pass=observable_xi_ok ? 1.0 : 0.0,
        observable_chain_xi_pass=observable_chain_xi_ok ? 1.0 : 0.0,
        observable_leave_one_chain_xi_pass=observable_leave_one_xi_ok ? 1.0 : 0.0,
        observable_target_profile_r2_pass=observable_target_profile_r2_ok ? 1.0 : 0.0,
        observable_fit_quality_pass=observable_fit_quality_ok ? 1.0 : 0.0,
        observable_block_drift_pass=drift_ok ? 1.0 : 0.0,
        observable_calibration_pass=observable_calibration_pass,
    ))
    calibration_pass = (abs_xi_error <= tol && r2_ok &&
                        fit_diagnostics.quality_pass == 1.0 &&
                        rhat_ok && split_rhat_ok && drift_ok) ? 1.0 : 0.0

    min_chunk_count = isempty(chunk_counts) ? 0 : minimum(Int.(chunk_counts))
    max_chunk_count = isempty(chunk_counts) ? 0 : maximum(Int.(chunk_counts))
    chunk_count = min_chunk_count
    min_completed_chunk_count = isempty(completed_chunk_counts) ? 0 :
                                minimum(Int.(completed_chunk_counts))
    max_completed_chunk_count = isempty(completed_chunk_counts) ? 0 :
                                maximum(Int.(completed_chunk_counts))
    completed_chunk_count = min_completed_chunk_count
    analysis_tail_chunk_count = analysis_tail_chunks === nothing ? 0 :
                                max(1, Int(analysis_tail_chunks))
    discarded_initial_chunks = max(0, Int(analysis_discard_initial_chunks))
    proposals_per_sweep = _proposals_per_sweep(grid)
    aggregate_steps = traces[1].steps
    aggregate_burnin_steps = traces[1].burnin_steps
    total_sweeps = _sweeps_from_steps(grid, aggregate_steps)
    production_sweeps = _sweeps_from_steps(grid, aggregate_steps - aggregate_burnin_steps)
    resolved_burnin_sweeps = _sweeps_from_steps(grid, aggregate_burnin_steps)
    resolved_sample_stride_sweeps = _sweeps_from_steps(grid, sample_stride)
    coordinate_log_jacobian_power = Float64(profile_measure_power) - 1.0

    profile_rows = NamedTuple[]
    for k in 1:grid.Nz
        z_over_L = grid.z[k] / grid.Lz
        push!(profile_rows, (series="saddle_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=Float64(saddle_phi[k]), stderr=0.0, xi=xi_bulk,
            sampler="reference"))
        push!(profile_rows, (series="mc_mean_3d_raw", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=raw_mean_phi[k], stderr=raw_stderr_phi[k],
            xi=NaN, sampler="arianna_blocked_raw_chunked"))
        push!(profile_rows, (series="mc_mean_3d", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=mean_phi[k], stderr=stderr_phi[k],
            xi=xi_eff, sampler=profile_estimator))
        push!(profile_rows, (series="eq22_fit_to_3d_mc", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=fit_phi[k], stderr=0.0, xi=xi_eff,
            sampler="post_fit"))
        push!(profile_rows, (series="ak_target_eq22", B=params.B, C=params.C, A=params.A,
            Nx=grid.Nx, Ny=grid.Ny, Nz=grid.Nz, Lxy=grid.Lxy, Lz=grid.Lz,
            z_over_L=z_over_L, phi=target_phi[k], stderr=0.0, xi=target,
            sampler="target_reference"))
    end
    profile_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_profile.csv"), profile_rows)
    observable_convergence_csv = _write_dataframe(
        joinpath(outdir, "slit_3d_mc_observable_convergence.csv"),
        [merge((profile_estimator=profile_estimator,), observable_convergence)])
    energy_summary = batch_summary(energy_trace)
    density_variance_summary = batch_summary(density_variance_trace)
    lateral_variance_summary = batch_summary(lateral_variance_trace)
    profile_measure_log_jacobian_summary = batch_summary(profile_measure_log_jacobian_trace)
    roughness_mean = mean(xy_profile_roughness_trace)
    diagnostics_rows = [(
        sampler=sampler_name,
        chunked_sampler=true,
        state_space="plane_mean_lateral_fraction",
        chunk_count=Float64(chunk_count),
        min_chunk_count=Float64(min_chunk_count),
        max_chunk_count=Float64(max_chunk_count),
        completed_chunk_count=Float64(completed_chunk_count),
        min_completed_chunk_count=Float64(min_completed_chunk_count),
        max_completed_chunk_count=Float64(max_completed_chunk_count),
        analysis_tail_chunks=Float64(analysis_tail_chunk_count),
        analysis_discard_initial_chunks=Float64(discarded_initial_chunks),
        initial_state_mode=String(initial_state_mode),
        initial_state_outdir=initial_state_outdir === nothing ? "" : String(initial_state_outdir),
        chain_indices=join(Int.(chain_indices), ";"),
        parallel_chains=Bool(parallel_chains),
        profile_measure_power=Float64(profile_measure_power),
        coordinate_log_jacobian_power=coordinate_log_jacobian_power,
        profile_measure_log_floor=max(Float64(profile_measure_log_floor), floatmin(Float64)),
        A=params.A,
        B=params.B,
        C=params.C,
        local_potential_a1=params.local_potential_coeffs[1],
        local_potential_a2=params.local_potential_coeffs[2],
        local_potential_a3=params.local_potential_coeffs[3],
        projected_local_potential_a1=params.projected_local_potential_coeffs[1],
        projected_local_potential_a2=params.projected_local_potential_coeffs[2],
        projected_local_potential_a3=params.projected_local_potential_coeffs[3],
        projected_local_potential_reference_source=String(projected_local_potential_reference_source),
        lateral_gradient_coeff=params.lateral_gradient_coeff,
        projected_entropy_coeff=params.projected_entropy_coeff,
        projected_entropy_reference_source=String(projected_entropy_reference_source),
        projected_quadratic_coeff=params.projected_quadratic_coeff,
        projected_quadratic_reference_source=String(projected_quadratic_reference_source),
        projected_quadratic_weight_source=String(projected_quadratic_weight_source),
        projected_quadratic_coeffs=_slit_join_float_values(params.projected_quadratic_coeffs),
        projected_quadratic_reference_sources=String(projected_quadratic_terms_reference_source),
        projected_quadratic_weight_sources=String(projected_quadratic_weight_sources),
        projected_quadratic_wall_width=Float64(projected_quadratic_wall_width),
        projected_profile_kernel_matrix_count=length(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_trace=
            _slit_matrix_trace(params.projected_profile_kernel_matrix),
        projected_profile_kernel_matrix_max_abs=
            _slit_matrix_max_abs(params.projected_profile_kernel_matrix),
        projected_profile_kernel_reference_source=String(projected_profile_kernel_reference_source),
        Nx=grid.Nx,
        Ny=grid.Ny,
        Nz=grid.Nz,
        Lxy=grid.Lxy,
        Lz=grid.Lz,
        steps=aggregate_steps,
        chunk_steps=Int(chunk_steps),
        burnin_steps=aggregate_burnin_steps,
        first_burnin_steps=Int(first_burnin_steps),
        sample_stride=Int(sample_stride),
        proposals_per_sweep=proposals_per_sweep,
        total_sweeps=total_sweeps,
        production_sweeps=production_sweeps,
        burnin_sweeps=resolved_burnin_sweeps,
        sample_stride_sweeps=resolved_sample_stride_sweeps,
        chain_count=length(traces),
        requested_chain_count=maximum(Int.(chain_indices)),
        replica_count=replica_count,
        replica_temperatures=replica_temperatures_text,
        replica_swap_interval=replica_swap_interval,
        replica_swap_attempts=replica_swap_attempts,
        replica_swap_accepts=replica_swap_accepts,
        replica_swap_acceptance_rate=replica_swap_accepts / max(replica_swap_attempts, 1),
        replica_round_trips=replica_round_trips,
        replica_min_round_trips=replica_min_round_trips,
        replica_max_round_trips=replica_max_round_trips,
        sample_count=sample_count,
        profile_estimator=profile_estimator,
        profile_symmetrized=symmetrize_profile,
        attempted_moves=attempted_moves,
        accepted_moves=accepted_moves,
        acceptance_rate=accepted_moves / max(attempted_moves, 1),
        lateral_fraction_acceptance_rate=lateral_fraction_accepted / max(lateral_fraction_attempted, 1),
        profile_transfer_acceptance_rate=profile_transfer_accepted / max(profile_transfer_attempted, 1),
        profile_mode_acceptance_rate=profile_mode_accepted / max(profile_mode_attempted, 1),
        reference_width_acceptance_rate=reference_width_accepted / max(reference_width_attempted, 1),
        reference_width_reflection_acceptance_rate=reference_width_reflection_accepted /
                                                   max(reference_width_reflection_attempted, 1),
        lateral_fraction_amplitude=Float64(lateral_fraction_amplitude),
        profile_transfer_amplitude=Float64(profile_transfer_amplitude),
        profile_mode_amplitude=Float64(profile_mode_amplitude),
        profile_mode_count=max(1, Int(profile_mode_count)),
        reference_width_amplitude=Float64(reference_width_amplitude),
        reference_width_xi=Float64(reference_width_xi),
        lateral_fraction_move_weight=Float64(lateral_fraction_move_weight),
        profile_transfer_move_weight=Float64(profile_transfer_move_weight),
        profile_mode_move_weight=Float64(profile_mode_move_weight),
        reference_width_move_weight=Float64(reference_width_move_weight),
        reference_width_reflection_move_weight=Float64(reference_width_reflection_move_weight),
        energy_mean=energy_summary.mean,
        energy_stderr=energy_summary.stderr,
        density_variance_mean=density_variance_summary.mean,
        density_variance_stderr=density_variance_summary.stderr,
        lateral_variance_mean=lateral_variance_summary.mean,
        lateral_variance_stderr=lateral_variance_summary.stderr,
        profile_measure_log_jacobian_mean=profile_measure_log_jacobian_summary.mean,
        profile_measure_log_jacobian_stderr=profile_measure_log_jacobian_summary.stderr,
        xy_profile_roughness_mean=roughness_mean,
        target_xi_eff=target,
        xi_bulk=xi_bulk,
        xi_eff=xi_eff,
        abs_xi_error=abs_xi_error,
        xi_tolerance=tol,
        xi_fit_error=xi_fit_error,
        xi_fit_rmse=fit_diagnostics.rmse,
        xi_fit_r2=fit_diagnostics.r2,
        xi_fit_mae=fit_diagnostics.mae,
        xi_fit_max_abs_error=fit_diagnostics.max_abs_error,
        xi_fit_wall_rms=fit_diagnostics.wall_rms,
        xi_fit_nrmse_range=fit_diagnostics.nrmse_range,
        xi_fit_nrmse_mean=fit_diagnostics.nrmse_mean,
        xi_fit_quality_pass=fit_diagnostics.quality_pass,
        target_profile_rmse=target_profile.rmse,
        target_profile_r2=target_profile.r2,
        target_profile_max_abs_error=target_profile.max_abs_error,
        target_profile_wall_rms=target_profile.wall_rms,
        observable_xi_eff=observable_convergence.observable_xi_eff,
        observable_abs_xi_error=observable_convergence.observable_abs_xi_error,
        observable_chain_xi_mean=observable_convergence.observable_chain_xi_mean,
        observable_chain_xi_sd=observable_convergence.observable_chain_xi_sd,
        observable_chain_xi_min=observable_convergence.observable_chain_xi_min,
        observable_chain_xi_max=observable_convergence.observable_chain_xi_max,
        observable_leave_one_chain_xi_min=observable_convergence.observable_leave_one_chain_xi_min,
        observable_leave_one_chain_xi_max=observable_convergence.observable_leave_one_chain_xi_max,
        observable_central_density_floor=observable_convergence.observable_central_density_floor,
        observable_central_bin_count=Float64(observable_convergence.observable_central_bin_count),
        observable_central_rhat_max=observable_convergence.observable_central_rhat_max,
        observable_central_split_rhat_max=observable_convergence.observable_central_split_rhat_max,
        observable_xi_pass=observable_convergence.observable_xi_pass,
        observable_chain_xi_pass=observable_convergence.observable_chain_xi_pass,
        observable_leave_one_chain_xi_pass=observable_convergence.observable_leave_one_chain_xi_pass,
        observable_target_profile_r2_pass=observable_convergence.observable_target_profile_r2_pass,
        observable_fit_quality_pass=observable_convergence.observable_fit_quality_pass,
        observable_block_drift_pass=observable_convergence.observable_block_drift_pass,
        observable_calibration_pass=observable_convergence.observable_calibration_pass,
        profile_chain_rhat_max=profile_convergence.profile_chain_rhat_max,
        profile_split_rhat_max=profile_convergence.profile_split_rhat_max,
        profile_chain_rmse_max=profile_convergence.profile_chain_rmse_max,
        profile_chain_max_abs_deviation=profile_convergence.profile_chain_max_abs_deviation,
        rhat_threshold=rhat_gate,
        r2_threshold=r2_gate,
        xi_block_drift_pass=xi_block_drift.block_drift_pass,
        xi_block_max_abs_start_end_delta=xi_block_drift.max_abs_start_end_delta,
        xi_block_max_abs_slope=xi_block_drift.max_abs_slope,
        xi_block_monotone_chain_fraction=xi_block_drift.monotone_chain_fraction,
        xi_block_min_block_count=Float64(xi_block_drift.min_block_count),
        xi_block_max_block_count=Float64(xi_block_drift.max_block_count),
        block_drift_tolerance=max(Float64(block_drift_tolerance), 0.0),
        calibration_pass=calibration_pass,
    )]
    diagnostics_csv = _write_dataframe(joinpath(outdir, "slit_3d_mc_diagnostics.csv"),
        diagnostics_rows)
    profile_svg = _write_slit_3d_profile_svg(profile_csv, outdir)
    summary_rows = [(
        state_space="plane_mean_lateral_fraction",
        profile_measure_power=Float64(profile_measure_power),
        coordinate_log_jacobian_power=coordinate_log_jacobian_power,
        projected_entropy_coeff=params.projected_entropy_coeff,
