function run_slit_3d_vk1_blocked_chunk!(
    outdir::AbstractString;
    Nx::Integer=20,
    Ny::Integer=Nx,
    Nz::Integer=40,
    Lxy::Real=1.0,
    Lz::Real=1.0,
    B::Real=25.0,
    C::Real=0.5,
    A::Real=0.0,
    alpha::Real=0.0,
    local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_coeffs=(0.0, 0.0, 0.0),
    projected_local_potential_reference=:saddle,
    lateral_gradient_coeff::Real=0.0,
    projected_entropy_coeff::Real=0.0,
    projected_entropy_reference=:saddle,
    projected_quadratic_coeff::Real=0.0,
    projected_quadratic_reference=:saddle,
    projected_quadratic_weight=:uniform,
    projected_quadratic_coeffs=(),
    projected_quadratic_weights=(),
    projected_quadratic_wall_width::Real=0.2,
    projected_profile_kernel_matrix=(),
    projected_profile_kernel_reference=:saddle,
    target_xi_eff::Real=0.34956193172308436,
    target_source::AbstractString="Alexander-Katz Fig. 3 filled-square CL target",
    xi_tolerance::Real=0.03,
    rhat_threshold::Real=1.25,
    r2_threshold::Real=0.995,
    block_drift_tolerance::Real=0.03,
    chunk_steps::Integer=64_000,
    first_burnin_steps::Integer=0,
    sample_stride::Integer=1_600,
    chunk_sweeps=nothing,
    first_burnin_sweeps=nothing,
    sample_stride_sweeps=nothing,
    chains::Integer=4,
    chain_indices=nothing,
    parallel_chains::Bool=false,
    analysis_tail_chunks=nothing,
    analysis_discard_initial_chunks::Integer=0,
    symmetrize_profile::Bool=true,
    lateral_fraction_amplitude::Real=5.0e-2,
    profile_transfer_amplitude::Real=1.0e-3,
    profile_mode_amplitude::Real=1.0e-3,
    reference_width_amplitude::Real=5.0e-4,
    lateral_fraction_move_weight::Real=0.60,
    profile_transfer_move_weight::Real=0.15,
    profile_mode_move_weight::Real=0.05,
    reference_width_move_weight::Real=0.20,
    reference_width_reflection_move_weight::Real=0.0,
    profile_mode_count::Integer=4,
    reference_width_xi::Real=0.0,
    phi_min::Real=1.0e-10,
    profile_measure_power::Real=1.0,
    profile_measure_log_floor::Real=1.0e-300,
    seed::Integer=260625,
    initial_profile=:reference_width,
    initial_state_outdir=nothing,
    replica_temperatures=(),
    replica_swap_interval::Integer=100,
)
    mkpath(outdir)
    mkpath(_slit_3d_chunk_trace_dir(outdir))
    mkpath(_slit_3d_chunk_state_dir(outdir))
    grid = SlitGrid3D(Nx, Nz, Lz; Ny=Ny, Lxy=Lxy)
    local_coeffs = _slit_local_potential_coeffs(local_potential_coeffs)
    projected_local_coeffs =
        _slit_projected_local_potential_coeffs(projected_local_potential_coeffs)
    lateral_gradient = _slit_lateral_gradient_coeff(lateral_gradient_coeff)
    projected_entropy = _slit_projected_entropy_coeff(projected_entropy_coeff)
    projected_quadratic = _slit_projected_quadratic_coeff(projected_quadratic_coeff)
    projected_profile_kernel =
        _slit_projected_profile_kernel_matrix(projected_profile_kernel_matrix)
    base_params = SlitParams(B=Float64(B), C=Float64(C), A=Float64(A), alpha=Float64(alpha),
        model=:vk1, local_potential_coeffs=local_coeffs,
        lateral_gradient_coeff=lateral_gradient)
    target = Float64(target_xi_eff)
    target > 0.0 || throw(ArgumentError("target_xi_eff must be positive"))
    resolved_reference_width_xi = Float64(reference_width_xi) > 0.0 ?
                                  Float64(reference_width_xi) : target
    replica_temperature_values = _slit_replica_temperature_values(replica_temperatures, 1.0)
    replica_count = length(replica_temperature_values)
    saddle_phi = _slit_3d_measure_corrected_saddle_profile(grid, base_params, initial_profile,
        resolved_reference_width_xi)
    projected_reference, projected_reference_source =
        _slit_resolve_projected_entropy_reference(projected_entropy_reference,
            projected_entropy, saddle_phi, grid.slit_grid)
    projected_local_reference, projected_local_reference_source =
        _slit_resolve_projected_local_potential_reference(
            projected_local_potential_reference, projected_local_coeffs, saddle_phi,
            grid.slit_grid)
    projected_quadratic_ref, projected_quadratic_reference_source =
        _slit_resolve_projected_quadratic_reference(projected_quadratic_reference,
            projected_quadratic, saddle_phi, grid.slit_grid)
    projected_quadratic_weight_values, projected_quadratic_weight_source =
        _slit_resolve_projected_quadratic_weight(projected_quadratic_weight,
            projected_quadratic, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_quadratic_coeff_values, projected_quadratic_refs,
    projected_quadratic_weight_values_vec, projected_quadratic_terms_reference_source,
    projected_quadratic_weight_sources =
        _slit_resolve_projected_quadratic_terms(projected_quadratic_coeffs,
            projected_quadratic_reference, projected_quadratic_weights,
            saddle_phi, grid.slit_grid;
            wall_width=projected_quadratic_wall_width)
    projected_profile_kernel_ref, projected_profile_kernel_reference_source =
        _slit_resolve_projected_profile_kernel_reference(
            projected_profile_kernel_reference, projected_profile_kernel, saddle_phi,
            grid.slit_grid)
    params = SlitParams(B=base_params.B, C=base_params.C, A=base_params.A,
        alpha=base_params.alpha, model=:vk1,
        local_potential_coeffs=base_params.local_potential_coeffs,
        projected_local_potential_coeffs=projected_local_coeffs,
        projected_local_potential_reference=projected_local_reference,
        lateral_gradient_coeff=base_params.lateral_gradient_coeff,
        projected_entropy_coeff=projected_entropy,
        projected_entropy_reference=projected_reference,
        projected_quadratic_coeff=projected_quadratic,
        projected_quadratic_reference=projected_quadratic_ref,
        projected_quadratic_weight=projected_quadratic_weight_values,
        projected_quadratic_coeffs=projected_quadratic_coeff_values,
        projected_quadratic_references=projected_quadratic_refs,
        projected_quadratic_weights=projected_quadratic_weight_values_vec,
        projected_profile_kernel_matrix=projected_profile_kernel,
        projected_profile_kernel_reference=projected_profile_kernel_ref)
    base_field = slit_3d_field_from_profile(saddle_phi, grid)
    initial_state_mode = initial_state_outdir === nothing ?
                         "saddle_profile" : "external_chunk_state"
    resolved_steps = chunk_sweeps === nothing ? max(1, Int(chunk_steps)) :
                     _steps_from_sweeps(grid, chunk_sweeps)
    resolved_first_burnin_steps = first_burnin_sweeps === nothing ?
                                  max(0, Int(first_burnin_steps)) :
                                  max(0, ceil(Int,
                                      Float64(first_burnin_sweeps) *
                                      _proposals_per_sweep(grid)))
    resolved_sample_stride = sample_stride_sweeps === nothing ?
                             max(1, Int(sample_stride)) :
                             max(1, ceil(Int,
                                 Float64(sample_stride_sweeps) *
                                 _proposals_per_sweep(grid)))
    selected_chain_indices = _slit_3d_select_chain_indices(chain_indices, chains)
    manifest_path = _slit_3d_chunk_manifest_path(outdir)
    manifest_header = [
        "chain",
        "chunk",
        "seed",
        "steps",
        "burnin_steps",
        "sample_stride",
        "sample_count",
        "accepted_moves",
        "attempted_moves",
        "acceptance_rate",
        "trace_path",
        "state_path",
    ]
    function build_chunk_result(chain_idx::Int)
        next_chunk = _slit_3d_next_chunk_index(manifest_path, chain_idx)
        state_path = _slit_3d_chunk_state_path(outdir, chain_idx)
        if next_chunk > 1 && !isfile(state_path)
            throw(ArgumentError("missing blocked chunk state for chain $(chain_idx): $(state_path)"))
        elseif next_chunk == 1 && isfile(state_path)
            throw(ArgumentError("state exists for chain $(chain_idx) but manifest has no completed chunk"))
        end
        initial_field = if next_chunk == 1 && initial_state_outdir !== nothing
            source_state_path = _slit_3d_chunk_state_path(String(initial_state_outdir), chain_idx)
            isfile(source_state_path) ||
                throw(ArgumentError("missing initial blocked state for chain $(chain_idx): $(source_state_path)"))
            _deserialize_jls(source_state_path)
        elseif next_chunk == 1
            copy(base_field)
        else
            _deserialize_jls(state_path)
        end
        _slit_3d_validate_phi(initial_field, grid)
        burn = next_chunk == 1 ? resolved_first_burnin_steps : 0
        chunk_seed = Int(seed) + 100_000 * (chain_idx - 1) + 1_000 * (next_chunk - 1)
        trace = if replica_count > 1
            _run_slit_3d_blocked_replica_exchange_trace(
                grid,
                params,
                initial_field;
                steps=resolved_steps,
                burnin_steps=burn,
                sample_stride=resolved_sample_stride,
                lateral_fraction_amplitude=lateral_fraction_amplitude,
                profile_transfer_amplitude=profile_transfer_amplitude,
                profile_mode_amplitude=profile_mode_amplitude,
                profile_mode_count=profile_mode_count,
                reference_width_amplitude=reference_width_amplitude,
                reference_width_xi=resolved_reference_width_xi,
                lateral_fraction_weight=lateral_fraction_move_weight,
                profile_transfer_weight=profile_transfer_move_weight,
                profile_mode_weight=profile_mode_move_weight,
                reference_width_weight=reference_width_move_weight,
                reference_width_reflection_weight=reference_width_reflection_move_weight,
                phi_min=phi_min,
                profile_measure_power=profile_measure_power,
                profile_measure_log_floor=profile_measure_log_floor,
                seed=chunk_seed,
                replica_temperatures=replica_temperature_values,
                replica_swap_interval=replica_swap_interval,
            )
        else
            _run_slit_3d_blocked_arianna_trace(
                grid,
                params,
                initial_field;
                steps=resolved_steps,
                burnin_steps=burn,
                sample_stride=resolved_sample_stride,
                lateral_fraction_amplitude=lateral_fraction_amplitude,
                profile_transfer_amplitude=profile_transfer_amplitude,
                profile_mode_amplitude=profile_mode_amplitude,
                profile_mode_count=profile_mode_count,
                reference_width_amplitude=reference_width_amplitude,
                reference_width_xi=resolved_reference_width_xi,
                lateral_fraction_weight=lateral_fraction_move_weight,
                profile_transfer_weight=profile_transfer_move_weight,
                profile_mode_weight=profile_mode_move_weight,
                reference_width_weight=reference_width_move_weight,
                reference_width_reflection_weight=reference_width_reflection_move_weight,
                phi_min=phi_min,
                profile_measure_power=profile_measure_power,
                profile_measure_log_floor=profile_measure_log_floor,
                seed=chunk_seed,
            )
        end
        trace_path = _slit_3d_chunk_trace_path(outdir, chain_idx, next_chunk)
        row = [
            chain_idx,
            next_chunk,
            chunk_seed,
            trace.steps,
            trace.burnin_steps,
            trace.sample_stride,
            trace.sample_count,
            trace.accepted_moves,
            trace.attempted_moves,
            trace.acceptance_rate,
            trace_path,
            state_path,
        ]
        return (trace=trace, trace_path=trace_path, state_path=state_path, row=row)
    end
    chunk_results = if Bool(parallel_chains) && length(selected_chain_indices) > 1
        tasks = [
            let idx = Int(chain_idx)
                Threads.@spawn build_chunk_result(idx)
            end
            for chain_idx in selected_chain_indices
        ]
        [fetch(task) for task in tasks]
    else
        [build_chunk_result(Int(chain_idx)) for chain_idx in selected_chain_indices]
    end
    for result in chunk_results
        trace = result.trace
        trace_path = result.trace_path
        state_path = result.state_path
        _serialize_jls(trace_path, trace)
        _serialize_jls(state_path, trace.final_phi)
        _append_table_row(manifest_path, manifest_header, result.row)
    end
    loaded = _load_slit_3d_blocked_chunk_traces(manifest_path, max(1, Int(chains));
        analysis_tail_chunks=analysis_tail_chunks,
        analysis_discard_initial_chunks=analysis_discard_initial_chunks)
    return _finalize_slit_3d_blocked_chunks(
        outdir,
        grid,
        params,
        saddle_phi,
        loaded.traces,
        loaded.chain_indices,
        loaded.chunk_counts;
        completed_chunk_counts=loaded.completed_chunk_counts,
        analysis_tail_chunks=analysis_tail_chunks,
        analysis_discard_initial_chunks=analysis_discard_initial_chunks,
        target_xi_eff=target,
        target_source=target_source,
        xi_tolerance=xi_tolerance,
        rhat_threshold=rhat_threshold,
        r2_threshold=r2_threshold,
        block_drift_tolerance=block_drift_tolerance,
        symmetrize_profile=symmetrize_profile,
        profile_measure_power=profile_measure_power,
        profile_measure_log_floor=profile_measure_log_floor,
        lateral_fraction_amplitude=lateral_fraction_amplitude,
        profile_transfer_amplitude=profile_transfer_amplitude,
        profile_mode_amplitude=profile_mode_amplitude,
        reference_width_amplitude=reference_width_amplitude,
        profile_mode_count=profile_mode_count,
        lateral_fraction_move_weight=lateral_fraction_move_weight,
        profile_transfer_move_weight=profile_transfer_move_weight,
        profile_mode_move_weight=profile_mode_move_weight,
        reference_width_move_weight=reference_width_move_weight,
        reference_width_reflection_move_weight=reference_width_reflection_move_weight,
        reference_width_xi=resolved_reference_width_xi,
        phi_min=phi_min,
        projected_entropy_reference_source=projected_reference_source,
        projected_local_potential_reference_source=projected_local_reference_source,
        projected_quadratic_reference_source=projected_quadratic_reference_source,
        projected_quadratic_weight_source=projected_quadratic_weight_source,
        projected_quadratic_terms_reference_source=projected_quadratic_terms_reference_source,
        projected_quadratic_weight_sources=projected_quadratic_weight_sources,
        projected_quadratic_wall_width=projected_quadratic_wall_width,
        projected_profile_kernel_reference_source=projected_profile_kernel_reference_source,
        initial_profile=initial_profile,
        initial_state_outdir=initial_state_outdir,
        initial_state_mode=initial_state_mode,
        parallel_chains=parallel_chains,
        seed=seed,
        chunk_steps=resolved_steps,
        first_burnin_steps=resolved_first_burnin_steps,
        sample_stride=resolved_sample_stride)
end

function _arianna_spike(outdir::AbstractString; seed=1, steps=100)
    grid = Grid3D(4, 6.4)
    params = HEURPParams()
    chains = [DensityFieldSystem(ones(grid.Nx, grid.Nx, grid.Nx), grid, params)]
    pool = (Arianna.Move(PairDensityAction(1, 2, 0.0), PairDensityPolicy(), [0.02], 1.0),)
    schedule = Arianna.build_schedule(max(steps, 1), 0, 1)
    path = joinpath(outdir, "arianna_native")
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=seed, parallel=false),
        (algorithm=Arianna.StoreCallbacks, callbacks=(field_energy, density_variance, low_mode_structure_factor), store_first=false, scheduler=schedule),
        (algorithm=Arianna.StoreAcceptance, dependencies=(Arianna.Metropolis,), scheduler=schedule),
    )
    simulation = Arianna.Simulation(chains, algorithms, max(steps, 1); path=path, verbose=false)
    Arianna.run!(simulation)
    energy_path = joinpath(path, "chains", "1", "field_energy.dat")
    variance_path = joinpath(path, "chains", "1", "density_variance.dat")
    structure_path = joinpath(path, "chains", "1", "low_mode_structure_factor.dat")
    energy_rows = isfile(energy_path) ? readdlm(energy_path) : zeros(0, 2)
    variance_rows = isfile(variance_path) ? readdlm(variance_path) : zeros(0, 2)
    structure_rows = isfile(structure_path) ? readdlm(structure_path) : zeros(0, 2)
    rows = Any[]
    for idx in 1:min(size(energy_rows, 1), size(variance_rows, 1), size(structure_rows, 1))
        push!(rows, (
            Int(energy_rows[idx, 1]),
            Float64(energy_rows[idx, 2]),
            Float64(variance_rows[idx, 2]),
            Float64(structure_rows[idx, 2]),
        ))
    end
    csv = _write_table(joinpath(outdir, "arianna_spike.csv"),
        ["step", "energy", "density_variance", "low_mode_structure_factor"], rows)
    accepted = 0
    total = 0
    for move in simulation.algorithms[1].pools[1]
        accepted += move.accepted_calls
        total += move.total_calls
    end
    return AriannaSpikeResult(true, csv, accepted / max(total, 1), true)
end

function _arianna_pair_acceptance_probe(
    grid::Grid3D,
    params::HEURPParams,
    amplitude::Real;
    seed=1,
    steps=20,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
    initial_phi=nothing,
)
    phi = initial_phi === nothing ? ones(grid.Nx, grid.Nx, grid.Nx) : copy(initial_phi)
    chain = DensityFieldSystem(phi, grid, params;
        basin_variance_max=basin_variance_max, phi_min=phi_min, target_model=target_model,
        boundary_barrier_strength=boundary_barrier_strength)
    pool = (
        Arianna.Move(PairDensityAction(1, 2, 0.0), PairDensityPolicy(), [Float64(amplitude)], 1.0),
    )
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=seed, parallel=false),
    )
    simulation = Arianna.Simulation([chain], algorithms, max(steps, 1); path=mktempdir(), verbose=false)
    Arianna.run!(simulation)
    accepted = 0
    total = 0
    for move in simulation.algorithms[1].pools[1]
        accepted += move.accepted_calls
        total += move.total_calls
    end
    return accepted / max(total, 1)
end

function _arianna_fourier_acceptance_probe(
    grid::Grid3D,
    params::HEURPParams,
    amplitude::Real,
    fourier_max_mode::Integer,
    fourier_min_k2::Real;
    seed=1,
    steps=20,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
    initial_phi=nothing,
)
    min_k2 = max(0.0, Float64(fourier_min_k2))
    max_mode = clamp(max(1, Int(fourier_max_mode)), 1, max(1, fld(grid.Nx, 2)))
    parameters = [max(Float64(amplitude), eps(Float64)), Float64(max_mode), min_k2]
    _fourier_mode_candidates(parameters, grid)
    phi = initial_phi === nothing ? ones(grid.Nx, grid.Nx, grid.Nx) : copy(initial_phi)
    chain = DensityFieldSystem(phi, grid, params;
        basin_variance_max=basin_variance_max, phi_min=phi_min, target_model=target_model,
        boundary_barrier_strength=boundary_barrier_strength)
    pool = (
        Arianna.Move(FourierModeDensityAction(0, 0, 0, 0.0, 0.0),
            FourierModeDensityPolicy(), parameters, 1.0),
    )
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=seed, parallel=false),
    )
    simulation = Arianna.Simulation([chain], algorithms, max(steps, 1); path=mktempdir(), verbose=false)
    Arianna.run!(simulation)
    accepted = 0
    total = 0
    for move in simulation.algorithms[1].pools[1]
        accepted += move.accepted_calls
        total += move.total_calls
    end
    return accepted / max(total, 1)
end

function _resolved_fourier_min_k2(params::HEURPParams; stable_mode_proposals=false, fourier_min_k2=nothing)
    explicit = fourier_min_k2 === nothing ? nothing : max(0.0, Float64(fourier_min_k2))
    if Bool(stable_mode_proposals)
        return explicit === nothing ? 2.0 * params.A / params.C : explicit
    end
    return explicit === nothing ? 0.0 : explicit
end

function _stability_probe_modes_for_target(
    grid::Grid3D,
    requested_modes,
    max_mode::Integer,
    min_k2::Real,
)
    cutoff = max(0.0, Float64(min_k2))
    filtered = Tuple{Int,Int,Int}[]
    for mode in requested_modes
        candidate = (Int(mode[1]), Int(mode[2]), Int(mode[3]))
        (candidate[1] == 0 && candidate[2] == 0 && candidate[3] == 0) && continue
        _fourier_mode_k2(grid, candidate...) >= cutoff - 1.0e-12 || continue
        push!(filtered, candidate)
    end
    !isempty(filtered) && return filtered
    cutoff <= 0.0 && return Tuple{Int,Int,Int}[(Int(mode[1]), Int(mode[2]), Int(mode[3])) for mode in requested_modes]
    candidates = _fourier_mode_candidates([1.0, Float64(max_mode), cutoff], grid)
    return candidates[1:min(length(candidates), max(1, length(requested_modes)))]
end

function _tune_pair_move_amplitude(
    grid::Grid3D,
    params::HEURPParams;
    initial_amplitude=0.01,
    target_acceptance=0.44,
    rounds=3,
    steps_per_round=20,
    seed=1,
    min_amplitude=1.0e-6,
    max_amplitude=0.5,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
    initial_phi=nothing,
)
    amplitude = clamp(Float64(initial_amplitude), Float64(min_amplitude), Float64(max_amplitude))
    target = clamp(Float64(target_acceptance), 1.0e-3, 0.999)
    completed_rounds = max(0, Int(rounds))
    completed_rounds == 0 && return (
        amplitude=amplitude,
        target_acceptance=target,
        tuning_rounds=0,
        tuning_acceptance_rate=NaN,
    )

    min_amp = Float64(min_amplitude)
    max_amp = Float64(max_amplitude)
    low_amp = NaN
    high_amp = NaN
    best_amplitude = amplitude
    best_acceptance = NaN
    best_distance = Inf

    function probe(candidate, round)
        acc = _arianna_pair_acceptance_probe(
            grid,
            params,
            candidate;
            seed=seed + round,
            steps=max(1, Int(steps_per_round)),
            basin_variance_max=basin_variance_max,
            phi_min=phi_min,
            target_model=target_model,
            boundary_barrier_strength=boundary_barrier_strength,
            initial_phi=initial_phi,
        )
        distance = abs(acc - target)
        if distance < best_distance
            best_distance = distance
            best_amplitude = candidate
            best_acceptance = acc
        end
        return acc
    end

    for round in 1:completed_rounds
        acc = probe(amplitude, round)
        if acc > target
            low_amp = amplitude
        else
            high_amp = amplitude
        end

        if isfinite(low_amp) && isfinite(high_amp)
            amplitude = exp((log(low_amp) + log(high_amp)) / 2.0)
        elseif acc > target
            amplitude = min(max_amp, amplitude * 4.0)
        else
            amplitude = max(min_amp, amplitude / 4.0)
        end
        (amplitude == min_amp || amplitude == max_amp) && (best_distance <= 0.05) && break
    end

    return (
        amplitude=best_amplitude,
        target_acceptance=target,
        tuning_rounds=completed_rounds,
        tuning_acceptance_rate=best_acceptance,
    )
end

