end

function _default_tuning_steps(burn_steps::Integer)
    burn = max(0, Int(burn_steps))
    return clamp(burn, 25, 2_000)
end

function _fixed_move_tuning(amplitude::Real, target_acceptance::Real)
    return (
        amplitude=Float64(amplitude),
        target_acceptance=clamp(Float64(target_acceptance), 1.0e-3, 0.999),
        tuning_rounds=0,
        tuning_acceptance_rate=NaN,
    )
end

function _weighted_tuning_acceptance(pairs::AbstractVector{<:Tuple})
    numerator = 0.0
    denominator = 0.0
    for (weight, rate) in pairs
        w = Float64(weight)
        r = Float64(rate)
        if w > 0.0 && isfinite(r)
            numerator += w * r
            denominator += w
        end
    end
    return denominator == 0.0 ? NaN : numerator / denominator
end

function _move_acceptance(move)
    total = move.total_calls
    return total == 0 ? NaN : move.accepted_calls / total
end

function _adapt_metropolis_amplitude(
    amplitude::Real,
    acceptance::Real;
    target_acceptance::Real,
    gain::Real=1.0,
    min_amplitude::Real=1.0e-8,
    max_amplitude::Real=0.5,
)
    acc = Float64(acceptance)
    isfinite(acc) || return clamp(Float64(amplitude), Float64(min_amplitude), Float64(max_amplitude))
    target = clamp(Float64(target_acceptance), 1.0e-3, 0.999)
    log_step = clamp(Float64(gain) * (acc - target), -1.0, 1.0)
    return clamp(Float64(amplitude) * exp(log_step), Float64(min_amplitude), Float64(max_amplitude))
end

function _adaptive_warmup_density_field!(
    phi::Array{Float64,3},
    grid::Grid3D,
    params::HEURPParams;
    pair_amplitude::Real,
    fourier_amplitude::Real,
    pair_weight::Real,
    collective_amplitude_scale::Real,
    collective_pair_count::Integer,
    collective_weight::Real,
    fourier_weight::Real,
    global_amplitude::Real=0.0,
    global_weight::Real=0.0,
    radial_variance_amplitude::Real=0.0,
    radial_variance_weight::Real=0.0,
    fourier_max_mode::Integer,
    fourier_min_k2::Real,
    stable_mode_proposals::Bool,
    rounds::Integer,
    steps_per_round::Integer,
    target_acceptance::Real,
    gain::Real=1.0,
    seed::Integer=1,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    target_model=:heurp,
    boundary_barrier_strength=0.0,
)
    round_count = max(0, Int(rounds))
    step_count = max(1, Int(steps_per_round))
    pair_amp = max(Float64(pair_amplitude), eps(Float64))
    fourier_amp = max(Float64(fourier_amplitude), eps(Float64))
    global_amp = max(Float64(global_amplitude), eps(Float64))
    radial_amp = max(Float64(radial_variance_amplitude), eps(Float64))
    pair_w = max(0.0, Float64(pair_weight))
    collective_w = max(0.0, Float64(collective_weight))
    fourier_w = max(0.0, Float64(fourier_weight))
    global_w = max(0.0, Float64(global_weight))
    radial_w = max(0.0, Float64(radial_variance_weight))
    multi_pair_count = max(2, Int(collective_pair_count))
    fourier_mode_count = clamp(max(1, Int(round(fourier_max_mode))), 1, max(1, fld(grid.Nx, 2)))
    min_k2 = max(0.0, Float64(fourier_min_k2))
    basin_cap = _basin_variance_cap(basin_variance_max)
    lower_bound = _density_lower_bound(phi_min)
    model = _direct_target_model_symbol(target_model)
    barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
    chain = DensityFieldSystem(phi, grid, params; basin_variance_max=basin_cap,
        phi_min=lower_bound, target_model=model, boundary_barrier_strength=barrier_strength)
    last_pair_acceptance = NaN
    last_collective_acceptance = NaN
    last_fourier_acceptance = NaN
    last_global_acceptance = NaN
    last_radial_acceptance = NaN

    for round_idx in 1:round_count
        collective_amplitude = max(pair_amp * Float64(collective_amplitude_scale) /
                                   sqrt(multi_pair_count), eps(Float64))
        fourier_parameters = [fourier_amp, Float64(fourier_mode_count), min_k2]
        pool = if stable_mode_proposals
            (Arianna.Move(FourierModeDensityAction(0, 0, 0, 0.0, 0.0),
                FourierModeDensityPolicy(), fourier_parameters, 1.0),)
        else
            base_pool = (
                Arianna.Move(PairDensityAction(1, 2, 0.0), PairDensityPolicy(),
                    [pair_amp], pair_w),
                Arianna.Move(MultiPairDensityAction(Int[], Int[], Float64[]),
                    MultiPairDensityPolicy(),
                    [collective_amplitude, Float64(multi_pair_count)], collective_w),
                Arianna.Move(FourierModeDensityAction(0, 0, 0, 0.0, 0.0),
                    FourierModeDensityPolicy(), fourier_parameters, fourier_w),
                Arianna.Move(RadialVarianceDensityAction(0.0),
                    RadialVarianceDensityPolicy(), [radial_amp], radial_w),
            )
            global_w > 0.0 ?
                (base_pool..., Arianna.Move(GlobalGaussianDensityAction(zeros(size(phi))),
                    GlobalGaussianDensityPolicy(), [global_amp], global_w)) :
                base_pool
        end
        algorithms = ((algorithm=Arianna.Metropolis, pool=pool,
            seed=Int(seed) + round_idx, parallel=false),)
        simulation = Arianna.Simulation([chain], algorithms, step_count; path=mktempdir(), verbose=false)
        Arianna.run!(simulation)
        metropolis_pool = simulation.algorithms[1].pools[1]
        if stable_mode_proposals
            last_pair_acceptance = NaN
            last_collective_acceptance = NaN
            last_fourier_acceptance = _move_acceptance(metropolis_pool[1])
            last_global_acceptance = NaN
            last_radial_acceptance = NaN
            fourier_amp = _adapt_metropolis_amplitude(fourier_amp, last_fourier_acceptance;
                target_acceptance=target_acceptance, gain=gain)
        else
            last_pair_acceptance = _move_acceptance(metropolis_pool[1])
            last_collective_acceptance = _move_acceptance(metropolis_pool[2])
            last_fourier_acceptance = _move_acceptance(metropolis_pool[3])
            last_radial_acceptance = _move_acceptance(metropolis_pool[4])
            last_global_acceptance = length(metropolis_pool) >= 5 ? _move_acceptance(metropolis_pool[5]) : NaN
            local_acceptance = _weighted_tuning_acceptance([
                (pair_w, last_pair_acceptance),
                (collective_w, last_collective_acceptance),
            ])
            pair_amp = _adapt_metropolis_amplitude(pair_amp, local_acceptance;
                target_acceptance=target_acceptance, gain=gain)
            fourier_amp = _adapt_metropolis_amplitude(fourier_amp, last_fourier_acceptance;
                target_acceptance=target_acceptance, gain=gain)
            global_amp = _adapt_metropolis_amplitude(global_amp, last_global_acceptance;
                target_acceptance=target_acceptance, gain=gain)
            radial_amp = _adapt_metropolis_amplitude(radial_amp, last_radial_acceptance;
                target_acceptance=target_acceptance, gain=gain)
        end
    end

    return (
        pair_proposal_amplitude=pair_amp,
        fourier_mode_amplitude=fourier_amp,
        global_field_amplitude=global_amp,
        radial_variance_amplitude=radial_amp,
        adaptive_warmup_rounds=round_count,
        adaptive_warmup_steps=round_count * step_count,
        adaptive_warmup_acceptance_rate=_weighted_tuning_acceptance([
            (pair_w, last_pair_acceptance),
            (collective_w, last_collective_acceptance),
            (fourier_w, last_fourier_acceptance),
            (global_w, last_global_acceptance),
            (radial_w, last_radial_acceptance),
        ]),
        adaptive_warmup_pair_acceptance_rate=last_pair_acceptance,
        adaptive_warmup_collective_acceptance_rate=last_collective_acceptance,
        adaptive_warmup_fourier_acceptance_rate=last_fourier_acceptance,
        adaptive_warmup_global_acceptance_rate=last_global_acceptance,
        adaptive_warmup_radial_variance_acceptance_rate=last_radial_acceptance,
    )
end

function _run_arianna_pressure_trace(
    grid::Grid3D,
    params::HEURPParams,
    contract::PressureContract;
    seed=1,
    steps=100,
    sweeps=nothing,
    burn_fraction=0.5,
    sample_stride=1,
    initial_proposal_amplitude=0.01,
    tune_proposal=true,
    target_acceptance=0.44,
    tuning_rounds=8,
    tuning_steps=nothing,
    adaptive_warmup=false,
    adaptive_warmup_rounds=nothing,
    adaptive_warmup_steps=nothing,
    adaptive_warmup_gain=1.0,
    collective_amplitude_scale=0.5,
    collective_pair_count=4,
    collective_move_weight=0.2,
    fourier_amplitude_scale=0.25,
    fourier_max_mode=2,
    fourier_move_weight=0.1,
    global_amplitude_scale=0.1,
    global_move_weight=0.0,
    radial_variance_amplitude_scale=0.1,
    radial_variance_move_weight=0.0,
    stable_mode_proposals=false,
    fourier_min_k2=nothing,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    boundary_barrier_strength=0.0,
    initial_density_mode=:uniform,
    initial_density_amplitude=0.0,
    target_model=:heurp,
)
    basin_cap = _basin_variance_cap(basin_variance_max)
    barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
    lower_bound = _density_lower_bound(phi_min)
    initial_mode = _initial_density_mode_symbol(initial_density_mode)
    model = _direct_target_model_symbol(target_model)
    phi = _initial_density_field(
        StableRNG(seed + 20_000),
        grid;
        initialization=initial_mode,
        initial_density_amplitude=initial_density_amplitude,
        basin_variance_max=basin_cap,
        phi_min=lower_bound,
    )
    initial_variance = var(vec(phi))
    initial_energy = _direct_target_energy(phi, grid, params, model, barrier_strength)
    stable_proposals = Bool(stable_mode_proposals)
    resolved_fourier_min_k2 = _resolved_fourier_min_k2(params;
        stable_mode_proposals=stable_proposals, fourier_min_k2=fourier_min_k2)
    if stable_proposals
        _fourier_mode_candidates([1.0, Float64(fourier_max_mode), resolved_fourier_min_k2], grid)
    end
    proposals_per_sweep = _proposals_per_sweep(grid)
    total_steps = _resolve_steps(grid; steps=steps, sweeps=sweeps)
    burn_fraction_value = Float64(burn_fraction)
    0.0 <= burn_fraction_value < 1.0 || throw(ArgumentError("burn_fraction must be in [0, 1)"))
    stride = Int(sample_stride)
    stride >= 1 || throw(ArgumentError("sample_stride must be at least 1"))
    burn = clamp(floor(Int, total_steps * burn_fraction_value), 0, max(total_steps - 1, 0))
    tune_steps = tuning_steps === nothing ? _default_tuning_steps(burn) : max(1, Int(tuning_steps))
    raw_collective_weight = stable_proposals ? 0.0 : max(0.0, Float64(collective_move_weight))
    raw_fourier_weight = stable_proposals ? 1.0 : max(0.0, Float64(fourier_move_weight))
    raw_global_weight = stable_proposals ? 0.0 : max(0.0, Float64(global_move_weight))
    raw_radial_weight = stable_proposals ? 0.0 : max(0.0, Float64(radial_variance_move_weight))
    nonlocal_weight = raw_collective_weight + raw_fourier_weight + raw_global_weight + raw_radial_weight
    weight_scale = !stable_proposals && nonlocal_weight > 0.95 ? 0.95 / nonlocal_weight : 1.0
    collective_weight = raw_collective_weight * weight_scale
    fourier_weight = stable_proposals ? 1.0 : raw_fourier_weight * weight_scale
    global_weight = raw_global_weight * weight_scale
    radial_weight = raw_radial_weight * weight_scale
    pair_weight = stable_proposals ? 0.0 : 1.0 - collective_weight - fourier_weight - global_weight - radial_weight
    multi_pair_count = max(2, Int(collective_pair_count))
    fourier_mode_count = clamp(max(1, Int(round(fourier_max_mode))), 1, max(1, fld(grid.Nx, 2)))
    pair_tuning = if tune_proposal && pair_weight > 0.0
        _tune_pair_move_amplitude(
            grid,
            params;
            initial_amplitude=initial_proposal_amplitude,
            target_acceptance=target_acceptance,
            rounds=tuning_rounds,
            steps_per_round=tune_steps,
            seed=seed + 10_000,
            basin_variance_max=basin_cap,
            phi_min=lower_bound,
            target_model=model,
            boundary_barrier_strength=barrier_strength,
            initial_phi=phi,
        )
    else
        _fixed_move_tuning(initial_proposal_amplitude, target_acceptance)
    end
    fourier_initial_amplitude = Float64(initial_proposal_amplitude) * Float64(fourier_amplitude_scale)
    fourier_tuning = if tune_proposal && fourier_weight > 0.0
        _tune_fourier_move_amplitude(
            grid,
            params;
            initial_amplitude=fourier_initial_amplitude,
            fourier_max_mode=fourier_max_mode,
            fourier_min_k2=resolved_fourier_min_k2,
            target_acceptance=target_acceptance,
            rounds=tuning_rounds,
            steps_per_round=tune_steps,
            seed=seed + 10_000,
            basin_variance_max=basin_cap,
            phi_min=lower_bound,
            target_model=model,
            boundary_barrier_strength=barrier_strength,
            initial_phi=phi,
        )
    else
        _fixed_move_tuning(fourier_initial_amplitude, target_acceptance)
    end
    tuning_acceptance = _weighted_tuning_acceptance([
        (pair_weight + collective_weight, pair_tuning.tuning_acceptance_rate),
        (fourier_weight, fourier_tuning.tuning_acceptance_rate),
    ])
    tuning_round_count = max(pair_tuning.tuning_rounds, fourier_tuning.tuning_rounds)
    pair_amplitude = max(pair_tuning.amplitude, eps(Float64))
    fourier_amplitude = max(fourier_tuning.amplitude, eps(Float64))
    global_amplitude = max(Float64(initial_proposal_amplitude) * Float64(global_amplitude_scale), eps(Float64))
    radial_amplitude = max(Float64(initial_proposal_amplitude) * Float64(radial_variance_amplitude_scale), eps(Float64))
    adaptive_round_count = Bool(adaptive_warmup) ?
                           (adaptive_warmup_rounds === nothing ?
                            max(1, Int(tuning_rounds)) :
                            max(1, Int(adaptive_warmup_rounds))) :
                           0
    adaptive_steps_per_round = adaptive_warmup_steps === nothing ? tune_steps :
                               max(1, Int(adaptive_warmup_steps))
    warmup = _adaptive_warmup_density_field!(
        phi,
        grid,
        params;
        pair_amplitude=pair_amplitude,
        fourier_amplitude=fourier_amplitude,
        pair_weight=pair_weight,
        collective_amplitude_scale=collective_amplitude_scale,
        collective_pair_count=multi_pair_count,
        collective_weight=collective_weight,
        fourier_weight=fourier_weight,
        global_amplitude=global_amplitude,
        global_weight=global_weight,
        radial_variance_amplitude=radial_amplitude,
        radial_variance_weight=radial_weight,
        fourier_max_mode=fourier_mode_count,
        fourier_min_k2=resolved_fourier_min_k2,
        stable_mode_proposals=stable_proposals,
        rounds=adaptive_round_count,
        steps_per_round=adaptive_steps_per_round,
        target_acceptance=target_acceptance,
        gain=adaptive_warmup_gain,
        seed=seed + 30_000,
        basin_variance_max=basin_cap,
        phi_min=lower_bound,
        target_model=model,
        boundary_barrier_strength=barrier_strength,
    )
    pair_amplitude = max(warmup.pair_proposal_amplitude, eps(Float64))
    fourier_amplitude = max(warmup.fourier_mode_amplitude, eps(Float64))
    global_amplitude = max(warmup.global_field_amplitude, eps(Float64))
    radial_amplitude = max(warmup.radial_variance_amplitude, eps(Float64))
    chain = DensityFieldSystem(phi, grid, params; pressure_contract=contract,
        basin_variance_max=basin_cap, phi_min=lower_bound, target_model=model,
        boundary_barrier_strength=barrier_strength)
    collective_amplitude = max(pair_amplitude * Float64(collective_amplitude_scale) / sqrt(multi_pair_count), eps(Float64))
    fourier_parameters = [fourier_amplitude, Float64(fourier_mode_count), resolved_fourier_min_k2]
    pool = if stable_proposals
        (Arianna.Move(FourierModeDensityAction(0, 0, 0, 0.0, 0.0),
            FourierModeDensityPolicy(), fourier_parameters, 1.0),)
    else
        base_pool = (
            Arianna.Move(PairDensityAction(1, 2, 0.0), PairDensityPolicy(), [pair_amplitude], pair_weight),
            Arianna.Move(MultiPairDensityAction(Int[], Int[], Float64[]), MultiPairDensityPolicy(),
                [collective_amplitude, Float64(multi_pair_count)], collective_weight),
            Arianna.Move(FourierModeDensityAction(0, 0, 0, 0.0, 0.0),
                FourierModeDensityPolicy(), fourier_parameters, fourier_weight),
            Arianna.Move(RadialVarianceDensityAction(0.0),
                RadialVarianceDensityPolicy(), [radial_amplitude], radial_weight),
        )
        global_weight > 0.0 ?
            (base_pool..., Arianna.Move(GlobalGaussianDensityAction(zeros(size(phi))),
                GlobalGaussianDensityPolicy(), [global_amplitude], global_weight)) :
            base_pool
    end
    schedule = Arianna.build_schedule(total_steps, burn, stride)
    path = mktempdir()
    algorithms = (
        (algorithm=Arianna.Metropolis, pool=pool, seed=seed, parallel=false),
        (algorithm=Arianna.StoreCallbacks, callbacks=(field_energy, density_variance, low_mode_structure_factor, field_pressure),
            store_first=false, scheduler=schedule),
        (algorithm=Arianna.StoreAcceptance, dependencies=(Arianna.Metropolis,), scheduler=schedule),
    )
    simulation = Arianna.Simulation([chain], algorithms, total_steps; path=path, verbose=false)
    Arianna.run!(simulation)

    pressure_path = joinpath(path, "chains", "1", "field_pressure.dat")
    energy_path = joinpath(path, "chains", "1", "field_energy.dat")
    variance_path = joinpath(path, "chains", "1", "density_variance.dat")
    structure_path = joinpath(path, "chains", "1", "low_mode_structure_factor.dat")
    pressure_rows = isfile(pressure_path) ? readdlm(pressure_path) : zeros(0, 2)
    energy_rows = isfile(energy_path) ? readdlm(energy_path) : zeros(0, 2)
    variance_rows = isfile(variance_path) ? readdlm(variance_path) : zeros(0, 2)
    structure_rows = isfile(structure_path) ? readdlm(structure_path) : zeros(0, 2)
    pressure_trace = Float64[pressure_rows[i, 2] for i in 1:size(pressure_rows, 1) if isfinite(pressure_rows[i, 2])]
    energy_trace = Float64[energy_rows[i, 2] for i in 1:size(energy_rows, 1) if isfinite(energy_rows[i, 2])]
    variance_trace = Float64[variance_rows[i, 2] for i in 1:size(variance_rows, 1) if isfinite(variance_rows[i, 2])]
    structure_trace = Float64[structure_rows[i, 2] for i in 1:size(structure_rows, 1) if isfinite(structure_rows[i, 2])]
    isempty(pressure_trace) && push!(pressure_trace, _direct_target_pressure(chain.phi, grid, params, contract, model))
    isempty(energy_trace) && push!(energy_trace, chain.energy)
    isempty(variance_trace) && push!(variance_trace, var(vec(chain.phi)))
    isempty(structure_trace) && push!(structure_trace, low_mode_structure_factor(chain.phi))
    accepted = 0
    total = 0
    metropolis_pool = simulation.algorithms[1].pools[1]
    pair_acceptance = NaN
    collective_acceptance = NaN
    fourier_acceptance = NaN
    global_acceptance = NaN
    radial_acceptance = NaN
    for (move_idx, move) in enumerate(metropolis_pool)
        accepted += move.accepted_calls
        total += move.total_calls
        if stable_proposals
            fourier_acceptance = _move_acceptance(move)
        elseif move_idx == 1
            pair_acceptance = _move_acceptance(move)
        elseif move_idx == 2
            collective_acceptance = _move_acceptance(move)
        elseif move_idx == 3
            fourier_acceptance = _move_acceptance(move)
        elseif move_idx == 4
            radial_acceptance = _move_acceptance(move)
        elseif move_idx == 5
            global_acceptance = _move_acceptance(move)
        end
    end
    final_energy = size(energy_rows, 1) == 0 ? chain.energy : Float64(energy_rows[end, 2])
    final_variance = size(variance_rows, 1) == 0 ? var(vec(chain.phi)) : Float64(variance_rows[end, 2])
    final_structure = size(structure_rows, 1) == 0 ? low_mode_structure_factor(chain.phi) :
                      Float64(structure_rows[end, 2])
    basin_pass = final_variance <= basin_cap + 1.0e-14 ? 1.0 : 0.0
    return (
        pressure_trace=pressure_trace,
        energy_trace=energy_trace,
        density_variance_trace=variance_trace,
        low_mode_structure_trace=structure_trace,
        acceptance=accepted / max(total, 1),
        final_energy=final_energy,
        density_variance=final_variance,
        basin_variance_max=basin_cap,
        phi_min=lower_bound,
        basin_constraint_pass=basin_pass,
        low_mode_structure_factor=final_structure,
        pair_acceptance_rate=pair_acceptance,
        collective_acceptance_rate=collective_acceptance,
        fourier_acceptance_rate=fourier_acceptance,
        global_acceptance_rate=global_acceptance,
        radial_variance_acceptance_rate=radial_acceptance,
        initial_density_overdispersed=initial_mode == :overdispersed ? 1.0 : 0.0,
        initial_density_amplitude=Float64(initial_density_amplitude),
        initial_density_variance=initial_variance,
        initial_energy=initial_energy,
        equilibration_steps=burn,
        burn_fraction=burn_fraction_value,
        sample_stride=stride,
        total_steps=total_steps,
        trace_samples=length(pressure_trace),
        proposals_per_sweep=proposals_per_sweep,
        production_sweeps=_sweeps_from_steps(grid, total_steps),
        equilibration_sweeps=_sweeps_from_steps(grid, burn),
        sample_stride_sweeps=_sweeps_from_steps(grid, stride),
        proposal_amplitude=stable_proposals ? fourier_amplitude : pair_amplitude,
        pair_proposal_amplitude=pair_amplitude,
        pair_move_weight=pair_weight,
        pair_tuning_acceptance_rate=pair_tuning.tuning_acceptance_rate,
        target_acceptance=max(pair_tuning.target_acceptance, fourier_tuning.target_acceptance),
        tuning_rounds=tuning_round_count,
        tuning_steps=tune_steps,
        tuning_acceptance_rate=tuning_acceptance,
        adaptive_warmup_rounds=warmup.adaptive_warmup_rounds,
        adaptive_warmup_steps=warmup.adaptive_warmup_steps,
        adaptive_warmup_acceptance_rate=warmup.adaptive_warmup_acceptance_rate,
        adaptive_warmup_pair_acceptance_rate=warmup.adaptive_warmup_pair_acceptance_rate,
        adaptive_warmup_collective_acceptance_rate=warmup.adaptive_warmup_collective_acceptance_rate,
        adaptive_warmup_fourier_acceptance_rate=warmup.adaptive_warmup_fourier_acceptance_rate,
        adaptive_warmup_global_acceptance_rate=warmup.adaptive_warmup_global_acceptance_rate,
        adaptive_warmup_radial_variance_acceptance_rate=warmup.adaptive_warmup_radial_variance_acceptance_rate,
        collective_proposal_amplitude=collective_amplitude,
        collective_pair_count=multi_pair_count,
        collective_move_weight=collective_weight,
        fourier_mode_amplitude=fourier_amplitude,
        fourier_max_mode=fourier_mode_count,
        fourier_move_weight=fourier_weight,
        fourier_tuning_acceptance_rate=fourier_tuning.tuning_acceptance_rate,
        global_field_amplitude=global_amplitude,
        global_move_weight=global_weight,
        radial_variance_amplitude=radial_amplitude,
        radial_variance_move_weight=radial_weight,
        stable_mode_proposals=stable_proposals ? 1.0 : 0.0,
        fourier_min_k2=resolved_fourier_min_k2,
        boundary_barrier_strength=barrier_strength,
        alpha=params.alpha,
        target_model_code=_direct_target_model_code(model),
        sampler="arianna",
    )
end

function _run_arianna_pressure_trace_until_ess(
    grid::Grid3D,
    params::HEURPParams,
    contract::PressureContract;
    seed=1,
    steps=100,
    sweeps=nothing,
    ess_target=4.0,
    max_steps=nothing,
    max_sweeps=nothing,
    step_growth=2.0,
    min_trace_samples=1,
    pressure_tolerance=Inf,
    equilibration_sensitivity_threshold=3.0,
    kwargs...,
)
    first_steps = _resolve_steps(grid; steps=steps, sweeps=sweeps)
    max_production_steps = if max_sweeps !== nothing
        max(first_steps, _steps_from_sweeps(grid, max_sweeps))
    elseif max_steps === nothing
        first_steps
    else
        max(first_steps, Int(max_steps))
    end
    target_ess = max(0.0, Float64(ess_target))
    target_min_trace = max(1, Int(ceil(Float64(min_trace_samples))))
    tolerance = Float64(pressure_tolerance)
    tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    growth = max(1.1, Float64(step_growth))
    current_steps = first_steps
    attempts = 0
    last_sample = nothing
    last_summary = nothing

    while true
        attempts += 1
        sample = _run_arianna_pressure_trace(
            grid,
            params,
            contract;
            seed=seed + 100_000 * (attempts - 1),
            steps=current_steps,
            kwargs...,
        )
        summary = batch_summary(sample.pressure_trace)
        last_sample = sample
        last_summary = summary
        ess_ok = target_ess == 0.0 || summary.effective_sample_size >= target_ess
        trace_ok = _trace_samples_pass(summary, target_min_trace) >= 0.5
        error_ok = _pressure_error_pass(summary, tolerance) >= 0.5
        if (ess_ok && trace_ok && error_ok) || current_steps >= max_production_steps
            break
        end
        next_steps = min(max_production_steps, max(current_steps + 1, ceil(Int, current_steps * growth)))
        next_steps == current_steps && break
        current_steps = next_steps
    end

    ess_ok = target_ess == 0.0 || last_summary.effective_sample_size >= target_ess
    trace_pass = _trace_samples_pass(last_summary, target_min_trace)
    pressure_error_pass = _pressure_error_pass(last_summary, tolerance)
    sampling_budget = _sampling_budget_estimate(
        last_summary;
        production_steps=last_sample.total_steps,
        proposals_per_sweep=last_sample.proposals_per_sweep,
        burn_fraction=last_sample.burn_fraction,
        sample_stride=last_sample.sample_stride,
        ess_target=target_ess,
        min_trace_samples=target_min_trace,
        pressure_tolerance=tolerance,
    )
    decorrelation = _decorrelation_diagnostics(
        last_summary;
        sample_stride=last_sample.sample_stride,
        production_steps=last_sample.total_steps,
        equilibration_steps=last_sample.equilibration_steps,
        required_effective_sample_size=sampling_budget.required_effective_sample_size,
    )
    equilibration = _equilibration_sensitivity_diagnostics(
        last_sample.pressure_trace,
        last_summary;
        threshold=equilibration_sensitivity_threshold,
    )
    observable_stationarity = _observable_stationarity_diagnostics(
        last_sample;
        threshold=equilibration_sensitivity_threshold,
    )
    converged = ess_ok && trace_pass >= 0.5 && pressure_error_pass >= 0.5 &&
                decorrelation.decorrelation_pass >= 0.5 &&
                equilibration.equilibration_sensitivity_pass >= 0.5 &&
                observable_stationarity.observable_stationarity_pass >= 0.5 ? 1.0 : 0.0
    sample_with_convergence = merge(
        last_sample,
        (
            ess_target=target_ess,
            converged=converged,
            min_trace_samples=target_min_trace,
            trace_samples_pass=trace_pass,
            pressure_tolerance=tolerance,
            pressure_error_pass=pressure_error_pass,
            pressure_target_effective_sample_size=sampling_budget.pressure_target_effective_sample_size,
            required_effective_sample_size=sampling_budget.required_effective_sample_size,
            required_trace_samples=sampling_budget.required_trace_samples,
            estimated_required_steps=sampling_budget.estimated_required_steps,
            estimated_required_sweeps=sampling_budget.estimated_required_sweeps,
            production_budget_shortfall=sampling_budget.production_budget_shortfall,
            sampling_budget_pass=sampling_budget.sampling_budget_pass,
            decorrelation_stride_samples=decorrelation.decorrelation_stride_samples,
            decorrelation_stride_steps=decorrelation.decorrelation_stride_steps,
            decorrelated_sample_count=decorrelation.decorrelated_sample_count,
            equilibration_autocorrelation_windows=decorrelation.equilibration_autocorrelation_windows,
            production_autocorrelation_windows=decorrelation.production_autocorrelation_windows,
            decorrelation_pass=decorrelation.decorrelation_pass,
            equilibration_tail_fraction=equilibration.equilibration_tail_fraction,
            equilibration_tail_sample_count=equilibration.equilibration_tail_sample_count,
            equilibration_head_mean=equilibration.equilibration_head_mean,
            equilibration_tail_mean=equilibration.equilibration_tail_mean,
            equilibration_tail_stderr=equilibration.equilibration_tail_stderr,
            equilibration_sensitivity_zscore=equilibration.equilibration_sensitivity_zscore,
            equilibration_sensitivity_threshold=equilibration.equilibration_sensitivity_threshold,
            equilibration_sensitivity_pass=equilibration.equilibration_sensitivity_pass,
            energy_drift_zscore=observable_stationarity.energy_drift_zscore,
            density_variance_drift_zscore=observable_stationarity.density_variance_drift_zscore,
            low_mode_structure_drift_zscore=observable_stationarity.low_mode_structure_drift_zscore,
            max_observable_drift_zscore=observable_stationarity.max_observable_drift_zscore,
            observable_stationarity_pass=observable_stationarity.observable_stationarity_pass,
            production_steps=last_sample.total_steps,
            max_production_steps=max_production_steps,
            production_sweeps=_sweeps_from_steps(grid, last_sample.total_steps),
            max_production_sweeps=_sweeps_from_steps(grid, max_production_steps),
            convergence_attempts=attempts,
        ),
    )
    return sample_with_convergence, last_summary
end

function _combine_replicated_pressure_samples(samples, summaries)
    chain_count = length(samples)
    chain_count >= 1 || throw(ArgumentError("at least one chain is required"))
    traces = [sample.pressure_trace for sample in samples]
    combined_trace = reduce(vcat, traces)
    combined_energy_trace = reduce(vcat, [sample.energy_trace for sample in samples])
    combined_variance_trace = reduce(vcat, [sample.density_variance_trace for sample in samples])
    combined_structure_trace = reduce(vcat, [sample.low_mode_structure_trace for sample in samples])
    pooled = batch_summary(combined_trace)
    chain_means = [summary.mean for summary in summaries]
    between_stderr = chain_count <= 1 ? 0.0 : std(chain_means; corrected=true) / sqrt(chain_count)
    within_stderr = sqrt(sum(summary.stderr^2 for summary in summaries)) / chain_count
    rhat = _chain_rhat(traces)
    split_rhat = _split_chain_rhat(traces)
    chain_mean = mean(chain_means)
    combined_summary = (
        mean=chain_mean,
        stderr=max(pooled.stderr, between_stderr, within_stderr),
        independent_stderr=max(pooled.independent_stderr, between_stderr),
        integrated_autocorrelation_time=maximum(summary.integrated_autocorrelation_time for summary in summaries),
        effective_sample_size=sum(summary.effective_sample_size for summary in summaries),
        trace_drift_zscore=_combined_chain_trace_drift_zscore(summaries),
        n=sum(summary.n for summary in summaries),
        chain_between_stderr=between_stderr,
        chain_within_stderr=within_stderr,
        chain_rhat=rhat,
        split_chain_rhat=split_rhat,
    )
    converged_count = count(sample -> sample.converged >= 0.5, samples)
    min_trace_samples = maximum(sample.min_trace_samples for sample in samples)
    trace_samples_pass = all(sample.trace_samples_pass >= 0.5 for sample in samples) ? 1.0 : 0.0
    pressure_tolerance = maximum(sample.pressure_tolerance for sample in samples)
    pressure_error_pass = _pressure_error_pass(combined_summary, pressure_tolerance)
    sampling_budget = _sampling_budget_estimate(
        combined_summary;
        production_steps=maximum(sample.production_steps for sample in samples),
        proposals_per_sweep=maximum(sample.proposals_per_sweep for sample in samples),
        burn_fraction=maximum(sample.burn_fraction for sample in samples),
        sample_stride=maximum(sample.sample_stride for sample in samples),
        ess_target=maximum(sample.ess_target for sample in samples),
        min_trace_samples=min_trace_samples,
        pressure_tolerance=pressure_tolerance,
        chain_count=chain_count,
    )
    decorrelation = _decorrelation_diagnostics(
        combined_summary;
        sample_stride=maximum(sample.sample_stride for sample in samples),
        production_steps=maximum(sample.production_steps for sample in samples),
        equilibration_steps=maximum(sample.equilibration_steps for sample in samples),
        required_effective_sample_size=sampling_budget.required_effective_sample_size,
    )
    equilibration = _combine_equilibration_sensitivity_diagnostics(samples)
    observable_stationarity = _combine_observable_stationarity_diagnostics(samples)
    combined_sample = merge(
        samples[1],
        (
            pressure_trace=combined_trace,
            energy_trace=combined_energy_trace,
            density_variance_trace=combined_variance_trace,
            low_mode_structure_trace=combined_structure_trace,
            acceptance=mean(sample.acceptance for sample in samples),
            final_energy=mean(sample.final_energy for sample in samples),
            density_variance=mean(sample.density_variance for sample in samples),
            basin_variance_max=maximum(sample.basin_variance_max for sample in samples),
            basin_constraint_pass=minimum(sample.basin_constraint_pass for sample in samples),
            low_mode_structure_factor=mean(sample.low_mode_structure_factor for sample in samples),
            pair_acceptance_rate=_mean_finite(sample.pair_acceptance_rate for sample in samples),
            collective_acceptance_rate=_mean_finite(sample.collective_acceptance_rate for sample in samples),
            fourier_acceptance_rate=_mean_finite(sample.fourier_acceptance_rate for sample in samples),
            global_acceptance_rate=_mean_finite(sample.global_acceptance_rate for sample in samples),
            radial_variance_acceptance_rate=_mean_finite(sample.radial_variance_acceptance_rate for sample in samples),
            initial_density_overdispersed=maximum(sample.initial_density_overdispersed for sample in samples),
            initial_density_amplitude=maximum(sample.initial_density_amplitude for sample in samples),
            initial_density_variance=maximum(sample.initial_density_variance for sample in samples),
            initial_energy=mean(sample.initial_energy for sample in samples),
            equilibration_steps=maximum(sample.equilibration_steps for sample in samples),
            burn_fraction=maximum(sample.burn_fraction for sample in samples),
            sample_stride=maximum(sample.sample_stride for sample in samples),
            total_steps=maximum(sample.total_steps for sample in samples),
            trace_samples=length(combined_trace),
            proposals_per_sweep=maximum(sample.proposals_per_sweep for sample in samples),
            production_sweeps=maximum(sample.production_sweeps for sample in samples),
            max_production_sweeps=maximum(sample.max_production_sweeps for sample in samples),
            equilibration_sweeps=maximum(sample.equilibration_sweeps for sample in samples),
            sample_stride_sweeps=maximum(sample.sample_stride_sweeps for sample in samples),
            proposal_amplitude=mean(sample.proposal_amplitude for sample in samples),
            pair_proposal_amplitude=mean(sample.pair_proposal_amplitude for sample in samples),
            pair_move_weight=mean(sample.pair_move_weight for sample in samples),
            pair_tuning_acceptance_rate=_mean_finite(sample.pair_tuning_acceptance_rate for sample in samples),
            target_acceptance=maximum(sample.target_acceptance for sample in samples),
            tuning_rounds=maximum(sample.tuning_rounds for sample in samples),
            tuning_steps=maximum(sample.tuning_steps for sample in samples),
            tuning_acceptance_rate=_mean_finite(sample.tuning_acceptance_rate for sample in samples),
            adaptive_warmup_rounds=maximum(sample.adaptive_warmup_rounds for sample in samples),
            adaptive_warmup_steps=maximum(sample.adaptive_warmup_steps for sample in samples),
            adaptive_warmup_acceptance_rate=_mean_finite(sample.adaptive_warmup_acceptance_rate for sample in samples),
            adaptive_warmup_pair_acceptance_rate=_mean_finite(sample.adaptive_warmup_pair_acceptance_rate for sample in samples),
            adaptive_warmup_collective_acceptance_rate=_mean_finite(sample.adaptive_warmup_collective_acceptance_rate for sample in samples),
            adaptive_warmup_fourier_acceptance_rate=_mean_finite(sample.adaptive_warmup_fourier_acceptance_rate for sample in samples),
            adaptive_warmup_global_acceptance_rate=_mean_finite(sample.adaptive_warmup_global_acceptance_rate for sample in samples),
            adaptive_warmup_radial_variance_acceptance_rate=_mean_finite(sample.adaptive_warmup_radial_variance_acceptance_rate for sample in samples),
            collective_proposal_amplitude=mean(sample.collective_proposal_amplitude for sample in samples),
            collective_pair_count=maximum(sample.collective_pair_count for sample in samples),
            collective_move_weight=mean(sample.collective_move_weight for sample in samples),
            fourier_mode_amplitude=mean(sample.fourier_mode_amplitude for sample in samples),
            fourier_max_mode=maximum(sample.fourier_max_mode for sample in samples),
            fourier_move_weight=mean(sample.fourier_move_weight for sample in samples),
            fourier_tuning_acceptance_rate=_mean_finite(sample.fourier_tuning_acceptance_rate for sample in samples),
            global_field_amplitude=mean(sample.global_field_amplitude for sample in samples),
            global_move_weight=mean(sample.global_move_weight for sample in samples),
            radial_variance_amplitude=mean(sample.radial_variance_amplitude for sample in samples),
            radial_variance_move_weight=mean(sample.radial_variance_move_weight for sample in samples),
            stable_mode_proposals=maximum(sample.stable_mode_proposals for sample in samples),
            fourier_min_k2=maximum(sample.fourier_min_k2 for sample in samples),
            boundary_barrier_strength=maximum(sample.boundary_barrier_strength for sample in samples),
            ess_target=maximum(sample.ess_target for sample in samples),
            converged=converged_count == chain_count &&
                      observable_stationarity.observable_stationarity_pass >= 0.5 ? 1.0 : 0.0,
            min_trace_samples=min_trace_samples,
            trace_samples_pass=trace_samples_pass,
            pressure_tolerance=pressure_tolerance,
            pressure_error_pass=pressure_error_pass,
            pressure_target_effective_sample_size=sampling_budget.pressure_target_effective_sample_size,
            required_effective_sample_size=sampling_budget.required_effective_sample_size,
            required_trace_samples=sampling_budget.required_trace_samples,
            estimated_required_steps=sampling_budget.estimated_required_steps,
            estimated_required_sweeps=sampling_budget.estimated_required_sweeps,
            production_budget_shortfall=sampling_budget.production_budget_shortfall,
            sampling_budget_pass=sampling_budget.sampling_budget_pass,
            decorrelation_stride_samples=decorrelation.decorrelation_stride_samples,
            decorrelation_stride_steps=decorrelation.decorrelation_stride_steps,
            decorrelated_sample_count=decorrelation.decorrelated_sample_count,
            equilibration_autocorrelation_windows=decorrelation.equilibration_autocorrelation_windows,
            production_autocorrelation_windows=decorrelation.production_autocorrelation_windows,
            decorrelation_pass=decorrelation.decorrelation_pass,
            equilibration_tail_fraction=equilibration.equilibration_tail_fraction,
            equilibration_tail_sample_count=equilibration.equilibration_tail_sample_count,
            equilibration_head_mean=equilibration.equilibration_head_mean,
            equilibration_tail_mean=equilibration.equilibration_tail_mean,
            equilibration_tail_stderr=equilibration.equilibration_tail_stderr,
            equilibration_sensitivity_zscore=equilibration.equilibration_sensitivity_zscore,
            equilibration_sensitivity_threshold=equilibration.equilibration_sensitivity_threshold,
            equilibration_sensitivity_pass=equilibration.equilibration_sensitivity_pass,
            energy_drift_zscore=observable_stationarity.energy_drift_zscore,
            density_variance_drift_zscore=observable_stationarity.density_variance_drift_zscore,
            low_mode_structure_drift_zscore=observable_stationarity.low_mode_structure_drift_zscore,
            max_observable_drift_zscore=observable_stationarity.max_observable_drift_zscore,
            observable_stationarity_pass=observable_stationarity.observable_stationarity_pass,
            production_steps=maximum(sample.production_steps for sample in samples),
            max_production_steps=maximum(sample.max_production_steps for sample in samples),
            convergence_attempts=maximum(sample.convergence_attempts for sample in samples),
            alpha=mean(sample.alpha for sample in samples),
            target_model_code=maximum(sample.target_model_code for sample in samples),
            chain_count=chain_count,
            chains_converged=converged_count,
            chain_rhat=rhat,
            split_chain_rhat=split_rhat,
            chain_between_stderr=between_stderr,
            chain_within_stderr=within_stderr,
            sampler="arianna",
        ),
    )
    return combined_sample, combined_summary
end

