function _append_pressure_trace_rows(
    path::AbstractString,
    C::Real,
    chain_idx::Integer,
    pressure_trace::AbstractVector{<:Real},
)
    mkpath(dirname(path))
    write_header = !isfile(path) || filesize(path) == 0
    open(path, "a") do io
        write_header && println(io, join(PRESSURE_TRACE_HEADER, ","))
        for (sample_idx, pressure) in enumerate(pressure_trace)
            isfinite(Float64(pressure)) || continue
            println(io, join((Float64(C), Int(chain_idx), Int(sample_idx), Float64(pressure)), ","))
        end
    end
    return path
end

function _append_observable_trace_rows(
    path::AbstractString,
    C::Real,
    chain_idx::Integer,
    sample,
)
    mkpath(dirname(path))
    write_header = !isfile(path) || filesize(path) == 0
    count = minimum((
        length(sample.pressure_trace),
        length(sample.energy_trace),
        length(sample.density_variance_trace),
        length(sample.low_mode_structure_trace),
    ))
    open(path, "a") do io
        write_header && println(io, join(OBSERVABLE_TRACE_HEADER, ","))
        for sample_idx in 1:count
            pressure = Float64(sample.pressure_trace[sample_idx])
            energy = Float64(sample.energy_trace[sample_idx])
            variance = Float64(sample.density_variance_trace[sample_idx])
            structure = Float64(sample.low_mode_structure_trace[sample_idx])
            all(isfinite, (pressure, energy, variance, structure)) || continue
            println(io, join((
                Float64(C),
                Int(chain_idx),
                Int(sample_idx),
                pressure,
                energy,
                variance,
                structure,
            ), ","))
        end
    end
    return path
end

