function _pressure_trace_groups(path::AbstractString)
    isfile(path) || throw(ArgumentError("pressure trace CSV not found: $path"))
    header, rows = _read_csv_strings(path)
    header == PRESSURE_TRACE_HEADER ||
        throw(ArgumentError("unsupported pressure trace header in $path"))
    c_idx = findfirst(==("C"), header)
    chain_idx = findfirst(==("chain"), header)
    sample_idx = findfirst(==("sample_index"), header)
    pressure_idx = findfirst(==("pressure"), header)
    grouped = Dict{Float64,Dict{Int,Vector{Tuple{Int,Float64}}}}()
    for row in rows
        length(row) >= length(PRESSURE_TRACE_HEADER) || continue
        C = parse(Float64, row[c_idx])
        chain = parse(Int, row[chain_idx])
        sample = parse(Int, row[sample_idx])
        pressure = parse(Float64, row[pressure_idx])
        isfinite(pressure) || continue
        chains = get!(grouped, C, Dict{Int,Vector{Tuple{Int,Float64}}}())
        values = get!(chains, chain, Tuple{Int,Float64}[])
        push!(values, (sample, pressure))
    end
    traces = Dict{Float64,Dict{Int,Vector{Float64}}}()
    for (C, chains) in grouped
        trace_chains = Dict{Int,Vector{Float64}}()
        for (chain, values) in chains
            sort!(values; by=first)
            trace_chains[chain] = [pressure for (_, pressure) in values]
        end
        traces[C] = trace_chains
    end
    return traces
end

function _row_value(header, row, name::AbstractString)
    idx = findfirst(==(name), header)
    idx === nothing && throw(ArgumentError("missing column `$name`"))
    length(row) >= idx || throw(ArgumentError("row is missing column `$name`"))
    parsed = tryparse(Float64, row[idx])
    parsed === nothing && throw(ArgumentError("column `$name` is not numeric"))
    return parsed
end

function _row_value_or(header, row, name::AbstractString, default::Real)
    idx = findfirst(==(name), header)
    idx === nothing && return Float64(default)
    length(row) >= idx && !isempty(row[idx]) || return Float64(default)
    parsed = tryparse(Float64, row[idx])
    return parsed === nothing ? Float64(default) : parsed
end

function _chain_diagnostic_groups(path::AbstractString)
    isfile(path) || return Dict{Float64,Dict{Int,Vector{String}}}()
    header, rows = _read_csv_strings(path)
    ("C" in header && "chain" in header) ||
        throw(ArgumentError("unsupported pressure chain diagnostic header in $path"))
    c_idx = findfirst(==("C"), header)
    chain_idx = findfirst(==("chain"), header)
    grouped = Dict{Float64,Dict{Int,Vector{String}}}()
    for row in rows
        length(row) >= max(c_idx, chain_idx) || continue
        C = parse(Float64, row[c_idx])
        chain = parse(Int, row[chain_idx])
        chains = get!(grouped, C, Dict{Int,Vector{String}}())
        chains[chain] = row
    end
    return (header=header, rows=grouped)
end

function _observable_trace_groups(path::AbstractString)
    isfile(path) || return Dict{Float64,Dict{Int,Any}}()
    header, rows = _read_csv_strings(path)
    header == OBSERVABLE_TRACE_HEADER ||
        throw(ArgumentError("unsupported observable trace header in $path"))
    c_idx = findfirst(==("C"), header)
    chain_idx = findfirst(==("chain"), header)
    sample_idx = findfirst(==("sample_index"), header)
    pressure_idx = findfirst(==("pressure"), header)
    energy_idx = findfirst(==("energy"), header)
    variance_idx = findfirst(==("density_variance"), header)
    structure_idx = findfirst(==("low_mode_structure_factor"), header)
    grouped = Dict{Float64,Dict{Int,Vector{Tuple{Int,Float64,Float64,Float64,Float64}}}}()
    for row in rows
        length(row) >= length(OBSERVABLE_TRACE_HEADER) || continue
        C = parse(Float64, row[c_idx])
        chain = parse(Int, row[chain_idx])
        sample = parse(Int, row[sample_idx])
        pressure = parse(Float64, row[pressure_idx])
        energy = parse(Float64, row[energy_idx])
        variance = parse(Float64, row[variance_idx])
        structure = parse(Float64, row[structure_idx])
        all(isfinite, (pressure, energy, variance, structure)) || continue
        chains = get!(grouped, C, Dict{Int,Vector{Tuple{Int,Float64,Float64,Float64,Float64}}}())
        values = get!(chains, chain, Tuple{Int,Float64,Float64,Float64,Float64}[])
        push!(values, (sample, pressure, energy, variance, structure))
    end
    traces = Dict{Float64,Dict{Int,Any}}()
    for (C, chains) in grouped
        trace_chains = Dict{Int,Any}()
        for (chain, values) in chains
            sort!(values; by=first)
            trace_chains[chain] = (
                pressure=Float64[value[2] for value in values],
                energy=Float64[value[3] for value in values],
                density_variance=Float64[value[4] for value in values],
                low_mode_structure=Float64[value[5] for value in values],
            )
        end
        traces[C] = trace_chains
    end
    return traces
end

function _sample_from_chain_diagnostic(
    header,
    row,
    pressure_trace::AbstractVector{<:Real},
)
    trace = Float64.(pressure_trace)
    sampler_idx = findfirst(==("sampler"), header)
    sampler_value = sampler_idx === nothing || length(row) < sampler_idx ? "arianna" : row[sampler_idx]
    fallback_summary = batch_summary(trace)
    fallback_decorrelation = _decorrelation_diagnostics(
        fallback_summary;
        sample_stride=_row_value(header, row, "sample_stride"),
        production_steps=_row_value(header, row, "production_steps"),
        equilibration_steps=_row_value(header, row, "equilibration_steps"),
        required_effective_sample_size=_row_value(header, row, "required_effective_sample_size"),
    )
    fallback_equilibration = _equilibration_sensitivity_diagnostics(
        trace,
        fallback_summary;
        threshold=_row_value_or(header, row, "equilibration_sensitivity_threshold", 3.0),
    )
    return (
        pressure_trace=trace,
        energy_trace=Float64[],
        density_variance_trace=Float64[],
        low_mode_structure_trace=Float64[],
        acceptance=_row_value(header, row, "acceptance_rate"),
        final_energy=_row_value(header, row, "final_energy"),
        density_variance=_row_value(header, row, "density_variance"),
        basin_variance_max=_row_value(header, row, "basin_variance_max"),
        phi_min=_row_value(header, row, "phi_min"),
        boundary_barrier_strength=_row_value_or(header, row, "boundary_barrier_strength", 0.0),
        basin_constraint_pass=_row_value(header, row, "basin_constraint_pass"),
        low_mode_structure_factor=_row_value(header, row, "low_mode_structure_factor"),
        pair_acceptance_rate=_row_value_or(header, row, "pair_acceptance_rate", NaN),
        collective_acceptance_rate=_row_value_or(header, row, "collective_acceptance_rate", NaN),
        fourier_acceptance_rate=_row_value_or(header, row, "fourier_acceptance_rate", NaN),
        global_acceptance_rate=_row_value_or(header, row, "global_acceptance_rate", NaN),
        radial_variance_acceptance_rate=_row_value_or(header, row, "radial_variance_acceptance_rate", NaN),
        initial_density_overdispersed=_row_value_or(header, row, "initial_density_overdispersed", 0.0),
        initial_density_amplitude=_row_value_or(header, row, "initial_density_amplitude", 0.0),
        initial_density_variance=_row_value_or(header, row, "initial_density_variance", 0.0),
        initial_energy=_row_value_or(header, row, "initial_energy", _row_value(header, row, "final_energy")),
        equilibration_steps=_row_value(header, row, "equilibration_steps"),
        burn_fraction=_row_value(header, row, "burn_fraction"),
        sample_stride=_row_value(header, row, "sample_stride"),
        total_steps=_row_value(header, row, "total_steps"),
        trace_samples=length(trace),
        proposals_per_sweep=_row_value(header, row, "proposals_per_sweep"),
        production_sweeps=_row_value(header, row, "production_sweeps"),
        max_production_sweeps=_row_value(header, row, "max_production_sweeps"),
        equilibration_sweeps=_row_value(header, row, "equilibration_sweeps"),
        sample_stride_sweeps=_row_value(header, row, "sample_stride_sweeps"),
        proposal_amplitude=_row_value(header, row, "proposal_amplitude"),
        pair_proposal_amplitude=_row_value_or(header, row, "pair_proposal_amplitude",
            _row_value(header, row, "proposal_amplitude")),
        pair_move_weight=_row_value_or(header, row, "pair_move_weight",
            max(0.0, 1.0 - _row_value_or(header, row, "collective_move_weight", 0.0) -
                      _row_value_or(header, row, "fourier_move_weight", 0.0) -
                      _row_value_or(header, row, "global_move_weight", 0.0) -
                      _row_value_or(header, row, "radial_variance_move_weight", 0.0))),
        pair_tuning_acceptance_rate=_row_value_or(header, row, "pair_tuning_acceptance_rate",
            _row_value(header, row, "tuning_acceptance_rate")),
        target_acceptance=_row_value(header, row, "target_acceptance"),
        tuning_rounds=_row_value(header, row, "tuning_rounds"),
        tuning_steps=_row_value(header, row, "tuning_steps"),
        tuning_acceptance_rate=_row_value(header, row, "tuning_acceptance_rate"),
        adaptive_warmup_rounds=_row_value_or(header, row, "adaptive_warmup_rounds", 0.0),
        adaptive_warmup_steps=_row_value_or(header, row, "adaptive_warmup_steps", 0.0),
        adaptive_warmup_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_acceptance_rate", NaN),
        adaptive_warmup_pair_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_pair_acceptance_rate", NaN),
        adaptive_warmup_collective_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_collective_acceptance_rate", NaN),
        adaptive_warmup_fourier_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_fourier_acceptance_rate", NaN),
        adaptive_warmup_global_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_global_acceptance_rate", NaN),
        adaptive_warmup_radial_variance_acceptance_rate=_row_value_or(header, row, "adaptive_warmup_radial_variance_acceptance_rate", NaN),
        collective_proposal_amplitude=_row_value(header, row, "collective_proposal_amplitude"),
        collective_pair_count=_row_value(header, row, "collective_pair_count"),
        collective_move_weight=_row_value(header, row, "collective_move_weight"),
        fourier_mode_amplitude=_row_value(header, row, "fourier_mode_amplitude"),
        fourier_max_mode=_row_value(header, row, "fourier_max_mode"),
        fourier_move_weight=_row_value(header, row, "fourier_move_weight"),
        fourier_tuning_acceptance_rate=_row_value_or(header, row, "fourier_tuning_acceptance_rate",
            _row_value(header, row, "tuning_acceptance_rate")),
        global_field_amplitude=_row_value_or(header, row, "global_field_amplitude",
            _row_value_or(header, row, "proposal_amplitude", 1.0e-8)),
        global_move_weight=_row_value_or(header, row, "global_move_weight", 0.0),
        radial_variance_amplitude=_row_value_or(header, row, "radial_variance_amplitude",
            _row_value_or(header, row, "proposal_amplitude", 1.0e-8)),
        radial_variance_move_weight=_row_value_or(header, row, "radial_variance_move_weight", 0.0),
        stable_mode_proposals=_row_value(header, row, "stable_mode_proposals"),
        fourier_min_k2=_row_value(header, row, "fourier_min_k2"),
        ess_target=_row_value(header, row, "ess_target"),
        converged=_row_value(header, row, "converged"),
        min_trace_samples=_row_value(header, row, "min_trace_samples"),
        trace_samples_pass=_row_value(header, row, "trace_samples_pass"),
        pressure_tolerance=_row_value(header, row, "pressure_tolerance"),
        pressure_error_pass=_row_value(header, row, "pressure_error_pass"),
        pressure_target_effective_sample_size=_row_value(header, row, "pressure_target_effective_sample_size"),
        required_effective_sample_size=_row_value(header, row, "required_effective_sample_size"),
        required_trace_samples=_row_value(header, row, "required_trace_samples"),
        estimated_required_steps=_row_value(header, row, "estimated_required_steps"),
        estimated_required_sweeps=_row_value(header, row, "estimated_required_sweeps"),
        production_budget_shortfall=_row_value(header, row, "production_budget_shortfall"),
        sampling_budget_pass=_row_value(header, row, "sampling_budget_pass"),
        decorrelation_stride_samples=fallback_decorrelation.decorrelation_stride_samples,
        decorrelation_stride_steps=fallback_decorrelation.decorrelation_stride_steps,
        decorrelated_sample_count=fallback_decorrelation.decorrelated_sample_count,
        equilibration_autocorrelation_windows=fallback_decorrelation.equilibration_autocorrelation_windows,
        production_autocorrelation_windows=fallback_decorrelation.production_autocorrelation_windows,
        decorrelation_pass=fallback_decorrelation.decorrelation_pass,
        equilibration_tail_fraction=fallback_equilibration.equilibration_tail_fraction,
        equilibration_tail_sample_count=fallback_equilibration.equilibration_tail_sample_count,
        equilibration_head_mean=fallback_equilibration.equilibration_head_mean,
        equilibration_tail_mean=fallback_equilibration.equilibration_tail_mean,
        equilibration_tail_stderr=fallback_equilibration.equilibration_tail_stderr,
        equilibration_sensitivity_zscore=fallback_equilibration.equilibration_sensitivity_zscore,
        equilibration_sensitivity_threshold=fallback_equilibration.equilibration_sensitivity_threshold,
        equilibration_sensitivity_pass=fallback_equilibration.equilibration_sensitivity_pass,
        energy_drift_zscore=_row_value_or(header, row, "energy_drift_zscore", NaN),
        density_variance_drift_zscore=_row_value_or(header, row, "density_variance_drift_zscore", NaN),
        low_mode_structure_drift_zscore=_row_value_or(header, row, "low_mode_structure_drift_zscore", NaN),
        max_observable_drift_zscore=_row_value_or(header, row, "max_observable_drift_zscore", NaN),
        observable_stationarity_pass=_row_value_or(header, row, "observable_stationarity_pass", 1.0),
        production_steps=_row_value(header, row, "production_steps"),
        max_production_steps=_row_value(header, row, "max_production_steps"),
        convergence_attempts=_row_value(header, row, "convergence_attempts"),
        alpha=_row_value(header, row, "alpha"),
        target_model_code=_row_value_or(header, row, "target_model_code", 1.0),
