function _existing_pressure_chain_samples(
    C::Real,
    trace_output_path,
    chain_diagnostics_path,
    observable_trace_output_path=nothing,
)
    trace_output_path === nothing && return Dict{Int,Any}()
    chain_diagnostics_path === nothing && return Dict{Int,Any}()
    trace_path = string(trace_output_path)
    diagnostics_path = string(chain_diagnostics_path)
    isfile(trace_path) || return Dict{Int,Any}()
    isfile(diagnostics_path) || throw(ArgumentError(
        "cannot resume full direct diagnostics from `$trace_path` without `$diagnostics_path`",
    ))
    trace_groups = _pressure_trace_groups(trace_path)
    diagnostic_groups = _chain_diagnostic_groups(diagnostics_path)
    observable_groups = observable_trace_output_path === nothing ? Dict{Float64,Dict{Int,Any}}() :
                        _observable_trace_groups(string(observable_trace_output_path))
    C_key = Float64(C)
    traces = get(trace_groups, C_key, Dict{Int,Vector{Float64}}())
    rows = get(diagnostic_groups.rows, C_key, Dict{Int,Vector{String}}())
    observable_traces = get(observable_groups, C_key, Dict{Int,Any}())
    header = diagnostic_groups.header
    samples = Dict{Int,Any}()
    for chain in sort(collect(intersect(keys(traces), keys(rows))))
        isempty(traces[chain]) && continue
        sample = _sample_from_chain_diagnostic(header, rows[chain], traces[chain])
        if haskey(observable_traces, chain)
            observable = observable_traces[chain]
            sample = merge(sample, (
                energy_trace=observable.energy,
                density_variance_trace=observable.density_variance,
                low_mode_structure_trace=observable.low_mode_structure,
            ))
            stationarity = _observable_stationarity_diagnostics(
                sample;
                threshold=sample.equilibration_sensitivity_threshold,
            )
            sample = merge(sample, (
                energy_drift_zscore=stationarity.energy_drift_zscore,
                density_variance_drift_zscore=stationarity.density_variance_drift_zscore,
                low_mode_structure_drift_zscore=stationarity.low_mode_structure_drift_zscore,
                max_observable_drift_zscore=stationarity.max_observable_drift_zscore,
                observable_stationarity_pass=stationarity.observable_stationarity_pass,
            ))
        end
        samples[chain] = sample
    end
    return samples
end

function _summarize_pressure_trace_chains(chains::Dict{Int,Vector{Float64}})
    chain_ids = sort(collect(keys(chains)))
    isempty(chain_ids) && throw(ArgumentError("cannot summarize empty pressure trace group"))
    traces = [chains[chain] for chain in chain_ids if !isempty(chains[chain])]
    isempty(traces) && throw(ArgumentError("cannot summarize pressure trace group without finite samples"))
    summaries = [batch_summary(trace) for trace in traces]
    combined_trace = reduce(vcat, traces)
    pooled = batch_summary(combined_trace)
    chain_means = [summary.mean for summary in summaries]
    chain_count = length(traces)
    between_stderr = chain_count <= 1 ? 0.0 : std(chain_means; corrected=true) / sqrt(chain_count)
    within_stderr = sqrt(sum(summary.stderr^2 for summary in summaries)) / chain_count
    return (
        chain_count=Float64(chain_count),
        trace_samples=Float64(length(combined_trace)),
        min_chain_samples=Float64(minimum(length(trace) for trace in traces)),
        max_chain_samples=Float64(maximum(length(trace) for trace in traces)),
        pressure_mean=mean(chain_means),
        pressure_stderr=max(pooled.stderr, between_stderr, within_stderr),
        pressure_stderr_independent=max(pooled.independent_stderr, between_stderr),
        integrated_autocorrelation_time=maximum(summary.integrated_autocorrelation_time for summary in summaries),
        effective_sample_size=sum(summary.effective_sample_size for summary in summaries),
        trace_drift_zscore=_combined_chain_trace_drift_zscore(summaries),
        chain_rhat=_chain_rhat(traces),
        split_chain_rhat=_split_chain_rhat(traces),
        chain_between_stderr=between_stderr,
        chain_within_stderr=within_stderr,
    )
end

function write_pressure_trace_summary(
    outdir::AbstractString;
    trace_filename="pressure_traces.csv",
    summary_filename="pressure_trace_summary.csv",
    markdown_filename="pressure_trace_summary.md",
)
    mkpath(outdir)
    trace_path = joinpath(outdir, trace_filename)
    grouped = _pressure_trace_groups(trace_path)
    rows = Any[]
    for C in sort(collect(keys(grouped)))
        summary = _summarize_pressure_trace_chains(grouped[C])
        push!(rows, (
            C,
            summary.chain_count,
            summary.trace_samples,
            summary.min_chain_samples,
            summary.max_chain_samples,
            summary.pressure_mean,
            summary.pressure_stderr,
            summary.pressure_stderr_independent,
            summary.integrated_autocorrelation_time,
            summary.effective_sample_size,
            summary.trace_drift_zscore,
            summary.chain_rhat,
            summary.split_chain_rhat,
            summary.chain_between_stderr,
            summary.chain_within_stderr,
        ))
    end
    csv_path = _write_table(joinpath(outdir, summary_filename), PRESSURE_TRACE_SUMMARY_HEADER, rows)
    markdown_path = joinpath(outdir, markdown_filename)
    open(markdown_path, "w") do io
        println(io, "Trace-only Arianna pressure summary")
        println(io, "===================================")
        println(io)
        println(io, "This file summarizes persisted direct Arianna pressure samples from `$(basename(trace_path))`.")
        println(io, "It is intended for interrupted or checkpointed long runs where chain pressure traces were written before the final pressure-sweep aggregation completed.")
        println(io, "The summary uses the same pressure-trace ESS, integrated-autocorrelation-time, drift, whole-chain R-hat, and split-chain R-hat estimators as the main direct sampler.")
        println(io, "It is pressure-only evidence: acceptance rates, final energies, and density-field diagnostics still require the completed direct sampler diagnostics CSV.")
        println(io)
        for row in rows
            println(io, @sprintf(
                "C = %.6g: %.0f chain(s), %.0f stored pressure samples, pressure %.6g +/- %.6g, ESS %.6g, tau_int %.6g, R-hat %.6g, split R-hat %.6g.",
                Float64(row[1]),
                Float64(row[2]),
                Float64(row[3]),
                Float64(row[6]),
                Float64(row[7]),
                Float64(row[10]),
                Float64(row[9]),
                Float64(row[12]),
                Float64(row[13]),
            ))
        end
        println(io)
        println(io, "Machine-readable summary: `$(basename(csv_path))`.")
    end
    return (csv_path=csv_path, markdown_path=markdown_path)
end

function _run_replicated_arianna_pressure_trace_until_ess(
    grid::Grid3D,
    params::HEURPParams,
    contract::PressureContract;
    chains=1,
    seed=1,
    trace_output_path=nothing,
    observable_trace_output_path=nothing,
    chain_diagnostics_path=nothing,
    trace_C=NaN,
    resume_existing=false,
    initial_density_mode=:uniform,
    kwargs...,
)
    chain_count = max(1, Int(chains))
    requested_initial_mode = _initial_density_mode_symbol(initial_density_mode)
    requested_initial_mode == :mixed && chain_count < 2 &&
        throw(ArgumentError("initial_density_mode=:mixed requires at least two chains"))
    samples_by_chain = Dict{Int,Any}()
    if Bool(resume_existing)
        samples_by_chain = _existing_pressure_chain_samples(
            trace_C,
            trace_output_path,
            chain_diagnostics_path,
            observable_trace_output_path,
        )
    end
    for chain_idx in 1:chain_count
        haskey(samples_by_chain, chain_idx) && continue
        sample, summary = _run_arianna_pressure_trace_until_ess(
            grid,
            params,
            contract;
            seed=seed + 1_000_000 * (chain_idx - 1),
            initial_density_mode=_chain_initial_density_mode(requested_initial_mode, chain_idx, chain_count),
            kwargs...,
        )
        samples_by_chain[chain_idx] = sample
        if trace_output_path !== nothing
            _append_pressure_trace_rows(string(trace_output_path), Float64(trace_C), chain_idx, sample.pressure_trace)
        end
        if observable_trace_output_path !== nothing
            _append_observable_trace_rows(string(observable_trace_output_path), Float64(trace_C), chain_idx, sample)
        end
        if chain_diagnostics_path !== nothing
            _append_pressure_chain_diagnostic_row(string(chain_diagnostics_path), Float64(trace_C), chain_idx, sample)
        end
    end
    samples = Any[]
    summaries = Any[]
    for chain_idx in 1:chain_count
        sample = samples_by_chain[chain_idx]
        push!(samples, sample)
        push!(summaries, batch_summary(sample.pressure_trace))
    end
    if Bool(resume_existing) && chain_diagnostics_path !== nothing
        diagnostics_path = string(chain_diagnostics_path)
        isfile(diagnostics_path) && rm(diagnostics_path)
        for chain_idx in 1:chain_count
            _append_pressure_chain_diagnostic_row(diagnostics_path, Float64(trace_C), chain_idx, samples_by_chain[chain_idx])
        end
    end
    return _combine_replicated_pressure_samples(samples, summaries)
end

function run_arianna_spike(outdir::AbstractString; seed=1, steps=100)
    mkpath(outdir)
    arianna_result = _arianna_spike(outdir; seed=seed, steps=steps)
    arianna_result !== nothing && return arianna_result

    rng = StableRNG(seed)
    grid = Grid3D(4, 6.4)
    params = HEURPParams()
    phi = ones(grid.Nx, grid.Nx, grid.Nx)
    energy = heurp_energy(phi, grid, params)
    accepted = 0
    rows = Any[]
    for step in 1:steps
        candidate, ok = pair_conserving_proposal(rng, phi, 0.02)
        if ok
            new_energy = heurp_energy(candidate, grid, params)
            if log(rand(rng)) < min(0.0, -(new_energy - energy))
                phi = candidate
                energy = new_energy
                accepted += 1
            end
        end
        push!(rows, (step, energy, var(vec(phi)), low_mode_structure_factor(phi)))
    end
    path = _write_table(joinpath(outdir, "arianna_spike.csv"),
        ["step", "energy", "density_variance", "low_mode_structure_factor"], rows)
    return AriannaSpikeResult(true, path, accepted / max(steps, 1), false)
end

function _direct_replica_global_proposal(
    rng::AbstractRNG,
    phi::Array{Float64,3},
    amplitude::Real;
    phi_min=1.0e-8,
)
    delta = randn(rng, size(phi))
    delta .-= mean(delta)
    delta_std = std(vec(delta); corrected=false)
    if delta_std <= eps(Float64)
        return phi, false
    end
    delta .*= Float64(amplitude) / delta_std
    delta .-= mean(delta)
    proposed = phi .+ delta
    ok = minimum(proposed) > Float64(phi_min)
    return ok ? proposed : phi, ok
end

function _direct_replica_exchange_candidate(
    rng::AbstractRNG,
    phi::Array{Float64,3};
    proposal_amplitude::Real,
    fourier_amplitude::Real,
    global_amplitude::Real,
    pair_weight::Real,
    fourier_weight::Real,
    global_weight::Real,
    phi_min=1.0e-8,
)
    pair_w = max(0.0, Float64(pair_weight))
    fourier_w = max(0.0, Float64(fourier_weight))
    global_w = max(0.0, Float64(global_weight))
    total_w = pair_w + fourier_w + global_w
    total_w > 0.0 || throw(ArgumentError("at least one replica-exchange move weight must be positive"))
    u = rand(rng) * total_w
    if u <= pair_w
        proposed, ok = pair_conserving_proposal(rng, phi, proposal_amplitude; phi_min=phi_min)
        return proposed, ok, :pair
    elseif u <= pair_w + fourier_w
        proposed, ok = fourier_mode_proposal(rng, phi, fourier_amplitude; phi_min=phi_min)
        return proposed, ok, :fourier
    else
        proposed, ok = _direct_replica_global_proposal(rng, phi, global_amplitude; phi_min=phi_min)
        return proposed, ok, :global
    end
end

function _direct_replica_exchange_weights(fourier_move_weight::Real, global_move_weight::Real)
    raw_fourier = max(0.0, Float64(fourier_move_weight))
    raw_global = max(0.0, Float64(global_move_weight))
    nonlocal = raw_fourier + raw_global
    scale = nonlocal > 0.95 ? 0.95 / nonlocal : 1.0
    fourier_w = raw_fourier * scale
    global_w = raw_global * scale
    pair_w = 1.0 - fourier_w - global_w
    return (pair=pair_w, fourier=fourier_w, global_field=global_w)
end

function run_direct_replica_exchange(
    outdir::AbstractString;
    seed=1,
    steps=1000,
    C=20.0,
    A=300.0,
    B=1.0,
    alpha=0.1,
    L=6.4,
    Nx=8,
    betas=[1.0, 0.7, 0.5, 0.35, 0.25],
    target_model=:hevk1,
    sample_stride=10,
    swap_interval=10,
    burn_fraction=0.5,
    proposal_amplitude=0.01,
    fourier_amplitude_scale=0.25,
    global_amplitude_scale=1.0,
    fourier_move_weight=0.5,
    global_move_weight=0.25,
    phi_min=1.0e-8,
    initial_density_amplitude=0.02,
    drift_threshold=3.0,
    min_trace_samples=1,
)
    mkpath(outdir)
    rng = StableRNG(seed)
    grid = Grid3D(Int(Nx), Float64(L))
    params = HEURPParams(A=Float64(A), B=Float64(B), C=Float64(C), alpha=Float64(alpha))
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    model = _direct_target_model_symbol(target_model)
    lower_bound = _density_lower_bound(phi_min)
    total_steps = max(1, Int(steps))
    stride = max(1, Int(sample_stride))
    swap_every = max(1, Int(swap_interval))
    burn_value = Float64(burn_fraction)
    0.0 <= burn_value < 1.0 || throw(ArgumentError("burn_fraction must be in [0, 1)"))
    burn = clamp(floor(Int, total_steps * burn_value), 0, max(total_steps - 1, 0))
    beta_values = sort(unique(Float64.(collect(betas))); rev=true)
    any(beta -> beta <= 0.0 || !isfinite(beta), beta_values) &&
        throw(ArgumentError("all replica-exchange betas must be positive and finite"))
    if !any(beta -> isapprox(beta, 1.0; rtol=0.0, atol=1.0e-12), beta_values)
        push!(beta_values, 1.0)
        sort!(beta_values; rev=true)
    end
    target_idx = findfirst(beta -> isapprox(beta, 1.0; rtol=0.0, atol=1.0e-12), beta_values)
    target_idx === nothing && throw(ArgumentError("replica-exchange beta ladder must contain beta = 1"))
    nreplicas = length(beta_values)
    weights = _direct_replica_exchange_weights(fourier_move_weight, global_move_weight)
    pair_amp = max(Float64(proposal_amplitude), eps(Float64))
    fourier_amp = max(pair_amp * Float64(fourier_amplitude_scale), eps(Float64))
    global_amp = max(pair_amp * Float64(global_amplitude_scale), eps(Float64))
    states = Array{Float64,3}[]
    energies = Float64[]
    for replica_idx in 1:nreplicas
        init_amp = replica_idx == target_idx ? 0.0 : Float64(initial_density_amplitude)
        phi = _initial_density_field(
            rng,
            grid;
            initialization=init_amp > 0.0 ? :overdispersed : :uniform,
            initial_density_amplitude=init_amp,
            phi_min=lower_bound,
        )
        push!(states, phi)
        push!(energies, _direct_target_energy(phi, grid, params, model))
    end
    replica_labels = collect(1:nreplicas)
    label_min_seen = falses(nreplicas)
    label_max_seen = falses(nreplicas)
    label_round_trips = zeros(Int, nreplicas)
    label_min_seen[replica_labels[1]] = true
    label_max_seen[replica_labels[end]] = true

    move_attempts = Dict(:pair => 0, :fourier => 0, :global => 0)
    move_accepts = Dict(:pair => 0, :fourier => 0, :global => 0)
    swap_attempts = 0
    swap_accepts = 0
    sample_rows = Any[]
    pressures = Float64[]
    density_variances = Float64[]
    low_mode_structures = Float64[]
    sample_index = 0
    for step in 1:total_steps
        for replica_idx in 1:nreplicas
            proposed, geometry_ok, family = _direct_replica_exchange_candidate(
                rng,
                states[replica_idx];
                proposal_amplitude=pair_amp,
                fourier_amplitude=fourier_amp,
                global_amplitude=global_amp,
                pair_weight=weights.pair,
                fourier_weight=weights.fourier,
                global_weight=weights.global_field,
                phi_min=lower_bound,
            )
            move_attempts[family] += 1
            geometry_ok || continue
            proposed_energy = _direct_target_energy(proposed, grid, params, model)
            isfinite(proposed_energy) || continue
            log_accept = -beta_values[replica_idx] * (proposed_energy - energies[replica_idx])
            if log(rand(rng)) < min(0.0, log_accept)
                states[replica_idx] = proposed
                energies[replica_idx] = proposed_energy
                move_accepts[family] += 1
            end
        end
        if nreplicas > 1 && step % swap_every == 0
            for replica_idx in 1:(nreplicas - 1)
                beta_i = beta_values[replica_idx]
                beta_j = beta_values[replica_idx + 1]
                energy_i = energies[replica_idx]
                energy_j = energies[replica_idx + 1]
                log_swap = (beta_i - beta_j) * (energy_i - energy_j)
                swap_attempts += 1
                if log(rand(rng)) < min(0.0, log_swap)
                    states[replica_idx], states[replica_idx + 1] = states[replica_idx + 1], states[replica_idx]
                    energies[replica_idx], energies[replica_idx + 1] = energies[replica_idx + 1], energies[replica_idx]
                    replica_labels[replica_idx], replica_labels[replica_idx + 1] =
                        replica_labels[replica_idx + 1], replica_labels[replica_idx]
                    swap_accepts += 1
                end
            end
            for slot in 1:nreplicas
                label = replica_labels[slot]
                if slot == 1
                    if label_max_seen[label]
                        label_round_trips[label] += 1
                        label_max_seen[label] = false
                    end
                    label_min_seen[label] = true
                elseif slot == nreplicas
                    if label_min_seen[label]
                        label_round_trips[label] += 1
                        label_min_seen[label] = false
                    end
                    label_max_seen[label] = true
                end
            end
        end
        if step > burn && step % stride == 0
            sample_index += 1
            phi = states[target_idx]
            pressure = _direct_target_pressure(phi, grid, params, contract, model)
            variance = var(vec(phi))
            structure = low_mode_structure_factor(phi)
            push!(pressures, pressure)
            push!(density_variances, variance)
            push!(low_mode_structures, structure)
            push!(sample_rows, (
                step,
                sample_index,
                target_idx,
                beta_values[target_idx],
                energies[target_idx],
                pressure,
                variance,
                structure,
            ))
        end
    end
    isempty(pressures) && throw(ArgumentError("replica-exchange run produced no target samples; reduce burn_fraction or sample_stride"))
    summary = batch_summary(pressures)
    variance_summary = batch_summary(density_variances)
    density_variance_drift = _trace_drift_zscore(density_variances)
    low_mode_structure_drift = _trace_drift_zscore(low_mode_structures)
    observable_drift_scores = (density_variance_drift, low_mode_structure_drift)
    finite_observable_drifts = Float64[z for z in observable_drift_scores if isfinite(z)]
    max_observable_drift =
        any(isinf, observable_drift_scores) ? Inf :
        isempty(finite_observable_drifts) ? NaN :
        maximum(finite_observable_drifts)
    observable_stationarity_pass =
        isnan(max_observable_drift) || max_observable_drift <= Float64(drift_threshold) ? 1.0 : 0.0
    replica_round_trips = sum(label_round_trips)
    max_replica_round_trips = maximum(label_round_trips)
    min_replica_round_trips = minimum(label_round_trips)
    trace_pass = _trace_samples_pass(summary, min_trace_samples)
    drift_pass = _drift_pass(summary, drift_threshold)
    move_total = sum(values(move_attempts))
    move_acceptance = sum(values(move_accepts)) / max(move_total, 1)
    swap_acceptance = swap_accepts / max(swap_attempts, 1)
    diagnostic_pass = min(trace_pass, drift_pass, observable_stationarity_pass)
    samples_csv = _write_table(
        joinpath(outdir, "replica_exchange_samples.csv"),
        [
            "step",
            "sample_index",
            "replica_index",
            "replica_beta",
            "energy",
            "pressure",
            "density_variance",
            "low_mode_structure_factor",
        ],
        sample_rows,
    )
    diagnostics_csv = _write_table(
        joinpath(outdir, "replica_exchange_diagnostics.csv"),
        [
            "C",
            "target_pressure_mean",
            "target_pressure_stderr",
            "target_sample_count",
            "target_effective_sample_size",
            "target_integrated_autocorrelation_time",
            "target_trace_drift_zscore",
            "density_variance_drift_zscore",
            "low_mode_structure_drift_zscore",
            "max_observable_drift_zscore",
            "observable_stationarity_pass",
            "target_density_variance_mean",
            "target_density_variance_stderr",
            "move_acceptance_rate",
            "pair_acceptance_rate",
            "fourier_acceptance_rate",
            "global_acceptance_rate",
            "swap_acceptance_rate",
            "swap_attempts",
            "replica_round_trips",
            "max_replica_round_trips",
            "min_replica_round_trips",
            "replica_count",
            "steps",
            "burn_fraction",
            "sample_stride",
            "swap_interval",
            "proposals_per_sweep",
            "production_sweeps",
            "trace_samples_pass",
            "drift_threshold",
            "drift_pass",
            "diagnostic_pass",
            "target_model_code",
        ],
        [(
            params.C,
            summary.mean,
            summary.stderr,
            summary.n,
            summary.effective_sample_size,
            summary.integrated_autocorrelation_time,
            summary.trace_drift_zscore,
            density_variance_drift,
            low_mode_structure_drift,
            max_observable_drift,
            observable_stationarity_pass,
            variance_summary.mean,
            variance_summary.stderr,
            move_acceptance,
            move_accepts[:pair] / max(move_attempts[:pair], 1),
            move_accepts[:fourier] / max(move_attempts[:fourier], 1),
            move_accepts[:global] / max(move_attempts[:global], 1),
            swap_acceptance,
            swap_attempts,
            replica_round_trips,
            max_replica_round_trips,
            min_replica_round_trips,
            nreplicas,
            total_steps,
            burn_value,
            stride,
            swap_every,
            _proposals_per_sweep(grid),
            _sweeps_from_steps(grid, total_steps),
            trace_pass,
            Float64(drift_threshold),
            drift_pass,
            diagnostic_pass,
            _direct_target_model_code(model),
        )],
    )
    markdown_path = joinpath(outdir, "replica_exchange.md")
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear replica-exchange MC diagnostic")
        println(io, "==============================================")
        println(io)
        println(io, "This run uses adjacent inverse-temperature swaps on the real-valued $(_direct_target_model_label(model)) density-field Hamiltonian.")
        println(io, "Only the beta = 1 replica slot is summarized as physical pressure evidence.")
        println(io, @sprintf("C = %.6g, Nx = %d, replicas = %d, betas = %s.", params.C, grid.Nx, nreplicas, join((@sprintf("%.6g", beta) for beta in beta_values), ", ")))
        println(io, @sprintf("Target pressure %.6g +/- %.6g from %.0f stored target samples; ESS %.6g, tau_int %.6g, drift z %.6g.", summary.mean, summary.stderr, Float64(summary.n), summary.effective_sample_size, summary.integrated_autocorrelation_time, summary.trace_drift_zscore))
        println(io, @sprintf("Observable drift z scores: density variance %.6g, low-mode structure %.6g; stationarity pass %.0f.", density_variance_drift, low_mode_structure_drift, observable_stationarity_pass))
        println(io, @sprintf("Replica endpoint traversals: total %.0f, min per label %.0f, max per label %.0f.", Float64(replica_round_trips), Float64(min_replica_round_trips), Float64(max_replica_round_trips)))
        println(io, @sprintf("Move acceptance %.6g (pair %.6g, Fourier %.6g, global %.6g); swap acceptance %.6g over %.0f attempts.", move_acceptance, move_accepts[:pair] / max(move_attempts[:pair], 1), move_accepts[:fourier] / max(move_attempts[:fourier], 1), move_accepts[:global] / max(move_attempts[:global], 1), swap_acceptance, Float64(swap_attempts)))
        println(io, @sprintf("Diagnostic pass %.0f with trace-sample pass %.0f, pressure-drift pass %.0f, and observable-stationarity pass %.0f.", diagnostic_pass, trace_pass, drift_pass, observable_stationarity_pass))
        println(io)
        println(io, "This is direct nonlinear MC evidence. It does not use or refine the Gaussian perturbation MC estimators.")
        println(io, "Machine-readable samples: `$(basename(samples_csv))`.")
        println(io, "Machine-readable diagnostics: `$(basename(diagnostics_csv))`.")
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "sampler" => "direct_replica_exchange",
            "target_model" => _direct_target_model_label(model),
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => grid.Nx,
            "L" => grid.L,
        ),
        "params" => Dict{String,Any}(
            "A" => params.A,
            "B" => params.B,
            "C" => params.C,
            "alpha" => params.alpha,
        ),
        "sampling" => Dict{String,Any}(
            "steps" => total_steps,
            "burn_fraction" => burn_value,
            "sample_stride" => stride,
            "swap_interval" => swap_every,
            "betas" => _toml_value(beta_values),
            "proposal_amplitude" => pair_amp,
            "fourier_amplitude" => fourier_amp,
            "global_amplitude" => global_amp,
            "pair_move_weight" => weights.pair,
            "fourier_move_weight" => weights.fourier,
            "global_move_weight" => weights.global_field,
            "phi_min" => lower_bound,
        ),
        "outputs" => Dict{String,Any}(
            "samples_csv" => samples_csv,
            "diagnostics_csv" => diagnostics_csv,
            "markdown_path" => markdown_path,
        ),
        "environment" => _metadata_environment(),
    ))
    return DirectReplicaExchangeResult(samples_csv, diagnostics_csv, markdown_path)
end

function run_pressure_sweep(
    outdir::AbstractString;
    mode=:quick,
    seed=1,
    steps=100,
    sweeps=nothing,
    require_arianna=true,
    C_values=nothing,
    ess_target=4.0,
    max_steps=nothing,
    max_sweeps=nothing,
    step_growth=2.0,
    chains=1,
    min_acceptance=0.2,
    max_acceptance=0.8,
    drift_threshold=3.0,
    rhat_threshold=1.1,
    min_trace_samples=nothing,
    pressure_tolerance=nothing,
    initial_proposal_amplitude=0.01,
    tune_proposal=true,
    target_acceptance=0.44,
    tuning_rounds=8,
    tuning_steps=nothing,
    adaptive_warmup=false,
    adaptive_warmup_rounds=nothing,
    adaptive_warmup_steps=nothing,
    adaptive_warmup_gain=1.0,
    fourier_amplitude_scale=0.25,
    fourier_max_mode=2,
    fourier_move_weight=0.1,
    global_amplitude_scale=0.1,
    global_move_weight=0.0,
    radial_variance_amplitude_scale=0.1,
    radial_variance_move_weight=0.0,
    stable_mode_proposals=false,
    fourier_min_k2=nothing,
    burn_fraction=0.5,
    sample_stride=1,
    Nx=nothing,
    stability_probe=true,
    stability_probe_modes=[(1, 0, 0), (1, 1, 0), (1, 1, 1), (2, 0, 0)],
    stability_amplitude_count=8,
    stability_boundary_margin=1.0e-3,
    stability_energy_tolerance=1.0e-8,
    basin_variance_max=nothing,
    phi_min=1.0e-8,
    boundary_barrier_strength=0.0,
    initial_density_mode=:uniform,
    initial_density_amplitude=0.0,
    target_model=:heurp,
    resume_traces=false,
)
    require_arianna || throw(ArgumentError("run_pressure_sweep now requires Arianna for manuscript validation"))
    cfg = run_config(mode)
    explicit_Nx = Nx === nothing ? nothing : Int(Nx)
    explicit_Nx === nothing || explicit_Nx >= 2 || throw(ArgumentError("Nx must be at least 2"))
    effective_Nx = cfg.Nx
    if mode == :production
        if explicit_Nx === nothing && get(ENV, "DFM_MC_FULL_PRODUCTION", "0") != "1"
            effective_Nx = parse(Int, get(ENV, "DFM_MC_PRODUCTION_FALLBACK_NX", "4"))
        end
    end
    if explicit_Nx !== nothing
        effective_Nx = explicit_Nx
    end
    mkpath(outdir)
    contract = load_pressure_contract(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml"))
    _check_contract(contract)
    cl_path = cfg.analysis_source
    cl_data = isfile(cl_path) ? read_cl_pressure(cl_path) : nothing
    pressure_rows = Any[]
    diag_rows = Any[]
    pressure_trace_csv = joinpath(outdir, "pressure_traces.csv")
    observable_trace_csv = joinpath(outdir, "observable_traces.csv")
    pressure_chain_csv = joinpath(outdir, "pressure_chain_diagnostics.csv")
    if !Bool(resume_traces)
        isfile(pressure_trace_csv) && rm(pressure_trace_csv)
        isfile(observable_trace_csv) && rm(observable_trace_csv)
        isfile(pressure_chain_csv) && rm(pressure_chain_csv)
    end
    sampled_C_values = C_values === nothing ? cfg.C_values : Float64.(C_values)
    effective_cfg = RunConfig(cfg.mode, cfg.dimension, effective_Nx, cfg.target_Nx, cfg.L, cfg.A, cfg.B,
        sampled_C_values, cfg.manuscript_grade, cfg.alpha, cfg.analysis_source)
    if mode == :production
        meta_path = joinpath(outdir, "production_target.txt")
        open(meta_path, "w") do io
            println(io, "Production target: 3D L=$(cfg.L), C=$(sampled_C_values)")
            println(io, "Manuscript target grid: Nx=$(cfg.target_Nx)")
            println(io, "Effective sampling grid: Nx=$(effective_Nx)")
            println(io, "Set DFM_MC_FULL_PRODUCTION=1 to run the full target grid when no explicit Nx override is supplied.")
        end
    end
    acceptance_min = clamp(Float64(min_acceptance), 0.0, 1.0)
    acceptance_max = clamp(Float64(max_acceptance), acceptance_min, 1.0)
    drift_limit = max(0.0, Float64(drift_threshold))
    rhat_limit = max(1.0, Float64(rhat_threshold))
    trace_minimum = min_trace_samples === nothing ? (mode == :production ? 100 : 1) :
                    max(1, Int(ceil(Float64(min_trace_samples))))
    pressure_error_tolerance = pressure_tolerance === nothing ? (mode == :production ? 0.1 : Inf) :
                               Float64(pressure_tolerance)
    pressure_error_tolerance >= 0.0 || throw(ArgumentError("pressure_tolerance must be nonnegative"))
    basin_cap = _basin_variance_cap(basin_variance_max)
    lower_bound = _density_lower_bound(phi_min)
    barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
    initial_mode = _initial_density_mode_symbol(initial_density_mode)
    initial_density_amp = Float64(initial_density_amplitude)
    target_model_symbol = _direct_target_model_symbol(target_model)
    stable_proposals = Bool(stable_mode_proposals)
    metadata_grid = Grid3D(effective_Nx, cfg.L)
    metadata_first_steps = _resolve_steps(metadata_grid; steps=steps, sweeps=sweeps)
    metadata_max_steps = if max_sweeps !== nothing
        max(metadata_first_steps, _steps_from_sweeps(metadata_grid, max_sweeps))
    elseif max_steps === nothing
        sweeps === nothing ? max(metadata_first_steps, 100) : metadata_first_steps
    else
        max(metadata_first_steps, Int(max_steps))
    end
    for (cidx, C) in enumerate(sampled_C_values)
        grid = Grid3D(effective_Nx, cfg.L)
        first_steps = _resolve_steps(grid; steps=steps, sweeps=sweeps)
        sweep_max_steps = if max_sweeps !== nothing
            max(first_steps, _steps_from_sweeps(grid, max_sweeps))
        elseif max_steps === nothing
            sweeps === nothing ? max(first_steps, 100) : first_steps
        else
            max(first_steps, Int(max_steps))
        end
        params = HEURPParams(A=cfg.A, B=cfg.B, C=C, alpha=cfg.alpha)
        row_fourier_min_k2 = _resolved_fourier_min_k2(params;
            stable_mode_proposals=stable_proposals, fourier_min_k2=fourier_min_k2)
        row_stability_modes = _stability_probe_modes_for_target(
            grid,
            stability_probe_modes,
            Int(fourier_max_mode),
            stable_proposals ? row_fourier_min_k2 : 0.0,
        )
        stability = if !stability_probe
            (
                pass=1.0,
                min_energy_delta=0.0,
                min_phi=1.0,
                mode_ax=0.0,
                mode_ay=0.0,
                mode_az=0.0,
                points=0.0,
                boundary_margin=Float64(stability_boundary_margin),
                energy_tolerance=Float64(stability_energy_tolerance),
            )
        elseif target_model_symbol == :hevk1
            _direct_stability_summary_for_energy(
                grid,
                params,
                hevk1_energy,
                hevk1_pressure_observable;
                modes=row_stability_modes,
                amplitude_count=stability_amplitude_count,
                boundary_margin=stability_boundary_margin,
                energy_tolerance=stability_energy_tolerance,
                basin_variance_max=basin_cap,
                phi_min=lower_bound,
            )
        else
            _direct_stability_summary(
                grid,
                params;
                modes=row_stability_modes,
                amplitude_count=stability_amplitude_count,
                boundary_margin=stability_boundary_margin,
                energy_tolerance=stability_energy_tolerance,
                basin_variance_max=basin_cap,
                phi_min=lower_bound,
                boundary_barrier_strength=barrier_strength,
            )
        end
        sample, summary = _run_replicated_arianna_pressure_trace_until_ess(
            grid,
            params,
            contract;
            chains=chains,
            seed=seed + cidx - 1,
            steps=steps,
            sweeps=sweeps,
            ess_target=ess_target,
            max_steps=sweep_max_steps,
            max_sweeps=nothing,
            step_growth=step_growth,
            min_trace_samples=trace_minimum,
            pressure_tolerance=pressure_error_tolerance,
            trace_output_path=pressure_trace_csv,
            observable_trace_output_path=observable_trace_csv,
            chain_diagnostics_path=pressure_chain_csv,
            trace_C=C,
            resume_existing=resume_traces,
            burn_fraction=burn_fraction,
            sample_stride=sample_stride,
            initial_proposal_amplitude=initial_proposal_amplitude,
            tune_proposal=tune_proposal,
            target_acceptance=target_acceptance,
            tuning_rounds=tuning_rounds,
            tuning_steps=tuning_steps,
            adaptive_warmup=adaptive_warmup,
            adaptive_warmup_rounds=adaptive_warmup_rounds,
            adaptive_warmup_steps=adaptive_warmup_steps,
            adaptive_warmup_gain=adaptive_warmup_gain,
            fourier_amplitude_scale=fourier_amplitude_scale,
            fourier_max_mode=fourier_max_mode,
            fourier_move_weight=fourier_move_weight,
            global_amplitude_scale=global_amplitude_scale,
            global_move_weight=global_move_weight,
            radial_variance_amplitude_scale=radial_variance_amplitude_scale,
            radial_variance_move_weight=radial_variance_move_weight,
            stable_mode_proposals=stable_proposals,
            fourier_min_k2=row_fourier_min_k2,
            basin_variance_max=basin_cap,
            phi_min=lower_bound,
            boundary_barrier_strength=barrier_strength,
            initial_density_mode=initial_mode,
            initial_density_amplitude=initial_density_amp,
            target_model=target_model_symbol,
            equilibration_sensitivity_threshold=drift_limit,
        )
        reference = dfm_pressure_discrete(cfg.A, cfg.B, C, grid; alpha=cfg.alpha)
        mc_pressure = summary.mean
        if cl_data === nothing
            cl_pressure, cl_error = NaN, NaN
        else
            nearest = argmin(abs.(cl_data.C .- C))
            cl_pressure, cl_error = cl_data.pressure[nearest], cl_data.pressure_error[nearest]
        end
        ess_pass = (sample.ess_target <= 0.0 || summary.effective_sample_size >= sample.ess_target) ? 1.0 : 0.0
        acceptance_pass = (acceptance_min <= sample.acceptance <= acceptance_max) ? 1.0 : 0.0
        drift_pass = _drift_pass(summary, drift_limit)
        whole_rhat_ok = sample.chain_count < 2 || _rhat_value_pass(sample.chain_rhat, rhat_limit) >= 0.5
        split_rhat_ok = sample.chain_count < 2 || _rhat_value_pass(sample.split_chain_rhat, rhat_limit) >= 0.5
        rhat_pass = (whole_rhat_ok && split_rhat_ok) ? 1.0 : 0.0
        trace_samples_pass = _trace_samples_pass(summary, trace_minimum)
        pressure_error_pass = _pressure_error_pass(summary, pressure_error_tolerance)
        budget_pass = sample.sampling_budget_pass
        decorrelation_pass = sample.decorrelation_pass
        equilibration_sensitivity_pass = sample.equilibration_sensitivity_pass
        observable_stationarity_pass = sample.observable_stationarity_pass
        basin_pass = sample.basin_constraint_pass
        stability_pass = stability.pass
