            "observable_traces_csv" => observable_trace_csv,
            "pressure_chain_diagnostics_csv" => pressure_chain_csv,
            "pressure_estimator_contract" => normpath(joinpath(@__DIR__, "..", "docs", "pressure_estimator_contract.toml")),
            "analysis_source" => effective_cfg.analysis_source,
        ),
    ))
    return SweepResult(pressure_csv, diagnostics_csv, effective_cfg)
end

function _single_row_value(header, row, name::AbstractString)
    idx = findfirst(==(name), header)
    return idx === nothing || length(row) < idx ? NaN : row[idx]
end

function _direct_budget_column_values(header, rows, name::AbstractString)
    idx = findfirst(==(name), header)
    idx === nothing && return Float64[]
    return Float64[row[idx] for row in rows if length(row) >= idx && isfinite(row[idx])]
end

function _direct_budget_c_values(header, rows)
    values = _direct_budget_column_values(header, rows, "C")
    unique_values = Float64[]
    for value in values
        any(existing -> isapprox(existing, value; rtol=0.0, atol=1.0e-12), unique_values) && continue
        push!(unique_values, value)
    end
    return unique_values
end

_direct_mc_script_prefix(mode) = mode == :production ? "DFM_MC_PRODUCTION" : "DFM_MC_QUICK"

function _direct_mc_target_model_env_value(target_model)
    model = _direct_target_model_symbol(target_model)
    return model == :hevk1 ? "hevk1" : "heurp"
end

function _write_direct_mc_budget_plan(
    outdir::AbstractString,
    diagnostics_csv::AbstractString;
    mode,
    seed,
    Nx,
    steps,
    chains,
    ess_target,
    min_trace_samples,
    pressure_tolerance,
    burn_fraction,
    sample_stride,
    initial_proposal_amplitude,
    initial_density_mode,
    initial_density_amplitude,
    tune_proposal,
    target_acceptance,
    tuning_rounds,
    tuning_steps,
    adaptive_warmup,
    adaptive_warmup_rounds,
    adaptive_warmup_steps,
    adaptive_warmup_gain,
    fourier_amplitude_scale,
    fourier_max_mode,
    fourier_move_weight,
    global_amplitude_scale,
    global_move_weight,
    radial_variance_amplitude_scale,
    radial_variance_move_weight,
    stable_mode_proposals,
    fourier_min_k2,
    basin_variance_max,
    phi_min,
    boundary_barrier_strength,
    target_model,
    budget_safety_factor=1.2,
)
    header, rows = _read_csv_numeric(diagnostics_csv)
    required_steps_values = _direct_budget_column_values(header, rows, "estimated_required_steps")
    required_sweeps_values = _direct_budget_column_values(header, rows, "estimated_required_sweeps")
    shortfall_values = _direct_budget_column_values(header, rows, "production_budget_shortfall")
    diagnostic_pass_values = _direct_budget_column_values(header, rows, "diagnostic_pass")
    c_values = _direct_budget_c_values(header, rows)
    c_values_text = join((@sprintf("%.12g", value) for value in c_values), ",")
    max_required_steps = isempty(required_steps_values) ? NaN : maximum(required_steps_values)
    max_required_sweeps = isempty(required_sweeps_values) ? NaN : maximum(required_sweeps_values)
    max_shortfall = isempty(shortfall_values) ? NaN : maximum(shortfall_values)
    pass_count = count(x -> x >= 0.5, diagnostic_pass_values)
    gate_count = length(diagnostic_pass_values)
    safety = max(1.0, Float64(budget_safety_factor))
    recommended_steps = isfinite(max_required_steps) ? max(1, ceil(Int, safety * max_required_steps)) :
                        max(1, Int(steps))
    recommended_steps = max(recommended_steps, Int(steps))
    prefix = _direct_mc_script_prefix(mode)
    project_dir = normpath(joinpath(@__DIR__, ".."))
    path = joinpath(outdir, "direct_mc_budget_plan.md")
    target_value = _direct_mc_target_model_env_value(target_model)
    initial_mode = string(_initial_density_mode_symbol(initial_density_mode))
    open(path, "w") do io
        println(io, "Recommended direct MC rerun")
        println(io, "===========================")
        println(io)
        println(io, "This plan is derived from the direct Arianna pressure-sweep diagnostics. It preserves the target model, initialization protocol, proposal mix, chain count, burn-in fraction, stride, and pressure/ESS gates from the completed run.")
        if gate_count > 0
            println(io, @sprintf("Current diagnostic pass count: %.0f of %.0f state point(s).", pass_count, gate_count))
        end
        if isfinite(max_required_steps)
            println(io, @sprintf("Observed maximum estimated_required_steps: %.6g proposal steps (%.6g sweeps), with maximum production_budget_shortfall %.6g.", max_required_steps, max_required_sweeps, max_shortfall))
            println(io, @sprintf("Safety factor: %.6g.", safety))
        else
            println(io, "No finite estimated_required_steps value was available; the command below repeats the completed proposal-step budget.")
        end
        println(io, @sprintf("Recommended proposal-step budget: %d.", recommended_steps))
        println(io)
        println(io, "Reproducible command:")
        println(io)
        println(io, "```bash")
        println(io, "DFM_MC_OUTDIR=$(joinpath(outdir, "budgeted")) \\")
        println(io, "$(prefix)_TARGET_MODEL=$target_value \\")
        println(io, "$(prefix)_NX=$(Int(Nx)) \\")
        isempty(c_values_text) || println(io, "$(prefix)_C_VALUES=$c_values_text \\")
        println(io, "$(prefix)_STEPS=$recommended_steps \\")
        println(io, "$(prefix)_CHAINS=$(Int(chains)) \\")
        println(io, "$(prefix)_ESS_TARGET=$(@sprintf("%.6g", Float64(ess_target))) \\")
        println(io, "$(prefix)_MIN_TRACE_SAMPLES=$(Int(min_trace_samples)) \\")
        println(io, "$(prefix)_PRESSURE_TOLERANCE=$(@sprintf("%.6g", Float64(pressure_tolerance))) \\")
        println(io, "$(prefix)_BURN_FRACTION=$(@sprintf("%.6g", Float64(burn_fraction))) \\")
        println(io, "$(prefix)_SAMPLE_STRIDE=$(Int(sample_stride)) \\")
        println(io, "$(prefix)_INITIAL_PROPOSAL_AMPLITUDE=$(@sprintf("%.6g", Float64(initial_proposal_amplitude))) \\")
        println(io, "$(prefix)_INITIAL_DENSITY_MODE=$initial_mode \\")
        println(io, "$(prefix)_INITIAL_DENSITY_AMPLITUDE=$(@sprintf("%.6g", Float64(initial_density_amplitude))) \\")
        println(io, "$(prefix)_TUNE_PROPOSAL=$(Bool(tune_proposal)) \\")
        println(io, "$(prefix)_TARGET_ACCEPTANCE=$(@sprintf("%.6g", Float64(target_acceptance))) \\")
        println(io, "$(prefix)_TUNING_ROUNDS=$(Int(tuning_rounds)) \\")
        if tuning_steps !== nothing
            println(io, "$(prefix)_TUNING_STEPS=$(Int(tuning_steps)) \\")
        end
        println(io, "$(prefix)_ADAPTIVE_WARMUP=$(Bool(adaptive_warmup)) \\")
        if adaptive_warmup_rounds !== nothing
            println(io, "$(prefix)_ADAPTIVE_WARMUP_ROUNDS=$(Int(adaptive_warmup_rounds)) \\")
        end
        if adaptive_warmup_steps !== nothing
            println(io, "$(prefix)_ADAPTIVE_WARMUP_STEPS=$(Int(adaptive_warmup_steps)) \\")
        end
        println(io, "$(prefix)_ADAPTIVE_WARMUP_GAIN=$(@sprintf("%.6g", Float64(adaptive_warmup_gain))) \\")
        println(io, "$(prefix)_FOURIER_AMPLITUDE_SCALE=$(@sprintf("%.6g", Float64(fourier_amplitude_scale))) \\")
        println(io, "$(prefix)_FOURIER_MAX_MODE=$(Int(fourier_max_mode)) \\")
        println(io, "$(prefix)_FOURIER_MOVE_WEIGHT=$(@sprintf("%.6g", Float64(fourier_move_weight))) \\")
        println(io, "$(prefix)_GLOBAL_AMPLITUDE_SCALE=$(@sprintf("%.6g", Float64(global_amplitude_scale))) \\")
        println(io, "$(prefix)_GLOBAL_MOVE_WEIGHT=$(@sprintf("%.6g", Float64(global_move_weight))) \\")
        println(io, "$(prefix)_RADIAL_VARIANCE_AMPLITUDE_SCALE=$(@sprintf("%.6g", Float64(radial_variance_amplitude_scale))) \\")
        println(io, "$(prefix)_RADIAL_VARIANCE_MOVE_WEIGHT=$(@sprintf("%.6g", Float64(radial_variance_move_weight))) \\")
        println(io, "$(prefix)_STABLE_MODE_PROPOSALS=$(Bool(stable_mode_proposals)) \\")
        if fourier_min_k2 !== nothing
            println(io, "$(prefix)_FOURIER_MIN_K2=$(@sprintf("%.6g", Float64(fourier_min_k2))) \\")
        end
        if basin_variance_max !== nothing
            println(io, "$(prefix)_BASIN_VARIANCE_MAX=$(@sprintf("%.6g", Float64(basin_variance_max))) \\")
        end
        barrier_strength = _boundary_barrier_strength(boundary_barrier_strength)
        if barrier_strength > 0.0
            println(io, "$(prefix)_BOUNDARY_BARRIER_STRENGTH=$(@sprintf("%.6g", barrier_strength)) \\")
        end
        println(io, "$(prefix)_PHI_MIN=$(@sprintf("%.6g", Float64(phi_min))) \\")
        println(io, "julia --project=$project_dir $(joinpath(project_dir, "scripts", "run_pressure_sweep.jl"))")
        println(io, "```")
        println(io)
        println(io, "The command is a budgeted diagnostic rerun, not manuscript evidence by itself. The rerun must still pass ESS, decorrelation, burn-in sensitivity, state-observable stationarity, R-hat, acceptance, and pressure-error gates.")
        println(io, @sprintf("Seed recorded in source run metadata: %d.", Int(seed)))
    end
    return path
end

function _floor_label(phi_min::Real)
    raw = @sprintf("%.6g", Float64(phi_min))
    return replace(replace(raw, "." => "p"), "-" => "m")
end

function run_direct_floor_sensitivity_study(
    outdir::AbstractString;
    mode=:quick,
    seed=701,
    Nx=4,
    C=20.0,
    phi_min_values=[0.1, 0.05, 0.02],
    steps=256,
    sweeps=nothing,
    max_steps=nothing,
    max_sweeps=nothing,
    step_growth=2.0,
    chains=2,
    ess_target=10.0,
    min_trace_samples=20,
    pressure_tolerance=Inf,
    min_acceptance=0.0,
    max_acceptance=1.0,
    drift_threshold=3.0,
    rhat_threshold=1.1,
    burn_fraction=0.5,
    sample_stride=1,
    initial_proposal_amplitude=0.01,
    tune_proposal=true,
    target_acceptance=0.44,
    tuning_rounds=4,
    tuning_steps=nothing,
    fourier_amplitude_scale=0.25,
    fourier_max_mode=2,
    fourier_move_weight=0.1,
    stable_mode_proposals=false,
    fourier_min_k2=nothing,
    stability_probe=true,
    stability_amplitude_count=8,
    stability_boundary_margin=1.0e-3,
    stability_energy_tolerance=1.0e-8,
    budget_safety_factor=1.2,
    reuse_existing=false,
)
    mkpath(outdir)
    floors = sort(unique(Float64.(collect(phi_min_values))))
    isempty(floors) && throw(ArgumentError("phi_min_values must not be empty"))
    any(floor -> !(0.0 <= floor < 1.0), floors) &&
        throw(ArgumentError("all phi_min_values must lie in [0, 1)"))

    base_rows = Any[]
    subdirs = String[]
    pressures = Float64[]
    for (floor_idx, phi_floor) in enumerate(floors)
        subdir = joinpath(outdir, "phi_min_" * _floor_label(phi_floor))
        push!(subdirs, subdir)
        pressure_csv = joinpath(subdir, "pressure_comparison.csv")
        diagnostics_csv = joinpath(subdir, "sampling_diagnostics.csv")
        result = if Bool(reuse_existing) && isfile(pressure_csv) && isfile(diagnostics_csv)
            (pressure_csv=pressure_csv, diagnostics_csv=diagnostics_csv)
        else
            run_pressure_sweep(
                subdir;
                mode=mode,
                seed=seed + 10_000 * (floor_idx - 1),
                steps=steps,
                sweeps=sweeps,
                max_steps=max_steps,
                max_sweeps=max_sweeps,
                step_growth=step_growth,
                chains=chains,
                C_values=[Float64(C)],
                ess_target=ess_target,
                min_acceptance=min_acceptance,
                max_acceptance=max_acceptance,
                drift_threshold=drift_threshold,
                rhat_threshold=rhat_threshold,
                min_trace_samples=min_trace_samples,
                pressure_tolerance=pressure_tolerance,
                initial_proposal_amplitude=initial_proposal_amplitude,
                tune_proposal=tune_proposal,
                target_acceptance=target_acceptance,
                tuning_rounds=tuning_rounds,
                tuning_steps=tuning_steps,
                fourier_amplitude_scale=fourier_amplitude_scale,
                fourier_max_mode=fourier_max_mode,
                fourier_move_weight=fourier_move_weight,
                stable_mode_proposals=stable_mode_proposals,
                fourier_min_k2=fourier_min_k2,
                burn_fraction=burn_fraction,
                sample_stride=sample_stride,
                Nx=Nx,
                stability_probe=stability_probe,
                stability_amplitude_count=stability_amplitude_count,
                stability_boundary_margin=stability_boundary_margin,
                stability_energy_tolerance=stability_energy_tolerance,
                phi_min=phi_floor,
            )
        end
        pressure_header, pressure_rows = _read_csv_numeric(result.pressure_csv)
        diagnostics_header, diagnostics_rows = _read_csv_numeric(result.diagnostics_csv)
        isempty(pressure_rows) && throw(ArgumentError("empty pressure comparison CSV for phi_min=$phi_floor"))
        isempty(diagnostics_rows) && throw(ArgumentError("empty diagnostics CSV for phi_min=$phi_floor"))
        pressure_row = first(pressure_rows)
        diagnostics_row = first(diagnostics_rows)
        mc_pressure = _single_row_value(pressure_header, pressure_row, "mc_pressure")
        push!(pressures, mc_pressure)
        dfm = _single_row_value(pressure_header, pressure_row, "dfm_pressure")
        cl = _single_row_value(pressure_header, pressure_row, "cl_pressure_nearest")
        push!(base_rows, (
            phi_floor,
            _single_row_value(pressure_header, pressure_row, "C"),
            mc_pressure,
            _single_row_value(pressure_header, pressure_row, "mc_error"),
            dfm,
            cl,
            _single_row_value(pressure_header, pressure_row, "cl_error_nearest"),
            isfinite(dfm) ? mc_pressure - dfm : NaN,
            isfinite(cl) ? mc_pressure - cl : NaN,
            _single_row_value(diagnostics_header, diagnostics_row, "acceptance_rate"),
            _single_row_value(diagnostics_header, diagnostics_row, "trace_samples"),
            _single_row_value(diagnostics_header, diagnostics_row, "integrated_autocorrelation_time"),
            _single_row_value(diagnostics_header, diagnostics_row, "effective_sample_size"),
            _single_row_value(diagnostics_header, diagnostics_row, "trace_drift_zscore"),
            _single_row_value(diagnostics_header, diagnostics_row, "chain_rhat"),
            _single_row_value(diagnostics_header, diagnostics_row, "split_chain_rhat"),
            _single_row_value(diagnostics_header, diagnostics_row, "production_steps"),
            _single_row_value(diagnostics_header, diagnostics_row, "production_sweeps"),
            _single_row_value(diagnostics_header, diagnostics_row, "sampling_budget_pass"),
            _single_row_value(diagnostics_header, diagnostics_row, "pressure_error_pass"),
            _single_row_value(diagnostics_header, diagnostics_row, "pressure_target_effective_sample_size"),
            _single_row_value(diagnostics_header, diagnostics_row, "required_effective_sample_size"),
            _single_row_value(diagnostics_header, diagnostics_row, "required_trace_samples"),
            _single_row_value(diagnostics_header, diagnostics_row, "estimated_required_steps"),
            _single_row_value(diagnostics_header, diagnostics_row, "estimated_required_sweeps"),
            _single_row_value(diagnostics_header, diagnostics_row, "production_budget_shortfall"),
            _single_row_value(diagnostics_header, diagnostics_row, "diagnostic_pass"),
            _single_row_value(diagnostics_header, diagnostics_row, "final_energy"),
            _single_row_value(diagnostics_header, diagnostics_row, "density_variance"),
            _single_row_value(diagnostics_header, diagnostics_row, "low_mode_structure_factor"),
            _single_row_value(diagnostics_header, diagnostics_row, "nonlinear_stability_pass"),
            _single_row_value(diagnostics_header, diagnostics_row, "nonlinear_stability_min_energy_delta"),
            _single_row_value(diagnostics_header, diagnostics_row, "nonlinear_stability_min_phi"),
        ))
    end
    finite_pressures = [p for p in pressures if isfinite(p)]
    pressure_span = isempty(finite_pressures) ? NaN : maximum(finite_pressures) - minimum(finite_pressures)
    rows = Any[]
    for row in base_rows
        push!(rows, (row..., pressure_span))
    end
    required_step_values = [Float64(row[24]) for row in rows if isfinite(Float64(row[24]))]
    required_sweep_values = [Float64(row[25]) for row in rows if isfinite(Float64(row[25]))]
    shortfall_values = [Float64(row[26]) for row in rows if isfinite(Float64(row[26]))]
    max_required_steps = isempty(required_step_values) ? NaN : maximum(required_step_values)
    max_required_sweeps = isempty(required_sweep_values) ? NaN : maximum(required_sweep_values)
    max_shortfall = isempty(shortfall_values) ? NaN : maximum(shortfall_values)
    safety = max(1.0, Float64(budget_safety_factor))
    recommended_steps = isfinite(max_required_steps) ? max(1, ceil(Int, safety * max_required_steps)) :
                        max(1, Int(steps))
    csv_path = _write_table(joinpath(outdir, "direct_floor_sensitivity.csv"),
        [
            "phi_min",
            "C",
            "mc_pressure",
            "mc_error",
            "dfm_pressure",
            "cl_pressure_nearest",
            "cl_error_nearest",
            "mc_minus_dfm",
            "mc_minus_cl",
            "acceptance_rate",
            "trace_samples",
            "integrated_autocorrelation_time",
            "effective_sample_size",
            "trace_drift_zscore",
            "chain_rhat",
            "split_chain_rhat",
            "production_steps",
            "production_sweeps",
            "sampling_budget_pass",
            "pressure_error_pass",
            "pressure_target_effective_sample_size",
            "required_effective_sample_size",
            "required_trace_samples",
            "estimated_required_steps",
            "estimated_required_sweeps",
            "production_budget_shortfall",
            "diagnostic_pass",
            "final_energy",
            "density_variance",
            "low_mode_structure_factor",
            "nonlinear_stability_pass",
            "nonlinear_stability_min_energy_delta",
            "nonlinear_stability_min_phi",
            "pressure_span",
        ], rows)
    svg_path = _write_direct_floor_sensitivity_svg(csv_path, outdir)
    markdown_path = joinpath(outdir, "direct_floor_sensitivity.md")
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear floor-sensitivity MC study")
        println(io, "==========================================")
        println(io)
        println(io, "This study runs the actual Arianna/Metropolis direct density-field sampler repeatedly while changing only the positivity floor `phi_min`.")
        println(io, "Each row is therefore a lower-bound-regularized target on truncated density-field support, with the same burn-in, striding, ESS, pressure-error, drift, R-hat, and acceptance diagnostics used by `run_pressure_sweep`.")
        println(io, @sprintf("Grid Nx = %d, C = %.6g, floors = %s.", Int(Nx), Float64(C), join(string.(floors), ", ")))
        if isfinite(pressure_span)
            println(io, @sprintf("The observed pressure span across tested floors is %.6g.", pressure_span))
        else
            println(io, "The pressure span across tested floors is not finite.")
        end
        println(io)
        for row in rows
            println(io, @sprintf(
                "- phi_min = %.6g: pressure %.6g +/- %.3g, ESS %.3g, tau_int %.3g, acceptance %.3g, diagnostic_pass %.0f.",
                Float64(row[1]),
                Float64(row[3]),
                Float64(row[4]),
                Float64(row[13]),
                Float64(row[12]),
                Float64(row[10]),
                Float64(row[27]),
            ))
        end
        println(io)
        if isfinite(max_required_steps)
            println(io, @sprintf("The largest estimated required budget is %.6g proposal steps (%.6g sweeps), with maximum budget shortfall %.6g relative to the completed production chains.", max_required_steps, max_required_sweeps, max_shortfall))
            println(io)
        end
        println(io, "Interpretation: because `phi_min` is an artificial support parameter and the unconstrained nonlinear HE-URP target is singular at the positivity boundary, these floor-dependent MC rows are not unconstrained HE-URP evidence.")
        println(io, "Use this artifact to document actual direct Arianna sampling behavior and lower-bound sensitivity, not as manuscript validation of the unconstrained nonlinear partition function.")
        println(io, "Machine-readable summary: `$(basename(csv_path))`.")
        println(io, "Comparison figure: `$(basename(svg_path))`.")
    end
    budget_plan_path = joinpath(outdir, "direct_floor_sensitivity_budget_plan.md")
    project_dir = normpath(joinpath(@__DIR__, ".."))
    c_text = @sprintf("%.6g", Float64(C))
    ess_target_text = @sprintf("%.6g", Float64(ess_target))
    pressure_tolerance_text = @sprintf("%.6g", Float64(pressure_tolerance))
    burn_fraction_text = @sprintf("%.6g", Float64(burn_fraction))
    budgeted_outdir = joinpath(project_dir, "results",
        "direct_floor_sensitivity_Nx$(Int(Nx))_C$(replace(c_text, "." => "p"))_budgeted")
    floor_text = join(string.(floors), ",")
    script_path = joinpath(project_dir, "scripts", "run_direct_floor_sensitivity_study.jl")
    open(budget_plan_path, "w") do io
        println(io, "Recommended direct floor-sensitivity rerun")
        println(io, "=========================================")
        println(io)
        println(io, "This plan is only for the lower-bound-regularized diagnostic target. It is not unconstrained HE-URP validation.")
        println(io, @sprintf("Observed maximum estimated requirement: %.6g proposal steps (%.6g sweeps).", max_required_steps, max_required_sweeps))
        println(io, @sprintf("Safety factor: %.6g.", safety))
        println(io, @sprintf("Recommended proposal-step budget: %d.", recommended_steps))
        println(io)
        println(io, "Reproducible command:")
        println(io)
        println(io, "```bash")
        println(io, "DFM_MC_OUTDIR=$budgeted_outdir \\")
        println(io, "DFM_DIRECT_FLOOR_NX=$(Int(Nx)) \\")
        println(io, "DFM_DIRECT_FLOOR_C=$c_text \\")
        println(io, "DFM_DIRECT_FLOOR_PHI_MIN_VALUES=$floor_text \\")
        println(io, "DFM_DIRECT_FLOOR_STEPS=$recommended_steps \\")
        println(io, "DFM_DIRECT_FLOOR_MAX_STEPS=$recommended_steps \\")
        println(io, "DFM_DIRECT_FLOOR_CHAINS=$(Int(chains)) \\")
        println(io, "DFM_DIRECT_FLOOR_ESS_TARGET=$ess_target_text \\")
        println(io, "DFM_DIRECT_FLOOR_MIN_TRACE_SAMPLES=$(Int(min_trace_samples)) \\")
        println(io, "DFM_DIRECT_FLOOR_PRESSURE_TOLERANCE=$pressure_tolerance_text \\")
        println(io, "DFM_DIRECT_FLOOR_BURN_FRACTION=$burn_fraction_text \\")
        println(io, "DFM_DIRECT_FLOOR_SAMPLE_STRIDE=$(Int(sample_stride)) \\")
        println(io, "  julia --startup-file=no --project=$project_dir \\")
        println(io, "  $script_path")
        println(io, "```")
        println(io)
        println(io, "Even if this rerun satisfies ESS, drift, R-hat, and budget gates, it remains a lower-bound-regularized diagnostic unless the manuscript defines that support as the physical nonlinear measure.")
    end
    _write_run_metadata(outdir, Dict{String,Any}(
        "run" => Dict{String,Any}(
            "sampler" => "arianna",
            "mode" => "direct_floor_sensitivity_study",
            "seed" => Int(seed),
        ),
        "grid" => Dict{String,Any}(
            "Nx" => Int(Nx),
            "L" => run_config(Symbol(mode)).L,
        ),
        "params" => Dict{String,Any}(
            "C" => Float64(C),
            "phi_min_values" => _toml_value(floors),
        ),
        "sampling" => Dict{String,Any}(
            "steps" => Int(steps),
            "sweeps" => _toml_value(sweeps),
            "max_steps" => _toml_value(max_steps),
            "max_sweeps" => _toml_value(max_sweeps),
            "step_growth" => Float64(step_growth),
            "chains" => Int(chains),
            "ess_target" => Float64(ess_target),
            "min_trace_samples" => Int(min_trace_samples),
            "pressure_tolerance" => _toml_value(Float64(pressure_tolerance)),
            "burn_fraction" => Float64(burn_fraction),
            "sample_stride" => Int(sample_stride),
            "tune_proposal" => Bool(tune_proposal),
            "target_acceptance" => Float64(target_acceptance),
            "tuning_rounds" => Int(tuning_rounds),
            "tuning_steps" => _toml_value(tuning_steps === nothing ? "auto" : Int(tuning_steps)),
            "budget_safety_factor" => safety,
            "recommended_steps" => recommended_steps,
            "reuse_existing" => Bool(reuse_existing),
        ),
        "outputs" => Dict{String,Any}(
            "floor_sensitivity_csv" => csv_path,
            "floor_sensitivity_markdown" => markdown_path,
            "floor_sensitivity_svg" => svg_path,
            "floor_sensitivity_budget_plan" => budget_plan_path,
            "floor_run_dirs" => subdirs,
        ),
        "environment" => _metadata_environment(),
    ))
    return (csv_path=csv_path, markdown_path=markdown_path,
            svg_path=svg_path, budget_plan_path=budget_plan_path,
            run_dirs=subdirs)
end

function _read_csv_numeric(path)
    rows = readlines(path)
    header = split(rows[1], ",")
    data = Vector{Float64}[]
    for row in rows[2:end]
        values = Float64[]
        for field in split(row, ",")
            parsed = tryparse(Float64, field)
            parsed === nothing && break
            push!(values, parsed)
        end
        push!(data, values)
    end
    return header, data
end

function write_pressure_svg(pressure_csv::AbstractString, outdir::AbstractString)
    mkpath(outdir)
    _, rows = _read_csv_numeric(pressure_csv)
    path = joinpath(outdir, "pressure_comparison.svg")
    xs = [row[1] for row in rows]
    ys = Float64[]
    for row in rows
        push!(ys, row[2])
        length(row) >= 4 && push!(ys, row[4])
        length(row) >= 5 && isfinite(row[5]) && push!(ys, row[5])
    end
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = _expand_plot_range(extrema(ys)...)
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    open(path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420' viewBox='0 0 640 420'>")
        println(io, "<title>MC vs DFM osmotic pressure</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='40' y='35' font-size='20'>MC vs DFM osmotic pressure</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        points = String[]
        for row in rows
            x = x_plot(row[1])
            y = y_plot(row[2])
            err = length(row) >= 3 ? 280 * abs(row[3]) / spany : 0.0
            push!(points, @sprintf("%.3f,%.3f", x, y))
            println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='#1f77b4'/>", x, y - err, x, y + err))
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4' fill='#1f77b4'/>", x, y))
            if length(row) >= 6 && isfinite(row[5])
                ycl = y_plot(row[5])
                clerr = 280 * abs(row[6]) / spany
                println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='#d62728'/>", x, ycl - clerr, x, ycl + clerr))
                println(io, @sprintf("<rect x='%.3f' y='%.3f' width='7' height='7' fill='none' stroke='#d62728'/>", x - 3.5, ycl - 3.5))
            end
        end
        println(io, "<polyline points='$(join(points, " "))' fill='none' stroke='#1f77b4' stroke-width='2'/>")
        println(io, "<text x='390' y='70' font-size='13' fill='#1f77b4'>circle/error: MC estimator</text>")
        println(io, "<text x='390' y='90' font-size='13' fill='#d62728'>square/error: nearest CL</text>")
        println(io, "<text class='x-axis-label' x='335' y='410' font-size='14' text-anchor='middle'>C</text>")
        println(io, "<text class='y-axis-label' x='15' y='210' font-size='14' text-anchor='middle' transform='rotate(-90 15 210)'>Pi</text>")
        println(io, "</svg>")
    end
    return path
end

function write_direct_stable_subspace_svg(
    pressure_csv::AbstractString,
    diagnostics_csv::AbstractString,
    outdir::AbstractString;
    B=1.0,
)
    mkpath(outdir)
    pressure_header, pressure_rows = _read_csv_numeric(pressure_csv)
    diagnostics_header, diagnostics_rows = _read_csv_numeric(diagnostics_csv)
    isempty(pressure_rows) && throw(ArgumentError("empty pressure comparison CSV: $pressure_csv"))
    isempty(diagnostics_rows) && throw(ArgumentError("empty diagnostics CSV: $diagnostics_csv"))
    pressure_row = first(pressure_rows)
    diagnostics_row = first(diagnostics_rows)
    C = _single_row_value(pressure_header, pressure_row, "C")
    mc = _single_row_value(pressure_header, pressure_row, "mc_pressure")
    mc_error = _single_row_value(pressure_header, pressure_row, "mc_error")
    dfm = _single_row_value(pressure_header, pressure_row, "dfm_pressure")
    cl = _single_row_value(pressure_header, pressure_row, "cl_pressure_nearest")
    cl_error = _single_row_value(pressure_header, pressure_row, "cl_error_nearest")
    mean_field = mean_field_pressure(B, C)
    min_k2 = _single_row_value(diagnostics_header, diagnostics_row, "fourier_min_k2")
    diagnostic_pass = _single_row_value(diagnostics_header, diagnostics_row, "diagnostic_pass")
    ess = _single_row_value(diagnostics_header, diagnostics_row, "effective_sample_size")
    rhat = _single_row_value(diagnostics_header, diagnostics_row, "chain_rhat")
    split_rhat = _single_row_value(diagnostics_header, diagnostics_row, "split_chain_rhat")

    labels = ["MC direct stable", "DFM grid", "CL nearest", "Mean field"]
    values = [mc, dfm, cl, mean_field]
    errors = [mc_error, 0.0, cl_error, 0.0]
    finite_indices = [idx for idx in eachindex(values) if isfinite(values[idx])]
    isempty(finite_indices) && throw(ArgumentError("no finite pressure values to plot"))
    y_values = Float64[]
    for idx in finite_indices
        err = isfinite(errors[idx]) ? abs(errors[idx]) : 0.0
        push!(y_values, values[idx] - err)
        push!(y_values, values[idx] + err)
    end
    ymin, ymax = _expand_plot_range(extrema(y_values)...)
    spany = ymax - ymin
    x_plot(v) = 95 + 455 * (Float64(v) - 1.0) / 3.0
    y_plot(v) = 360 - 280 * (Float64(v) - ymin) / spany
    xticks = collect(1.0:4.0)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks; subdivisions=4)
    y_minor_ticks = _minor_ticks(yticks)
    x_label(v) = labels[clamp(round(Int, Float64(v)), 1, length(labels))]
    path = joinpath(outdir, "direct_stable_subspace_pressure.svg")
    colors = ["#1f77b4", "#2ca02c", "#d62728", "#555555"]
    marker_shapes = ["circle", "diamond", "square", "triangle"]
    open(path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='720' height='450' viewBox='0 0 720 450'>")
        println(io, "<title>Constrained direct nonlinear MC pressure</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='40' y='34' font-size='20'>Constrained direct nonlinear MC pressure</text>")
        println(io, @sprintf("<text x='40' y='55' font-size='12' fill='#555'>stable Fourier subspace k^2 &gt;= %.6g; diagnostic_pass = %.0f; not unconstrained HE-URP</text>", min_k2, diagnostic_pass))
        println(io, @sprintf("<text x='40' y='73' font-size='12' fill='#555'>ESS %.4g, R-hat %.5g, split R-hat %.5g</text>", ess, rhat, split_rhat))
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot; x_label=x_label)
        for idx in finite_indices
            x = x_plot(idx)
            y = y_plot(values[idx])
            err = isfinite(errors[idx]) ? 280 * abs(errors[idx]) / spany : 0.0
            err > 0.0 && println(io, @sprintf("<line x1='%.3f' y1='%.3f' x2='%.3f' y2='%.3f' stroke='%s'/>", x, y - err, x, y + err, colors[idx]))
            if marker_shapes[idx] == "circle"
                println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='5' fill='%s'/>", x, y, colors[idx]))
            elseif marker_shapes[idx] == "square"
                println(io, @sprintf("<rect x='%.3f' y='%.3f' width='9' height='9' fill='none' stroke='%s' stroke-width='2'/>", x - 4.5, y - 4.5, colors[idx]))
            elseif marker_shapes[idx] == "diamond"
                println(io, @sprintf("<polygon points='%.3f,%.3f %.3f,%.3f %.3f,%.3f %.3f,%.3f' fill='%s'/>",
                    x, y - 6, x + 6, y, x, y + 6, x - 6, y, colors[idx]))
            else
                println(io, @sprintf("<polygon points='%.3f,%.3f %.3f,%.3f %.3f,%.3f' fill='%s'/>",
                    x, y - 6, x + 6, y + 6, x - 6, y + 6, colors[idx]))
            end
        end
        legend_x = 610
        for idx in eachindex(labels)
            y = 95 + 20 * (idx - 1)
            println(io, @sprintf("<text x='%d' y='%d' font-size='12' fill='%s'>%s</text>", legend_x, y, colors[idx], labels[idx]))
        end
        println(io, "<text class='x-axis-label' x='335' y='430' font-size='14' text-anchor='middle'>Estimator</text>")
        println(io, "<text class='y-axis-label' x='15' y='210' font-size='14' text-anchor='middle' transform='rotate(-90 15 210)'>Pi</text>")
        println(io, "</svg>")
    end
    return path
end

function write_diagnostics_svg(diagnostics_csv::AbstractString, outdir::AbstractString)
    mkpath(outdir)
    header, rows = _read_csv_numeric(diagnostics_csv)
    path = joinpath(outdir, "sampling_diagnostics.svg")
    xs = [row[1] for row in rows]
    acceptance_idx = something(findfirst(==("acceptance_rate"), header), 2)
    structure_idx = findfirst(==("low_mode_structure_factor"), header)
    structure_values = structure_idx === nothing ? Float64[] :
                       [row[structure_idx] for row in rows if length(row) >= structure_idx && isfinite(row[structure_idx])]
    structure_scale = isempty(structure_values) ? NaN : maximum(structure_values)
    xmin, xmax = _expand_plot_range(extrema(xs)...)
    ymin, ymax = 0.0, 1.0
    spanx = xmax - xmin
    spany = ymax - ymin
    x_plot(v) = 70 + 530 * (v - xmin) / spanx
    y_plot(v) = 360 - 280 * (v - ymin) / spany
    xticks = _major_ticks(xmin, xmax)
    yticks = _major_ticks(ymin, ymax)
    x_minor_ticks = _minor_ticks(xticks)
    y_minor_ticks = _minor_ticks(yticks)
    open(path, "w") do io
        println(io, "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='420' viewBox='0 0 640 420'>")
        println(io, "<title>Sampling diagnostics</title>")
        println(io, "<rect width='100%' height='100%' fill='white'/>")
        println(io, "<text class='plot-title' x='40' y='35' font-size='20'>Sampling diagnostics</text>")
        println(io, "<line x1='70' y1='360' x2='600' y2='360' stroke='black'/>")
        println(io, "<line x1='70' y1='60' x2='70' y2='360' stroke='black'/>")
        _write_svg_axis_ticks(io, xticks, yticks, x_minor_ticks, y_minor_ticks, x_plot, y_plot)
        for row in rows
            x = x_plot(row[1])
            y = y_plot(clamp(row[acceptance_idx], 0.0, 1.0))
            println(io, @sprintf("<circle cx='%.3f' cy='%.3f' r='4' fill='#2ca02c'/>", x, y))
            if structure_idx !== nothing && length(row) >= structure_idx && isfinite(row[structure_idx])
                normalized = structure_scale > 0.0 ? row[structure_idx] / structure_scale : 0.0
                ys = y_plot(clamp(normalized, 0.0, 1.0))
                println(io, @sprintf("<rect x='%.3f' y='%.3f' width='7' height='7' fill='none' stroke='#ff7f0e'/>", x - 3.5, ys - 3.5))
            end
        end
        println(io, "<text x='380' y='70' font-size='12' fill='#2ca02c'>acceptance</text>")
        if structure_idx !== nothing
            println(io, "<text x='380' y='88' font-size='12' fill='#ff7f0e'>normalized low-k structure factor</text>")
        end
        println(io, "<text class='x-axis-label' x='335' y='410' font-size='14' text-anchor='middle'>C</text>")
        ylabel = structure_idx === nothing ? "acceptance rate" : "acceptance / normalized S_low"
        println(io, "<text class='y-axis-label' x='12' y='235' font-size='14' text-anchor='middle' transform='rotate(-90 12 235)'>$ylabel</text>")
        println(io, "</svg>")
    end
    return path
end

function write_gaussian_mc_text(result::SweepResult, outdir::AbstractString)
    mkpath(outdir)
    path = joinpath(outdir, "gaussian_mc_validation.md")
    pressure_header, pressure_rows = _read_csv_numeric(result.pressure_csv)
    diag_header, diag_rows = _read_csv_numeric(result.diagnostics_csv)
    mc_idx = findfirst(==("mc_pressure"), pressure_header)
    err_idx = findfirst(==("mc_error"), pressure_header)
    dfm_idx = findfirst(==("dfm_pressure"), pressure_header)
    cl_idx = findfirst(==("cl_pressure_nearest"), pressure_header)
    cl_residual_idx = findfirst(==("cl_model_residual"), pressure_header)
    cl_context_idx = findfirst(==("cl_context_pass"), pressure_header)
    modes_idx = findfirst(==("stable_mode_count"), pressure_header)
    samples_idx = findfirst(==("samples"), pressure_header)
    max_samples_idx = findfirst(==("max_samples"), pressure_header)
    attempts_idx = findfirst(==("sampling_attempts"), pressure_header)
    chains_idx = findfirst(==("chain_count"), pressure_header)
    within_idx = findfirst(==("within_chain_stderr"), pressure_header)
    between_idx = findfirst(==("between_chain_stderr"), pressure_header)
    pass_idx = findfirst(==("diagnostic_pass"), diag_header)
    ref_pass_idx = findfirst(==("reference_agreement_pass"), diag_header)
    budget_pass_idx = findfirst(==("sampling_budget_pass"), diag_header)
    ref_z_idx = findfirst(==("reference_zscore"), diag_header)
    required_samples_idx = findfirst(==("required_samples_per_chain"), diag_header)
    sampler_label = "gaussian_mode_mc"
    try
        string_header, string_rows = _read_csv_strings(result.pressure_csv)
        sampler_idx = findfirst(==("sampler"), string_header)
        if sampler_idx !== nothing && !isempty(string_rows) && length(first(string_rows)) >= sampler_idx
            sampler_label = first(string_rows)[sampler_idx]
        end
    catch
        sampler_label = "gaussian_mode_mc"
    end
    random_sample_unit = sampler_label == "gaussian_field_mc" ? "random field-amplitude samples" :
                         sampler_label == "gaussian_field_configuration_mc" ? "random field-configuration samples" :
                         "random mode samples"
    max_dfm_error = isempty(pressure_rows) ? NaN :
                    maximum(abs(row[mc_idx] - row[dfm_idx]) for row in pressure_rows if length(row) >= dfm_idx)
    max_mc_error = isempty(pressure_rows) ? NaN :
                   maximum(row[err_idx] for row in pressure_rows if length(row) >= err_idx)
    max_cl_error = cl_idx === nothing || isempty(pressure_rows) ? NaN :
                   maximum(abs(row[mc_idx] - row[cl_idx]) for row in pressure_rows if length(row) >= cl_idx && isfinite(row[cl_idx]))
    cl_residual_values = cl_residual_idx === nothing ? Float64[] :
                         [abs(row[cl_residual_idx]) for row in pressure_rows if length(row) >= cl_residual_idx && isfinite(row[cl_residual_idx])]
    max_cl_model_residual = isempty(cl_residual_values) ? NaN : maximum(cl_residual_values)
    cl_context_values = cl_context_idx === nothing ? Float64[] :
                        [row[cl_context_idx] for row in pressure_rows if length(row) >= cl_context_idx && isfinite(row[cl_context_idx])]
    cl_context_pass_count = count(x -> x >= 0.5, cl_context_values)
    max_modes = modes_idx === nothing || isempty(pressure_rows) ? NaN :
                maximum(row[modes_idx] for row in pressure_rows if length(row) >= modes_idx)
    max_samples = samples_idx === nothing || isempty(pressure_rows) ? NaN :
                  maximum(row[samples_idx] for row in pressure_rows if length(row) >= samples_idx)
    max_sample_budget = max_samples_idx === nothing || isempty(pressure_rows) ? NaN :
                        maximum(row[max_samples_idx] for row in pressure_rows if length(row) >= max_samples_idx)
    max_sampling_attempts = attempts_idx === nothing || isempty(pressure_rows) ? NaN :
                            maximum(row[attempts_idx] for row in pressure_rows if length(row) >= attempts_idx)
    max_chains = chains_idx === nothing || isempty(pressure_rows) ? NaN :
                 maximum(row[chains_idx] for row in pressure_rows if length(row) >= chains_idx)
    max_within_stderr = within_idx === nothing || isempty(pressure_rows) ? NaN :
                        maximum(row[within_idx] for row in pressure_rows if length(row) >= within_idx)
    max_between_stderr = between_idx === nothing || isempty(pressure_rows) ? NaN :
                         maximum(row[between_idx] for row in pressure_rows if length(row) >= between_idx)
    max_reference_zscore = ref_z_idx === nothing || isempty(diag_rows) ? NaN :
                           maximum(row[ref_z_idx] for row in diag_rows if length(row) >= ref_z_idx && isfinite(row[ref_z_idx]))
    max_required_samples = required_samples_idx === nothing || isempty(diag_rows) ? NaN :
                           maximum(row[required_samples_idx] for row in diag_rows if length(row) >= required_samples_idx && isfinite(row[required_samples_idx]))
    pass_count = pass_idx === nothing ? 0 :
                 count(row -> length(row) >= pass_idx && row[pass_idx] >= 0.5, diag_rows)
    ref_pass_count = ref_pass_idx === nothing ? 0 :
                     count(row -> length(row) >= ref_pass_idx && row[ref_pass_idx] >= 0.5, diag_rows)
    budget_pass_count = budget_pass_idx === nothing ? 0 :
                        count(row -> length(row) >= budget_pass_idx && row[budget_pass_idx] >= 0.5, diag_rows)
    gate_count = length(diag_rows)
    open(path, "w") do io
        println(io, "Gaussian HE-URP perturbation Monte Carlo")
        println(io, "========================================")
        println(io)
        if sampler_label == "gaussian_field_mc"
            println(io, "This validation samples Gaussian field-amplitudes for stable Fourier modes in the Gaussian expansion around phi = 1.")
        elseif sampler_label == "gaussian_field_configuration_mc"
            println(io, "This validation samples Gaussian field configurations over all stable Fourier modes in the Gaussian expansion around phi = 1.")
        else
            println(io, "This validation samples the stable Fourier-mode pressure correction of the Gaussian expansion around phi = 1.")
        end
        println(io, "It is a conventional Monte Carlo estimate of the same finite-grid DFM mode sum used by `dfm_pressure_discrete`; it is not the nonlinear direct-density Arianna sampler.")
        println(io, @sprintf("The effective grid was Nx = %d, with manuscript target Nx = %d and alpha = %.3g.", result.config.Nx, result.config.target_Nx, result.config.alpha))
        if isfinite(max_samples) && isfinite(max_chains) && isfinite(max_modes)
            println(io, @sprintf("The largest state point used %.0f %s per chain, %.0f chains, and %.0f stable Fourier modes.", max_samples, random_sample_unit, max_chains, max_modes))
        end
        if isfinite(max_sample_budget) && isfinite(max_sampling_attempts)
            println(io, @sprintf("The adaptive sampler allowed up to %.0f %s per chain and used up to %.0f sampling attempt(s).", max_sample_budget, random_sample_unit, max_sampling_attempts))
        end
        if isfinite(max_dfm_error) && isfinite(max_mc_error)
            println(io, @sprintf("The maximum absolute MC deviation from the exact finite-grid DFM pressure was %.3g, with maximum reported MC standard error %.3g.", max_dfm_error, max_mc_error))
        end
        if isfinite(max_within_stderr) && isfinite(max_between_stderr)
            println(io, @sprintf("The reported MC standard error is the conservative maximum of the within-chain standard error and between-chain standard error; their maxima were %.3g and %.3g.", max_within_stderr, max_between_stderr))
        end
        if isfinite(max_reference_zscore)
            println(io, @sprintf("The largest MC-vs-DFM reference z-score was %.3g.", max_reference_zscore))
        end
        if isfinite(max_required_samples)
            println(io, @sprintf("The largest estimated sample-budget requirement was %.0f %s per chain for the configured pressure tolerance.", max_required_samples, random_sample_unit))
        end
        if isfinite(max_cl_error)
            println(io, @sprintf("The maximum absolute deviation from the nearest representative CL pressure was %.3g; this comparison includes both DFM model error and MC statistical error.", max_cl_error))
        end
        if isfinite(max_cl_model_residual)
            println(io, @sprintf("The finite-grid DFM-vs-CL model offset is tracked separately; the maximum residual after subtracting that offset was %.3g, and %.0f of %.0f CL-context rows passed the finite-grid DFM agreement gate.", max_cl_model_residual, cl_context_pass_count, length(cl_context_values)))
        end
        if ref_pass_idx !== nothing && budget_pass_idx !== nothing
            println(io, @sprintf("The diagnostic gate used pressure-error, reference-agreement, and sample-budget checks; %.0f of %.0f state points passed all gates (reference %.0f/%.0f, sample-budget %.0f/%.0f).", pass_count, gate_count, ref_pass_count, gate_count, budget_pass_count, gate_count))
        else
            println(io, @sprintf("The diagnostic gate used the configured pressure-error tolerance; %.0f of %.0f state points passed.", pass_count, gate_count))
        end
        if gate_count > 0 && pass_count == gate_count
            println(io, "Current status: finite-grid perturbation validation. The Gaussian MC estimator reproduces the finite-grid DFM pressure within its statistical uncertainty.")
        else
            println(io, "Current status: diagnostic perturbation run. Increase random mode samples or relax the pressure tolerance before using this as manuscript validation evidence.")
        end
    end
    return path
end

function write_gaussian_analysis_summary(outdir::AbstractString; filename="gaussian_analysis_validation.md")
    paths = sort(filter(path -> endswith(basename(path), "_gaussian_mc_comparison.csv"), readdir(outdir; join=true)))
    path = joinpath(outdir, filename)
    csv_count = length(paths)
    row_count = 0
    pass_count = 0
    max_dfm_error = NaN
    max_mc_error = NaN
    max_cl_error = NaN
    max_cl_model_residual = NaN
    max_samples = NaN
    max_sample_budget = NaN
    max_sampling_attempts = NaN
    max_chains = NaN
    max_within_stderr = NaN
    max_between_stderr = NaN
    max_effective_samples = NaN
    max_reference_zscore = NaN
    max_required_samples = NaN
    max_modes = NaN
    alpha = NaN
    worst_dfm = ""
    worst_cl = ""
    worst_cl_residual = ""
    reference_pass_count = 0
    reference_gate_count = 0
    budget_pass_count = 0
    budget_gate_count = 0
    cl_context_pass_count = 0
    cl_context_gate_count = 0
    sampler_counts = Dict{String,Int}()

    function update_max(current, candidate)
        isfinite(candidate) || return current
        return !isfinite(current) || candidate > current ? candidate : current
    end

    for csv_path in paths
        header, rows = _read_csv_strings(csv_path)
        axis_idx = findfirst(==("axis"), header)
        mc_idx = findfirst(==("mc_pressure"), header)
        err_idx = findfirst(==("mc_error"), header)
        dfm_idx = findfirst(==("dfm_pressure"), header)
        cl_idx = findfirst(==("cl_pressure"), header)
        cl_residual_idx = findfirst(==("cl_model_residual"), header)
        cl_context_idx = findfirst(==("cl_context_pass"), header)
        pass_idx = findfirst(==("diagnostic_pass"), header)
        ref_pass_idx = findfirst(==("reference_agreement_pass"), header)
        budget_pass_idx = findfirst(==("sampling_budget_pass"), header)
        ref_z_idx = findfirst(==("reference_zscore"), header)
        required_samples_idx = findfirst(==("required_samples_per_chain"), header)
        samples_idx = findfirst(==("samples"), header)
        max_samples_idx = findfirst(==("max_samples"), header)
        attempts_idx = findfirst(==("sampling_attempts"), header)
        chains_idx = findfirst(==("chain_count"), header)
        sampler_idx = findfirst(==("sampler"), header)
        within_idx = findfirst(==("within_chain_stderr"), header)
        between_idx = findfirst(==("between_chain_stderr"), header)
        ess_idx = findfirst(==("effective_sample_size"), header)
        modes_idx = findfirst(==("stable_mode_count"), header)
        alpha_idx = findfirst(==("alpha"), header)
        for row in rows
            row_count += 1
            if sampler_idx !== nothing && length(row) >= sampler_idx
                sampler = isempty(row[sampler_idx]) ? "unknown" : row[sampler_idx]
                sampler_counts[sampler] = get(sampler_counts, sampler, 0) + 1
            end
            if pass_idx !== nothing && length(row) >= pass_idx && parse(Float64, row[pass_idx]) >= 0.5
                pass_count += 1
            end
            if ref_pass_idx !== nothing && length(row) >= ref_pass_idx
                reference_gate_count += 1
                parse(Float64, row[ref_pass_idx]) >= 0.5 && (reference_pass_count += 1)
            end
            if budget_pass_idx !== nothing && length(row) >= budget_pass_idx
                budget_gate_count += 1
                parse(Float64, row[budget_pass_idx]) >= 0.5 && (budget_pass_count += 1)
            end
            if cl_context_idx !== nothing && length(row) >= cl_context_idx
                cl_context = parse(Float64, row[cl_context_idx])
                if isfinite(cl_context)
                    cl_context_gate_count += 1
                    cl_context >= 0.5 && (cl_context_pass_count += 1)
                end
            end
            if mc_idx !== nothing && dfm_idx !== nothing && length(row) >= max(mc_idx, dfm_idx)
                mc = parse(Float64, row[mc_idx])
                dfm = parse(Float64, row[dfm_idx])
                delta = abs(mc - dfm)
                if !isfinite(max_dfm_error) || delta > max_dfm_error
                    max_dfm_error = delta
                    axis_label = axis_idx === nothing || length(row) < axis_idx ? "unknown" : row[axis_idx]
                    worst_dfm = "$(basename(csv_path)) axis=$axis_label"
                end
            end
            if mc_idx !== nothing && cl_idx !== nothing && length(row) >= max(mc_idx, cl_idx)
                mc = parse(Float64, row[mc_idx])
                cl = parse(Float64, row[cl_idx])
                if isfinite(cl)
                    delta = abs(mc - cl)
                    if !isfinite(max_cl_error) || delta > max_cl_error
                        max_cl_error = delta
                        axis_label = axis_idx === nothing || length(row) < axis_idx ? "unknown" : row[axis_idx]
                        worst_cl = "$(basename(csv_path)) axis=$axis_label"
                    end
                end
            end
            if cl_residual_idx !== nothing && length(row) >= cl_residual_idx
                residual = parse(Float64, row[cl_residual_idx])
                if isfinite(residual)
                    delta = abs(residual)
                    if !isfinite(max_cl_model_residual) || delta > max_cl_model_residual
                        max_cl_model_residual = delta
                        axis_label = axis_idx === nothing || length(row) < axis_idx ? "unknown" : row[axis_idx]
                        worst_cl_residual = "$(basename(csv_path)) axis=$axis_label"
                    end
                end
            end
            if err_idx !== nothing && length(row) >= err_idx
                max_mc_error = update_max(max_mc_error, parse(Float64, row[err_idx]))
            end
            if samples_idx !== nothing && length(row) >= samples_idx
                max_samples = update_max(max_samples, parse(Float64, row[samples_idx]))
            end
            if max_samples_idx !== nothing && length(row) >= max_samples_idx
                max_sample_budget = update_max(max_sample_budget, parse(Float64, row[max_samples_idx]))
            end
            if attempts_idx !== nothing && length(row) >= attempts_idx
                max_sampling_attempts = update_max(max_sampling_attempts, parse(Float64, row[attempts_idx]))
            end
            if chains_idx !== nothing && length(row) >= chains_idx
                max_chains = update_max(max_chains, parse(Float64, row[chains_idx]))
            end
            if within_idx !== nothing && length(row) >= within_idx
                max_within_stderr = update_max(max_within_stderr, parse(Float64, row[within_idx]))
            end
            if between_idx !== nothing && length(row) >= between_idx
                max_between_stderr = update_max(max_between_stderr, parse(Float64, row[between_idx]))
            end
            if ess_idx !== nothing && length(row) >= ess_idx
                max_effective_samples = update_max(max_effective_samples, parse(Float64, row[ess_idx]))
            end
            if ref_z_idx !== nothing && length(row) >= ref_z_idx
                max_reference_zscore = update_max(max_reference_zscore, parse(Float64, row[ref_z_idx]))
            end
            if required_samples_idx !== nothing && length(row) >= required_samples_idx
                max_required_samples = update_max(max_required_samples, parse(Float64, row[required_samples_idx]))
            end
            if modes_idx !== nothing && length(row) >= modes_idx
                max_modes = update_max(max_modes, parse(Float64, row[modes_idx]))
            end
            if alpha_idx !== nothing && length(row) >= alpha_idx
                parsed_alpha = parse(Float64, row[alpha_idx])
                isfinite(parsed_alpha) && (alpha = parsed_alpha)
            end
        end
    end

    sampler_keys = sort(collect(keys(sampler_counts)))
    all_field = !isempty(sampler_keys) && all(==("gaussian_field_mc"), sampler_keys)
    all_field_configuration = !isempty(sampler_keys) && all(==("gaussian_field_configuration_mc"), sampler_keys)
    all_mode = !isempty(sampler_keys) && all(==("gaussian_mode_mc"), sampler_keys)
    sample_unit = all_field ? "field-amplitude samples" :
                  all_field_configuration ? "field-configuration samples" :
                  all_mode ? "mode samples" :
                  "perturbative samples"
    random_sample_unit = all_field ? "random field-amplitude samples" :
                         all_field_configuration ? "random field-configuration samples" :
                         all_mode ? "random mode samples" :
                         "random perturbative samples"
    estimator_description = all_field ?
                            "The MC estimator samples independent Gaussian field-amplitudes for stable Fourier modes and compares them with the same finite-grid DFM mode sum." :
                            all_field_configuration ?
                            "The MC estimator samples independent Gaussian field configurations over all stable Fourier modes and compares them with the same finite-grid DFM mode sum." :
                            all_mode ?
                            "The MC estimator samples independent Fourier-mode pressure contributions and compares them with the same finite-grid DFM mode sum." :
                            "The MC estimator samples independent perturbative Gaussian contributions and compares them with the same finite-grid DFM mode sum."
    sampler_summary = isempty(sampler_counts) ? "" :
                      join(["$key=$(sampler_counts[key])" for key in sampler_keys], ", ")

    open(path, "w") do io
        println(io, "Gaussian Analysis MC validation")
        println(io, "===============================")
        println(io)
        println(io, "This summary scans the Gaussian perturbation Monte Carlo overlays generated for the Analysis figure specifications.")
        println(io, estimator_description)
        !isempty(sampler_summary) && println(io, "Sampler rows: $sampler_summary.")
        if isfinite(alpha)
            println(io, @sprintf("The comparison uses alpha = %.3g and the Analysis grid convention.", alpha))
        end
        println(io, @sprintf("The directory contains %.0f comparison CSVs and %.0f sampled MC points.", csv_count, row_count))
        if isfinite(max_samples) && isfinite(max_chains) && isfinite(max_effective_samples)
            println(io, @sprintf("The largest point used %.0f independent %s per chain, %.0f chains, and %.0f total independent samples.", max_samples, sample_unit, max_chains, max_effective_samples))
        end
        if isfinite(max_sample_budget) && isfinite(max_sampling_attempts)
            println(io, @sprintf("The adaptive sampler allowed up to %.0f independent %s per chain and used up to %.0f sampling attempt(s).", max_sample_budget, sample_unit, max_sampling_attempts))
        end
        if isfinite(max_modes)
            println(io, @sprintf("The largest stable-mode set contained %.0f Fourier modes.", max_modes))
        end
        if reference_gate_count > 0 && budget_gate_count > 0
            println(io, @sprintf("%.0f of %.0f MC points passed the combined pressure-error, reference-agreement, and sample-budget diagnostic gate (reference %.0f/%.0f, sample-budget %.0f/%.0f).", pass_count, row_count, reference_pass_count, reference_gate_count, budget_pass_count, budget_gate_count))
        else
            println(io, @sprintf("%.0f of %.0f MC points passed the configured pressure-error diagnostic gate.", pass_count, row_count))
        end
        if isfinite(max_dfm_error) && isfinite(max_mc_error)
            println(io, @sprintf("The maximum absolute MC deviation from finite-grid DFM was %.3g, with maximum reported MC standard error %.3g.", max_dfm_error, max_mc_error))
            !isempty(worst_dfm) && println(io, "The largest MC-vs-DFM deviation occurred at `$worst_dfm`.")
        end
        if isfinite(max_within_stderr) && isfinite(max_between_stderr)
            println(io, @sprintf("The reported MC standard error is the conservative maximum of within-chain and between-chain standard errors; their maxima were %.3g and %.3g.", max_within_stderr, max_between_stderr))
        end
        if isfinite(max_reference_zscore)
            println(io, @sprintf("The largest MC-vs-DFM reference z-score was %.3g.", max_reference_zscore))
        end
        if isfinite(max_required_samples)
            println(io, @sprintf("The largest estimated sample-budget requirement was %.0f %s per chain.", max_required_samples, random_sample_unit))
        end
        if isfinite(max_cl_error)
            println(io, @sprintf("The maximum absolute MC deviation from CL was %.3g; this includes finite-grid DFM model discrepancy and MC statistical error.", max_cl_error))
            !isempty(worst_cl) && println(io, "The largest MC-vs-CL deviation occurred at `$worst_cl`.")
        end
        if isfinite(max_cl_model_residual)
            println(io, @sprintf("The finite-grid DFM-vs-CL model offset is tracked separately; the maximum residual after subtracting that offset was %.3g.", max_cl_model_residual))
            !isempty(worst_cl_residual) && println(io, "The largest CL-context residual occurred at `$worst_cl_residual`.")
            cl_context_gate_count > 0 && println(io, @sprintf("The CL-context gate passed for %.0f of %.0f rows; it asks whether MC reproduces finite-grid DFM after the DFM-vs-CL model offset is accounted for.", cl_context_pass_count, cl_context_gate_count))
        end
        if row_count > 0 && pass_count == row_count
            println(io, "Current status: manuscript-ready perturbation MC overlays. These files validate the finite-grid DFM pressure curve by conventional independent Monte Carlo sampling.")
        else
            println(io, "Current status: diagnostic perturbation MC overlays. Increase independent mode samples or relax the pressure tolerance before using all rows as manuscript evidence.")
        end
    end
    return path
end

function _parse_audit_float(row::AbstractVector{<:AbstractString}, idx)
    idx === nothing && return NaN
    length(row) >= idx || return NaN
    parsed = tryparse(Float64, row[idx])
    return parsed === nothing ? NaN : parsed
end

function _audit_update_max!(stats::Dict{String,Any}, key::String, value::Real)
    value_float = Float64(value)
    isfinite(value_float) || return stats
    current = Float64(get(stats, key, NaN))
    stats[key] = !isfinite(current) || value_float > current ? value_float : current
    return stats
end

function _audit_update_min!(stats::Dict{String,Any}, key::String, value::Real)
    value_float = Float64(value)
    isfinite(value_float) || return stats
    current = Float64(get(stats, key, NaN))
    stats[key] = !isfinite(current) || value_float < current ? value_float : current
    return stats
end

function _audit_increment_count!(stats::Dict{String,Any}, key::String, value::AbstractString)
    counts = get!(stats, key, Dict{String,Any}())
    label = isempty(value) ? "unknown" : String(value)
    counts[label] = Int(get(counts, label, 0)) + 1
    return stats
end

function _audit_count_summary(counts)
    isempty(counts) && return "none"
    return join(["$key=$(counts[key])" for key in sort(collect(keys(counts)))], ", ")
end

function _gaussian_audit_paths(dir::AbstractString)
    isdir(dir) || return String[]
    paths = sort(filter(path -> endswith(basename(path), "_gaussian_mc_comparison.csv"),
        readdir(dir; join=true)))
    diagnostics = joinpath(dir, "gaussian_sampling_diagnostics.csv")
    isfile(diagnostics) && push!(paths, diagnostics)
    sample_size = joinpath(dir, "gaussian_sample_size_study.csv")
    isfile(sample_size) && push!(paths, sample_size)
    return paths
end

function _direct_audit_paths(dir::AbstractString)
    diagnostics = joinpath(dir, "sampling_diagnostics.csv")
    return isfile(diagnostics) ? [diagnostics] : String[]
end

function _stability_probe_audit_paths(dir::AbstractString)
    probe = joinpath(dir, "direct_stability_probe.csv")
    return isfile(probe) ? [probe] : String[]
end

function _boundary_asymptotic_audit_paths(dir::AbstractString)
    path = joinpath(dir, "direct_boundary_asymptotic_scan.csv")
    return isfile(path) ? [path] : String[]
end

function _floor_sensitivity_audit_paths(dir::AbstractString)
    path = joinpath(dir, "direct_floor_sensitivity.csv")
    return isfile(path) ? [path] : String[]
end

function _boundary_ray_audit_paths(dir::AbstractString)
    path = joinpath(dir, "direct_boundary_ray_summary.csv")
    return isfile(path) ? [path] : String[]
end

