        "total_points" => 0,
        "passed_points" => 0,
        "reference_passed_points" => 0,
        "sample_budget_passed_points" => 0,
        "max_reference_error" => NaN,
        "max_reference_zscore" => NaN,
        "max_mc_error" => NaN,
        "max_samples_per_chain" => NaN,
        "max_total_independent_samples" => NaN,
        "max_required_samples_per_chain" => NaN,
        "finite_cl_points" => 0,
        "cl_context_passed_points" => 0,
        "max_cl_model_residual" => NaN,
        "sampler_counts" => Dict{String,Any}(),
    )
end

