function _scan_gaussian_audit!(stats::Dict{String,Any}, paths::Vector{String})
    for csv_path in paths
        stats["csv_count"] = Int(stats["csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        pass_idx = findfirst(==("diagnostic_pass"), header)
        ref_pass_idx = findfirst(==("reference_agreement_pass"), header)
        budget_pass_idx = findfirst(==("sampling_budget_pass"), header)
        ref_error_idx = findfirst(==("reference_error"), header)
        ref_z_idx = findfirst(==("reference_zscore"), header)
        mc_error_idx = findfirst(==("mc_error"), header)
        samples_idx = findfirst(==("samples"), header)
        chains_idx = findfirst(==("chain_count"), header)
        effective_idx = findfirst(==("effective_sample_size"), header)
        required_idx = findfirst(==("required_samples_per_chain"), header)
        sampler_idx = findfirst(==("sampler"), header)
        cl_idx = findfirst(name -> name in ("cl_pressure_nearest", "cl_pressure"), header)
        cl_context_idx = findfirst(==("cl_context_pass"), header)
        cl_residual_idx = findfirst(==("cl_model_residual"), header)
        for row in rows
            stats["total_points"] = Int(stats["total_points"]) + 1
            sampler = sampler_idx === nothing || length(row) < sampler_idx ? "unknown" : row[sampler_idx]
            _audit_increment_count!(stats, "sampler_counts", sampler)
            pass_value = _parse_audit_float(row, pass_idx)
            ref_pass_value = _parse_audit_float(row, ref_pass_idx)
            budget_pass_value = _parse_audit_float(row, budget_pass_idx)
            isfinite(pass_value) && pass_value >= 0.5 && (stats["passed_points"] = Int(stats["passed_points"]) + 1)
            isfinite(ref_pass_value) && ref_pass_value >= 0.5 && (stats["reference_passed_points"] = Int(stats["reference_passed_points"]) + 1)
            isfinite(budget_pass_value) && budget_pass_value >= 0.5 && (stats["sample_budget_passed_points"] = Int(stats["sample_budget_passed_points"]) + 1)
            _audit_update_max!(stats, "max_reference_error", _parse_audit_float(row, ref_error_idx))
            _audit_update_max!(stats, "max_reference_zscore", _parse_audit_float(row, ref_z_idx))
            _audit_update_max!(stats, "max_mc_error", _parse_audit_float(row, mc_error_idx))
            samples = _parse_audit_float(row, samples_idx)
            chains = _parse_audit_float(row, chains_idx)
            effective = _parse_audit_float(row, effective_idx)
            _audit_update_max!(stats, "max_samples_per_chain", samples)
            if isfinite(effective)
                _audit_update_max!(stats, "max_total_independent_samples", effective)
            elseif isfinite(samples) && isfinite(chains)
                _audit_update_max!(stats, "max_total_independent_samples", samples * chains)
            end
            _audit_update_max!(stats, "max_required_samples_per_chain", _parse_audit_float(row, required_idx))
            cl_value = _parse_audit_float(row, cl_idx)
            if isfinite(cl_value)
                stats["finite_cl_points"] = Int(stats["finite_cl_points"]) + 1
                cl_context = _parse_audit_float(row, cl_context_idx)
                isfinite(cl_context) && cl_context >= 0.5 &&
                    (stats["cl_context_passed_points"] = Int(stats["cl_context_passed_points"]) + 1)
                residual = _parse_audit_float(row, cl_residual_idx)
                _audit_update_max!(stats, "max_cl_model_residual", abs(residual))
            end
        end
    end
    return stats
end

function _scan_direct_audit!(stats::Dict{String,Any}, paths::Vector{String})
    for csv_path in paths
        stats["csv_count"] = Int(stats["csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        pass_idx = findfirst(==("diagnostic_pass"), header)
        stability_idx = findfirst(==("nonlinear_stability_pass"), header)
        budget_idx = findfirst(==("sampling_budget_pass"), header)
        stability_delta_idx = findfirst(==("nonlinear_stability_min_energy_delta"), header)
        stability_phi_idx = findfirst(==("nonlinear_stability_min_phi"), header)
        steps_idx = findfirst(==("production_steps"), header)
        sweeps_idx = findfirst(==("production_sweeps"), header)
        ess_idx = findfirst(==("effective_sample_size"), header)
        structure_idx = findfirst(==("low_mode_structure_factor"), header)
        basin_cap_idx = findfirst(==("basin_variance_max"), header)
        basin_pass_idx = findfirst(==("basin_constraint_pass"), header)
        barrier_idx = findfirst(==("boundary_barrier_strength"), header)
        stable_idx = findfirst(==("stable_mode_proposals"), header)
        fourier_min_idx = findfirst(==("fourier_min_k2"), header)
        phi_min_idx = findfirst(==("phi_min"), header)
        target_model_idx = findfirst(==("target_model_code"), header)
        if phi_min_idx === nothing
            stats["phi_min_missing_csv_count"] = Int(stats["phi_min_missing_csv_count"]) + 1
        else
            stats["phi_min_present_csv_count"] = Int(stats["phi_min_present_csv_count"]) + 1
        end
        for row in rows
            stats["total_points"] = Int(stats["total_points"]) + 1
            pass_value = _parse_audit_float(row, pass_idx)
            stability_value = _parse_audit_float(row, stability_idx)
            budget_value = _parse_audit_float(row, budget_idx)
            isfinite(pass_value) && pass_value >= 0.5 && (stats["passed_points"] = Int(stats["passed_points"]) + 1)
            isfinite(stability_value) && stability_value >= 0.5 && (stats["stability_passed_points"] = Int(stats["stability_passed_points"]) + 1)
            isfinite(budget_value) && budget_value >= 0.5 && (stats["budget_passed_points"] = Int(stats["budget_passed_points"]) + 1)
            _audit_update_min!(stats, "min_nonlinear_stability_energy_delta", _parse_audit_float(row, stability_delta_idx))
            _audit_update_min!(stats, "min_nonlinear_stability_phi", _parse_audit_float(row, stability_phi_idx))
            _audit_update_max!(stats, "max_production_steps", _parse_audit_float(row, steps_idx))
            _audit_update_max!(stats, "max_production_sweeps", _parse_audit_float(row, sweeps_idx))
            ess = _parse_audit_float(row, ess_idx)
            _audit_update_min!(stats, "min_effective_sample_size", ess)
            _audit_update_max!(stats, "max_effective_sample_size", ess)
            _audit_update_max!(stats, "max_low_mode_structure_factor", _parse_audit_float(row, structure_idx))
            phi_min = _parse_audit_float(row, phi_min_idx)
            _audit_update_max!(stats, "max_phi_min", phi_min)
            basin_cap = _parse_audit_float(row, basin_cap_idx)
            if isfinite(basin_cap)
                stats["finite_basin_points"] = Int(stats["finite_basin_points"]) + 1
                _audit_update_max!(stats, "max_basin_variance_max", basin_cap)
                basin_pass = _parse_audit_float(row, basin_pass_idx)
                isfinite(basin_pass) && basin_pass >= 0.5 &&
                    (stats["basin_passed_points"] = Int(stats["basin_passed_points"]) + 1)
            end
            stable_flag = _parse_audit_float(row, stable_idx)
            if isfinite(stable_flag) && stable_flag >= 0.5
                stats["stable_subspace_points"] = Int(stats["stable_subspace_points"]) + 1
                isfinite(pass_value) && pass_value >= 0.5 &&
                    (stats["stable_subspace_passed_points"] = Int(stats["stable_subspace_passed_points"]) + 1)
                _audit_update_max!(stats, "max_fourier_min_k2", _parse_audit_float(row, fourier_min_idx))
            end
            barrier_strength = _parse_audit_float(row, barrier_idx)
            barrier_active = isfinite(barrier_strength) && barrier_strength > 0.0
            if barrier_active
                stats["boundary_barrier_points"] = Int(stats["boundary_barrier_points"]) + 1
                _audit_update_max!(stats, "max_boundary_barrier_strength", barrier_strength)
                isfinite(pass_value) && pass_value >= 0.5 &&
                    (stats["boundary_barrier_passed_points"] =
                        Int(stats["boundary_barrier_passed_points"]) + 1)
            end
            modified_target = isfinite(basin_cap) || (isfinite(stable_flag) && stable_flag >= 0.5) ||
                              barrier_active
            default_positive_support = isfinite(phi_min) && phi_min <= 1.0e-6
            if modified_target
                stats["modified_target_points"] = Int(stats["modified_target_points"]) + 1
            elseif default_positive_support
                stats["unconstrained_points"] = Int(stats["unconstrained_points"]) + 1
                accepted_unconstrained = isfinite(pass_value) && pass_value >= 0.5 &&
                                         isfinite(stability_value) && stability_value >= 0.5 &&
                                         isfinite(budget_value) && budget_value >= 0.5
                target_model_code = _parse_audit_float(row, target_model_idx)
                if accepted_unconstrained
                    stats["accepted_unconstrained_points"] = Int(stats["accepted_unconstrained_points"]) + 1
                    if isfinite(target_model_code) && target_model_code >= 1.5
                        stats["accepted_unconstrained_hevk1_points"] =
                            Int(stats["accepted_unconstrained_hevk1_points"]) + 1
                    elseif isfinite(target_model_code) && target_model_code >= 0.5
                        stats["accepted_unconstrained_heurp_points"] =
                            Int(stats["accepted_unconstrained_heurp_points"]) + 1
                    end
                else
                    stats["diagnostic_unconstrained_points"] = Int(stats["diagnostic_unconstrained_points"]) + 1
                    if isfinite(target_model_code) && target_model_code >= 1.5
                        stats["diagnostic_unconstrained_hevk1_points"] =
                            Int(stats["diagnostic_unconstrained_hevk1_points"]) + 1
                    elseif isfinite(target_model_code) && target_model_code >= 0.5
                        stats["diagnostic_unconstrained_heurp_points"] =
                            Int(stats["diagnostic_unconstrained_heurp_points"]) + 1
                    end
                end
            end
        end
    end
    return stats
end

function _scan_stability_probe_audit!(stats::Dict{String,Any}, paths::Vector{String})
    for csv_path in paths
        stats["stability_probe_csv_count"] = Int(stats["stability_probe_csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        delta_idx = findfirst(==("energy_delta"), header)
        min_phi_idx = findfirst(==("min_phi"), header)
        for row in rows
            stats["stability_probe_points"] = Int(stats["stability_probe_points"]) + 1
            _audit_update_min!(stats, "stability_probe_min_energy_delta", _parse_audit_float(row, delta_idx))
            _audit_update_min!(stats, "stability_probe_min_phi", _parse_audit_float(row, min_phi_idx))
        end
    end
    return stats
end

function _scan_boundary_asymptotic_audit!(stats::Dict{String,Any}, paths::Vector{String})
    for csv_path in paths
        stats["boundary_asymptotic_csv_count"] = Int(stats["boundary_asymptotic_csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        slope_idx = findfirst(==("log_boundary_slope"), header)
        unbounded_idx = findfirst(==("asymptotic_unbounded_below"), header)
        corrected_slope_idx = findfirst(==("jacobian_corrected_log_slope"), header)
        corrected_unbounded_idx = findfirst(==("jacobian_corrected_unbounded_below"), header)
        for row in rows
            stats["boundary_asymptotic_points"] = Int(stats["boundary_asymptotic_points"]) + 1
            slope = _parse_audit_float(row, slope_idx)
            _audit_update_max!(stats, "max_boundary_asymptotic_log_slope", slope)
            unbounded = _parse_audit_float(row, unbounded_idx)
            isfinite(unbounded) && unbounded >= 0.5 &&
                (stats["boundary_asymptotic_unbounded_points"] = Int(stats["boundary_asymptotic_unbounded_points"]) + 1)
            corrected_slope = _parse_audit_float(row, corrected_slope_idx)
            _audit_update_max!(stats, "max_boundary_asymptotic_jacobian_corrected_log_slope", corrected_slope)
            corrected_unbounded = _parse_audit_float(row, corrected_unbounded_idx)
            isfinite(corrected_unbounded) && corrected_unbounded >= 0.5 &&
                (stats["boundary_asymptotic_jacobian_corrected_unbounded_points"] =
                    Int(stats["boundary_asymptotic_jacobian_corrected_unbounded_points"]) + 1)
        end
    end
    return stats
end

function _scan_floor_sensitivity_audit!(stats::Dict{String,Any}, paths::Vector{String})
    phi_values = Set{Float64}()
    for csv_path in paths
        stats["floor_sensitivity_csv_count"] = Int(stats["floor_sensitivity_csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        phi_idx = findfirst(==("phi_min"), header)
        span_idx = findfirst(==("pressure_span"), header)
        required_steps_idx = findfirst(==("estimated_required_steps"), header)
        required_sweeps_idx = findfirst(==("estimated_required_sweeps"), header)
        shortfall_idx = findfirst(==("production_budget_shortfall"), header)
        for row in rows
            stats["floor_sensitivity_points"] = Int(stats["floor_sensitivity_points"]) + 1
            phi_min = _parse_audit_float(row, phi_idx)
            isfinite(phi_min) && push!(phi_values, phi_min)
            _audit_update_max!(stats, "max_floor_sensitivity_phi_min", phi_min)
            _audit_update_max!(stats, "floor_sensitivity_pressure_span", _parse_audit_float(row, span_idx))
            _audit_update_max!(stats, "max_floor_sensitivity_estimated_required_steps", _parse_audit_float(row, required_steps_idx))
            _audit_update_max!(stats, "max_floor_sensitivity_estimated_required_sweeps", _parse_audit_float(row, required_sweeps_idx))
            _audit_update_max!(stats, "max_floor_sensitivity_budget_shortfall", _parse_audit_float(row, shortfall_idx))
        end
    end
    stats["floor_sensitivity_phi_min_count"] = length(phi_values)
    return stats
end

function _scan_boundary_ray_audit!(stats::Dict{String,Any}, paths::Vector{String})
    for csv_path in paths
        stats["boundary_ray_csv_count"] = Int(stats["boundary_ray_csv_count"]) + 1
        header, rows = _read_csv_strings(csv_path)
        cutoff_idx = findfirst(==("cutoff_dominated"), header)
        hit_idx = findfirst(==("lower_cutoff_hit_fraction"), header)
        pressure_dfm_idx = findfirst(==("pressure_minus_dfm"), header)
        pressure_cl_idx = findfirst(==("pressure_minus_cl"), header)
        corrected_slope_idx = findfirst(==("jacobian_corrected_log_slope"), header)
        epsilon_min_idx = findfirst(==("epsilon_min"), header)
        for row in rows
            stats["boundary_ray_points"] = Int(stats["boundary_ray_points"]) + 1
            cutoff = _parse_audit_float(row, cutoff_idx)
            isfinite(cutoff) && cutoff >= 0.5 &&
                (stats["boundary_ray_cutoff_dominated_points"] =
                    Int(stats["boundary_ray_cutoff_dominated_points"]) + 1)
            _audit_update_max!(stats, "max_boundary_ray_lower_cutoff_hit_fraction",
                _parse_audit_float(row, hit_idx))
            _audit_update_max!(stats, "max_boundary_ray_pressure_minus_dfm",
                abs(_parse_audit_float(row, pressure_dfm_idx)))
            _audit_update_max!(stats, "max_boundary_ray_pressure_minus_cl",
                abs(_parse_audit_float(row, pressure_cl_idx)))
            _audit_update_max!(stats, "max_boundary_ray_jacobian_corrected_log_slope",
                _parse_audit_float(row, corrected_slope_idx))
            _audit_update_min!(stats, "min_boundary_ray_epsilon_min",
                _parse_audit_float(row, epsilon_min_idx))
        end
    end
    return stats
end

function write_direct_target_preflight(
    outdir::AbstractString;
    boundary_asymptotic_dirs=AbstractString[],
    floor_sensitivity_dirs=AbstractString[],
    boundary_ray_dirs=AbstractString[],
    floor_pressure_span_tolerance=10.0,
    filename="direct_target_preflight.md",
    metadata_filename="direct_target_preflight.toml",
)
    mkpath(outdir)
    boundary_paths = String[]
    for dir in boundary_asymptotic_dirs
        append!(boundary_paths, _boundary_asymptotic_audit_paths(string(dir)))
    end
    floor_paths = String[]
    for dir in floor_sensitivity_dirs
        append!(floor_paths, _floor_sensitivity_audit_paths(string(dir)))
    end
    boundary_ray_paths = String[]
    for dir in boundary_ray_dirs
        append!(boundary_ray_paths, _boundary_ray_audit_paths(string(dir)))
    end

    stats = _new_direct_audit_stats()
    _scan_boundary_asymptotic_audit!(stats, boundary_paths)
    _scan_floor_sensitivity_audit!(stats, floor_paths)
    _scan_boundary_ray_audit!(stats, boundary_ray_paths)

    unbounded_points = Int(stats["boundary_asymptotic_unbounded_points"])
    boundary_points = Int(stats["boundary_asymptotic_points"])
    floor_points = Int(stats["floor_sensitivity_points"])
    boundary_ray_points = Int(stats["boundary_ray_points"])
    boundary_ray_cutoff_points = Int(stats["boundary_ray_cutoff_dominated_points"])
    floor_span = Float64(stats["floor_sensitivity_pressure_span"])
    span_tolerance = max(0.0, Float64(floor_pressure_span_tolerance))
    floor_sensitive = floor_points > 0 && isfinite(floor_span) && floor_span > span_tolerance
    ray_cutoff_dominated = boundary_ray_cutoff_points > 0
    has_boundary_obstruction = unbounded_points > 0
    blocked = has_boundary_obstruction || floor_sensitive || ray_cutoff_dominated
    status = blocked ? "blocked_unconstrained_direct_production" :
             "no_preflight_block_detected"
    recommended_action = blocked ? "reformulate_or_constrain_nonlinear_target" :
                         "attempt_unconstrained_direct_sampling_with_full_diagnostics"
    reasons = String[]
    if has_boundary_obstruction
        push!(reasons, "boundary_asymptotic_unbounded_below")
    end
    if floor_sensitive
        push!(reasons, "lower_bound_floor_sensitive")
    end
    if ray_cutoff_dominated
        push!(reasons, "boundary_ray_cutoff_dominated")
    end
    if isempty(reasons)
        push!(reasons, "no_boundary_floor_or_ray_preflight_block_detected")
    end

    metadata = Dict{String,Any}(
        "decision" => Dict{String,Any}(
            "status" => status,
            "recommended_action" => recommended_action,
            "reasons" => reasons,
        ),
        "checks" => Dict{String,Any}(
            "boundary_asymptotic_csv_count" => Int(stats["boundary_asymptotic_csv_count"]),
            "boundary_asymptotic_points" => boundary_points,
            "boundary_asymptotic_unbounded_points" => unbounded_points,
            "boundary_asymptotic_jacobian_corrected_unbounded_points" =>
                Int(stats["boundary_asymptotic_jacobian_corrected_unbounded_points"]),
            "max_boundary_asymptotic_log_slope" => _toml_value(stats["max_boundary_asymptotic_log_slope"]),
            "max_boundary_asymptotic_jacobian_corrected_log_slope" =>
                _toml_value(stats["max_boundary_asymptotic_jacobian_corrected_log_slope"]),
            "floor_sensitivity_csv_count" => Int(stats["floor_sensitivity_csv_count"]),
            "floor_sensitivity_points" => floor_points,
            "floor_sensitivity_phi_min_count" => Int(stats["floor_sensitivity_phi_min_count"]),
            "floor_sensitivity_pressure_span" => _toml_value(floor_span),
            "floor_pressure_span_tolerance" => span_tolerance,
            "floor_sensitive" => floor_sensitive,
            "max_floor_sensitivity_estimated_required_steps" => _toml_value(stats["max_floor_sensitivity_estimated_required_steps"]),
            "max_floor_sensitivity_estimated_required_sweeps" => _toml_value(stats["max_floor_sensitivity_estimated_required_sweeps"]),
            "max_floor_sensitivity_budget_shortfall" => _toml_value(stats["max_floor_sensitivity_budget_shortfall"]),
            "boundary_ray_csv_count" => Int(stats["boundary_ray_csv_count"]),
            "boundary_ray_points" => boundary_ray_points,
            "boundary_ray_cutoff_dominated_points" => boundary_ray_cutoff_points,
            "max_boundary_ray_lower_cutoff_hit_fraction" =>
                _toml_value(stats["max_boundary_ray_lower_cutoff_hit_fraction"]),
            "max_boundary_ray_pressure_minus_dfm" =>
                _toml_value(stats["max_boundary_ray_pressure_minus_dfm"]),
            "max_boundary_ray_pressure_minus_cl" =>
                _toml_value(stats["max_boundary_ray_pressure_minus_cl"]),
            "max_boundary_ray_jacobian_corrected_log_slope" =>
                _toml_value(stats["max_boundary_ray_jacobian_corrected_log_slope"]),
            "boundary_ray_cutoff_dominated" => ray_cutoff_dominated,
        ),
        "inputs" => Dict{String,Any}(
            "boundary_asymptotic_dirs" => [string(dir) for dir in boundary_asymptotic_dirs],
            "floor_sensitivity_dirs" => [string(dir) for dir in floor_sensitivity_dirs],
            "boundary_ray_dirs" => [string(dir) for dir in boundary_ray_dirs],
            "boundary_asymptotic_csvs" => boundary_paths,
            "floor_sensitivity_csvs" => floor_paths,
            "boundary_ray_csvs" => boundary_ray_paths,
        ),
        "environment" => _metadata_environment(),
    )
    toml_path = joinpath(outdir, metadata_filename)
    open(toml_path, "w") do io
        TOML.print(io, metadata)
    end

    markdown_path = joinpath(outdir, filename)
    open(markdown_path, "w") do io
        println(io, "Direct nonlinear target preflight")
        println(io, "=================================")
        println(io)
        if blocked
            println(io, "Decision: do not spend longer unconstrained direct Arianna budgets.")
            println(io, "Recommended action: reformulate or constrain the nonlinear target before treating direct MC as manuscript evidence.")
        else
            println(io, "Decision: no boundary-asymptotic or floor-sensitivity preflight block was detected.")
            println(io, "Recommended action: an unconstrained direct Arianna run may be attempted, but it must still pass ESS, drift, R-hat, acceptance, pressure-error, production-budget, and nonlinear-stability gates.")
        end
        println(io)
        if boundary_points > 0
            println(io, @sprintf("Boundary asymptotic check: %.0f of %.0f row(s) are asymptotically unbounded below; maximum log-boundary slope is %.3g.", Float64(unbounded_points), Float64(boundary_points), Float64(stats["max_boundary_asymptotic_log_slope"])))
            if Int(stats["boundary_asymptotic_jacobian_corrected_unbounded_points"]) > 0
                println(io, @sprintf("Jacobian-corrected boundary check: %.0f row(s) remain unbounded below after subtracting the log-coordinate direct-measure Jacobian contribution; maximum corrected slope is %.3g.",
                    Float64(stats["boundary_asymptotic_jacobian_corrected_unbounded_points"]),
                    Float64(stats["max_boundary_asymptotic_jacobian_corrected_log_slope"])))
            end
        else
            println(io, "Boundary asymptotic check: no scan rows were found.")
        end
        if floor_points > 0
            state = floor_sensitive ? "floor-sensitive" : "not floor-sensitive at the configured tolerance"
            println(io, @sprintf("Floor-sensitivity check: %.0f lower-bound row(s) across %.0f distinct phi_min value(s), pressure span %.3g, tolerance %.3g, status %s.", Float64(floor_points), Float64(stats["floor_sensitivity_phi_min_count"]), floor_span, span_tolerance, state))
            if isfinite(Float64(stats["max_floor_sensitivity_estimated_required_steps"]))
                println(io, @sprintf("Largest lower-bound diagnostic budget forecast: %.3g proposal steps (%.3g sweeps), shortfall %.3g.", Float64(stats["max_floor_sensitivity_estimated_required_steps"]), Float64(stats["max_floor_sensitivity_estimated_required_sweeps"]), Float64(stats["max_floor_sensitivity_budget_shortfall"])))
            end
        else
            println(io, "Floor-sensitivity check: no lower-bound diagnostic rows were found.")
        end
        if boundary_ray_points > 0
            println(io, @sprintf("Boundary-ray MC check: %.0f row(s), %.0f cutoff-dominated; maximum lower-cutoff hit fraction %.3g, maximum |pressure - DFM| %.3g, maximum |pressure - CL| %.3g.",
                Float64(boundary_ray_points),
                Float64(boundary_ray_cutoff_points),
                Float64(stats["max_boundary_ray_lower_cutoff_hit_fraction"]),
                Float64(stats["max_boundary_ray_pressure_minus_dfm"]),
                Float64(stats["max_boundary_ray_pressure_minus_cl"])))
        else
            println(io, "Boundary-ray MC check: no ray diagnostic rows were found.")
        end
        println(io)
        println(io, "Interpretation: this preflight report does not replace Monte Carlo diagnostics. It prevents spending longer unconstrained direct-density MC budgets when deterministic target geometry, lower-bound support sensitivity, or boundary-ray cutoff domination already shows that the sampled nonlinear measure is not a manuscript-ready unconstrained HE-URP target.")
        println(io, "Machine-readable preflight metadata: `$(basename(toml_path))`.")
    end
    return (markdown_path=markdown_path, toml_path=toml_path,
            status=status, recommended_action=recommended_action)
end

function write_validation_audit(
    outdir::AbstractString;
    gaussian_dirs=AbstractString[],
    direct_dirs=AbstractString[],
    stability_probe_dirs=AbstractString[],
    boundary_asymptotic_dirs=AbstractString[],
    floor_sensitivity_dirs=AbstractString[],
    boundary_ray_dirs=AbstractString[],
    filename="validation_audit.md",
    metadata_filename="validation_audit.toml",
)
    mkpath(outdir)
    gaussian_paths = String[]
    for dir in gaussian_dirs
        append!(gaussian_paths, _gaussian_audit_paths(string(dir)))
    end
    direct_paths = String[]
    for dir in direct_dirs
        append!(direct_paths, _direct_audit_paths(string(dir)))
    end
    stability_probe_paths = String[]
    for dir in stability_probe_dirs
        append!(stability_probe_paths, _stability_probe_audit_paths(string(dir)))
    end
    boundary_asymptotic_paths = String[]
    for dir in boundary_asymptotic_dirs
        append!(boundary_asymptotic_paths, _boundary_asymptotic_audit_paths(string(dir)))
    end
    floor_sensitivity_paths = String[]
    for dir in floor_sensitivity_dirs
        append!(floor_sensitivity_paths, _floor_sensitivity_audit_paths(string(dir)))
    end
    boundary_ray_paths = String[]
    for dir in boundary_ray_dirs
        append!(boundary_ray_paths, _boundary_ray_audit_paths(string(dir)))
    end

    gaussian = _scan_gaussian_audit!(_new_gaussian_audit_stats(), gaussian_paths)
    direct = _scan_direct_audit!(_new_direct_audit_stats(), direct_paths)
    _scan_stability_probe_audit!(direct, stability_probe_paths)
    _scan_boundary_asymptotic_audit!(direct, boundary_asymptotic_paths)
    _scan_floor_sensitivity_audit!(direct, floor_sensitivity_paths)
    _scan_boundary_ray_audit!(direct, boundary_ray_paths)
    gaussian_total = Int(gaussian["total_points"])
    gaussian_passed = Int(gaussian["passed_points"])
    direct_total = Int(direct["total_points"])
    direct_passed = Int(direct["passed_points"])
    direct_stability_passed = Int(direct["stability_passed_points"])
    direct_basin_points = Int(direct["finite_basin_points"])
    direct_barrier_points = Int(direct["boundary_barrier_points"])
    direct_stable_subspace_points = Int(direct["stable_subspace_points"])
    accepted_unconstrained_direct_points = Int(direct["accepted_unconstrained_points"])
    accepted_unconstrained_heurp_points = Int(direct["accepted_unconstrained_heurp_points"])
    accepted_unconstrained_hevk1_points = Int(direct["accepted_unconstrained_hevk1_points"])
    diagnostic_unconstrained_heurp_points = Int(direct["diagnostic_unconstrained_heurp_points"])
    diagnostic_unconstrained_hevk1_points = Int(direct["diagnostic_unconstrained_hevk1_points"])
    unconstrained_direct_points = Int(direct["unconstrained_points"])
    floor_sensitivity_points = Int(direct["floor_sensitivity_points"])
    boundary_ray_points = Int(direct["boundary_ray_points"])
    boundary_ray_cutoff_points = Int(direct["boundary_ray_cutoff_dominated_points"])
    probe_points = Int(direct["stability_probe_points"])
    probe_min_delta = Float64(direct["stability_probe_min_energy_delta"])
    probe_has_downhill = probe_points > 0 && isfinite(probe_min_delta) && probe_min_delta < 0.0
    boundary_asymptotic_unbounded = Int(direct["boundary_asymptotic_unbounded_points"])
    boundary_has_unbounded = boundary_asymptotic_unbounded > 0
    boundary_ray_cutoff_dominated = boundary_ray_cutoff_points > 0
    direct_min_delta = Float64(direct["min_nonlinear_stability_energy_delta"])
    direct_has_downhill = direct_total > 0 && isfinite(direct_min_delta) && direct_min_delta < 0.0 &&
                          direct_stability_passed < direct_total
    has_downhill_obstruction = probe_has_downhill || direct_has_downhill ||
                               boundary_has_unbounded || boundary_ray_cutoff_dominated
    gaussian_status = gaussian_total > 0 && gaussian_passed == gaussian_total ? "accepted" :
                      gaussian_total > 0 ? "diagnostic" : "missing"
    direct_status = accepted_unconstrained_direct_points > 0 ? "accepted" :
                    direct_total > 0 && direct_passed == direct_total &&
                    direct_stability_passed == direct_total && !has_downhill_obstruction &&
                    direct_basin_points == 0 && direct_barrier_points == 0 &&
                    direct_stable_subspace_points == 0 ? "accepted" :
                    direct_total > 0 || floor_sensitivity_points > 0 || boundary_ray_points > 0 ?
                    "diagnostic" : "missing"
    direct_recommendation = direct_status == "accepted" ? "none_direct_nonlinear_accepted" :
                            has_downhill_obstruction ? "reformulate_or_constrain_nonlinear_target" :
                            direct_basin_points > 0 && direct_stable_subspace_points > 0 ? "justify_or_reformulate_modified_direct_targets" :
                            direct_basin_points > 0 ? "justify_or_reformulate_basin_target" :
                            direct_barrier_points > 0 ? "justify_or_reformulate_boundary_barrier_target" :
                            direct_stable_subspace_points > 0 ? "justify_or_reformulate_stable_subspace_target" :
                            floor_sensitivity_points > 0 ? "justify_or_reformulate_lower_bound_target" :
                            direct_total > 0 ? "increase_sampling_budget_and_tuning" :
                            "generate_direct_diagnostics"
    unconstrained_direct_status = direct_status == "accepted" ? "accepted" :
                                  unconstrained_direct_points > 0 ? "diagnostic" : "missing"
    unconstrained_heurp_direct_status = accepted_unconstrained_heurp_points > 0 ? "accepted" :
                                        diagnostic_unconstrained_heurp_points > 0 || boundary_has_unbounded ?
                                        "diagnostic" : "missing"
    unconstrained_hevk1_direct_status = accepted_unconstrained_hevk1_points > 0 ? "accepted" :
                                        diagnostic_unconstrained_hevk1_points > 0 ? "diagnostic" : "missing"
    basin_direct_status = direct_basin_points > 0 ? "diagnostic" : "absent"
    boundary_barrier_direct_status = direct_barrier_points > 0 ? "diagnostic" : "absent"
    stable_subspace_direct_status = direct_stable_subspace_points > 0 ? "diagnostic" : "absent"
    heurp_direct_required = diagnostic_unconstrained_heurp_points > 0 ||
                            accepted_unconstrained_heurp_points > 0 ||
                            boundary_has_unbounded ||
                            boundary_ray_points > 0 ||
                            direct_barrier_points > 0
    required_direct_target_complete = heurp_direct_required ?
                                      accepted_unconstrained_heurp_points > 0 :
                                      accepted_unconstrained_direct_points > 0
    full_objective_complete = gaussian_status == "accepted" && required_direct_target_complete
    readiness_status = full_objective_complete ? "complete" :
                       gaussian_status == "accepted" ? "partial" : "insufficient"
    manuscript_evidence = full_objective_complete ? "finite_grid_gaussian_perturbation_mc_and_direct_nonlinear_arianna" :
                          gaussian_status == "accepted" ? "finite_grid_gaussian_perturbation_mc" : "none"
    direct_target_summary = accepted_unconstrained_heurp_points > 0 && accepted_unconstrained_hevk1_points > 0 ?
                            "representative direct nonlinear HE-URP and HE-VK1 pressure points" :
                            accepted_unconstrained_heurp_points > 0 ?
                            "a representative direct nonlinear HE-URP pressure point" :
                            accepted_unconstrained_hevk1_points > 0 ?
                            "a representative direct nonlinear HE-VK1 pressure point" :
                            "a representative direct nonlinear pressure point"
    remaining_gap = full_objective_complete ? "none" :
                    heurp_direct_required && accepted_unconstrained_heurp_points == 0 ?
                    "unconstrained HE-URP direct-density MC remains diagnostic" :
                    unconstrained_direct_status == "diagnostic" ?
                    "unconstrained nonlinear direct-density MC remains diagnostic" :
                    basin_direct_status == "diagnostic" ?
                    "basin-restricted direct MC is a modified target that needs physical justification" :
                    boundary_barrier_direct_status == "diagnostic" ?
                    "boundary-barrier direct MC is a modified target that needs physical justification" :
                    stable_subspace_direct_status == "diagnostic" ?
                    "stable-Fourier-subspace direct MC is a modified target that needs physical justification" :
                    "accepted finite-grid perturbative MC exists only if Gaussian status is accepted; direct-density validation is missing or diagnostic"
    verdict = Dict{String,Any}(
        "gaussian_status" => gaussian_status,
        "direct_status" => direct_status,
        "direct_recommendation" => direct_recommendation,
        "accepted_evidence" => full_objective_complete ? "finite-grid Gaussian perturbation MC and direct nonlinear Arianna MC" :
                               gaussian_status == "accepted" ? "finite-grid Gaussian perturbation MC" : "none",
        "manuscript_claim" => gaussian_status == "accepted" ?
                              (direct_status == "accepted" ?
                               "conventional Monte Carlo validates the finite-grid DFM pressure estimator and $direct_target_summary" :
                               "conventional Monte Carlo validates the finite-grid DFM pressure estimator; direct nonlinear Arianna remains separately audited") :
                              "no manuscript-ready Monte Carlo pressure validation has passed all configured gates",
    )
    metadata = Dict{String,Any}(
        "verdict" => verdict,
        "gaussian" => gaussian,
        "direct" => direct,
        "readiness" => Dict{String,Any}(
            "overall_status" => readiness_status,
            "perturbative_mc" => gaussian_status,
            "unconstrained_direct_mc" => unconstrained_direct_status,
            "unconstrained_heurp_direct_mc" => unconstrained_heurp_direct_status,
            "unconstrained_hevk1_direct_mc" => unconstrained_hevk1_direct_status,
            "basin_restricted_direct_mc" => basin_direct_status,
            "boundary_barrier_direct_mc" => boundary_barrier_direct_status,
            "stable_subspace_direct_mc" => stable_subspace_direct_status,
            "heurp_direct_required" => heurp_direct_required,
            "required_direct_target_complete" => required_direct_target_complete,
            "manuscript_evidence" => manuscript_evidence,
            "full_objective_complete" => full_objective_complete,
            "remaining_gap" => remaining_gap,
        ),
        "inputs" => Dict{String,Any}(
            "gaussian_dirs" => [string(dir) for dir in gaussian_dirs],
            "direct_dirs" => [string(dir) for dir in direct_dirs],
            "stability_probe_dirs" => [string(dir) for dir in stability_probe_dirs],
            "boundary_asymptotic_dirs" => [string(dir) for dir in boundary_asymptotic_dirs],
            "floor_sensitivity_dirs" => [string(dir) for dir in floor_sensitivity_dirs],
            "boundary_ray_dirs" => [string(dir) for dir in boundary_ray_dirs],
            "gaussian_csvs" => gaussian_paths,
            "direct_csvs" => direct_paths,
            "stability_probe_csvs" => stability_probe_paths,
            "boundary_asymptotic_csvs" => boundary_asymptotic_paths,
            "floor_sensitivity_csvs" => floor_sensitivity_paths,
            "boundary_ray_csvs" => boundary_ray_paths,
        ),
        "environment" => _metadata_environment(),
    )
    toml_path = joinpath(outdir, metadata_filename)
    open(toml_path, "w") do io
        TOML.print(io, metadata)
    end

    markdown_path = joinpath(outdir, filename)
    open(markdown_path, "w") do io
        println(io, "Monte Carlo Validation Audit")
        println(io, "============================")
        println(io)
        if gaussian_status == "accepted"
            println(io, "Accepted evidence: finite-grid Gaussian perturbation MC.")
            println(io, @sprintf("Gaussian diagnostics: %d of %d MC points passed the combined pressure-error, reference-agreement, and sample-budget gates across %d CSV file(s).", gaussian_passed, gaussian_total, Int(gaussian["csv_count"])))
            sampler_summary = _audit_count_summary(gaussian["sampler_counts"])
            println(io, "Gaussian samplers: $sampler_summary.")
            if isfinite(Float64(gaussian["max_reference_error"]))
                println(io, @sprintf("The largest MC-vs-finite-grid-DFM reference error was %.3g with largest reference z-score %.3g and largest MC error %.3g.", Float64(gaussian["max_reference_error"]), Float64(gaussian["max_reference_zscore"]), Float64(gaussian["max_mc_error"])))
            end
            if isfinite(Float64(gaussian["max_total_independent_samples"]))
                println(io, @sprintf("The largest Gaussian point used %.0f total independent perturbative samples; the largest estimated per-chain requirement was %.0f.", Float64(gaussian["max_total_independent_samples"]), Float64(gaussian["max_required_samples_per_chain"])))
            end
            if Int(gaussian["finite_cl_points"]) > 0 && isfinite(Float64(gaussian["max_cl_model_residual"]))
                println(io, @sprintf("CL-context diagnostics: %.0f of %.0f finite-CL rows passed after subtracting the finite-grid DFM-vs-CL model offset; the largest residual was %.3g.", Float64(gaussian["cl_context_passed_points"]), Float64(gaussian["finite_cl_points"]), Float64(gaussian["max_cl_model_residual"])))
            end
        elseif gaussian_status == "diagnostic"
            println(io, @sprintf("Gaussian perturbation MC status: diagnostic (%d of %d points passed).", gaussian_passed, gaussian_total))
        else
            println(io, "Gaussian perturbation MC status: missing.")
        end
        println(io)
        if direct_status == "accepted"
            println(io, "Direct nonlinear Arianna status: accepted.")
            println(io, @sprintf("Direct diagnostics: %.0f accepted unconstrained direct state point(s); %.0f of %.0f audited direct state point(s) passed all direct gates, and nonlinear stability passed for %.0f of %.0f state point(s).", Float64(direct["accepted_unconstrained_points"]), Float64(direct_passed), Float64(direct_total), Float64(direct_stability_passed), Float64(direct_total)))
            println(io, @sprintf("Accepted direct targets: HE-URP=%.0f, HE-VK1=%.0f.", Float64(accepted_unconstrained_heurp_points), Float64(accepted_unconstrained_hevk1_points)))
            println(io, "Target-specific direct status: HE-URP $(unconstrained_heurp_direct_status), HE-VK1 $(unconstrained_hevk1_direct_status).")
            if Int(direct["diagnostic_unconstrained_points"]) > 0
                println(io, @sprintf("Historical unconstrained direct diagnostics still include %.0f failed or incomplete state point(s); these remain useful failure evidence but no longer define the current direct status.", Float64(direct["diagnostic_unconstrained_points"])))
            end
            if Int(direct["modified_target_points"]) > 0
                println(io, @sprintf("The audit also contains %.0f modified-target direct state point(s), including basin-restricted, boundary-barrier, or stable-Fourier-subspace diagnostics where present.", Float64(direct["modified_target_points"])))
            end
            if Int(direct["boundary_barrier_points"]) > 0
                println(io, @sprintf("boundary-barrier direct outputs remain diagnostic: %.0f state point(s) used logarithmic boundary-barrier strength up to %.3g, and %.0f passed their local MC gates. These rows sample a regularized nonlinear target and are not evidence for the unconstrained HE-URP measure without an explicit manuscript definition and physical justification.", Float64(direct["boundary_barrier_points"]), Float64(direct["max_boundary_barrier_strength"]), Float64(direct["boundary_barrier_passed_points"])))
            end
            if isfinite(Float64(direct["max_effective_sample_size"]))
                println(io, @sprintf("The largest accepted/diagnostic direct production evidence reached %.3g effective samples over %.3g sweeps.", Float64(direct["max_effective_sample_size"]), Float64(direct["max_production_sweeps"])))
            end
            if Int(direct["boundary_asymptotic_points"]) > 0
                println(io, @sprintf("Boundary asymptotic scan: %.0f row(s) across %.0f CSV file(s), with %.0f row(s) flagged unbounded below and maximum log-boundary slope %.3g.", Float64(direct["boundary_asymptotic_points"]), Float64(direct["boundary_asymptotic_csv_count"]), Float64(direct["boundary_asymptotic_unbounded_points"]), Float64(direct["max_boundary_asymptotic_log_slope"])))
                if Int(direct["boundary_asymptotic_jacobian_corrected_unbounded_points"]) > 0
                    println(io, @sprintf("Jacobian-corrected boundary scan: %.0f row(s) remain unbounded below after subtracting the direct-measure log-coordinate Jacobian contribution; maximum corrected slope %.3g.", Float64(direct["boundary_asymptotic_jacobian_corrected_unbounded_points"]), Float64(direct["max_boundary_asymptotic_jacobian_corrected_log_slope"])))
                end
            end
            if Int(direct["boundary_ray_points"]) > 0
                println(io, @sprintf("Boundary-ray direct MC: %.0f row(s), %.0f cutoff-dominated; maximum lower-cutoff hit fraction %.3g and maximum |pressure - DFM| %.3g. These rows are direct nonlinear slice diagnostics, not unconstrained HE-URP production evidence.", Float64(direct["boundary_ray_points"]), Float64(direct["boundary_ray_cutoff_dominated_points"]), Float64(direct["max_boundary_ray_lower_cutoff_hit_fraction"]), Float64(direct["max_boundary_ray_pressure_minus_dfm"])))
            end
        elseif direct_status == "diagnostic"
            println(io, "Direct nonlinear Arianna status: diagnostic.")
            println(io, "Target-specific direct status: HE-URP $(unconstrained_heurp_direct_status), HE-VK1 $(unconstrained_hevk1_direct_status).")
            println(io, @sprintf("Direct diagnostics: %d of %d state points passed all direct gates; nonlinear stability passed for %d of %d state points.", direct_passed, direct_total, direct_stability_passed, direct_total))
            if isfinite(Float64(direct["min_nonlinear_stability_energy_delta"]))
                println(io, @sprintf("The lowest scanned nonlinear stability energy change was %.3g with minimum phi %.3g.", Float64(direct["min_nonlinear_stability_energy_delta"]), Float64(direct["min_nonlinear_stability_phi"])))
            end
            if isfinite(Float64(direct["max_phi_min"]))
                println(io, @sprintf("The largest explicit density lower bound in audited direct outputs was phi_min = %.3g.", Float64(direct["max_phi_min"])))
            end
            if Int(direct["phi_min_missing_csv_count"]) > 0
                println(io, @sprintf("%.0f audited direct CSV file(s) are missing explicit phi_min support metadata; treat their direct-target support as unknown or stale.", Float64(direct["phi_min_missing_csv_count"])))
            end
            if Int(direct["stability_probe_points"]) > 0
                println(io, @sprintf("Standalone stability probe: %.0f ray points across %.0f CSV file(s), with lowest energy change %.3g and minimum phi %.3g.", Float64(direct["stability_probe_points"]), Float64(direct["stability_probe_csv_count"]), Float64(direct["stability_probe_min_energy_delta"]), Float64(direct["stability_probe_min_phi"])))
            end
            if Int(direct["boundary_asymptotic_points"]) > 0
                println(io, @sprintf("Boundary asymptotic scan: %.0f row(s) across %.0f CSV file(s), with %.0f row(s) flagged unbounded below and maximum log-boundary slope %.3g.", Float64(direct["boundary_asymptotic_points"]), Float64(direct["boundary_asymptotic_csv_count"]), Float64(direct["boundary_asymptotic_unbounded_points"]), Float64(direct["max_boundary_asymptotic_log_slope"])))
                if Int(direct["boundary_asymptotic_jacobian_corrected_unbounded_points"]) > 0
                    println(io, @sprintf("Jacobian-corrected boundary scan: %.0f row(s) remain unbounded below after subtracting the direct-measure log-coordinate Jacobian contribution; maximum corrected slope %.3g.", Float64(direct["boundary_asymptotic_jacobian_corrected_unbounded_points"]), Float64(direct["max_boundary_asymptotic_jacobian_corrected_log_slope"])))
                end
            end
            if Int(direct["floor_sensitivity_points"]) > 0
                println(io, @sprintf("Direct floor-sensitivity MC: %.0f lower-bound-regularized row(s) across %.0f CSV file(s), %.0f distinct phi_min value(s), pressure span %.3g, maximum estimated required budget %.3g proposal steps (%.3g sweeps), and maximum budget shortfall %.3g. These rows are not unconstrained HE-URP evidence because phi_min changes the sampled support.", Float64(direct["floor_sensitivity_points"]), Float64(direct["floor_sensitivity_csv_count"]), Float64(direct["floor_sensitivity_phi_min_count"]), Float64(direct["floor_sensitivity_pressure_span"]), Float64(direct["max_floor_sensitivity_estimated_required_steps"]), Float64(direct["max_floor_sensitivity_estimated_required_sweeps"]), Float64(direct["max_floor_sensitivity_budget_shortfall"])))
            end
            if Int(direct["boundary_ray_points"]) > 0
                println(io, @sprintf("Boundary-ray direct MC: %.0f row(s), %.0f cutoff-dominated; maximum lower-cutoff hit fraction %.3g, maximum |pressure - DFM| %.3g, and maximum |pressure - CL| %.3g. These rows sample the nonlinear HE-URP energy on an unstable boundary slice and are not unconstrained production evidence.", Float64(direct["boundary_ray_points"]), Float64(direct["boundary_ray_cutoff_dominated_points"]), Float64(direct["max_boundary_ray_lower_cutoff_hit_fraction"]), Float64(direct["max_boundary_ray_pressure_minus_dfm"]), Float64(direct["max_boundary_ray_pressure_minus_cl"])))
            end
            if Int(direct["finite_basin_points"]) > 0
                println(io, @sprintf("basin-restricted direct outputs remain diagnostic: %.0f state point(s) used a finite density-variance cap up to %.3g, and %.0f passed the basin constraint. These rows are not evidence for the unconstrained nonlinear HE-URP measure without an explicit physical basin justification.", Float64(direct["finite_basin_points"]), Float64(direct["max_basin_variance_max"]), Float64(direct["basin_passed_points"])))
            end
            if Int(direct["boundary_barrier_points"]) > 0
                println(io, @sprintf("boundary-barrier direct outputs remain diagnostic: %.0f state point(s) used logarithmic boundary-barrier strength up to %.3g, and %.0f passed their local MC gates. These rows sample a regularized nonlinear target and are not evidence for the unconstrained HE-URP measure without an explicit manuscript definition and physical justification.", Float64(direct["boundary_barrier_points"]), Float64(direct["max_boundary_barrier_strength"]), Float64(direct["boundary_barrier_passed_points"])))
            end
            if Int(direct["stable_subspace_points"]) > 0
                println(io, @sprintf("stable-Fourier-subspace direct outputs remain diagnostic: %.0f state point(s) excluded low Fourier modes below k^2 = %.3g; %.0f passed their local MC gates. These rows sample a constrained nonlinear target and are not evidence for the unconstrained HE-URP measure without an explicit manuscript definition and physical justification.", Float64(direct["stable_subspace_points"]), Float64(direct["max_fourier_min_k2"]), Float64(direct["stable_subspace_passed_points"])))
            end
            if isfinite(Float64(direct["max_production_sweeps"]))
                println(io, @sprintf("The largest direct production chain in the audited files was %.3g sweeps with maximum ESS %.3g.", Float64(direct["max_production_sweeps"]), Float64(direct["max_effective_sample_size"])))
            end
            if direct_recommendation == "justify_or_reformulate_modified_direct_targets"
                println(io, "Recommended direct-MC next step: justify the modified direct targets physically or reformulate the nonlinear target before using these direct outputs as manuscript evidence.")
            elseif direct_recommendation == "justify_or_reformulate_basin_target"
                println(io, "Recommended direct-MC next step: justify the basin-restricted target physically or reformulate the nonlinear target before using these direct outputs as manuscript evidence.")
            elseif direct_recommendation == "justify_or_reformulate_boundary_barrier_target"
                println(io, "Recommended direct-MC next step: justify the logarithmic boundary-barrier target physically or reformulate the nonlinear target before using these direct outputs as manuscript evidence.")
            elseif direct_recommendation == "justify_or_reformulate_stable_subspace_target"
                println(io, "Recommended direct-MC next step: justify the stable-Fourier-subspace target physically or reformulate the nonlinear target before using these direct outputs as manuscript evidence.")
            elseif direct_recommendation == "justify_or_reformulate_lower_bound_target"
                println(io, "Recommended direct-MC next step: justify the lower-bound-regularized target physically or reformulate the nonlinear target before using these direct outputs as manuscript evidence.")
            elseif direct_recommendation == "reformulate_or_constrain_nonlinear_target"
                println(io, "Recommended direct-MC next step: reformulate or constrain the nonlinear target before spending longer Arianna budgets.")
            elseif direct_recommendation == "increase_sampling_budget_and_tuning"
                println(io, "Recommended direct-MC next step: increase the sweep budget, chain count, and proposal tuning because no standalone downhill stability obstruction was detected.")
            end
            println(io, "do not use diagnostic direct-density outputs as manuscript validation; use them only to document sampler functionality, diagnostics, and the nonlinear-target stability issue.")
        else
            println(io, "Direct nonlinear Arianna status: missing.")
        end
        println(io)
        println(io, "Full objective readiness: $(readiness_status).")
        if readiness_status == "complete"
            println(io, "The audit has accepted perturbative MC evidence and accepted unconstrained direct-density MC evidence.")
        elseif gaussian_status == "accepted"
            println(io, "The audit has accepted perturbative MC evidence for the finite-grid DFM pressure curve, but the full objective remains incomplete because $(remaining_gap).")
        else
            println(io, "The audit has not yet accepted perturbative MC evidence; direct-density validation is also not sufficient for the full objective.")
        end
        println(io)
        if readiness_status == "complete"
            println(io, "Conclusion: the manuscript-ready conventional-MC evidence now includes both the finite-grid Gaussian perturbation estimator and $(direct_target_summary). Historical diagnostic direct rows remain documented as rejected sampler configurations.")
        else
            println(io, "Conclusion: the manuscript-ready conventional-MC evidence is the finite-grid Gaussian perturbation estimator when its gates pass. The direct nonlinear Arianna sampler remains a separate target and must not be conflated with the accepted perturbative DFM validation.")
        end
        println(io, "Machine-readable audit metadata: `$(basename(toml_path))`.")
    end
    return (markdown_path=markdown_path, toml_path=toml_path,
            gaussian_status=gaussian_status, direct_status=direct_status)
end

function write_manuscript_evidence_text(
    outdir::AbstractString;
    gaussian_dirs=AbstractString[],
    direct_dirs=AbstractString[],
    stability_probe_dirs=AbstractString[],
    boundary_asymptotic_dirs=AbstractString[],
    floor_sensitivity_dirs=AbstractString[],
    boundary_ray_dirs=AbstractString[],
)
    return write_validation_audit(outdir; gaussian_dirs=gaussian_dirs, direct_dirs=direct_dirs,
        stability_probe_dirs=stability_probe_dirs, boundary_asymptotic_dirs=boundary_asymptotic_dirs,
        floor_sensitivity_dirs=floor_sensitivity_dirs, boundary_ray_dirs=boundary_ray_dirs,
        filename="mc_validation.md",
        metadata_filename="mc_validation.toml")
end

function write_manuscript_text(result::SweepResult, outdir::AbstractString)
    mkpath(outdir)
    path = joinpath(outdir, "mc_validation.md")
    _, rows = _read_csv_numeric(result.pressure_csv)
    diag_header, diag_rows = _read_csv_numeric(result.diagnostics_csv)
    max_dfm_relative = maximum(abs(row[2] - row[4]) / max(abs(row[4]), 1.0) for row in rows)
    max_cl_relative = maximum(abs(row[2] - row[5]) / max(abs(row[5]), 1.0) for row in rows if length(row) >= 5 && isfinite(row[5]))
    ess_idx = findfirst(==("effective_sample_size"), diag_header)
    tau_idx = findfirst(==("integrated_autocorrelation_time"), diag_header)
    drift_idx = findfirst(==("trace_drift_zscore"), diag_header)
    burn_idx = findfirst(==("equilibration_steps"), diag_header)
    burn_fraction_idx = findfirst(==("burn_fraction"), diag_header)
    stride_idx = findfirst(==("sample_stride"), diag_header)
    stride_sweeps_idx = findfirst(==("sample_stride_sweeps"), diag_header)
    amplitude_idx = findfirst(==("proposal_amplitude"), diag_header)
    target_idx = findfirst(==("target_acceptance"), diag_header)
    tuning_idx = findfirst(==("tuning_rounds"), diag_header)
    tuning_steps_idx = findfirst(==("tuning_steps"), diag_header)
    tuning_acceptance_idx = findfirst(==("tuning_acceptance_rate"), diag_header)
    adaptive_warmup_rounds_idx = findfirst(==("adaptive_warmup_rounds"), diag_header)
    adaptive_warmup_steps_idx = findfirst(==("adaptive_warmup_steps"), diag_header)
    adaptive_warmup_acceptance_idx = findfirst(==("adaptive_warmup_acceptance_rate"), diag_header)
    adaptive_warmup_pair_acceptance_idx = findfirst(==("adaptive_warmup_pair_acceptance_rate"), diag_header)
    adaptive_warmup_collective_acceptance_idx = findfirst(==("adaptive_warmup_collective_acceptance_rate"), diag_header)
    adaptive_warmup_fourier_acceptance_idx = findfirst(==("adaptive_warmup_fourier_acceptance_rate"), diag_header)
    adaptive_warmup_global_acceptance_idx = findfirst(==("adaptive_warmup_global_acceptance_rate"), diag_header)
    adaptive_warmup_radial_acceptance_idx = findfirst(==("adaptive_warmup_radial_variance_acceptance_rate"), diag_header)
    collective_amplitude_idx = findfirst(==("collective_proposal_amplitude"), diag_header)
    collective_pair_count_idx = findfirst(==("collective_pair_count"), diag_header)
    collective_idx = findfirst(==("collective_move_weight"), diag_header)
    fourier_amplitude_idx = findfirst(==("fourier_mode_amplitude"), diag_header)
    fourier_max_mode_idx = findfirst(==("fourier_max_mode"), diag_header)
    fourier_idx = findfirst(==("fourier_move_weight"), diag_header)
    global_amplitude_idx = findfirst(==("global_field_amplitude"), diag_header)
    global_idx = findfirst(==("global_move_weight"), diag_header)
    radial_amplitude_idx = findfirst(==("radial_variance_amplitude"), diag_header)
    radial_idx = findfirst(==("radial_variance_move_weight"), diag_header)
    stable_idx = findfirst(==("stable_mode_proposals"), diag_header)
    fourier_min_idx = findfirst(==("fourier_min_k2"), diag_header)
    ess_target_idx = findfirst(==("ess_target"), diag_header)
    converged_idx = findfirst(==("converged"), diag_header)
    production_steps_idx = findfirst(==("production_steps"), diag_header)
    max_production_steps_idx = findfirst(==("max_production_steps"), diag_header)
    proposals_per_sweep_idx = findfirst(==("proposals_per_sweep"), diag_header)
    production_sweeps_idx = findfirst(==("production_sweeps"), diag_header)
    max_production_sweeps_idx = findfirst(==("max_production_sweeps"), diag_header)
    equilibration_sweeps_idx = findfirst(==("equilibration_sweeps"), diag_header)
    convergence_attempts_idx = findfirst(==("convergence_attempts"), diag_header)
    chain_count_idx = findfirst(==("chain_count"), diag_header)
    chains_converged_idx = findfirst(==("chains_converged"), diag_header)
    chain_rhat_idx = findfirst(==("chain_rhat"), diag_header)
    split_chain_rhat_idx = findfirst(==("split_chain_rhat"), diag_header)
    chain_between_idx = findfirst(==("chain_between_stderr"), diag_header)
    chain_within_idx = findfirst(==("chain_within_stderr"), diag_header)
    pair_acceptance_idx = findfirst(==("pair_acceptance_rate"), diag_header)
    collective_acceptance_idx = findfirst(==("collective_acceptance_rate"), diag_header)
    fourier_acceptance_idx = findfirst(==("fourier_acceptance_rate"), diag_header)
    global_acceptance_idx = findfirst(==("global_acceptance_rate"), diag_header)
    radial_acceptance_idx = findfirst(==("radial_variance_acceptance_rate"), diag_header)
    acceptance_min_idx = findfirst(==("acceptance_min"), diag_header)
    acceptance_max_idx = findfirst(==("acceptance_max"), diag_header)
    acceptance_pass_idx = findfirst(==("acceptance_pass"), diag_header)
    drift_threshold_idx = findfirst(==("drift_threshold"), diag_header)
    drift_pass_idx = findfirst(==("drift_pass"), diag_header)
    rhat_threshold_idx = findfirst(==("rhat_threshold"), diag_header)
    rhat_pass_idx = findfirst(==("rhat_pass"), diag_header)
    ess_pass_idx = findfirst(==("ess_pass"), diag_header)
    stability_pass_idx = findfirst(==("nonlinear_stability_pass"), diag_header)
    stability_delta_idx = findfirst(==("nonlinear_stability_min_energy_delta"), diag_header)
    stability_phi_idx = findfirst(==("nonlinear_stability_min_phi"), diag_header)
    stability_ax_idx = findfirst(==("nonlinear_stability_mode_ax"), diag_header)
    stability_ay_idx = findfirst(==("nonlinear_stability_mode_ay"), diag_header)
    stability_az_idx = findfirst(==("nonlinear_stability_mode_az"), diag_header)
    stability_points_idx = findfirst(==("nonlinear_stability_points"), diag_header)
    stability_margin_idx = findfirst(==("nonlinear_stability_boundary_margin"), diag_header)
    basin_cap_idx = findfirst(==("basin_variance_max"), diag_header)
    basin_pass_idx = findfirst(==("basin_constraint_pass"), diag_header)
    phi_min_idx = findfirst(==("phi_min"), diag_header)
    boundary_barrier_idx = findfirst(==("boundary_barrier_strength"), diag_header)
    min_trace_samples_idx = findfirst(==("min_trace_samples"), diag_header)
    trace_samples_pass_idx = findfirst(==("trace_samples_pass"), diag_header)
    pressure_tolerance_idx = findfirst(==("pressure_tolerance"), diag_header)
    pressure_error_pass_idx = findfirst(==("pressure_error_pass"), diag_header)
    required_ess_idx = findfirst(==("required_effective_sample_size"), diag_header)
    required_trace_idx = findfirst(==("required_trace_samples"), diag_header)
    required_steps_idx = findfirst(==("estimated_required_steps"), diag_header)
    required_sweeps_idx = findfirst(==("estimated_required_sweeps"), diag_header)
    budget_shortfall_idx = findfirst(==("production_budget_shortfall"), diag_header)
    budget_pass_idx = findfirst(==("sampling_budget_pass"), diag_header)
    decorrelation_stride_idx = findfirst(==("decorrelation_stride_samples"), diag_header)
