    mean_adaptive_warmup_fourier_acceptance = isempty(adaptive_warmup_fourier_acceptances) ? NaN : mean(adaptive_warmup_fourier_acceptances)
    mean_adaptive_warmup_global_acceptance = isempty(adaptive_warmup_global_acceptances) ? NaN : mean(adaptive_warmup_global_acceptances)
    mean_adaptive_warmup_radial_acceptance = isempty(adaptive_warmup_radial_acceptances) ? NaN : mean(adaptive_warmup_radial_acceptances)
    acceptance_min = isempty(acceptance_mins) ? NaN : minimum(acceptance_mins)
    acceptance_max = isempty(acceptance_maxs) ? NaN : maximum(acceptance_maxs)
    drift_threshold = isempty(drift_thresholds) ? NaN : maximum(drift_thresholds)
    rhat_threshold = isempty(rhat_thresholds) ? NaN : maximum(rhat_thresholds)
    acceptance_pass_count = count(x -> x >= 0.5, acceptance_passes)
    drift_pass_count = count(x -> x >= 0.5, drift_passes)
    rhat_pass_count = count(x -> x >= 0.5, rhat_passes)
    ess_pass_count = count(x -> x >= 0.5, ess_passes)
    stability_pass_count = count(x -> x >= 0.5, stability_passes)
    min_stability_delta = isempty(stability_deltas) ? NaN : minimum(stability_deltas)
    min_stability_phi = isempty(stability_phis) ? NaN : minimum(stability_phis)
    max_stability_points = isempty(stability_points) ? NaN : maximum(stability_points)
    max_stability_margin = isempty(stability_margins) ? NaN : maximum(stability_margins)
    worst_stability_mode = isempty(stability_axes) || isempty(stability_deltas) ? (NaN, NaN, NaN) :
                           stability_axes[argmin(stability_deltas)]
    max_basin_cap = isempty(basin_caps) ? NaN : maximum(basin_caps)
    max_phi_min = isempty(phi_mins) ? NaN : maximum(phi_mins)
    max_boundary_barrier_strength = isempty(boundary_barrier_strengths) ? NaN :
                                    maximum(boundary_barrier_strengths)
    basin_pass_count = count(x -> x >= 0.5, basin_passes)
    trace_samples_pass_count = count(x -> x >= 0.5, trace_samples_passes)
    pressure_error_pass_count = count(x -> x >= 0.5, pressure_error_passes)
    max_required_ess = isempty(required_esses) ? NaN : maximum(required_esses)
    max_required_trace = isempty(required_traces) ? NaN : maximum(required_traces)
    max_required_step = isempty(required_steps) ? NaN : maximum(required_steps)
    max_required_sweep = isempty(required_sweeps) ? NaN : maximum(required_sweeps)
    max_budget_shortfall = isempty(budget_shortfalls) ? NaN : maximum(budget_shortfalls)
    budget_pass_count = count(x -> x >= 0.5, budget_passes)
    max_decorrelation_stride = isempty(decorrelation_strides) ? NaN : maximum(decorrelation_strides)
    max_decorrelation_steps = isempty(decorrelation_step_strides) ? NaN : maximum(decorrelation_step_strides)
    min_decorrelated_count = isempty(decorrelated_counts) ? NaN : minimum(decorrelated_counts)
    min_equilibration_windows = isempty(equilibration_windows) ? NaN : minimum(equilibration_windows)
    min_production_windows = isempty(production_windows) ? NaN : minimum(production_windows)
    decorrelation_pass_count = count(x -> x >= 0.5, decorrelation_passes)
    min_equilibration_tail_count = isempty(equilibration_tail_counts) ? NaN : minimum(equilibration_tail_counts)
    max_equilibration_head_mean = isempty(equilibration_head_means) ? NaN : maximum(equilibration_head_means)
    max_equilibration_tail_mean = isempty(equilibration_tail_means) ? NaN : maximum(equilibration_tail_means)
    max_equilibration_zscore = isempty(equilibration_zscores) ? NaN : maximum(equilibration_zscores)
    equilibration_sensitivity_threshold = isempty(equilibration_thresholds) ? NaN : maximum(equilibration_thresholds)
    equilibration_pass_count = count(x -> x >= 0.5, equilibration_passes)
    max_observable_zscore = isempty(observable_zscores) ? NaN : maximum(observable_zscores)
    observable_pass_count = count(x -> x >= 0.5, observable_passes)
    min_trace_sample_count = isempty(min_trace_sample_values) ? NaN : maximum(min_trace_sample_values)
    pressure_tolerance = isempty(pressure_tolerances) ? NaN : maximum(pressure_tolerances)
    diagnostic_pass_count = count(x -> x >= 0.5, diagnostic_passes)
    diagnostic_gate_count = length(diagnostic_passes)
    if decorrelation_pass_idx === nothing
        decorrelation_pass_count = diagnostic_gate_count
    end
    if equilibration_pass_idx === nothing
        equilibration_pass_count = diagnostic_gate_count
    end
    if observable_pass_idx === nothing
        observable_pass_count = diagnostic_gate_count
    end
    all_diagnostics_passed = diagnostic_gate_count > 0 && diagnostic_pass_count == diagnostic_gate_count
    max_low_mode_structure = isempty(structure_values) ? NaN : maximum(structure_values)
    min_low_mode_structure = isempty(structure_values) ? NaN : minimum(structure_values)
    stable_subspace_target = any(x -> x >= 0.5, stable_subspace_values)
    max_stable_fourier_min_k2 = isempty(fourier_min_values) ? NaN : maximum(fourier_min_values)
    sampled_alpha = isempty(alpha_values) ? result.config.alpha : maximum(alpha_values)
    default_phi_min = 1.0e-8
    support_metadata_missing = phi_min_idx === nothing || isempty(phi_mins)
    lower_bound_regularized = isfinite(max_phi_min) && max_phi_min > default_phi_min * (1.0 + 1.0e-6)
    boundary_barrier_regularized = isfinite(max_boundary_barrier_strength) &&
                                   max_boundary_barrier_strength > 0.0
    open(path, "w") do io
        println(io, "Monte Carlo validation of the real-valued $(target_model_label) Hamiltonian")
        println(io, "========================================================")
        println(io)
        println(io, "A direct-density Arianna/Metropolis Monte Carlo workflow was run for the 3D $(target_model_label) effective Hamiltonian ($(target_equation)).")
        println(io, "The generated pressure comparison table is `$(basename(result.pressure_csv))`; sampling diagnostics are `$(basename(result.diagnostics_csv))`.")
        if target_model_label == "HE-VK1"
            println(io, @sprintf("The sampled HE-VK1 Hamiltonian used the local VK1 gradient form; alpha = %.3g is retained for the Analysis/DFM reference comparison.", sampled_alpha))
        else
            println(io, @sprintf("The sampled HE-URP Hamiltonian used Gaussian regularization alpha = %.3g.", sampled_alpha))
        end
        println(io, "The manuscript does not require this MC calculation to reproduce complex-Langevin data exactly: CL samples the full complex field theory used to calibrate the DFM, whereas MC samples the approximate real-valued effective Hamiltonian.")
        println(io, "The validation target is therefore that conventional real-valued sampling is possible and gives osmotic pressures on the same physical scale as the DFM perturbation analysis and representative CL data.")
        println(io)
        if isfinite(min_ess) && isfinite(max_tau)
            if isfinite(stride_sweeps) && isfinite(max_burn_fraction)
                println(io, @sprintf("Sampling diagnostics used burn fraction %.3g, %.0f equilibration steps, post-burn stride %.0f (%.3g sweeps), maximum integrated autocorrelation time %.3g, maximum quarter-trace drift z-score %.3g, and minimum effective sample size %.3g.", max_burn_fraction, max_burn, stride, stride_sweeps, max_tau, max_drift, min_ess))
            else
                println(io, @sprintf("Sampling diagnostics used %.0f equilibration steps, post-burn stride %.0f, maximum integrated autocorrelation time %.3g, maximum quarter-trace drift z-score %.3g, and minimum effective sample size %.3g.", max_burn, stride, max_tau, max_drift, min_ess))
            end
        end
        if isfinite(proposals_per_sweep) && isfinite(max_production_sweep)
            println(io, @sprintf("One sweep was counted as %.0f local proposal attempts; the largest equilibration window was %.3g sweeps and the largest production chain was %.3g sweeps.", proposals_per_sweep, max_equilibration_sweep, max_production_sweep))
        end
        if isfinite(ess_target) && isfinite(max_production_step) && isfinite(max_production_budget)
            if isfinite(max_production_sweep_budget)
                println(io, @sprintf("The convergence gate used ESS target %.3g, minimum trace length %.0f, and pressure-error tolerance %.3g; %.0f of %.0f state points reached all active targets within the production budget, using at most %.0f of %.0f allowed production steps (%.3g of %.3g sweeps) over %.0f attempt(s).", ess_target, min_trace_sample_count, pressure_tolerance, converged_count, chain_count, max_production_step, max_production_budget, max_production_sweep, max_production_sweep_budget, max_convergence_attempts))
            else
                println(io, @sprintf("The convergence gate used ESS target %.3g, minimum trace length %.0f, and pressure-error tolerance %.3g; %.0f of %.0f state points reached all active targets within the production budget, using at most %.0f of %.0f allowed production steps over %.0f attempt(s).", ess_target, min_trace_sample_count, pressure_tolerance, converged_count, chain_count, max_production_step, max_production_budget, max_convergence_attempts))
            end
        end
        if isfinite(max_required_step)
            println(io, @sprintf("The estimated required production budget from the observed autocorrelation and pressure variance was at most %.0f effective samples, %.0f stored trace samples, %.0f proposal steps (%.3g sweeps), giving a maximum shortfall factor %.3g.", max_required_ess, max_required_trace, max_required_step, max_required_sweep, max_budget_shortfall))
        end
        if isfinite(max_decorrelation_stride)
            println(io, @sprintf("The autocorrelation audit used a conservative decorrelation stride of up to %.0f stored pressure samples (%.0f proposal steps), leaving at least %.0f approximately independent thinned samples; the shortest equilibration and production windows were %.3g and %.3g autocorrelation lengths, respectively.", max_decorrelation_stride, max_decorrelation_steps, min_decorrelated_count, min_equilibration_windows, min_production_windows))
        end
        if isfinite(max_equilibration_zscore)
            println(io, @sprintf("The burn-in sensitivity audit compared the first and second halves of the stored post-burn pressure trace; the largest sensitivity z-score was %.3g against threshold %.3g, with at least %.0f samples in the tail half and head/tail mean range %.6g to %.6g.", max_equilibration_zscore, equilibration_sensitivity_threshold, min_equilibration_tail_count, max_equilibration_head_mean, max_equilibration_tail_mean))
        end
        if isfinite(max_observable_zscore)
            println(io, @sprintf("The state-observable stationarity audit separately checked energy, density variance, and low-mode structure traces; the largest non-pressure observable drift z-score was %.3g against threshold %.3g, with %.0f of %.0f state points passing.", max_observable_zscore, equilibration_sensitivity_threshold, observable_pass_count, diagnostic_gate_count))
        end
        if isfinite(max_phi_min)
            println(io, @sprintf("The direct density-field target used an explicit density lower bound phi_min = %.3g for positivity and boundary regularization.", max_phi_min))
            if lower_bound_regularized
                println(io, @sprintf("Because this is larger than the numerical default phi_min = %.3g, the run samples a lower-bound-regularized target with truncated density-field support.", default_phi_min))
            end
        elseif support_metadata_missing
            println(io, "The direct density-field target did not record explicit phi_min support metadata, so its sampled support is not auditable.")
        end
        if !isempty(stability_passes)
            println(io, @sprintf("The nonlinear stability gate scanned %.0f cosine-ray points toward the positivity boundary with boundary margin %.3g; %.0f of %.0f state points passed. The lowest scanned energy change was %.3g at mode (%.0f,%.0f,%.0f), with minimum phi %.3g.", max_stability_points, max_stability_margin, stability_pass_count, length(stability_passes), min_stability_delta, worst_stability_mode[1], worst_stability_mode[2], worst_stability_mode[3], min_stability_phi))
        end
        if isfinite(max_basin_cap)
            println(io, @sprintf("The direct target used a hard-wall Gaussian-basin restriction density_variance <= %.3g; %.0f of %.0f sampled state points satisfied the basin constraint.", max_basin_cap, basin_pass_count, length(basin_passes)))
        end
        if boundary_barrier_regularized
            println(io, @sprintf("The direct target included logarithmic boundary-barrier regularization H_barrier = -lambda * sum_i log(phi_i), with maximum lambda = %.3g. This suppresses the positivity-boundary singularity but defines a regularized direct target rather than the unconstrained HE-URP measure.", max_boundary_barrier_strength))
        end
        if isfinite(max_chain_count) && max_chain_count > 1
            if !isnan(max_chain_rhat)
                if !isnan(max_split_chain_rhat)
                    println(io, @sprintf("The independent chains check used up to %.0f chains per state point; at least %.0f chains per point met the chain-level convergence gates, with maximum R-hat %.3g, maximum split R-hat %.3g, maximum between-chain standard error %.3g, and maximum within-chain standard error %.3g.", max_chain_count, min_chains_converged, max_chain_rhat, max_split_chain_rhat, max_chain_between_stderr, max_chain_within_stderr))
                else
                    println(io, @sprintf("The independent chains check used up to %.0f chains per state point; at least %.0f chains per point met the chain-level convergence gates, with maximum R-hat %.3g, maximum between-chain standard error %.3g, and maximum within-chain standard error %.3g.", max_chain_count, min_chains_converged, max_chain_rhat, max_chain_between_stderr, max_chain_within_stderr))
                end
            else
                println(io, @sprintf("The independent chains check used up to %.0f chains per state point; at least %.0f chains per point met the chain-level convergence gates, while R-hat was unavailable for the stored trace lengths.", max_chain_count, min_chains_converged))
            end
        end
        if diagnostic_gate_count > 0 && isfinite(acceptance_min) && isfinite(acceptance_max) && isfinite(rhat_threshold)
            if budget_pass_idx === nothing
                println(io, @sprintf("The diagnostic gate used acceptance window [%.3g, %.3g], drift z-score threshold %.3g, whole/split R-hat threshold %.3g, the ESS/trace/error convergence targets above, and the pressure-error gate; %.0f of %.0f state points passed all gates (ESS %.0f/%.0f, trace %.0f/%.0f, pressure error %.0f/%.0f, drift %.0f/%.0f, R-hat %.0f/%.0f, acceptance %.0f/%.0f).", acceptance_min, acceptance_max, drift_threshold, rhat_threshold, diagnostic_pass_count, diagnostic_gate_count, ess_pass_count, diagnostic_gate_count, trace_samples_pass_count, diagnostic_gate_count, pressure_error_pass_count, diagnostic_gate_count, drift_pass_count, diagnostic_gate_count, rhat_pass_count, diagnostic_gate_count, acceptance_pass_count, diagnostic_gate_count))
            else
                if !isempty(stability_passes) && isfinite(max_basin_cap)
                    println(io, @sprintf("The diagnostic gate used acceptance window [%.3g, %.3g], drift z-score threshold %.3g, whole/split R-hat threshold %.3g, nonlinear stability, basin constraint, the ESS/trace/error convergence targets above, and the pressure-error plus production-budget/decorrelation/burn-in-sensitivity/state-observable-stationarity gates; %.0f of %.0f state points passed all gates (ESS %.0f/%.0f, trace %.0f/%.0f, pressure error %.0f/%.0f, production budget %.0f/%.0f, decorrelation %.0f/%.0f, burn-in %.0f/%.0f, state observables %.0f/%.0f, nonlinear stability %.0f/%.0f, basin %.0f/%.0f, drift %.0f/%.0f, R-hat %.0f/%.0f, acceptance %.0f/%.0f).", acceptance_min, acceptance_max, drift_threshold, rhat_threshold, diagnostic_pass_count, diagnostic_gate_count, ess_pass_count, diagnostic_gate_count, trace_samples_pass_count, diagnostic_gate_count, pressure_error_pass_count, diagnostic_gate_count, budget_pass_count, diagnostic_gate_count, decorrelation_pass_count, diagnostic_gate_count, equilibration_pass_count, diagnostic_gate_count, observable_pass_count, diagnostic_gate_count, stability_pass_count, length(stability_passes), basin_pass_count, length(basin_passes), drift_pass_count, diagnostic_gate_count, rhat_pass_count, diagnostic_gate_count, acceptance_pass_count, diagnostic_gate_count))
                elseif !isempty(stability_passes)
                    println(io, @sprintf("The diagnostic gate used acceptance window [%.3g, %.3g], drift z-score threshold %.3g, whole/split R-hat threshold %.3g, nonlinear stability, the ESS/trace/error convergence targets above, and the pressure-error plus production-budget/decorrelation/burn-in-sensitivity/state-observable-stationarity gates; %.0f of %.0f state points passed all gates (ESS %.0f/%.0f, trace %.0f/%.0f, pressure error %.0f/%.0f, production budget %.0f/%.0f, decorrelation %.0f/%.0f, burn-in %.0f/%.0f, state observables %.0f/%.0f, nonlinear stability %.0f/%.0f, drift %.0f/%.0f, R-hat %.0f/%.0f, acceptance %.0f/%.0f).", acceptance_min, acceptance_max, drift_threshold, rhat_threshold, diagnostic_pass_count, diagnostic_gate_count, ess_pass_count, diagnostic_gate_count, trace_samples_pass_count, diagnostic_gate_count, pressure_error_pass_count, diagnostic_gate_count, budget_pass_count, diagnostic_gate_count, decorrelation_pass_count, diagnostic_gate_count, equilibration_pass_count, diagnostic_gate_count, observable_pass_count, diagnostic_gate_count, stability_pass_count, length(stability_passes), drift_pass_count, diagnostic_gate_count, rhat_pass_count, diagnostic_gate_count, acceptance_pass_count, diagnostic_gate_count))
                else
                    println(io, @sprintf("The diagnostic gate used acceptance window [%.3g, %.3g], drift z-score threshold %.3g, whole/split R-hat threshold %.3g, the ESS/trace/error convergence targets above, and the pressure-error plus production-budget/decorrelation/burn-in-sensitivity/state-observable-stationarity gates; %.0f of %.0f state points passed all gates (ESS %.0f/%.0f, trace %.0f/%.0f, pressure error %.0f/%.0f, production budget %.0f/%.0f, decorrelation %.0f/%.0f, burn-in %.0f/%.0f, state observables %.0f/%.0f, drift %.0f/%.0f, R-hat %.0f/%.0f, acceptance %.0f/%.0f).", acceptance_min, acceptance_max, drift_threshold, rhat_threshold, diagnostic_pass_count, diagnostic_gate_count, ess_pass_count, diagnostic_gate_count, trace_samples_pass_count, diagnostic_gate_count, pressure_error_pass_count, diagnostic_gate_count, budget_pass_count, diagnostic_gate_count, decorrelation_pass_count, diagnostic_gate_count, equilibration_pass_count, diagnostic_gate_count, observable_pass_count, diagnostic_gate_count, drift_pass_count, diagnostic_gate_count, rhat_pass_count, diagnostic_gate_count, acceptance_pass_count, diagnostic_gate_count))
                end
            end
        end
        if isfinite(min_amplitude) && isfinite(target_acceptance)
            if isfinite(max_tuning_rounds) && max_tuning_rounds > 0.0 && isfinite(max_tuning_acceptance)
                if isfinite(max_tuning_steps)
                    println(io, @sprintf("Arianna pilot tuning used %.0f rounds of up to %.0f Metropolis proposals toward target acceptance %.3g; the production proposal amplitude range was %.3g to %.3g with maximum pilot acceptance %.3g.", max_tuning_rounds, max_tuning_steps, target_acceptance, min_amplitude, max_amplitude, max_tuning_acceptance))
                else
                    println(io, @sprintf("Arianna pilot tuning used %.0f rounds toward target acceptance %.3g; the production proposal amplitude range was %.3g to %.3g with maximum pilot acceptance %.3g.", max_tuning_rounds, target_acceptance, min_amplitude, max_amplitude, max_tuning_acceptance))
                end
            elseif isfinite(max_adaptive_warmup_steps) && max_adaptive_warmup_steps > 0.0
                println(io, @sprintf("No separate Arianna pilot tuning rounds were run; production used proposal amplitudes in the range %.3g to %.3g, with adaptive warmup controlling the recorded chains toward target acceptance %.3g.", min_amplitude, max_amplitude, target_acceptance))
            else
                println(io, @sprintf("No separate Arianna pilot tuning rounds were run; production used proposal amplitudes in the range %.3g to %.3g toward target acceptance %.3g.", min_amplitude, max_amplitude, target_acceptance))
            end
        end
        if isfinite(max_adaptive_warmup_steps) && max_adaptive_warmup_steps > 0.0
            if isfinite(mean_adaptive_warmup_global_acceptance) && isfinite(mean_adaptive_warmup_radial_acceptance)
                println(io, @sprintf("Before stored production sampling, adaptive warmup discarded up to %.0f Metropolis proposals per chain over %.0f round(s); final warmup acceptance rates were aggregate %.3g, pair %.3g, collective %.3g, Fourier %.3g, global %.3g, and radial-variance %.3g, after which proposal amplitudes were frozen for the recorded Markov chains.", max_adaptive_warmup_steps, max_adaptive_warmup_rounds, mean_adaptive_warmup_acceptance, mean_adaptive_warmup_pair_acceptance, mean_adaptive_warmup_collective_acceptance, mean_adaptive_warmup_fourier_acceptance, mean_adaptive_warmup_global_acceptance, mean_adaptive_warmup_radial_acceptance))
            elseif isfinite(mean_adaptive_warmup_global_acceptance)
                println(io, @sprintf("Before stored production sampling, adaptive warmup discarded up to %.0f Metropolis proposals per chain over %.0f round(s); final warmup acceptance rates were aggregate %.3g, pair %.3g, collective %.3g, Fourier %.3g, and global %.3g, after which proposal amplitudes were frozen for the recorded Markov chains.", max_adaptive_warmup_steps, max_adaptive_warmup_rounds, mean_adaptive_warmup_acceptance, mean_adaptive_warmup_pair_acceptance, mean_adaptive_warmup_collective_acceptance, mean_adaptive_warmup_fourier_acceptance, mean_adaptive_warmup_global_acceptance))
            elseif isfinite(mean_adaptive_warmup_radial_acceptance)
                println(io, @sprintf("Before stored production sampling, adaptive warmup discarded up to %.0f Metropolis proposals per chain over %.0f round(s); final warmup acceptance rates were aggregate %.3g, pair %.3g, collective %.3g, Fourier %.3g, and radial-variance %.3g, after which proposal amplitudes were frozen for the recorded Markov chains.", max_adaptive_warmup_steps, max_adaptive_warmup_rounds, mean_adaptive_warmup_acceptance, mean_adaptive_warmup_pair_acceptance, mean_adaptive_warmup_collective_acceptance, mean_adaptive_warmup_fourier_acceptance, mean_adaptive_warmup_radial_acceptance))
            else
                println(io, @sprintf("Before stored production sampling, adaptive warmup discarded up to %.0f Metropolis proposals per chain over %.0f round(s); final warmup acceptance rates were aggregate %.3g, pair %.3g, collective %.3g, and Fourier %.3g, after which proposal amplitudes were frozen for the recorded Markov chains.", max_adaptive_warmup_steps, max_adaptive_warmup_rounds, mean_adaptive_warmup_acceptance, mean_adaptive_warmup_pair_acceptance, mean_adaptive_warmup_collective_acceptance, mean_adaptive_warmup_fourier_acceptance))
            end
        end
        if isfinite(collective_amplitude) && isfinite(collective_weight) && collective_weight > 0.0
            println(io, @sprintf("Production sampling mixed local pair-density moves with sparse multi-pair collective moves using %.0f pairs, amplitude %.3g, and pool weight %.3g.", collective_pair_count, collective_amplitude, collective_weight))
        end
        if isfinite(fourier_amplitude) && isfinite(fourier_weight) && fourier_weight > 0.0
            println(io, @sprintf("The production move pool also included low Fourier density-mode proposals up to index %.0f, amplitude %.3g, and pool weight %.3g to accelerate long-wavelength decorrelation.", fourier_max_mode, fourier_amplitude, fourier_weight))
            if stable_subspace_target && isfinite(max_stable_fourier_min_k2)
                println(io, @sprintf("For this direct nonlinear diagnostic, the Fourier proposal support was restricted to the stable subspace k^2 >= %.3g; low unstable modes were intentionally excluded from the Markov chain state exploration.", max_stable_fourier_min_k2))
            end
        end
        if isfinite(global_amplitude) && isfinite(global_weight) && global_weight > 0.0
            println(io, @sprintf("The production move pool also included zero-mean global Gaussian density-field moves with field standard deviation %.3g and pool weight %.3g to attack variance-sector decorrelation without changing the density normalization.", global_amplitude, global_weight))
        end
        if isfinite(radial_amplitude) && isfinite(radial_weight) && radial_weight > 0.0
            println(io, @sprintf("The production move pool also included radial density-variance moves with field-standard-deviation amplitude %.3g and pool weight %.3g to move directly along the current centered density direction while preserving the density normalization.", radial_amplitude, radial_weight))
        end
        if isfinite(mean_pair_acceptance) || isfinite(mean_collective_acceptance) || isfinite(mean_fourier_acceptance) || isfinite(mean_global_acceptance) || isfinite(mean_radial_acceptance)
            if isfinite(mean_radial_acceptance)
                println(io, @sprintf("Per-family production acceptance rates were pair %.3g, collective %.3g, Fourier %.3g, global %.3g, and radial-variance %.3g; these rates are measured from production calls, not just the pilot tuning probes.", mean_pair_acceptance, mean_collective_acceptance, mean_fourier_acceptance, mean_global_acceptance, mean_radial_acceptance))
            else
                println(io, @sprintf("Per-family production acceptance rates were pair %.3g, collective %.3g, Fourier %.3g, and global %.3g; these rates are measured from production calls, not just the pilot tuning probes.", mean_pair_acceptance, mean_collective_acceptance, mean_fourier_acceptance, mean_global_acceptance))
            end
        end
        if isfinite(max_low_mode_structure)
            println(io, @sprintf("The density-field diagnostic recorded the first-shell low-mode structure factor |delta_phi_k|^2/M^2 averaged over the lowest nonzero Fourier shell; values ranged from %.3g to %.3g across the sampled state points.", min_low_mode_structure, max_low_mode_structure))
        end
        println(io, @sprintf("For the current run, the maximum relative MC deviation is %.3g from the %s and %.3g from the nearest CL values.", max_dfm_relative, reference_curve_label, max_cl_relative))
        if lower_bound_regularized
            println(io, "Current status: lower-bound-regularized target diagnostic. The Arianna MC path sampled a truncated density-field support, so this result should not be reported as unconstrained direct $(target_model_label) MC without an explicit manuscript definition and justification of the lower-bound-regularized measure.")
        elseif support_metadata_missing
            println(io, "Current status: support-metadata diagnostic. The Arianna MC path is functional, but the direct-target support was not recorded and therefore cannot be used as manuscript-supporting direct MC evidence.")
        elseif isfinite(max_basin_cap)
            println(io, "Current status: constrained-target diagnostic. The Arianna MC path sampled the stated hard-wall basin target, but this artificial restriction is not the unconstrained nonlinear $(target_model_label) measure and should not be reported as manuscript-supporting direct MC without an explicit physical justification for the basin.")
        elseif boundary_barrier_regularized
            println(io, "Current status: regularized direct-target diagnostic. The Arianna MC path sampled a logarithmic boundary-barrier regularization of the nonlinear $(target_model_label) measure, so this result should not be reported as unconstrained direct $(target_model_label) MC without an explicit manuscript definition and physical justification of the regularized measure.")
        elseif stable_subspace_target
            if isfinite(max_stable_fourier_min_k2)
                println(io, @sprintf("Stable-subspace cutoff: k^2 >= %.3g.", max_stable_fourier_min_k2))
            end
            println(io, "Current status: stable-Fourier-subspace target diagnostic. The Arianna MC path sampled a direct nonlinear target whose proposal support excludes low Fourier modes below the stability cutoff, so this result should not be reported as unconstrained direct $(target_model_label) MC without an explicit manuscript definition and physical justification of the stable-subspace measure.")
        elseif all_diagnostics_passed && max_dfm_relative < 0.03 && max_cl_relative < 0.03
            println(io, "Current status: manuscript-supporting validation. The calculation demonstrates that conventional Monte Carlo can sample the real-valued $(target_model_label) Hamiltonian and produces pressures close to both the perturbation prediction and CL benchmark, while retaining the expected model-level discrepancy from CL.")
        else
            println(io, "Current status: diagnostic validation. The Arianna MC path is functional, but diagnostic gates did not all pass or pressure deviations are larger than the configured manuscript-support threshold.")
        end
    end
    return path
end

